import sys


def can_make(seq, K):
    n = len(seq)
    INF = 10**9

    # dp[l][r] = minimum number of PRINT statements needed
    # to output seq[l:r].
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        dp[i][i + 1] = 1

    for length in range(2, n + 1):
        for l in range(n - length + 1):
            r = l + length
            best = INF

            # Concatenate two programs.
            for mid in range(l + 1, r):
                val = dp[l][mid] + dp[mid][r]
                if val < best:
                    best = val

            # Repeat a smaller program.
            for p in range(1, length):
                if length % p != 0:
                    continue

                if dp[l][l + p] >= best:
                    continue

                ok = True
                for i in range(l + p, r):
                    if seq[i] != seq[i - p]:
                        ok = False
                        break

                if ok:
                    best = dp[l][l + p]

            dp[l][r] = best

    return dp[0][n] <= K


