import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, q = data[0], data[1]
    a = data[2:2 + n]
    queries = data[2 + n:2 + n + q]

    max_x = max(queries)
    L = max_x.bit_length()

    INF = 10 ** 30
    c = [0] * (L + 1)

    c[0] = a[0]
    for k in range(1, L + 1):
        deal_cost = a[k] if k < n else INF
        c[k] = min(deal_cost, 2 * c[k - 1])

    answers = []

    for x in queries:
        exact_cost = 0
        for i in range(L + 1):
            if (x >> i) & 1:
                exact_cost += c[i]

        ans = exact_cost
        higher_cost = 0

        for k in range(L, -1, -1):
            if (x >> k) & 1:
                higher_cost += c[k]
            else:
                ans = min(ans, higher_cost + c[k])

        answers.append(str(ans))

    sys.stdout.write("\n".join(answers))


