import sys


def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    t = int(next(it))
    answers = []

    for _ in range(t):
        n = int(next(it))
        k = int(next(it))

        # Reflect the values when K is negative, reducing to K > 0.
        sign = 1
        if k < 0:
            k = -k
            sign = -1

        groups = {}
        for _ in range(n):
            x = sign * int(next(it))
            residue = x % k
            if residue in groups:
                groups[residue].append(x)
            else:
                groups[residue] = [x]

        operations = 0

        # Values in different residue classes can never collide.
        for values in groups.values():
            if len(values) < 2:
                continue

            values.sort()
            previous = values[0]

            for i in range(1, len(values)):
                x = values[i]
                if x <= previous:
                    previous += k
                    operations += (previous - x) // k
                else:
                    previous = x

        answers.append(str(operations))

    sys.stdout.write("\n".join(answers))


