        K = int(next(it))

        d = abs(K)
        groups = {}

        if K > 0:
            for _ in range(N):
                v = int(next(it))
                q, r = divmod(v, d)

                if r in groups:
                    groups[r].append(q)
                else:
                    groups[r] = [q]
        else:
            for _ in range(N):
                v = int(next(it))
                c = -v
                q, r = divmod(c, d)

                if r in groups:
                    groups[r].append(q)
                else:
                    groups[r] = [q]

        ans = 0

        for arr in groups.values():
            if len(arr) <= 1:
                continue

            arr.sort()
            last = arr[0]

            for i in range(1, len(arr)):
                x = arr[i]
                if x > last:
                    last = x
                else:
                    last += 1
                    ans += last - x

        answers.append(str(ans))

