import sys


def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    flat = data[1:1 + n * n]

    if n == 1:
        # The only value in the original 1x1 addition table is 2.
        print(2)
        return

    max_val = 2 * n
    freq = [0] * (max_val + 2)
    for v in flat:
        freq[v] += 1

    # The two values occurring exactly once are at the two opposite corners
    # corresponding to sums 2 and 2N.
    singles = []
    for idx, v in enumerate(flat):
        if freq[v] == 1:
            singles.append((idx // n, idx % n))
            if len(singles) == 2:
                break

    best = None

    for r0, c0 in singles:
        # Treat this singleton cell as the (1, 1) corner of the sum table.
        R = [0] * n
        seen = [False] * (n + 1)
        valid = True

        for i in range(n):
            rv = freq[flat[i * n + c0]]
            if rv < 1 or rv > n or seen[rv]:
                valid = False
                break
            seen[rv] = True
            R[i] = rv

        if not valid:
            continue

        C = [0] * n
        seen = [False] * (n + 1)
        row0 = r0 * n

        for j in range(n):
            cv = freq[flat[row0 + j]]
            if cv < 1 or cv > n or seen[cv]:
                valid = False
                break
            seen[cv] = True
            C[j] = cv

        if not valid:
            continue

        # Verify that cells with equal R[i] + C[j] have equal final values.
        mapping = [-1] * (2 * n + 1)
        ok = True

        for i in range(n):
            base = i * n
            ri = R[i]
            for j in range(n):
                s = ri + C[j]
                t = flat[base + j]
                if mapping[s] == -1:
                    mapping[s] = t
                elif mapping[s] != t:
                    ok = False
                    break
            if not ok:
                break

        if not ok:
            continue

        cand = [0] * (n * n)
        idx = 0
        for i in range(n):
            ri = R[i]
            for c in C:
                cand[idx] = ri + c
                idx += 1

        if best is None or cand < best:
            best = cand

    out_lines = []
    for i in range(n):
        out_lines.append(" ".join(map(str, best[i * n:(i + 1) * n])))

    sys.stdout.write("\n".join(out_lines))


