import sys


def min_operations(a, b, c, d):
    if c < a or d < b:
        return -1

    x, y = c, d
    operations = 0

    while True:
        if x == a and y == b:
            return operations

        if x == y:
            return -1

        if x > y:
            # Reverse: subtract y from x as many times as possible
            # without making x smaller than a.
            k = (x - a) // y
            if k == 0:
                return -1
            x -= k * y
            operations += k
        else:
            # Reverse: subtract x from y as many times as possible
            # without making y smaller than b.
            k = (y - b) // x
            if k == 0:
                return -1
            y -= k * x
            operations += k


