import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    n = next(it)
    A = next(it)
    B = next(it)

    counts = [0] * n
    ids = [0] * n
    for i in range(n):
        counts[i] = next(it)
        ids[i] = next(it)

    index = {d: i for i, d in enumerate(ids)}
    adj = [[] for _ in range(n)]
    self_pair = bytearray(n)

    sums = (A,) if A == B else (A, B)
    for i, d in enumerate(ids):
        for s in sums:
            other = s - d
            if other == d:
                self_pair[i] = 1
            elif other > d:
                j = index.get(other)
                if j is not None:
                    adj[i].append(j)
                    adj[j].append(i)

    seen = bytearray(n)
    answer = 0

    for root in range(n):
        if seen[root]:
            continue

        # Collect this component. The communication graph consists of paths.
        seen[root] = 1
        stack = [root]
        component = []
        loop_vertex = -1

        while stack:
            v = stack.pop()
            component.append(v)
            if self_pair[v]:
                loop_vertex = v
            for w in adj[v]:
                if not seen[w]:
                    seen[w] = 1
                    stack.append(w)

        if len(component) == 1:
            if self_pair[root]:
                answer += counts[root] // 2
            continue

        endpoints = [v for v in component if len(adj[v]) == 1]

        # If a self-pairing ID exists, it is at one end. Greedily process
        # the path from the opposite end, then use cows left at that ID.
        if loop_vertex != -1:
            start = endpoints[0] if endpoints[0] != loop_vertex else endpoints[1]
        else:
            start = endpoints[0]

        previous = -1
        v = start
        remaining = counts[v]

        while True:
            nxt = -1
            for w in adj[v]:
                if w != previous:
                    nxt = w
                    break
            if nxt == -1:
                break

            pairs = min(remaining, counts[nxt])
            answer += pairs
            remaining = counts[nxt] - pairs
            previous, v = v, nxt

        if self_pair[v]:
            answer += remaining // 2

    sys.stdout.write(str(answer))


