    solve()

import sys
import math

INF = 10**30


def get_order(comp, adj):
    if len(comp) == 1:
        return comp, False

    is_cycle = True
    for v in comp:
        if len(adj[v]) != 2:
            is_cycle = False
            break

    if is_cycle:
        start = comp[0]
        order = []
        prev = -1
        cur = start
        while True:
            order.append(cur)
            nxts = [u for u in adj[cur] if u != prev]
            if not nxts:
                break
            nxt = nxts[0]
            if nxt == start:
                break
            prev, cur = cur, nxt
        return order, True

    start = comp[0]
    for v in comp:
        if len(adj[v]) <= 1:
            start = v
            break

    order = []
    prev = -1
    cur = start
    while True:
        order.append(cur)
        nxts = [u for u in adj[cur] if u != prev]
        if not nxts:
            break
        nxt = nxts[0]
        prev, cur = cur, nxt

    return order, False


def min_cover_path(weights):
    if not weights:
        return 0

    dp0 = 0
    dp1 = weights[0]

    for w in weights[1:]:
        ndp0 = dp1
        ndp1 = min(dp0, dp1) + w
        dp0, dp1 = ndp0, ndp1

    return min(dp0, dp1)


def min_cover_cycle(weights):
    n = len(weights)
    if n == 0:
        return 0
    if n == 1:
        return 0

    ans = INF

    for first in (0, 1):
        dp0 = 0 if first == 0 else INF
        dp1 = weights[0] if first == 1 else INF

        for w in weights[1:]:
            ndp0 = dp1
            ndp1 = min(dp0, dp1) + w
            dp0, dp1 = ndp0, ndp1

        if first == 0:
            val = dp1
        else:
            val = min(dp0, dp1)

        if val < ans:
            ans = val

    return ans


def min_cover_forced(order, is_cycle, weights, forced_pos):
    n = len(order)

    if not is_cycle:
        f = forced_pos.get(0)
        dp0 = 0 if (f is None or f == 0) else INF
        dp1 = weights[0] if (f is None or f == 1) else INF

        for i in range(1, n):
            w = weights[i]
            ndp0 = dp1
            ndp1 = min(dp0, dp1) + w

            f = forced_pos.get(i)
            if f == 0:
                ndp1 = INF
            elif f == 1:
                ndp0 = INF

            dp0, dp1 = ndp0, ndp1

        return min(dp0, dp1)

    ans = INF
    f0 = forced_pos.get(0)

    for first in (0, 1):
        if f0 is not None and first != f0:
            continue

        dp0 = 0 if first == 0 else INF
        dp1 = weights[0] if first == 1 else INF

        for i in range(1, n):
            w = weights[i]
            ndp0 = dp1
            ndp1 = min(dp0, dp1) + w

            f = forced_pos.get(i)
            if f == 0:
                ndp1 = INF
            elif f == 1:
                ndp0 = INF

            dp0, dp1 = ndp0, ndp1

        if first == 0:
            val = dp1
        else:
            val = min(dp0, dp1)

        if val < ans:
            ans = val

    return ans


def solve_loop1(c, statuses):
    A0 = INF
    A1 = INF

    for A, s in statuses:
        if s == 0:
            A0 = min(A0, A)
        else:
            A1 = min(A1, A)

    def eval_e(e):
        ext = INF
        if A0 < INF:
            ext = min(ext, A0)
        if A1 < INF:
            ext = min(ext, A1 + e)

        if ext >= INF:
            return -INF

        return ext + (c - e) // 2

    best = 0
    candidates = set()

    for e in (0, 1, c - 1, c):
        if 0 <= e <= c:
            candidates.add(e)

    if A0 < INF and A1 < INF:
        cross = A0 - A1
        for d in range(-10, 11):
            e = cross + d
            if 0 <= e <= c:
                candidates.add(e)

    for e in candidates:
        val = eval_e(e)
        if val > best:
            best = val

    return best


def solve_loop2(c1, c2, statuses):
    best = 0

    for p1 in (0, 1):
        for p2 in (0, 1):
            r1 = (c1 - p1) % 2
            r2 = (c2 - p2) % 2
            const = c1 + c2 - r1 - r2

            forms = []
            for A, s0, s1 in statuses:
                if A >= INF:
                    continue
                A2 = 2 * A + const
                a = 2 * s0 - 1
                b = 2 * s1 - 1
                forms.append((A2, a, b))

            if not forms:
                continue

            cand_points = [
                (0, 0),
                (0, c2),
                (c1, 0),
                (c1, c2),
            ]

            m = len(forms)

            # Intersections of equality lines with rectangle boundaries.
            for i in range(m):
                Ai, ai, bi = forms[i]
                for j in range(i + 1, m):
                    Aj, aj, bj = forms[j]

                    da = ai - aj
                    db = bi - bj
                    C = Aj - Ai

                    if da == 0 and db == 0:
                        continue

                    if db != 0:
                        y = C / db
                        if -1e-9 <= y <= c2 + 1e-9:
                            cand_points.append((0, y))

                        y2 = (C - da * c1) / db
                        if -1e-9 <= y2 <= c2 + 1e-9:
                            cand_points.append((c1, y2))

                    if da != 0:
                        x = C / da
                        if -1e-9 <= x <= c1 + 1e-9:
                            cand_points.append((x, 0))

                        x2 = (C - db * c2) / da
                        if -1e-9 <= x2 <= c1 + 1e-9:
                            cand_points.append((x2, c2))

            # Triple intersections.
            for i in range(m):
                Ai, ai, bi = forms[i]
                for j in range(i + 1, m):
                    Aj, aj, bj = forms[j]

                    da1 = ai - aj
                    db1 = bi - bj
                    C1 = Aj - Ai

                    for k in range(j + 1, m):
                        Ak, ak, bk = forms[k]

                        da2 = ai - ak
                        db2 = bi - bk
                        C2 = Ak - Ai

                        det = da1 * db2 - da2 * db1
                        if abs(det) < 1e-12:
                            continue

                        x = (C1 * db2 - C2 * db1) / det
                        y = (da1 * C2 - da2 * C1) / det

                        if (
                            -1e-9 <= x <= c1 + 1e-9
                            and -1e-9 <= y <= c2 + 1e-9
                        ):
                            cand_points.append((x, y))

            # Check integer points with the required parities near all
            # continuous candidates.
            for xr, yr in cand_points:
                bx = math.floor(xr)
                by = math.floor(yr)

                for dx in range(-6, 7):
                    x = bx + dx
                    if x < 0 or x > c1 or (x & 1) != p1:
                        continue

                    for dy in range(-6, 7):
                        y = by + dy
                        if y < 0 or y > c2 or (y & 1) != p2:
                            continue

                        ext = INF
                        for A, s0, s1 in statuses:
                            if A >= INF:
                                continue
                            val = A + s0 * x + s1 * y
                            if val < ext:
                                ext = val

                        if ext >= INF:
                            continue

                        total = ext + (c1 - x) // 2 + (c2 - y) // 2
                        if total > best:
                            best = total

    return best


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    A = int(next(it))
    B = int(next(it))

    ids = []
    counts = []
    index = {}

    for i in range(N):
        n = int(next(it))
        d = int(next(it))
        counts.append(n)
        ids.append(d)
        index[d] = i

    is_loop = [False] * N
    for i, d in enumerate(ids):
        if 2 * d == A or 2 * d == B:
            is_loop[i] = True

    adj = [[] for _ in range(N)]

    sums = (A,) if A == B else (A, B)

    for i, d in enumerate(ids):
        for S in sums:
            other = S - d
            if other == d:
                continue
            j = index.get(other)
            if j is not None and j > i:
                adj[i].append(j)
                adj[j].append(i)

    visited = [False] * N
    answer = 0

    for start in range(N):
        if visited[start]:
            continue

        comp = []
        stack = [start]
        visited[start] = True

        while stack:
            v = stack.pop()
            comp.append(v)
            for u in adj[v]:
                if not visited[u]:
                    visited[u] = True
                    stack.append(u)

        order, is_cycle = get_order(comp, adj)
        loops = [v for v in comp if is_loop[v]]

        if not loops:
            weights = [counts[v] for v in order]

            if is_cycle:
                answer += min_cover_cycle(weights)
            else:
                answer += min_cover_path(weights)

        else:
            order_pos = {v: i for i, v in enumerate(order)}
            weights_rest = [
                0 if is_loop[v] else counts[v]
                for v in order
            ]

            loops.sort(key=lambda v: order_pos[v])
            L = len(loops)
            statuses = []

            for mask in range(1 << L):
                forced_pos = {}
                s_list = []

                for k, v in enumerate(loops):
                    s = (mask >> k) & 1
                    s_list.append(s)
                    forced_pos[order_pos[v]] = s

                cost = min_cover_forced(
                    order, is_cycle, weights_rest, forced_pos
                )

                if cost < INF:
                    statuses.append((cost, s_list))

            if L == 1:
                c = counts[loops[0]]
                stat1 = [(A_cost, slist[0]) for A_cost, slist in statuses]
                answer += solve_loop1(c, stat1)

            else:
                c1 = counts[loops[0]]
                c2 = counts[loops[1]]
                stat2 = [
                    (A_cost, slist[0], slist[1])
                    for A_cost, slist in statuses
                ]
                answer += solve_loop2(c1, c2, stat2)

    print(answer)


