def cow_position(c, t):
    if c == 0:
        z = 0
    else:
        if t < 2 * c:
            return c
        z = 3 * c - 1

    while z < t:
        z += 1 + ((z + 1) // 2)
    return z - t


def cow_at_position(x, t):
    s = t
    i = x

    while True:
        if s == 0:
            return 0

        k = s // 2

        if i > k:
            return i

        if i == k:
            i = 0
            s -= 1
            continue

        # i < k: jump through consecutive backward moves
        steps = (s - 2 * i - 2) // 3 + 1
        s -= steps
        i += steps


