import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    a = data[1:n + 1]
    q = data[n + 1]

    # P = (a[0] + 1) * product(ceil(a[i] / a[i-1]), i >= 1).
    # Products larger than 10^18 can be saturated, since they always give 0.
    LIMIT = 10**18 + 1

    size = 1
    while size < n:
        size <<= 1

    seg = [1] * (2 * size)
    seg[size] = a[0] + 1
    for i in range(1, n):
        seg[size + i] = (a[i] + a[i - 1] - 1) // a[i - 1]

    for i in range(size - 1, 0, -1):
        product = seg[2 * i] * seg[2 * i + 1]
        seg[i] = product if product <= LIMIT else LIMIT

    def update(pos, value, seg=seg, size=size, limit=LIMIT):
        node = size + pos
        if seg[node] == value:
            return
        seg[node] = value
        node >>= 1
        while node:
            product = seg[2 * node] * seg[2 * node + 1]
            if product > limit:
                product = limit
            if seg[node] == product:
                break
            seg[node] = product
            node >>= 1

    answers = []
    ptr = n + 2

    for _ in range(q):
        pos = data[ptr] - 1
        v = data[ptr + 1]
        t = data[ptr + 2]
        ptr += 3

        if a[pos] != v:
            a[pos] = v

            if pos == 0:
                update(0, v + 1)
            else:
                update(pos, (v + a[pos - 1] - 1) // a[pos - 1])

            if pos + 1 < n:
                update(pos + 1, (a[pos + 1] + v - 1) // v)

        x = t - n + 1
        if x > 0:
            dumps = x // seg[1]
            if dumps:
                answers.append(str(dumps * a[-1]))
                continue
        answers.append("0")

    sys.stdout.write("\n".join(answers))

