#include <bits/stdc++.h>
using namespace std;

constexpr int MAX_W = 50;

struct Node {
    unsigned char nxt[MAX_W + 1];
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> w(N);
    long long totalWeight = 0;
    for (int &x : w) {
        cin >> x;
        totalWeight += x;
    }

    int size = 1;
    while (size < N) size <<= 1;

    vector<Node> seg(2 * size);

    auto setLeaf = [&](int p, int weight) {
        for (int d = 0; d <= MAX_W; ++d) {
            seg[p].nxt[d] = static_cast<unsigned char>(
                d >= weight ? d - weight : weight - d
            );
        }
    };

    auto pull = [&](int p) {
        const auto &top = seg[p << 1].nxt;
        const auto &bottom = seg[p << 1 | 1].nxt;
        auto &res = seg[p].nxt;

        for (int d = 0; d <= MAX_W; ++d) {
            res[d] = top[bottom[d]];
        }
    };

    for (int i = 0; i < size; ++i) {
        if (i < N) {
            setLeaf(size + i, w[i]);
        } else {
            for (int d = 0; d <= MAX_W; ++d) {
                seg[size + i].nxt[d] = static_cast<unsigned char>(d);
            }
        }
    }

    for (int p = size - 1; p >= 1; --p) {
        pull(p);
    }

    auto answer = [&]() -> long long {
        return (totalWeight - seg[1].nxt[0]) / 2;
    };

    cout << answer() << '\n';

    while (Q--) {
        int P, Z;
        cin >> P >> Z;

        totalWeight += Z - w[P];
        w[P] = Z;

        int p = size + P;
