constexpr int MAXW = 50;
constexpr int STATES = MAXW + 1;

struct Node {
    int add[STATES];
    unsigned char nxt[STATES];
};

inline void makeLeaf(Node &node, int w) {
    for (int d = 0; d < STATES; ++d) {
        node.add[d] = max(0, w - d);
        node.nxt[d] = static_cast<unsigned char>(abs(d - w));
    }
}

inline void makeIdentity(Node &node) {
    for (int d = 0; d < STATES; ++d) {
        node.add[d] = 0;
        node.nxt[d] = static_cast<unsigned char>(d);
    }
}

