#include <bits/stdc++.h>
using namespace std;

class SegmentTree {
    static constexpr int MAX_WEIGHT = 50;
    static constexpr int STATES = MAX_WEIGHT + 1;

    struct Node {
        uint8_t to[STATES];
        int gain[STATES];
    };

    int base;
    vector<Node> tree;

    static void setLeaf(Node& node, int weight) {
        for (int d = 0; d < STATES; ++d) {
            node.to[d] = static_cast<uint8_t>(abs(d - weight));
            node.gain[d] = min(d, weight);
        }
    }

    // The right segment is processed first, followed by the left segment.
    static void pull(Node& result, const Node& left, const Node& right) {
        for (int d = 0; d < STATES; ++d) {
            int middle = right.to[d];
            result.to[d] = left.to[middle];
            result.gain[d] = right.gain[d] + left.gain[middle];
        }
    }

public:
    explicit SegmentTree(const vector<int>& weights) {
        int n = static_cast<int>(weights.size());
        base = 1;
        while (base < n) base <<= 1;

        tree.resize(base << 1);

        for (int i = 0; i < base; ++i) {
            Node& leaf = tree[base + i];

            if (i < n) {
                setLeaf(leaf, weights[i]);
            } else {
                // Identity transformation for padded positions.
                for (int d = 0; d < STATES; ++d) {
                    leaf.to[d] = static_cast<uint8_t>(d);
                    leaf.gain[d] = 0;
                }
            }
        }

        for (int p = base - 1; p >= 1; --p) {
            pull(tree[p], tree[p << 1], tree[p << 1 | 1]);
        }
    }

    void update(int position, int weight) {
        int p = base + position;
        setLeaf(tree[p], weight);

        for (p >>= 1; p > 0; p >>= 1) {
            pull(tree[p], tree[p << 1], tree[p << 1 | 1]);
        }
    }

    int answer() const {
        return tree[1].gain[0];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> weights(N);
    for (int& weight : weights) {
        cin >> weight;
    }

    SegmentTree segmentTree(weights);

    cout << segmentTree.answer() << '\n';

    for (int i = 0; i < Q; ++i) {
        int position, newWeight;
        cin >> position >> newWeight;

        if (weights[position] != newWeight) {
            weights[position] = newWeight;
            segmentTree.update(position, newWeight);
        }

        cout << segmentTree.answer() << '\n';
    }

    return 0;
}

