class SegmentTree {
    static constexpr int K = 51;
    using Mapping = array<unsigned char, K>;

    int base;
    vector<Mapping> tree;
    array<Mapping, K> singleWeight;

    void pull(int node) {
        const Mapping &left = tree[node << 1];
        const Mapping &right = tree[node << 1 | 1];
        Mapping &result = tree[node];

        // The bottom (right) segment is processed first.
        for (int x = 0; x < K; ++x) {
            result[x] = left[right[x]];
        }
    }

public:
    explicit SegmentTree(const vector<int> &weights) {
        int n = static_cast<int>(weights.size());

        base = 1;
        while (base < n) base <<= 1;
        tree.resize(base << 1);

        for (int weight = 0; weight < K; ++weight) {
            for (int x = 0; x < K; ++x) {
                singleWeight[weight][x] =
                    static_cast<unsigned char>(abs(x - weight));
            }
        }

        for (int i = 0; i < base; ++i) {
            if (i < n) {
                tree[base + i] = singleWeight[weights[i]];
            } else {
                // Empty segments have the identity transformation.
                for (int x = 0; x < K; ++x) {
                    tree[base + i][x] = static_cast<unsigned char>(x);
                }
            }
        }

        for (int node = base - 1; node >= 1; --node) {
            pull(node);
        }
    }

    void update(int position, int weight) {
        int node = base + position;
        tree[node] = singleWeight[weight];

        while (node > 1) {
            node >>= 1;
            pull(node);
        }
    }

    int difference() const {
        return tree[1][0];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

