    cout << (totalWeight - segmentTree.difference()) / 2 << '\n';

    for (int i = 0; i < Q; ++i) {
        int position, newWeight;
        cin >> position >> newWeight;

        totalWeight += newWeight - weights[position];
        weights[position] = newWeight;
        segmentTree.update(position, newWeight);

        cout << (totalWeight - segmentTree.difference()) / 2 << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class SegmentTree {
    static constexpr int STATES = 51;

    struct Node {
        array<uint8_t, STATES> next{};
        array<int, STATES> gain{};
    };

    int n, base;
    vector<Node> tree;

    void setLeaf(int pos, int weight) {
        Node &leaf = tree[base + pos];
        for (int d = 0; d < STATES; ++d) {
            leaf.next[d] = static_cast<uint8_t>(abs(d - weight));
            leaf.gain[d] = min(d, weight);
        }
    }

    static void pull(Node &parent, const Node &left, const Node &right) {
        for (int d = 0; d < STATES; ++d) {
            int middle = left.next[d];
            parent.next[d] = right.next[middle];
            parent.gain[d] = left.gain[d] + right.gain[middle];
        }
    }

public:
    explicit SegmentTree(const vector<int> &weights)
        : n(static_cast<int>(weights.size())), base(1) {
        while (base < n) base <<= 1;
        tree.resize(base << 1);

        // Padding leaves represent the identity transformation.
        for (int i = base + n; i < 2 * base; ++i) {
            for (int d = 0; d < STATES; ++d) {
                tree[i].next[d] = static_cast<uint8_t>(d);
            }
        }

        // The game recurrence processes weights from bottom to top.
        for (int i = 0; i < n; ++i) {
            setLeaf(n - 1 - i, weights[i]);
        }

        for (int p = base - 1; p >= 1; --p) {
            pull(tree[p], tree[p << 1], tree[(p << 1) | 1]);
        }
    }

    void update(int pos, int weight) {
        setLeaf(pos, weight);
        for (int p = (base + pos) >> 1; p >= 1; p >>= 1) {
            pull(tree[p], tree[p << 1], tree[(p << 1) | 1]);
        }
    }

    int answer() const {
        return tree[1].gain[0];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> weights(N);
    for (int &w : weights) cin >> w;

    SegmentTree seg(weights);

    cout << seg.answer() << '\n';

    while (Q--) {
        int P, Z;
        cin >> P >> Z;

        // Original top-to-bottom index P corresponds to bottom-to-top
        // position N - 1 - P.
        seg.update(N - 1 - P, Z);
        cout << seg.answer() << '\n';
    }

    return 0;
}

