int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> a(N);
    int A = 0;
    for (int i = 0; i < N; ++i) {
        cin >> a[i];
        A = max(A, a[i]);
    }

    vector<int> freq(A + 2, 0);
    for (int x : a) freq[x]++;

    vector<int> ge(A + 3, 0);
    for (int x = A; x >= 1; --x) {
        ge[x] = ge[x + 1] + freq[x];
    }

    // B[T] = sum floor(a_i / T)
    vector<long long> B(A + 1, 0);
    for (int T = 1; T <= A; ++T) {
        long long sum = 0;
        for (int m = T; m <= A; m += T) {
            sum += ge[m];
        }
        B[T] = sum;
    }

    vector<pair<long long, long long>> intervals;

    for (int T = 1; T <= A; ++T) {
        long long L = (A + T - 1LL) / T;
        long long R = B[T];
        if (L <= R) {
            intervals.push_back({L, R});
        }
    }

    sort(intervals.begin(), intervals.end());

    vector<pair<long long, long long>> merged;
    for (auto [l, r] : intervals) {
        if (merged.empty() || l > merged.back().second + 1) {
            merged.push_back({l, r});
        } else {
            merged.back().second = max(merged.back().second, r);
        }
    }

    while (Q--) {
        long long K;
        cin >> K;

        int lo = 0, hi = (int)merged.size() - 1;
        int idx = -1;

        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (merged[mid].first <= K) {
                idx = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        bool ok = false;
        if (idx != -1 && K <= merged[idx].second) {
            ok = true;
        }

        cout << (ok ? "YES\n" : "NO\n");
    }

    return 0;
}

