struct Runs {
    int a, b, c;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string S;
    cin >> N >> S;

    if (S.front() != '+' || S.back() != '-') {
        cout << "NO\n";
        return 0;
    }

    vector<Runs> runs;
    vector<int> nxt(N, -1);

    int pos = 0;
    while (pos < N) {
        int a = pos;
        while (pos < N && S[pos] == '+') ++pos;
        int b = pos - 1;

        while (pos < N && S[pos] == '-') ++pos;
        int c = pos - 1;

        runs.push_back({a, b, c});

        for (int v = a; v < b; ++v) nxt[v] = v + 1;
        nxt[b] = c;

        for (int v = c; v > b + 1; --v) nxt[v] = v - 1;
        nxt[b + 1] = a;
    }

    for (int i = 1; i < (int)runs.size(); ++i) {
        const auto &p = runs[i - 1];
        const auto &q = runs[i];
        nxt[p.b] = q.a;
        nxt[q.b + 1] = p.c;
    }

    cout << "YES\n";
    int cur = 0;
    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << cur;
        cur = nxt[cur];
    }
    cout << '\n';

    return 0;
}

