    int N, D;
    cin >> N >> D;

    vector<long long> t(N);
    for (int i = 0; i < N; ++i) cin >> t[i];

    vector<int> state(N, 0);
    vector<int> start(N, 0);
    vector<long long> acc(N, 0);

    for (int p = 1; p < N; ++p) {
        state[p] = (t[p] < t[p - 1]) ? 1 : 0;
        start[p] = 0;
    }

    for (int day = 0; day < D; ++day) {
        char op;
        cin >> op;

        if (op == '?') {
            int r;
