            int p = r;
            long long ans = acc[p] + 1LL * state[p] * (day - start[p] + 1);
            cout << ans << '\n';
        } else {
            int r;
            long long x;
            cin >> r >> x;

            int affected[2];
            int cnt = 0;

            if (r >= 1) affected[cnt++] = r;
            if (r + 1 < N) affected[cnt++] = r + 1;

            for (int i = 0; i < cnt; ++i) {
                int p = affected[i];
                acc[p] += 1LL * state[p] * (day - start[p] + 1);
            }

            t[r] = x;

            for (int i = 0; i < cnt; ++i) {
                int p = affected[i];
                state[p] = (t[p] < t[p - 1]) ? 1 : 0;
                start[p] = day + 1;
            }
        }
    }

