int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, D;
    cin >> N >> D;

    vector<long long> t(N);
    for (int i = 0; i < N; ++i) cin >> t[i];

    vector<char> active(N, 0);
    vector<long long> sum(N, 0), last(N, -1);

    for (int i = 1; i < N; ++i) {
        active[i] = (t[i] < t[i - 1]);
    }

    auto updateEdge = [&](int e, int day) {
        if (e < 1 || e >= N) return;

        bool newActive = (t[e] < t[e - 1]);
        if (newActive != (bool)active[e]) {
            if (active[e]) {
                sum[e] += (long long)day - last[e];
            }
            last[e] = day;
            active[e] = newActive;
        }
    };

    for (int day = 0; day < D; ++day) {
        char type;
        cin >> type;

        if (type == '?') {
            int r;
            cin >> r;

            long long ans = sum[r];
            if (active[r]) {
                ans += (long long)day - last[r];
            }

            cout << ans << '\n';
        } else {
            int r;
            long long x;
            cin >> r >> x;

            t[r] = x;

            updateEdge(r, day);
            updateEdge(r + 1, day);
        }
    }

    return 0;
}

