    vector<unsigned char> active(N, 0);
    vector<long long> answer(N, 0);

    // nextDay[e] is the first day not yet included in answer[e].
    vector<int> nextDay(N, 0);

    for (int e = 1; e < N; ++e) {
        active[e] = (t[e] < t[e - 1]);
    }

    // Account for all unprocessed days using the currently stored result.
