#include <bits/stdc++.h>
using namespace std;

struct Change {
    int start;  // First day on which this value is used
    int value;
};

struct Query {
    int day;
    int id;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, D;
    cin >> N >> D;

    vector<int> initial(N);
    for (int &x : initial) {
        cin >> x;
    }

    vector<vector<Change>> changes(N);
    for (int r = 0; r < N; ++r) {
        changes[r].push_back({0, initial[r]});
    }

    vector<vector<Query>> queries(N);
    int queryCount = 0;

    for (int day = 0; day < D; ++day) {
        char type;
        cin >> type;

        if (type == '!') {
            int r, x;
            cin >> r >> x;

            // The new return time starts on the next day.
            changes[r].push_back({day + 1, x});
        } else {
            int r;
            cin >> r;
            queries[r].push_back({day, queryCount++});
        }
    }

    vector<long long> answer(queryCount);
    constexpr int INF = numeric_limits<int>::max();

    for (int r = 1; r < N; ++r) {
        if (queries[r].empty()) {
            continue;
        }

        const auto &lowerChanges = changes[r - 1];
        const auto &upperChanges = changes[r];

        size_t lowerPos = 1;  // Skip the initial value
        size_t upperPos = 1;

        int lowerValue = initial[r - 1];
        int upperValue = initial[r];

        int segmentStart = 0;
        long long completed = 0;

        for (const Query &query : queries[r]) {
            // Apply all schedule changes effective by this query day.
            while (true) {
                int lowerBoundary =
                    lowerPos < lowerChanges.size()
                        ? lowerChanges[lowerPos].start
                        : INF;

                int upperBoundary =
                    upperPos < upperChanges.size()
                        ? upperChanges[upperPos].start
                        : INF;

                int boundary = min(lowerBoundary, upperBoundary);
                if (boundary > query.day) {
                    break;
                }

                // Close the segment [segmentStart, boundary).
                if (upperValue < lowerValue) {
                    completed += boundary - segmentStart;
                }

                segmentStart = boundary;

                if (lowerBoundary == boundary) {
                    lowerValue = lowerChanges[lowerPos].value;
                    ++lowerPos;
                }

                if (upperBoundary == boundary) {
                    upperValue = upperChanges[upperPos].value;
                    ++upperPos;
                }
            }

            long long result = completed;
            if (upperValue < lowerValue) {
                result += query.day - segmentStart + 1;
            }

            answer[query.id] = result;
        }
    }

    for (long long result : answer) {
        cout << result << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> positions(N + 1);
    int distinctLabels = 0;

    for (int i = 0; i < N; ++i) {
        int a;
        cin >> a;
        if (positions[a].empty()) ++distinctLabels;
        positions[a].push_back(i);
    }

    vector<int> multiLabels;
    int singletonLabels = 0;

    for (int label = 1; label <= N; ++label) {
        if (positions[label].size() == 1) {
            ++singletonLabels;
        } else if (positions[label].size() > 1) {
            multiLabels.push_back(label);
        }
    }

    int B = max(1, (int)sqrt((double)N));
    int K = (N - 1) / (B + 1) + 1;

    vector<int> answer(N + 1, 0);
    vector<int> delta(N + 2, 0);

    // Directly compute the answers for small x.
    for (int x = 1; x <= B; ++x) {
        int total = singletonLabels;

        for (int label : multiLabels) {
            const vector<int> &v = positions[label];
            int m = (int)v.size();
            int j = 0;

            while (j < m) {
                ++total;
                int start = v[j++];
                while (j < m && v[j] - start <= x) ++j;
            }
        }

        answer[x] = total;
    }

    const int firstLargeX = B + 1;

    // A threshold g contributes one extra group for firstLargeX <= x < g.
    auto addThreshold = [&](int g) {
        if (g > firstLargeX) {
            ++delta[firstLargeX];
            --delta[g];
        }
    };

    /*
     * For each label, let g[k] be the smallest x allowing at most k groups.
     * For large x, only g[1], ..., g[min(m,K)-1] are needed.
     *
     * DP transition, covering the first i occurrences with k groups:
     * dp[i] = min over j of max(previous[j], v[i-1] - v[j]).
     * The monotone pointer finds the best j in amortized O(1).
     */
    for (int label : multiLabels) {
        const vector<int> &v = positions[label];
        int m = (int)v.size();
        int limit = min(m, K);

        if (limit <= 1) continue;

        int g = v.back() - v.front();
        addThreshold(g);

        if (g <= firstLargeX || limit == 2) continue;

        vector<int> previous(m + 1), current(m + 1);

        // DP for one group.
        for (int i = 1; i <= m; ++i) {
            previous[i] = v[i - 1] - v[0];
        }

        for (int k = 2; k < limit; ++k) {
            int ptr = k - 1;

            for (int i = k; i <= m; ++i) {
                int endpoint = v[i - 1];

                while (ptr < i - 1 &&
                       previous[ptr] + v[ptr] < endpoint) {
                    ++ptr;
                }

                int best = previous[ptr];
                if (ptr > k - 1) {
                    best = min(best, endpoint - v[ptr - 1]);
                }

                current[i] = best;
            }

            g = current[m];
            addThreshold(g);

            if (g <= firstLargeX) break;
            swap(previous, current);
        }
    }

    int extraGroups = 0;
    for (int x = firstLargeX; x <= N; ++x) {
        extraGroups += delta[x];
        answer[x] = distinctLabels + extraGroups;
    }

    for (int x = 1; x <= N; ++x) {
        cout << answer[x] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> positions(N + 1);
    for (int i = 1; i <= N; i++) {
        int a;
        cin >> a;
        positions[a].push_back(i);
    }

    int distinctLabels = 0;
    for (int label = 1; label <= N; label++) {
        if (!positions[label].empty()) distinctLabels++;
    }

    vector<int> direct(N + 1, 0);
    vector<int> delta(N + 3, 0);

    for (int label = 1; label <= N; label++) {
        const vector<int>& p = positions[label];
        int m = (int)p.size();
        if (m <= 1) continue;

        int L = m - 1;

        if (L == 1) {
            int span = p[1] - p[0];
            if (span > 1) {
                delta[1]++;
                delta[span]--;
            }
            continue;
        }

        vector<int> prefix(L + 1, 0);
        for (int i = 1; i <= L; i++) {
            prefix[i] = p[i] - p[0];
        }

        int span = prefix[L];
        int K = (int)sqrt((double)span);
        K = max(K, 1);
        K = min(K, L);

        vector<int> bottleneck(K + 1, 0);
        vector<int> previous(L + 1, 0), current(L + 1, 0), combined(L + 1, 0);

        for (int i = 1; i <= L; i++) previous[i] = prefix[i];
        bottleneck[1] = span;

        for (int r = 2; r <= K; r++) {
            int low = r - 1;

            for (int i = low; i <= L; i++) {
                combined[i] = previous[i] + prefix[i];
            }

            int pointer = low - 1;

            for (int j = r; j <= L; j++) {
                int high = j - 1;

                while (pointer < high &&
                       combined[pointer + 1] <= prefix[j]) {
                    pointer++;
                }

                int best = -1;

                if (pointer >= low) {
                    best = previous[pointer];
                }

                if (pointer < high) {
                    int candidate = prefix[j] - prefix[pointer + 1];
                    best = max(best, candidate);
                }

                current[j] = best;
            }

            bottleneck[r] = current[L];
            swap(previous, current);
        }

        if (K == L) {
            for (int r = 1; r <= L; r++) {
                int b = bottleneck[r];
                if (b > 1) {
                    delta[1]++;
                    delta[b]--;
                }
            }
        } else {
            int split = bottleneck[K];

            for (int x = 1; x < split; x++) {
                int extraGroups = 0;
                int last = p[0];

                for (int i = 1; i < m; i++) {
                    if (p[i] - last > x) {
                        extraGroups++;
                        last = p[i];
                    }
                }

                direct[x] += extraGroups;
            }

            for (int r = 1; r <= K; r++) {
                if (bottleneck[r] > split) {
                    delta[split]++;
                    delta[bottleneck[r]]--;
                }
            }
        }
    }

    int active = 0;
    for (int x = 1; x <= N; x++) {
        active += delta[x];
        cout << distinctLabels + direct[x] + active << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    vector<vector<int>> occ(N + 1);
    for (int i = 1; i <= N; i++) {
        cin >> a[i];
        occ[a[i]].push_back(i);
    }

    int B = max(1, (int)sqrt(2.0 * N));
    B = min(B, N);

    vector<int> answer(N + 1, 0);

    // Compute small x directly using the greedy maximum separated set.
    vector<int> last(N + 1, 0), seen(N + 1, 0);
    for (int x = 1; x <= B; x++) {
        int groups = 0;
        for (int i = 1; i <= N; i++) {
            int c = a[i];
            if (seen[c] != x) {
                seen[c] = x;
                last[c] = i;
                groups++;
            } else if (i - last[c] > x) {
                last[c] = i;
                groups++;
            }
        }
        answer[x] = groups;
    }

    // drop[r] is how many groups disappear when x reaches r.
    vector<int> drop(N + 2, 0);

    for (int c = 1; c <= N; c++) {
        const vector<int> &p = occ[c];
        int k = (int)p.size();
        if (k < 2) continue;

        int diameter = p.back() - p.front();
        if (diameter <= B) continue;

        // If R_v > B, then (v-1)*(B+1) <= diameter.
        int V = min(k, 1 + diameter / (B + 1));

        // R_2 is simply the diameter.
        drop[diameter]++;
        if (V == 2) continue;

        // prev[i]: best bottleneck for a chain of the current length
        // starting at p[0] and ending at p[i].
        vector<int> prev(k), cur(k);
        for (int i = 1; i < k; i++) {
            prev[i] = p[i] - p[0]; // Chains of length 2.
        }

        for (int v = 3; v <= V; v++) {
            int L = v - 2;       // First valid endpoint in prev.
            int h = L - 1;

            for (int i = v - 1; i < k; i++) {
                while (h + 1 < i &&
                       p[h + 1] + prev[h + 1] <= p[i]) {
                    h++;
                }

                int best = -1;
                if (h >= L) best = prev[h];

                int j = h + 1;
                if (j < i) best = max(best, p[i] - p[j]);

                cur[i] = best;
            }

            int R = cur[k - 1];
            if (R <= B) break; // Later R values are no larger.

            drop[R]++;
            swap(prev, cur);
        }
    }

    for (int x = B + 1; x <= N; x++) {
        answer[x] = answer[x - 1] - drop[x];
    }

    for (int x = 1; x <= N; x++) {
        cout << answer[x] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int count_groups_full(const vector<int>& P, int x) {
    int m = (int)P.size();
    int i = 0, cnt = 0;

    if (m > 700) {
        while (i < m) {
            ++cnt;
            int start = P[i];
            i = upper_bound(P.begin() + i + 1, P.end(), start + x) - P.begin();
        }
    } else {
        while (i < m) {
            ++cnt;
            int start = P[i];
            ++i;
            while (i < m && P[i] - start <= x) ++i;
        }
    }

    return cnt;
}

bool groups_leq(const vector<int>& P, int x, int k) {
    int m = (int)P.size();
    int i = 0, cnt = 0;

    if (m > 700) {
        while (i < m) {
            ++cnt;
            if (cnt > k) return false;

            int start = P[i];
            i = upper_bound(P.begin() + i + 1, P.end(), start + x) - P.begin();
        }
        return true;
    } else {
        while (i < m) {
            ++cnt;
            if (cnt > k) return false;

            int start = P[i];
            ++i;
            while (i < m && P[i] - start <= x) ++i;
        }
        return true;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N);
    vector<vector<int>> occ(N + 1);
    vector<int> present;
    present.reserve(N);

    for (int i = 0; i < N; ++i) {
        int label;
        cin >> label;
        a[i] = label;

        if (occ[label].empty()) present.push_back(label);
        occ[label].push_back(i + 1);
    }

    int distinct = (int)present.size();

    int S = min(N, 1200);

    vector<int> ans(N + 1);
    vector<int> ver(N + 1, 0), start(N + 1, 0);

    // Directly compute answers for small x.
    for (int x = 1; x <= S; ++x) {
        int groups = 0;

        for (int i = 0; i < N; ++i) {
            int label = a[i];
            int pos = i + 1;

            if (ver[label] != x) {
                ver[label] = x;
                start[label] = pos;
                ++groups;
            } else if (pos - start[label] > x) {
                start[label] = pos;
                ++groups;
            }
        }

        ans[x] = groups;
    }

    // Handle larger x using range updates.
    if (S < N) {
        vector<int> diff(N + 3, 0);

        for (int label : present) {
            vector<int>& P = occ[label];
            int m = (int)P.size();

            if (m <= 1) continue;

            int span = P.back() - P.front();

            // All occurrences already fit into one group for every x > S.
            if (span <= S + 1) continue;

            int g = count_groups_full(P, S + 1);
            if (g <= 1) continue;

            vector<int> h(g + 1);
            h[1] = span;

            int prevHi = span;

            for (int k = 2; k < g; ++k) {
                int lo = S + 1;
                int hi = prevHi;

                while (hi - lo > 1) {
                    int mid = (lo + hi) >> 1;

                    if (groups_leq(P, mid, k)) {
                        hi = mid;
                    } else {
                        lo = mid;
                    }
                }

                h[k] = hi;
                prevHi = hi;
            }

            for (int k = 2; k <= g; ++k) {
                int L = (k == g ? S + 1 : h[k]);
                int R = h[k - 1] - 1;

                if (L < S + 1) L = S + 1;
                if (R > N) R = N;

                if (L <= R) {
                    int extra = k - 1;
                    diff[L] += extra;
                    diff[R + 1] -= extra;
                }
            }
        }

        int running = 0;

        for (int x = S + 1; x <= N; ++x) {
            running += diff[x];
            ans[x] = distinct + running;
        }
    }

    for (int x = 1; x <= N; ++x) {
        cout << ans[x] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> pos(N + 1);
    for (int i = 0; i < N; ++i) {
        int a;
        cin >> a;
        pos[a].push_back(i); // 0-indexed positions
    }

    vector<vector<int>> groups;
    groups.reserve(N);
    for (int v = 1; v <= N; ++v) {
        if (!pos[v].empty()) {
            groups.push_back(move(pos[v]));
        }
    }

    // For small x, compute answers directly.
    const int T = min(N, 500);
    vector<long long> base(T + 1, 0);

    for (int x = 1; x <= T; ++x) {
        long long total = 0;

        for (const auto &p : groups) {
            int sz = (int)p.size();
            int i = 0;

            while (i < sz) {
                ++total;

                int limit = p[i] + x;
                int j = i;
                while (j + 1 < sz && p[j + 1] <= limit) {
                    ++j;
                }

                i = j + 1;
            }
        }

        base[x] = total;
    }

    if (T == N) {
        for (int x = 1; x <= N; ++x) {
            cout << base[x] << '\n';
        }
        return 0;
    }

    const int startX = T + 1;
    const int SMALL_K = 3000;

    vector<long long> diff(N + 3, 0);

    for (const auto &p : groups) {
        int k = (int)p.size();
        int span = p.back() - p.front();

        // For all x > T >= span, all occurrences can be in one group.
        if (span <= T) {
            diff[startX] += 1;
            diff[N + 1] -= 1;
            continue;
        }

        if (k <= SMALL_K) {
            vector<int> prev(k), cur(k);
            vector<int> d(k + 1);

            // One group.
            d[1] = span;
            for (int i = 0; i < k; ++i) {
                prev[i] = p[i] - p[0];
            }

            // DP to find d[m] = minimum possible maximum span when using m groups.
            for (int m = 2; m <= k; ++m) {
                int jptr = m - 1;

                for (int i = m - 1; i < k; ++i) {
                    while (jptr + 1 <= i &&
                           prev[jptr] + p[jptr + 1] <= p[i]) {
                        ++jptr;
                    }

                    int best = INT_MAX;

                    {
                        int j = jptr;
                        int A = prev[j - 1];
                        int B = p[i] - p[j];
                        best = max(A, B);
                    }

                    if (jptr + 1 <= i) {
                        int j = jptr + 1;
                        int A = prev[j - 1];
                        int B = p[i] - p[j];
                        best = min(best, max(A, B));
                    }

                    cur[i] = best;
                }

                d[m] = cur[k - 1];
                prev.swap(cur);
            }

            // Add this label's contribution for x > T.
            for (int m = 1; m <= k; ++m) {
                int L = (m == 1 ? d[1] : d[m]);
                int R = (m == 1 ? N : d[m - 1] - 1);

                if (L < startX) L = startX;
                if (R > N) R = N;

                if (L <= R) {
                    diff[L] += m;
                    diff[R + 1] -= m;
                }
            }
        } else {
            // Heavy label: simulate each x > T using binary search jumps.
            int end = min(N, span);

            for (int x = startX; x <= end; ++x) {
                int groupsCount = 0;
                int i = 0;

                while (i < k) {
                    ++groupsCount;

                    int limit = p[i] + x;

                    if (limit >= p.back()) {
                        break;
                    }

                    int lo = i + 1;
                    int hi = k;

                    while (lo < hi) {
                        int mid = (lo + hi) >> 1;
                        if (p[mid] <= limit) {
                            lo = mid + 1;
                        } else {
                            hi = mid;
                        }
                    }

                    i = lo;
                }

                diff[x] += groupsCount;
                diff[x + 1] -= groupsCount;
            }

            // For x > span, all occurrences fit into one group.
            int L = max(startX, span + 1);
            if (L <= N) {
                diff[L] += 1;
                diff[N + 1] -= 1;
            }
        }
    }

    long long curSum = 0;

    for (int x = 1; x <= N; ++x) {
        curSum += diff[x];

        long long ans;
        if (x <= T) {
            ans = base[x] + curSum;
        } else {
            ans = curSum;
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005;
const int B = 2000;

int N;
vector<int> pos[MAXN];
long long diffArr[MAXN];

inline void addThreshold(int d) {
    // Add +1 to extra[x] for 1 <= x < d
    if (d > 1) {
        diffArr[1] += 1;
        diffArr[d] -= 1;
    }
}

inline int calcGroups(const vector<int>& p, int x) {
    int m = (int)p.size();
    int idx = 0;
    int groups = 0;

    while (idx < m) {
        ++groups;
        int limit = p[idx] + x;
        idx = int(upper_bound(p.begin() + idx, p.end(), limit) - p.begin());
    }

    return groups;
}

void processSmall(const vector<int>& p) {
    int m = (int)p.size();
    if (m < 2) return;

    int span = p.back() - p.front();
    addThreshold(span);

    if (m == 2) return;

    vector<int> prev(m), cur(m);

    // For selecting 2 points ending at j, best minimum gap is p[j] - p[0].
    for (int j = 1; j < m; ++j) {
        prev[j] = p[j] - p[0];
    }

    // Compute M_k = maximum possible minimum gap when selecting k points.
    for (int k = 3; k <= m; ++k) {
        int L = k - 2;
        int t = L - 1;

        for (int i = k - 1; i < m; ++i) {
            while (t + 1 <= i - 1 &&
                   prev[t + 1] + p[t + 1] < p[i]) {
                ++t;
            }

            int best = 0;

            if (t >= L) best = prev[t];

            int j2 = max(L, t + 1);
            if (j2 <= i - 1) {
                best = max(best, p[i] - p[j2]);
            }

            cur[i] = best;
        }

        addThreshold(cur[m - 1]);
        swap(prev, cur);
    }
}

void solveRange(const vector<int>& p, int l, int r, int vl, int vr) {
    if (l > r) return;

    if (vl == vr) {
        if (vl > 0) {
            diffArr[l] += vl;
            diffArr[r + 1] -= vl;
        }
        return;
    }

    if (l == r) {
        if (vl > 0) {
            diffArr[l] += vl;
            diffArr[l + 1] -= vl;
        }
        return;
    }

    if (l + 1 == r) {
        if (vl > 0) {
            diffArr[l] += vl;
            diffArr[l + 1] -= vl;
        }
        if (vr > 0) {
            diffArr[r] += vr;
            diffArr[r + 1] -= vr;
        }
        return;
    }

    int mid = (l + r) >> 1;
    int vm = calcGroups(p, mid) - 1;

    solveRange(p, l, mid, vl, vm);

    int vm1;
    if (mid + 1 == r) vm1 = vr;
    else vm1 = calcGroups(p, mid + 1) - 1;

    solveRange(p, mid + 1, r, vm1, vr);
}

void processLarge(const vector<int>& p) {
    int e1 = calcGroups(p, 1) - 1;
    if (e1 <= 0) return;

    int R = p.back() - p.front();
    solveRange(p, 1, R, e1, 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 1; i <= N; ++i) {
        int a;
        cin >> a;
        pos[a].push_back(i);
    }

    long long base = 0;

    for (int label = 1; label <= N; ++label) {
        if (pos[label].empty()) continue;

        ++base;

        int m = (int)pos[label].size();
        if (m == 1) continue;

        if (m <= B) {
            processSmall(pos[label]);
        } else {
            processLarge(pos[label]);
        }
    }

    long long cur = base;

    for (int x = 1; x <= N; ++x) {
        cur += diffArr[x];
        cout << cur << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static int countGroups(const vector<int>& p, int x) {
    int groups = 1;
    int first = p[0];

    for (int i = 1; i < (int)p.size(); ++i) {
        if (p[i] - first > x) {
            ++groups;
            first = p[i];
        }
    }

    return groups;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> positions(N + 1);
    for (int i = 1; i <= N; ++i) {
        int a;
        cin >> a;
        positions[a].push_back(i);
    }

    const int S = max(1, (int)sqrt((double)N));

    vector<int> answer(N + 1, 0);
    vector<int> drops(N + 1, 0);

    int usedLabels = 0;
    for (int label = 1; label <= N; ++label) {
        if (!positions[label].empty()) {
            ++usedLabels;
        }
    }

    // Every nonempty label contributes at least one group.
    for (int x = 1; x <= S; ++x) {
        answer[x] = usedLabels;
    }

    vector<int> dp, nextDp;

    for (int label = 1; label <= N; ++label) {
        const vector<int>& p = positions[label];
        int m = (int)p.size();

        if (m <= 1) {
            continue;
        }

        int span = p.back() - p.front();

        // Compute all small-x answers directly.
        for (int x = 1; x <= S; ++x) {
            if (span <= x) {
                continue;  // This label already contributes its one baseline group.
            }
            answer[x] += countGroups(p, x) - 1;
        }

        int b = countGroups(p, S);
        if (b <= 1) {
            continue;
        }

        /*
        dp[i] = minimum possible maximum group span when the first i
                occurrences are partitioned into exactly g groups.

        Initially g = 1.
        */
        dp.resize(m + 1);
        nextDp.resize(m + 1);

        for (int i = 1; i <= m; ++i) {
            dp[i] = p[i - 1] - p[0];
        }

        // D_1: all occurrences must be in one group.
        ++drops[span];

        /*
        For each g = 2,...,b-1, compute dp_g[i] in O(m).

        The optimal previous split is found by maintaining the first j for which
        dp_{g-1}[j] >= p[i-1] - p[j].
        */
        for (int g = 2; g < b; ++g) {
            int ptr = g - 1;

            for (int i = g; i <= m; ++i) {
                while (ptr < i - 1 &&
                       dp[ptr] < p[i - 1] - p[ptr]) {
                    ++ptr;
                }

                int best = dp[ptr];

                if (ptr > g - 1) {
                    best = min(best, p[i - 1] - p[ptr - 1]);
                }

                nextDp[i] = best;
            }

            dp.swap(nextDp);

            // D_g = dp_g[m].
            ++drops[dp[m]];
        }
    }

    // For x > S, apply all group-count decreases at their thresholds.
    int current = answer[S];
    for (int x = S + 1; x <= N; ++x) {
        current -= drops[x];
        answer[x] = current;
    }

    for (int x = 1; x <= N; ++x) {
        cout << answer[x] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> positions(N + 1);
    for (int i = 1; i <= N; ++i) {
        int a;
        cin >> a;
        positions[a].push_back(i);
    }

    int labelCount = 0;
    for (int a = 1; a <= N; ++a) {
        if (!positions[a].empty()) ++labelCount;
    }

    // B is Theta(sqrt(N)); the constant is tuned to balance the two parts.
    int B = min(N, max(1, (int)sqrt(2.0 * N)));
    int K = 1 + (N - 1) / (B + 2);

    // Every nonempty label always contributes at least one group.
    vector<int> answer(N + 1, labelCount);
    vector<int> diff(N + 2, 0);

    vector<int> previous, current, D;

    for (int a = 1; a <= N; ++a) {
        const vector<int>& p = positions[a];
        int m = (int)p.size();

        if (m <= 1) continue;

        int span = p.back() - p.front();

        // Small x: compute the greedy number of groups directly.
        // For x >= span, all occurrences already form one group.
        int smallLimit = min(B, span - 1);
        for (int x = 1; x <= smallLimit; ++x) {
            int groups = 1;
            int groupEnd = p[0] + x;

            for (int i = 1; i < m; ++i) {
                if (p[i] > groupEnd) {
                    ++groups;
                    groupEnd = p[i] + x;
                }
            }

            answer[x] += groups - 1;
        }

        // At x >= B+1, span <= B+1 means this label forms one group.
        if (span <= B + 1) continue;

        int limit = min(m, K);
        if (limit < 2) continue;

        // previous[j] = F_{k-1}(j).
        // N acts as infinity because every distance is at most N-1.
        previous.assign(m, N);
        current.assign(m, 0);
        D.assign(limit + 1, 0);

        int lastComputed = 1;

        for (int k = 2; k <= limit; ++k) {
            int c = k - 2;

            for (int j = k - 1; j < m; ++j) {
                // Find the first crossing:
                // previous[c] >= p[j] - p[c].
                while (c < j && previous[c] + p[c] < p[j]) {
                    ++c;
                }

                int best = 0;

                // Right side of the crossing.
                if (c < j) {
                    best = p[j] - p[c];
                }

                // Left side of the crossing.
                if (c > k - 2) {
                    best = max(best, previous[c - 1]);
                }

                current[j] = best;
            }

            // F_k[j] is nondecreasing in j.
            D[k] = current[m - 1];
            lastComputed = k;

            previous.swap(current);

            // D_k is nonincreasing, so later thresholds cannot contribute.
            if (D[k] <= B + 1) break;
        }

        // D_k > x contributes one additional group exactly when
        // x is in [B+1, D_k-1].
        for (int k = 2; k <= lastComputed; ++k) {
            int d = D[k];
            if (d > B + 1) {
                ++diff[B + 1];
                --diff[d];
            }
        }
    }

    int extraGroups = 0;
    for (int x = B + 1; x <= N; ++x) {
        extraGroups += diff[x];
        answer[x] += extraGroups;
    }

    for (int x = 1; x <= N; ++x) {
        cout << answer[x] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> positions(N + 1);
    for (int i = 1; i <= N; ++i) {
        int label;
        cin >> label;
        positions[label].push_back(i);
    }

    const int B = max(1, (int)sqrt((double)N));
    const int K = (N + B) / (B + 1);  // ceil(N / (B + 1))

    // For small x, directly run the optimal greedy algorithm.
    vector<int> smallAnswer(B + 1);
    vector<int> groupStart(N + 1);

    for (int x = 1; x <= B; ++x) {
        fill(groupStart.begin(), groupStart.end(), 0);

        int groups = 0;
        for (int i = 1; i <= N; ++i) {
            int label = a_label(i);
            if (groupStart[label] == 0 || i - groupStart[label] > x) {
                ++groups;
                groupStart[label] = i;
            }
        }
        smallAnswer[x] = groups;
    }

    // Difference array for the answers with x > B.
    vector<long long> diff(N + 2, 0);
    vector<int> previous, current;

    for (int label = 1; label <= N; ++label) {
        const vector<int>& p = positions[label];
        const int m = (int)p.size();
        if (m == 0) continue;

        if (m == 1) {
            if (B < N) {
                ++diff[B + 1];
                --diff[N + 1];
            }
            continue;
        }

        /*
          D[k] is the smallest possible maximum group span when the
          occurrences of this label are partitioned into k groups.

          previous[i] is the corresponding optimum for the first i
          occurrences using k-1 groups.
        */
        const int limitK = min(m, K);
        vector<int> D(limitK + 1);
        D[0] = N + 1;

        previous.resize(m + 1);
        current.resize(m + 1);

        // Base case: one group.
        previous[0] = 0;
        for (int i = 1; i <= m; ++i) {
            previous[i] = p[i - 1] - p[0];
        }
        D[1] = previous[m];

        for (int k = 2; k <= limitK; ++k) {
            int t = k - 1;

            for (int i = k; i <= m; ++i) {
                /*
                  Find the first split j for which
                  previous[j] > p[i-1] - p[j].
                */
                while (t < i && previous[t] + p[t] <= p[i - 1]) {
                    ++t;
                }

                if (t == k - 1) {
                    current[i] = previous[t];
                } else if (t == i) {
                    current[i] = 0;
                } else {
                    current[i] = min(previous[t], p[i - 1] - p[t - 1]);
                }
            }

            D[k] = current[m];
            previous.swap(current);
        }

        /*
          The minimum number of groups for a given x is k exactly when
          D[k] <= x < D[k-1].
        */
        for (int k = 1; k <= limitK; ++k) {
            int left = max(B + 1, D[k]);
            int right = min(N, D[k - 1] - 1);

            if (left <= right) {
                diff[left] += k;
                diff[right + 1] -= k;
            }
        }
    }

    vector<long long> answer(N + 1);
    for (int x = 1; x <= B; ++x) {
        answer[x] = smallAnswer[x];
    }

    long long running = 0;
    for (int x = B + 1; x <= N; ++x) {
        running += diff[x];
        answer[x] = running;
    }

    for (int x = 1; x <= N; ++x) {
        cout << answer[x] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string s;
    cin >> N >> s;

    vector<int> nextB(N + 1, N), nextR(N + 1, N), prevR(N, -1);
    for (int i = N - 1; i >= 0; --i) {
        nextB[i] = (s[i] == 'B' ? i : nextB[i + 1]);
        nextR[i] = (s[i] == 'R' ? i : nextR[i + 1]);
    }
    int last = -1;
    for (int i = 0; i < N; ++i) {
        if (s[i] == 'R') last = i;
        prevR[i] = last;
    }

    vector<int> dp(N + 1, 0);
    array<vector<int>, 2> diff;
    diff[0].assign(N + 3, 0);
    diff[1].assign(N + 3, 0);

    long long active[2] = {0, 0};
    dp[0] = 1;

    for (int p = 0; p <= N; ++p) {
        int parity = p & 1;
        active[parity] += diff[parity][p];
        if (active[parity] >= MOD) active[parity] -= MOD;

        int val = dp[p] + (int)active[parity];
        if (val >= MOD) val -= MOD;
        dp[p] = val;

        if (p == N) break;
        if (val == 0) continue;

        if (s[p] == 'X') {
            dp[p + 1] += val;
            if (dp[p + 1] >= MOD) dp[p + 1] -= MOD;
        }

        int U = min((N - p) / 2, nextB[p] - p);
        if (U <= 0) continue;

        auto &D = diff[parity];

        // Add val to dp[p+2*x] for every x in [a,b].
        auto addInterval = [&](int a, int b) {
            if (a > b) return;
            int l = p + 2 * a;
            int r = p + 2 * b;

            int z = D[l] + val;
            if (z >= MOD) z -= MOD;
            D[l] = z;

            z = D[r + 2] - val;
            if (z < 0) z += MOD;
            D[r + 2] = z;
        };

        /*
         * For an R at distance d from p, the operation is invalid exactly
         * for half-lengths x in [d/2+1, d]. Only d <= 2*U-1 matters.
         * Merge these intervals; their union has O(log N) components.
         */
        int lastPos = p + 2 * U - 1;
        int rpos = nextR[p + 1];
        int cursor = 1;

        while (rpos <= lastPos) {
            int d = rpos - p;
            int L = d / 2 + 1;

            addInterval(cursor, L - 1);

            int c = d;
            while (c < U) {
                int far = prevR[p + 2 * c + 1];
                if (far > p + c) {
                    c = far - p;
                } else {
                    break;
                }
            }

            if (c >= U) {
                cursor = U + 1;
                break;
            }

            cursor = c + 1;
            int nextPos = p + 2 * c + 2;
            rpos = (nextPos > lastPos ? N : nextR[nextPos]);
        }

        addInterval(cursor, U);
    }

    cout << dp[N] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string s;
    cin >> N >> s;

    vector<int> nextR(N + 2, N + 1), nextB(N + 2, N + 1);
    for (int i = N; i >= 1; --i) {
        nextR[i] = (s[i - 1] == 'R') ? i : nextR[i + 1];
        nextB[i] = (s[i - 1] == 'B') ? i : nextB[i + 1];
    }

    vector<int> prevR(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        prevR[i] = (s[i - 1] == 'R') ? i : prevR[i - 1];
    }

    vector<int> dp(N + 2, 0);
    vector<int> diff[2];
    diff[0].assign(N + 3, 0);
    diff[1].assign(N + 3, 0);

    int running[2] = {0, 0};
    dp[1] = 1;

    for (int i = 1; i <= N + 1; ++i) {
        int parity = i & 1;
        int k = i >> 1;

        running[parity] += diff[parity][k];
        if (running[parity] >= MOD) running[parity] -= MOD;

        dp[i] += running[parity];
        if (dp[i] >= MOD) dp[i] -= MOD;

        if (i == N + 1) break;

        int value = dp[i];
        if (value == 0) continue;

        if (s[i - 1] == 'X') {
            dp[i + 1] += value;
            if (dp[i + 1] >= MOD) dp[i + 1] -= MOD;
        }

        int maxX = min((N - i + 1) / 2, nextB[i] - i);
        if (maxX <= 0) continue;

        auto addRange = [&](int l, int r) {
            if (l > r) return;

            int left = (i + 2 * l) >> 1;
            int right = (i + 2 * r) >> 1;
            int p = i & 1;

            diff[p][left] += value;
            if (diff[p][left] >= MOD) diff[p][left] -= MOD;

            diff[p][right + 1] -= value;
            if (diff[p][right + 1] < 0) diff[p][right + 1] += MOD;
        };

        int r = nextR[i + 1];
        if (r > N) {
            addRange(1, maxX);
            continue;
        }

        int d = r - i;
        int a = d / 2 + 1;

        if (a > maxX) {
            addRange(1, maxX);
            continue;
        }

        int current = 1;

        while (true) {
            addRange(current, a - 1);

            int end = d;

            while (end < maxX) {
                int limit = i + 2 * end + 1;
                if (limit > N) limit = N;

                int last = prevR[limit];
                if (last <= r) break;

                r = last;
                end = r - i;
            }

            if (end >= maxX) break;

            current = end + 1;
            r = (r < N) ? nextR[r + 1] : N + 1;

            if (r > N) {
                addRange(current, maxX);
                break;
            }

            d = r - i;
            a = d / 2 + 1;

            if (a > maxX) {
                addRange(current, maxX);
                break;
            }
        }
    }

    cout << dp[N + 1] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int MOD = 1000000007;

struct Fenwick {
    int n = 0;
    vector<int> tree;

    void init(int size) {
        n = size;
        tree.assign(n + 1, 0);
    }

    // Adds val to source index pos (0-based).
    void add(int pos, int val) {
        for (int i = pos + 1; i <= n; i += i & -i) {
            tree[i] += val;
            if (tree[i] >= MOD) tree[i] -= MOD;
        }
    }

    // Sum of source indices 0 through cnt-1.
    int prefix(int cnt) const {
        long long result = 0;
        for (int i = cnt; i > 0; i -= i & -i) {
            result += tree[i];
        }
        return static_cast<int>(result % MOD);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string s;
    cin >> N >> s;

    // nextB[i] = first forced B at position i or later.
    vector<int> nextB(N + 2, N + 1);
    int nxt = N + 1;
    for (int i = N; i >= 1; --i) {
        if (s[i - 1] == 'B') nxt = i;
        nextB[i] = nxt;
    }

    vector<int> dp(N + 1, 0);
    dp[0] = 1;

    Fenwick bit[2];
    bit[0].init(N + 1);
    bit[1].init(N + 1);

    int activeSum[2] = {0, 0};
    vector<vector<int>> removals(N + 2);

    int lastR = 0;

    for (int b = 1; b <= N; ++b) {
        for (int a : removals[b]) {
            int p = a & 1;
            bit[p].add(a, MOD - dp[a]);
            activeSum[p] -= dp[a];
            if (activeSum[p] < 0) activeSum[p] += MOD;
        }

        // A source a becomes available for tokens ending at b = a + 2.
        if (b >= 2) {
            int a = b - 2;
            if (dp[a] != 0) {
                int t = nextB[a + 1];
                long long expiration;
                if (t == N + 1) {
                    expiration = N + 1LL;
                } else {
                    expiration = 2LL * t - a - 1;
                }

                if (expiration >= b) {
                    int p = a & 1;
                    bit[p].add(a, dp[a]);
                    activeSum[p] += dp[a];
                    if (activeSum[p] >= MOD) activeSum[p] -= MOD;

                    if (expiration + 1 <= N) {
                        removals[static_cast<int>(expiration + 1)].push_back(a);
                    }
                }
            }
        }

        if (s[b - 1] == 'R') lastR = b;

        // Blue-half compatibility requires a >= 2*lastR-b.
        int lower = max(0, 2 * lastR - b);
        int p = b & 1;

        long long ways = activeSum[p] - bit[p].prefix(lower);
        if (ways < 0) ways += MOD;

        if (s[b - 1] == 'X') {
            ways += dp[b - 1];
            if (ways >= MOD) ways -= MOD;
        }

        dp[b] = static_cast<int>(ways);
    }

    cout << dp[N] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 1'000'000'007;

struct Run {
    int a, b, len, val;
};

int N, M;
vector<Run> runs;
vector<int> seg;
vector<int> pref0, pref1;
int curI, curL, curBlock;

void buildSeg(int node, int l, int r) {
    if (l == r) {
        seg[node] = runs[l].val;
        return;
    }
    int mid = (l + r) >> 1;
    buildSeg(node << 1, l, mid);
    buildSeg(node << 1 | 1, mid + 1, r);
    seg[node] = max(seg[node << 1], seg[node << 1 | 1]);
}

void addRun(int idx) {
    const Run &r = runs[idx];

    int lo = max(r.a, curI - curL);
    lo = max(lo, (curI + r.a) / 2);

    int hi = min(r.b, curI - 1);
    if (lo > hi) return;

    int pL = 2 * lo - curI;
    int pH = 2 * hi - curI;

    if (pH < 0) return;
    if (pL < 0) pL = 0;

    int total;
    if (curI & 1) {
        total = pref1[pH];
        if (pL > 0) total -= pref1[pL - 1];
    } else {
        total = pref0[pH];
        if (pL > 0) total -= pref0[pL - 1];
    }

    if (total < 0) total += MOD;

    curBlock += total;
    if (curBlock >= MOD) curBlock -= MOD;
}

void processRange(int node, int l, int r, int ql, int qr, int threshold) {
    if (r < ql || l > qr || seg[node] < threshold) return;

    if (l == r) {
        addRun(l);
        return;
    }

    int mid = (l + r) >> 1;
    processRange(node << 1, l, mid, ql, qr, threshold);
    processRange(node << 1 | 1, mid + 1, r, ql, qr, threshold);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    string s;
    cin >> s;

    vector<int> runId(N + 1, -1);
    vector<int> ends;

    for (int pos = 1; pos <= N;) {
        if (s[pos - 1] == 'B') {
            ++pos;
            continue;
        }

        int a = pos;
        while (pos <= N && s[pos - 1] != 'B') {
            ++pos;
        }
        int b = pos - 1;
        int len = b - a + 1;
        int idx = (int)runs.size();

        runs.push_back({a, b, len, b + len});
        ends.push_back(b);

        for (int p = a; p <= b; ++p) {
            runId[p] = idx;
        }
    }

    M = (int)runs.size();

    if (M > 0) {
        seg.assign(4 * M + 5, 0);
        buildSeg(1, 0, M - 1);
    }

    vector<int> dp(N + 1, 0);
    pref0.assign(N + 1, 0);
    pref1.assign(N + 1, 0);

    dp[0] = 1;
    pref0[0] = 1;

    int Lprev = 0;
    int rightIdx = -1;

    for (int i = 1; i <= N; ++i) {
        int L;
        if (s[i - 1] != 'R') L = Lprev + 1;
        else L = 0;
        Lprev = L;

        while (M > 0 && rightIdx + 1 < M && runs[rightIdx + 1].b <= i - 1) {
            ++rightIdx;
        }

        int ways = 0;
        if (s[i - 1] == 'X') {
            ways = dp[i - 1];
        }

        int block = 0;

        if (L > 0 && M > 0) {
            int lowerPos = i - L;
            int lidx = lower_bound(ends.begin(), ends.end(), lowerPos) - ends.begin();
            int ridx = rightIdx;

            curI = i;
            curL = L;
            curBlock = 0;

            if (lidx <= ridx) {
                processRange(1, 0, M - 1, lidx, ridx, i);
            }

            if (i >= 2 && s[i - 2] != 'B') {
                int rid = runId[i - 1];
                if (rid != -1 && runs[rid].b >= i) {
                    addRun(rid);
                }
            }

            block = curBlock;
        }

        int val = ways + block;
        if (val >= MOD) val -= MOD;
        dp[i] = val;

        pref0[i] = pref0[i - 1];
        pref1[i] = pref1[i - 1];

        if (i & 1) {
            pref1[i] += dp[i];
            if (pref1[i] >= MOD) pref1[i] -= MOD;
        } else {
            pref0[i] += dp[i];
            if (pref0[i] >= MOD) pref0[i] -= MOD;
        }
    }

    cout << dp[N] % MOD << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

struct BIT {
    int n;
    vector<int> tree;

    BIT() {}
    BIT(int n) { init(n); }

    void init(int n_) {
        n = n_;
        tree.assign(n + 1, 0);
    }

    void add(int idx, int val) {
        if (val < 0) val += MOD;
        for (; idx <= n; idx += idx & -idx) {
            tree[idx] += val;
            if (tree[idx] >= MOD) tree[idx] -= MOD;
        }
    }

    int sum(int idx) const {
        int res = 0;
        for (; idx > 0; idx -= idx & -idx) {
            res += tree[idx];
            if (res >= MOD) res -= MOD;
        }
        return res;
    }

    int rangeSum(int l, int r) const {
        if (l > r) return 0;
        int res = sum(r) - sum(l - 1);
        if (res < 0) res += MOD;
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    string s;
    cin >> s;

    vector<int> nextB(N + 2);
    int nb = N + 1;

    for (int i = N; i >= 1; --i) {
        if (s[i - 1] == 'B') nb = i;
        nextB[i] = nb;
    }

    vector<int> expire(N + 2);

    for (int L = 1; L <= N; ++L) {
        int p = nextB[L];
        long long e = 2LL * p - L - 1;
        if (e > N + 1) e = N + 1;
        expire[L] = (int)e;
    }

    vector<int> dp(N + 1, 0);
    dp[0] = 1;

    BIT bit[2];
    bit[0].init(N);
    bit[1].init(N);

    vector<vector<int>> removeAt(N + 2);

    int lastR = 0;

    for (int i = 1; i <= N; ++i) {
        for (int L : removeAt[i]) {
            int w = dp[L - 1];
            bit[L & 1].add(L, -w);
        }

        int Lins = i - 1;
        if (Lins >= 1 && expire[Lins] >= i) {
            int w = dp[Lins - 1];
            bit[Lins & 1].add(Lins, w);

            int remTime = expire[Lins] + 1;
            if (remTime <= N) {
                removeAt[remTime].push_back(Lins);
            }
        }

        if (s[i - 1] == 'R') lastR = i;

        int bound = 2 * lastR - i + 1;
        if (bound < 1) bound = 1;

        int tokenWays = 0;

        if (bound <= i - 1) {
            int parity = (i - 1) & 1;
            tokenWays = bit[parity].rangeSum(bound, i - 1);
        }

        long long ways = tokenWays;

        if (s[i - 1] == 'X') {
            ways += dp[i - 1];
        }

        dp[i] = ways % MOD;
    }

    cout << dp[N] % MOD << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

struct Fenwick {
    int n;
    vector<int> bit;

    Fenwick() : n(0) {}
    Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int idx, int val) {
        for (int i = idx + 1; i <= n; i += i & -i) {
            int x = bit[i] + val;
            if (x >= MOD) x -= MOD;
            bit[i] = x;
        }
    }

    int sumPrefix(int idx) const {
        if (idx < 0) return 0;
        if (idx >= n) idx = n - 1;
        int res = 0;
        for (int i = idx + 1; i > 0; i -= i & -i) {
            res += bit[i];
            if (res >= MOD) res -= MOD;
        }
        return res;
    }

    int rangeSum(int l, int r) const {
        if (l > r) return 0;
        int res = sumPrefix(r) - sumPrefix(l - 1);
        if (res < 0) res += MOD;
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string s;
    cin >> N;
    cin >> s;

    vector<int> nextB(N + 1);
    nextB[N] = N; // one past the end

    for (int i = N - 1; i >= 0; --i) {
        if (s[i] == 'B') nextB[i] = i;
        else nextB[i] = nextB[i + 1];
    }

    vector<int> expire(N + 1);
    for (int a = 0; a <= N; ++a) {
        long long u = 2LL * nextB[a] - a;
        if (u > N) u = N;
        expire[a] = (int)u;
    }

    vector<int> dp(N + 1, 0);
    dp[0] = 1;

    Fenwick fen[2] = {Fenwick(N + 1), Fenwick(N + 1)};

    vector<vector<int>> removals(N + 2);

    int lastR = -1;

    for (int i = 1; i <= N; ++i) {
        // Remove starts that are no longer usable for this end.
        for (int a : removals[i]) {
            int p = a & 1;
            int val = (MOD - dp[a]) % MOD;
            fen[p].add(a, val);
        }

        // Start a = i - 2 first becomes usable for a token of length 2.
        int aNew = i - 2;
        if (aNew >= 0 && expire[aNew] >= i) {
            int p = aNew & 1;
            fen[p].add(aNew, dp[aNew]);

            if (expire[aNew] + 1 <= N) {
                removals[expire[aNew] + 1].push_back(aNew);
            }
        }

        if (s[i - 1] == 'R') {
            lastR = i - 1;
        }

        // Blue half must contain no R.
        int lower = 2 * lastR - i + 1;
        if (lower < 0) lower = 0;

        int upper = i - 2;
        int tokenWays = 0;

        if (lower <= upper) {
            int p = i & 1;
            tokenWays = fen[p].rangeSum(lower, upper);
        }

        int ways = tokenWays;

        // Last atom is a single white point.
        if (s[i - 1] == 'X') {
            ways += dp[i - 1];
            if (ways >= MOD) ways -= MOD;
        }

        dp[i] = ways;
    }

    cout << dp[N] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1'000'000'007;

struct Fenwick {
    int n;
    int total = 0;
    vector<int> bit;

    explicit Fenwick(int size) : n(size), bit(size + 1, 0) {}

    void add(int index, int value) {
        if (value == 0) return;

        total += value;
        if (total >= MOD) total -= MOD;

        for (int i = index; i <= n; i += i & -i) {
            bit[i] += value;
            if (bit[i] >= MOD) bit[i] -= MOD;
        }
    }

    int prefixSum(int index) const {
        int result = 0;
        for (int i = index; i > 0; i -= i & -i) {
            result += bit[i];
            if (result >= MOD) result -= MOD;
        }
        return result;
    }

    int suffixSum(int firstIndex) const {
        if (firstIndex > n) return 0;

        int result = total - prefixSum(firstIndex - 1);
        if (result < 0) result += MOD;
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string s;
    cin >> N >> s;
    s.insert(s.begin(), ' ');  // 1-indexed

    /*
       For each prefix boundary j, let b_j be the first fixed B strictly
       after j. A block starting at j+1 can end at t only while

           t < 2*b_j - j.

       expiration[j] is therefore the first endpoint where j becomes
       invalid. Expirations are stored in linked-list buckets.
    */
    vector<int> head(N + 2, -1);
    vector<int> nextInBucket(N + 1, -1);

    int nextB = N + 1;
    for (int j = N; j >= 0; --j) {
        // nextB is the first fixed B strictly after j.
        int expiration = 2 * nextB - j;
        if (expiration <= N) {
            nextInBucket[j] = head[expiration];
            head[expiration] = j;
        }

        // Position j becomes available for boundaries strictly before j.
        if (j >= 1 && s[j] == 'B') nextB = j;
    }

    /*
       Separate trees for even and odd prefix boundaries.
       Boundary j is stored at coordinate j/2 + 1 in its parity's tree.
    */
    Fenwick trees[2] = {
        Fenwick(N / 2 + 1),
        Fenwick((N + 1) / 2)
    };

    vector<int> dp(N + 1, 0);
    dp[0] = 1;
    trees[0].add(1, dp[0]);

    int lastR = 0;

    for (int t = 1; t <= N; ++t) {
        // These boundaries have just become invalid.
        for (int j = head[t]; j != -1; j = nextInBucket[j]) {
            if (dp[j] != 0) {
                trees[j & 1].add(j / 2 + 1, MOD - dp[j]);
            }
        }

        if (s[t] == 'R') lastR = t;

        /*
           A block covering positions j+1 ... t is valid only if

               j >= 2*lastR - t.

           Also j and t must have the same parity.
        */
        int lower = 2 * lastR - t;
        if (lower < 0) lower = 0;

        int parity = t & 1;
        if ((lower & 1) != parity) ++lower;

        int firstCoordinate = lower / 2 + 1;
        int ways = trees[parity].suffixSum(firstCoordinate);

        // Position t can instead remain white.
        if (s[t] == 'X') {
            ways += dp[t - 1];
            if (ways >= MOD) ways -= MOD;
        }

        dp[t] = ways;

        // This boundary may be used by future blocks.
        trees[parity].add(t / 2 + 1, dp[t]);
    }

    cout << dp[N] << '\n';
    return 0;
}

