static constexpr int MOD = 1'000'000'007;

struct Fenwick {
    int n;
    vector<int> bit;

    explicit Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int idx, int value) {
        if (value < 0) value += MOD;
        if (value >= MOD) value -= MOD;

        for (; idx <= n; idx += idx & -idx) {
            bit[idx] += value;
            if (bit[idx] >= MOD) bit[idx] -= MOD;
        }
    }

    int prefixSum(int idx) const {
        int result = 0;
        for (; idx > 0; idx -= idx & -idx) {
            result += bit[idx];
            if (result >= MOD) result -= MOD;
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string s;
    cin >> N >> s;
    s = " " + s;  // 1-indexed

    // nextB[k] is the first fixed B strictly after position k.
    vector<int> nextB(N + 1, N + 1);
    int nearest = N + 1;
    for (int k = N; k >= 0; --k) {
        nextB[k] = nearest;
        if (k >= 1 && s[k] == 'B') nearest = k;
    }

    /*
       A block beginning at k+1 and ending at i has midpoint
       (k+i)/2. If its first fixed B is b, it remains valid with
       respect to B's until i reaches expiry[k] = 2*b-k.
    */
    vector<int> expiry(N + 1);
    vector<int> head(N + 1, -1), link(N + 1, -1);

    for (int k = 0; k <= N; ++k) {
        int b = nextB[k];
        expiry[k] = 2 * b - k;

        if (k + 2 <= N && expiry[k] <= N) {
            link[k] = head[expiry[k]];
            head[expiry[k]] = k;
        }
    }

    // Separate Fenwick trees for even and odd prefix lengths.
    int fenwickSize = N / 2 + 2;
    Fenwick fen[2] = {Fenwick(fenwickSize), Fenwick(fenwickSize)};
    int total[2] = {0, 0};

    vector<unsigned char> active(N + 1, false);
    vector<int> dp(N + 1, 0);
    dp[0] = 1;

    int lastR = 0;

    for (int i = 1; i <= N; ++i) {
        if (s[i] == 'R') lastR = i;

        // Prefixes whose final block has just become invalid due to a B.
        for (int k = head[i]; k != -1; k = link[k]) {
            if (!active[k]) continue;

            int parity = k & 1;
            fen[parity].add(k / 2 + 1, MOD - dp[k]);

            total[parity] -= dp[k];
            if (total[parity] < 0) total[parity] += MOD;

            active[k] = false;
        }

        // Prefix k = i-2 can now be the beginning of a block ending at i.
        if (i >= 2) {
            int k = i - 2;
            if (expiry[k] > i) {
                int parity = k & 1;
                fen[parity].add(k / 2 + 1, dp[k]);

                total[parity] += dp[k];
                if (total[parity] >= MOD) total[parity] -= MOD;

                active[k] = true;
            }
        }

        // Leave position i white.
        int answer = (s[i] == 'X' ? dp[i - 1] : 0);

        // End a red-blue block at position i.
        if (i >= 2) {
            int parity = i & 1;

            // The blue half contains no fixed R iff k >= 2*lastR-i.
            int lower = 2 * lastR - i;
            int minimumK;
            if (lower <= 0) {
                minimumK = parity;
            } else {
                minimumK = lower;
                if ((minimumK & 1) != parity) ++minimumK;
            }

            int idx = minimumK / 2 + 1;
            int contribution = total[parity] - fen[parity].prefixSum(idx - 1);
            if (contribution < 0) contribution += MOD;

            answer += contribution;
            if (answer >= MOD) answer -= MOD;
        }

        dp[i] = answer;
    }

    cout << dp[N] << '\n';
    return 0;
}

