static constexpr int MOD = 1'000'000'007;

class Fenwick {
    int n;
    vector<int> tree;

public:
    explicit Fenwick(int n) : n(n), tree(n + 1, 0) {}

    void add(int index, int delta) {
        for (int p = index + 1; p <= n; p += p & -p) {
            tree[p] += delta;
            if (tree[p] >= MOD) tree[p] -= MOD;
        }
    }

    // Sum over indices [0, index].
    int prefix(int index) const {
        if (index < 0) return 0;
        index = min(index, n - 1);

        int result = 0;
        for (int p = index + 1; p > 0; p -= p & -p) {
            result += tree[p];
            if (result >= MOD) result -= MOD;
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string s;
    cin >> N >> s;

    // nextB[j] = first position strictly after j that is forced to be B.
    vector<int> nextB(N + 1);
    int nearestB = N + 1;
    for (int j = N; j >= 0; --j) {
        nextB[j] = nearestB;
        if (j > 0 && s[j - 1] == 'B') {
            nearestB = j;
        }
    }

    // A block [j+1, i] is red-compatible exactly when i <= limit[j].
    vector<int> limit(N + 1);
    vector<int> expireHead(N + 2, -1);
    vector<int> expireNext(N + 1, -1);

    for (int j = 0; j + 2 <= N; ++j) {
        limit[j] = 2 * nextB[j] - j - 2;

        // The source j becomes active at j+2 and expires after limit[j].
        if (limit[j] >= j + 2 && limit[j] + 1 <= N) {
            int when = limit[j] + 1;
            expireNext[j] = expireHead[when];
            expireHead[when] = j;
        }
    }

    // Separate Fenwick trees for even and odd source indices j.
    Fenwick bit[2] = {Fenwick(N + 1), Fenwick(N + 1)};
    int total[2] = {0, 0};

    vector<int> dp(N + 1, 0);
    dp[0] = 1;

    int lastR = 0;

    for (int i = 1; i <= N; ++i) {
        // Remove sources whose red halves have become incompatible.
        for (int j = expireHead[i]; j != -1; j = expireNext[j]) {
            if (dp[j] != 0) {
                int parity = j & 1;
                bit[parity].add(j, MOD - dp[j]);

                total[parity] -= dp[j];
                if (total[parity] < 0) total[parity] += MOD;
            }
        }

        // The source j = i-2 can now form a block ending at i.
        int j = i - 2;
        if (j >= 0 && limit[j] >= i && dp[j] != 0) {
            int parity = j & 1;
            bit[parity].add(j, dp[j]);

            total[parity] += dp[j];
            if (total[parity] >= MOD) total[parity] -= MOD;
        }

        if (s[i - 1] == 'R') {
            lastR = i;
        }

        // The blue half is compatible iff j >= 2*lastR - i.
        int lowerBound = 2 * lastR - i;
        int parity = i & 1;

        int blockWays = total[parity];
        if (lowerBound > 0) {
            blockWays -= bit[parity].prefix(lowerBound - 1);
            if (blockWays < 0) blockWays += MOD;
        }

        dp[i] = blockWays;

        // Alternatively, leave position i white.
        if (s[i - 1] == 'X') {
            dp[i] += dp[i - 1];
            if (dp[i] >= MOD) dp[i] -= MOD;
        }
    }

    cout << dp[N] << '\n';
    return 0;
}

