const int MAXN = 200005;
const long long INF = (1LL << 62);

int N;
long long costArr[MAXN];
int freeCat[MAXN];
long long dp[MAXN][3];
int med3[3][3][3];

inline void compute(int v) {
    int f = freeCat[v];
    long long c = costArr[v];

    long long oc[3];
    oc[0] = (f == 0 ? 0 : c);
    oc[1] = (f == 1 ? 0 : c);
    oc[2] = (f == 2 ? 0 : c);

    if (2 * v > N) {
        dp[v][0] = oc[0];
        dp[v][1] = oc[1];
        dp[v][2] = oc[2];
        return;
    }

    int l = 2 * v;
    int r = l + 1;

    long long best[3] = {INF, INF, INF};

    for (int own = 0; own < 3; own++) {
        long long co = oc[own];
        for (int x = 0; x < 3; x++) {
            long long dl = dp[l][x];
            for (int y = 0; y < 3; y++) {
                int out = med3[own][x][y];
                long long val = co + dl + dp[r][y];
                if (val < best[out]) best[out] = val;
            }
        }
    }

    dp[v][0] = best[0];
    dp[v][1] = best[1];
    dp[v][2] = best[2];
}

struct Event {
    int key;
    int node;
    int state;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    for (int a = 0; a < 3; a++) {
        for (int b = 0; b < 3; b++) {
            for (int c = 0; c < 3; c++) {
                int arr[3] = {a, b, c};
                sort(arr, arr + 3);
                med3[a][b][c] = arr[1];
            }
        }
    }

    cin >> N;

    vector<int> a(N + 1);
    vector<Event> events;
    events.reserve(2 * N);

    for (int i = 1; i <= N; i++) {
        long long c;
        cin >> a[i] >> c;

        costArr[i] = c;
        freeCat[i] = 2; // For m = -1, all a[i] >= 0, so G is free.

        events.push_back({a[i], i, 1});     // At m = a[i], E becomes free.
        events.push_back({a[i] + 1, i, 0}); // After m = a[i], L becomes free.
    }

    for (int v = N; v >= 1; v--) {
        compute(v);
    }

    int Q;
    cin >> Q;

    vector<pair<int, int>> queries(Q);
    for (int i = 0; i < Q; i++) {
        int m;
        cin >> m;
        queries[i] = {m, i};
    }

    sort(events.begin(), events.end(), [](const Event &x, const Event &y) {
        if (x.key != y.key) return x.key < y.key;
        return x.node < y.node;
    });

    sort(queries.begin(), queries.end());

    vector<long long> answer(Q);

    int ei = 0;
    int E = (int)events.size();

    for (auto [m, idx] : queries) {
        while (ei < E && events[ei].key <= m) {
            int v = events[ei].node;
            freeCat[v] = events[ei].state;

            int u = v;
            while (u >= 1) {
                compute(u);
                u /= 2;
            }

            ei++;
        }

        answer[idx] = dp[1][1];
    }

    for (int i = 0; i < Q; i++) {
        cout << answer[i] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005;
const long long INF = (1LL << 62);

int N;
int a[MAXN], b[MAXN];
long long c[MAXN];
long long dp[MAXN][3];
int med3[3][3][3];

void recompute(int v) {
    if (v * 2 > N) {
        long long cv = c[v];
        int bv = b[v];
        dp[v][0] = (bv == 0 ? 0LL : cv);
        dp[v][1] = (bv == 1 ? 0LL : cv);
        dp[v][2] = (bv == 2 ? 0LL : cv);
    } else {
        long long cost0 = (b[v] == 0 ? 0LL : c[v]);
        long long cost1 = (b[v] == 1 ? 0LL : c[v]);
        long long cost2 = (b[v] == 2 ? 0LL : c[v]);

        long long best0 = INF, best1 = INF, best2 = INF;
        int L = v * 2, R = L + 1;

        for (int y = 0; y < 3; y++) {
            long long dL = dp[L][y];
            for (int z = 0; z < 3; z++) {
                long long base = dL + dp[R][z];

                int s = med3[0][y][z];
                long long val = base + cost0;
                if (s == 0) {
                    if (val < best0) best0 = val;
                } else if (s == 1) {
                    if (val < best1) best1 = val;
                } else {
                    if (val < best2) best2 = val;
                }

                s = med3[1][y][z];
                val = base + cost1;
                if (s == 0) {
                    if (val < best0) best0 = val;
                } else if (s == 1) {
                    if (val < best1) best1 = val;
                } else {
                    if (val < best2) best2 = val;
                }

                s = med3[2][y][z];
                val = base + cost2;
                if (s == 0) {
                    if (val < best0) best0 = val;
                } else if (s == 1) {
                    if (val < best1) best1 = val;
                } else {
                    if (val < best2) best2 = val;
                }
            }
        }

        dp[v][0] = best0;
        dp[v][1] = best1;
        dp[v][2] = best2;
    }
}

void setBase(int v, int nb) {
    if (b[v] == nb) return;
    b[v] = nb;

    int u = v;
    while (u >= 1) {
        recompute(u);
        u >>= 1;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 1; i <= N; i++) {
        cin >> a[i] >> c[i];
    }

    for (int x = 0; x < 3; x++) {
        for (int y = 0; y < 3; y++) {
            for (int z = 0; z < 3; z++) {
                int arr[3] = {x, y, z};
                sort(arr, arr + 3);
                med3[x][y][z] = arr[1];
            }
        }
    }

    // Initially, for m smaller than every a_i, every node prefers state 2 (> m).
    for (int i = 1; i <= N; i++) b[i] = 2;

    for (int v = N; v >= 1; v--) {
        recompute(v);
    }

    int Q;
    cin >> Q;

    vector<int> queries(Q);
    for (int i = 0; i < Q; i++) {
        cin >> queries[i];
    }

    vector<int> qidx(Q);
    iota(qidx.begin(), qidx.end(), 0);
    sort(qidx.begin(), qidx.end(), [&](int x, int y) {
        return queries[x] < queries[y];
    });

    vector<int> ord(N);
    iota(ord.begin(), ord.end(), 1);
    sort(ord.begin(), ord.end(), [&](int x, int y) {
        return a[x] < a[y];
    });

    vector<long long> ans(Q);

    int p = 0;
    int qi = 0;

    while (qi < Q) {
        int m = queries[qidx[qi]];

        while (p < N && a[ord[p]] < m) {
            int v = ord[p++];
            setBase(v, 0);
        }

        int q = p;
        while (q < N && a[ord[q]] == m) {
            q++;
        }

        // At target m, nodes with a_i == m prefer state 1 (= m).
        for (int t = p; t < q; t++) {
            setBase(ord[t], 1);
        }

        long long res = dp[1][1];

        while (qi < Q && queries[qidx[qi]] == m) {
            ans[qidx[qi]] = res;
            qi++;
        }

        // For larger future m, these nodes become < m.
        for (int t = p; t < q; t++) {
            setBase(ord[t], 0);
        }

        p = q;
    }

    for (int i = 0; i < Q; i++) {
        cout << ans[i] << '\n';
    }

    return 0;
}

