    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    vector<int64> cost(N + 1);

    for (int i = 1; i <= N; ++i) {
        cin >> a[i] >> cost[i];
    }

    int Q;
    cin >> Q;

    vector<pair<int, int>> queries(Q);
    for (int i = 0; i < Q; ++i) {
        int m;
        cin >> m;
        queries[i] = {m, i};
    }
    sort(queries.begin(), queries.end());

    const int firstTarget = queries.front().first;

    // Category of each original value relative to the current target:
    // LT: a[i] < target, EQ: a[i] == target, GT: a[i] > target.
    vector<int> state(N + 1);
    for (int i = 1; i <= N; ++i) {
        if (a[i] < firstTarget) state[i] = LT;
        else if (a[i] == firstTarget) state[i] = EQ;
        else state[i] = GT;
    }

    // dp[i][category] is the minimum cost to make the value produced
    // by node i have the specified category relative to the target.
    vector<array<int64, 3>> dp(N + 1);

    auto pull = [&](int v) {
        // Cost of making node v's own initial value have each category.
        array<int64, 3> own{cost[v], cost[v], cost[v]};
        own[state[v]] = 0;

        const int left = 2 * v;
        if (left > N) {
            dp[v] = own;
            return;
        }

        // N is odd, so every internal node has exactly two children.
        const auto &L = dp[left];
        const auto &R = dp[left + 1];

        const int64 minOwn = min(own[LT], min(own[EQ], own[GT]));
        const int64 minL = min(L[LT], min(L[EQ], L[GT]));
        const int64 minR = min(R[LT], min(R[EQ], R[GT]));

        array<int64, 3> result;

        // The median is LT exactly when at least two inputs are LT.
        result[LT] = min(
            own[LT] + L[LT] + minR,
            min(own[LT] + R[LT] + minL,
                L[LT] + R[LT] + minOwn)
        );

        // The median is GT exactly when at least two inputs are GT.
        result[GT] = min(
            own[GT] + L[GT] + minR,
            min(own[GT] + R[GT] + minL,
                L[GT] + R[GT] + minOwn)
        );

        // At least two inputs equal the target.
        int64 twoEqual = min(
            own[EQ] + L[EQ] + minR,
            min(own[EQ] + R[EQ] + minL,
                L[EQ] + R[EQ] + minOwn)
        );

        // Exactly one input equals the target, while the other two
        // are on opposite sides of the target.
        int64 oneEqual = min(
            own[EQ] + min(L[LT] + R[GT], L[GT] + R[LT]),
            min(L[EQ] + min(own[LT] + R[GT], own[GT] + R[LT]),
                R[EQ] + min(own[LT] + L[GT], own[GT] + L[LT]))
        );

        result[EQ] = min(twoEqual, oneEqual);
        dp[v] = result;
    };

    // Children have larger indices, so this is a valid bottom-up order.
    for (int i = N; i >= 1; --i) {
        pull(i);
    }

    // As the target increases, a[i] changes category:
    // GT -> EQ at target a[i], then EQ -> LT at target a[i] + 1.
    vector<Event> events;
    events.reserve(2 * N);
    for (int i = 1; i <= N; ++i) {
        events.push_back({a[i], i, EQ});
        events.push_back({a[i] + 1, i, LT});
    }

    sort(events.begin(), events.end(),
         [](const Event &x, const Event &y) {
             return x.when < y.when;
         });

    size_t eventPos = 0;

    // States were initialized directly for the first target, so these
    // events have already been accounted for.
    while (eventPos < events.size() &&
           events[eventPos].when <= firstTarget) {
        ++eventPos;
    }

    auto update = [&](int v, int newType) {
        if (state[v] == newType) return;
        state[v] = newType;

        // Only this node and its ancestors are affected.
        for (int u = v; u > 0; u >>= 1) {
            pull(u);
        }
    };

    vector<int64> answer(Q);

    for (const auto &[target, queryIndex] : queries) {
        while (eventPos < events.size() &&
               events[eventPos].when <= target) {
            const Event event = events[eventPos++];
            update(event.node, event.type);
        }
        answer[queryIndex] = dp[1][EQ];
    }

    for (int64 result : answer) {
        cout << result << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using Arr = array<ll, 3>;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    vector<ll> cost(N + 1);

    for (int i = 1; i <= N; ++i) {
        cin >> a[i] >> cost[i];
    }

    int Q;
    cin >> Q;

    vector<pair<int, int>> queries(Q);
    for (int i = 0; i < Q; ++i) {
        cin >> queries[i].first;
        queries[i].second = i;
    }
    sort(queries.begin(), queries.end());

    vector<int> order(N);
    iota(order.begin(), order.end(), 1);
    sort(order.begin(), order.end(), [&](int x, int y) {
        return a[x] < a[y];
    });

    // States: 0 = value < m, 1 = value = m, 2 = value > m.
    vector<int> state(N + 1, 2);
    vector<Arr> weight(N + 1), dp(N + 1);

    // Initially, conceptually m is below every a[i], so every original
    // value is in state 2.
    for (int i = 1; i <= N; ++i) {
        weight[i] = {cost[i], cost[i], 0};
    }

    auto pull = [&](int v) {
        // N is odd, so every non-leaf has exactly two children.
        if (v > N / 2) {
            dp[v] = weight[v];
            return;
        }

        const Arr &own = weight[v];
        const Arr &left = dp[2 * v];
        const Arr &right = dp[2 * v + 1];

        ll minOwn = min(own[0], min(own[1], own[2]));
        ll minLeft = min(left[0], min(left[1], left[2]));
        ll minRight = min(right[0], min(right[1], right[2]));

        Arr result;

        // Median is LESS iff at least two inputs are LESS.
        result[0] = min(
            min(own[0] + left[0] + minRight,
                own[0] + right[0] + minLeft),
            left[0] + right[0] + minOwn
        );

        // Median is GREATER iff at least two inputs are GREATER.
        result[2] = min(
            min(own[2] + left[2] + minRight,
                own[2] + right[2] + minLeft),
            left[2] + right[2] + minOwn
        );

        // At least two inputs are EQUAL.
        ll atLeastTwoEqual = min(
            min(own[1] + left[1] + minRight,
                own[1] + right[1] + minLeft),
            left[1] + right[1] + minOwn
        );

        // Exactly one input is EQUAL, and the other two are LESS/GREATER.
        ll crossChildren = min(
            left[0] + right[2],
            left[2] + right[0]
        );
        ll crossOwnRight = min(
            own[0] + right[2],
            own[2] + right[0]
        );
        ll crossOwnLeft = min(
            own[0] + left[2],
            own[2] + left[0]
        );

        ll exactlyOneEqual = min(
            own[1] + crossChildren,
            min(left[1] + crossOwnRight,
                right[1] + crossOwnLeft)
        );

        result[1] = min(atLeastTwoEqual, exactlyOneEqual);
        dp[v] = result;
    };

    // Children have larger indices, so process in decreasing index order.
    for (int v = N; v >= 1; --v) {
        pull(v);
    }

    auto changeState = [&](int v, int newState) {
        if (state[v] == newState) return;

        state[v] = newState;
        for (int s = 0; s < 3; ++s) {
            weight[v][s] = (s == newState ? 0LL : cost[v]);
        }

        // Recompute this node and its ancestors.
        for (int x = v; x > 0; x /= 2) {
            Arr old = dp[x];
            pull(x);

            // If this subtree's DP did not change, no ancestor can change.
            if (dp[x] == old) break;
        }
    };

    vector<ll> answer(Q);
    int ptr = 0;
    int previousTarget = -1;

    for (auto [m, id] : queries) {
        // Avoid repeatedly scanning a large group for duplicate queries.
        if (m != previousTarget) {
            // Original values strictly below m are now LESS.
            while (ptr < N && a[order[ptr]] < m) {
                changeState(order[ptr], 0);
                ++ptr;
            }

            // Original values equal to m are EQUAL.
            if (ptr < N && a[order[ptr]] == m) {
                int j = ptr;
                while (j < N && a[order[j]] == m) {
                    changeState(order[j], 1);
                    ++j;
                }
            }

            previousTarget = m;
        }

        answer[id] = dp[1][1];
    }

    string output;
    output.reserve(static_cast<size_t>(Q) * 17);
    for (ll x : answer) {
        output += to_string(x);
        output.push_back('\n');
    }
    cout << output;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Group {
    int value;
    int begin, end;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    vector<int64> c(N + 1);

    for (int i = 1; i <= N; ++i) {
        cin >> a[i] >> c[i];
    }

    int Q;
    cin >> Q;

    vector<pair<int, int>> queries(Q);
    for (int i = 0; i < Q; ++i) {
        int m;
        cin >> m;
        queries[i] = {m, i};
    }
    sort(queries.begin(), queries.end());

    vector<int> order(N);
    iota(order.begin(), order.end(), 1);
    sort(order.begin(), order.end(), [&](int x, int y) {
        return a[x] < a[y];
    });

    vector<Group> groups;
    for (int left = 0; left < N; ) {
        int right = left + 1;
        while (right < N && a[order[right]] == a[order[left]]) {
            ++right;
        }
        groups.push_back({a[order[left]], left, right});
        left = right;
    }

    // Local classifications:
    // 0 = ABOVE, 1 = EQUAL, 2 = BELOW.
    constexpr int ABOVE = 0;
    constexpr int EQUAL = 1;
    constexpr int BELOW = 2;

    // own[v][0/1/2] is the cost to make a_v below/equal/above m.
    vector<array<int64, 3>> own(N + 1);
    vector<array<int64, 3>> dp(N + 1);
    vector<int> state(N + 1, ABOVE);

    // Initially assume m < every a_i.
    for (int i = 1; i <= N; ++i) {
        own[i] = {c[i], c[i], 0};
    }

    auto pull = [&](int v) -> bool {
        array<int64, 3> next;

        if (2 * v > N) {
            next = own[v];
        } else {
            int left = 2 * v;
            int right = left + 1;

            const auto &x = own[v];
            const auto &L = dp[left];
            const auto &R = dp[right];

            // At least two inputs must be below m.
            next[0] = min(L[0] + R[0],
                           x[0] + min(L[0], R[0]));

            // At least two inputs must be above m.
            next[2] = min(L[2] + R[2],
                           x[2] + min(L[2], R[2]));

            // At least two inputs are equal to m.
            int64 equalCost = min(L[1] + R[1],
                                  x[1] + min(L[1], R[1]));

            // Exactly one equal, one below, and one above.
            equalCost = min(
                equalCost,
                x[1] + min(L[0] + R[2], L[2] + R[0])
            );
            equalCost = min(
                equalCost,
                L[1] + min(x[0] + R[2], x[2] + R[0])
            );
            equalCost = min(
                equalCost,
                R[1] + min(x[0] + L[2], x[2] + L[0])
            );

            next[1] = equalCost;
        }

        if (next == dp[v]) {
            return false;
        }
        dp[v] = next;
        return true;
    };

    // Children have larger indices, so initialize bottom-up.
    for (int v = N; v >= 1; --v) {
        pull(v);
    }

    auto changeState = [&](int v, int newState) {
        if (state[v] == newState) {
            return;
        }

        state[v] = newState;

        if (newState == ABOVE) {
            own[v] = {c[v], c[v], 0};
        } else if (newState == EQUAL) {
            own[v] = {c[v], 0, c[v]};
        } else {
            own[v] = {0, c[v], c[v]};
        }

        // Only this node and its ancestors can be affected.
        for (int u = v; u > 0; u /= 2) {
            if (!pull(u)) {
                break;
            }
        }
    };

    vector<int64> answer(Q);

    int groupIndex = 0;
    int lastTarget = -1;

    for (auto [m, queryIndex] : queries) {
        if (m != lastTarget) {
            // All a_i < m are now below the target.
            while (groupIndex < (int)groups.size() &&
                   groups[groupIndex].value < m) {
                const Group &g = groups[groupIndex++];
                for (int k = g.begin; k < g.end; ++k) {
                    changeState(order[k], BELOW);
                }
            }

            // All a_i = m are exactly equal to the target.
            if (groupIndex < (int)groups.size() &&
                groups[groupIndex].value == m) {
                const Group &g = groups[groupIndex];
                for (int k = g.begin; k < g.end; ++k) {
                    changeState(order[k], EQUAL);
                }
            }

            lastTarget = m;
        }

        answer[queryIndex] = dp[1][1];
    }

    for (int64 result : answer) {
        cout << result << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, sz;
    vector<int> terminals;

    explicit DSU(int n) : parent(n + 1), sz(n + 1, 1), terminals(n + 1, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    string s;
    cin >> s;

    vector<pair<int, int>> edges(M);
    vector<vector<int>> adj(N + 1);

    for (auto &[u, v] : edges) {
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    DSU dsu(N);
    vector<char> active(N + 1, false);

    // Nodes labeled 1 act as connector nodes until their own reverse timestep.
    for (int i = 1; i <= N; ++i) {
        if (s[i - 1] == '1') active[i] = true;
    }

    long long reachablePairs = 0;

    auto unite = [&](int a, int b) {
        a = dsu.find(a);
        b = dsu.find(b);
        if (a == b) return;

        if (dsu.sz[a] < dsu.sz[b]) swap(a, b);

        reachablePairs += 1LL * dsu.terminals[a] * dsu.terminals[b];
        dsu.parent[b] = a;
        dsu.sz[a] += dsu.sz[b];
        dsu.terminals[a] += dsu.terminals[b];
    };

    for (const auto &[u, v] : edges) {
        if (active[u] && active[v]) unite(u, v);
    }

    vector<long long> answer(N + 1);

    // Reverse the process. A terminal of weight 1 is a node still present;
    // connector nodes have weight 0 and do not contribute to the answer.
    for (int t = N; t >= 1; --t) {
        if (s[t - 1] == '1') {
            int r = dsu.find(t);
            reachablePairs += dsu.terminals[r];
            ++dsu.terminals[r];
        } else {
            active[t] = true;
            dsu.terminals[t] = 1;

            for (int v : adj[t]) {
                if (active[v]) unite(t, v);
            }
        }

        answer[t] = reachablePairs;
    }

    for (int t = 1; t <= N; ++t) {
        cout << answer[t] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, sz;
    vector<long long> active;
    long long pairs = 0;

    explicit DSU(int n) : parent(n + 1), sz(n + 1, 1), active(n + 1, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;

        pairs += active[a] * active[b];
        if (sz[a] < sz[b]) swap(a, b);

        parent[b] = a;
        sz[a] += sz[b];
        active[a] += active[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    string s;
    cin >> s;

    vector<pair<int, int>> edges;
    edges.reserve(M);
    vector<vector<int>> adj(N + 1);

    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        edges.push_back({a, b});
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    DSU dsu(N);
    vector<char> present(N + 1, false);

    // Every node with s_i = 1 is present throughout the reverse process,
    // initially only as a zero-weight connector.
    for (int i = 1; i <= N; ++i) {
        if (s[i - 1] == '1') present[i] = true;
    }

    for (auto [a, b] : edges) {
        if (s[a - 1] == '1' && s[b - 1] == '1') {
            dsu.unite(a, b);
        }
    }

    vector<long long> answer(N + 1);

    for (int t = N; t >= 1; --t) {
        if (s[t - 1] == '1') {
            int r = dsu.find(t);
            dsu.pairs += dsu.active[r];
            ++dsu.active[r];
        } else {
            present[t] = true;
            dsu.active[t] = 1;

            for (int u : adj[t]) {
                if (present[u]) dsu.unite(t, u);
            }
        }
        answer[t] = dsu.pairs;
    }

    for (int t = 1; t <= N; ++t) {
        cout << answer[t] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, sz, counted;
    long long pairs = 0;

    explicit DSU(int n)
        : parent(n + 1), sz(n + 1, 1), counted(n + 1, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;

        pairs += 1LL * counted[a] * counted[b];

        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
        counted[a] += counted[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    string s;
    cin >> s;

    vector<pair<int, int>> edges(M);
    vector<vector<int>> adj(N + 1);

    for (auto &[u, v] : edges) {
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    DSU dsu(N);
    vector<char> active(N + 1, false);

    // In the reverse process, every node with s_i = 1 is always present.
    // Initially none of them is counted as an unprocessed node.
    for (int i = 1; i <= N; ++i) {
        if (s[i - 1] == '1') active[i] = true;
    }

    for (auto [u, v] : edges) {
        if (active[u] && active[v]) {
            dsu.unite(u, v);
        }
    }

    vector<long long> answer(N + 1);

    for (int t = N; t >= 1; --t) {
        if (s[t - 1] == '1') {
            // Node t changes from a connector to a counted node.
            int root = dsu.find(t);
            dsu.pairs += dsu.counted[root];
            ++dsu.counted[root];
        } else {
            // Reinsert node t and all edges to currently present nodes.
            active[t] = true;
            dsu.parent[t] = t;
            dsu.sz[t] = 1;
            dsu.counted[t] = 1;

            for (int v : adj[t]) {
                if (active[v]) {
                    dsu.unite(t, v);
                }
            }
        }

        answer[t] = dsu.pairs;
    }

    for (int t = 1; t <= N; ++t) {
        cout << answer[t] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int THRESH = 20;

struct Hyper {
    vector<int> mem;
    vector<int> st;
    int active_size;
    bool active;
    bool large;
};

struct Change {
    int type;       // 0 = union, 1 = activate
    int a, b;
    int old_cnt;
    int old_sz;
    long long delta;
};

int N, M, S;
vector<vector<pair<int, int>>> seg;
vector<int> parent, cnt, sz;
vector<Change> history;
long long total_pairs = 0;
vector<long long> ans;

inline void add_interval(int l, int r, int a, int b) {
    if (l > r) return;
    if (l < 1) l = 1;
    if (r > N) r = N;
    if (l > r) return;
    l--; r--;
    l += S; r += S;
    while (l <= r) {
        if (l & 1) seg[l++].push_back({a, b});
        if (!(r & 1)) seg[r--].push_back({a, b});
        l >>= 1;
        r >>= 1;
    }
}

int find_set(int x) {
    while (parent[x] != x) x = parent[x];
    return x;
}

void unite(int a, int b) {
    int ra = find_set(a), rb = find_set(b);
    if (ra == rb) return;
    if (sz[ra] < sz[rb]) swap(ra, rb);

    Change c;
    c.type = 0;
    c.a = ra;
    c.b = rb;
    c.old_cnt = cnt[ra];
    c.old_sz = sz[ra];
    c.delta = 1LL * cnt[ra] * cnt[rb];
    history.push_back(c);

    total_pairs += c.delta;
    parent[rb] = ra;
    cnt[ra] += cnt[rb];
    sz[ra] += sz[rb];
}

void activate(int v) {
    int r = find_set(v);
    Change c;
    c.type = 1;
    c.a = r;
    c.b = 0;
    c.old_cnt = cnt[r];
    c.old_sz = 0;
    c.delta = cnt[r];
    history.push_back(c);

    total_pairs += c.delta;
    cnt[r]++;
}

void rollback(int cp) {
    while ((int)history.size() > cp) {
        Change c = history.back();
        history.pop_back();
        if (c.type == 0) {
            int ra = c.a, rb = c.b;
            parent[rb] = rb;
            cnt[ra] = c.old_cnt;
            sz[ra] = c.old_sz;
            total_pairs -= c.delta;
        } else {
            int r = c.a;
            cnt[r] = c.old_cnt;
            total_pairs -= c.delta;
        }
    }
}

void dfs(int node, int L, int R) {
    int cp = history.size();

    for (auto &e : seg[node]) {
        if (e.second == 0) activate(e.first);
        else unite(e.first, e.second);
    }

    if (L == R) {
        if (L < N) ans[L + 1] = total_pairs;
    } else {
        int mid = (L + R) >> 1;
        dfs(node << 1, L, mid);
        dfs(node << 1 | 1, mid + 1, R);
    }

    rollback(cp);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M;
    string s;
    cin >> s;

    S = 1;
    while (S < N) S <<= 1;
    seg.resize(S << 1);

    vector<vector<int>> adj(N + 1);

    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
        add_interval(1, min(u, v), u, v);
    }

    // Vertex activation intervals: vertex v is active for times 1..v
    for (int v = 1; v <= N; ++v) {
        add_interval(1, v, v, 0);
    }

    vector<Hyper> hs;
    hs.reserve(N + 5);

    vector<vector<pair<int, int>>> incident(N + 1);
    vector<int> visH(N + 5, 0), seenTemp(N + 1, 0);
    unordered_set<long long> largeSet;
    largeSet.reserve(100000);

    auto key = [](int h, int v) -> long long {
        return ((long long)h << 20) | v;
    };

    auto contains = [&](int h, int v) -> bool {
        Hyper &H = hs[h];
        if (H.large) {
            return largeSet.find(key(h, v)) != largeSet.end();
        }
        for (int u : H.mem) {
            if (u == v) return true;
        }
        return false;
    };

    auto add_member = [&](int h, int v, int start) {
        if (contains(h, v)) return;
        Hyper &H = hs[h];
        H.mem.push_back(v);
        H.st.push_back(start);
        H.active_size++;
        incident[v].push_back({h, start});

        if (H.large) {
            largeSet.insert(key(h, v));
        } else if ((int)H.mem.size() > THRESH) {
            H.large = true;
            for (int u : H.mem) largeSet.insert(key(h, u));
        }
    };

    auto destroy = [&](int h) {
        Hyper &H = hs[h];
        if (!H.active) return;
        H.active = false;
        if (H.large) {
            for (int v : H.mem) largeSet.erase(key(h, v));
            H.large = false;
        }
        vector<int>().swap(H.mem);
        vector<int>().swap(H.st);
        H.active_size = 0;
    };

    vector<int> inc;
    for (int t = 1; t <= N; ++t) {
        inc.clear();

        for (auto &pr : incident[t]) {
            int h = pr.first;
            if (h >= (int)hs.size()) continue;
            if (!hs[h].active) continue;

            int start = pr.second;
            add_interval(start, t, N + h + 1, t);
            hs[h].active_size--;

            if (visH[h] != t) {
                visH[h] = t;
                inc.push_back(h);
            }
        }

        if (s[t - 1] == '0') {
            for (int h : inc) {
                if (hs[h].active && hs[h].active_size == 0) {
                    destroy(h);
                }
            }
        } else {
            int base = -1, maxsz = -1;
            for (int h : inc) {
                if (hs[h].active_size > maxsz) {
                    maxsz = hs[h].active_size;
                    base = h;
                }
            }

            for (int h : inc) {
                if (h == base) continue;

                Hyper &H = hs[h];
                for (size_t i = 0; i < H.mem.size(); ++i) {
                    int u = H.mem[i];
                    if (u <= t) continue;

                    add_interval(H.st[i], t, N + h + 1, u);
                    add_member(base, u, t + 1);
                }
                destroy(h);
            }

            if (base != -1) {
                for (int v : adj[t]) {
                    if (v > t) add_member(base, v, t + 1);
                }
                if (hs[base].active && hs[base].active_size == 0) {
                    destroy(base);
                }
            } else {
                vector<int> newMem;
                for (int v : adj[t]) {
                    if (v > t && seenTemp[v] != t) {
                        seenTemp[v] = t;
                        newMem.push_back(v);
                    }
                }

                if ((int)newMem.size() >= 2) {
                    int h = hs.size();
                    hs.push_back({{}, {}, 0, true, false});
                    for (int v : newMem) {
                        add_member(h, v, t + 1);
                    }
                }
            }
        }
    }

    int totalNodes = N + hs.size() + 5;
    parent.resize(totalNodes + 1);
    cnt.assign(totalNodes + 1, 0);
    sz.assign(totalNodes + 1, 1);

    for (int i = 1; i <= totalNodes; ++i) parent[i] = i;

    ans.assign(N + 1, 0);
    history.reserve(1000000);

    // Free memory no longer needed
    vector<vector<int>>().swap(adj);
    vector<vector<pair<int, int>>>().swap(incident);
    vector<Hyper>().swap(hs);
    unordered_set<long long>().swap(largeSet);

    dfs(1, 0, S - 1);

    for (int i = 1; i <= N; ++i) {
        cout << ans[i] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    vector<long long> sz; // number of active vertices in component
    long long pairs;
    DSU(int n) : parent(n), sz(n, 0), pairs(0) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }
    void add_vertex(int x) {
        int r = find(x);
        pairs -= sz[r] * (sz[r] - 1) / 2;
        sz[r] += 1;
        pairs += sz[r] * (sz[r] - 1) / 2;
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        pairs -= sz[a] * (sz[a] - 1) / 2;
        pairs -= sz[b] * (sz[b] - 1) / 2;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
        pairs += sz[a] * (sz[a] - 1) / 2;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    string s;
    cin >> s;
    vector<vector<int>> adj(N);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<char> active_vertex(N, 1);
    vector<unordered_set<int>> active_members;
    vector<unordered_set<int>> hist;
    vector<char> alive;
    vector<vector<int>> inc_active(N);

    auto get_new_id = [&]() {
        int id = active_members.size();
        active_members.emplace_back();
        hist.emplace_back();
        alive.push_back(1);
        return id;
    };

    for (int t = 0; t < N; ++t) {
        if (s[t] == '0') {
            for (int id : inc_active[t]) {
                if (alive[id]) {
                    active_members[id].erase(t);
                    if (active_members[id].size() < 2) {
                        alive[id] = 0;
                    }
                }
            }
            active_vertex[t] = 0;
        } else {
            vector<int> H;
            for (int id : inc_active[t]) {
                if (alive[id] && active_members[id].count(t)) {
                    H.push_back(id);
                }
            }
            sort(H.begin(), H.end());
            H.erase(unique(H.begin(), H.end()), H.end());

            int base = -1;
            if (!H.empty()) {
                for (int id : H) {
                    if (base == -1 || active_members[id].size() > active_members[base].size()) {
                        base = id;
                    }
                }
                for (int id : H) {
                    if (id == base) continue;
                    // merge hist
                    if (hist[id].size() > hist[base].size()) {
                        hist[base].swap(hist[id]);
                    }
                    for (int v : hist[id]) {
                        hist[base].insert(v);
                    }
                    // merge active
                    for (int v : active_members[id]) {
                        if (v == t) continue;
                        if (active_members[base].insert(v).second) {
                            inc_active[v].push_back(base);
                            hist[base].insert(v);
                        }
                    }
                    alive[id] = 0;
                    active_members[id].clear();
                    hist[id].clear();
                }
                // remove t from base active
                active_members[base].erase(t);
                // add active original neighbors
                for (int v : adj[t]) {
                    if (active_vertex[v] && v != t) {
                        if (active_members[base].insert(v).second) {
                            inc_active[v].push_back(base);
                            hist[base].insert(v);
                        }
                    }
                }
                if (active_members[base].size() < 2) {
                    alive[base] = 0;
                }
            } else {
                unordered_set<int> C;
                for (int v : adj[t]) {
                    if (active_vertex[v] && v != t) {
                        C.insert(v);
                    }
                }
                if (C.size() >= 2) {
                    int id = get_new_id();
                    active_members[id] = std::move(C);
                    for (int v : active_members[id]) {
                        inc_active[v].push_back(id);
                        hist[id].insert(v);
                    }
                }
            }
            active_vertex[t] = 0;
        }
    }

    int num_ids = active_members.size();
    vector<vector<int>> inc_hist(N);
    for (int id = 0; id < num_ids; ++id) {
        if (hist[id].size() < 2) continue;
        for (int v : hist[id]) {
            inc_hist[v].push_back(N + id);
        }
    }

    int total_nodes = N + num_ids;
    DSU dsu(total_nodes);
    vector<long long> ans(N);
    vector<char> active_rev(N, 0);

    for (int v = N - 1; v >= 0; --v) {
        active_rev[v] = 1;
        dsu.add_vertex(v);
        for (int u : adj[v]) {
            if (u > v) {
                dsu.unite(v, u);
            }
        }
        for (int hub : inc_hist[v]) {
            dsu.unite(v, hub);
        }
        ans[v] = dsu.pairs;
    }

    for (int i = 0; i < N; ++i) {
        cout << ans[i] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, cnt;
    long long total = 0;

    DSU(int n) : parent(n + 1), cnt(n + 1, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    long long C2(long long x) {
        return x * (x - 1) / 2;
    }

    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    void increment(int x) {
        int r = find(x);
        total -= C2(cnt[r]);
        cnt[r]++;
        total += C2(cnt[r]);
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;

        total -= C2(cnt[a]);
        total -= C2(cnt[b]);

        if (cnt[a] < cnt[b]) swap(a, b);
        parent[b] = a;
        cnt[a] += cnt[b];

        total += C2(cnt[a]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    string s;
    cin >> s;

    vector<vector<int>> adj(N + 1);
    vector<pair<int, int>> edges;
    edges.reserve(M);

    for (int i = 0; i < M; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
        edges.push_back({u, v});
    }

    DSU dsu(N);

    vector<char> active(N + 1, false);

    for (int i = 1; i <= N; i++) {
        if (s[i - 1] == '1') {
            active[i] = true;
        }
    }

    // Initially, after all removals, all type-1 vertices remain as connectors.
    for (auto [u, v] : edges) {
        if (s[u - 1] == '1' && s[v - 1] == '1') {
            dsu.unite(u, v);
        }
    }

    vector<long long> ans(N + 1);

    for (int t = N; t >= 1; t--) {
        if (s[t - 1] == '0') {
            active[t] = true;
        }

        dsu.increment(t);

        if (s[t - 1] == '0') {
            for (int v : adj[t]) {
                if (active[v]) {
                    dsu.unite(t, v);
                }
            }
        }

        ans[t] = dsu.total;
    }

    for (int t = 1; t <= N; t++) {
        cout << ans[t] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, sz, activeCount;
    long long pairCount = 0;

    explicit DSU(int n)
        : parent(n), sz(n, 1), activeCount(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);

        if (a == b) return;

        pairCount += 1LL * activeCount[a] * activeCount[b];

        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
        activeCount[a] += activeCount[b];
    }

    void activate(int x) {
        int root = find(x);
        pairCount += activeCount[root];
        ++activeCount[root];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    string s;
    cin >> s;

    vector<vector<int>> adj(N);
    vector<char> included(N, false);

    // All '1' vertices exist from the beginning as zero-weight connectors.
    for (int i = 0; i < N; ++i) {
        included[i] = (s[i] == '1');
    }

    DSU dsu(N);

    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;

        adj[u].push_back(v);
        adj[v].push_back(u);

        // Edges between two initially included vertices are immediately present.
        if (included[u] && included[v]) {
            dsu.unite(u, v);
        }
    }

    vector<long long> answer(N);

    for (int t = N - 1; t >= 0; --t) {
        if (s[t] == '0') {
            // Restore this deleted vertex and all edges to included vertices.
            included[t] = true;

            for (int v : adj[t]) {
                if (included[v]) {
                    dsu.unite(t, v);
                }
            }
        }

        // Vertex t is now one of the remaining vertices and is counted.
        dsu.activate(t);
        answer[t] = dsu.pairCount;
    }

    for (long long value : answer) {
        cout << value << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, sz;
    vector<long long> liveCount;
    long long totalPairs = 0;

    explicit DSU(int n)
        : parent(n), sz(n, 1), liveCount(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;

        if (sz[a] < sz[b]) swap(a, b);

        // Every live vertex in one component can now reach every
        // live vertex in the other component.
        totalPairs += liveCount[a] * liveCount[b];

        parent[b] = a;
        sz[a] += sz[b];
        liveCount[a] += liveCount[b];
    }

    void activate(int x) {
        int root = find(x);

        // The new live vertex forms a pair with every existing
        // live vertex in its component.
        totalPairs += liveCount[root];
        ++liveCount[root];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    string s;
    cin >> s;

    vector<vector<int>> adj(N);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    DSU dsu(N);

    // "present" refers to membership in the auxiliary graph.
    // A present vertex is not necessarily live: removed type-1
    // vertices remain as uncounted connectors.
    vector<char> present(N, false);
    for (int v = 0; v < N; ++v) {
        if (s[v] == '1') present[v] = true;
    }

    // Type-1 vertices are always structurally present.
    // Initially, unite all edges between them.
    for (int u = 0; u < N; ++u) {
        if (!present[u]) continue;
        for (int v : adj[u]) {
            if (present[v] && u < v) {
                dsu.unite(u, v);
            }
        }
    }

    vector<long long> answer(N);

    // Reverse time. At time t, the live vertices are exactly t, ..., N.
    for (int t = N - 1; t >= 0; --t) {
        if (s[t] == '0') {
            // A type-0 vertex is genuinely deleted, so in reverse time
            // it is inserted into the auxiliary graph.
            present[t] = true;
            dsu.activate(t);

            for (int v : adj[t]) {
                if (present[v]) {
                    dsu.unite(t, v);
                }
            }
        } else {
            // A type-1 vertex was already structurally present.
            // It only becomes live now.
            dsu.activate(t);
        }

        answer[t] = dsu.totalPairs;
    }

    for (long long value : answer) {
        cout << value << '\n';
    }

    return 0;
}

