int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    vector<long long> c(N + 1);

    for (int i = 1; i <= N; i++) cin >> a[i];

    long long totalCost = 0;
    for (int i = 1; i <= N; i++) {
        cin >> c[i];
        totalCost += c[i];
    }

    vector<int> indeg(N + 1, 0);
    for (int i = 1; i <= N; i++) {
        indeg[a[i]]++;
    }

    vector<long long> sum0(N + 1, 0), sum1(N + 1, 0);
    vector<long long> dp0(N + 1, 0), dp1(N + 1, 0);

    queue<int> q;
    for (int i = 1; i <= N; i++) {
        if (indeg[i] == 0) q.push(i);
    }

    while (!q.empty()) {
        int v = q.front();
        q.pop();

        dp0[v] = sum0[v];
        dp1[v] = sum1[v];

        int p = a[v];

        sum0[p] += max(dp0[v], dp1[v]);
        sum1[p] += max(dp0[v] + c[v], dp1[v]);

        indeg[p]--;
        if (indeg[p] == 0) q.push(p);
    }

    for (int v = 1; v <= N; v++) {
        if (indeg[v] > 0) {
            dp0[v] = sum0[v];
            dp1[v] = sum1[v];
            if (a[v] == v) {
                dp1[v] += c[v];
            }
        }
    }

    vector<char> visited(N + 1, 0);
    long long saved = 0;
    const long long NEG = -(1LL << 60);

    for (int i = 1; i <= N; i++) {
        if (indeg[i] > 0 && !visited[i]) {
            vector<int> cycle;
            int v = i;

            while (!visited[v]) {
                visited[v] = 1;
                cycle.push_back(v);
                v = a[v];
            }

            int k = (int)cycle.size();

            if (k == 1) {
                int u = cycle[0];
                saved += dp1[u];
            } else {
                long long best = NEG;

                for (int first = 0; first <= 1; first++) {
                    long long prev[2] = {NEG, NEG};

                    int u0 = cycle[0];
                    prev[first] = (first == 0 ? dp0[u0] : dp1[u0]);

                    for (int idx = 1; idx < k; idx++) {
                        int pv = cycle[idx - 1];
                        int cv = cycle[idx];

                        long long cur[2];

                        cur[0] = max(prev[0], prev[1]) + dp0[cv];

                        cur[1] = max(prev[0] + c[pv], prev[1]) + dp1[cv];

                        prev[0] = cur[0];
                        prev[1] = cur[1];
                    }

                    int last = cycle[k - 1];

                    for (int lastState = 0; lastState <= 1; lastState++) {
                        long long val = prev[lastState];

                        if (lastState == 0 && first == 1) {
                            val += c[last];
                        }

                        best = max(best, val);
                    }
                }

                saved += best;
            }
        }
    }

    cout << totalCost - saved << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    vector<long long> c(N + 1);
    vector<int> indeg(N + 1, 0);

    for (int i = 1; i <= N; i++) {
        cin >> a[i];
        indeg[a[i]]++;
    }

    long long totalCost = 0;
    for (int i = 1; i <= N; i++) {
        cin >> c[i];
        totalCost += c[i];
    }

    queue<int> q;
    for (int i = 1; i <= N; i++) {
        if (indeg[i] == 0) q.push(i);
    }

    vector<char> onCycle(N + 1, 1);
    vector<int> order;
    order.reserve(N);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        onCycle[u] = 0;
        order.push_back(u);

        int v = a[u];
        if (--indeg[v] == 0) {
            q.push(v);
        }
    }

    vector<vector<int>> rev(N + 1);
    for (int i = 1; i <= N; i++) {
        rev[a[i]].push_back(i);
    }

    vector<long long> dp0(N + 1), dp1(N + 1);

    for (int u : order) {
        long long s0 = 0, s1 = 0;

        for (int v : rev[u]) {
            s0 += max(dp0[v], dp1[v]);
            s1 += max(dp0[v] + c[v], dp1[v]);
        }

        dp0[u] = s0;
        dp1[u] = s1;
    }

    vector<long long> base0(N + 1), base1(N + 1);
    vector<char> visitedCycle(N + 1, 0);
    vector<int> cyc;

    long long maxSavings = 0;
    const long long NEG = -(1LL << 60);

    for (int start = 1; start <= N; start++) {
        if (!onCycle[start] || visitedCycle[start]) continue;

        cyc.clear();
        int u = start;

        while (!visitedCycle[u]) {
            visitedCycle[u] = 1;
            cyc.push_back(u);
            u = a[u];
        }

        int L = (int)cyc.size();

        for (int id : cyc) {
            long long s0 = 0, s1 = 0;

            for (int v : rev[id]) {
                if (!onCycle[v]) {
                    s0 += max(dp0[v], dp1[v]);
                    s1 += max(dp0[v] + c[v], dp1[v]);
                }
            }

            base0[id] = s0;
            base1[id] = s1;
        }

        if (L == 1) {
            int id = cyc[0];
            long long val0 = base0[id];
            long long val1 = base1[id] + c[id];
            maxSavings += max(val0, val1);
        } else {
            long long best = NEG;

            for (int first = 0; first < 2; first++) {
                long long cur[2] = {NEG, NEG};
                cur[first] = (first == 0 ? base0[cyc[0]] : base1[cyc[0]]);

                for (int k = 1; k < L; k++) {
                    long long nxt[2] = {NEG, NEG};

                    int prevId = cyc[k - 1];
                    int currId = cyc[k];

                    for (int prev = 0; prev < 2; prev++) {
                        if (cur[prev] <= NEG / 2) continue;

                        for (int curr = 0; curr < 2; curr++) {
                            long long val = cur[prev] +
                                (curr == 0 ? base0[currId] : base1[currId]);

                            if (prev == 0 && curr == 1) {
                                val += c[prevId];
                            }

                            nxt[curr] = max(nxt[curr], val);
                        }
                    }

                    cur[0] = nxt[0];
                    cur[1] = nxt[1];
                }

                int lastId = cyc[L - 1];

                for (int last = 0; last < 2; last++) {
                    if (cur[last] <= NEG / 2) continue;

                    long long val = cur[last];

                    if (last == 0 && first == 1) {
                        val += c[lastId];
                    }

                    best = max(best, val);
                }
            }

            maxSavings += best;
        }
    }

    cout << totalCost - maxSavings << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 INF = (1LL << 62);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1), indegree(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        ++indegree[a[i]];
    }

    vector<int64> c(N + 1);
    for (int i = 1; i <= N; ++i) {
        cin >> c[i];
    }

    // down0[v]: contribution of v's off-cycle descendants when v is not fixed.
    // down1[v]: contribution of v's off-cycle descendants when v is fixed.
    // The cost of editing v itself is not included.
    vector<int64> down0(N + 1, 0), down1(N + 1, 0);

    queue<int> q;
    for (int i = 1; i <= N; ++i) {
        if (indegree[i] == 0) {
            q.push(i);
        }
    }

    // Remove all non-cycle vertices, processing children before parents.
    while (!q.empty()) {
        int x = q.front();
        q.pop();

        // A removed vertex cannot be a self-loop.
        //
        // If the parent is not fixed:
        //   x fixed:     c[x] + down1[x]
        //   x not fixed: c[x] + down0[x]
        //
        // If the parent is fixed:
        //   x fixed:     c[x] + down1[x]
        //   x not fixed: down0[x]
        int64 whenParentNotFixed =
            c[x] + min(down0[x], down1[x]);
        int64 whenParentFixed =
            min(down0[x], c[x] + down1[x]);

        int p = a[x];
        down0[p] += whenParentNotFixed;
        down1[p] += whenParentFixed;

        if (--indegree[p] == 0) {
            q.push(p);
        }
    }

    vector<char> visited(N + 1, false);
    int64 answer = 0;

    for (int start = 1; start <= N; ++start) {
        if (indegree[start] == 0 || visited[start]) {
            continue;
        }

        vector<int> cycle;
        int v = start;
        do {
            visited[v] = true;
            cycle.push_back(v);
            v = a[v];
        } while (v != start);

        int k = static_cast<int>(cycle.size());

        if (k == 1) {
            // This vertex is already a fixed point.
            answer += down1[cycle[0]];
            continue;
        }

        int64 best = INF;

        // Fix the state of cycle[0], then run a two-state DP around the cycle.
        for (int firstState = 0; firstState <= 1; ++firstState) {
            array<int64, 2> dp = {INF, INF};
            dp[firstState] = (firstState == 1)
                                 ? down1[cycle[0]]
                                 : down0[cycle[0]];

            for (int i = 0; i + 1 < k; ++i) {
                array<int64, 2> nextDP = {INF, INF};
                int u = cycle[i];
                int w = cycle[i + 1];

                for (int currentState = 0; currentState <= 1; ++currentState) {
                    if (dp[currentState] == INF) {
                        continue;
                    }

                    for (int nextState = 0; nextState <= 1; ++nextState) {
                        // u's parent is w.
                        // If u is not fixed and its parent is fixed, u can
                        // remain unchanged. Otherwise u must be edited.
                        int64 localCost =
                            (currentState == 1 || nextState == 0) ? c[u] : 0LL;

                        int64 treeCost = (nextState == 1)
                                             ? down1[w]
                                             : down0[w];

                        nextDP[nextState] = min(
                            nextDP[nextState],
                            dp[currentState] + localCost + treeCost
                        );
                    }
                }

                dp = nextDP;
            }

            // Close the cycle: the parent of the last vertex is cycle[0].
            for (int lastState = 0; lastState <= 1; ++lastState) {
                if (dp[lastState] == INF) {
                    continue;
                }

                int64 localCost =
                    (lastState == 1 || firstState == 0)
                        ? c[cycle.back()]
                        : 0LL;

                best = min(best, dp[lastState] + localCost);
            }
        }

        answer += best;
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    if (!(cin >> N)) return 0;
    vector<int> a(N);
    for (int i = 0; i < N; ++i) { cin >> a[i]; --a[i]; }
    vector<long long> c(N);
    for (int i = 0; i < N; ++i) cin >> c[i];

    // deg[v] = number of children (nodes pointing to v), self-loop included
    vector<int> deg(N, 0);
    for (int i = 0; i < N; ++i) ++deg[a[i]];

    vector<long long> sumFix(N, 0), sumNotFix(N, 0); // children contributions
    vector<long long> P(N, 0), Q(N, 0);

    // peel leaves -> process trees bottom-up, cycle nodes survive
    queue<int> q;
    for (int i = 0; i < N; ++i) if (deg[i] == 0) q.push(i);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        long long wfix = (a[v] == v ? 0LL : c[v]);
        P[v] = wfix + sumFix[v];      // v fixed
        Q[v] = sumNotFix[v];          // v not fixed (own cost handled by parent)
        int p = a[v];
        sumFix[p]    += min(P[v], Q[v]);            // parent fixed
        sumNotFix[p] += min(P[v], c[v] + Q[v]);      // parent not fixed
        if (--deg[p] == 0) q.push(p);
    }

    vector<char> inCycle(N, 0);
    for (int i = 0; i < N; ++i) if (deg[i] > 0) inCycle[i] = 1;

    const long long INF = (1LL << 62);
    long long answer = 0;
    vector<char> vis(N, 0);

    for (int st = 0; st < N; ++st) {
        if (!inCycle[st] || vis[st]) continue;
        vector<int> cyc;
        int v = st;
        do { cyc.push_back(v); vis[v] = 1; v = a[v]; } while (v != st);
        int k = (int)cyc.size();

        long long best = INF;
        for (int start = 0; start < 2; ++start) {   // status of cyc[0]
            long long dp[2] = {INF, INF};
            dp[start] = 0;
            for (int i = 0; i + 1 < k; ++i) {
                int u = cyc[i];
                long long wfix = (a[u] == u ? 0LL : c[u]);
                long long child[2] = {sumNotFix[u], sumFix[u]}; // by status of u
                long long ndp[2] = {INF, INF};
                for (int s = 0; s < 2; ++s) {
                    if (dp[s] >= INF) continue;
                    for (int t = 0; t < 2; ++t) {   // t = status of parent a[u]
                        long long own = s ? wfix : (t ? 0LL : c[u]);
                        ndp[t] = min(ndp[t], dp[s] + own + child[s]);
                    }
                }
                dp[0] = ndp[0]; dp[1] = ndp[1];
            }
            int last = cyc[k - 1];
            long long wfix = (a[last] == last ? 0LL : c[last]);
            long long child[2] = {sumNotFix[last], sumFix[last]};
            for (int s = 0; s < 2; ++s) {
                if (dp[s] >= INF) continue;
                // parent of cyc[k-1] is cyc[0], whose status is `start`
                long long own = s ? wfix : (start ? 0LL : c[last]);
                best = min(best, dp[s] + own + child[s]);
            }
        }
        answer += best;
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> a(N+1);
    vector<long long> c(N+1);
    for(int i=1;i<=N;i++) cin>>a[i];
    long long total=0;
    for(int i=1;i<=N;i++){ cin>>c[i]; total+=c[i]; }

    vector<int> indeg(N+1,0);
    for(int i=1;i<=N;i++) indeg[a[i]]++;

    const long long NEG = -(1LL<<60);

    // For a tree node v (v is not on a cycle):
    //  X[v] = max savings inside subtree(v) (incl. v) assuming a[v] is NOT a fixed point
    //  Y[v] = max savings inside subtree(v) (incl. v) assuming a[v] IS a fixed point
    // sumX[v]/sumY[v] accumulate children contributions.
    vector<long long> X(N+1,0), Y(N+1,0), sumX(N+1,0), sumY(N+1,0);

    queue<int> q;
    for(int i=1;i<=N;i++) if(indeg[i]==0) q.push(i);

    // Peel off all non-cycle nodes, processing them bottom-up.
    while(!q.empty()){
        int v=q.front(); q.pop();
        X[v] = max(sumY[v], sumX[v]);
        Y[v] = max(sumY[v], sumX[v] + c[v]);
        int p=a[v];
        sumX[p] += X[v];
        sumY[p] += Y[v];
        if(--indeg[p]==0) q.push(p);
    }

    long long bestSavings = 0;
    vector<char> vis(N+1,0);

    for(int i=1;i<=N;i++){
        if(indeg[i]==0 || vis[i]) continue;   // not a cycle node, or already handled

        // Collect the cycle in order: cyc[i] -> cyc[i+1] -> ... -> cyc[0]
        vector<int> cyc;
        int v=i;
        do{ cyc.push_back(v); vis[v]=1; v=a[v]; }while(v!=i);
        int k=(int)cyc.size();

        if(k==1){
            // Self loop: a[u]==u, so u can be a fixed point with zero cost.
            int u=cyc[0];
            bestSavings += max(c[u] + sumY[u], sumX[u]);
        }else{
            long long compBest = NEG;
            for(int s1=0;s1<=1;s1++){
                // dp0/dp1 : best value with current cycle node NOT in S / IN S
                long long dp0 = (s1==0 ? sumX[cyc[0]] : NEG);
                long long dp1 = (s1==1 ? sumY[cyc[0]] : NEG);
                for(int j=1;j<k;j++){
                    int prev=cyc[j-1], cur=cyc[j];
                    long long ndp0 = max(dp0,dp1) + sumX[cur];
                    // prev not fixed but cur fixed  =>  prev keeps a[prev]=cur for free
                    long long ndp1 = max(dp1, dp0 + c[prev]) + sumY[cur];
                    dp0=ndp0; dp1=ndp1;
                }
                long long val;
                if(s1==1) val = max(dp1, dp0 + c[cyc[k-1]]); // wrap-around edge
                else      val = max(dp0, dp1);
                compBest = max(compBest, val);
            }
            bestSavings += compBest;
        }
    }

    cout << total - bestSavings << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

ll modPow(ll a, ll e) {
    ll res = 1;
    while (e > 0) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

struct Run {
    ll start, len;
    int bit;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll N;
    int M, Q;
    cin >> N >> M >> Q;

    map<ll, int> diff;
    for (int i = 0; i < M; i++) {
        ll l, r;
        cin >> l >> r;
        diff[l] ^= 1;
        diff[r + 1] ^= 1;
    }

    vector<Run> runs;
    runs.reserve(diff.size() + 1);

    auto addRun = [&](ll start, ll len, int bit) {
        if (len <= 0) return;
        if (!runs.empty() && runs.back().bit == bit) {
            runs.back().len += len;
        } else {
            runs.push_back({start, len, bit});
        }
    };

    ll pos = 1;
    int curBit = 0;
    for (const auto &[x, delta] : diff) {
        if (x > pos) addRun(pos, x - pos, curBit);
        curBit ^= delta;
        pos = x;
    }
    if (pos <= N) addRun(pos, N - pos + 1, curBit);

    int R = (int)runs.size();
    vector<ll> starts(R);
    vector<ll> zeroPref(R + 1, 0);
    vector<ll> valuePref(R + 1, 0);

    for (int i = 0; i < R; i++) {
        starts[i] = runs[i].start;
        zeroPref[i + 1] = zeroPref[i] +
                          (runs[i].bit == 0 ? runs[i].len : 0);

        ll p = modPow(2, runs[i].len);
        ll add = runs[i].bit ? p - 1 : 0;
        valuePref[i + 1] = (valuePref[i] * p + add) % MOD;
    }

    auto runContaining = [&](ll x) {
        return int(upper_bound(starts.begin(), starts.end(), x) -
                   starts.begin() - 1);
    };

    auto zerosUpTo = [&](ll x) -> ll {
        if (x <= 0) return 0;
        int i = runContaining(x);
        ll result = zeroPref[i];
        if (runs[i].bit == 0) result += x - runs[i].start + 1;
        return result;
    };

    // Value of the binary string consisting of global positions 1..x.
    auto prefixValue = [&](ll x) -> ll {
        if (x <= 0) return 0;
        int i = runContaining(x);
        ll taken = x - runs[i].start + 1;
        if (taken == runs[i].len) return valuePref[i + 1];

        ll p = modPow(2, taken);
        ll result = valuePref[i] * p % MOD;
        if (runs[i].bit) result = (result + p - 1) % MOD;
        return result;
    };

    while (Q--) {
        ll l, r, k;
        cin >> l >> r >> k;

        ll length = r - l + 1;
        ll deletions = length - k;
        ll zerosBefore = zerosUpTo(l - 1);
        ll zeros = zerosUpTo(r) - zerosBefore;

        if (deletions >= zeros) {
            // There are enough ones to make the answer k consecutive ones.
            cout << (modPow(2, k) + MOD - 1) % MOD << '\n';
            continue;
        }

        // Delete the first `deletions` zeros in the query. If p is the
        // position immediately after them, the answer consists of all ones
        // before p, followed by the unchanged suffix s[p..r].
        ll p;
        if (deletions == 0) {
            p = l;
        } else {
            ll target = zerosBefore + deletions;
            int j = int(lower_bound(zeroPref.begin(), zeroPref.end(), target) -
                        zeroPref.begin());
            int i = j - 1;
            ll offset = target - zeroPref[i];
            ll zeroPosition = runs[i].start + offset - 1;
            p = zeroPosition + 1;
        }

        ll suffixLength = r - p + 1;
        ll A = prefixValue(p - 1);
        ll B = prefixValue(r);
        ll suffixPow = modPow(2, suffixLength);
        ll answerPow = modPow(2, k);

        ll product = (A + 1) % MOD * suffixPow % MOD;
        ll answer = (answerPow - product + MOD) % MOD;
        answer = (answer + B) % MOD;

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 1000000007LL;

int64 pow2mod(int64 e) {
    int64 result = 1, base = 2;
    while (e > 0) {
        if (e & 1) result = result * base % MOD;
        base = base * base % MOD;
        e >>= 1;
    }
    return result;
}

struct Run {
    int64 l, r;
    int bit;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 N;
    int M, Q;
    cin >> N >> M >> Q;

    vector<pair<int64, int>> events;
    events.reserve(2 * M + 2);
    events.push_back({1, 0});
    events.push_back({N + 1, 0});

    for (int i = 0; i < M; ++i) {
        int64 l, r;
        cin >> l >> r;
        events.push_back({l, 1});
        events.push_back({r + 1, 1});
    }

    sort(events.begin(), events.end());

    vector<Run> runs;
    int parity = 0;

    for (size_t i = 0; i < events.size();) {
        size_t j = i;
        int64 pos = events[i].first;
        int x = 0;

        while (j < events.size() && events[j].first == pos) {
            x ^= events[j].second;
            ++j;
        }
        parity ^= x;

        if (j < events.size()) {
            int64 nextPos = events[j].first;
            int64 end = min(N, nextPos - 1);
            if (pos <= end) {
                if (!runs.empty() && runs.back().bit == parity &&
                    runs.back().r + 1 == pos) {
                    runs.back().r = end;
                } else {
                    runs.push_back({pos, end, parity});
                }
            }
        }
        i = j;
    }

    int R = (int)runs.size();
    vector<int64> ends(R);
    vector<int64> prefOnes(R + 1, 0), prefZeros(R + 1, 0);
    vector<int64> prefHash(R + 1, 0);

    for (int i = 0; i < R; ++i) {
        ends[i] = runs[i].r;
        int64 len = runs[i].r - runs[i].l + 1;
        int64 p = pow2mod(len);

        prefOnes[i + 1] = prefOnes[i] + (runs[i].bit ? len : 0);
        prefZeros[i + 1] = prefZeros[i] + (runs[i].bit ? 0 : len);

        prefHash[i + 1] = prefHash[i] * p % MOD;
        if (runs[i].bit) {
            prefHash[i + 1] = (prefHash[i + 1] + p - 1) % MOD;
        }
    }

    auto prefixCount = [&](int64 x, int bit) -> int64 {
        if (x <= 0) return 0;
        int idx = (int)(lower_bound(ends.begin(), ends.end(), x) - ends.begin());
        int64 taken = x - runs[idx].l + 1;
        if (bit == 1) {
            return prefOnes[idx] + (runs[idx].bit == 1 ? taken : 0);
        }
        return prefZeros[idx] + (runs[idx].bit == 0 ? taken : 0);
    };

    auto prefixHash = [&](int64 x) -> int64 {
        if (x <= 0) return 0;
        int idx = (int)(lower_bound(ends.begin(), ends.end(), x) - ends.begin());
        int64 taken = x - runs[idx].l + 1;
        int64 fullLen = runs[idx].r - runs[idx].l + 1;

        if (taken == fullLen) return prefHash[idx + 1];

        int64 p = pow2mod(taken);
        int64 value = prefHash[idx] * p % MOD;
        if (runs[idx].bit) value = (value + p - 1) % MOD;
        return value;
    };

    while (Q--) {
        int64 l, r, k;
        cin >> l >> r >> k;

        int64 length = r - l + 1;
        int64 deletions = length - k;
        int64 zerosBefore = prefixCount(l - 1, 0);
        int64 zeros = prefixCount(r, 0) - zerosBefore;

        if (zeros <= deletions) {
            int64 answer = pow2mod(k) - 1;
            if (answer < 0) answer += MOD;
            cout << answer << '\n';
            continue;
        }

        int64 targetRank = zerosBefore + deletions + 1;
        int boundary = (int)(lower_bound(prefZeros.begin(), prefZeros.end(),
                                        targetRank) - prefZeros.begin());
        int idx = boundary - 1;

        int64 offset = targetRank - prefZeros[idx];
        int64 p = runs[idx].l + offset - 1;

        int64 leadingOnes = p - l - deletions;
        int64 suffixLength = r - p + 1;

        int64 suffixPow = pow2mod(suffixLength);
        int64 suffixValue = (prefixHash(r) -
                             prefixHash(p - 1) * suffixPow) % MOD;
        if (suffixValue < 0) suffixValue += MOD;

        int64 leadingPow = pow2mod(leadingOnes);
        int64 answer = ((leadingPow - 1) * suffixPow + suffixValue) % MOD;
        if (answer < 0) answer += MOD;

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modPow(long long a, long long e) {
    long long res = 1;
    while (e > 0) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

struct Run {
    long long l, r;
    int bit;
};

struct Node {
    long long val, pw;
};

Node makeNode(int bit, long long len) {
    long long pw = modPow(2, len);
    return {bit ? pw - 1 : 0, pw};
}

Node combine(const Node &a, const Node &b) {
    return {
        (a.val * b.pw + b.val) % MOD,
        a.pw * b.pw % MOD
    };
}

class ValueTree {
private:
    const vector<Run> &runs;
    int n;
    vector<Node> tree;

    void build(int v, int tl, int tr) {
        if (tl == tr) {
            tree[v] = makeNode(runs[tl].bit, runs[tl].r - runs[tl].l + 1);
            return;
        }
        int tm = (tl + tr) / 2;
        build(v * 2, tl, tm);
        build(v * 2 + 1, tm + 1, tr);
        tree[v] = combine(tree[v * 2], tree[v * 2 + 1]);
    }

    Node query(int v, int tl, int tr, int l, int r) const {
        if (l == tl && r == tr) return tree[v];
        int tm = (tl + tr) / 2;
        if (r <= tm) return query(v * 2, tl, tm, l, r);
        if (l > tm) return query(v * 2 + 1, tm + 1, tr, l, r);
        return combine(
            query(v * 2, tl, tm, l, tm),
            query(v * 2 + 1, tm + 1, tr, tm + 1, r)
        );
    }

public:
    ValueTree(const vector<Run> &runs) : runs(runs), n((int)runs.size()), tree(4 * n) {
        build(1, 0, n - 1);
    }

    Node query(int l, int r) const {
        return query(1, 0, n - 1, l, r);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N;
    int M, Q;
    cin >> N >> M >> Q;

    map<long long, int> events;
    for (int i = 0; i < M; i++) {
        long long l, r;
        cin >> l >> r;
        events[l] ^= 1;
        events[r + 1] ^= 1;
    }

    vector<Run> runs;
    auto addRun = [&](int bit, long long l, long long len) {
        if (len <= 0) return;
        if (!runs.empty() && runs.back().bit == bit) {
            runs.back().r += len;
        } else {
            runs.push_back({l, l + len - 1, bit});
        }
    };

    long long previous = 1;
    int currentBit = 0;
    for (const auto &[position, delta] : events) {
        if (position > previous) {
            addRun(currentBit, previous, position - previous);
        }
        currentBit ^= delta;
        previous = position;
    }
    if (previous <= N) {
        addRun(currentBit, previous, N - previous + 1);
    }

    int R = (int)runs.size();
    vector<long long> starts(R);
    vector<long long> prefixOnes(R + 1, 0), prefixZeros(R + 1, 0);

    for (int i = 0; i < R; i++) {
        starts[i] = runs[i].l;
        long long len = runs[i].r - runs[i].l + 1;
        prefixOnes[i + 1] = prefixOnes[i] + (runs[i].bit ? len : 0);
        prefixZeros[i + 1] = prefixZeros[i] + (runs[i].bit ? 0 : len);
    }

    auto runIndex = [&](long long position) {
        return int(upper_bound(starts.begin(), starts.end(), position) - starts.begin()) - 1;
    };

    auto onesUpTo = [&](long long position) -> long long {
        if (position <= 0) return 0;
        int idx = runIndex(position);
        long long result = prefixOnes[idx];
        if (runs[idx].bit) result += position - runs[idx].l + 1;
        return result;
    };

    ValueTree valueTree(runs);

    auto substringValue = [&](long long l, long long r) -> long long {
        int leftRun = runIndex(l);
        int rightRun = runIndex(r);

        if (leftRun == rightRun) {
            return makeNode(runs[leftRun].bit, r - l + 1).val;
        }

        Node result = makeNode(
            runs[leftRun].bit,
            runs[leftRun].r - l + 1
        );

        if (leftRun + 1 <= rightRun - 1) {
            result = combine(
                result,
                valueTree.query(leftRun + 1, rightRun - 1)
            );
        }

        Node last = makeNode(
            runs[rightRun].bit,
            r - runs[rightRun].l + 1
        );
        result = combine(result, last);
        return result.val;
    };

    while (Q--) {
        long long l, r, k;
        cin >> l >> r >> k;

        long long onesBeforeL = onesUpTo(l - 1);
        long long ones = onesUpTo(r) - onesBeforeL;

        if (ones >= k) {
            cout << (modPow(2, k) - 1) << '\n';
            continue;
        }

        long long length = r - l + 1;
        long long zeroRankInInterval = length - k + 1;
        long long zerosBeforeL = (l - 1) - onesBeforeL;
        long long targetZeroRank = zerosBeforeL + zeroRankInInterval;

        int boundary = int(lower_bound(
            prefixZeros.begin(), prefixZeros.end(), targetZeroRank
        ) - prefixZeros.begin());
        int zeroRun = boundary - 1;

        long long q = runs[zeroRun].l
                    + (targetZeroRank - prefixZeros[zeroRun]) - 1;

        long long leadingOnes = onesUpTo(q - 1) - onesBeforeL;
        long long suffixLength = r - q + 1;
        long long suffixValue = substringValue(q, r);

        long long answer = (modPow(2, leadingOnes) - 1 + MOD) % MOD;
        answer = answer * modPow(2, suffixLength) % MOD;
        answer = (answer + suffixValue) % MOD;

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long res = 1 % MOD;
    a %= MOD;
    while (e > 0) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N;
    int M, Q;
    cin >> N >> M >> Q;

    vector<pair<long long, int>> ev;
    ev.reserve(2 * M);

    for (int i = 0; i < M; i++) {
        long long l, r;
        cin >> l >> r;
        ev.emplace_back(l, 1);
        ev.emplace_back(r + 1, 1);
    }

    sort(ev.begin(), ev.end());

    vector<pair<long long, int>> events;
    for (auto &e : ev) {
        if (events.empty() || events.back().first != e.first) {
            events.push_back(e);
        } else {
            events.back().second ^= e.second;
        }
    }

    vector<long long> L, R;
    vector<int> bit;

    auto addRun = [&](long long a, long long b, int v) {
        if (a > b) return;
        if (!L.empty() && bit.back() == v && R.back() + 1 == a) {
            R.back() = b;
        } else {
            L.push_back(a);
            R.push_back(b);
            bit.push_back(v);
        }
    };

    long long curPos = 1;
    int curBit = 0;

    for (auto &e : events) {
        long long p = e.first;
        int delta = e.second;

        if (p > curPos) {
            long long end = min(p - 1, N);
            if (curPos <= end) addRun(curPos, end, curBit);
            curPos = p;
        }

        if (p > N) break;

        curBit ^= delta;
        curPos = p;
    }

    if (curPos <= N) addRun(curPos, N, curBit);

    int rn = (int)L.size();

    vector<long long> prefOnes(rn + 1, 0);
    vector<long long> prefZeros(rn + 1, 0);
    vector<long long> prefVal(rn + 1, 0);

    for (int i = 0; i < rn; i++) {
        long long len = R[i] - L[i] + 1;

        prefOnes[i + 1] = prefOnes[i] + (bit[i] ? len : 0);
        prefZeros[i + 1] = prefZeros[i] + (bit[i] ? 0 : len);

        long long p2 = modpow(2, len);
        long long add = bit[i] ? (p2 - 1 + MOD) % MOD : 0;

        prefVal[i + 1] = (prefVal[i] * p2 + add) % MOD;
    }

    auto onesPrefix = [&](long long pos) -> long long {
        if (pos <= 0) return 0LL;
        if (pos > N) pos = N;

        int idx = int(lower_bound(R.begin(), R.end(), pos) - R.begin());
        long long take = pos - L[idx] + 1;

        return prefOnes[idx] + (bit[idx] ? take : 0LL);
    };

    auto getPrefVal = [&](long long pos) -> long long {
        if (pos <= 0) return 0LL;
        if (pos > N) pos = N;

        int idx = int(lower_bound(R.begin(), R.end(), pos) - R.begin());

        if (pos == R[idx]) return prefVal[idx + 1];

        long long take = pos - L[idx] + 1;
        long long p2 = modpow(2, take);

        long long res = prefVal[idx] * p2 % MOD;

        if (bit[idx]) {
            res += p2 - 1;
            res %= MOD;
        }

        return res;
    };

    auto positionZeroRank = [&](long long target) -> long long {
        int idx = int(upper_bound(prefZeros.begin(), prefZeros.end(), target - 1) - prefZeros.begin()) - 1;
        long long rank = target - prefZeros[idx];
        return L[idx] + rank - 1;
    };

    for (int qi = 0; qi < Q; qi++) {
        long long l, r, k;
        cin >> l >> r >> k;

        long long len = r - l + 1;

        long long onesBeforeL = onesPrefix(l - 1);
        long long onesR = onesPrefix(r);
        long long ones = onesR - onesBeforeL;

        long long ans;

        if (ones >= k) {
            ans = (modpow(2, k) - 1 + MOD) % MOD;
        } else {
            long long deleted = len - k;
            long long targetInSubstring = deleted + 1;

            long long zerosBeforeL = (l - 1) - onesBeforeL;
            long long targetZero = zerosBeforeL + targetInSubstring;

            long long p = positionZeroRank(targetZero);

            long long onesPminus1 = onesPrefix(p - 1);
            long long onesBeforeP = onesPminus1 - onesBeforeL;

            long long lenB = r - p + 1;
            long long powLenB = modpow(2, lenB);

            long long prefR = getPrefVal(r);
            long long prefPminus = getPrefVal(p - 1);

            long long B = (prefR - prefPminus * powLenB % MOD + MOD) % MOD;
            long long A = (modpow(2, onesBeforeP) - 1 + MOD) % MOD;

            ans = (A * powLenB % MOD + B) % MOD;
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int modpow(long long a, long long e) {
    long long res = 1;
    a %= MOD;
    while (e > 0) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return (int)res;
}

struct Node {
    long long len;
    long long ones;
    int val;
    int p2;
};

Node combineNode(const Node& A, const Node& B) {
    if (A.len == 0) return B;
    if (B.len == 0) return A;

    Node C;
    C.len = A.len + B.len;
    C.ones = A.ones + B.ones;
    C.val = ((long long)A.val * B.p2 + B.val) % MOD;
    C.p2 = (long long)A.p2 * B.p2 % MOD;
    return C;
}

struct SegTree {
    int size;
    vector<Node> tr;

    void init(int n) {
        size = 1;
        while (size < n) size <<= 1;
        tr.assign(2 * size, {0, 0, 0, 1});
    }

    void build(const vector<long long>& L, const vector<long long>& R, const vector<int>& bit) {
        int n = (int)L.size();
        init(n);

        for (int i = 0; i < n; i++) {
            long long len = R[i] - L[i] + 1;
            int p = modpow(2, len);
            long long ones = 0;
            int val = 0;

            if (bit[i]) {
                ones = len;
                val = (p - 1 + MOD) % MOD;
            }

            tr[size + i] = {len, ones, val, p};
        }

        for (int i = size - 1; i >= 1; i--) {
            tr[i] = combineNode(tr[i << 1], tr[i << 1 | 1]);
        }
    }

    Node query(int l, int r) {
        Node leftRes = {0, 0, 0, 1};
        Node rightRes = {0, 0, 0, 1};

        l += size;
        r += size;

        while (l < r) {
            if (l & 1) leftRes = combineNode(leftRes, tr[l++]);
            if (r & 1) rightRes = combineNode(tr[--r], rightRes);
            l >>= 1;
            r >>= 1;
        }

        return combineNode(leftRes, rightRes);
    }
};

long long N;
int M, Q;

vector<long long> runL, runR;
vector<int> runBit;

vector<long long> prefOnes, prefZeros;

SegTree seg;

int getRun(long long pos) {
    return int(upper_bound(runL.begin(), runL.end(), pos) - runL.begin()) - 1;
}

Node makePartial(int idx, long long l, long long r) {
    long long len = r - l + 1;
    int p = modpow(2, len);

    long long ones = 0;
    int val = 0;

    if (runBit[idx]) {
        ones = len;
        val = (p - 1 + MOD) % MOD;
    }

    return {len, ones, val, p};
}

long long onesRange(long long l, long long r, int i, int j) {
    if (l > r) return 0;

    if (i == j) {
        return runBit[i] ? (r - l + 1) : 0;
    }

    long long ans = 0;

    if (runBit[i]) ans += runR[i] - l + 1;
    if (runBit[j]) ans += r - runL[j] + 1;

    if (i + 1 < j) {
        ans += prefOnes[j] - prefOnes[i + 1];
    }

    return ans;
}

int valueRange(long long l, long long r, int i, int j) {
    if (l > r) return 0;

    if (i == j) {
        if (!runBit[i]) return 0;
        long long len = r - l + 1;
        int p = modpow(2, len);
        return (p - 1 + MOD) % MOD;
    }

    Node res = makePartial(i, l, runR[i]);

    if (i + 1 < j) {
        Node mid = seg.query(i + 1, j);
        res = combineNode(res, mid);
    }

    Node last = makePartial(j, runL[j], r);
    res = combineNode(res, last);

    return res.val;
}

long long findZeroByGlobalRank(long long rank) {
    int idx = int(upper_bound(prefZeros.begin(), prefZeros.end(), rank - 1) - prefZeros.begin()) - 1;
    long long offset = rank - prefZeros[idx];
    return runL[idx] + offset - 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M >> Q;

    vector<pair<long long, int>> events;
    events.reserve(2 * M);

    for (int i = 0; i < M; i++) {
        long long l, r;
        cin >> l >> r;

        events.push_back({l, 1});
        events.push_back({r + 1, 1});
    }

    sort(events.begin(), events.end());

    auto addRun = [&](long long l, long long r, int b) {
        if (l > r) return;

        if (!runL.empty() && runBit.back() == b && runR.back() + 1 == l) {
            runR.back() = r;
        } else {
            runL.push_back(l);
            runR.push_back(r);
            runBit.push_back(b);
        }
    };

    long long cur = 1;
    int parity = 0;
    int ei = 0;

    while (ei < (int)events.size()) {
        long long x = events[ei].first;

        if (cur < x) {
            long long L = cur;
            long long R = min(x - 1, N);
            if (L <= R) addRun(L, R, parity);
        }

        int toggles = 0;
        while (ei < (int)events.size() && events[ei].first == x) {
            toggles ^= events[ei].second;
            ei++;
        }

        parity ^= toggles;
        cur = x;

        if (cur > N) break;
    }

    if (cur <= N) {
        addRun(cur, N, parity);
    }

    int R = (int)runL.size();

    prefOnes.assign(R + 1, 0);
    prefZeros.assign(R + 1, 0);

    for (int i = 0; i < R; i++) {
        long long len = runR[i] - runL[i] + 1;

        prefOnes[i + 1] = prefOnes[i] + (runBit[i] ? len : 0);
        prefZeros[i + 1] = prefZeros[i] + (runBit[i] ? 0 : len);
    }

    seg.build(runL, runR, runBit);

    while (Q--) {
        long long l, r, k;
        cin >> l >> r >> k;

        int iL = getRun(l);
        int iR = getRun(r);

        long long len = r - l + 1;
        long long ones = onesRange(l, r, iL, iR);

        int ans;

        if (ones >= k) {
            ans = (modpow(2, k) - 1 + MOD) % MOD;
        } else {
            long long t = k - ones;
            long long zeros = len - ones;

            if (t >= zeros) {
                ans = valueRange(l, r, iL, iR);
            } else {
                long long zeroRankFromLeft = zeros - t;

                long long zerosBeforeL = prefZeros[iL];
                if (runBit[iL] == 0) {
                    zerosBeforeL += l - runL[iL];
                }

                long long globalRank = zerosBeforeL + zeroRankFromLeft;
                long long q = findZeroByGlobalRank(globalRank);

                long long suffixOnes = 0;
                int suffixVal = 0;

                if (q + 1 <= r) {
                    int iq = getRun(q + 1);
                    suffixOnes = onesRange(q + 1, r, iq, iR);
                    suffixVal = valueRange(q + 1, r, iq, iR);
                }

                long long leftOnes = ones - suffixOnes;

                long long leftPart = modpow(2, leftOnes);
                leftPart = (leftPart - 1 + MOD) % MOD;

                long long multiplier = modpow(2, t + suffixOnes);

                ans = (suffixVal + multiplier * leftPart) % MOD;
            }
        }

        cout << ans << '\n';
    }

    return 0;
}

