        if (L > R) return;
        if (!starts.empty() && bits.back() == b && ends.back() + 1 == L) {
            ends.back() = R;
        } else {
            starts.push_back(L);
            ends.push_back(R);
            bits.push_back(b);
        }
    };

    long long last = 1;
    int parity = 0;
    int i = 0;

    while (i < (int)events.size()) {
        long long x = events[i].first;

        if (x > last) {
            long long R = min(x - 1, N);
            if (last <= R) {
                addRun(last, R, parity);
            }
            last = x;
        }

        int flip = 0;
        while (i < (int)events.size() && events[i].first == x) {
            flip ^= events[i].second;
            i++;
        }
        parity ^= flip;
    }

    if (last <= N) {
        addRun(last, N, parity);
    }

    int K = (int)starts.size();

    vector<long long> prefOnes(K), prefZeros(K), prefVal(K);

    long long curOnes = 0;
    long long curVal = 0;

    for (int idx = 0; idx < K; idx++) {
        long long len = ends[idx] - starts[idx] + 1;
        long long p2 = modPow(2, len);

        long long piece = 0;
        if (bits[idx] == 1) {
            piece = (p2 - 1 + MOD) % MOD;
            curOnes += len;
        }

        curVal = (curVal * p2 + piece) % MOD;

        prefVal[idx] = curVal;
        prefOnes[idx] = curOnes;
        prefZeros[idx] = ends[idx] - curOnes;
    }

    auto onesPrefix = [&](long long x) -> long long {
        if (x <= 0) return 0LL;
        if (x > N) x = N;

        int idx = upper_bound(ends.begin(), ends.end(), x) - ends.begin();

        long long res = (idx > 0 ? prefOnes[idx - 1] : 0LL);

        if (bits[idx] == 1) {
            res += x - starts[idx] + 1;
        }

        return res;
    };

    auto valuePrefix = [&](long long x) -> long long {
        if (x <= 0) return 0LL;
        if (x > N) x = N;

        int idx = upper_bound(ends.begin(), ends.end(), x) - ends.begin();

        long long before = (idx > 0 ? prefVal[idx - 1] : 0LL);
        long long len = x - starts[idx] + 1;

        long long p2 = modPow(2, len);
        long long piece = 0;

        if (bits[idx] == 1) {
            piece = (p2 - 1 + MOD) % MOD;
        }

        return (before * p2 + piece) % MOD;
    };

    auto valueInterval = [&](long long l, long long r) -> long long {
        if (l > r) return 0LL;

        long long len = r - l + 1;
        long long pr = valuePrefix(r);
        long long pl = valuePrefix(l - 1);

        long long p2 = modPow(2, len);

        return (pr - pl * p2 % MOD + MOD) % MOD;
    };

    while (Q--) {
        long long l, r, k;
        cin >> l >> r >> k;

        long long len = r - l + 1;
        long long ones = onesPrefix(r) - onesPrefix(l - 1);

        long long ans;

        if (ones >= k) {
            ans = (modPow(2, k) - 1 + MOD) % MOD;
        } else {
            long long d = len - k;

            if (d == 0) {
                ans = valueInterval(l, r);
            } else {
                long long onesBeforeL = onesPrefix(l - 1);
                long long zerosBefore = (l - 1) - onesBeforeL;
                long long targetZero = zerosBefore + d;

                int idx = lower_bound(prefZeros.begin(), prefZeros.end(), targetZero) - prefZeros.begin();

                long long prevZeros = (idx > 0 ? prefZeros[idx - 1] : 0LL);
                long long offset = targetZero - prevZeros;

                long long p = starts[idx] + offset - 1;

                long long a = onesPrefix(p - 1) - onesBeforeL;
                long long suffixLen = r - p;

                long long powA = modPow(2, a);
                long long prefixOnesVal = (powA - 1 + MOD) % MOD;

                long long powSuffix = modPow(2, suffixLen);

                long long pr = valuePrefix(r);
                long long pp = valuePrefix(p);

                long long suffixVal = (pr - pp * powSuffix % MOD + MOD) % MOD;

                ans = (prefixOnesVal * powSuffix + suffixVal) % MOD;
            }
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1'000'000'007;

// O(1) evaluation of 2^e modulo MOD for 0 <= e <= 1e9.
// Since 2^15 * 2^15 > 1e9, two tables of size 2^15 suffice.
struct PowersOfTwo {
    static constexpr int SHIFT = 15;
    static constexpr int SIZE = 1 << SHIFT;
    static constexpr int MASK = SIZE - 1;

    vector<int> low, high;

    PowersOfTwo() : low(SIZE), high(SIZE) {
        low[0] = 1;
        for (int i = 1; i < SIZE; ++i) {
            low[i] = (2LL * low[i - 1]) % MOD;
        }

        long long step = (2LL * low[SIZE - 1]) % MOD; // 2^SIZE
        high[0] = 1;
        for (int i = 1; i < SIZE; ++i) {
            high[i] = (1LL * high[i - 1] * step) % MOD;
        }
    }

    int get(long long exponent) const {
        int a = int(exponent >> SHIFT);
        int b = int(exponent & MASK);
        return (1LL * high[a] * low[b]) % MOD;
    }
};

struct Run {
    int l, r;
};

struct Gap {
    int l, r;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, Q;
    cin >> N >> M >> Q;

    vector<int> events;
    events.reserve(2 * M);

    for (int i = 0; i < M; ++i) {
        int l, r;
        cin >> l >> r;
        events.push_back(l);
        events.push_back(r + 1);
    }

    sort(events.begin(), events.end());

    // Construct maximal runs of ones in the final string.
    vector<Run> runs;
    runs.reserve(M + 1);

    auto addRun = [&](int l, int r) {
        if (l > r) return;

        if (!runs.empty() && runs.back().r + 1 == l) {
            runs.back().r = r;
        } else {
            runs.push_back({l, r});
        }
    };

    int parity = 0;
    int previous = 1;
    int eventCount = int(events.size());

    for (int i = 0; i < eventCount;) {
        int j = i + 1;
        while (j < eventCount && events[j] == events[i]) {
            ++j;
        }

        int position = events[i];

        if (parity && previous < position) {
            addRun(previous, position - 1);
        }

        parity ^= ((j - i) & 1);
        previous = position;
        i = j;
    }

    if (parity && previous <= N) {
        addRun(previous, N);
    }

    PowersOfTwo powers;

    int runCount = int(runs.size());
    vector<int> starts(runCount), ends(runCount);
    vector<int> prefixCount(runCount + 1, 0);
    vector<int> prefixValue(runCount + 1, 0);
    vector<int> base(runCount);

    // prefixCount[i]: number of ones in the first i runs.
    // prefixValue[i]: binary value of the prefix ending at run i-1.
    // base[i] = (value immediately before run i) + 1, modulo MOD.
    for (int i = 0; i < runCount; ++i) {
        starts[i] = runs[i].l;
        ends[i] = runs[i].r;

        int length = ends[i] - starts[i] + 1;
        prefixCount[i + 1] = prefixCount[i] + length;

        long long before = 0;
        if (i > 0) {
            int gapLength = starts[i] - ends[i - 1] - 1;
            before = (1LL * prefixValue[i] * powers.get(gapLength)) % MOD;
        }

        base[i] = int((before + 1) % MOD);
        prefixValue[i + 1] = int(
            (1LL * base[i] * powers.get(length) % MOD + MOD - 1) % MOD
        );
    }

    // Construct the zero-gaps, i.e. the complement of the one-runs.
    vector<Gap> gaps;
    gaps.reserve(runCount + 1);

    auto addGap = [&](int l, int r) {
        if (l <= r) gaps.push_back({l, r});
    };

    if (runCount == 0) {
        addGap(1, N);
    } else {
        addGap(1, runs.front().l - 1);

        for (int i = 1; i < runCount; ++i) {
            addGap(runs[i - 1].r + 1, runs[i].l - 1);
        }

        addGap(runs.back().r + 1, N);
    }

    vector<int> zeroPrefix(gaps.size() + 1, 0);
    for (size_t i = 0; i < gaps.size(); ++i) {
        int length = gaps[i].r - gaps[i].l + 1;
        zeroPrefix[i + 1] = zeroPrefix[i] + length;
    }

    // Number of ones in positions [1, t].
    auto onesPrefix = [&](int t) -> long long {
        if (t <= 0 || runCount == 0) return 0;

        int index = int(
            upper_bound(starts.begin(), starts.end(), t) - starts.begin()
        ) - 1;

        if (index < 0) return 0;

        long long inside = min(t, ends[index]) - starts[index] + 1;
        return prefixCount[index] + inside;
    };

    // Binary value of positions [1, t], modulo MOD.
    auto prefixBinaryValue = [&](int t) -> long long {
        if (t <= 0 || runCount == 0) return 0;

        int index = int(
            upper_bound(starts.begin(), starts.end(), t) - starts.begin()
        ) - 1;

        if (index < 0) return 0;

        if (t <= ends[index]) {
            long long taken = t - starts[index] + 1;
            long long value = (1LL * base[index] * powers.get(taken)) % MOD;
            return (value + MOD - 1) % MOD;
        }

        int trailingZeros = t - ends[index];
        return (1LL * prefixValue[index + 1] *
                powers.get(trailingZeros)) % MOD;
    };

    while (Q--) {
        int l, r, k;
        cin >> l >> r >> k;

        long long ones = onesPrefix(r) - onesPrefix(l - 1);
        long long answer;

        if (ones == 0) {
            answer = 0;
        } else if (ones >= k) {
            answer = (powers.get(k) + MOD - 1LL) % MOD;
        } else {
            long long deletions = (long long)r - l + 1 - k;

            int lastRun = int(
                upper_bound(starts.begin(), starts.end(), r) - starts.begin()
            ) - 1;

            long long lastOne = min(r, ends[lastRun]);
            long long eligibleZeros =
                (lastOne - l) - (ones - 1);

            if (deletions > eligibleZeros) {
                // The optimal subsequence is 1^ones followed by k-ones zeros.
                answer = (
                    powers.get(k) - powers.get(k - ones) + MOD
                ) % MOD;
            } else {
                int x = l - 1;

                if (deletions > 0) {
                    // Convert the local zero rank into a global zero rank.
                    long long zerosBefore =
                        (long long)l - 1 - onesPrefix(l - 1);
                    long long target = zerosBefore + deletions;

                    auto it = lower_bound(
                        zeroPrefix.begin() + 1,
                        zeroPrefix.end(),
                        target
                    );

                    int gapIndex = int(it - zeroPrefix.begin()) - 1;
                    long long zerosBeforeGap = zeroPrefix[gapIndex];

                    x = int(
                        (long long)gaps[gapIndex].l +
                        (target - zerosBeforeGap) - 1
                    );
                }

                long long leadingOnes =
                    onesPrefix(x) - onesPrefix(l - 1);

                long long shift = powers.get((long long)r - x);
                long long valueR = prefixBinaryValue(r);
                long long valueX = prefixBinaryValue(x);

                long long coefficient =
                    (powers.get(leadingOnes) - 1LL - valueX) % MOD;
                if (coefficient < 0) coefficient += MOD;

                answer = (valueR + coefficient * shift) % MOD;
            }
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int MOD = 1'000'000'007;

// Computes 2^e and 2^(-e) modulo MOD in O(1).
// small tables handle the low bits, large tables handle complete blocks.
class PowerTable {
    static constexpr int B = 1 << 15;

    vector<int> smallPow, largePow;
    vector<int> smallInv, largeInv;

public:
    explicit PowerTable(int maxExponent) {
        smallPow.resize(B);
        smallInv.resize(B);

        smallPow[0] = smallInv[0] = 1;
        const int INV2 = 500'000'004;

        for (int i = 1; i < B; ++i) {
            smallPow[i] = 2LL * smallPow[i - 1] % MOD;
            smallInv[i] = 1LL * smallInv[i - 1] * INV2 % MOD;
        }

        int blocks = maxExponent / B + 2;
        largePow.assign(blocks, 1);
        largeInv.assign(blocks, 1);

        int step = 2LL * smallPow[B - 1] % MOD;
        int inverseStep = 1LL * smallInv[B - 1] * INV2 % MOD;

        for (int i = 1; i < blocks; ++i) {
            largePow[i] = 1LL * largePow[i - 1] * step % MOD;
            largeInv[i] = 1LL * largeInv[i - 1] * inverseStep % MOD;
        }
    }

    int powerOfTwo(long long exponent) const {
        int block = static_cast<int>(exponent / B);
        int offset = static_cast<int>(exponent % B);
        return 1LL * largePow[block] * smallPow[offset] % MOD;
    }

    int inversePowerOfTwo(long long exponent) const {
        int block = static_cast<int>(exponent / B);
        int offset = static_cast<int>(exponent % B);
        return 1LL * largeInv[block] * smallInv[offset] % MOD;
    }
};

struct Run {
    int l, r, bit;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, Q;
    cin >> N >> M >> Q;

    // Each flip toggles the derivative at l and r+1.
    vector<int> events;
    events.reserve(2 * M);

    for (int i = 0; i < M; ++i) {
        int l, r;
        cin >> l >> r;
        events.push_back(l);
        events.push_back(r + 1);
    }

    sort(events.begin(), events.end());

    vector<Run> runs;
    runs.reserve(events.size() + 1);

    auto addRun = [&](int l, int r, int bit) {
        if (l > r) return;

        if (!runs.empty() &&
            runs.back().bit == bit &&
            runs.back().r + 1 == l) {
            runs.back().r = r;
        } else {
            runs.push_back({l, r, bit});
        }
    };

    int currentBit = 0;
    int previous = 1;

    for (size_t i = 0; i < events.size();) {
        size_t j = i + 1;
        while (j < events.size() && events[j] == events[i]) ++j;

        int position = events[i];
        addRun(previous, position - 1, currentBit);

        if ((j - i) & 1U) currentBit ^= 1;
        previous = position;
        i = j;
    }
    addRun(previous, N, currentBit);

    PowerTable powers(N);

    int runCount = static_cast<int>(runs.size());
    vector<int> starts(runCount);
    vector<int> prefixOnes(runCount + 1, 0);
    vector<int> prefixZeros(runCount + 1, 0);
    vector<int> prefixWeight(runCount + 1, 0);

    // prefixWeight[j] = sum_{i=1}^{end of run j-1} s_i * 2^(-i).
    for (int i = 0; i < runCount; ++i) {
        starts[i] = runs[i].l;
        int length = runs[i].r - runs[i].l + 1;

        prefixOnes[i + 1] = prefixOnes[i];
        prefixZeros[i + 1] = prefixZeros[i];

        if (runs[i].bit) {
            prefixOnes[i + 1] += length;
            prefixZeros[i + 1] += length;

            // Sum_{x=l}^{r} 2^(-x) = 2^(-(l-1)) - 2^(-r).
            int contribution =
                powers.inversePowerOfTwo(runs[i].l - 1) -
                powers.inversePowerOfTwo(runs[i].r);

            if (contribution < 0) contribution += MOD;

            prefixWeight[i + 1] = prefixWeight[i] + contribution;
            if (prefixWeight[i + 1] >= MOD) prefixWeight[i + 1] -= MOD;
        } else {
            prefixWeight[i + 1] = prefixWeight[i];
        }
    }

    auto runIndex = [&](int position) -> int {
        return static_cast<int>(
            upper_bound(starts.begin(), starts.end(), position) -
            starts.begin()
        ) - 1;
    };

    auto onesPrefix = [&](int position) -> int {
        if (position <= 0) return 0;

        int index = runIndex(position);
        int result = prefixOnes[index];

        if (runs[index].bit) {
            result += position - runs[index].l + 1;
        }
        return result;
    };

    auto zerosPrefix = [&](int position) -> int {
        if (position <= 0) return 0;

        int index = runIndex(position);
        int result = prefixZeros[index];

        if (!runs[index].bit) {
            result += position - runs[index].l + 1;
        }
        return result;
    };

    auto weightPrefix = [&](int position) -> int {
        if (position <= 0) return 0;

        int index = runIndex(position);
        int result = prefixWeight[index];

        if (runs[index].bit) {
            int contribution =
                powers.inversePowerOfTwo(runs[index].l - 1) -
                powers.inversePowerOfTwo(position);

            if (contribution < 0) contribution += MOD;

            result += contribution;
            if (result >= MOD) result -= MOD;
        }
        return result;
    };

    // Binary value of s[l..r], interpreted as a binary number.
    auto rangeValue = [&](int l, int r) -> int {
        if (l > r) return 0;

        int difference = weightPrefix(r) - weightPrefix(l - 1);
        if (difference < 0) difference += MOD;

        return 1LL * powers.powerOfTwo(r) * difference % MOD;
    };

    string output;
    output.reserve(static_cast<size_t>(Q) * 12);

    for (int query = 0; query < Q; ++query) {
        int l, r, k;
        cin >> l >> r >> k;

        int length = r - l + 1;
        int ones = onesPrefix(r) - onesPrefix(l - 1);
        int answer;

        if (ones >= k) {
            // The answer consists of k ones.
            answer = powers.powerOfTwo(k) - 1;
            if (answer < 0) answer += MOD;
        } else {
            int deletedZeros = length - k;

            // If deletedZeros == 0, use the virtual position l-1.
            int p = l - 1;

            if (deletedZeros > 0) {
                // Global rank of the deletedZeros-th zero in [l, r].
                long long target =
                    static_cast<long long>(zerosPrefix(l - 1)) +
                    deletedZeros;

                auto it = lower_bound(
                    prefixZeros.begin(), prefixZeros.end(), target
                );

                int completedRuns =
                    static_cast<int>(it - prefixZeros.begin());
                int index = completedRuns - 1;

                long long offset =
                    target - prefixZeros[index];

                p = runs[index].l + static_cast<int>(offset) - 1;
            }

            int suffixLength = r - p;
            int suffixValue = rangeValue(p + 1, r);

            long long value =
                static_cast<long long>(powers.powerOfTwo(k)) -
                powers.powerOfTwo(suffixLength) +
                suffixValue;

            value %= MOD;
            if (value < 0) value += MOD;
            answer = static_cast<int>(value);
        }

        output += to_string(answer);
        output.push_back('\n');
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
static constexpr int64 MOD = 1'000'000'007LL;

class FastInput {
    static constexpr size_t SIZE = 1 << 16;
    char buffer[SIZE];
    size_t pos = 0, len = 0;

    int getChar() {
        if (pos == len) {
            len = fread(buffer, 1, SIZE, stdin);
            pos = 0;
            if (len == 0) return EOF;
        }
        return static_cast<unsigned char>(buffer[pos++]);
    }

public:
    template <class T>
    bool read(T& value) {
        int c = getChar();
        while (c != EOF && c <= ' ') c = getChar();
        if (c == EOF) return false;

        bool negative = false;
        if (c == '-') {
            negative = true;
            c = getChar();
        }

        T result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = getChar();
        }

        value = negative ? -result : result;
        return true;
    }
};

class FastOutput {
    static constexpr size_t SIZE = 1 << 16;
    char buffer[SIZE];
    size_t pos = 0;

public:
    ~FastOutput() {
        flush();
    }

    void flush() {
        if (pos) {
            fwrite(buffer, 1, pos, stdout);
            pos = 0;
        }
    }

    void put(char c) {
        if (pos == SIZE) flush();
        buffer[pos++] = c;
    }

    void writeInt(int64 value) {
        if (value == 0) {
            put('0');
            put('\n');
            return;
        }

        char digits[24];
        int count = 0;
        while (value) {
            digits[count++] = char('0' + value % 10);
            value /= 10;
        }
        while (count) put(digits[--count]);
        put('\n');
    }
};

// O(1) lookup for 2^exponent, where exponent <= 1e9 < 2^30.
// Split the exponent into two 15-bit parts.
class PowerOfTwo {
    static constexpr int SHIFT = 15;
    static constexpr int BLOCK = 1 << SHIFT;

    vector<int64> low, high;

public:
    explicit PowerOfTwo(int64 maxExponent) {
        low.resize(BLOCK);
        low[0] = 1;
        for (int i = 1; i < BLOCK; ++i) {
            low[i] = low[i - 1] * 2 % MOD;
        }

        int64 jump = low[BLOCK - 1] * 2 % MOD; // 2^BLOCK

        high.resize(static_cast<size_t>((maxExponent >> SHIFT) + 1));
        high[0] = 1;
        for (size_t i = 1; i < high.size(); ++i) {
            high[i] = high[i - 1] * jump % MOD;
        }
    }

    int64 operator()(int64 exponent) const {
        int lo = static_cast<int>(exponent & (BLOCK - 1));
        int hi = static_cast<int>(exponent >> SHIFT);
        return low[lo] * high[hi] % MOD;
    }
};

struct Run {
    int64 start, end;
    int bit;
    int64 onesBefore;
    int64 zerosBefore;
    int64 valueBefore;
};

struct PrefixInfo {
    int64 ones;
    int64 value;
};

int main() {
    FastInput in;
    FastOutput out;

    int64 N;
    int M, Q;
    if (!in.read(N)) return 0;
    in.read(M);
    in.read(Q);

    // Each flip toggles at l and again at r+1.
    vector<int64> events;
    events.reserve(2 * M);

    for (int i = 0; i < M; ++i) {
        int64 l, r;
        in.read(l);
        in.read(r);
        events.push_back(l);
        events.push_back(r + 1);
    }

    sort(events.begin(), events.end());

    vector<Run> runs;
    runs.reserve(events.size() + 1);

    auto addRun = [&](int64 l, int64 r, int bit) {
        if (l > r) return;

        if (!runs.empty() &&
            runs.back().bit == bit &&
            runs.back().end + 1 == l) {
            runs.back().end = r;
        } else {
            runs.push_back(Run{l, r, bit, 0, 0, 0});
        }
    };

    int64 current = 1;
    int currentBit = 0;

    size_t pos = 0;
    while (pos < events.size()) {
        int64 x = events[pos];
        addRun(current, x - 1, currentBit);

        size_t next = pos;
        while (next < events.size() && events[next] == x) ++next;

        currentBit ^= static_cast<int>((next - pos) & 1ULL);
        current = x;
        pos = next;
    }

    if (current <= N) {
        addRun(current, N, currentBit);
    }

    PowerOfTwo power2(N);

    vector<int64> starts;
    vector<int64> cumulativeZeros;
    starts.reserve(runs.size());
    cumulativeZeros.reserve(runs.size());

    int64 prefixOnes = 0;
    int64 prefixZeros = 0;
    int64 prefixValue = 0;

    for (Run& run : runs) {
        int64 length = run.end - run.start + 1;

        run.onesBefore = prefixOnes;
        run.zerosBefore = prefixZeros;
        run.valueBefore = prefixValue;

        int64 p = power2(length);
        prefixValue = prefixValue * p % MOD;
        if (run.bit) {
            prefixValue = (prefixValue + p - 1 + MOD) % MOD;
        }

        if (run.bit) {
            prefixOnes += length;
        } else {
            prefixZeros += length;
        }

        starts.push_back(run.start);
        cumulativeZeros.push_back(prefixZeros);
    }

    // Information about the prefix S[1..x].
    auto prefixInfo = [&](int64 x) -> PrefixInfo {
        if (x <= 0) return {0, 0};

        int id = static_cast<int>(
            upper_bound(starts.begin(), starts.end(), x) - starts.begin()
        ) - 1;

        int64 length = x - runs[id].start + 1;
        int64 ones = runs[id].onesBefore;
        if (runs[id].bit) ones += length;

        int64 p = power2(length);
        int64 value = runs[id].valueBefore * p % MOD;
        if (runs[id].bit) {
            value = (value + p - 1 + MOD) % MOD;
        }

        return {ones, value};
    };

    for (int qi = 0; qi < Q; ++qi) {
        int64 l, r, k;
        in.read(l);
        in.read(r);
        in.read(k);

        PrefixInfo left = prefixInfo(l - 1);
        PrefixInfo right = prefixInfo(r);

        int64 countOnes = right.ones - left.ones;

        // We can choose k ones, so 111...111 is optimal.
        if (countOnes >= k) {
            out.writeInt((power2(k) - 1 + MOD) % MOD);
            continue;
        }

        int64 substringLength = r - l + 1;
        int64 deletions = substringLength - k;

        // The optimal subsequence retains all ones and the rightmost
        // (k - countOnes) zeros. Thus the first retained zero is the
        // (deletions + 1)-st zero of the queried substring.
        int64 zerosBeforeL = (l - 1) - left.ones;
        int64 targetZero = zerosBeforeL + deletions + 1;

        int id = static_cast<int>(
            lower_bound(cumulativeZeros.begin(), cumulativeZeros.end(),
                        targetZero) - cumulativeZeros.begin()
        );

        const Run& zeroRun = runs[id];
        int64 localZeroIndex =
            targetZero - zeroRun.zerosBefore; // 1-indexed within this run
        int64 x = zeroRun.start + localZeroIndex - 1;

        // All characters before x that remain are ones.
        int64 p = zeroRun.onesBefore - left.ones;

        int64 suffixLength = r - x + 1;
        int64 scale = power2(suffixLength);

        // The run containing x is a zero run, so this is value(S[1..x-1]).
        int64 valueBeforeX =
            zeroRun.valueBefore * power2(x - zeroRun.start) % MOD;

        int64 suffixValue =
            (right.value - valueBeforeX * scale % MOD + MOD) % MOD;

        int64 leadingValue = (power2(p) - 1 + MOD) % MOD;
        int64 answer = (leadingValue * scale + suffixValue) % MOD;

        out.writeInt(answer);
    }

    return 0;
}

