            if (A < K) {
                cout << 0 << '\n';
                return 0;
            }

            long long x = A % MOD;

            for (int t = 0; t < K; ++t) {
                long long term = x - t;
                if (term < 0) term += MOD;
                numerator = numerator * term % MOD;
            }
        }
    }

    long long perCopy = numerator * modpow(invFact, MT) % MOD;
    long long answer = modpow(perCopy, L);

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    a %= MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long K, L;
    int N;
    cin >> K >> N >> L;

    string T;
    cin >> T;

    long long M = 0;
    for (char ch : T) {
        if (ch == 'M') ++M;
    }
    long long O = N - M;

    // A valid decomposition must use every character:
    // total Os = K * total Ms.
    if (K > N || K * M != O) {
        cout << 0 << '\n';
        return 0;
    }

    long long available = 0;
    long long numerator = 1;
    long long kMod = K % MOD;

    for (char ch : T) {
        if (ch == 'M') {
            available += kMod;
            if (available >= MOD) available -= MOD;
        } else {
            numerator = numerator * available % MOD;
            --available;
            if (available < 0) available += MOD;
        }
    }

    long long factK = 1;
    for (long long i = 2; i <= K; ++i) {
        factK = factK * i % MOD;
    }

    long long invFactK = modpow(factK, MOD - 2);
    long long denominatorInverse = modpow(invFactK, M);

    long long perPeriod = numerator * denominatorInverse % MOD;
    long long answer = modpow(perPeriod, L);

    cout << answer << '\n';
    return 0;
}

