using int64 = long long;
constexpr int64 MOD = 1'000'000'007;

int64 modPow(int64 base, int64 exp) {
    int64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 K, L;
    int N;
    cin >> K >> N >> L;

    string T;
    cin >> T;

    int64 seenM = 0, seenO = 0;
    int64 numerator = 1;

    for (char c : T) {
        if (c == 'M') {
            ++seenM;
        } else {
            ++seenO;
            int64 choices = K * seenM - (seenO - 1);
            choices %= MOD;
            if (choices < 0) choices += MOD;
            numerator = numerator * choices % MOD;
        }
    }

    // A nonzero decomposition requires #O(T) = K * #M(T).
    if (seenO != K * seenM) {
        cout << 0 << '\n';
        return 0;
    }

    int64 factorial = 1;
    for (int64 i = 1; i <= K; ++i) {
        factorial = factorial * i % MOD;
    }

    int64 denominator = modPow(factorial, seenM);
    int64 oneCopy = numerator * modPow(denominator, MOD - 2) % MOD;

    cout << modPow(oneCopy, L) << '\n';
    return 0;
}

