int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> a(N + 1), cnt(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        ++cnt[a[i]];
    }

    map<int, set<int>> groups;
    for (int i = 1; i <= N; ++i) {
        if (cnt[i] > 0) groups[cnt[i]].insert(i);
    }

    auto removeCow = [&](int cow, int c) {
        auto it = groups.find(c);
        it->second.erase(cow);
        if (it->second.empty()) groups.erase(it);
    };

    auto addCow = [&](int cow, int c) {
        groups[c].insert(cow);
    };

    while (Q--) {
        int i, x;
        cin >> i >> x;

        int old = a[i];
        if (old != x) {
            removeCow(old, cnt[old]);
            --cnt[old];
            if (cnt[old] > 0) addCow(old, cnt[old]);

            if (cnt[x] > 0) removeCow(x, cnt[x]);
            ++cnt[x];
            addCow(x, cnt[x]);

            a[i] = x;
        }

        int K = (int)groups.size();
        vector<int> value(K), mn(K), mx(K);
        int p = 0;
        for (const auto &entry : groups) {
            value[p] = entry.first;
            mn[p] = *entry.second.begin();
            mx[p] = *entry.second.rbegin();
            ++p;
        }

        vector<int> sufMn(K), sufMx(K);
        for (int j = K - 1; j >= 0; --j) {
            sufMn[j] = mn[j];
            sufMx[j] = mx[j];
            if (j + 1 < K) {
                sufMn[j] = min(sufMn[j], sufMn[j + 1]);
                sufMx[j] = max(sufMx[j], sufMx[j + 1]);
            }
        }

        int M = value.back();
        int answer = 0;

        for (int j = 0; j < K; ++j) {
            int need = M - value[j];
            int k = lower_bound(value.begin(), value.end(), need) - value.begin();
            if (k == K) continue;

            int low = sufMn[k], high = sufMx[k];
            answer = max(answer, abs(mn[j] - low));
            answer = max(answer, abs(mn[j] - high));
            answer = max(answer, abs(mx[j] - low));
            answer = max(answer, abs(mx[j] - high));
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct SegTree {
    int n, size;
    vector<int> tr;

    SegTree(int n_) : n(n_) {
        size = 1;
        while (size < n) size <<= 1;
        tr.assign(2 * size, 0);
    }

    void setValue(int pos, int value) {
        int p = pos + size - 1;
        tr[p] = value;
        for (p >>= 1; p; p >>= 1)
            tr[p] = max(tr[p << 1], tr[p << 1 | 1]);
    }

    int firstAtLeast(int value) const {
        if (tr[1] < value) return n + 1;
        int p = 1;
        while (p < size) {
            if (tr[p << 1] >= value) p <<= 1;
            else p = p << 1 | 1;
        }
        return p - size + 1;
    }

    int lastAtLeast(int value) const {
        if (tr[1] < value) return 0;
        int p = 1;
        while (p < size) {
            if (tr[p << 1 | 1] >= value) p = p << 1 | 1;
            else p <<= 1;
        }
        return p - size + 1;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> a(N + 1), cnt(N + 1, 0);
    map<int, set<int>> byCount;
    SegTree seg(N);

    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        ++cnt[a[i]];
    }

    for (int x = 1; x <= N; ++x) {
        if (cnt[x] > 0) {
            byCount[cnt[x]].insert(x);
            seg.setValue(x, cnt[x]);
        }
    }

    auto changeCount = [&](int x, int newCount) {
        int oldCount = cnt[x];
        if (oldCount > 0) {
            auto &s = byCount[oldCount];
            s.erase(x);
            if (s.empty()) byCount.erase(oldCount);
        }
        cnt[x] = newCount;
        if (newCount > 0) byCount[newCount].insert(x);
        seg.setValue(x, newCount);
    };

    while (Q--) {
        int i, x;
        cin >> i >> x;

        int old = a[i];
        if (old != x) {
            changeCount(old, cnt[old] - 1);
            changeCount(x, cnt[x] + 1);
            a[i] = x;
        }

        int M = byCount.rbegin()->first;
        int answer = 0;

        auto it = byCount.lower_bound((M + 1) / 2);
        for (; it != byCount.end(); ++it) {
            int c = it->first;
            int needed = max(1, M - c);
            int lo = seg.firstAtLeast(needed);
            int hi = seg.lastAtLeast(needed);

            for (int h : it->second) {
                answer = max(answer, abs(h - lo));
                answer = max(answer, abs(h - hi));
            }
        }

        cout << answer << '\n';
    }

    return 0;
}

