    vector<int> a(N + 1);
    vector<int> cnt(N + 1, 0);

    for (int i = 1; i <= N; i++) {
        cin >> a[i];
        cnt[a[i]]++;
    }

    vector< set<int> > bucket(N + 1);
    set<int> activeFreqs;

    for (int v = 1; v <= N; v++) {
        if (cnt[v] > 0) {
            bucket[cnt[v]].insert(v);
            activeFreqs.insert(cnt[v]);
        }
    }

    vector<int> freqs;
    freqs.reserve(N + 1);

    vector<int> cumMin(N + 1), cumMax(N + 1);
    vector<int> exactMin(N + 1), exactMax(N + 1);

    auto computeAnswer = [&]() -> int {
        freqs.clear();

        for (auto it = activeFreqs.rbegin(); it != activeFreqs.rend(); ++it) {
            freqs.push_back(*it);
        }

        int D = (int)freqs.size();

        for (int i = 0; i < D; i++) {
            int f = freqs[i];
            auto &s = bucket[f];

            int mn = *s.begin();
            int mx = *s.rbegin();

            exactMin[i] = mn;
            exactMax[i] = mx;

            if (i == 0) {
                cumMin[i] = mn;
                cumMax[i] = mx;
            } else {
                cumMin[i] = min(cumMin[i - 1], mn);
                cumMax[i] = max(cumMax[i - 1], mx);
            }
        }

        int M = freqs[0];
        int ans = 0;
        int r = D - 1;

        for (int i = 0; i < D; i++) {
            int f = freqs[i];
            int need = M - f;

            while (r >= 0 && freqs[r] < need) {
                r--;
            }

            if (r < 0) continue;

            int minB = cumMin[r];
            int maxB = cumMax[r];

            int minA = exactMin[i];
            int maxA = exactMax[i];

            ans = max(ans, maxB - minA);
            ans = max(ans, maxA - minB);
        }

        return ans;
    };

    for (int qi = 0; qi < Q; qi++) {
        int i, x;
        cin >> i >> x;

        int old = a[i];

        if (old != x) {
            // Remove old vote.
            int oldCnt = cnt[old];
            bucket[oldCnt].erase(old);
            if (bucket[oldCnt].empty()) {
                activeFreqs.erase(oldCnt);
            }

            cnt[old]--;
            if (cnt[old] > 0) {
                bucket[cnt[old]].insert(old);
                activeFreqs.insert(cnt[old]);
            }

            // Add new vote.
            int curCnt = cnt[x];
            if (curCnt > 0) {
                bucket[curCnt].erase(x);
                if (bucket[curCnt].empty()) {
                    activeFreqs.erase(curCnt);
                }
            }

            cnt[x]++;
            bucket[cnt[x]].insert(x);
            activeFreqs.insert(cnt[x]);

            a[i] = x;
        }

        cout << computeAnswer() << '\n';
    }

    return 0;
}

