        int old = cnt[v];
        int nw = old + delta;

        if (old > 0) {
            auto &s = byFreq[old];
            s.erase(v);

            if (s.empty()) {
                freqValues.erase(old);
                mn[old] = INF;
                mx[old] = -INF;
            } else {
                mn[old] = *s.begin();
                mx[old] = *s.rbegin();
            }
        }

        cnt[v] = nw;

        if (nw > 0) {
            auto &s = byFreq[nw];

            if (s.empty()) {
                freqValues.insert(nw);
            }

            s.insert(v);
            mn[nw] = *s.begin();
            mx[nw] = *s.rbegin();
