        for (int v = B; v >= 1; v--) {
            if (!byFreq[v].empty()) {
                int gmin = *byFreq[v].begin();
                int gmax = *byFreq[v].rbegin();

                exMin[v] = gmin;
                exMax[v] = gmax;

                curMin = min(curMin, gmin);
                curMax = max(curMax, gmax);
            } else {
                exMin[v] = INF;
                exMax[v] = -INF;
            }

            sufMin[v] = curMin;
            sufMax[v] = curMax;
        }

        int ans = 0;

        if (M <= B) {
            for (int af = 1; af <= M; af++) {
                if (exMin[af] == INF) continue;

                int need = M - af;
                if (need < 1) need = 1;

                int amin = exMin[af];
                int amax = exMax[af];

                int cmin = sufMin[need];
                int cmax = sufMax[need];

                if (amin != cmin) ans = max(ans, abs(amin - cmin));
                if (amin != cmax) ans = max(ans, abs(amin - cmax));
                if (amax != cmin) ans = max(ans, abs(amax - cmin));
                if (amax != cmax) ans = max(ans, abs(amax - cmax));
            }
        } else {
            hf.clear();
            hMin.clear();
            hMax.clear();

            for (auto it = activeFreqs.lower_bound(B + 1); it != activeFreqs.end(); ++it) {
                int f = *it;

                int gmin = *byFreq[f].begin();
                int gmax = *byFreq[f].rbegin();

                hf.push_back(f);
                hMin.push_back(gmin);
                hMax.push_back(gmax);
            }

            int curMinH = INF, curMaxH = -INF;

            for (int idx = (int)hf.size() - 1; idx >= 0; idx--) {
                curMinH = min(curMinH, hMin[idx]);
                curMaxH = max(curMaxH, hMax[idx]);

                hMin[idx] = curMinH;
                hMax[idx] = curMaxH;
            }

            int half = (M + 1) / 2;

            for (auto it = activeFreqs.lower_bound(half); it != activeFreqs.end(); ++it) {
                int f = *it;

                for (int cowVal : byFreq[f]) {
                    int need = M - f;
                    if (need < 1) need = 1;

                    int cmin, cmax;

                    if (need <= B) {
                        cmin = sufMin[need];
                        cmax = sufMax[need];
                    } else {
                        int idx = lower_bound(hf.begin(), hf.end(), need) - hf.begin();
                        if (idx == (int)hf.size()) continue;

                        cmin = hMin[idx];
                        cmax = hMax[idx];
                    }

                    if (cmin != cowVal) ans = max(ans, abs(cowVal - cmin));
                    if (cmax != cowVal) ans = max(ans, abs(cowVal - cmax));
                }
            }
        }

        output += to_string(ans);
        output += '\n';
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class VoteTracker {
    static constexpr int INF = 1'000'000'000;

    int n;
    int maxFrequency = 0;

    vector<int> frequency;
    vector<set<int>> bucket;

    // exactMin[f], exactMax[f]: extreme labels having exactly f votes.
    vector<int> exactMin, exactMax;

    // suffixMin[f], suffixMax[f]: extreme labels having at least f votes.
    vector<int> suffixMin, suffixMax;

    // Nonempty frequency buckets.
    vector<int> activeFrequencies;
    vector<int> activePosition;

    void insertIntoBucket(int label, int f) {
        auto &s = bucket[f];

        if (s.empty()) {
            activePosition[f] = (int)activeFrequencies.size();
            activeFrequencies.push_back(f);
        }

        s.insert(label);
        exactMin[f] = min(exactMin[f], label);
        exactMax[f] = max(exactMax[f], label);
    }

    void eraseFromBucket(int label, int f) {
        auto &s = bucket[f];
        auto it = s.find(label);
        s.erase(it);

        if (s.empty()) {
            exactMin[f] = INF;
            exactMax[f] = -INF;

            int pos = activePosition[f];
            int last = activeFrequencies.back();

            activeFrequencies[pos] = last;
            activePosition[last] = pos;
            activeFrequencies.pop_back();
            activePosition[f] = -1;
        } else {
            exactMin[f] = *s.begin();
            exactMax[f] = *s.rbegin();
        }
    }

    void refreshSuffix(int f) {
        suffixMin[f] = min(exactMin[f], suffixMin[f + 1]);
        suffixMax[f] = max(exactMax[f], suffixMax[f + 1]);
    }

    void normalizeMaximum() {
        while (maxFrequency > 0 && bucket[maxFrequency].empty()) {
            --maxFrequency;
        }
    }

public:
    explicit VoteTracker(vector<int> initial)
        : n((int)initial.size() - 1),
          frequency(std::move(initial)),
          bucket(n + 1),
          exactMin(n + 1, INF),
          exactMax(n + 1, -INF),
          suffixMin(n + 2, INF),
          suffixMax(n + 2, -INF),
          activePosition(n + 1, -1) {

        for (int label = 1; label <= n; ++label) {
            if (frequency[label] > 0) {
                auto &s = bucket[frequency[label]];
                s.insert(s.end(), label);
            }
        }

        for (int f = 1; f <= n; ++f) {
            if (!bucket[f].empty()) {
                exactMin[f] = *bucket[f].begin();
                exactMax[f] = *bucket[f].rbegin();

                activePosition[f] = (int)activeFrequencies.size();
                activeFrequencies.push_back(f);
            }
        }

        maxFrequency = activeFrequencies.empty() ? 0 : activeFrequencies.back();

        for (int f = n; f >= 1; --f) {
            refreshSuffix(f);
        }
    }

    void removeOneVote(int label) {
        int oldFrequency = frequency[label];

        eraseFromBucket(label, oldFrequency);
        frequency[label] = oldFrequency - 1;

        if (oldFrequency > 1) {
            insertIntoBucket(label, oldFrequency - 1);
        }

        // This label leaves exactly the set of labels with frequency >= oldFrequency.
        refreshSuffix(oldFrequency);
        normalizeMaximum();
    }

    void addOneVote(int label) {
        int oldFrequency = frequency[label];

        if (oldFrequency > 0) {
            eraseFromBucket(label, oldFrequency);
        }

        frequency[label] = oldFrequency + 1;
        insertIntoBucket(label, oldFrequency + 1);

        // This label enters exactly the set of labels with frequency >= oldFrequency+1.
        refreshSuffix(oldFrequency + 1);

        maxFrequency = max(maxFrequency, oldFrequency + 1);
        normalizeMaximum();
    }

    int bestDiversity() const {
        int answer = 0;

        for (int f : activeFrequencies) {
            // A partner with frequency g must satisfy f+g >= maxFrequency.
            int required = max(1, maxFrequency - f);

            answer = max(answer, suffixMax[required] - exactMin[f]);
            answer = max(answer, exactMax[f] - suffixMin[required]);
        }

        return answer;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> a(N + 1);
    vector<int> count(N + 1, 0);

    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        ++count[a[i]];
    }

    VoteTracker tracker(std::move(count));

    while (Q--) {
        int i, x;
        cin >> i >> x;

        if (a[i] != x) {
            tracker.removeOneVote(a[i]);
            tracker.addOneVote(x);
            a[i] = x;
        }

        cout << tracker.bestDiversity() << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class ElectionSolver {
    struct CacheCell {
        int nonEdge = -1;
        int oneEdge = -1;
        uint32_t nonGen1 = 0, nonGen2 = 0;
        uint32_t oneGen1 = 0, oneGen2 = 0;
    };

    int N;
    vector<int> a, cnt;

    // group[c] contains the cows receiving exactly c votes.
    vector<set<int>> group;
    set<int> activeCounts;

    // Slots give active vote-count values compact cache indices.
    vector<int> slotOf;
    vector<int> slotValue;
    vector<uint32_t> slotGeneration;
    vector<int> freeSlots;
    vector<vector<CacheCell>> cacheCells;

    int currentAnswer = 0;

    static vector<int> firstK(const set<int>& s, int k) {
        vector<int> result;
        result.reserve(k);
        for (auto it = s.begin(); it != s.end() && (int)result.size() < k; ++it) {
            result.push_back(*it);
        }
        return result;
    }

    static vector<int> lastKDescending(const set<int>& s, int k) {
        vector<int> result;
        result.reserve(k);
        auto it = s.end();
        while (it != s.begin() && (int)result.size() < k) {
            --it;
            result.push_back(*it);
        }
        return result;
    }

    static vector<int> extremeIds(const set<int>& s) {
        vector<int> result = firstK(s, 3);
        vector<int> last = lastKDescending(s, 3);
        result.insert(result.end(), last.begin(), last.end());
        sort(result.begin(), result.end());
        result.erase(unique(result.begin(), result.end()), result.end());
        return result;
    }

    int allocateSlot(int countValue) {
        int s;
        if (!freeSlots.empty()) {
            s = freeSlots.back();
            freeSlots.pop_back();
            slotValue[s] = countValue;
            ++slotGeneration[s];
        } else {
            s = (int)slotValue.size();
            slotValue.push_back(countValue);
            slotGeneration.push_back(1);
            cacheCells.emplace_back();
            for (auto& row : cacheCells) {
                row.resize(s + 1);
            }
        }
        slotOf[countValue] = s;
        return s;
    }

    void markDirty(int c1, int c2) {
        if (c1 <= 0 || c2 <= 0) return;
        int s1 = slotOf[c1], s2 = slotOf[c2];
        if (s1 < 0 || s2 < 0) return;
        if (s1 > s2) swap(s1, s2);
        cacheCells[s1][s2].nonEdge = -1;
        cacheCells[s1][s2].oneEdge = -1;
    }

    void moveBetweenGroups(int cow, int oldCount, int newCount) {
        if (oldCount == newCount) return;

        if (oldCount > 0) {
            group[oldCount].erase(cow);

            int s = slotOf[oldCount];
            if (s >= 0) ++slotGeneration[s];

            if (group[oldCount].empty()) {
                if (s >= 0) {
                    slotOf[oldCount] = -1;
                    freeSlots.push_back(s);
                }
                activeCounts.erase(oldCount);
            }
        }

        if (newCount > 0) {
            int s = slotOf[newCount];
            if (s < 0) s = allocateSlot(newCount);
            ++slotGeneration[s];

            group[newCount].insert(cow);
            activeCounts.insert(newCount);
        }
    }

    bool adjacent(int x, int y) const {
        return a[x] == y || a[y] == x;
    }

    // For two cows whose counts sum to M, they can be leaders exactly
    // when neither votes for the other.
    int computeNonEdgeBest(int c, int d) {
        const auto& C = group[c];
        const auto& D = group[d];

        int best = 0;
        int minC = *C.begin();
        int minD = *D.begin();

        int limX = (int)min<long long>((long long)d + 2, C.size());
        int limY = (int)min<long long>((long long)c + 2, D.size());

        vector<int> firstX = firstK(C, limX);
        vector<int> lastX = lastKDescending(C, limX);
        vector<int> firstY = firstK(D, limY);
        vector<int> lastY = lastKDescending(D, limY);

        // Cases with the cow from D having the larger index.
        for (int y : lastY) {
            if (y - minC <= best) break;
            for (int x : firstX) {
                if (x >= y) break;
                if (!adjacent(x, y)) {
                    best = max(best, y - x);
                    break;
                }
            }
        }

        // Cases with the cow from C having the larger index.
        for (int x : lastX) {
            if (x - minD <= best) break;
            for (int y : firstY) {
                if (y >= x) break;
                if (!adjacent(x, y)) {
                    best = max(best, x - y);
                    break;
                }
            }
        }

        return best;
    }

    // For two cows whose counts sum to M+1, at most one directed
    // relation between them is allowed.
    bool validOneEdge(int x, int y, int c, int d) const {
        int u = (a[y] == x);
        int v = (a[x] == y);

        int p = c - u;
        int q = d - v;

        return p >= 1 && q >= 1 && u + v <= 1;
    }

    int computeOneEdgeBest(int c, int d) {
        vector<int> C = extremeIds(group[c]);
        vector<int> D = extremeIds(group[d]);

        int best = 0;
        for (int x : C) {
            for (int y : D) {
                if (x == y) continue;
                if (validOneEdge(x, y, c, d)) {
                    best = max(best, abs(x - y));
                }
            }
        }
        return best;
    }

    int getNonEdgeBest(int c, int d) {
        int s1 = slotOf[c], s2 = slotOf[d];
        int lo = min(s1, s2), hi = max(s1, s2);
        CacheCell& cell = cacheCells[lo][hi];

        if (cell.nonEdge < 0 ||
            cell.nonGen1 != slotGeneration[lo] ||
            cell.nonGen2 != slotGeneration[hi]) {
            cell.nonEdge = computeNonEdgeBest(c, d);
            cell.nonGen1 = slotGeneration[lo];
            cell.nonGen2 = slotGeneration[hi];
        }
        return cell.nonEdge;
    }

    int getOneEdgeBest(int c, int d) {
        int s1 = slotOf[c], s2 = slotOf[d];
        int lo = min(s1, s2), hi = max(s1, s2);
        CacheCell& cell = cacheCells[lo][hi];

        if (cell.oneEdge < 0 ||
            cell.oneGen1 != slotGeneration[lo] ||
            cell.oneGen2 != slotGeneration[hi]) {
            cell.oneEdge = computeOneEdgeBest(c, d);
            cell.oneGen1 = slotGeneration[lo];
            cell.oneGen2 = slotGeneration[hi];
        }
        return cell.oneEdge;
    }

    int calculateAnswer() {
        int M = *activeCounts.rbegin();

        vector<int> values(activeCounts.begin(), activeCounts.end());
        int K = (int)values.size();

        vector<int> suffixMin(K), suffixMax(K);
        for (int i = K - 1; i >= 0; --i) {
            int c = values[i];
            int mn = *group[c].begin();
            int mx = *group[c].rbegin();
            if (i + 1 < K) {
                mn = min(mn, suffixMin[i + 1]);
                mx = max(mx, suffixMax[i + 1]);
            }
            suffixMin[i] = mn;
            suffixMax[i] = mx;
        }

        int answer = 0;

        // If the two vote counts sum to at least M+2, the pair is
        // always feasible, regardless of the directed votes between them.
        int firstValid = K;
        for (int i = 0; i < K; ++i) {
            int c = values[i];
            int threshold = M - c + 2;

            while (firstValid > 0 && values[firstValid - 1] >= threshold) {
                --firstValid;
            }
            if (firstValid == K) continue;

            int mn = *group[c].begin();
            int mx = *group[c].rbegin();

            answer = max(answer, mx - suffixMin[firstValid]);
            answer = max(answer, suffixMax[firstValid] - mn);
        }

        // Counts summing to M+1.
        for (int c : values) {
            int d = M + 1 - c;
            if (c > d || d <= 0 || group[d].empty()) continue;
            answer = max(answer, getOneEdgeBest(c, d));
        }

        // Counts summing to M.
        for (int c : values) {
            int d = M - c;
            if (c > d || d <= 0 || group[d].empty()) continue;
            answer = max(answer, getNonEdgeBest(c, d));
        }

        return answer;
    }

public:
    ElectionSolver(int n, vector<int> initialVotes)
        : N(n), a(std::move(initialVotes)), cnt(n + 1, 0),
          group(n + 1), slotOf(n + 1, -1) {
        for (int v : a) ++cnt[v];

        for (int cow = 1; cow <= N; ++cow) {
            if (cnt[cow] > 0) {
                group[cnt[cow]].insert(group[cnt[cow]].end(), cow);
                activeCounts.insert(cnt[cow]);
            }
        }

        for (int c : activeCounts) allocateSlot(c);
        currentAnswer = calculateAnswer();
    }

    int update(int cow, int newVote) {
        int oldVote = a[cow];
        if (oldVote == newVote) return currentAnswer;

        a[cow] = newVote;

        int oldCount = cnt[oldVote];
        --cnt[oldVote];
        moveBetweenGroups(oldVote, oldCount, oldCount - 1);

        int newCount = cnt[newVote];
        ++cnt[newVote];
        moveBetweenGroups(newVote, newCount, newCount + 1);

        // Only relations involving this cow's outgoing vote changed.
        markDirty(cnt[cow], cnt[oldVote]);
        markDirty(cnt[cow], cnt[newVote]);

        currentAnswer = calculateAnswer();
        return currentAnswer;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> a(N + 1);
    for (int i = 1; i <= N; ++i) cin >> a[i];

    ElectionSolver solver(N, std::move(a));

    while (Q--) {
        int i, x;
        cin >> i >> x;
        cout << solver.update(i, x) << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class MaxSegTree {
    int n, base;
    vector<int> tree;

public:
    MaxSegTree(int n_, const vector<int>& values) : n(n_), base(1) {
        while (base < n) base <<= 1;
        tree.assign(2 * base, 0);

        for (int i = 1; i <= n; ++i) {
            tree[base + i - 1] = values[i];
        }
        for (int p = base - 1; p >= 1; --p) {
            tree[p] = max(tree[2 * p], tree[2 * p + 1]);
        }
    }

    void update(int pos, int value) {
        int p = base + pos - 1;
        tree[p] = value;

        for (p >>= 1; p >= 1; p >>= 1) {
            tree[p] = max(tree[2 * p], tree[2 * p + 1]);
        }
    }

    // Maximum over count values in [pos, n].
    int suffixMax(int pos) const {
        int l = base + pos - 1;
        int r = base + n;
        int result = 0;

        while (l < r) {
            if (l & 1) result = max(result, tree[l++]);
            if (r & 1) result = max(result, tree[--r]);
            l >>= 1;
            r >>= 1;
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> a(N + 1);
    vector<int> cnt(N + 1, 0);

    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        ++cnt[a[i]];
    }

    // bucket[c] contains all cows receiving exactly c votes.
    vector<set<int>> bucket(N + 1);
    for (int cow = 1; cow <= N; ++cow) {
        if (cnt[cow] > 0) {
            auto& s = bucket[cnt[cow]];
            s.insert(s.end(), cow);
        }
    }

    vector<int> exactMin(N + 1, 0);
    vector<int> exactMax(N + 1, 0);

    // The occurring positive vote counts.
    vector<int> activeCounts;
    vector<int> activePos(N + 1, -1);
    activeCounts.reserve(700);

    auto activate = [&](int c) {
        if (activePos[c] == -1) {
            activePos[c] = (int)activeCounts.size();
            activeCounts.push_back(c);
        }
    };

    auto deactivate = [&](int c) {
        int p = activePos[c];
        int last = activeCounts.back();

        activeCounts[p] = last;
        activePos[last] = p;
        activeCounts.pop_back();
        activePos[c] = -1;
    };

    for (int c = 1; c <= N; ++c) {
        if (!bucket[c].empty()) {
            activate(c);
            exactMin[c] = *bucket[c].begin();
            exactMax[c] = *bucket[c].rbegin();
        }
    }

    auto removeFromBucket = [&](int c, int cow) {
        auto& s = bucket[c];
        s.erase(cow);

        if (s.empty()) {
            deactivate(c);
            exactMin[c] = 0;
            exactMax[c] = 0;
        } else {
            exactMin[c] = *s.begin();
            exactMax[c] = *s.rbegin();
        }
    };

    auto addToBucket = [&](int c, int cow) {
        auto& s = bucket[c];
        if (s.empty()) activate(c);

        s.insert(cow);
        exactMin[c] = *s.begin();
        exactMax[c] = *s.rbegin();
    };

    // The segment tree stores the largest cow number having each exact count.
    MaxSegTree seg(N, exactMax);

    // R[t] = largest cow number receiving at least t votes.
    vector<int> R(N + 2, 0);
    for (int t = N; t >= 1; --t) {
        R[t] = max(exactMax[t], R[t + 1]);
    }

    int M = 0;
    for (int c : activeCounts) M = max(M, c);

    auto computeAnswer = [&]() {
        int answer = 0;

        for (int c : activeCounts) {
            int needed = M - c;
            if (needed < 1) needed = 1;

            answer = max(answer, R[needed] - exactMin[c]);
        }

        return answer;
    };

    int answer = computeAnswer();

    while (Q--) {
        int voter, newTarget;
        cin >> voter >> newTarget;

        int oldTarget = a[voter];

        if (oldTarget != newTarget) {
            int oldCount = cnt[oldTarget];
            int newCount = cnt[newTarget];

            // The old target's vote count changes: oldCount -> oldCount - 1.
            removeFromBucket(oldCount, oldTarget);
            if (oldCount > 1) {
                addToBucket(oldCount - 1, oldTarget);
            }

            // The new target's vote count changes: newCount -> newCount + 1.
            if (newCount > 0) {
                removeFromBucket(newCount, newTarget);
            }
            addToBucket(newCount + 1, newTarget);

            cnt[oldTarget] = oldCount - 1;
            cnt[newTarget] = newCount + 1;
            a[voter] = newTarget;

            // Update all exact-count buckets that could have changed.
            vector<int> changed;
            changed.push_back(oldCount);
            changed.push_back(oldCount - 1);
            changed.push_back(newCount);
            changed.push_back(newCount + 1);

            sort(changed.begin(), changed.end());
            changed.erase(unique(changed.begin(), changed.end()), changed.end());

            for (int c : changed) {
                if (c >= 1 && c <= N) {
                    seg.update(c, exactMax[c]);
                }
            }

            M = max(M, newCount + 1);
            while (M > 0 && exactMax[M] == 0) {
                --M;
            }

            // Threshold membership changes only at these two thresholds.
            R[oldCount] = seg.suffixMax(oldCount);
            if (newCount + 1 != oldCount) {
                R[newCount + 1] = seg.suffixMax(newCount + 1);
            }

            answer = computeAnswer();
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, A, B;
    int64 D;
    cin >> N >> D;
    cin >> A >> B;

    vector<int64> m(N);
    for (auto &x : m) cin >> x;
    sort(m.begin(), m.end());

    int64 answer = 0;
    auto addSquare = [&](int64 x) {
        int64 r = x % MOD;
        answer = (answer + r * r) % MOD;
    };

    // Only the initially largest A bottles need to be considered active.
    int inactive = N - A;
    for (int i = 0; i < inactive; ++i) addSquare(m[i]);

    vector<int64> a(m.begin() + inactive, m.end());
    vector<int64> pref(A + 1, 0), prefUpper(A + 1, 0);
    vector<int64> prefSq(A + 1, 0), prefUpperSq(A + 1, 0);

    for (int i = 0; i < A; ++i) {
        pref[i + 1] = pref[i] + a[i];
        prefUpper[i + 1] = prefUpper[i] + a[i] + D;

        int64 r1 = a[i] % MOD;
        int64 r2 = (a[i] + D) % MOD;
        prefSq[i + 1] = (prefSq[i] + r1 * r1) % MOD;
        prefUpperSq[i + 1] = (prefUpperSq[i] + r2 * r2) % MOD;
    }

    const int64 target = pref[A] + (int64)(A - B) * D;

    // At level L, bottle i has clamp(L, a[i], a[i]+D) milk.
    // Find the water-filling level for the required total amount.
    auto baseSum = [&](int64 L, int *upIndex = nullptr,
                       int *lowIndex = nullptr) -> int64 {
        int up = upper_bound(a.begin(), a.end(), L - D) - a.begin();
        int low = upper_bound(a.begin(), a.end(), L) - a.begin();

        if (upIndex) *upIndex = up;
        if (lowIndex) *lowIndex = low;

        return prefUpper[up]
             + (int64)(low - up) * L
             + (pref[A] - pref[low]);
    };

    int64 lo = 0, hi = 2000000000LL;
    while (lo < hi) {
        int64 mid = (lo + hi + 1) / 2;
        if (baseSum(mid) <= target) lo = mid;
        else hi = mid - 1;
    }

    int up, low;
    int64 base = baseSum(lo, &up, &low);
    int64 freeCount = low - up;
    int64 raised = target - base; // Number of free bottles at level lo+1.
    int64 atBase = freeCount - raised;

    auto rangeSum = [](const vector<int64> &p, int l, int r) -> int64 {
        return (p[r] - p[l] + MOD) % MOD;
    };

    // Bottles fixed at their upper bounds.
    answer = (answer + rangeSum(prefUpperSq, 0, up)) % MOD;
    // Bottles fixed at their initial amounts.
    answer = (answer + rangeSum(prefSq, low, A)) % MOD;

    int64 r0 = lo % MOD;
    int64 r1 = (lo + 1) % MOD;
    answer = (answer + (atBase % MOD) * r0 % MOD * r0) % MOD;
    answer = (answer + (raised % MOD) * r1 % MOD * r1) % MOD;

    cout << answer << '\n';
    return 0;
}

