    vector<int64> m(N);
    for (auto &x : m) cin >> x;

    sort(m.begin(), m.end(), greater<int64>());

    int64 answer = 0;
    for (int i = A; i < N; ++i) {
        int64 v = m[i] % MOD;
        answer = (answer + v * v) % MOD;
    }

    int64 initialSum = 0;
    for (int i = 0; i < A; ++i) initialSum += m[i];

    const int64 total = initialSum + int64(A - B) * D;
    const int64 upperLimit = m[0] + D;

    auto clampedSum = [&](int64 q) {
        int64 sum = 0;
        for (int i = 0; i < A; ++i) {
            if (q <= m[i]) {
                sum += m[i];
            } else if (q >= m[i] + D) {
                sum += m[i] + D;
            } else {
                sum += q;
            }
        }
        return sum;
    };

    // Find an integer water level q with clampedSum(q) <= total.
    int64 lo = 0, hi = upperLimit;
    while (lo < hi) {
        int64 mid = lo + (hi - lo + 1) / 2;
        if (clampedSum(mid) <= total)
            lo = mid;
        else
            hi = mid - 1;
    }
    const int64 q = lo;

    int64 baseSum = 0;
    for (int i = 0; i < A; ++i) {
        int64 v;
        if (q <= m[i]) {
            v = m[i];
        } else if (q >= m[i] + D) {
            v = m[i] + D;
        } else {
            v = q;
        }

        baseSum += v;
        int64 z = v % MOD;
        answer = (answer + z * z) % MOD;
    }

    // The remaining bottles increase from q to q+1.
    const int64 remaining = total - baseSum;
    int64 increment = (2 * q + 1) % MOD;
    answer = (answer + (remaining % MOD) * increment) % MOD;

    cout << answer << '\n';
