    const long long MOD = 1000000007LL;

    int fixed = N - A;
    long long answer = 0;

    for (int i = 0; i < fixed; i++) {
        long long v = m[i] % MOD;
        answer = (answer + v * v) % MOD;
    }

    vector<long long> a;
    a.reserve(A);
    for (int i = fixed; i < N; i++) {
        a.push_back(m[i]);
    }

    long long C = (long long)A - B;
    long long T = C * D;

    long long minA = a.front();
    long long maxA = a.back();

    auto cost = [&](long long level) -> long long {
        long long res = 0;
        for (long long x : a) {
            if (level > x) {
                long long diff = level - x;
                res += min(D, diff);
            }
        }
        return res;
    };

    long long lo = minA - 1;
    long long hi = maxA + D + 1;

    while (hi - lo > 1) {
        long long mid = lo + (hi - lo) / 2;
        if (cost(mid) <= T) lo = mid;
        else hi = mid;
    }

    long long level = lo;
    long long used = cost(level);
    long long remaining = T - used;

    long long activeSq = 0;

    for (long long x : a) {
        long long base;
        if (x >= level) {
            base = x;
        } else if (x + D <= level) {
            base = x + D;
        } else {
            base = level;
        }

