int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long D;
    cin >> N >> D;

    int A, B;
    cin >> A >> B;

    vector<long long> m(N);
    for (long long &x : m) cin >> x;

    sort(m.begin(), m.end());

    int bottom = N - A;
    vector<long long> b(m.begin() + bottom, m.end()); // active A bottles, ascending

    long long K = A - B;
    long long sumB = 0;
    for (long long x : b) sumB += x;

    long long target = sumB + K * D;

    auto calc = [&](long long h) -> long long {
        long long s = 0;
        for (long long x : b) {
            if (x >= h) s += x;
            else if (x + D <= h) s += x + D;
            else s += h;
        }
        return s;
    };

    long long lo = b.front();
    long long hi = b.back() + D;

    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (calc(mid) >= target) hi = mid;
        else lo = mid + 1;
    }

    long long h = lo;
    long long Sh = calc(h);
    long long overshoot = Sh - target;

    const long long MOD = 1000000007LL;

    auto addSquare = [&](long long v, long long &ans) {
        v %= MOD;
        ans = (ans + v * v) % MOD;
    };

    long long ans = 0;

    // Bottles below the top A are never changed.
    for (int i = 0; i < bottom; i++) {
        addSquare(m[i], ans);
    }

    long long activeCount = 0;

    for (long long x : b) {
        if (x + D < h) {
            addSquare(x + D, ans);
        } else if (x >= h) {
            addSquare(x, ans);
        } else {
            activeCount++;
        }
    }

    long long R = overshoot;

    long long hm = h % MOD;
    long long h2 = hm * hm % MOD;

    long long hm1 = (h - 1) % MOD;
    long long hm12 = hm1 * hm1 % MOD;

    long long cntH = (activeCount - R) % MOD;
    long long cntHm1 = R % MOD;

    ans = (ans + cntH * h2) % MOD;
    ans = (ans + cntHm1 * hm12) % MOD;

    cout << ans % MOD << '\n';
    return 0;
}

#include <bits/stdc++.h>
