using int64 = long long;
constexpr int64 MOD = 1'000'000'007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    int64 D;
    cin >> N >> D;

    int A, B;
    cin >> A >> B;

    vector<int64> milk(N);
    for (int64 &x : milk) cin >> x;
    sort(milk.begin(), milk.end());

    // Only the largest A bottles can ever be changed.
    vector<int64> active(milk.begin() + (N - A), milk.end());

    const int64 C = A - B;
    const int64 need = C * D;

    // Number of possible increment events with pre-increment value <= level.
    auto countEvents = [&](int64 level) -> int64 {
        int64 result = 0;
        for (int64 x : active) {
            if (level < x) break;
            result += min(D, level - x + 1);
        }
        return result;
    };

    // Find the level of the need-th smallest possible increment event.
    int64 low = active.front();
    int64 high = active.back() + D - 1;

    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (countEvents(mid) >= need) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    const int64 q = low;
    const int64 selectedAtQ = need - countEvents(q - 1);

    auto squareMod = [](int64 x) -> int64 {
        x %= MOD;
        if (x < 0) x += MOD;
        return x * x % MOD;
    };

    int64 answer = 0;

    // The N-A smallest bottles never change.
    for (int i = 0; i < N - A; ++i) {
        answer = (answer + squareMod(milk[i])) % MOD;
    }

    int64 partialCount = 0;

    for (int64 x : active) {
        if (x > q) {
            // None of this bottle's increment events is selected.
            answer = (answer + squareMod(x)) % MOD;
        } else if (x + D - 1 < q) {
            // All D possible increment events are selected.
            answer = (answer + squareMod(x + D)) % MOD;
        } else {
            // This bottle ends with either q or q+1.
            ++partialCount;
        }
    }

    // Exactly selectedAtQ partial bottles receive the event of value q,
    // changing their final amount from q to q+1.
    answer = (answer
              + ((partialCount - selectedAtQ) % MOD) * squareMod(q)) % MOD;
    answer = (answer
              + (selectedAtQ % MOD) * squareMod(q + 1)) % MOD;

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

constexpr int64 MOD = 1'000'000'007LL;

int64 squareMod(int64 x) {
    x %= MOD;
    return x * x % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    int64 D;
    cin >> N >> D;

    int A, B;
    cin >> A >> B;

    vector<int64> m(N);
    for (int64 &x : m) cin >> x;
    sort(m.rbegin(), m.rend());

    const int64 K = A - B;
    const int64 M = K * D;

    /*
       Only the initial A largest bottles ever participate.

       For an active bottle initially containing x, its possible marginal
       increment levels are:
           x, x+1, ..., x+D-1.

       After D days, exactly M = K*D marginal increments are chosen.
    */

    auto countLe = [&](int64 z) -> int64 {
        int64 count = 0;
        for (int i = 0; i < A; ++i) {
            if (z < m[i]) continue;
            count += min(D, z - m[i] + 1);
        }
        return count;
    };

    // Find the level of the M-th smallest marginal increment.
    int64 lo = m[A - 1];
    int64 hi = m[0] + D - 1;

    while (lo < hi) {
        int64 mid = lo + (hi - lo) / 2;
        if (countLe(mid) >= M) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }

    const int64 z = lo;

    // Number of marginal increments strictly smaller than z.
    int64 below = 0;
    for (int i = 0; i < A; ++i) {
        if (z > m[i]) {
            below += min(D, z - m[i]);
        }
    }

    // Number of increments selected at level z.
    const int64 selectedAtZ = M - below;

    int64 answer = 0;

    for (int i = 0; i < N; ++i) {
        int64 finalAmount;

        if (i < A) {
            const int64 x = m[i];

            if (x > z) {
                // No increments selected for this bottle.
                finalAmount = x;
            } else if (x + D <= z) {
                // All D possible increments were selected.
                finalAmount = x + D;
            } else {
                // Baseline amount; selectedAtZ of these become z+1.
                finalAmount = z;
            }
        } else {
            // These bottles are never filled or stolen from.
            finalAmount = m[i];
        }

        answer = (answer + squareMod(finalAmount)) % MOD;
    }

    // Replacing z by z+1 changes the square sum by 2z+1.
    const int64 delta = (2 * (z % MOD) + 1) % MOD;
    answer = (answer + (selectedAtZ % MOD) * delta) % MOD;

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

static constexpr int64 MOD = 1'000'000'007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, A, B;
    int64 D;

    cin >> N >> D;
    cin >> A >> B;

    vector<int64> m(N);
    for (int64 &x : m) cin >> x;

    sort(m.begin(), m.end(), greater<int64>());

    const int K = A - B;

    // Farmer John optimally fills these same A bottles every day.
    vector<int64> lower(A), upper(A), finalAmount(A);

    int64 target = 0;
    for (int i = 0; i < A; ++i) {
        lower[i] = m[i];
        upper[i] = m[i] + D;
        target += lower[i];
    }
    target += int64(K) * D;

    auto levelSum = [&](int64 h) -> int64 {
        int64 sum = 0;
        for (int i = 0; i < A; ++i) {
            sum += min(upper[i], max(lower[i], h));
        }
        return sum;
    };

    // Find the water level h such that clamping every selected bottle
    // to h gives a total not exceeding target.
    int64 low = 0;
    int64 high = m[0] + D;

    while (low < high) {
        int64 mid = low + (high - low + 1) / 2;
        if (levelSum(mid) <= target) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }

    const int64 h = low;
    int64 currentSum = 0;

    for (int i = 0; i < A; ++i) {
        finalAmount[i] = min(upper[i], max(lower[i], h));
        currentSum += finalAmount[i];
    }

    // Distribute the remaining units among bottles whose level can
    // be increased from h to h+1.
    int64 remaining = target - currentSum;
    for (int i = 0; i < A && remaining > 0; ++i) {
        if (lower[i] <= h && h < upper[i]) {
            ++finalAmount[i];
            --remaining;
        }
    }

    int64 answer = 0;

    auto addSquare = [&](int64 x) {
        int64 square = static_cast<int64>(static_cast<i128>(x) * x % MOD);
        answer += square;
        if (answer >= MOD) answer -= MOD;
    };

    for (int i = A; i < N; ++i) {
        addSquare(m[i]);
    }
    for (int64 x : finalAmount) {
        addSquare(x);
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n = 0;
    vector<long long> bit;

    Fenwick() {}
    explicit Fenwick(int n_) { init(n_); }

    void init(int n_) {
        n = n_;
        bit.assign(n + 1, 0);
    }

    void add(int i, long long v) {
        for (; i <= n; i += i & -i) bit[i] += v;
    }

    long long sum(int i) const {
        long long res = 0;
        for (; i > 0; i -= i & -i) res += bit[i];
        return res;
    }

    // Range addition, point queries.
    void rangeAdd(int l, int r, long long v) {
        if (l > r) return;
        add(l, v);
        if (r + 1 <= n) add(r + 1, -v);
    }

    long long pointQuery(int i) const {
        return sum(i);
    }
};

struct CycleComponent {
    vector<int> nodes;
    int offset = 0;
    set<int> parties; // Local positions on the cycle.
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    for (int i = 1; i <= N; i++) cin >> a[i];

    int M;
    cin >> M;

    // Remove non-cycle vertices using in-degree peeling.
    vector<int> deg(N + 1, 0);
    for (int i = 1; i <= N; i++) deg[a[i]]++;

    queue<int> q;
    for (int i = 1; i <= N; i++) {
        if (deg[i] == 0) q.push(i);
    }

    while (!q.empty()) {
        int v = q.front();
        q.pop();
        if (--deg[a[v]] == 0) q.push(a[v]);
    }

    vector<char> isCycle(N + 1, false);
    for (int i = 1; i <= N; i++) {
        if (deg[i] > 0) isCycle[i] = true;
    }

    vector<CycleComponent> comps;
    vector<int> compOf(N + 1, -1), cyclePos(N + 1, -1);
    vector<char> seen(N + 1, false);
    vector<int> roots;

    int totalCycleVertices = 0;

    for (int i = 1; i <= N; i++) {
        if (!isCycle[i] || seen[i]) continue;

        int id = (int)comps.size();
        CycleComponent comp;
        comp.offset = totalCycleVertices;

        int v = i, p = 0;
        do {
            seen[v] = true;
            compOf[v] = id;
            cyclePos[v] = p++;
            comp.nodes.push_back(v);
            roots.push_back(v);
            v = a[v];
        } while (v != i);

        totalCycleVertices += p;
        comps.push_back(std::move(comp));
    }

    // Each cycle vertex roots a tree directed towards that cycle vertex.
    vector<vector<int>> children(N + 1);
    for (int i = 1; i <= N; i++) {
        if (!isCycle[i]) children[a[i]].push_back(i);
    }

    vector<int> parent(N + 1, 0), treeRoot(N + 1, 0);
    vector<int> order;
    order.reserve(N);

    vector<int> st;
    for (int r : roots) {
        parent[r] = 0;
        treeRoot[r] = r;
        st.push_back(r);

        while (!st.empty()) {
            int v = st.back();
            st.pop_back();
            order.push_back(v);

            for (int u : children[v]) {
                parent[u] = v;
                treeRoot[u] = r;
                st.push_back(u);
            }
        }
    }

    vector<long long> subtreeSize(N + 1, 1);
    for (auto it = order.rbegin(); it != order.rend(); ++it) {
        int v = *it;
        if (parent[v]) subtreeSize[parent[v]] += subtreeSize[v];
    }

    // Heavy-light decomposition of the rooted forest.
    vector<int> heavy(N + 1, 0);
    for (int v = 1; v <= N; v++) {
        for (int u : children[v]) {
            if (!heavy[v] || subtreeSize[u] > subtreeSize[heavy[v]]) {
                heavy[v] = u;
            }
        }
    }

    vector<int> head(N + 1, 0), pos(N + 1, 0), rev(N + 1, 0);
    int timer = 1;

    vector<pair<int, int>> decomposeStack;
    for (int r : roots) decomposeStack.push_back({r, r});

    while (!decomposeStack.empty()) {
        auto [start, h] = decomposeStack.back();
        decomposeStack.pop_back();

        int v = start;
        while (v) {
            head[v] = h;
            pos[v] = timer;
            rev[timer] = v;
            timer++;

            for (int u : children[v]) {
                if (u != heavy[v]) decomposeStack.push_back({u, u});
            }
            v = heavy[v];
        }
    }

    // F(v): if v is unmarked, the sum of subtree sizes of the topmost
    // parties below v; if v is marked, F(v) = subtreeSize[v].
    Fenwick treeDelta(N);
    vector<set<int>> chainMarks(N + 1);

    auto nearestMarkedAncestor = [&](int v) {
        while (v) {
            auto &marks = chainMarks[head[v]];
            auto it = marks.upper_bound(pos[v]);
            if (it != marks.begin()) {
                --it;
                return rev[*it];
            }
            v = parent[head[v]];
        }
        return 0;
    };

    // Add delta on the path from v upwards, stopping just below p.
    // p = 0 means update through the root.
    auto addVisiblePath = [&](int v, int p, long long delta) {
        if (p == 0) {
            while (v) {
                treeDelta.rangeAdd(pos[head[v]], pos[v], delta);
                v = parent[head[v]];
            }
            return;
        }

        while (head[v] != head[p]) {
            treeDelta.rangeAdd(pos[head[v]], pos[v], delta);
            v = parent[head[v]];
        }
        treeDelta.rangeAdd(pos[p] + 1, pos[v], delta);
    };

    // Number of cows from each cycle tree that still reach the cycle.
    Fenwick cycleWeights(totalCycleVertices);
    for (const auto &comp : comps) {
        for (int i = 0; i < (int)comp.nodes.size(); i++) {
            cycleWeights.add(comp.offset + i + 1,
                             subtreeSize[comp.nodes[i]]);
        }
    }

    auto cycleRangeSum = [&](const CycleComponent &comp, int l, int r) {
        if (l > r) return 0LL;
        return cycleWeights.sum(comp.offset + r + 1)
             - cycleWeights.sum(comp.offset + l);
    };

    // For a marked vertex, sum of subtree sizes of its topmost marked
    // descendants in the virtual party tree.
    vector<long long> below(N + 1, 0);
    vector<int> color(N + 1, 0); // 0 = no party, 1 = C, 2 = O, 3 = W.
    long long answer[4] = {0, 0, 0, 0};

    auto insertParty = [&](int v, int newColor) {
        long long previousTopmost = treeDelta.pointQuery(pos[v]);
        int p = nearestMarkedAncestor(v);
        long long delta = subtreeSize[v] - previousTopmost;

        addVisiblePath(v, p, delta);
        below[v] = previousTopmost;
        if (p) below[p] += delta;

        color[v] = newColor;
        chainMarks[head[v]].insert(pos[v]);

        if (p) {
            // The new party takes delta attendees from its nearest party ancestor.
            answer[color[p]] -= delta;
            answer[newColor] += delta;
            return;
        }

        if (!isCycle[v]) {
            // The residual weight of this cycle tree decreases.
            int r = treeRoot[v];
            CycleComponent &comp = comps[compOf[r]];
            int j = cyclePos[r];

            if (!comp.parties.empty()) {
                auto it = comp.parties.lower_bound(j);
                if (it == comp.parties.end()) it = comp.parties.begin();
                int nextParty = comp.nodes[*it];
                answer[color[nextParty]] -= delta;
            }

            answer[newColor] += delta;
            cycleWeights.add(comp.offset + j + 1, -delta);
            return;
        }

        // Inserting a party directly on a cycle.
        CycleComponent &comp = comps[compOf[v]];
        int i = cyclePos[v];
        int len = (int)comp.nodes.size();
        long long gained;

        if (comp.parties.empty()) {
            gained = cycleRangeSum(comp, 0, len - 1);
        } else {
            auto it = comp.parties.lower_bound(i);
            if (it == comp.parties.begin()) it = comp.parties.end();
            --it;
            int previous = *it;

            auto jt = comp.parties.upper_bound(i);
            if (jt == comp.parties.end()) jt = comp.parties.begin();
            int nextParty = comp.nodes[*jt];

            // Residual weights in the cyclic arc (previous, i].
            if (previous < i) {
                gained = cycleRangeSum(comp, previous + 1, i);
            } else {
                gained = cycleRangeSum(comp, previous + 1, len - 1)
                       + cycleRangeSum(comp, 0, i);
            }

            answer[color[nextParty]] -= gained;
        }

        answer[newColor] += gained;

        // The old residual weight at this root was exactly delta.
        cycleWeights.add(comp.offset + i + 1, -delta);
        comp.parties.insert(i);
    };

    auto cyclePartyBasin = [&](int v) {
        CycleComponent &comp = comps[compOf[v]];
        int i = cyclePos[v];
        int len = (int)comp.nodes.size();

        auto it = comp.parties.lower_bound(i);
        if (it == comp.parties.begin()) it = comp.parties.end();
        --it;
        int previous = *it;

        // Residual weights strictly between previous and i on the cycle.
        long long residual;
        if (previous < i) {
            residual = cycleRangeSum(comp, previous + 1, i - 1);
        } else {
            residual = cycleRangeSum(comp, previous + 1, len - 1)
                     + cycleRangeSum(comp, 0, i - 1);
        }

        return subtreeSize[v] - below[v] + residual;
    };

    while (M--) {
        int v;
        char type;
        cin >> v >> type;

        int newColor = (type == 'C' ? 1 : (type == 'O' ? 2 : 3));

        if (color[v] == 0) {
            insertParty(v, newColor);
        } else if (color[v] != newColor) {
            long long basin;
            if (isCycle[v]) basin = cyclePartyBasin(v);
            else basin = subtreeSize[v] - below[v];

            answer[color[v]] -= basin;
            answer[newColor] += basin;
            color[v] = newColor;
        }

        cout << answer[1] << ' ' << answer[2] << ' ' << answer[3] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Info {
    int sz = 0;
    int cnt[3] = {0, 0, 0};
};

static inline void addInfo(Info &a, const Info &b, int sign = 1) {
    a.sz += sign * b.sz;
    for (int t = 0; t < 3; ++t) a.cnt[t] += sign * b.cnt[t];
}

struct LinkCutTree {
    int n;
    vector<array<int, 2>> ch;
    vector<int> fa, stk;
    vector<unsigned char> rev;
    vector<Info> base, vir, sum;

    explicit LinkCutTree(int n_) : n(n_), ch(n_ + 1), fa(n_ + 1, 0),
        stk(n_ + 1), rev(n_ + 1, 0), base(n_ + 1), vir(n_ + 1), sum(n_ + 1) {
        for (int i = 1; i <= n; ++i) {
            ch[i] = {0, 0};
            base[i].sz = 1;
            pull(i);
        }
    }

    bool isRoot(int x) const {
        int p = fa[x];
        return p == 0 || (ch[p][0] != x && ch[p][1] != x);
    }

    void pull(int x) {
        sum[x] = base[x];
        addInfo(sum[x], vir[x]);
        if (ch[x][0]) addInfo(sum[x], sum[ch[x][0]]);
        if (ch[x][1]) addInfo(sum[x], sum[ch[x][1]]);
    }

    void push(int x) {
        if (!rev[x]) return;
        swap(ch[x][0], ch[x][1]);
        if (ch[x][0]) rev[ch[x][0]] ^= 1;
        if (ch[x][1]) rev[ch[x][1]] ^= 1;
        rev[x] = 0;
    }

    void rotate(int x) {
        int y = fa[x], z = fa[y];
        int dx = (ch[y][1] == x);
        int dy = (ch[z][1] == y);

        if (!isRoot(y)) ch[z][dy] = x;
        fa[x] = z;

        int b = ch[x][dx ^ 1];
        ch[y][dx] = b;
        if (b) fa[b] = y;

        ch[x][dx ^ 1] = y;
        fa[y] = x;

        pull(y);
        pull(x);
    }

    void splay(int x) {
        int top = 0, y = x;
        stk[top++] = y;
        while (!isRoot(y)) {
            y = fa[y];
            stk[top++] = y;
        }
        while (top) push(stk[--top]);

        while (!isRoot(x)) {
            y = fa[x];
            int z = fa[y];
            if (!isRoot(y)) {
                bool zigzig = ((ch[y][0] == x) == (ch[z][0] == y));
                rotate(zigzig ? y : x);
            }
            rotate(x);
        }
    }

    void access(int x) {
        int y = 0;
        for (int u = x; u; u = fa[u]) {
            splay(u);
            if (ch[u][1]) addInfo(vir[u], sum[ch[u][1]], 1);
            if (y) addInfo(vir[u], sum[y], -1);
            ch[u][1] = y;
            pull(u);
            y = u;
        }
        splay(x);
    }

    void makeRoot(int x) {
        access(x);
        rev[x] ^= 1;
    }

    int findRoot(int x) {
        access(x);
        while (true) {
            push(x);
            if (!ch[x][0]) break;
            x = ch[x][0];
        }
        splay(x);
        return x;
    }

    bool link(int x, int y) {
        makeRoot(x);
        if (findRoot(y) == x) return false;
        access(y);
        fa[x] = y;
        addInfo(vir[y], sum[x], 1);
        pull(y);
        return true;
    }

    void cut(int x, int y) {
        makeRoot(x);
        access(y);
        // x and y are directly adjacent, with x the left child of y.
        ch[y][0] = 0;
        fa[x] = 0;
        pull(y);
    }

    Info componentInfo(int x) {
        return sum[findRoot(x)];
    }

    void changeParty(int x, int oldType, int newType) {
        access(x);
        if (oldType >= 0) --base[x].cnt[oldType];
        ++base[x].cnt[newType];
        pull(x);
    }
};

struct DSU {
    vector<int> p, sz;
    explicit DSU(int n) : p(n + 1), sz(n + 1, 1) {
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> a(N + 1);
    for (int i = 1; i <= N; ++i) cin >> a[i];

    DSU dsu(N);
    vector<int> indeg(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        dsu.unite(i, a[i]);
        ++indeg[a[i]];
    }

    // Mark vertices lying on directed cycles by removing all tree vertices.
    queue<int> q;
    for (int i = 1; i <= N; ++i) {
        if (indeg[i] == 0) q.push(i);
    }
    while (!q.empty()) {
        int v = q.front(); q.pop();
        if (--indeg[a[v]] == 0) q.push(a[v]);
    }
    vector<unsigned char> onCycle(N + 1, 0);
    for (int i = 1; i <= N; ++i) onCycle[i] = (indeg[i] > 0);

    vector<int> comp(N + 1);
    for (int i = 1; i <= N; ++i) comp[i] = dsu.find(i);

    LinkCutTree lct(N);

    // Each component initially has one extra edge closing its unique cycle.
    // All other edges are stored in the link-cut forest.
    vector<int> extra(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        if (i == a[i]) {
            extra[comp[i]] = i;
        } else if (!lct.link(i, a[i])) {
            extra[comp[i]] = i;
        }
    }

    int M;
    cin >> M;

    vector<int> partyType(N + 1, -1);
    long long answer[3] = {0, 0, 0};

    auto typeOf = [](char c) {
        if (c == 'C') return 0;
        if (c == 'O') return 1;
        return 2;
    };

    while (M--) {
        int v;
        char vc;
        cin >> v >> vc;
        int nt = typeOf(vc);

        if (partyType[v] != -1) {
            int ot = partyType[v];
            int attendees = lct.componentInfo(v).sz;
            answer[ot] -= attendees;
            answer[nt] += attendees;
            lct.changeParty(v, ot, nt);
            partyType[v] = nt;
        } else {
            Info before = lct.componentInfo(v);
            int ot = -1;
            for (int t = 0; t < 3; ++t) {
                if (before.cnt[t] > 0) ot = t;
            }

            int id = comp[v];
            int ex = extra[id];

            if (ot == -1) {
                // The component still contains its original directed cycle.
                if (v == ex) {
                    // Removing the already omitted edge breaks the cycle.
                    extra[id] = 0;
                } else if (onCycle[v]) {
                    // Replace the removed cycle edge by the omitted one,
                    // preserving undirected connectivity.
                    lct.cut(v, a[v]);
                    lct.link(ex, a[ex]);
                    extra[id] = 0;
                } else {
                    // A tree edge is cut; the cycle remains in the other part.
                    lct.cut(v, a[v]);
                }
            } else {
                // This component already has a party at its root.
                lct.cut(v, a[v]);
            }

            int attendees = lct.componentInfo(v).sz;
            if (ot != -1) answer[ot] -= attendees;
            answer[nt] += attendees;

            lct.changeParty(v, -1, nt);
            partyType[v] = nt;
        }

        cout << answer[0] << ' ' << answer[1] << ' ' << answer[2] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;

    explicit Fenwick(int n_) : n(n_), bit(n_ + 1, 0) {}

    void add(int idx, long long val) {
        for (int i = idx + 1; i <= n; i += i & -i) bit[i] += val;
    }

    long long prefix(int idx) const {
        long long res = 0;
        for (int i = idx + 1; i > 0; i -= i & -i) res += bit[i];
        return res;
    }

    long long rangeSum(int l, int r) const {
        if (l > r) return 0;
        return prefix(r) - (l ? prefix(l - 1) : 0);
    }
};

struct MaxSeg {
    int n;
    vector<pair<int, int>> tree; // (depth, vertex)

    static pair<int, int> better(const pair<int, int>& a,
                                 const pair<int, int>& b) {
        return a.first > b.first ? a : b;
    }

    explicit MaxSeg(int n_) : n(n_), tree(2 * n_, {-1, 0}) {}

    void update(int pos, int depth, int vertex) {
        int p = pos + n;
        tree[p] = {depth, vertex};
        for (p >>= 1; p; p >>= 1)
            tree[p] = better(tree[p << 1], tree[p << 1 | 1]);
    }

    pair<int, int> query(int l, int r) const {
        pair<int, int> res = {-1, 0};
        for (l += n, r += n + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res = better(res, tree[l++]);
            if (r & 1) res = better(res, tree[--r]);
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1), indeg(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        ++indeg[a[i]];
    }

    // Find cycle vertices by removing all tree vertices.
    vector<char> isCycle(N + 1, true);
    queue<int> que;
    for (int i = 1; i <= N; ++i) {
        if (indeg[i] == 0) que.push(i);
    }
    while (!que.empty()) {
        int v = que.front();
        que.pop();
        isCycle[v] = false;
        if (--indeg[a[v]] == 0) que.push(a[v]);
    }

    // Reverse edges, excluding edges between cycle vertices, form rooted trees.
    vector<vector<int>> children(N + 1);
    for (int v = 1; v <= N; ++v) {
        if (!isCycle[v]) children[a[v]].push_back(v);
    }

    vector<int> comp(N + 1, -1), cyclePos(N + 1, -1), globalCycleIdx(N + 1, -1);
    vector<int> compStart, compEnd;
    vector<int> cycleNode;
    vector<set<int>> activeCycleParties;

    for (int i = 1; i <= N; ++i) {
        if (!isCycle[i] || comp[i] != -1) continue;

        int id = (int)compStart.size();
        int start = (int)cycleNode.size();
        int pos = 0;
        int v = i;

        do {
            comp[v] = id;
            cyclePos[v] = pos++;
            globalCycleIdx[v] = (int)cycleNode.size();
            cycleNode.push_back(v);
            v = a[v];
        } while (v != i);

        compStart.push_back(start);
        compEnd.push_back((int)cycleNode.size());
        activeCycleParties.emplace_back();
    }

    int K = (int)cycleNode.size();

    vector<int> parent(N + 1, 0), depth(N + 1, 0), root(N + 1, 0);
    vector<int> sz(N + 1, 1), heavy(N + 1, 0);
    vector<int> order;
    order.reserve(N);

    for (int r : cycleNode) {
        root[r] = r;
        stack<int> st;
        st.push(r);

        while (!st.empty()) {
            int v = st.top();
            st.pop();
            order.push_back(v);

            for (int u : children[v]) {
                parent[u] = v;
                depth[u] = depth[v] + 1;
                root[u] = r;
                comp[u] = comp[r];
                st.push(u);
            }
        }
    }

    for (auto it = order.rbegin(); it != order.rend(); ++it) {
        int v = *it;
        int p = parent[v];
        if (p) {
            sz[p] += sz[v];
            if (!heavy[p] || sz[v] > sz[heavy[p]]) heavy[p] = v;
        }
    }

    // Heavy-light decomposition. Its numbering also gives contiguous subtrees.
    vector<int> head(N + 1, 0), dfn(N + 1, 0);
    int timer = 0;

    for (int r : cycleNode) {
        stack<pair<int, int>> st;
        st.emplace(r, r);

        while (!st.empty()) {
            auto [v, h] = st.top();
            st.pop();

            int u = v;
            while (u) {
                head[u] = h;
                dfn[u] = timer++;

                for (int w : children[u]) {
                    if (w != heavy[u]) st.emplace(w, w);
                }
                u = heavy[u];
            }
        }
    }

    Fenwick cycleWeights(K);
    for (int r : cycleNode) {
        cycleWeights.add(globalCycleIdx[r], sz[r]);
    }

    // For non-cycle parties, a subtree query gives the sum of subtree sizes
    // of the highest existing parties in that subtree.
    Fenwick treeCoefficients(N);
    MaxSeg nearestPartySeg(N);

    auto nearestTreeParty = [&](int v) {
        int u = v;
        while (u) {
            auto res = nearestPartySeg.query(dfn[head[u]], dfn[u]);
            if (res.first != -1) return res.second;
            u = parent[head[u]];
        }
        return 0;
    };

    vector<int> state(N + 1, 0); // 0 = none, 1 = C, 2 = O, 3 = W
    vector<long long> area(N + 1, 0);
    long long answer[4] = {0, 0, 0, 0};

    int M;
    cin >> M;

    while (M--) {
        int v;
        char type;
        cin >> v >> type;

        int color = (type == 'C' ? 1 : (type == 'O' ? 2 : 3));

        if (state[v]) {
            int old = state[v];
            if (old != color) {
                answer[old] -= area[v];
                answer[color] += area[v];
                state[v] = color;
            }
        } else if (!isCycle[v]) {
            int p = nearestTreeParty(v);

            long long covered = treeCoefficients.rangeSum(
                dfn[v], dfn[v] + sz[v] - 1);
            long long gained = (long long)sz[v] - covered;

            treeCoefficients.add(dfn[v], gained);

            if (p) {
                treeCoefficients.add(dfn[p], -gained);
                area[p] -= gained;
                answer[state[p]] -= gained;
            } else {
                int r = root[v];
                cycleWeights.add(globalCycleIdx[r], -gained);

                int cid = comp[r];
                auto& parties = activeCycleParties[cid];

                if (!parties.empty()) {
                    auto it = parties.lower_bound(cyclePos[r]);
                    int qpos = (it == parties.end() ? *parties.begin() : *it);
                    int q = cycleNode[compStart[cid] + qpos];

                    area[q] -= gained;
                    answer[state[q]] -= gained;
                }
            }

            state[v] = color;
            area[v] = gained;
            answer[color] += gained;
            nearestPartySeg.update(dfn[v], depth[v], v);
        } else {
            int cid = comp[v];
            int pos = cyclePos[v];
            int start = compStart[cid];
            int end = compEnd[cid];
            int len = end - start;
            auto& parties = activeCycleParties[cid];

            long long gained;

            if (parties.empty()) {
                gained = cycleWeights.rangeSum(start, end - 1);
            } else {
                auto it = parties.lower_bound(pos);

                int previousPos;
                if (it == parties.begin()) {
                    previousPos = *prev(parties.end());
                } else {
                    --it;
                    previousPos = *it;
                }

                auto nextIt = parties.lower_bound(pos);
                int nextPos = (nextIt == parties.end()
                                   ? *parties.begin()
                                   : *nextIt);
                int nextParty = cycleNode[start + nextPos];

                if (previousPos < pos) {
                    gained = cycleWeights.rangeSum(
                        start + previousPos + 1, start + pos);
                } else {
                    gained = 0;
                    if (previousPos + 1 < len) {
                        gained += cycleWeights.rangeSum(
                            start + previousPos + 1, end - 1);
                    }
                    gained += cycleWeights.rangeSum(start, start + pos);
                }

                area[nextParty] -= gained;
                answer[state[nextParty]] -= gained;
            }

            state[v] = color;
            area[v] = gained;
            answer[color] += gained;
            parties.insert(pos);
        }

        cout << answer[1] << ' ' << answer[2] << ' ' << answer[3] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 200005;

struct LinkCut {
    int ch[MAXN][2], fa[MAXN], vir[MAXN], siz[MAXN];

    void init(int n) {
        for (int i = 1; i <= n; i++) {
            ch[i][0] = ch[i][1] = 0;
            fa[i] = vir[i] = 0;
            siz[i] = 1;
        }
        siz[0] = vir[0] = 0;
    }

    bool isRoot(int x) {
        return fa[x] == 0 ||
               (ch[fa[x]][0] != x && ch[fa[x]][1] != x);
    }

    void pushUp(int x) {
        siz[x] = 1 + vir[x] + siz[ch[x][0]] + siz[ch[x][1]];
    }

    void rotate(int x) {
        int y = fa[x], z = fa[y];
        int dx = (ch[y][1] == x);
        int b = ch[x][dx ^ 1];

        if (!isRoot(y)) {
            if (ch[z][0] == y) ch[z][0] = x;
            else if (ch[z][1] == y) ch[z][1] = x;
        }

        fa[x] = z;
        ch[x][dx ^ 1] = y;
        fa[y] = x;
        ch[y][dx] = b;
        if (b) fa[b] = y;

        pushUp(y);
        pushUp(x);
    }

    void splay(int x) {
        while (!isRoot(x)) {
            int y = fa[x], z = fa[y];
            if (!isRoot(y)) {
                if ((ch[y][0] == x) ^ (ch[z][0] == y)) rotate(x);
                else rotate(y);
            }
            rotate(x);
        }
    }

    void access(int x) {
        int last = 0;
        for (int u = x; u; u = fa[u]) {
            splay(u);

            int old = ch[u][1];
            if (old) vir[u] += siz[old];
            if (last) vir[u] -= siz[last];

            ch[u][1] = last;
            if (last) fa[last] = u;

            pushUp(u);
            last = u;
        }
        splay(x);
    }

    int findRoot(int x) {
        access(x);
        while (ch[x][0]) x = ch[x][0];
        splay(x);
        return x;
    }

    int subtreeSize(int x) {
        access(x);
        return 1 + vir[x];
    }

    int componentSize(int root) {
        access(root);
        return 1 + vir[root];
    }

    void link(int x, int y) {
        access(x);
        access(y);
        fa[x] = y;
        vir[y] += siz[x];
        pushUp(y);
    }

    void cutParent(int x) {
        access(x);
        int l = ch[x][0];
        ch[x][0] = 0;
        if (l) fa[l] = 0;
        pushUp(x);
    }
};

int N, M;
int a[MAXN];
bool isCycle[MAXN];
bool removedEdge[MAXN];
bool activeCow[MAXN];
int typ[MAXN];
int basinSize[MAXN];

LinkCut lct;

int id(char c) {
    if (c == 'C') return 0;
    if (c == 'O') return 1;
    return 2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    for (int i = 1; i <= N; i++) {
        cin >> a[i];
    }

    vector<int> indeg(N + 1, 0);
    for (int i = 1; i <= N; i++) {
        indeg[a[i]]++;
    }

    queue<int> q;
    for (int i = 1; i <= N; i++) {
        if (indeg[i] == 0) q.push(i);
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        int v = a[u];
        indeg[v]--;
        if (indeg[v] == 0) q.push(v);
    }

    for (int i = 1; i <= N; i++) {
        if (indeg[i] > 0) isCycle[i] = true;
    }

    vector<bool> visited(N + 1, false);

    for (int i = 1; i <= N; i++) {
        if (isCycle[i] && !visited[i]) {
            removedEdge[i] = true;

            int u = i;
            do {
                visited[u] = true;
                u = a[u];
            } while (u != i);
        }
    }

    lct.init(N);

    for (int v = 1; v <= N; v++) {
        if (!removedEdge[v]) {
            lct.link(v, a[v]);
        }
    }

    cin >> M;

    long long ans[3] = {0, 0, 0};

    while (M--) {
        int c;
        char ch;
        cin >> c >> ch;
        int t = id(ch);

        if (activeCow[c]) {
            if (typ[c] != t) {
                int s = basinSize[c];
                ans[typ[c]] -= s;
                ans[t] += s;
                typ[c] = t;
            }
        } else {
            int root = lct.findRoot(c);

            if (activeCow[root]) {
                int s = lct.subtreeSize(c);

                int oldType = typ[root];
                ans[oldType] -= s;
                basinSize[root] -= s;

                lct.cutParent(c);

                activeCow[c] = true;
                typ[c] = t;
                basinSize[c] = s;
                ans[t] += s;
            } else {
                if (isCycle[c]) {
                    int s = lct.componentSize(root);

                    if (c != root) {
                        lct.cutParent(c);
                        lct.link(root, a[root]);
                    }

                    activeCow[c] = true;
                    typ[c] = t;
                    basinSize[c] = s;
                    ans[t] += s;
                } else {
                    int s = lct.subtreeSize(c);

                    lct.cutParent(c);

                    activeCow[c] = true;
                    typ[c] = t;
                    basinSize[c] = s;
                    ans[t] += s;
                }
            }
        }

        cout << ans[0] << ' ' << ans[1] << ' ' << ans[2] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;

    Fenwick() : n(0) {}
    Fenwick(int n) { init(n); }

    void init(int n_) {
        n = n_;
        bit.assign(n + 1, 0);
    }

    void add(int idx, long long delta) {
        for (++idx; idx <= n; idx += idx & -idx) bit[idx] += delta;
    }

    long long sumPrefix(int idx) const {
        long long res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }

    long long rangeSum(int l, int r) const {
        if (l > r) return 0;
        return sumPrefix(r + 1) - sumPrefix(l);
    }
};

struct SegTree {
    int n;
    vector<pair<int, int>> seg;

    SegTree() : n(1) {}
    SegTree(int sz) { init(sz); }

    void init(int sz) {
        n = 1;
        while (n < max(1, sz)) n <<= 1;
        seg.assign(2 * n, {-1, -1});
    }

    void update(int idx, int dep, int id) {
        int p = idx + n;
        seg[p] = {dep, id};
        for (p >>= 1; p; p >>= 1) {
            seg[p] = max(seg[p << 1], seg[p << 1 | 1]);
        }
    }

    pair<int, int> query(int l, int r) const {
        if (l > r) return {-1, -1};
        l += n;
        r += n;
        pair<int, int> res = {-1, -1};
        while (l <= r) {
            if (l & 1) res = max(res, seg[l++]);
            if (!(r & 1)) res = max(res, seg[r--]);
            l >>= 1;
            r >>= 1;
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    vector<int> indeg(N + 1, 0);
    vector<vector<int>> rev(N + 1);

    for (int i = 1; i <= N; i++) {
        cin >> a[i];
        indeg[a[i]]++;
        rev[a[i]].push_back(i);
    }

    int M;
    cin >> M;

    vector<int> qc(M);
    vector<char> qt(M);

    for (int i = 0; i < M; i++) {
        cin >> qc[i] >> qt[i];
    }

    // Find cycle nodes by removing indegree-zero nodes.
    vector<char> isCycle(N + 1, 1);
    vector<int> deg = indeg;
    queue<int> qu;

    for (int i = 1; i <= N; i++) {
        if (deg[i] == 0) qu.push(i);
    }

    while (!qu.empty()) {
        int u = qu.front();
        qu.pop();

        isCycle[u] = 0;

        int v = a[u];
        if (--deg[v] == 0) qu.push(v);
    }

    // Decompose cycles.
    vector<int> comp(N + 1, -1), cpos(N + 1, -1);
    vector<vector<int>> compCycle;

    for (int i = 1; i <= N; i++) {
        if (isCycle[i] && comp[i] == -1) {
            int cid = (int)compCycle.size();
            vector<int> vec;

            int cur = i;
            do {
                comp[cur] = cid;
                cpos[cur] = (int)vec.size();
                vec.push_back(cur);
                cur = a[cur];
            } while (cur != i);

            compCycle.push_back(vec);
        }
    }

    int numComps = (int)compCycle.size();

    vector<int> compBase(numComps), compLen(numComps);
    vector<int> cycleGidx(N + 1, -1);

    int Ccnt = 0;

    for (int cid = 0; cid < numComps; cid++) {
        compBase[cid] = Ccnt;
        compLen[cid] = (int)compCycle[cid].size();

        for (int p = 0; p < compLen[cid]; p++) {
            int cow = compCycle[cid][p];
            cycleGidx[cow] = Ccnt + p;
        }

        Ccnt += compLen[cid];
    }

    // Build non-cycle forest.
    vector<int> parentTree(N + 1, -1);
    vector<int> depth(N + 1, 0);
    vector<int> rootCycle(N + 1, -1);
    vector<int> heavy(N + 1, -1);
    vector<int> head(N + 1, -1);
    vector<int> pos(N + 1, -1);

    vector<int> order;
    vector<int> forestRoots;

    vector<int> st;

    for (int r = 1; r <= N; r++) {
        if (!isCycle[r]) continue;

        for (int v : rev[r]) {
            if (isCycle[v]) continue;

            parentTree[v] = -1;
            depth[v] = 0;
            rootCycle[v] = r;
            forestRoots.push_back(v);

            st.clear();
            st.push_back(v);

            while (!st.empty()) {
                int u = st.back();
                st.pop_back();

                order.push_back(u);

                for (int w : rev[u]) {
                    if (isCycle[w]) continue;

                    parentTree[w] = u;
                    depth[w] = depth[u] + 1;
                    rootCycle[w] = r;
                    st.push_back(w);
                }
            }
        }
    }

    vector<int> sz(N + 1, 1);

    for (int i = (int)order.size() - 1; i >= 0; i--) {
        int u = order[i];
        int p = parentTree[u];

        if (p != -1) {
            sz[p] += sz[u];

            if (heavy[p] == -1 || sz[u] > sz[heavy[p]]) {
                heavy[p] = u;
            }
        }
    }

    // Heavy-light decomposition for non-cycle nodes.
    int timer = 0;
    vector<pair<int, int>> st2;

    for (int root : forestRoots) {
        st2.clear();
        st2.push_back({root, root});

        while (!st2.empty()) {
            auto [u, h] = st2.back();
            st2.pop_back();

            int cur = u;

            while (cur != -1) {
                head[cur] = h;
                pos[cur] = timer++;

                for (int w : rev[cur]) {
                    if (isCycle[w]) continue;

                    if (w != heavy[cur]) {
                        st2.push_back({w, w});
                    }
                }

                cur = heavy[cur];
            }
        }
    }

    int nonCycleCount = timer;

    // Initial cycle weights: cycle cow itself + all attached non-cycle nodes.
    vector<long long> Winit(Ccnt, 0);

    for (int i = 1; i <= N; i++) {
        if (isCycle[i]) {
            Winit[cycleGidx[i]] = 1;
        }
    }

    for (int i = 1; i <= N; i++) {
        if (!isCycle[i]) {
            int r = rootCycle[i];
            Winit[cycleGidx[r]]++;
        }
    }

    Fenwick bitW(Ccnt);

    for (int i = 0; i < Ccnt; i++) {
        if (Winit[i]) bitW.add(i, Winit[i]);
    }

    vector<set<int>> activeSet(numComps);

    vector<char> active(N + 1, 0);
    vector<int> color(N + 1, -1);
    vector<long long> terr(N + 1, 0);

    long long ans[3] = {0, 0, 0};

    Fenwick bitTerr(nonCycleCount);
    SegTree seg(nonCycleCount);

    auto rangeAfter = [&](int cid, int from, int to) -> long long {
        int base = compBase[cid];
        int len = compLen[cid];

        if (from < to) {
            return bitW.rangeSum(base + from + 1, base + to);
        } else if (from > to) {
            long long res = 0;

            if (from + 1 <= len - 1) {
                res += bitW.rangeSum(base + from + 1, base + len - 1);
            }

            res += bitW.rangeSum(base, base + to);
            return res;
        } else {
            return bitW.rangeSum(base, base + len - 1);
        }
    };

    auto decreaseW = [&](int cycCow, long long delta) {
        int cid = comp[cycCow];
        int p = cpos[cycCow];

        auto &s = activeSet[cid];

        if (!s.empty()) {
            auto it = s.lower_bound(p);
            if (it == s.end()) it = s.begin();

            int qpos = *it;
            int qid = compCycle[cid][qpos];

            terr[qid] -= delta;
            ans[color[qid]] -= delta;
        }

        int gid = cycleGidx[cycCow];
        bitW.add(gid, -delta);
    };

    auto queryPath = [&](int x) -> int {
        pair<int, int> best = {-1, -1};

        while (x != -1) {
            int h = head[x];
            auto cur = seg.query(pos[h], pos[x]);

            if (cur.first > best.first) best = cur;

            x = parentTree[h];
        }

        return best.second;
    };

    auto activateCycle = [&](int x, int v) {
        int cid = comp[x];
        int p = cpos[x];

        auto &s = activeSet[cid];
        long long t;

        if (s.empty()) {
            int base = compBase[cid];
            int len = compLen[cid];

            t = bitW.rangeSum(base, base + len - 1);

            terr[x] = t;
            color[x] = v;
            active[x] = 1;
            s.insert(p);

            ans[v] += t;
        } else {
            auto itq = s.lower_bound(p);
            if (itq == s.end()) itq = s.begin();

            int qpos = *itq;
            int qid = compCycle[cid][qpos];

            auto itp = itq;
            if (itp == s.begin()) itp = prev(s.end());
            else --itp;

            int ppos = *itp;

            t = rangeAfter(cid, ppos, p);

            terr[qid] -= t;
            ans[color[qid]] -= t;

            terr[x] = t;
            color[x] = v;
            active[x] = 1;
            s.insert(p);

            ans[v] += t;
        }
    };

    auto activateNonCycle = [&](int x, int v) {
        long long covered = bitTerr.rangeSum(pos[x], pos[x] + sz[x] - 1);
        long long t = (long long)sz[x] - covered;

        int p = queryPath(x);

        if (p != -1) {
            terr[p] -= t;
            bitTerr.add(pos[p], -t);
            ans[color[p]] -= t;
        } else {
            int r = rootCycle[x];
            decreaseW(r, t);
        }

        terr[x] = t;
        color[x] = v;
        active[x] = 1;

        bitTerr.add(pos[x], t);
        seg.update(pos[x], depth[x], x);

        ans[v] += t;
    };

    for (int i = 0; i < M; i++) {
        int c = qc[i];
        char ch = qt[i];

        int v;
        if (ch == 'C') v = 0;
        else if (ch == 'O') v = 1;
        else v = 2;

        if (!active[c]) {
            if (isCycle[c]) {
                activateCycle(c, v);
            } else {
                activateNonCycle(c, v);
            }
        } else {
            if (color[c] != v) {
                ans[color[c]] -= terr[c];
                ans[v] += terr[c];
                color[c] = v;
            }
        }

        cout << ans[0] << ' ' << ans[1] << ' ' << ans[2] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;

    Fenwick(int n = 0) {
        init(n);
    }

    void init(int n_) {
        n = n_;
        bit.assign(n + 1, 0);
    }

    void add(int idx, long long delta) {
        for (int i = idx + 1; i <= n; i += i & -i) {
            bit[i] += delta;
        }
    }

    long long sumPrefix(int idx) const {
        long long res = 0;
        for (int i = idx + 1; i > 0; i -= i & -i) {
            res += bit[i];
        }
        return res;
    }

    long long range(int l, int r) const {
        if (l > r) return 0;
        return sumPrefix(r) - (l ? sumPrefix(l - 1) : 0);
    }
};

struct MaxSeg {
    int n;
    vector<pair<int, int>> tr;

    MaxSeg(int n = 0) : n(n), tr(4 * max(1, n) + 5, {-1, -1}) {}

    void updateRec(int p, int l, int r, int ql, int qr, pair<int, int> val) {
        if (ql > r || qr < l) return;

        if (ql <= l && r <= qr) {
            if (val > tr[p]) tr[p] = val;
            return;
        }

        int m = (l + r) >> 1;
        updateRec(p << 1, l, m, ql, qr, val);
        updateRec(p << 1 | 1, m + 1, r, ql, qr, val);
    }

    void update(int l, int r, pair<int, int> val) {
        if (n == 0 || l > r) return;
        updateRec(1, 0, n - 1, l, r, val);
    }

    pair<int, int> queryRec(int p, int l, int r, int idx, pair<int, int> res) {
        if (tr[p] > res) res = tr[p];

        if (l == r) return res;

        int m = (l + r) >> 1;
        if (idx <= m) return queryRec(p << 1, l, m, idx, res);
        else return queryRec(p << 1 | 1, m + 1, r, idx, res);
    }

    int query(int idx) {
        if (n == 0) return -1;
        return queryRec(1, 0, n - 1, idx, {-1, -1}).second;
    }
};

