    for (int i = 0; i < N; i++) {
        if (isCycle[i] && cycleId[i] == -1) {
            int cid = (int)cycleLen.size();

            vector<int> order;
            int cur = i;

            do {
                order.push_back(cur);
                cur = a[cur];
            } while (cur != i);

            cycleLen.push_back((int)order.size());
            cycleOffset.push_back(totalCycleNodes);

            for (int pos = 0; pos < (int)order.size(); pos++) {
                int node = order[pos];
                cycleId[node] = cid;
                cyclePos[node] = pos;
            }

            totalCycleNodes += (int)order.size();
        }
    }

    // Build reverse forest, excluding cycle edges.
    vector<vector<int>> children(N);

    for (int i = 0; i < N; i++) {
        if (!isCycle[i]) {
            children[a[i]].push_back(i);
        }
    }

    vector<int> tin(N), tout(N), sz(N, 1), depth(N), parent(N, -1), rootCycle(N);

    int timer = 0;
    vector<pair<int, int>> st;
    st.reserve(N);

    for (int r = 0; r < N; r++) {
        if (!isCycle[r]) continue;

        parent[r] = -1;
        depth[r] = 0;
        rootCycle[r] = r;
        tin[r] = timer++;
        sz[r] = 1;

        st.clear();
        st.push_back({r, 0});

        while (!st.empty()) {
            int v = st.back().first;
            int &idx = st.back().second;

            if (idx < (int)children[v].size()) {
                int u = children[v][idx++];

                parent[u] = v;
                depth[u] = depth[v] + 1;
                rootCycle[u] = rootCycle[v];
                tin[u] = timer++;
                sz[u] = 1;

                st.push_back({u, 0});
            } else {
                tout[v] = timer - 1;
                st.pop_back();

                if (parent[v] != -1) {
                    sz[parent[v]] += sz[v];
                }
            }
        }
    }

    Fenwick bitDom(N);
    Fenwick bitCycle(totalCycleNodes);

    vector<long long> sumR(cycleLen.size(), 0);

    for (int i = 0; i < N; i++) {
        if (isCycle[i]) {
            int cid = cycleId[i];
            int pos = cyclePos[i];
            int gidx = cycleOffset[cid] + pos;

            long long val = sz[i];

            bitCycle.add(gidx, val);
            sumR[cid] += val;
        }
    }

    vector<char> active(N, 0);
    vector<int> party(N, -1);
    vector<long long> dom(N, 0);

    vector<set<int>> activeCycle(cycleLen.size());

    MaxSeg seg(N);

    long long ans[3] = {0, 0, 0};

    for (int night = 0; night < M; night++) {
        int c = uc[night];
        int col = ut[night];

        if (active[c]) {
            if (party[c] != col) {
                long long s = dom[c];

                ans[party[c]] -= s;
                ans[col] += s;

                party[c] = col;
            }
        } else {
            active[c] = 1;
            party[c] = col;

            if (isCycle[c]) {
                int cid = cycleId[c];
                int pos = cyclePos[c];
                int len = cycleLen[cid];

                auto &S = activeCycle[cid];

                long long s;
                int p = -1;

                if (S.empty()) {
                    s = sumR[cid];
                } else {
                    auto it = S.lower_bound(pos);
                    int pred;

                    if (it == S.end()) {
                        p = *S.begin();
                        pred = *S.rbegin();
                    } else {
                        p = *it;

                        if (it == S.begin()) {
                            pred = *S.rbegin();
                        } else {
                            auto itp = prev(it);
                            pred = *itp;
                        }
                    }

                    int off = cycleOffset[cid];

                    if (pred < pos) {
                        s = bitCycle.range(off + pred + 1, off + pos);
                    } else if (pred > pos) {
                        s = 0;

                        if (pred + 1 <= len - 1) {
                            s += bitCycle.range(off + pred + 1, off + len - 1);
                        }

                        s += bitCycle.range(off, off + pos);
                    } else {
                        s = sumR[cid];
                    }
                }

                if (p != -1) {
                    ans[party[p]] -= s;
                    dom[p] -= s;
                }

                dom[c] = s;
                ans[col] += s;

                S.insert(pos);

                seg.update(tin[c], tout[c], {depth[c], c});
            } else {
                long long sub = bitDom.range(tin[c], tout[c]);
                long long s = (long long)sz[c] - sub;

                int p = seg.query(tin[c]);
                bool pNonCycle = (p != -1 && !isCycle[p]);

                if (!pNonCycle) {
                    int q = rootCycle[c];
                    int cid = cycleId[q];

                    sumR[cid] -= s;

                    int gidx = cycleOffset[cid] + cyclePos[q];
                    bitCycle.add(gidx, -s);
                }

                if (p != -1) {
                    ans[party[p]] -= s;
                    dom[p] -= s;

                    if (!isCycle[p]) {
                        bitDom.add(tin[p], -s);
                    }
                }

                dom[c] = s;
                ans[col] += s;

                bitDom.add(tin[c], s);

                seg.update(tin[c], tout[c], {depth[c], c});
            }
        }

        cout << ans[0] << ' ' << ans[1] << ' ' << ans[2] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

/*
 * Supports:
 *   - range add
 *   - range minimum together with the number of positions attaining it
 */
class MinCountSegmentTree {
    int n;
    vector<int> mn, cnt, lazy;

    static pair<int, int> combine(pair<int, int> a, pair<int, int> b) {
        if (a.first < b.first) return a;
        if (b.first < a.first) return b;
        return {a.first, a.second + b.second};
    }

    void build(int p, int l, int r) {
        cnt[p] = r - l + 1;
        if (l == r) return;
        int mid = (l + r) / 2;
        build(p * 2, l, mid);
        build(p * 2 + 1, mid + 1, r);
    }

    void apply(int p, int value) {
        mn[p] += value;
        lazy[p] += value;
    }

    void push(int p) {
        if (lazy[p] == 0) return;
        apply(p * 2, lazy[p]);
        apply(p * 2 + 1, lazy[p]);
        lazy[p] = 0;
    }

    void pull(int p) {
        mn[p] = min(mn[p * 2], mn[p * 2 + 1]);
        cnt[p] = 0;
        if (mn[p * 2] == mn[p]) cnt[p] += cnt[p * 2];
        if (mn[p * 2 + 1] == mn[p]) cnt[p] += cnt[p * 2 + 1];
    }

    void add(int p, int l, int r, int ql, int qr, int value) {
        if (ql <= l && r <= qr) {
            apply(p, value);
            return;
        }
        push(p);
        int mid = (l + r) / 2;
        if (ql <= mid) add(p * 2, l, mid, ql, qr, value);
        if (qr > mid) add(p * 2 + 1, mid + 1, r, ql, qr, value);
        pull(p);
    }

    pair<int, int> query(int p, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return {mn[p], cnt[p]};

        push(p);
        int mid = (l + r) / 2;
        if (qr <= mid) return query(p * 2, l, mid, ql, qr);
        if (ql > mid) return query(p * 2 + 1, mid + 1, r, ql, qr);

        return combine(
            query(p * 2, l, mid, ql, qr),
            query(p * 2 + 1, mid + 1, r, ql, qr)
        );
    }

public:
    explicit MinCountSegmentTree(int n)
        : n(n), mn(4 * n, 0), cnt(4 * n, 0), lazy(4 * n, 0) {
        build(1, 0, n - 1);
    }

    void add(int l, int r, int value) {
        add(1, 0, n - 1, l, r, value);
    }

    pair<int, int> query(int l, int r) {
        return query(1, 0, n - 1, l, r);
    }
};

/*
 * Range "chmax" updates and point maximum queries.
 * Each update inserts an active vertex over its subtree interval.
 * The deepest active vertex containing a point is its nearest active ancestor.
 */
class RangeMaxPointQuery {
    int base;
    const vector<int>& depth;
    vector<int> tag;

    void relax(int& best, int candidate) const {
        if (candidate < 0) return;
        if (best < 0 || depth[candidate] > depth[best]) {
            best = candidate;
        }
    }

public:
    explicit RangeMaxPointQuery(const vector<int>& depth) : depth(depth) {
        base = 1;
        while (base < (int)depth.size()) base <<= 1;
        tag.assign(2 * base, -1);
    }

    void update(int l, int r, int vertex) {
        l += base;
        r += base + 1;
        while (l < r) {
            if (l & 1) {
                relax(tag[l], vertex);
                ++l;
            }
            if (r & 1) {
                --r;
                relax(tag[r], vertex);
            }
            l >>= 1;
            r >>= 1;
        }
    }

    int query(int position) const {
        int best = -1;
        for (int p = position + base; p > 0; p >>= 1) {
            relax(best, tag[p]);
        }
        return best;
    }
};

class Fenwick {
    int n;
    vector<int> bit;

public:
    explicit Fenwick(const vector<int>& values)
        : n((int)values.size()), bit(n + 1, 0) {
        for (int i = 0; i < n; ++i) bit[i + 1] = values[i];
        for (int i = 1; i <= n; ++i) {
            int j = i + (i & -i);
            if (j <= n) bit[j] += bit[i];
        }
    }

    void add(int index, int delta) {
        for (int i = index + 1; i <= n; i += i & -i) {
            bit[i] += delta;
        }
    }

    // Sum of [0, r)
    int prefix(int r) const {
        int result = 0;
        for (int i = r; i > 0; i -= i & -i) result += bit[i];
        return result;
    }

    // Sum of [l, r)
    int rangeSum(int l, int r) const {
        return prefix(r) - prefix(l);
    }
};

struct CycleInfo {
    int start;
    int len;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N);
    vector<int> indegree(N, 0);
    for (int i = 0; i < N; ++i) {
        cin >> a[i];
        --a[i];
        ++indegree[a[i]];
    }

    // Remove all non-cycle vertices.
    vector<int> queue;
    queue.reserve(N);
    for (int i = 0; i < N; ++i) {
        if (indegree[i] == 0) queue.push_back(i);
    }
    for (size_t head = 0; head < queue.size(); ++head) {
        int v = queue[head];
        if (--indegree[a[v]] == 0) queue.push_back(a[v]);
    }

    vector<char> onCycle(N, false);
    for (int i = 0; i < N; ++i) onCycle[i] = (indegree[i] > 0);

    // Enumerate cycles in the direction in which cows move.
    vector<CycleInfo> cycles;
    vector<int> cycleVertices;
    vector<int> cycleId(N, -1), cycleLocal(N, -1);
    vector<char> seen(N, false);
    cycleVertices.reserve(N);

    for (int i = 0; i < N; ++i) {
        if (!onCycle[i] || seen[i]) continue;

        int id = (int)cycles.size();
        int start = (int)cycleVertices.size();
        int v = i;

        do {
            seen[v] = true;
            cycleId[v] = id;
            cycleLocal[v] = (int)cycleVertices.size() - start;
            cycleVertices.push_back(v);
            v = a[v];
        } while (v != i);

        cycles.push_back({start, (int)cycleVertices.size() - start});
    }

    /*
     * Cut cycle edges. The remaining edges form trees rooted at cycle vertices.
     * Children are stored in CSR format.
     */
    vector<int> childStart(N + 1, 0);
    for (int v = 0; v < N; ++v) {
        if (!onCycle[v]) ++childStart[a[v] + 1];
    }
    for (int i = 1; i <= N; ++i) childStart[i] += childStart[i - 1];

    vector<int> childList(N - (int)cycleVertices.size());
    vector<int> cursor = childStart;
    for (int v = 0; v < N; ++v) {
        if (!onCycle[v]) childList[cursor[a[v]]++] = v;
    }

    // Euler intervals, depths, tree roots, and subtree sizes.
    vector<int> tin(N), tout(N), depth(N), treeRoot(N), subtreeSize(N, 1);
    vector<int> dfsStack;
    dfsStack.reserve(2 * N);
    int timer = 0;

    for (int root : cycleVertices) {
        treeRoot[root] = root;
        depth[root] = 0;
        dfsStack.push_back(root);

        while (!dfsStack.empty()) {
            int code = dfsStack.back();
            dfsStack.pop_back();

            if (code >= 0) {
                int v = code;
                tin[v] = timer++;

                dfsStack.push_back(~v);
                for (int j = childStart[v + 1] - 1; j >= childStart[v]; --j) {
                    int u = childList[j];
                    depth[u] = depth[v] + 1;
                    treeRoot[u] = root;
                    dfsStack.push_back(u);
                }
            } else {
                int v = ~code;
                tout[v] = timer - 1;
                if (!onCycle[v]) subtreeSize[a[v]] += subtreeSize[v];
            }
        }
    }

    /*
     * residual[r]: cows from r's attached tree that reach the cycle without
     * encountering a party in that tree.
     */
    vector<int> residual(N, 0);
    for (int root : cycleVertices) residual[root] = subtreeSize[root];

    vector<int> fenwickValues(cycleVertices.size());
    for (int i = 0; i < (int)cycleVertices.size(); ++i) {
        fenwickValues[i] = residual[cycleVertices[i]];
    }
    Fenwick fenwick(fenwickValues);

    MinCountSegmentTree coverage(N);
    RangeMaxPointQuery nearestActiveAncestor(depth);

    // treeAssigned[v]: cows assigned to v's party inside its attached tree.
    vector<int> treeAssigned(N, 0);

    // cycleAssigned[i]: free cows assigned to the active marker at cycle index i.
    vector<int> cycleAssigned(cycleVertices.size(), 0);

    // -1 means no party; otherwise 0=C, 1=O, 2=W.
    vector<int> partyColor(N, -1);
    array<int, 3> answer{0, 0, 0};

    // Active cycle markers, ordered by (cycle id, position in cycle).
    set<pair<int, int>> markers;
    vector<int> markerCount(cycles.size(), 0);

    auto cycleRangeSum = [&](int id, int l, int r) -> int {
        if (l > r) return 0;
        const auto& cycle = cycles[id];
        return fenwick.rangeSum(cycle.start + l, cycle.start + r + 1);
    };

    // Sum of residual cows in the cyclic interval (P, pos].
    auto gapSum = [&](int id, int P, int pos) -> int {
        if (P == pos) return 0;
        if (P < pos) return cycleRangeSum(id, P + 1, pos);

        int result = cycleRangeSum(id, P + 1, cycles[id].len - 1);
        result += cycleRangeSum(id, 0, pos);
        return result;
    };

    // First active marker at or after pos, cyclically.
    auto nextMarker = [&](int id, int pos) -> int {
        if (markerCount[id] == 0) return -1;

        auto it = markers.lower_bound({id, pos});
        if (it != markers.end() && it->first == id) return it->second;

        it = markers.lower_bound({id, 0});
        return it->second;
    };

    // Previous and next old markers around an inactive position.
    auto markerNeighbors = [&](int id, int pos) -> pair<int, int> {
        auto first = markers.lower_bound({id, 0});
        auto afterLast = markers.upper_bound({id, INT_MAX});
        auto last = prev(afterLast);

        auto next = markers.upper_bound({id, pos});
        if (next == markers.end() || next->first != id) next = first;

        int D = next->second;
        int P;

        if (next != first) {
            P = prev(next)->second;
        } else if (first != last) {
            P = prev(last)->second;
        } else {
            P = D;
        }

        return {P, D};
    };

    auto insertMarker = [&](int id, int pos, int color) {
        const auto& cycle = cycles[id];
        int globalIndex = cycle.start + pos;

        if (markerCount[id] == 0) {
            // Every remaining free cow now reaches this marker.
            int amount = cycleRangeSum(id, 0, cycle.len - 1);
            cycleAssigned[globalIndex] = amount;
            answer[color] += amount;
        } else {
            auto [P, D] = markerNeighbors(id, pos);
            int amount = gapSum(id, P, pos);

            int globalD = cycle.start + D;
            cycleAssigned[globalD] -= amount;
            answer[partyColor[cycleVertices[globalD]]] -= amount;

            cycleAssigned[globalIndex] = amount;
            answer[color] += amount;
        }

        markers.insert({id, pos});
        ++markerCount[id];
    };

    auto activate = [&](int v, int color) {
        int root = treeRoot[v];
        int id = cycleId[root];
        int rootPosition = cycleLocal[root];

        int amount;
        int ancestor = -1;

        if (onCycle[v]) {
            // An inactive cycle root captures its entire remaining local basin.
            amount = residual[v];
        } else {
            // Cows in v's subtree not already captured by active descendants.
            amount = coverage.query(tin[v], tout[v]).second;
            ancestor = nearestActiveAncestor.query(tin[v]);
        }

        if (ancestor != -1) {
            // These cows used to attend the nearest active ancestor.
            treeAssigned[ancestor] -= amount;
            answer[partyColor[ancestor]] -= amount;
        } else {
            // These cows previously reached the cycle.
            if (onCycle[v]) residual[v] = 0;
            else residual[root] -= amount;

            fenwick.add(cycles[id].start + rootPosition, -amount);

            int destination = nextMarker(id, rootPosition);
            if (destination != -1) {
                int globalDestination = cycles[id].start + destination;
                cycleAssigned[globalDestination] -= amount;
                answer[partyColor[cycleVertices[globalDestination]]] -= amount;
            }
        }

        treeAssigned[v] = amount;
        answer[color] += amount;
        partyColor[v] = color;

        if (onCycle[v]) {
            insertMarker(id, cycleLocal[v], color);
        }

        coverage.add(tin[v], tout[v], 1);
        nearestActiveAncestor.update(tin[v], tout[v], v);
    };

    int M;
    cin >> M;

    while (M--) {
        int c;
        char type;
        cin >> c >> type;
        --c;

        int color = (type == 'C' ? 0 : (type == 'O' ? 1 : 2));

        if (partyColor[c] == -1) {
            // Parties never disappear, so this is the cow's first activation.
            activate(c, color);
        } else if (partyColor[c] != color) {
            int oldColor = partyColor[c];

            int localAmount = treeAssigned[c];
            answer[oldColor] -= localAmount;
            answer[color] += localAmount;

            if (onCycle[c]) {
                int globalIndex = cycles[cycleId[c]].start + cycleLocal[c];
                int cycleAmount = cycleAssigned[globalIndex];
                answer[oldColor] -= cycleAmount;
                answer[color] += cycleAmount;
            }

            partyColor[c] = color;
        }

        cout << answer[0] << ' ' << answer[1] << ' ' << answer[2] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Fenwick {
    int n;
    vector<ll> bit;

    explicit Fenwick(int n = 0) : n(n), bit(n + 1, 0) {}

    void build(const vector<ll>& values) {
        n = (int)values.size();
        bit.assign(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            bit[i] += values[i - 1];
            int parent = i + (i & -i);
            if (parent <= n) bit[parent] += bit[i];
        }
    }

    void add(int pos, ll delta) {
        for (int i = pos + 1; i <= n; i += i & -i) {
            bit[i] += delta;
        }
    }

    // Sum of [0, end).
    ll prefixSum(int end) const {
        ll result = 0;
        for (int i = end; i > 0; i -= i & -i) {
            result += bit[i];
        }
        return result;
    }

    // Sum of [left, right], inclusive.
    ll rangeSum(int left, int right) const {
        if (left > right) return 0;
        return prefixSum(right + 1) - prefixSum(left);
    }
};

// Supports inserting an active vertex's subtree and finding the deepest
// active ancestor of a given Euler-tour position.
struct AncestorMax {
    int base;
    const vector<int>& depth;
    vector<int> best;

    AncestorMax(int n, const vector<int>& depth) : depth(depth) {
        base = 1;
        while (base < n) base <<= 1;
        best.assign(base << 1, -1);
    }

    bool better(int a, int b) const {
        if (a == -1) return false;
        if (b == -1) return true;
        if (depth[a] != depth[b]) return depth[a] > depth[b];
        return a > b;
    }

    void relax(int index, int candidate) {
        if (better(candidate, best[index])) {
            best[index] = candidate;
        }
    }

    void update(int left, int right, int candidate) {
        left += base;
        right += base;
        while (left <= right) {
            if (left & 1) relax(left++, candidate);
            if (!(right & 1)) relax(right--, candidate);
            left >>= 1;
            right >>= 1;
        }
    }

    int query(int pos) const {
        int answer = -1;
        for (int index = base + pos; index > 0; index >>= 1) {
            if (better(best[index], answer)) {
                answer = best[index];
            }
        }
        return answer;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N);
    vector<int> indegree(N, 0);
    for (int i = 0; i < N; ++i) {
        cin >> a[i];
        --a[i];
        ++indegree[a[i]];
    }

    // Remove all non-cycle vertices. At the same time, compute the size
    // of each rooted tree attached to a cycle vertex.
    vector<int> subtreeSize(N, 1);
    vector<int> queue;
    queue.reserve(N);
    for (int i = 0; i < N; ++i) {
        if (indegree[i] == 0) queue.push_back(i);
    }

    for (int qi = 0; qi < (int)queue.size(); ++qi) {
        int u = queue[qi];
        int v = a[u];
        subtreeSize[v] += subtreeSize[u];
        if (--indegree[v] == 0) queue.push_back(v);
    }

    vector<char> onCycle(N, false);
    for (int i = 0; i < N; ++i) {
        onCycle[i] = (indegree[i] > 0);
    }

    // Store the cycles in directed order, using flat arrays.
    vector<int> cycleId(N, -1);
    vector<int> cyclePosition(N, -1);
    vector<int> cycleNodes;
    vector<int> cycleLength;
    vector<int> cycleBase;
    cycleNodes.reserve(N);

    for (int start = 0; start < N; ++start) {
        if (!onCycle[start] || cycleId[start] != -1) continue;

        int id = (int)cycleLength.size();
        int base = (int)cycleNodes.size();
        int u = start;
        do {
            cycleId[u] = id;
            cyclePosition[u] = (int)cycleNodes.size() - base;
            cycleNodes.push_back(u);
            u = a[u];
        } while (u != start);

        cycleBase.push_back(base);
        cycleLength.push_back((int)cycleNodes.size() - base);
    }

    // Reverse adjacency, stored without per-vertex allocations.
    vector<int> head(N, -1);
    vector<int> nextChild(N, -1);
    for (int v = 0; v < N; ++v) {
        nextChild[v] = head[a[v]];
        head[a[v]] = v;
    }

    // Euler tour of the forest obtained by removing all cycle edges.
    vector<int> tin(N);
    vector<int> rootOf(N, -1);
    vector<int> depth(N, 0);
    vector<int> stack;
    stack.reserve(N);

    for (int root : cycleNodes) {
        rootOf[root] = root;
        depth[root] = 0;
        stack.push_back(root);
    }

    int timer = 0;
    while (!stack.empty()) {
        int u = stack.back();
        stack.pop_back();
        tin[u] = timer++;

        for (int v = head[u]; v != -1; v = nextChild[v]) {
            if (onCycle[v]) continue;
            rootOf[v] = rootOf[u];
            depth[v] = depth[u] + 1;
            stack.push_back(v);
        }
    }

    // Stores the current owner-count of each active non-cycle host.
    Fenwick hostTree(N);

    // For an inactive cycle vertex, weight is the number of cows from its
    // attached tree that reach the cycle. Active cycle vertices have weight 0.
    vector<ll> weight(cycleNodes.size(), 0);
    for (int id = 0; id < (int)cycleLength.size(); ++id) {
        int base = cycleBase[id];
        for (int pos = 0; pos < cycleLength[id]; ++pos) {
            int u = cycleNodes[base + pos];
            weight[base + pos] = subtreeSize[u];
        }
    }

    Fenwick weightTree;
    weightTree.build(weight);

    vector<set<int>> activeCycleVertices(cycleLength.size());

    auto changeWeight = [&](int id, int pos, ll delta) {
        int index = cycleBase[id] + pos;
        weight[index] += delta;
        weightTree.add(index, delta);
    };

    // Sum of weights strictly after 'from' through 'to', following cycle order.
    auto cycleArcSum = [&](int id, int from, int to) -> ll {
        if (from == to) return 0;

        int base = cycleBase[id];
        int last = base + cycleLength[id] - 1;

        if (from < to) {
            return weightTree.rangeSum(base + from + 1, base + to);
        }

        return weightTree.rangeSum(base + from + 1, last)
             + weightTree.rangeSum(base, base + to);
    };

    AncestorMax ancestors(N, depth);

    vector<int> partyType(N, 0);  // 0 = inactive, 1 = C, 2 = O, 3 = W
    vector<ll> hostCount(N, 0);
    array<ll, 4> answer{};

    int M;
    cin >> M;

    for (int night = 0; night < M; ++night) {
        int c;
        char typeCharacter;
        cin >> c >> typeCharacter;
        --c;

        int newType;
        if (typeCharacter == 'C') newType = 1;
        else if (typeCharacter == 'O') newType = 2;
        else newType = 3;

        if (partyType[c] != 0) {
            // A host never stops hosting when its party type changes.
            if (partyType[c] != newType) {
                answer[partyType[c]] -= hostCount[c];
                answer[newType] += hostCount[c];
                partyType[c] = newType;
            }
        } else if (onCycle[c]) {
            int id = cycleId[c];
            int pos = cyclePosition[c];
            int base = cycleBase[id];
            auto& active = activeCycleVertices[id];

            ll countForNewHost;

            if (active.empty()) {
                // The first cycle host receives every cow that reaches the cycle.
                countForNewHost = weightTree.rangeSum(
                    base, base + cycleLength[id] - 1
                );
            } else {
                auto it = active.lower_bound(pos);

                int successorPos;
                int predecessorPos;

                if (it == active.end()) {
                    successorPos = *active.begin();
                    predecessorPos = *active.rbegin();
                } else {
                    successorPos = *it;
                    if (it == active.begin()) {
                        predecessorPos = *active.rbegin();
                    } else {
                        predecessorPos = *prev(it);
                    }
                }

                ll transferred = cycleArcSum(id, predecessorPos, pos);
                int successor = cycleNodes[base + successorPos];

                answer[partyType[successor]] -= transferred;
                hostCount[successor] -= transferred;
                countForNewHost = transferred;
            }

            partyType[c] = newType;
            hostCount[c] = countForNewHost;
            answer[newType] += countForNewHost;

            int index = base + pos;
            ll oldWeight = weight[index];
            changeWeight(id, pos, -oldWeight);

            active.insert(pos);
            ancestors.update(tin[c], tin[c] + subtreeSize[c] - 1, c);
        } else {
            // Cows already owned by active strict descendants do not change.
            ll shielded = hostTree.rangeSum(
                tin[c] + 1, tin[c] + subtreeSize[c] - 1
            );
            ll newlyHosted = (ll)subtreeSize[c] - shielded;

            int predecessor = ancestors.query(tin[c]);
            partyType[c] = newType;

            if (predecessor != -1) {
                // The nearest active tree ancestor currently owns these cows.
                answer[partyType[predecessor]] -= newlyHosted;
                hostCount[predecessor] -= newlyHosted;

                if (!onCycle[predecessor]) {
                    hostTree.add(tin[predecessor], -newlyHosted);
                }
            } else {
                // These cows previously reached the cycle.
                int root = rootOf[c];
                int id = cycleId[root];
                int rootPos = cyclePosition[root];
                auto& active = activeCycleVertices[id];

                int successor = -1;
                if (!active.empty()) {
                    auto it = active.lower_bound(rootPos);
                    if (it == active.end()) it = active.begin();
                    successor = cycleNodes[cycleBase[id] + *it];
                }

                if (successor != -1) {
                    answer[partyType[successor]] -= newlyHosted;
                    hostCount[successor] -= newlyHosted;
                }

                changeWeight(id, rootPos, -newlyHosted);
            }

            hostCount[c] = newlyHosted;
            answer[newType] += newlyHosted;

            hostTree.add(tin[c], newlyHosted);
            ancestors.update(tin[c], tin[c] + subtreeSize[c] - 1, c);
        }

        cout << answer[1] << ' ' << answer[2] << ' ' << answer[3] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Fenwick {
    int n;
    vector<ll> bit;

    explicit Fenwick(int n = 0) : n(n), bit(n + 1, 0) {}

    void build(const vector<ll>& values) {
        n = (int)values.size();
        bit.assign(n + 1, 0);
        for (int i = 1; i <= n; ++i) bit[i] = values[i - 1];
        for (int i = 1; i <= n; ++i) {
            int j = i + (i & -i);
            if (j <= n) bit[j] += bit[i];
        }
    }

    // Indices are 0-based.
    void add(int index, ll value) {
        for (int i = index + 1; i <= n; i += i & -i) {
            bit[i] += value;
        }
    }

    ll prefixSum(int index) const {
        ll result = 0;
        for (int i = index + 1; i > 0; i -= i & -i) {
            result += bit[i];
        }
        return result;
    }

    ll rangeSum(int left, int right) const {
        if (left > right || right < 0 || left >= n) return 0;
        left = max(left, 0);
        right = min(right, n - 1);
        return prefixSum(right) - prefixSum(left - 1);
    }
};

// Supports range chmax updates and point maximum queries.
// No pushes are necessary because updates only take maxima.
struct RangeMaxPointQuery {
    int size;
    vector<ll> tag;

    explicit RangeMaxPointQuery(int n) {
        size = 1;
        while (size < n) size <<= 1;
        tag.assign(size << 1, 0);
    }

    // Left and right are 1-based and inclusive.
    void update(int left, int right, ll value) {
        left += size - 1;
        right += size - 1;

        while (left <= right) {
            if (left & 1) {
                tag[left] = max(tag[left], value);
                ++left;
            }
            if (!(right & 1)) {
                tag[right] = max(tag[right], value);
                --right;
            }
            left >>= 1;
            right >>= 1;
        }
    }

    // Position is 1-based.
    ll query(int position) const {
        ll result = 0;
        for (int p = position + size - 1; p > 0; p >>= 1) {
            result = max(result, tag[p]);
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    vector<int> indegree(N + 1, 0);
    vector<int> head(N + 1, -1), nextChild(N + 1, -1);

    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        ++indegree[a[i]];
        nextChild[i] = head[a[i]];
        head[a[i]] = i;
    }

    int M;
    cin >> M;

    // Remove all non-cycle vertices.
    vector<int> queue;
    queue.reserve(N);
    for (int i = 1; i <= N; ++i) {
        if (indegree[i] == 0) queue.push_back(i);
    }

    for (int qi = 0; qi < (int)queue.size(); ++qi) {
        int v = queue[qi];
        if (--indegree[a[v]] == 0) {
            queue.push_back(a[v]);
        }
    }

    vector<char> onCycle(N + 1, false);
    for (int i = 1; i <= N; ++i) {
        onCycle[i] = (indegree[i] > 0);
    }

    // Store all cycles consecutively, in the direction of the edges.
    vector<int> component(N + 1, -1);
    vector<int> cycleIndex(N + 1, -1);
    vector<int> cycleNodes;
    vector<int> base, cycleLength;
    cycleNodes.reserve(N);

    for (int start = 1; start <= N; ++start) {
        if (!onCycle[start] || component[start] != -1) continue;

        int cid = (int)base.size();
        int b = (int)cycleNodes.size();
        base.push_back(b);

        int v = start;
        do {
            component[v] = cid;
            cycleIndex[v] = (int)cycleNodes.size();
            cycleNodes.push_back(v);
            v = a[v];
        } while (v != start);

        cycleLength.push_back((int)cycleNodes.size() - b);
    }

    // Removing cycle edges leaves a forest rooted at individual cycle vertices.
    vector<int> tin(N + 1), tout(N + 1), depth(N + 1);
    vector<int> rootCycle(N + 1);
    vector<int> stack;
    stack.reserve(2 * N);

    int timer = 0;
    for (int cid = 0; cid < (int)base.size(); ++cid) {
        for (int pos = 0; pos < cycleLength[cid]; ++pos) {
            int root = cycleNodes[base[cid] + pos];
            rootCycle[root] = root;
            depth[root] = 0;
            stack.push_back(root);

            while (!stack.empty()) {
                int token = stack.back();
                stack.pop_back();

                if (token < 0) {
                    tout[-token] = timer;
                    continue;
                }

                int v = token;
                tin[v] = ++timer;
                stack.push_back(-v);

                for (int child = head[v]; child != -1;
                     child = nextChild[child]) {
                    if (onCycle[child]) continue;

                    depth[child] = depth[v] + 1;
                    rootCycle[child] = root;
                    component[child] = cid;
                    stack.push_back(child);
                }
            }
        }
    }

    vector<int> subtreeSize(N + 1);
    for (int v = 1; v <= N; ++v) {
        subtreeSize[v] = tout[v] - tin[v] + 1;
    }

    const int cycleCount = (int)cycleNodes.size();

    // The weight of cycle position i is free(root of position i).
    vector<ll> initialWeights(cycleCount);
    for (int i = 0; i < cycleCount; ++i) {
        int root = cycleNodes[i];
        initialWeights[i] = subtreeSize[root];
    }

    Fenwick cycleWeights(cycleCount);
    cycleWeights.build(initialWeights);

    // free(v) = subtreeSize[v] + sum(delta[x] for x in subtree(v)).
    Fenwick delta(N);

    // Finds the deepest active ancestor of a vertex.
    RangeMaxPointQuery ancestorQuery(N);
    const ll KEY_BASE = N + 1LL;

    auto keyOf = [&](int v) -> ll {
        return depth[v] * KEY_BASE + v;
    };

    // Global cycle indices; each component occupies one contiguous interval.
    set<int> activeCycle;

    auto firstActive = [&](int cid) -> int {
        int b = base[cid];
        int e = b + cycleLength[cid];
        auto it = activeCycle.lower_bound(b);
        if (it != activeCycle.end() && *it < e) return *it;
        return -1;
    };

    auto lastActive = [&](int cid) -> int {
        int b = base[cid];
        int e = b + cycleLength[cid];
        auto it = activeCycle.lower_bound(e);
        if (it == activeCycle.begin()) return -1;
        --it;
        return (*it >= b ? *it : -1);
    };

    auto nextActiveForEntry = [&](int cid, int position) -> int {
        int e = base[cid] + cycleLength[cid];
        auto it = activeCycle.lower_bound(position);
        if (it != activeCycle.end() && *it < e) return *it;
        return firstActive(cid);
    };

    // Sum of weights in the forward cycle arc (p, v].
    auto arcSum = [&](int cid, int p, int v) -> ll {
        int b = base[cid];
        int e = b + cycleLength[cid];

        if (p < v) {
            return cycleWeights.rangeSum(p + 1, v);
        }

        return cycleWeights.rangeSum(p + 1, e - 1)
             + cycleWeights.rangeSum(b, v);
    };

    vector<char> active(N + 1, false);
    vector<int> color(N + 1, -1);

    // Number of cows currently stopping at each active tree host.
    vector<ll> ownedTree(N + 1, 0);

    // Number of cows currently stopping at each active cycle host.
    vector<ll> ownerWeight(N + 1, 0);

    array<ll, 3> answer{0, 0, 0};

    auto activateTree = [&](int u) {
        ll best = ancestorQuery.query(tin[u]);
        int p = (best == 0 ? 0 : (int)(best % KEY_BASE));

        ll K = (ll)subtreeSize[u]
             + delta.rangeSum(tin[u], tout[u]);

        int root = rootCycle[u];
        int cid = component[root];
        int rootPosition = cycleIndex[root];

        bool parentIsTree = (p != 0 && !onCycle[p]);

        if (parentIsTree) {
            ownedTree[p] -= K;
            answer[color[p]] -= K;
        } else if (p != 0) {
            // The closest active ancestor is this cycle vertex.
            ownerWeight[p] -= K;
            answer[color[p]] -= K;
        } else {
            // These cows previously continued around the cycle.
            int q = nextActiveForEntry(cid, rootPosition);
            if (q != -1) {
                int qVertex = cycleNodes[q];
                ownerWeight[qVertex] -= K;
                answer[color[qVertex]] -= K;
            }
        }

        ownedTree[u] = K;
        answer[color[u]] += K;

        // Update free() on exactly the affected ancestor path.
        delta.add(tin[a[u]], -K);

        if (parentIsTree) {
            // Cancel the change above p, but retain the change at p.
            delta.add(tin[a[p]], K);
        } else {
            // The cycle root's weight decreases by K.
            cycleWeights.add(rootPosition, -K);
        }

        ancestorQuery.update(tin[u], tout[u], keyOf(u));
    };

    auto activateCycle = [&](int u) {
        int cid = component[u];
        int b = base[cid];
        int e = b + cycleLength[cid];
        int position = cycleIndex[u];

        int first = firstActive(cid);

        if (first == -1) {
            // This is the first active party on this cycle.
            ll total = cycleWeights.rangeSum(b, e - 1);
            ownerWeight[u] = total;
            answer[color[u]] += total;
        } else {
            int last = lastActive(cid);
            auto lower = activeCycle.lower_bound(position);

            int successor;
            if (lower != activeCycle.end() && *lower < e) {
                successor = *lower;
            } else {
                successor = first;
            }

            int predecessor;
            if (lower != activeCycle.begin()) {
                auto previous = prev(lower);
                predecessor = (*previous >= b ? *previous : last);
            } else {
                predecessor = last;
            }

            ll transferred = arcSum(cid, predecessor, position);
            int successorVertex = cycleNodes[successor];

            ownerWeight[successorVertex] -= transferred;
            answer[color[successorVertex]] -= transferred;

            ownerWeight[u] = transferred;
            answer[color[u]] += transferred;
        }

        activeCycle.insert(position);
        ancestorQuery.update(tin[u], tout[u], keyOf(u));
    };

    for (int night = 0; night < M; ++night) {
        int c;
        char type;
        cin >> c >> type;

        int newColor = (type == 'C' ? 0 : (type == 'O' ? 1 : 2));

        if (!active[c]) {
            active[c] = true;
            color[c] = newColor;

            if (onCycle[c]) {
                activateCycle(c);
            } else {
                activateTree(c);
            }
        } else if (color[c] != newColor) {
            ll count = onCycle[c] ? ownerWeight[c] : ownedTree[c];

            answer[color[c]] -= count;
            answer[newColor] += count;
            color[c] = newColor;
        }

        cout << answer[0] << ' ' << answer[1] << ' ' << answer[2] << '\n';
    }

    return 0;
}

