int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int N;
        cin >> N;

        vector<pair<long long, int>> items(N);
        for (int i = 0; i < N; ++i) {
            cin >> items[i].first;
            items[i].second = i + 1;
        }
        sort(items.begin(), items.end());

        Fenwick fw(N);
        vector<vector<int>> groups;
        int lowerCount = 0;

        for (int l = 0; l < N; ) {
            int r = l;
            while (r < N && items[r].first == items[l].first) ++r;

            vector<int> costs;
            costs.reserve(r - l);
            for (int i = l; i < r; ++i) {
                int p = items[i].second;
                int before = fw.sum(p - 1);
                int after = lowerCount - before;
                costs.push_back(min(before, after));
            }
            for (int i = l; i < r; ++i) fw.add(items[i].second, 1);

            groups.push_back(move(costs));
            lowerCount += r - l;
            l = r;
        }

        long long answer = 0;
        int remainingRanks = max(0, N - 2);

        for (int g = (int)groups.size() - 1; g >= 0 && remainingRanks > 0; --g) {
            auto &costs = groups[g];
            int take = min(remainingRanks, (int)costs.size());

            if (take < (int)costs.size()) {
                nth_element(costs.begin(), costs.begin() + take, costs.end());
            }
            for (int i = 0; i < take; ++i) answer += costs[i];
            remainingRanks -= take;
        }

        cout << answer << '\n';
    }

    return 0;
}

