    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<pair<int, int>> buckets(N);
        for (int i = 0; i < N; ++i) {
            cin >> buckets[i].first;
            buckets[i].second = i;
        }

        sort(buckets.begin(), buckets.end());

        Fenwick fenwick(N);
        long long answer = 0;
        int smallerCount = 0;

        for (int left = 0; left < N; ) {
            int right = left + 1;
            while (right < N && buckets[right].first == buckets[left].first) {
                ++right;
            }

            // Query before inserting this group so that only strictly
            // smaller buckets are counted.
            for (int k = left; k < right; ++k) {
                int position = buckets[k].second;
                int smallerLeft = fenwick.prefixSum(position);
                int smallerRight = smallerCount - smallerLeft;

                answer += min(smallerLeft, smallerRight);
            }

            for (int k = left; k < right; ++k) {
                fenwick.add(buckets[k].second + 1);
            }

            smallerCount += right - left;
            left = right;
        }

        cout << answer << '\n';
    }

    return 0;
}

