            long long activeSum = multiplier * activeBaseSum % MOD;
            total += activeSum;
            if (total >= MOD) total -= MOD;

            multiplier = multiplier * 2 % MOD;
            invMultiplier = invMultiplier * INV2 % MOD;
        }
