    long long activeBase = 0; // Sum of base weights of active coaches.
    long long mult = 1;       // Actual active weight = mult * base weight.
    long long invMult = 1;

    for (int i = 0; i < N; ++i) {
        long long p;
        int type;
        cin >> p >> type;

        if (type == 1) {
            // Appending this coach to any previous subset, or to the empty set.
            long long ways = (total + 1) % MOD;
            total += ways;
            if (total >= MOD) total -= MOD;

            long long base = ways * invMult % MOD;
            coachPos[tail] = p;
            coachBase[tail] = base;
            ++tail;

            activeBase += base;
            if (activeBase >= MOD) activeBase -= MOD;
        } else {
