            while (head < tail && coachPos[head] < leftLimit) {
                activeBase -= coachBase[head];
                if (activeBase < 0) activeBase += MOD;
                ++head;
            }

            // Every state whose latest coach is active gains one new subset
            // by selecting this camper, so all those state weights double.
            long long eligible = mult * activeBase % MOD;
            total += eligible;
            if (total >= MOD) total -= MOD;

            mult = mult * 2 % MOD;
            invMult = invMult * INV2 % MOD;
        }
    }

    cout << total << '\n';
    return 0;
}

