        if (c == '-') {
            sign = -1;
            c = readChar();
        }

        T num = 0;
        while (c >= '0' && c <= '9') {
            num = num * 10 + (c - '0');
            c = readChar();
        }

        out = num * sign;
        return true;
    }
};

