int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    const int INF = 1e9;

    while (T--) {
        int N, M;
        cin >> N >> M;

        vector<vector<Edge>> adj(N);
        vector<int> minLabel(N, 26);

        for (int i = 0; i < M; i++) {
            int u, v;
            char ch;
            cin >> u >> v >> ch;
            --u;
            --v;
            int c = ch - 'a';

            adj[u].push_back({v, c});
            adj[v].push_back({u, c});

            minLabel[u] = min(minLabel[u], c);
            minLabel[v] = min(minLabel[v], c);
        }

        vector<int> ans(N, -1);
        ans[0] = 0;

        vector<int> S;
        S.push_back(0);

        int depth = 0;

        vector<int> dist0(N), dist1(N), q(2 * N);

        while (!S.empty()) {
            int c = 26;
            for (int u : S) {
                c = min(c, minLabel[u]);
            }

            vector<int> T;
            T.reserve(S.size());

            for (int u : S) {
                if (minLabel[u] == c) {
                    T.push_back(u);
                }
            }

            fill(dist0.begin(), dist0.end(), INF);
            fill(dist1.begin(), dist1.end(), INF);

            int head = 0, tail = 0;

            for (int u : T) {
                if (dist0[u] == INF) {
                    dist0[u] = 0;
                    q[tail++] = 2 * u;
                }
            }

            while (head < tail) {
                int id = q[head++];
                int v = id >> 1;
                int parity = id & 1;
                int cur = parity ? dist1[v] : dist0[v];

                for (const Edge &e : adj[v]) {
                    if (e.c != c) continue;

                    int to = e.to;
                    int np = parity ^ 1;

                    if (np == 0) {
                        if (dist0[to] == INF) {
                            dist0[to] = cur + 1;
                            q[tail++] = 2 * to;
                        }
                    } else {
                        if (dist1[to] == INF) {
                            dist1[to] = cur + 1;
                            q[tail++] = 2 * to + 1;
                        }
                    }
                }
            }

            int endDist = INF;

            for (int v = 0; v < N; v++) {
                if (minLabel[v] < c) {
                    int d = min(dist0[v], dist1[v]);
                    if (d < endDist) endDist = d;
                }
            }

            if (endDist == INF) {
                for (int v = 0; v < N; v++) {
                    int d = min(dist0[v], dist1[v]);
                    if (d < INF) {
                        int val = depth + d;
                        if (ans[v] == -1 || val < ans[v]) {
                            ans[v] = val;
                        }
                    }
                }
                break;
            }

            for (int v = 0; v < N; v++) {
                int d = min(dist0[v], dist1[v]);
                if (d <= endDist) {
                    int val = depth + d;
                    if (ans[v] == -1 || val < ans[v]) {
                        ans[v] = val;
                    }
                }
            }

            vector<int> newS;

            int needParity = endDist & 1;

            if (needParity == 0) {
                for (int v = 0; v < N; v++) {
                    if (dist0[v] <= endDist) {
                        newS.push_back(v);
                    }
                }
            } else {
                for (int v = 0; v < N; v++) {
                    if (dist1[v] <= endDist) {
                        newS.push_back(v);
                    }
                }
            }

            depth += endDist;
            S.swap(newS);

            if (depth >= N) break;
        }

        for (int i = 0; i < N; i++) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
