const int INF = 1e9;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N, M;
        cin >> N >> M;

        vector<vector<pair<int,int>>> adj(N);
        vector<unsigned int> mask(N, 0);

        for (int i = 0; i < M; i++) {
            int u, v;
            char ch;
            cin >> u >> v >> ch;
            --u; --v;
            int c = ch - 'a';

            if (u == v) {
                adj[u].push_back({v, c});
            } else {
                adj[u].push_back({v, c});
                adj[v].push_back({u, c});
            }

            mask[u] |= (1u << c);
            mask[v] |= (1u << c);
        }

        vector<long long> ans(N, -1);
        ans[0] = 0;

        vector<int> S;
        S.push_back(0);

        long long curTime = 0;
        int curChar = -1;

        if (mask[0] != 0) {
            curChar = __builtin_ctz(mask[0]);
        }

        vector<int> q;
        q.reserve(2 * N);

        while (curChar != -1) {
            vector<int> d0(N, INF), d1(N, INF);

            q.clear();

            for (int v : S) {
                if (d0[v] == INF) {
                    d0[v] = 0;
                    q.push_back(v * 2);
                }
            }

            size_t head = 0;
            while (head < q.size()) {
                int state = q[head++];
                int u = state >> 1;
                int parity = state & 1;
                int du = parity ? d1[u] : d0[u];

                for (auto [v, label] : adj[u]) {
                    if (label != curChar) continue;

                    int np = parity ^ 1;
                    int nd = du + 1;

                    if (np == 0) {
                        if (d0[v] > nd) {
                            d0[v] = nd;
                            q.push_back(v * 2);
                        }
                    } else {
                        if (d1[v] > nd) {
                            d1[v] = nd;
                            q.push_back(v * 2 + 1);
                        }
                    }
                }
            }

            unsigned lowerMask = (curChar == 0 ? 0u : ((1u << curChar) - 1u));

            int firstDrop = INF;

            for (int v = 0; v < N; v++) {
                if (mask[v] & lowerMask) {
                    int d = min(d0[v], d1[v]);
                    if (d < firstDrop) firstDrop = d;
                }
            }

            if (firstDrop == INF) {
                for (int v = 0; v < N; v++) {
                    int d = min(d0[v], d1[v]);
                    if (d < INF && ans[v] == -1) {
                        ans[v] = curTime + d;
                    }
                }
                break;
            }

            for (int v = 0; v < N; v++) {
                int d = min(d0[v], d1[v]);
                if (d <= firstDrop && ans[v] == -1) {
                    ans[v] = curTime + d;
                }
            }

            vector<int> nextS;
            nextS.reserve(N);

            int needParity = firstDrop & 1;
            unsigned hasCurChar = (1u << curChar);

            for (int v = 0; v < N; v++) {
                int dpar = needParity ? d1[v] : d0[v];

                if (dpar <= firstDrop) {
                    if (dpar == 0 && firstDrop > 0 && (mask[v] & hasCurChar) == 0) {
                        continue;
                    }
                    nextS.push_back(v);
                }
            }

            int nextChar = 26;

            for (int v : nextS) {
                unsigned m = mask[v] & lowerMask;
                if (m) {
                    int lb = __builtin_ctz(m);
                    if (lb < nextChar) nextChar = lb;
                }
            }

            curTime += firstDrop;
            S.swap(nextS);
            curChar = nextChar;

            if (curChar == 26) break;
        }

        for (int i = 0; i < N; i++) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    const int INF = 1e9;

    while (T--) {
        int N, M;
        cin >> N >> M;

        vector<int> mn(N, 26);
        vector<vector<pair<int,int>>> edgesByLabel(26);

        for (int i = 0; i < M; ++i) {
            int u, v;
            char ch;
            cin >> u >> v >> ch;
            --u; --v;
            int c = ch - 'a';
            edgesByLabel[c].push_back({u, v});
            mn[u] = min(mn[u], c);
            mn[v] = min(mn[v], c);
        }

        if (N == 1 && M == 0) {
            cout << 0 << '\n';
            continue;
        }

        // Compute B(v): the lexicographically smallest infinite walk from v.
        vector<vector<int>> activeByLabel(26);
        for (int v = 0; v < N; ++v) {
            activeByLabel[mn[v]].push_back(v);
        }

        vector<int> runLen(N, -1), suffixRank(N, -1), rankB(N, -1);
        vector<int> rep;
        int nextRank = 0;

        vector<int> head(N, -1), distTmp(N, -1), bestTmp(N, -1);

        for (int c = 0; c < 26; ++c) {
            if (activeByLabel[c].empty()) continue;

            vector<int> touched;
            vector<int> to, nxt;
            int E = (int)edgesByLabel[c].size();
            to.reserve(2 * E);
            nxt.reserve(2 * E);

            for (auto [u, v] : edgesByLabel[c]) {
                if (head[u] == -1) {
                    touched.push_back(u);
                    distTmp[u] = -1;
                    bestTmp[u] = -1;
                }
                to.push_back(v);
                nxt.push_back(head[u]);
                head[u] = (int)to.size() - 1;

                if (head[v] == -1) {
                    touched.push_back(v);
                    distTmp[v] = -1;
                    bestTmp[v] = -1;
                }
                to.push_back(u);
                nxt.push_back(head[v]);
                head[v] = (int)to.size() - 1;
            }

            vector<int> q;
            q.reserve(touched.size());

            for (int x : touched) {
                if (mn[x] < c) {
                    distTmp[x] = 0;
                    bestTmp[x] = rankB[x];
                    q.push_back(x);
                }
            }

            for (size_t qi = 0; qi < q.size(); ++qi) {
                int u = q[qi];
                int du = distTmp[u];

                for (int e = head[u]; e != -1; e = nxt[e]) {
                    int v = to[e];
                    if (mn[v] < c) continue;

                    if (distTmp[v] == -1) {
                        distTmp[v] = du + 1;
                        bestTmp[v] = bestTmp[u];
                        q.push_back(v);
                    } else if (distTmp[v] == du + 1) {
                        bestTmp[v] = min(bestTmp[v], bestTmp[u]);
                    }
                }
            }

            for (int v : activeByLabel[c]) {
                if (distTmp[v] == -1) {
                    runLen[v] = INF;
                    suffixRank[v] = -1;
                } else {
                    runLen[v] = distTmp[v];
                    suffixRank[v] = bestTmp[v];
                }
            }

            auto &vec = activeByLabel[c];
            sort(vec.begin(), vec.end(), [&](int a, int b) {
                if (runLen[a] != runLen[b]) return runLen[a] < runLen[b];
                return suffixRank[a] < suffixRank[b];
            });

            int prevRun = INT_MIN, prevSuf = INT_MIN, curRank = -1;

            for (int v : vec) {
                if (runLen[v] != prevRun || suffixRank[v] != prevSuf) {
                    curRank = nextRank++;
                    rep.push_back(v);
                    prevRun = runLen[v];
                    prevSuf = suffixRank[v];
                }
                rankB[v] = curRank;
            }

            for (int x : touched) head[x] = -1;
        }

        // Build the run-length encoding of W = B(1).
        vector<pair<int,int>> runs;
        int finalChar = -1;
        int cur = 0;

        while (true) {
            int c = mn[cur];
            if (runLen[cur] == INF) {
                finalChar = c;
                break;
            } else {
                int d = runLen[cur];
                runs.push_back({c, d});
                int suf = suffixRank[cur];
                cur = rep[suf];
            }
        }

        // Simulate the word W to find the first occurrence of each vertex.
        vector<int> ans(N, -1);
        vector<char> inCurrent(N, 0);
        vector<int> currentSet;
        currentSet.push_back(0);
        inCurrent[0] = 1;
        ans[0] = 0;

        int curTime = 0;
        vector<int> headSim(N, -1);
        vector<int> d0(N, -1), d1(N, -1);

        for (auto [c, L] : runs) {
            vector<int> touched;
            vector<int> to, nxt;

            for (auto [u, v] : edgesByLabel[c]) {
                if (headSim[u] == -1) {
                    touched.push_back(u);
                    headSim[u] = -1;
                }
                to.push_back(v);
                nxt.push_back(headSim[u]);
                headSim[u] = (int)to.size() - 1;

                if (headSim[v] == -1) {
                    touched.push_back(v);
                    headSim[v] = -1;
                }
                to.push_back(u);
                nxt.push_back(headSim[v]);
                headSim[v] = (int)to.size() - 1;
            }

            for (int x : touched) {
                d0[x] = d1[x] = -1;
            }

            vector<pair<int,int>> q;
            q.reserve(touched.size() * 2);

            for (int x : touched) {
                if (inCurrent[x]) {
                    d0[x] = 0;
                    q.push_back({x, 0});
                }
            }

            for (size_t qi = 0; qi < q.size(); ++qi) {
                int u = q[qi].first;
                int p = q[qi].second;
                int du = (p == 0 ? d0[u] : d1[u]);

                for (int e = headSim[u]; e != -1; e = nxt[e]) {
                    int v = to[e];
                    int np = p ^ 1;

                    if (np == 0) {
                        if (d0[v] == -1) {
                            d0[v] = du + 1;
                            q.push_back({v, 0});
                        }
                    } else {
                        if (d1[v] == -1) {
                            d1[v] = du + 1;
                            q.push_back({v, 1});
                        }
                    }
                }
            }

            int parity = L & 1;
            vector<int> nextSet;

            for (int v : touched) {
                int md = INF;
                if (d0[v] != -1) md = min(md, d0[v]);
                if (d1[v] != -1) md = min(md, d1[v]);

                if (md <= L && ans[v] == -1) {
                    ans[v] = curTime + md;
                }

                int dpar = (parity == 0 ? d0[v] : d1[v]);
                if (dpar != -1 && dpar <= L) {
                    nextSet.push_back(v);
                }
            }

            for (int v : currentSet) inCurrent[v] = 0;
            for (int v : nextSet) inCurrent[v] = 1;

            currentSet.swap(nextSet);
            curTime += L;

            for (int x : touched) headSim[x] = -1;
        }

        // Final infinite run.
        if (finalChar != -1) {
            int c = finalChar;

            vector<int> touched;
            vector<int> to, nxt;

            for (auto [u, v] : edgesByLabel[c]) {
                if (headSim[u] == -1) {
                    touched.push_back(u);
                    headSim[u] = -1;
                }
                to.push_back(v);
                nxt.push_back(headSim[u]);
                headSim[u] = (int)to.size() - 1;

                if (headSim[v] == -1) {
                    touched.push_back(v);
                    headSim[v] = -1;
                }
                to.push_back(u);
                nxt.push_back(headSim[v]);
                headSim[v] = (int)to.size() - 1;
            }

            for (int x : touched) d0[x] = -1;

            vector<int> q;
            for (int x : touched) {
                if (inCurrent[x]) {
                    d0[x] = 0;
                    q.push_back(x);
                }
            }

            for (size_t qi = 0; qi < q.size(); ++qi) {
                int u = q[qi];

                for (int e = headSim[u]; e != -1; e = nxt[e]) {
                    int v = to[e];
                    if (d0[v] == -1) {
                        d0[v] = d0[u] + 1;
                        q.push_back(v);
                    }
                }
            }

            for (int v : touched) {
                if (d0[v] != -1 && ans[v] == -1) {
                    ans[v] = curTime + d0[v];
                }
            }

            for (int x : touched) headSim[x] = -1;
        }

        for (int i = 0; i < N; ++i) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }

    return 0;
}

