    cin >> T;

    constexpr int ALPHABET = 26;
    constexpr int INF = 1'000'000'000;

    while (T--) {
        int N, M;
        cin >> N >> M;

        vector<vector<Edge>> adj(N);
        vector<int> minLabel(N, ALPHABET);

        for (int i = 0; i < M; ++i) {
            int u, v;
            char ch;
            cin >> u >> v >> ch;
            --u;
            --v;

            int label = ch - 'a';
            adj[u].push_back({v, label});
            if (u != v) {
                adj[v].push_back({u, label});
            } else {
                // A self-loop only needs to be stored once.
            }

            minLabel[u] = min(minLabel[u], label);
            minLabel[v] = min(minLabel[v], label);
        }

        if (N == 1) {
            cout << 0 << '\n';
            continue;
        }

        vector<int> answer(N, -1);
        vector<unsigned char> seen(N, 0);
        answer[0] = 0;
        seen[0] = 1;

        // The lexicographically greedy sequence of edge labels is
        // nonincreasing, so it has at most 26 constant-label phases.
        vector<int> current = {0};
        int currentLength = 0;
        int currentLabel = minLabel[0];

        vector<array<int, 2>> dist(N);
        vector<int> first(N);
        vector<int> bfsQueue;
        bfsQueue.reserve(2 * N);

        while (true) {
            for (int v : current) {
                if (!seen[v]) {
                    seen[v] = 1;
                    answer[v] = currentLength;
                }
            }

            // Only vertices whose minimum incident label equals
            // currentLabel can continue a currentLabel edge.
            vector<int> seeds;
            seeds.reserve(current.size());
            for (int v : current) {
                if (minLabel[v] == currentLabel) {
                    seeds.push_back(v);
                }
            }

            fill(dist.begin(), dist.end(), array<int, 2>{INF, INF});
            bfsQueue.clear();

            for (int v : seeds) {
                dist[v][0] = 0;
                bfsQueue.push_back(2 * v);
            }

            // BFS on (vertex, path-length parity), using only
            // currentLabel edges.
            for (size_t head = 0; head < bfsQueue.size(); ++head) {
                int state = bfsQueue[head];
                int v = state >> 1;
                int parity = state & 1;
                int nextParity = parity ^ 1;

                for (const Edge &e : adj[v]) {
                    if (e.label != currentLabel) continue;

                    if (dist[e.to][nextParity] == INF) {
                        dist[e.to][nextParity] = dist[v][parity] + 1;
                        bfsQueue.push_back(2 * e.to + nextParity);
                    }
                }
            }

            // A phase ends when a vertex with a smaller incident label
            // first becomes reachable.
            int phaseEnd = INF;

            for (int v = 0; v < N; ++v) {
                first[v] = min(dist[v][0], dist[v][1]);
                if (minLabel[v] < currentLabel) {
                    phaseEnd = min(phaseEnd, first[v]);
                }
            }

            for (int v = 0; v < N; ++v) {
                if (!seen[v] && first[v] != INF && first[v] <= phaseEnd) {
                    seen[v] = 1;
                    answer[v] = currentLength + first[v];
                }
            }

            if (phaseEnd == INF) {
                // This label phase continues forever. No later phase exists.
                break;
            }

            // Construct the exact endpoint set after phaseEnd edges
            // of the current label.
            vector<int> nextCurrent;
            nextCurrent.reserve(N);

            int nextLabel = ALPHABET;
            int parity = phaseEnd & 1;

            for (int v = 0; v < N; ++v) {
                if (dist[v][parity] <= phaseEnd) {
                    nextCurrent.push_back(v);
                    nextLabel = min(nextLabel, minLabel[v]);
                }
            }

            current.swap(nextCurrent);
            currentLength += phaseEnd;
            currentLabel = nextLabel;
        }

        for (int v = 0; v < N; ++v) {
            if (v) cout << ' ';
            cout << answer[v];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct FlatAdjacency {
    vector<int> head, to, nextEdge;

    FlatAdjacency(int n, size_t edgeCount) : head(n, -1) {
        to.reserve(2 * edgeCount);
        nextEdge.reserve(2 * edgeCount);
    }

    void addDirected(int u, int v) {
        int id = (int)to.size();
        to.push_back(v);
        nextEdge.push_back(head[u]);
        head[u] = id;
    }

    void addUndirected(int u, int v) {
        addDirected(u, v);
        addDirected(v, u);
    }
};

void solve() {
    int N, M;
    cin >> N >> M;

    array<vector<pair<int, int>>, 26> edgesByLabel;
    vector<int> minimumIncidentLabel(N, 26);

    for (int i = 0; i < M; ++i) {
        int u, v;
        char ch;
        cin >> u >> v >> ch;
        --u;
        --v;

        int label = ch - 'a';
        edgesByLabel[label].push_back({u, v});
        minimumIncidentLabel[u] = min(minimumIncidentLabel[u], label);
        minimumIncidentLabel[v] = min(minimumIncidentLabel[v], label);
    }

    vector<long long> answer(N, -1);
    answer[0] = 0;

    if (N > 1) {
        const int INF = 1'000'000'000;

        // Endpoints of the current greedy prefix.
        vector<int> current{0};

        // Character used by the current constant-character phase.
        int phaseLabel = minimumIncidentLabel[0];

        // Length of the prefix before the current phase.
        long long phaseStartTime = 0;

        vector<int> dist(2 * N);
        vector<int> bfsQueue(2 * N);

        while (true) {
            FlatAdjacency adjacency(N, edgesByLabel[phaseLabel].size());
            vector<char> hasPhaseEdge(N, false);

            for (auto [u, v] : edgesByLabel[phaseLabel]) {
                adjacency.addUndirected(u, v);
                hasPhaseEdge[u] = true;
                hasPhaseEdge[v] = true;
            }

            /*
             * BFS on parity-expanded vertices.
             *
             * State 2*v+p means that we are at v after a walk whose length
             * has parity p.
             */
            fill(dist.begin(), dist.end(), INF);
            int front = 0, back = 0;

            for (int v : current) {
                dist[2 * v] = 0;
                bfsQueue[back++] = 2 * v;
            }

            while (front < back) {
                int state = bfsQueue[front++];
                int v = state / 2;
                int nextParity = (state & 1) ^ 1;

                for (int e = adjacency.head[v]; e != -1; e = adjacency.nextEdge[e]) {
                    int w = adjacency.to[e];
                    int nextState = 2 * w + nextParity;

                    if (dist[nextState] == INF) {
                        dist[nextState] = dist[state] + 1;
                        bfsQueue[back++] = nextState;
                    }
                }
            }

            vector<int> firstAppearance(N, INF);
            int phaseEnd = INF;

            for (int v = 0; v < N; ++v) {
                firstAppearance[v] = min(dist[2 * v], dist[2 * v + 1]);

                // This vertex offers a smaller next character.
                if (minimumIncidentLabel[v] < phaseLabel) {
                    phaseEnd = min(phaseEnd, firstAppearance[v]);
                }
            }

            if (phaseEnd == INF) {
                // The phase never changes character.
                for (int v = 0; v < N; ++v) {
                    if (firstAppearance[v] != INF && answer[v] == -1) {
                        answer[v] = phaseStartTime + firstAppearance[v];
                    }
                }
                break;
            }

            // Assign all vertices that first appear during this phase.
            for (int v = 0; v < N; ++v) {
                if (firstAppearance[v] != INF &&
                    firstAppearance[v] <= phaseEnd &&
                    answer[v] == -1) {
                    answer[v] = phaseStartTime + firstAppearance[v];
                }
            }

            // Compute the endpoint set after exactly phaseEnd phase edges.
            vector<int> nextCurrent;
            nextCurrent.reserve(N);

            if (phaseEnd == 0) {
                nextCurrent = current;
            } else {
                int parity = phaseEnd & 1;
                for (int v = 0; v < N; ++v) {
                    if (hasPhaseEdge[v] &&
                        dist[2 * v + parity] <= phaseEnd) {
                        nextCurrent.push_back(v);
                    }
                }
            }

            int nextLabel = 26;
            for (int v : nextCurrent) {
                nextLabel = min(nextLabel, minimumIncidentLabel[v]);
            }

            phaseStartTime += phaseEnd;
            current.swap(nextCurrent);
            phaseLabel = nextLabel;
        }
    }

    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << answer[i];
    }
    cout << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        solve();
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to;
    int label;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    constexpr int ALPHABET = 26;

    while (T--) {
        int N, M;
        cin >> N >> M;

        vector<vector<Edge>> adj(N);
        vector<int> smallest(N, ALPHABET);

        for (int i = 0; i < M; ++i) {
            int u, v;
            char ch;
            cin >> u >> v >> ch;
            --u;
            --v;

            int label = ch - 'a';
            adj[u].push_back({v, label});
            adj[v].push_back({u, label});
            smallest[u] = min(smallest[u], label);
            smallest[v] = min(smallest[v], label);
        }

        vector<long long> answer(N, -1);
        answer[0] = 0;

        vector<int> current{0};
        vector<int> nextSet;
        vector<int> bfsQueue;
        bfsQueue.reserve(N);

        vector<int> dist(N);
        vector<int> marked(N, 0);
        int stamp = 0;

        // The current set consists of vertices reachable after exactly
        // 'depth' edges of the greedily constructed lexicographic prefix.
        long long depth = 0;

        while (!current.empty()) {
            int currentLabel = ALPHABET;
            for (int v : current) {
                currentLabel = min(currentLabel, smallest[v]);
            }

            // This occurs only for the single-vertex, zero-edge graph.
            if (currentLabel == ALPHABET) {
                break;
            }

            // While currentLabel stays unchanged, the greedy set evolves
            // by taking all neighbors through edges with this label.
            fill(dist.begin(), dist.end(), -1);
            bfsQueue.clear();

            for (int v : current) {
                if (dist[v] == -1) {
                    dist[v] = 0;
                    bfsQueue.push_back(v);
                }
            }

            for (size_t head = 0; head < bfsQueue.size(); ++head) {
                int v = bfsQueue[head];
                for (const Edge &e : adj[v]) {
                    if (e.label == currentLabel && dist[e.to] == -1) {
                        dist[e.to] = dist[v] + 1;
                        bfsQueue.push_back(e.to);
                    }
                }
            }

            // Find the first layer at which the greedy label decreases.
            int switchDistance = N + 1;
            int nextLabel = ALPHABET;

            for (int v = 0; v < N; ++v) {
                if (dist[v] == -1 || smallest[v] >= currentLabel) {
                    continue;
                }

                if (dist[v] < switchDistance) {
                    switchDistance = dist[v];
                    nextLabel = smallest[v];
                } else if (dist[v] == switchDistance) {
                    nextLabel = min(nextLabel, smallest[v]);
                }
            }

            int limit = (switchDistance == N + 1 ? N : switchDistance);

            // A vertex's first occurrence in this phase is its BFS distance.
            for (int v = 0; v < N; ++v) {
                if (dist[v] != -1 && dist[v] <= limit) {
                    long long candidate = depth + dist[v];
                    if (answer[v] == -1 || candidate < answer[v]) {
                        answer[v] = candidate;
                    }
                }
            }

            // No smaller label is reachable, so the greedy process remains
            // in this phase forever.
            if (switchDistance == N + 1) {
                break;
            }

            // At the switching layer, only vertices whose smallest incident
            // label equals nextLabel can use an edge with that label.
            ++stamp;
            nextSet.clear();

            for (int v = 0; v < N; ++v) {
                if (dist[v] != switchDistance || smallest[v] != nextLabel) {
                    continue;
                }

                for (const Edge &e : adj[v]) {
                    if (e.label == nextLabel && marked[e.to] != stamp) {
                        marked[e.to] = stamp;
                        nextSet.push_back(e.to);
                    }
                }
            }

            depth += static_cast<long long>(switchDistance) + 1;
            current.swap(nextSet);
        }

        for (int i = 0; i < N; ++i) {
            if (i) cout << ' ';
            cout << answer[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Component {
    int len = 0;
    vector<int> safeDist;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<int> nxt(N);
    vector<vector<int>> radj(N);
    vector<int> indeg(N, 0);

    for (int i = 0; i < N; ++i) {
        cin >> nxt[i];
        --nxt[i];
        radj[nxt[i]].push_back(i);
        ++indeg[nxt[i]];
    }

    vector<int> farmers(F);
    for (int &s : farmers) {
        cin >> s;
        --s;
    }

    // Earliest time at which any farmer visits each farm.
    vector<int> dist(N, -1);
    vector<int> queue(N);
    int qh = 0, qt = 0;

    for (int s : farmers) {
        dist[s] = 0;
        queue[qt++] = s;
    }

    while (qh < qt) {
        int v = queue[qh++];
        int u = nxt[v];
        if (dist[u] == -1) {
            dist[u] = dist[v] + 1;
            queue[qt++] = u;
        }
    }

    // Remove all non-cycle vertices; remaining vertices are exactly cycle vertices.
    qh = qt = 0;
    for (int i = 0; i < N; ++i) {
        if (indeg[i] == 0) queue[qt++] = i;
    }

    while (qh < qt) {
        int v = queue[qh++];
        int u = nxt[v];
        if (--indeg[u] == 0) queue[qt++] = u;
    }

    vector<int> comp(N, -1), potential(N, 0);
    vector<Component> components;

    // Assign cycle positions. potential increases by 1 modulo the cycle length
    // whenever any vertex moves along its outgoing edge.
    for (int i = 0; i < N; ++i) {
        if (indeg[i] > 0 && comp[i] == -1) {
            int cid = (int)components.size();
            components.push_back(Component());

            int v = i;
            int pos = 0;
            do {
                comp[v] = cid;
                potential[v] = pos++;
                v = nxt[v];
            } while (v != i);

            components[cid].len = pos;
        }
    }

    // Propagate component IDs and potentials into the trees feeding the cycles.
    vector<int> st;
    for (int i = 0; i < N; ++i) {
        if (indeg[i] <= 0) continue;

        st.push_back(i);
        while (!st.empty()) {
            int v = st.back();
            st.pop_back();

            int cid = comp[v];
            int L = components[cid].len;

            for (int u : radj[v]) {
                if (comp[u] != -1) continue;

                comp[u] = cid;
                potential[u] = potential[v] - 1;
                if (potential[u] < 0) potential[u] += L;
                st.push_back(u);
            }
        }
    }

    // Phases occupied by farmers are unsafe for Bessie's eventual motion.
    for (auto &c : components) c.safeDist.assign(c.len, 0);

    for (int s : farmers) {
        Component &c = components[comp[s]];
        c.safeDist[potential[s]] = -1;
    }

    const int INF = 1e9;

    // For every phase, find the distance forward to the nearest safe phase.
    for (auto &c : components) {
        int safePhase = -1;
        for (int p = 0; p < c.len; ++p) {
            if (c.safeDist[p] == 0) {
                safePhase = p;
                break;
            }
        }

        if (safePhase == -1) {
            fill(c.safeDist.begin(), c.safeDist.end(), INF);
            continue;
        }

        int d = 0;
        for (int step = 1; step < c.len; ++step) {
            int p = safePhase - step;
            if (p < 0) p += c.len;

            if (c.safeDist[p] == 0) {
                d = 0;
            } else {
                c.safeDist[p] = ++d;
            }
        }
    }

    for (int b = 0; b < N; ++b) {
        if (dist[b] == -1) {
            cout << -2 << '\n';
            continue;
        }

        if (dist[b] == 0) {
            cout << -1 << '\n';
            continue;
        }

        int r = dist[b] - 1;
        Component &c = components[comp[b]];

        int phase = potential[b] - (r % c.len);
        if (phase < 0) phase += c.len;

        int delta = c.safeDist[phase];
        if (delta > r) {
            cout << -1 << '\n';
        } else {
            cout << r - delta << '\n';
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<int> nxtNode(N);
    vector<vector<int>> rev(N);
    vector<int> indeg(N, 0);

    for (int i = 0; i < N; ++i) {
        cin >> nxtNode[i];
        --nxtNode[i];
        rev[nxtNode[i]].push_back(i);
        ++indeg[nxtNode[i]];
    }

    vector<int> farmers(F);
    for (int &s : farmers) {
        cin >> s;
        --s;
    }

    // First visit time of any farmer, by multi-source BFS on reversed edges.
    vector<int> dist(N, -1);
    vector<int> bfs;
    bfs.reserve(N);
    for (int s : farmers) {
        if (dist[s] == -1) {
            dist[s] = 0;
            bfs.push_back(s);
        }
    }
    for (size_t head = 0; head < bfs.size(); ++head) {
        int v = bfs[head];
        for (int u : rev[v]) {
            if (dist[u] == -1) {
                dist[u] = dist[v] + 1;
                bfs.push_back(u);
            }
        }
    }

    // Remove trees, leaving precisely the cycle vertices.
    vector<int> q;
    q.reserve(N);
    for (int i = 0; i < N; ++i) {
        if (indeg[i] == 0) q.push_back(i);
    }

    vector<int> removalOrder;
    removalOrder.reserve(N);
    for (size_t head = 0; head < q.size(); ++head) {
        int u = q[head];
        removalOrder.push_back(u);
        int v = nxtNode[u];
        if (--indeg[v] == 0) q.push_back(v);
    }

    vector<int> comp(N, -1), pos(N, -1), depth(N, -1), root(N, -1);
    vector<int> cycleLen;
    int C = 0;

    for (int i = 0; i < N; ++i) {
        if (indeg[i] > 0 && comp[i] == -1) {
            int v = i;
            int len = 0;
            do {
                comp[v] = C;
                pos[v] = len++;
                depth[v] = 0;
                root[v] = v;
                v = nxtNode[v];
            } while (comp[v] == -1);
            cycleLen.push_back(len);
            ++C;
        }
    }

    for (auto it = removalOrder.rbegin(); it != removalOrder.rend(); ++it) {
        int u = *it;
        int v = nxtNode[u];
        comp[u] = comp[v];
        root[u] = root[v];
        depth[u] = depth[v] + 1;
    }

    auto phase = [&](int v) {
        int c = comp[v];
        int L = cycleLen[c];
        int x = pos[root[v]] - depth[v] % L;
        if (x < 0) x += L;
        return x;
    };

    // A delay is eventually safe exactly when its resulting cycle phase
    // is not occupied by any farmer's phase.
    vector<vector<char>> bad(C);
    for (int c = 0; c < C; ++c) {
        bad[c].assign(cycleLen[c], 0);
    }
    for (int s : farmers) {
        bad[comp[s]][phase(s)] = 1;
    }

    // jump[p] = smallest x >= 0 such that phase p+x is safe.
    vector<vector<int>> jump(C);
    const int INF = 1000000000;

    for (int c = 0; c < C; ++c) {
        int L = cycleLen[c];
        jump[c].resize(L);

        bool hasSafe = false;
        for (int p = 0; p < L; ++p) {
            if (!bad[c][p]) {
                hasSafe = true;
                break;
            }
        }

        if (!hasSafe) {
            fill(jump[c].begin(), jump[c].end(), INF);
            continue;
        }

        int cur = L;
        for (int i = 2 * L - 1; i >= 0; --i) {
            int p = i % L;
            if (!bad[c][p]) cur = 0;
            else ++cur;
            if (i < L) jump[c][p] = cur;
        }
    }

    for (int b = 0; b < N; ++b) {
        if (dist[b] == -1) {
            cout << -2 << '\n';
            continue;
        }
        if (dist[b] == 0) {
            cout << -1 << '\n';
            continue;
        }

        int T = dist[b];
        int c = comp[b];
        int L = cycleLen[c];

        int p = phase(b) - (T - 1) % L;
        if (p < 0) p += L;

        int x = jump[c][p];
        if (x < T) cout << T - 1 - x << '\n';
        else cout << -1 << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<int> a(N);
    vector<int> head(N, -1), to(N), nxt(N);
    vector<int> indeg(N, 0);

    for (int i = 0; i < N; ++i) {
        cin >> a[i];
        --a[i];
        ++indeg[a[i]];
        to[i] = i;
        nxt[i] = head[a[i]];
        head[a[i]] = i;
    }

    vector<int> farmers(F);
    for (int &s : farmers) {
        cin >> s;
        --s;
    }

    // Remove all non-cycle nodes, recording the removal order.
    vector<int> order;
    order.reserve(N);
    queue<int> q;
    for (int i = 0; i < N; ++i) {
        if (indeg[i] == 0) q.push(i);
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u);
        int v = a[u];
        if (--indeg[v] == 0) q.push(v);
    }

    vector<int> comp(N, -1), height(N, 0), cyclePos(N, 0);
    vector<int> cycleBase, cycleLen;

    int cycleNodes = 0;
    for (int i = 0; i < N; ++i) {
        if (indeg[i] > 0 && comp[i] == -1) {
            int id = (int)cycleLen.size();
            cycleBase.push_back(cycleNodes);

            int v = i, len = 0;
            do {
                comp[v] = id;
                height[v] = 0;
                cyclePos[v] = len++;
                ++cycleNodes;
                v = a[v];
            } while (v != i);

            cycleLen.push_back(len);
        }
    }

    // Propagate cycle information from each node's successor.
    for (int i = (int)order.size() - 1; i >= 0; --i) {
        int u = order[i], v = a[u];
        comp[u] = comp[v];
        height[u] = height[v] + 1;
        cyclePos[u] = cyclePos[v];
    }

    vector<char> blocked(cycleNodes, 0);
    for (int s : farmers) {
        int c = comp[s], L = cycleLen[c];
        int k = (height[s] - cyclePos[s]) % L;
        if (k < 0) k += L;
        blocked[cycleBase[c] + k] = 1;
    }

    // prevSafe[r] is the greatest safe residue at most r.
    vector<int> prevSafe(cycleNodes, -1);
    vector<int> maxSafe(cycleLen.size(), -1);

    for (int c = 0; c < (int)cycleLen.size(); ++c) {
        int last = -1, base = cycleBase[c];
        for (int r = 0; r < cycleLen[c]; ++r) {
            if (!blocked[base + r]) last = r;
            prevSafe[base + r] = last;
        }
        maxSafe[c] = last;
    }

    // Earliest time at which any farmer reaches each farm.
    vector<int> dist(N, -1);
    queue<int> bfs;
    for (int s : farmers) {
        if (dist[s] == -1) {
            dist[s] = 0;
            bfs.push(s);
        }
    }

    while (!bfs.empty()) {
        int u = bfs.front();
        bfs.pop();
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                bfs.push(v);
            }
        }
    }

    for (int b = 0; b < N; ++b) {
        if (dist[b] == -1) {
            cout << -2 << '\n';
            continue;
        }
        if (dist[b] == 0) {
            cout << -1 << '\n';
            continue;
        }

        int c = comp[b], L = cycleLen[c], base = cycleBase[c];
        int x = dist[b] - 1; // Maximum possible number of rests.

        int shift = (cyclePos[b] - height[b]) % L;
        if (shift < 0) shift += L;

        int r = (x - shift) % L;
        if (r < 0) r += L;

        int answer = -1;
        int p = prevSafe[base + r];

        if (p != -1) {
            answer = x - (r - p);
        } else if (maxSafe[c] != -1) {
            answer = x - (r + L - maxSafe[c]);
        }

        if (answer < 0) answer = -1;
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<int> a(N);
    vector<int> indeg(N, 0);

    for (int i = 0; i < N; i++) {
        cin >> a[i];
        --a[i];
        indeg[a[i]]++;
    }

    vector<int> starts(F);
    vector<char> isFarmer(N, false);

    for (int i = 0; i < F; i++) {
        cin >> starts[i];
        --starts[i];
        isFarmer[starts[i]] = true;
    }

    // Peel trees to find cycles.
    queue<int> q;
    for (int i = 0; i < N; i++) {
        if (indeg[i] == 0) q.push(i);
    }

    vector<int> peel;
    peel.reserve(N);

    while (!q.empty()) {
        int v = q.front();
        q.pop();

        peel.push_back(v);

        int p = a[v];
        if (--indeg[p] == 0) {
            q.push(p);
        }
    }

    vector<int> comp(N, -1), depth(N, 0), cpos(N, 0), cyclePos(N, -1);
    vector<int> cycleLen;
    vector<vector<int>> cycles;

    int compCnt = 0;

    // Remaining vertices are cycle vertices.
    for (int i = 0; i < N; i++) {
        if (indeg[i] > 0 && comp[i] == -1) {
            vector<int> cyc;

            int v = i;
            do {
                comp[v] = compCnt;
                depth[v] = 0;
                cyclePos[v] = (int)cyc.size();
                cpos[v] = (int)cyc.size();
                cyc.push_back(v);
                v = a[v];
            } while (v != i);

            int L = (int)cyc.size();
            cycleLen.push_back(L);
            cycles.push_back(cyc);

            compCnt++;
        }
    }

    vector<int> x(N, 0);

    for (int id = 0; id < compCnt; id++) {
        int L = cycleLen[id];
        for (int v : cycles[id]) {
            x[v] = cpos[v] % L;
        }
    }

    // Process non-cycle vertices from near cycle outward.
    for (int idx = (int)peel.size() - 1; idx >= 0; idx--) {
        int v = peel[idx];
        int p = a[v];

        comp[v] = comp[p];
        depth[v] = depth[p] + 1;
        cpos[v] = cpos[p];

        int L = cycleLen[comp[v]];
        int val = (cpos[v] - depth[v]) % L;
        if (val < 0) val += L;
        x[v] = val;
    }

    const int INF = 1e9;

    // mn[v] = minimum depth of a farmer in the in-tree subtree of v.
    vector<int> mn(N, INF);

    for (int v : starts) {
        mn[v] = min(mn[v], depth[v]);
    }

    // Peel order goes from leaves toward cycles, so this aggregates upward.
    for (int v : peel) {
        int p = a[v];
        mn[p] = min(mn[p], mn[v]);
    }

    vector<char> compHasFarmer(compCnt, false);
    vector<vector<int>> farmVerts(compCnt);

    for (int v : starts) {
        int id = comp[v];
        compHasFarmer[id] = true;
        farmVerts[id].push_back(v);
    }

    vector<vector<int>> compVerts(compCnt);

    for (int v = 0; v < N; v++) {
        compVerts[comp[v]].push_back(v);
    }

    vector<int> ans(N, -1);
    const long long INFLL = (long long)4e18;

    for (int id = 0; id < compCnt; id++) {
        int L = cycleLen[id];

        if (!compHasFarmer[id]) {
            for (int v : compVerts[id]) {
                ans[v] = -2;
            }
            continue;
        }

        vector<char> present(L, false);

        for (int v : farmVerts[id]) {
            int xv = x[v] % L;
            if (xv < 0) xv += L;
            present[xv] = true;
        }

        bool allPresent = true;

        for (int i = 0; i < L; i++) {
            if (!present[i]) {
                allPresent = false;
                break;
            }
        }

        vector<int> nextSafe(L, -1);

        if (!allPresent) {
            int nextNot = 2 * L;

            for (int i = 2 * L - 1; i >= 0; i--) {
                int idx = i % L;

                if (!present[idx]) {
                    nextNot = i;
                }

                if (i < L) {
                    nextSafe[i] = nextNot - i;
                }
            }
        }

        // Earliest time a farmer can be at each cycle vertex.
        vector<int> D(L, INF);

        for (int v : farmVerts[id]) {
            int cp = cpos[v];
            int d = depth[v];

            if (d < D[cp]) {
                D[cp] = d;
            }
        }

        vector<int> pref(L, INF), suff(L + 1, INF);

        for (int i = 0; i < L; i++) {
            if (D[i] < INF) {
                pref[i] = D[i] - i;
            }
        }

        for (int i = 1; i < L; i++) {
            pref[i] = min(pref[i], pref[i - 1]);
        }

        for (int i = L - 1; i >= 0; i--) {
            suff[i] = suff[i + 1];

            if (D[i] < INF) {
                suff[i] = min(suff[i], D[i] - i);
            }
        }

        vector<long long> T(L, INFLL);

        for (int p = 0; p < L; p++) {
            long long best = INFLL;

            if (pref[p] < INF) {
                best = min(best, (long long)p + pref[p]);
            }

            if (p + 1 < L && suff[p + 1] < INF) {
                best = min(best, (long long)p + L + suff[p + 1]);
            }

            T[p] = best;
        }

        for (int v : compVerts[id]) {
            if (isFarmer[v]) {
                ans[v] = -1;
                continue;
            }

            if (depth[v] == 0) {
                // Bessie starts on the cycle.
                int p = cyclePos[v];
                long long t = T[p];

                if (t <= 0) {
                    ans[v] = -1;
                    continue;
                }

                if (allPresent) {
                    ans[v] = -1;
                    continue;
                }

                long long r = t - 1;
                int y0 = (int)(((p - (r % L)) % L + L) % L);
                int d = nextSafe[y0];

                if (d <= r) {
                    ans[v] = (int)(r - d);
                } else {
                    ans[v] = -1;
                }
            } else {
                // Bessie starts in a tree.
                if (mn[v] >= INF) {
                    ans[v] = -2;
                    continue;
                }

                int C = mn[v] - depth[v] - 1;

                if (C < 0) {
                    ans[v] = -1;
                    continue;
                }

                if (allPresent) {
                    ans[v] = -1;
                    continue;
                }

                long long Cll = C;
                int y0 = (int)(((x[v] - (Cll % L)) % L + L) % L);
                int d = nextSafe[y0];

                if (d <= Cll) {
                    ans[v] = (int)(Cll - d);
                } else {
                    ans[v] = -1;
                }
            }
        }
    }

    for (int i = 0; i < N; i++) {
        cout << ans[i] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<int> a(N);
    for (int i = 0; i < N; i++) {
        cin >> a[i];
        --a[i];
    }

    vector<int> starts(F);
    vector<char> isFarmer(N, 0);
    for (int i = 0; i < F; i++) {
        cin >> starts[i];
        --starts[i];
        isFarmer[starts[i]] = 1;
    }

    const int INF = 1e9;

    // dist[v] = earliest time any farmer reaches v
    vector<int> dist(N, INF);
    queue<int> bfs;
    for (int s : starts) {
        dist[s] = 0;
        bfs.push(s);
    }

    while (!bfs.empty()) {
        int u = bfs.front();
        bfs.pop();

        int v = a[u];
        if (dist[v] == INF) {
            dist[v] = dist[u] + 1;
            bfs.push(v);
        }
    }

    // Find cycle vertices using Kahn's algorithm.
    vector<int> indeg(N, 0);
    for (int i = 0; i < N; i++) {
        indeg[a[i]]++;
    }

    queue<int> qk;
    for (int i = 0; i < N; i++) {
        if (indeg[i] == 0) qk.push(i);
    }

    vector<int> removed;
    while (!qk.empty()) {
        int u = qk.front();
        qk.pop();
        removed.push_back(u);

        int v = a[u];
        indeg[v]--;
        if (indeg[v] == 0) qk.push(v);
    }

    vector<int> comp(N, -1);
    vector<int> p(N, 0);
    vector<int> compC;

    // Assign cycle vertices.
    for (int i = 0; i < N; i++) {
        if (indeg[i] > 0 && comp[i] == -1) {
            int cid = (int)compC.size();

            vector<int> cyc;
            int cur = i;
            do {
                comp[cur] = cid;
                cyc.push_back(cur);
                cur = a[cur];
            } while (cur != i);

            int C = (int)cyc.size();
            compC.push_back(C);

            for (int pos = 0; pos < C; pos++) {
                p[cyc[pos]] = pos;
            }
        }
    }

    // Assign non-cycle vertices in reverse removal order.
    for (int idx = (int)removed.size() - 1; idx >= 0; idx--) {
        int u = removed[idx];
        int v = a[u];

        comp[u] = comp[v];
        int C = compC[comp[u]];

        p[u] = p[v] - 1;
        if (p[u] < 0) p[u] += C;
    }

    int numComp = (int)compC.size();

    // Group vertices by component without vector<vector>.
    vector<int> cnt(numComp, 0);
    for (int i = 0; i < N; i++) {
        cnt[comp[i]]++;
    }

    vector<int> start(numComp, 0);
    int sum = 0;
    for (int c = 0; c < numComp; c++) {
        start[c] = sum;
        sum += cnt[c];
    }

    vector<int> ptr = start;
    vector<int> order(N);
    for (int i = 0; i < N; i++) {
        int c = comp[i];
        order[ptr[c]++] = i;
    }

    vector<int> ans(N, -2);

    vector<char> present(N, 0);
    vector<int> nextMiss(N, 0);

    for (int cid = 0; cid < numComp; cid++) {
        int C = compC[cid];
        int L = start[cid];
        int R = L + cnt[cid];

        fill(present.begin(), present.begin() + C, 0);

        int presentCount = 0;

        for (int idx = L; idx < R; idx++) {
            int v = order[idx];
            if (isFarmer[v]) {
                int r = p[v] % C;
                if (!present[r]) {
                    present[r] = 1;
                    presentCount++;
                }
            }
        }

        if (presentCount == 0) {
            for (int idx = L; idx < R; idx++) {
                ans[order[idx]] = -2;
            }
            continue;
        }

        if (presentCount == C) {
            for (int idx = L; idx < R; idx++) {
                int v = order[idx];
                if (dist[v] == INF) ans[v] = -2;
                else ans[v] = -1;
            }
            continue;
        }

        int missing = -1;
        for (int i = 0; i < C; i++) {
            if (!present[i]) {
                missing = i;
                break;
            }
        }

        int nextMissingPos = missing;

        for (int step = 1; step < C; step++) {
            int pos = missing - step;
            pos %= C;
            if (pos < 0) pos += C;

            if (present[pos]) {
                int d = nextMissingPos - pos;
                if (d <= 0) d += C;
                nextMiss[pos] = d;
            } else {
                nextMissingPos = pos;
            }
        }

        for (int idx = L; idx < R; idx++) {
            int v = order[idx];

            if (dist[v] == INF) {
                ans[v] = -2;
                continue;
            }

            if (dist[v] == 0) {
                ans[v] = -1;
                continue;
            }

            int D = dist[v];
            int pB = p[v];

            int maxVal = D - 1;
            int k = maxVal / C;
            int q0 = maxVal % C;

            auto maxSafeLE = [&](int q) -> int {
                if (q < 0) return -1;

                int val = pB - q;
                val %= C;
                if (val < 0) val += C;

                if (!present[val]) return q;

                int d = nextMiss[val];
                if (d <= q) return q - d;
                return -1;
            };

            int qSafe = maxSafeLE(q0);
            int bestR;

            if (qSafe != -1) {
                bestR = k * C + qSafe;
            } else {
                if (k == 0) {
                    ans[v] = -1;
                    continue;
                } else {
                    int qFull = maxSafeLE(C - 1);
                    bestR = (k - 1) * C + qFull;
                }
            }

            ans[v] = bestR;
        }
    }

    for (int i = 0; i < N; i++) {
        cout << ans[i] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<int> a(N);
    for (int i = 0; i < N; i++) {
        cin >> a[i];
        --a[i];
    }

    vector<int> farmers(F);
    for (int i = 0; i < F; i++) {
        cin >> farmers[i];
        --farmers[i];
    }

    // Remove all tree vertices using Kahn's algorithm.
    vector<int> indeg(N, 0);
    for (int i = 0; i < N; i++) indeg[a[i]]++;

    queue<int> q;
    for (int i = 0; i < N; i++) {
        if (indeg[i] == 0) q.push(i);
    }

    vector<int> removed;
    removed.reserve(N);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        removed.push_back(u);

        int v = a[u];
        if (--indeg[v] == 0) q.push(v);
    }

    vector<int> cid(N, -1), pos(N, -1), y0(N, -1);
    vector<int> cycle_len, offset;
    vector<char> forbidden;
    int cycle_count = 0;

    // Extract cycles.
    for (int i = 0; i < N; i++) {
        if (cid[i] == -1 && indeg[i] > 0) {
            int cur = i;
            vector<int> temp;

            while (cid[cur] == -1) {
                cid[cur] = cycle_count;
                pos[cur] = (int)temp.size();
                temp.push_back(cur);
                cur = a[cur];
            }

            int C = (int)temp.size();
            cycle_len.push_back(C);
            offset.push_back((int)forbidden.size());
            forbidden.resize(forbidden.size() + C, 0);

            for (int v : temp) {
                y0[v] = pos[v];
            }

            cycle_count++;
        }
    }

    // Process tree vertices from closest to cycle outward.
    for (int idx = (int)removed.size() - 1; idx >= 0; idx--) {
        int v = removed[idx];
        int u = a[v];

        cid[v] = cid[u];
        int C = cycle_len[cid[u]];

        int val = y0[u] - 1;
        if (val < 0) val += C;
        y0[v] = val;
    }

    // Multi-source BFS from all farmers following the directed edges.
    const int INF = 1e9;
    vector<int> dist(N, INF);
    queue<int> bfs;

    for (int s : farmers) {
        if (dist[s] == INF) {
            dist[s] = 0;
            bfs.push(s);
        }
    }

    while (!bfs.empty()) {
        int u = bfs.front();
        bfs.pop();

        int v = a[u];
        if (dist[v] == INF) {
            dist[v] = dist[u] + 1;
            bfs.push(v);
        }
    }

    // Mark all cycle phases that are occupied by some farmer.
    for (int s : farmers) {
        int c = cid[s];
        int C = cycle_len[c];
        int p = y0[s];

        forbidden[offset[c] + p] = 1;
    }

    // For every cycle phase, compute distance forward to the next safe phase.
    vector<int> nextSafe(forbidden.size(), INF);

    for (int c = 0; c < cycle_count; c++) {
        int C = cycle_len[c];
        int off = offset[c];

        bool hasSafe = false;
        for (int p = 0; p < C; p++) {
            if (!forbidden[off + p]) {
                hasSafe = true;
                break;
            }
        }

        if (!hasSafe) {
            for (int p = 0; p < C; p++) {
                nextSafe[off + p] = INF;
            }
        } else {
            int nextPos = -1;

            for (int i = 2 * C - 1; i >= 0; i--) {
                int p = i % C;

                if (!forbidden[off + p]) nextPos = i;

                if (i < C) {
                    nextSafe[off + i] = nextPos - i;
                }
            }
        }
    }

    for (int v = 0; v < N; v++) {
        int ans;

        if (dist[v] == 0) {
            ans = -1;
        } else if (dist[v] == INF) {
            ans = -2;
        } else {
            int c = cid[v];
            int C = cycle_len[c];
            int off = offset[c];
            int d = dist[v];

            // Check T = d - 1, d - 2, ... for the largest valid total rests.
            int q = y0[v] - ((d - 1) % C);
            q %= C;
            if (q < 0) q += C;

            int k = nextSafe[off + q];

            if (k == INF || k >= d) {
                ans = -1;
            } else {
                ans = d - 1 - k;
            }
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<int> a(N), indegree(N, 0);
    for (int v = 0; v < N; ++v) {
        cin >> a[v];
        --a[v];
        ++indegree[a[v]];
    }

    vector<int> farmers(F);
    for (int &s : farmers) {
        cin >> s;
        --s;
    }

    // Remove all non-cycle vertices. The removal order is leaves-to-cycle.
    vector<int> removed;
    removed.reserve(N);

    for (int v = 0; v < N; ++v) {
        if (indegree[v] == 0) removed.push_back(v);
    }

    for (size_t i = 0; i < removed.size(); ++i) {
        int v = removed[i];
        int u = a[v];
        if (--indegree[u] == 0) removed.push_back(u);
    }

    // Component information.
    vector<int> component(N, -1);
    vector<int> depth(N, 0);
    vector<int> entryPos(N, 0);

    // Cycles are stored consecutively in cycleNodes.
    vector<int> cycleNodes;
    cycleNodes.reserve(N);
    vector<int> cycleStart, cycleLength;

    for (int v = 0; v < N; ++v) {
        if (indegree[v] == 0 || component[v] != -1) continue;

        int cid = (int)cycleLength.size();
        int start = (int)cycleNodes.size();
        int u = v;
        int pos = 0;

        do {
            component[u] = cid;
            entryPos[u] = pos++;
            cycleNodes.push_back(u);
            u = a[u];
        } while (u != v);

        cycleStart.push_back(start);
        cycleLength.push_back(pos);
    }

    // Compute depth and cycle-entry position for tree vertices.
    for (int i = (int)removed.size() - 1; i >= 0; --i) {
        int v = removed[i];
        int u = a[v];
        component[v] = component[u];
        depth[v] = depth[u] + 1;
        entryPos[v] = entryPos[u];
    }

    const int INF = 1'000'000'000;

    // low[v] = minimum depth of a farmer starting in v's reverse-tree subtree.
    // This is used for tree vertices only.
    vector<int> low(N, INF);
    for (int s : farmers) low[s] = depth[s];

    for (int v : removed) {
        int u = a[v];
        if (depth[u] > 0) {
            low[u] = min(low[u], low[v]);
        }
    }

    int components = (int)cycleLength.size();
    int totalCycleNodes = (int)cycleNodes.size();

    // For each component, mark the virtual phases occupied by its farmers.
    vector<unsigned char> occupied(totalCycleNodes, 0);
    vector<int> distinctKeys(components, 0);

    // For cycle vertices:
    // best[p] = earliest time any farmer reaches cycle position p.
    // origin[p] = virtual phase key of a farmer attaining that time.
    vector<int> best(totalCycleNodes, INF);
    vector<int> origin(totalCycleNodes, -1);

    auto mod = [](int x, int m) {
        x %= m;
        if (x < 0) x += m;
        return x;
    };

    for (int s : farmers) {
        int cid = component[s];
        int L = cycleLength[cid];
        int base = cycleStart[cid];

        int key = mod(entryPos[s] - depth[s], L);
        int keyIndex = base + key;

        if (!occupied[keyIndex]) {
            occupied[keyIndex] = 1;
            ++distinctKeys[cid];
        }

        int entryIndex = base + entryPos[s];
        if (depth[s] < best[entryIndex]) {
            best[entryIndex] = depth[s];
            origin[entryIndex] = key;
        }
    }

    // Directed unit-weight relaxation around every cycle.
    // Two passes handle all paths, including those wrapping past position 0.
    for (int cid = 0; cid < components; ++cid) {
        int L = cycleLength[cid];
        int base = cycleStart[cid];

        for (int pass = 0; pass < 2; ++pass) {
            for (int i = 0; i < L; ++i) {
                int cur = base + i;
                int nxt = base + ((i + 1 == L) ? 0 : i + 1);

                if (best[cur] != INF && best[cur] + 1 < best[nxt]) {
                    best[nxt] = best[cur] + 1;
                    origin[nxt] = origin[cur];
                }
            }
        }
    }

    // gap[c] = number of consecutive occupied residues beginning at c+1.
    vector<int> gap(totalCycleNodes, -1);

    for (int cid = 0; cid < components; ++cid) {
        int L = cycleLength[cid];
        int base = cycleStart[cid];

        if (distinctKeys[cid] == 0 || distinctKeys[cid] == L) continue;

        int freePosition = 0;
        while (freePosition < L && occupied[base + freePosition]) {
            ++freePosition;
        }

        int nextFree = freePosition;
        int x = (freePosition + L - 1) % L;

        for (int step = 0; step < L - 1; ++step) {
            if (occupied[base + x]) {
                int value = nextFree - x - 1;
                if (value < 0) value += L;
                gap[base + x] = value;
            } else {
                nextFree = x;
            }

            x = (x == 0 ? L - 1 : x - 1);
        }
    }

    string output;
    output.reserve((size_t)N * 8);

    for (int v = 0; v < N; ++v) {
        int cid = component[v];
        int L = cycleLength[cid];
        int base = cycleStart[cid];

        int firstVisit;
        int anchorKey;

        if (depth[v] > 0) {
            // No farmer ever visits this tree vertex.
            if (low[v] == INF) {
                output += "-2\n";
                continue;
            }

            firstVisit = low[v] - depth[v];
            anchorKey = mod(entryPos[v] - low[v], L);
        } else {
            // Every farmer in the component eventually visits every cycle vertex.
            if (distinctKeys[cid] == 0) {
                output += "-2\n";
                continue;
            }

            int index = base + entryPos[v];
            firstVisit = best[index];
            anchorKey = origin[index];
        }

        if (firstVisit == 0 || distinctKeys[cid] == L) {
            output += "-1\n";
            continue;
        }

        int g = gap[base + anchorKey];
        int answer = firstVisit - 1 - g;

        if (answer < 0) answer = -1;
        output += to_string(answer);
        output += '\n';
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Component {
    int length = 0;
    int offset = 0;
    bool hasFarmer = false;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<int> a(N);
    for (int &x : a) {
        cin >> x;
        --x;
    }

    vector<int> farmers(F);
    vector<char> isFarmer(N, false);
    for (int &s : farmers) {
        cin >> s;
        --s;
        isFarmer[s] = true;
    }

    // Remove all non-cycle vertices.
    vector<int> indegree(N, 0);
    for (int v = 0; v < N; ++v) {
        ++indegree[a[v]];
    }

    vector<int> order;
    order.reserve(N);
    for (int v = 0; v < N; ++v) {
        if (indegree[v] == 0) {
            order.push_back(v);
        }
    }

    for (int i = 0; i < (int)order.size(); ++i) {
        int v = order[i];
        if (--indegree[a[v]] == 0) {
            order.push_back(a[v]);
        }
    }

    vector<int> component(N, -1);
    vector<int> depth(N, 0);
    vector<int> entry(N, -1);
    vector<int> key(N, 0);
    vector<Component> components;

    // Label each directed cycle in the direction of its edges.
    for (int v = 0; v < N; ++v) {
        if (indegree[v] == 0 || component[v] != -1) {
            continue;
        }

        int cid = (int)components.size();
        int u = v;
        int length = 0;

        do {
            component[u] = cid;
            entry[u] = length;
            key[u] = length;
            ++length;
            u = a[u];
        } while (u != v);

        Component c;
        c.length = length;
        components.push_back(c);
    }

    // Propagate cycle information into the in-trees.
    for (int i = (int)order.size() - 1; i >= 0; --i) {
        int v = order[i];
        int p = a[v];

        component[v] = component[p];
        depth[v] = depth[p] + 1;
        entry[v] = entry[p];

        int L = components[component[v]].length;
        key[v] = (entry[v] - depth[v] % L + L) % L;
    }

    int totalCycleVertices = 0;
    for (auto &c : components) {
        c.offset = totalCycleVertices;
        totalCycleVertices += c.length;
    }

    const int INF = 1'000'000'000;

    vector<char> occupied(totalCycleVertices, false);
    vector<int> nextFree(totalCycleVertices, -1);
    vector<int> dist(totalCycleVertices, INF);

    // A farmer entering the cycle at entry[s] at time depth[s] is a source
    // with initial cost depth[s] at position entry[s].
    for (int s : farmers) {
        int cid = component[s];
        Component &c = components[cid];
        c.hasFarmer = true;

        occupied[c.offset + key[s]] = true;

        int pos = c.offset + entry[s];
        dist[pos] = min(dist[pos], depth[s]);
    }

    // Multi-source shortest distances on each directed cycle.
    // Every edge advances by one and has cost 1.
    for (const auto &c : components) {
        if (!c.hasFarmer) continue;

        int L = c.length;
        int off = c.offset;

        for (int pass = 0; pass < 2; ++pass) {
            for (int i = 0; i < L; ++i) {
                int j = (i + 1 == L ? 0 : i + 1);
                if (dist[off + i] < INF) {
                    dist[off + j] = min(dist[off + j], dist[off + i] + 1);
                }
            }
        }
    }

    // nextFree[off + r] is the first free phase at or after r, cyclically.
    for (const auto &c : components) {
        int L = c.length;
        int off = c.offset;

        int firstFree = -1;
        for (int i = 0; i < L; ++i) {
            if (!occupied[off + i]) {
                firstFree = i;
                break;
            }
        }

        if (firstFree == -1) continue;

        int nxt = firstFree;
        for (int i = L - 1; i >= 0; --i) {
            if (!occupied[off + i]) {
                nxt = i;
            }
            nextFree[off + i] = nxt;
        }
    }

    // For a tree vertex v, minFarmerDepth[v] is the minimum depth of a
    // farmer in the reverse subtree of v.
    vector<int> minFarmerDepth(N, INF);
    for (int s : farmers) {
        minFarmerDepth[s] = depth[s];
    }

    for (int v : order) {
        minFarmerDepth[a[v]] = min(minFarmerDepth[a[v]], minFarmerDepth[v]);
    }

    // Find the largest R < H whose resulting cycle phase is unoccupied.
    auto boundedAnswer = [&](int v, int H) -> int {
        if (H <= 0 || H >= INF) return -1;

        int cid = component[v];
        int L = components[cid].length;
        int off = components[cid].offset;

        int x = H - 1;
        int phase = (key[v] - x % L + L) % L;

        int nxt = nextFree[off + phase];
        if (nxt == -1) return -1;

        int delta = (nxt - off) - phase;
        if (delta < 0) delta += L;

        int answer = x - delta;
        return answer >= 0 ? answer : -1;
    };

    for (int v = 0; v < N; ++v) {
        if (depth[v] > 0) {
            // A tree farm is visited by a farmer exactly when that farmer
            // lies in its reverse subtree.
            if (minFarmerDepth[v] == INF) {
                cout << -2 << '\n';
                continue;
            }

            int H = minFarmerDepth[v] - depth[v];
            cout << boundedAnswer(v, H) << '\n';
        } else {
            int cid = component[v];

            if (!components[cid].hasFarmer) {
                cout << -2 << '\n';
                continue;
            }

            int H = dist[components[cid].offset + key[v]];
            cout << boundedAnswer(v, H) << '\n';
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static inline int mod(int x, int m) {
    x %= m;
    if (x < 0) x += m;
    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<int> to(N);
    vector<int> indegree(N, 0);

    for (int v = 0; v < N; ++v) {
        cin >> to[v];
        --to[v];
        ++indegree[to[v]];
    }

    vector<int> farmers(F);
    for (int &s : farmers) {
        cin >> s;
        --s;
    }

    /*
       nearest[v] = minimum number of steps needed for any farmer
                    to reach v, starting from time 0.
       This is a multi-source BFS following the original outgoing edges.
    */
    vector<int> nearest(N, -1);
    vector<int> bfs;
    bfs.reserve(N);

    for (int s : farmers) {
        nearest[s] = 0;
        bfs.push_back(s);
    }

    for (size_t head = 0; head < bfs.size(); ++head) {
        int v = bfs[head];
        int u = to[v];

        if (nearest[u] == -1) {
            nearest[u] = nearest[v] + 1;
            bfs.push_back(u);
        }
    }

    /*
       Remove all non-cycle vertices.
       peel is ordered from leaves toward cycles, so processing it backwards
       processes each parent before its children.
    */
    vector<int> peel;
    peel.reserve(N);

    for (int v = 0; v < N; ++v) {
        if (indegree[v] == 0) {
            peel.push_back(v);
        }
    }

    for (size_t head = 0; head < peel.size(); ++head) {
        int v = peel[head];
        int u = to[v];

        if (--indegree[u] == 0) {
            peel.push_back(u);
        }
    }

    /*
       label[v] is defined modulo the cycle length of v's component:
           label[to[v]] = label[v] + 1 (mod cycle length).

       On cycle vertices, the labels are all distinct.
    */
    vector<int> component(N, -1);
    vector<int> label(N, 0);
    vector<int> cycleLength;
    vector<int> componentBase;

    int totalCycleLength = 0;

    for (int start = 0; start < N; ++start) {
        if (indegree[start] == 0 || component[start] != -1) {
            continue;
        }

        int cid = static_cast<int>(cycleLength.size());
        int v = start;
        int len = 0;

        do {
            component[v] = cid;
            label[v] = len++;
            v = to[v];
        } while (v != start);

        cycleLength.push_back(len);
        componentBase.push_back(totalCycleLength);
        totalCycleLength += len;
    }

    for (int i = static_cast<int>(peel.size()) - 1; i >= 0; --i) {
        int v = peel[i];
        int parent = to[v];
        int cid = component[parent];

        component[v] = cid;
        label[v] = mod(label[parent] - 1, cycleLength[cid]);
    }

    /*
       For each component, record which cycle labels belong to farmers.
       Labels are stored in one flat array to avoid many small allocations.
    */
    vector<unsigned char> occupied(totalCycleLength, 0);

    for (int s : farmers) {
        int cid = component[s];
        occupied[componentBase[cid] + label[s]] = 1;
    }

    /*
       runLength[p] is the number of consecutive occupied labels starting
       at p and proceeding cyclically upward. If every label is occupied,
       runLength[p] equals the cycle length for every p.
    */
    vector<int> runLength(totalCycleLength, 0);

    for (int cid = 0; cid < static_cast<int>(cycleLength.size()); ++cid) {
        int c = cycleLength[cid];
        int base = componentBase[cid];

        int gap = -1;
        for (int p = 0; p < c; ++p) {
            if (!occupied[base + p]) {
                gap = p;
                break;
            }
        }

        if (gap == -1) {
            for (int p = 0; p < c; ++p) {
                runLength[base + p] = c;
            }
        } else {
            int streak = 0;

            // Scan backward from a missing label. A missing label resets
            // the streak; an occupied label extends it by one.
            for (int step = 1; step < c; ++step) {
                int p = gap - step;
                if (p < 0) p += c;

                int idx = base + p;
                if (occupied[idx]) {
                    ++streak;
                    runLength[idx] = streak;
                } else {
                    streak = 0;
                    runLength[idx] = 0;
                }
            }
        }
    }

    string output;
    output.reserve(static_cast<size_t>(N) * 8);

    for (int b = 0; b < N; ++b) {
        int answer;

        if (nearest[b] == -1) {
            // No farmer ever reaches this farm, so Bessie can rest forever.
            answer = -2;
        } else {
            int limit = nearest[b] - 1;

            if (limit < 0) {
                // A farmer is initially at b.
                answer = -1;
            } else {
                int cid = component[b];
                int c = cycleLength[cid];
                int base = componentBase[cid];

                int x = limit % c;

                /*
                   A total of K rests is cycle-safe exactly when
                       label[b] - K (mod c)
                   is not a farmer's label.

                   First test K = limit, whose residue is x.
                */
                int farmerLabel = mod(label[b] - x, c);

                if (!occupied[base + farmerLabel]) {
                    answer = limit;
                } else {
                    int run = runLength[base + farmerLabel];

                    if (run == c) {
                        // Every residue is forbidden.
                        answer = -1;
                    } else {
                        /*
                           As K decreases from x, the required farmer label
                           increases from farmerLabel. The first safe residue
                           below x is therefore x - run.
                        */
                        int safeResidue = mod(x - run, c);

                        // Largest K <= limit with this safe residue.
                        int delta = mod(limit - safeResidue, c);
                        answer = limit - delta;

                        if (answer < 0) {
                            answer = -1;
                        }
                    }
                }
            }
        }

        output += to_string(answer);
        output.push_back('\n');
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<int> p(N);
        for (int &x : p) cin >> x;

        // Initial inversion count.
        vector<int> bit(N + 1, 0);
        auto add = [&](int i, int v) {
            for (; i <= N; i += i & -i) bit[i] += v;
        };
        auto sum = [&](int i) {
            int r = 0;
            for (; i > 0; i -= i & -i) r += bit[i];
            return r;
        };

        long long inv = 0;
        for (int i = 0; i < N; ++i) {
            inv += i - sum(p[i]);
            add(p[i], 1);
        }

        long long f = 0;
        for (int i = 0; i < N; ++i) {
            f += abs((long long)p[i] - (i + 1));
        }
        f /= 2;

        /*
         * For the current permutation q, let d_i = q_i - i and
         * L = #{i : d_i <= 0}.
         *
         * After a right cyclic shift whose last element is x:
         *   inv' = inv + 2*x - N - 1
         *   f'   = f + L + x - N - 1
         *
         * Keys represent d_i with a global offset: at shift s,
         * d_i = key_i - s. Each ordinary position change subtracts 1
         * from d_i; the wrapped element additionally has its key
         * increased by N.
         */
        const int offset = N + 1;
        vector<int> key(N), freq(3 * N + 5, 0);
        int L = 0;

        for (int i = 0; i < N; ++i) {
            key[i] = p[i] - (i + 1);
            ++freq[key[i] + offset];
            L += (key[i] <= 0);
        }

        vector<int> answer;
        answer.reserve(N);

        for (int s = 0; s < N; ++s) {
            if (inv <= f) answer.push_back(s);
            if (s + 1 == N) break;

            int idx = N - 1 - s;
            int x = p[idx];

            f += L + x - N - 1;
            inv += 2LL * x - N - 1;

            int threshold = s + 1;
            L += freq[threshold + offset];

            // Remove the virtual value of the wrapped element and insert
            // its actual new value.
            --L;
            if (x == 1) ++L;

            int oldKey = key[idx];
            --freq[oldKey + offset];
            key[idx] += N;
            ++freq[key[idx] + offset];
        }

        cout << answer.size() << '\n';
        for (int i = 0; i < (int)answer.size(); ++i) {
            if (i) cout << ' ';
            cout << answer[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Fenwick {
    int n;
    vector<int> bit;

    explicit Fenwick(int n_) : n(n_), bit(n_ + 1, 0) {}

    void add(int index, int value) {
        for (; index <= n; index += index & -index) {
            bit[index] += value;
        }
    }

    int sum(int index) const {
        int result = 0;
        for (; index > 0; index -= index & -index) {
            result += bit[index];
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<int> p(N);
        vector<int> originalPosition(N + 1);

        for (int i = 0; i < N; ++i) {
            cin >> p[i];
            originalPosition[p[i]] = i + 1;
        }

        Fenwick fenwick(N);
        int64 inversions = 0;

        for (int i = N - 1; i >= 0; --i) {
            inversions += fenwick.sum(p[i] - 1);
            fenwick.add(p[i], 1);
        }

        int64 totalDistance = 0;
        int positiveCount = 0;

        for (int i = 0; i < N; ++i) {
            totalDistance += abs(p[i] - (i + 1));
            positiveCount += (p[i] > i + 1);
        }

        int64 f = totalDistance / 2;

        // diagonal[s] is the number of positions i with q_i = i + 1
        // in the cyclic shift s.
        vector<int> diagonal(N, 0);

        for (int value = 2; value <= N; ++value) {
            int s = value - originalPosition[value] - 1;
            if (s < 0) {
                s += N;
            }
            ++diagonal[s];
        }

        vector<int> answer;
        answer.reserve(N);

        for (int s = 0; s < N; ++s) {
            if (inversions <= f) {
                answer.push_back(s);
            }

            if (s + 1 == N) {
                break;
            }

            int x = p[N - 1 - s];

            inversions += 2LL * x - N - 1;
            f += x - positiveCount - 1;
            positiveCount += (x > 1 ? 1 : 0) - diagonal[s];
        }

        cout << answer.size() << '\n';
        for (size_t i = 0; i < answer.size(); ++i) {
            if (i > 0) {
                cout << ' ';
            }
            cout << answer[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Fenwick {
    int n;
    vector<int> bit;

    explicit Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int i, int value) {
        for (; i <= n; i += i & -i) bit[i] += value;
    }

    int sum(int i) const {
        int result = 0;
        for (; i > 0; i -= i & -i) result += bit[i];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<int> p(N);
        for (int &x : p) cin >> x;

        Fenwick fw(N);
        int64 inversions = 0;
        int64 displacement = 0;

        for (int i = 0; i < N; ++i) {
            inversions += i - fw.sum(p[i]);
            fw.add(p[i], 1);
            displacement += abs(p[i] - (i + 1));
        }
        displacement /= 2;

        // positive[s] = number of indices i with q_i > i,
        // where q is the right cyclic shift by s.
        vector<int> diff(N + 1, 0);

        for (int j = 0; j < N; ++j) {
            int length = p[j] - 1;
            if (length == 0) continue;

            int start = (N - j) % N;
            if (start + length <= N) {
                ++diff[start];
                --diff[start + length];
            } else {
                ++diff[start];
                --diff[N];
                ++diff[0];
                --diff[start + length - N];
            }
        }

        vector<int> positive(N);
        int current = 0;
        for (int s = 0; s < N; ++s) {
            current += diff[s];
            positive[s] = current;
        }

        vector<int> answer;
        for (int s = 0; s < N; ++s) {
            if (inversions <= displacement) answer.push_back(s);
            if (s + 1 == N) break;

            int x = p[N - 1 - s];
            inversions += 2LL * x - N - 1;
            displacement += x - 1 - positive[s];
        }

        cout << answer.size() << '\n';
        for (int i = 0; i < (int)answer.size(); ++i) {
            if (i) cout << ' ';
            cout << answer[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<int> p(N);
        for (int i = 0; i < N; ++i) {
            cin >> p[i];
            --p[i];
        }

        // Compute inversion count of the original permutation.
        long long inv = 0;
        vector<int> bit(N + 2, 0);

        for (int i = 0; i < N; ++i) {
            int v = p[i];

            int sum = 0;
            for (int k = v + 1; k > 0; k -= k & -k) {
                sum += bit[k];
            }

            inv += (long long)i - sum;

            for (int k = v + 1; k <= N; k += k & -k) {
                ++bit[k];
            }
        }

        // We need F(s) = sum |p_j - ((j + s) mod N)| for all shifts s.
        // Add all V-shaped functions using range additions of linear functions.
        vector<long long> diffA(N + 2, 0), diffB(N + 2, 0);

        auto rangeAdd = [&](int l, int r, long long a, long long b) {
            if (l > r) return;
            diffA[l] += a;
            diffA[r + 1] -= a;
            diffB[l] += b;
            diffB[r + 1] -= b;
        };

        auto addAbs = [&](int L, int R, int c) {
            if (L > R) return;

            // Add c - s on [L, min(R, c)]
            int r1 = min(R, c);
            if (L <= r1) {
                rangeAdd(L, r1, -1, c);
            }

            // Add s - c on [max(L, c + 1), R]
            int l2 = max(L, c + 1);
            if (l2 <= R) {
                rangeAdd(l2, R, 1, -c);
            }
        };

        for (int j = 0; j < N; ++j) {
            int v = p[j];

            // Before wrapping: s in [0, N - 1 - j]
            addAbs(0, N - 1 - j, v - j);

            // After wrapping: s in [N - j, N - 1]
            addAbs(N - j, N - 1, v - j + N);
        }

        vector<int> answer;

        long long coefA = 0, coefB = 0;

        for (int s = 0; s < N; ++s) {
            coefA += diffA[s];
            coefB += diffB[s];

            long long F = coefA * s + coefB;

            if (s > 0) {
                int x = p[N - s];
                inv += 2LL * x - (N - 1);
            }

            if (2LL * inv <= F) {
                answer.push_back(s);
            }
        }

        cout << answer.size() << '\n';
        for (size_t i = 0; i < answer.size(); ++i) {
            if (i) cout << ' ';
            cout << answer[i];
        }
        cout << '\n';
    }

    return 0;
}

