using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<int> p(N);
        for (int i = 0; i < N; ++i) cin >> p[i];

        // Initial inversion count of p.
        vector<int> bit(N + 1, 0);
        auto bit_add = [&](int idx) {
            while (idx <= N) {
                bit[idx]++;
                idx += idx & -idx;
            }
        };
        auto bit_sum = [&](int idx) {
            int res = 0;
            while (idx > 0) {
                res += bit[idx];
                idx -= idx & -idx;
            }
            return res;
        };

        long long inv = 0;
        for (int i = 0; i < N; ++i) {
            inv += i - bit_sum(p[i]);
            bit_add(p[i]);
        }

        long long S = 0;
        int C = 0;

        for (int i = 0; i < N; ++i) {
            int pos = i + 1;
            S += llabs((long long)p[i] - pos);
            if (pos >= p[i]) ++C;
        }

        // G[s] = number of i with 1 <= i < N such that q_s[i] = i + 1.
        vector<int> G(N, 0);
        for (int j = 0; j < N; ++j) {
            int a = p[j];
            if (a >= 2) {
                int s = (a - 2 - j) % N;
                if (s < 0) s += N;
                G[s]++;
            }
        }

        vector<int> ans;
        ans.reserve(N);

        for (int s = 0; s < N; ++s) {
            if (2LL * inv <= S) ans.push_back(s);

            if (s + 1 < N) {
                int idx = N - 1 - s;
                int x = p[idx];

                long long newS = S + (2LL * C - N) + (2LL * x - N - 2);
                long long newInv = inv + 2LL * x - N - 1;

                C = C + G[s] - (x > 1 ? 1 : 0);
                S = newS;
                inv = newInv;
            }
        }

        cout << ans.size() << '\n';
        for (size_t i = 0; i < ans.size(); ++i) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<int> p(N);
        vector<int> bit(N + 1, 0);

        auto bitAdd = [&](int idx) {
            for (int i = idx; i <= N; i += i & -i) ++bit[i];
        };

        auto bitSum = [&](int idx) {
            int res = 0;
            for (int i = idx; i > 0; i -= i & -i) res += bit[i];
            return res;
        };

        long long inv0 = 0;

        for (int i = 0; i < N; ++i) {
            cin >> p[i];
            int x = p[i];
            int le = bitSum(x);
            inv0 += (long long)i - le;
            bitAdd(x);
        }

        vector<long long> diffM(N + 2, 0), diffB(N + 2, 0);

        auto addLinear = [&](int l, int r, long long m, long long b) {
            if (l > r) return;
            diffM[l] += m;
            diffM[r + 1] -= m;
            diffB[l] += b;
            diffB[r + 1] -= b;
        };

        auto addAbs = [&](int l, int r, long long c) {
            if (l > r) return;

            if (c < l) {
                addLinear(l, r, 1, -c);
            } else if (c > r) {
                addLinear(l, r, -1, c);
            } else {
                int cc = (int)c;
                addLinear(l, cc - 1, -1, c);
                addLinear(cc, r, 1, -c);
            }
        };

        for (int j = 0; j < N; ++j) {
            long long a = (long long)p[j] - (j + 1);

            // s such that j + s < N
            addAbs(0, N - j - 1, a);

            // s such that j + s >= N
            int L = N - j;
            if (L <= N - 1) {
                addAbs(L, N - 1, a + N);
            }
        }

        vector<int> ans;
        ans.reserve(N);

        long long curM = 0, curB = 0;
        long long invCur = inv0;

        for (int s = 0; s < N; ++s) {
            curM += diffM[s];
            curB += diffB[s];

            long long sumAbs = curM * (long long)s + curB;

            if (2 * invCur == sumAbs) {
                ans.push_back(s);
            }

            if (s + 1 < N) {
                int x = p[N - 1 - s];
                invCur += 2LL * x - N - 1;
            }
        }

        cout << ans.size() << '\n';
        for (size_t i = 0; i < ans.size(); ++i) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<int> bit;

    explicit Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int index) {
        for (; index <= n; index += index & -index) {
            ++bit[index];
        }
    }

    int prefixSum(int index) const {
        int result = 0;
        for (; index > 0; index -= index & -index) {
            result += bit[index];
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n;
        cin >> n;

        vector<int> p(n);
        for (int &x : p) {
            cin >> x;
        }

        // Initial inversion count.
        Fenwick fenwick(n);
        long long inversions = 0;

        for (int i = 0; i < n; ++i) {
            inversions += static_cast<long long>(i)
                        - fenwick.prefixSum(p[i]);
            fenwick.add(p[i]);
        }

        // displacement = sum |p_i - i| = 2 * f(p).
        long long displacement = 0;
        for (int i = 0; i < n; ++i) {
            displacement += llabs(static_cast<long long>(p[i]) - (i + 1));
        }

        /*
          countGE is the number of elements whose current position is
          at least their value.

          deltaCount[s] is the change in countGE when the permutation
          is shifted right by s positions.
        */
        vector<int> deltaCount(n + 1, 0);
        int countGE = 0;

        for (int j = 1; j <= n; ++j) {
            int v = p[j - 1];

            if (j >= v) {
                ++countGE;
            }

            if (j < v) {
                // Reaches position v before wrapping.
                ++deltaCount[v - j];

                // Wraps from n to 1 and no longer satisfies pos >= v.
                --deltaCount[n - j + 1];
            } else if (j == v) {
                if (v > 1) {
                    --deltaCount[n - j + 1];
                }
            } else { // j > v
                if (v > 1) {
                    // Loses the condition while wrapping ...
                    --deltaCount[n - j + 1];

                    // ... and regains it when its position becomes v.
                    ++deltaCount[n + v - j];
                }
            }
        }

        vector<int> answer;

        if (2 * inversions <= displacement) {
            answer.push_back(0);
        }

        for (int s = 1; s < n; ++s) {
            // The element moved from the end to the front.
            int x = p[n - s];

            // Use countGE for the permutation before this shift.
            displacement += 2LL * (countGE + x - n - 1);
            inversions += 2LL * x - n - 1;

            countGE += deltaCount[s];

            if (2 * inversions <= displacement) {
                answer.push_back(s);
            }
        }

        cout << answer.size() << '\n';
        for (int i = 0; i < static_cast<int>(answer.size()); ++i) {
            if (i > 0) {
                cout << ' ';
            }
            cout << answer[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<int> bit;

    explicit Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int index) {
        for (; index <= n; index += index & -index) {
            ++bit[index];
        }
    }

    int sum(int index) const {
        int result = 0;
        for (; index > 0; index -= index & -index) {
            result += bit[index];
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<int> p(N + 1);
        for (int i = 1; i <= N; ++i) {
            cin >> p[i];
        }

        /*
        b[s] = number of positions i < N such that
               q_s[i] = i + 1, where q_s is p shifted right by s.

        The element p[j] is at position p[j] - 1 in exactly the shift
        s = (p[j] - 1 - j) mod N.
        */
        vector<int> b(N, 0);
        for (int j = 1; j <= N; ++j) {
            if (p[j] > 1) {
                int s = (p[j] - 1 - j) % N;
                if (s < 0) s += N;
                ++b[s];
            }
        }

        Fenwick fw(N);
        long long inversions = 0;
        long long displacement = 0;
        int C = 0;  // Number of positions i with p[i] <= i.

        for (int i = 1; i <= N; ++i) {
            inversions += (i - 1LL) - fw.sum(p[i]);
            fw.add(p[i]);

            displacement += llabs(1LL * p[i] - i);
            if (p[i] <= i) ++C;
        }

        vector<int> answer;
        answer.reserve(N);

        for (int s = 0; s < N; ++s) {
            if (2LL * inversions == displacement) {
                answer.push_back(s);
            }

            if (s == N - 1) break;

            // The last element of the current rotation is p[N - s].
            int x = p[N - s];

            // Update the inversion count after moving x to the front.
            inversions += 2LL * x - N - 1;

            // Update the total displacement.
            displacement += llabs(1LL * x - 1)
                         - llabs(1LL * x - N)
                         + 2LL * C - N - 1;

            // Update C for the next rotation.
            C += -1 + (x == 1 ? 1 : 0) + b[s];
        }

        cout << answer.size() << '\n';
        for (int i = 0; i < (int)answer.size(); ++i) {
            if (i) cout << ' ';
            cout << answer[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<int> tree;

    explicit Fenwick(int n) : n(n), tree(n + 1, 0) {}

    void add(int index) {
        for (; index <= n; index += index & -index) {
            ++tree[index];
        }
    }

    int prefixSum(int index) const {
        int result = 0;
        for (; index > 0; index -= index & -index) {
            result += tree[index];
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n;
        cin >> n;

        vector<int> p(n + 1), pos(n + 1);
        Fenwick bit(n);
        long long inversions = 0;

        for (int i = 1; i <= n; ++i) {
            cin >> p[i];
            pos[p[i]] = i;

            // Count previous elements greater than p[i].
            inversions += (i - 1) - bit.prefixSum(p[i]);
            bit.add(p[i]);
        }

        // Difference arrays for adding a function slope * s + intercept
        // to an interval of shifts.
        vector<long long> diffSlope(n + 1, 0);
        vector<long long> diffIntercept(n + 1, 0);

        auto addRange = [&](int left, int right,
                            long long slope, long long intercept) {
            if (left > right) return;

            diffSlope[left] += slope;
            diffSlope[right + 1] -= slope;

            diffIntercept[left] += intercept;
            diffIntercept[right + 1] -= intercept;
        };

        for (int value = 1; value <= n; ++value) {
            int a = pos[value];

            // No wrap: the new position is a + s.
            // Its positive displacement is value - a - s.
            int right = min(n - a, value - a - 1);
            addRange(0, right, -1, 1LL * value - a);

            // Wrap: the new position is a + s - n.
            // Its positive displacement is n + value - a - s.
            int left = n - a + 1;
            right = min(n - 1, n + value - a - 1);
            addRange(left, right, -1, 1LL * n + value - a);
        }

        vector<long long> f(n);
        long long slope = 0, intercept = 0;

        for (int s = 0; s < n; ++s) {
            slope += diffSlope[s];
            intercept += diffIntercept[s];
            f[s] = slope * s + intercept;
        }

        vector<int> answer;
        answer.reserve(n);

        for (int s = 0; s < n; ++s) {
            if (inversions <= f[s]) {
                answer.push_back(s);
            }

            if (s + 1 < n) {
                // Shifting right moves the last element x to the front.
                // In q_s, the last element is p[n - s].
                int x = p[n - s];
                inversions += 2LL * x - n - 1;
            }
        }

        cout << answer.size() << '\n';
        for (int i = 0; i < static_cast<int>(answer.size()); ++i) {
            if (i) cout << ' ';
            cout << answer[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N, M, K, L;
        cin >> N >> M >> K >> L;

        vector<int> flowers(K);
        for (int &x : flowers) cin >> x;

        vector<char> isDestination(N + 1, false);
        for (int i = 0; i < L; ++i) {
            int x;
            cin >> x;
            isDestination[x] = true;
        }

        vector<vector<int>> adj(N + 1);
        vector<pair<int, int>> edges(M);
        for (int i = 0; i < M; ++i) {
            int u, v;
            cin >> u >> v;
            edges[i] = {u, v};
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        vector<int> dist(N + 1, -1);
        queue<int> q;
        dist[1] = 0;
        q.push(1);

        int maxDist = 0;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            maxDist = max(maxDist, dist[u]);

            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }

        vector<vector<int>> layers(maxDist + 1);
        for (int v = 1; v <= N; ++v) {
            layers[dist[v]].push_back(v);
        }

        // Directed acyclic graph containing exactly the edges that can be
        // used by shortest paths starting at farm 1.
        vector<vector<int>> dag(N + 1);
        for (auto [u, v] : edges) {
            if (dist[u] + 1 == dist[v]) {
                dag[u].push_back(v);
            } else if (dist[v] + 1 == dist[u]) {
                dag[v].push_back(u);
            }
        }

        sort(flowers.begin(), flowers.end(), [&](int a, int b) {
            return dist[a] < dist[b];
        });

        bool possible = true;
        for (int i = 1; i < K; ++i) {
            if (dist[flowers[i]] == dist[flowers[i - 1]]) {
                possible = false;
                break;
            }
        }

        vector<char> answer(N + 1, false);

        if (possible) {
            vector<int> chain;
            chain.reserve(K + 1);
            chain.push_back(1);
            for (int x : flowers) chain.push_back(x);

            vector<char> forward(N + 1, false);
            vector<char> backward(N + 1, false);

            // Process the portions between consecutive required flowers.
            // Their distance-layer intervals are disjoint, so altogether
            // these loops take O(N + M).
            for (int i = 0; i + 1 < (int)chain.size() && possible; ++i) {
                int a = chain[i];
                int b = chain[i + 1];
                int da = dist[a];
                int db = dist[b];

                forward[a] = true;
                for (int d = da; d < db; ++d) {
                    for (int u : layers[d]) {
                        if (!forward[u]) continue;
                        for (int v : dag[u]) {
                            forward[v] = true;
                        }
                    }
                }

                if (!forward[b]) {
                    possible = false;
                    break;
                }

                for (int d = db; d >= da; --d) {
                    for (int u : layers[d]) {
                        bool canReach = (u == b);

                        if (d < db) {
                            for (int v : dag[u]) {
                                if (backward[v]) {
                                    canReach = true;
                                    break;
                                }
                            }
                        }

                        backward[u] = canReach;
                        if (canReach && forward[u]) {
                            answer[u] = true;
                        }
                    }
                }

                for (int d = da; d <= db; ++d) {
                    for (int u : layers[d]) {
                        forward[u] = false;
                        backward[u] = false;
                    }
                }
            }

            if (possible) {
                // Final portion: from the last required flower (or farm 1)
                // to any reachable destination.
                int a = chain.back();
                int da = dist[a];

                forward[a] = true;
                for (int d = da; d < maxDist; ++d) {
                    for (int u : layers[d]) {
                        if (!forward[u]) continue;
                        for (int v : dag[u]) {
                            forward[v] = true;
                        }
                    }
                }

                for (int d = maxDist; d >= da; --d) {
                    for (int u : layers[d]) {
                        bool canReach = isDestination[u] && forward[u];

                        for (int v : dag[u]) {
                            if (backward[v]) {
                                canReach = true;
                                break;
                            }
                        }

                        backward[u] = canReach;
                        if (canReach && forward[u]) {
                            answer[u] = true;
                        }
                    }
                }

                possible = backward[a];
            }
        }

        string result(N - 1, '0');
        if (possible) {
            for (int v = 2; v <= N; ++v) {
                if (answer[v]) result[v - 2] = '1';
            }
        }

        cout << result << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
