struct TestCase {
    int n;
    vector<pair<int, int>> edges;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    vector<TestCase> tests(T);
    int maxN = 2;

    for (int tc = 0; tc < T; ++tc) {
        cin >> tests[tc].n;
        maxN = max(maxN, tests[tc].n);
        tests[tc].edges.resize(tests[tc].n - 1);
        for (auto &e : tests[tc].edges) {
            cin >> e.first >> e.second;
        }
    }

    vector<long long> inv(maxN + 1), fact(maxN + 1), invfact(maxN + 1);
    inv[1] = 1;
    for (int i = 2; i <= maxN; ++i) {
        inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
    }

    fact[0] = 1;
    for (int i = 1; i <= maxN; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    invfact[maxN] = modpow(fact[maxN], MOD - 2);
    for (int i = maxN; i >= 1; --i) {
        invfact[i - 1] = invfact[i] * i % MOD;
    }

    for (const auto &test : tests) {
        int n = test.n;
        vector<vector<int>> adj(n + 1);
        for (auto [u, v] : test.edges) {
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        vector<int> parent(n + 1, 0), sz(n + 1, 1), order;
        order.reserve(n);
        parent[1] = -1;
        order.push_back(1);

        for (int i = 0; i < n; ++i) {
            int v = order[i];
            for (int to : adj[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                order.push_back(to);
            }
        }

        // For a fixed root r, let P_r be the product of all non-root
        // subtree sizes. First compute the modular inverse of P_1.
        long long invP = 1;
        for (int i = n - 1; i >= 0; --i) {
            int v = order[i];
            if (v != 1) {
                invP = invP * inv[sz[v]] % MOD;
                sz[parent[v]] += sz[v];
            }
        }

        vector<long long> value(n + 1);
        value[1] = invP;
        long long sum = invP;

        // Moving the root across an edge with child subtree size s changes
        // inv(P) by a factor of s / (n - s).
        for (int v : order) {
            for (int to : adj[v]) {
                if (parent[to] != v) continue;
                value[to] = value[v] * sz[to] % MOD
                          * inv[n - sz[to]] % MOD;
                sum = (sum + value[to]) % MOD;
            }
        }

        cout << sum * invfact[n] % MOD << '\n';
    }

    return 0;
}

