long long mod_pow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const int MAXN = 500000 + 5;

    vector<long long> inv(MAXN), fact(MAXN), invfact(MAXN);

    inv[1] = 1;
    for (int i = 2; i < MAXN; i++) {
        inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
    }

    fact[0] = 1;
    for (int i = 1; i < MAXN; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }

    invfact[MAXN - 1] = mod_pow(fact[MAXN - 1], MOD - 2);
    for (int i = MAXN - 1; i >= 1; i--) {
        invfact[i - 1] = invfact[i] * i % MOD;
    }

    int T;
    cin >> T;

    while (T--) {
        int n;
        cin >> n;

        vector<vector<int>> adj(n + 1);
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            cin >> u >> v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        vector<int> parent(n + 1, 0);
        vector<int> order;
        order.reserve(n);

        vector<int> st;
        st.reserve(n);
        st.push_back(1);
        parent[1] = 0;

        while (!st.empty()) {
            int v = st.back();
            st.pop_back();
            order.push_back(v);

            for (int to : adj[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                st.push_back(to);
            }
        }

        vector<int> sub(n + 1, 1);

        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            if (parent[v] != 0) {
                sub[parent[v]] += sub[v];
            }
        }

        long long F1 = 1;
        for (int v = 2; v <= n; v++) {
            F1 = F1 * sub[v] % MOD;
        }

        long long invF1 = mod_pow(F1, MOD - 2);

        vector<long long> invF(n + 1);
        invF[1] = invF1;

        long long sum = invF1;

        for (int i = 1; i < n; i++) {
            int v = order[i];
            int p = parent[v];

            invF[v] = invF[p] * sub[v] % MOD * inv[n - sub[v]] % MOD;

            sum += invF[v];
            if (sum >= MOD) sum -= MOD;
        }

        long long ans = sum * invfact[n] % MOD;
        cout << ans << '\n';
    }

    return 0;
}

