using int64 = long long;
constexpr int64 MOD = 1'000'000'007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<vector<int>> adj(N);
        for (int i = 0; i < N - 1; ++i) {
            int u, v;
            cin >> u >> v;
            --u;
            --v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        // Root the tree at vertex 0 and construct a parent-before-child order.
        vector<int> parent(N, -1), order;
        order.reserve(N);
        parent[0] = 0;
        order.push_back(0);

        for (int i = 0; i < (int)order.size(); ++i) {
            int v = order[i];
            for (int to : adj[v]) {
                if (parent[to] != -1) continue;
                parent[to] = v;
                order.push_back(to);
            }
        }

        // Subtree sizes for the initial root.
        vector<int> sub(N, 1);
        for (int i = N - 1; i >= 1; --i) {
            int v = order[i];
            sub[parent[v]] += sub[v];
        }

        // Modular inverses of 1, 2, ..., N.
        vector<int64> inv(N + 1);
        inv[1] = 1;
        for (int i = 2; i <= N; ++i) {
            inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
        }

        // reciprocalF[v] = 1 / F_v, where
        // F_v = product of subtree sizes when the tree is rooted at v.
        vector<int64> reciprocalF(N);
        reciprocalF[0] = 1;
        for (int v = 0; v < N; ++v) {
            reciprocalF[0] =
                reciprocalF[0] * inv[sub[v]] % MOD;
        }

        int64 sum = reciprocalF[0];

        // Reroot from each parent u to its child v.
        for (int i = 1; i < N; ++i) {
            int v = order[i];
            int u = parent[v];
            int s = sub[v];

            reciprocalF[v] =
                reciprocalF[u] * s % MOD * inv[N - s] % MOD;

            sum += reciprocalF[v];
            if (sum >= MOD) sum -= MOD;
        }

        // Inverse of (N-1)!.
        int64 invFactorial = 1;
        for (int i = 1; i < N; ++i) {
            invFactorial = invFactorial * inv[i] % MOD;
        }

        cout << sum * invFactorial % MOD << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

constexpr int MOD = 1'000'000'007;
constexpr int MAXN = 200'000;

int64 modPow(int64 a, int64 e) {
    int64 result = 1;
    while (e > 0) {
        if (e & 1) result = result * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<int64> fact(MAXN + 1), invFact(MAXN + 1), invNum(MAXN + 1);

    fact[0] = 1;
    for (int i = 1; i <= MAXN; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }

    invFact[MAXN] = modPow(fact[MAXN], MOD - 2);
    for (int i = MAXN; i >= 1; --i) {
        invFact[i - 1] = invFact[i] * i % MOD;
    }

    for (int i = 1; i <= MAXN; ++i) {
        invNum[i] = fact[i - 1] * invFact[i] % MOD;
    }

    int T;
    cin >> T;

    while (T--) {
        int n;
        cin >> n;

        vector<vector<int>> adj(n);
        for (int i = 0; i < n - 1; ++i) {
            int u, v;
            cin >> u >> v;
            --u;
            --v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        // Root the tree at vertex 0 and construct a parent-before-child order.
        vector<int> parent(n, -1), order;
        order.reserve(n);
        order.push_back(0);

        for (int i = 0; i < (int)order.size(); ++i) {
            int u = order[i];
            for (int v : adj[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                order.push_back(v);
            }
        }

        // Subtree sizes for the initial root.
        vector<int> subtree(n, 1);
        for (int i = n - 1; i >= 1; --i) {
            int v = order[i];
            subtree[parent[v]] += subtree[v];
        }

        // ways[r] = number of orders in which every parent precedes its
        // children, when the tree is rooted at r.
        vector<int64> ways(n);

        ways[0] = fact[n];
        for (int v = 0; v < n; ++v) {
            ways[0] = ways[0] * invNum[subtree[v]] % MOD;
        }

        // Reroot from each parent u to its child v.
        for (int i = 1; i < n; ++i) {
            int v = order[i];
            int u = parent[v];
            ways[v] = ways[u] * subtree[v] % MOD
                    * invNum[n - subtree[v]] % MOD;
        }

        int64 total = 0;
        for (int r = 0; r < n; ++r) {
            total = (total + ways[r]) % MOD;
        }

        // Probability = total / (n! * (n-1)!).
        int64 answer = total * invFact[n] % MOD
                           * invFact[n - 1] % MOD;

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
constexpr int64 MOD = 1'000'000'007LL;

int64 modPow(int64 base, int64 exponent) {
    int64 result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<vector<int>> adj(N + 1);
        for (int i = 0; i < N - 1; ++i) {
            int u, v;
            cin >> u >> v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        // Root the tree at vertex 1 and construct a parent-before-child order.
        vector<int> parent(N + 1, 0);
        vector<int> order;
        order.reserve(N);
        order.push_back(1);

        for (int i = 0; i < (int)order.size(); ++i) {
            int v = order[i];
            for (int u : adj[v]) {
                if (u == parent[v]) continue;
                parent[u] = v;
                order.push_back(u);
            }
        }

        // Subtree sizes when rooted at vertex 1.
        vector<int> subtree(N + 1, 1);
        for (int i = N - 1; i >= 1; --i) {
            int v = order[i];
            subtree[parent[v]] += subtree[v];
        }

        // Modular inverses of 1, 2, ..., N.
        vector<int64> inv(N + 1);
        inv[1] = 1;
        for (int i = 2; i <= N; ++i) {
            inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
        }

        // q[v] = 1 / P_v, where P_v is the product of the non-root
        // subtree sizes when the entire tree is rooted at v.
        vector<int64> q(N + 1);
        int64 rootQ = 1;
        for (int v = 2; v <= N; ++v) {
            rootQ = rootQ * inv[subtree[v]] % MOD;
        }

        q[1] = rootQ;
        int64 sumQ = rootQ;

        // Reroot from each parent to its children.
        for (int i = 1; i < N; ++i) {
            int v = order[i];
            int u = parent[v];

            q[v] = q[u] * subtree[v] % MOD;
            q[v] = q[v] * inv[N - subtree[v]] % MOD;

            sumQ += q[v];
            if (sumQ >= MOD) sumQ -= MOD;
        }

        int64 factorial = 1;
        for (int i = 2; i <= N; ++i) {
            factorial = factorial * i % MOD;
        }

        cout << sumQ * modPow(factorial, MOD - 2) % MOD << '\n';
    }

    return 0;
}

