            uint32_t weighted = dp[row + r] >> 32;
            sum += (long long)weighted * inv[pc + r];
        }
        answer[a] = sum % MOD;
    }

    for (int x : masks) {
        cout << answer[x] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

inline void addmod(int &a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    const int M = 1 << K;
    vector<int> masks(N), freq(M, 0);
    for (int &x : masks) {
        cin >> x;
        ++freq[x];
    }

    vector<int> pc(M, 0);
    for (int i = 1; i < M; ++i)
        pc[i] = pc[i >> 1] + (i & 1);

    vector<int> f0(M), f1(M);
    for (int i = 1; i < M; ++i) {
        f0[i] = freq[i] % MOD;
        f1[i] = (long long)freq[i] * pc[i] % MOD;
    }

    // Subset zeta transforms:
    // f[mask] = sum of the original values over submasks of mask.
    for (int bit = 1; bit < M; bit <<= 1) {
        for (int base = 0; base < M; base += bit << 1) {
            for (int j = 0; j < bit; ++j) {
                addmod(f0[base + bit + j], f0[base + j]);
                addmod(f1[base + bit + j], f1[base + j]);
            }
        }
    }

    // weight[p] = 1 / (p * choose(K, p)).
    vector<long long> fact(K + 1, 1), invfact(K + 1, 1);
    for (int i = 1; i <= K; ++i)
        fact[i] = fact[i - 1] * i % MOD;
    invfact[K] = modpow(fact[K], MOD - 2);
    for (int i = K; i >= 1; --i)
        invfact[i - 1] = invfact[i] * i % MOD;

    vector<int> weight(K + 1, 0);
    for (int p = 1; p <= K; ++p) {
        long long choose = fact[K] * invfact[p] % MOD * invfact[K - p] % MOD;
        weight[p] = modpow(choose * p % MOD, MOD - 2);
    }

    for (int i = 1; i < M; ++i) {
        int w = weight[pc[i]];
        f0[i] = (long long)f0[i] * w % MOD;
        f1[i] = (long long)f1[i] * w % MOD;
    }

    // Superset zeta transforms.
    for (int bit = 1; bit < M; bit <<= 1) {
        for (int base = 0; base < M; base += bit << 1) {
            for (int j = 0; j < bit; ++j) {
                addmod(f0[base + j], f0[base + bit + j]);
                addmod(f1[base + j], f1[base + bit + j]);
            }
        }
    }

    const int nmod = N % MOD;
    for (int s : masks) {
        int ans = ((long long)pc[s] * f0[s] + f1[s]) % MOD;
        ans -= nmod;
        if (ans < 0) ans += MOD;
        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    int M = 1 << K;
    vector<int> cnt(M, 0);
    vector<int> cows(N);

    for (int i = 0; i < N; i++) {
        int x;
        cin >> x;
        cows[i] = x;
        cnt[x]++;
    }

    vector<unsigned char> pc(M, 0);
    for (int i = 1; i < M; i++) {
        pc[i] = pc[i >> 1] + (i & 1);
    }

    vector<int> A(M), B(M);

    for (int mask = 0; mask < M; mask++) {
        A[mask] = cnt[mask];
        B[mask] = (long long)cnt[mask] * pc[mask] % MOD;
    }

    // Superset zeta transform:
    // A[u] = sum_{t superset u} cnt[t]
    // B[u] = sum_{t superset u} cnt[t] * popcount(t)
    for (int bit = 0; bit < K; bit++) {
        int step = 1 << bit;
        int block = step << 1;

        for (int base = 0; base < M; base += block) {
            for (int off = 0; off < step; off++) {
                int low = base + off;
                int high = low + step;

                A[low] += A[high];
                if (A[low] >= MOD) A[low] -= MOD;

                B[low] += B[high];
                if (B[low] >= MOD) B[low] -= MOD;
            }
        }
    }

    int Nmod = N % MOD;

    vector<int> fact(K + 1), invfact(K + 1);
    fact[0] = 1;
    for (int i = 1; i <= K; i++) {
        fact[i] = (long long)fact[i - 1] * i % MOD;
    }

    invfact[K] = modpow(fact[K], MOD - 2);
    for (int i = K; i >= 1; i--) {
        invfact[i - 1] = (long long)invfact[i] * i % MOD;
    }

    // f[a][p] = integral_0^1 x^(a-1) (x-1)^p dx
    //         = (-1)^p (a-1)! p! / (a+p)!
    vector<vector<int>> f(K + 1, vector<int>(K + 1, 0));

    for (int a = 1; a <= K; a++) {
        for (int p = 0; p <= K - a; p++) {
            long long val = (long long)fact[a - 1] * fact[p] % MOD;
            val = val * invfact[a + p] % MOD;
            if (p & 1) val = (MOD - val) % MOD;
            f[a][p] = (int)val;
        }
    }

    vector<vector<int>> masksByPop(K + 1);
    for (int mask = 0; mask < M; mask++) {
        masksByPop[pc[mask]].push_back(mask);
    }

    vector<int> ans(M, 0);

    // p = 0 contribution.
    // For r = complement(s), q = popcount(r), a = popcount(s) = K - q:
    // p0 = f[a][0] * (B[0] + a * A[0]) - N
    for (int q = 0; q <= K - 1; q++) {
        int a = K - q;

        int term = (B[0] + (long long)a * A[0]) % MOD;
        int baseVal = (long long)f[a][0] * term % MOD;

        baseVal -= Nmod;
        if (baseVal < 0) baseVal += MOD;

        for (int r : masksByPop[q]) {
            ans[r] = baseVal;
        }
    }

    if (K > 1) {
        int R = K - 1;
        size_t total = (size_t)R * M;

        vector<uint64_t> dpA(total, 0);
        vector<uint64_t> dpB(total, 0);

        for (int p = 1; p <= K - 1; p++) {
            size_t base = (size_t)(p - 1) * M;

            for (int mask : masksByPop[p]) {
                dpA[base + mask] = A[mask];
                dpB[base + mask] = B[mask];
            }
        }

        // Ranked subset zeta transform:
        // dpA[p-1][r] = sum_{u subset r, |u|=p} A[u]
        // dpB[p-1][r] = sum_{u subset r, |u|=p} B[u]
        for (int pidx = 0; pidx < R; pidx++) {
            uint64_t* arrA = dpA.data() + (size_t)pidx * M;
            uint64_t* arrB = dpB.data() + (size_t)pidx * M;

            for (int bit = 0; bit < K; bit++) {
                int step = 1 << bit;
                int block = step << 1;

                for (int base = 0; base < M; base += block) {
                    uint64_t* aLow = arrA + base;
                    uint64_t* aHigh = aLow + step;
                    uint64_t* bLow = arrB + base;
                    uint64_t* bHigh = bLow + step;

                    for (int off = 0; off < step; off++) {
                        aHigh[off] += aLow[off];
                        bHigh[off] += bLow[off];
                    }
                }
            }
        }

        for (int p = 1; p <= K - 1; p++) {
            uint64_t* arrA = dpA.data() + (size_t)(p - 1) * M;
            uint64_t* arrB = dpB.data() + (size_t)(p - 1) * M;

            for (int q = p; q <= K - 1; q++) {
                int a = K - q;

                int coefA = (long long)a * f[a][p] % MOD;
                int coefB = f[a][p];

                for (int r : masksByPop[q]) {
                    int valA = arrA[r] % MOD;
                    int valB = arrB[r] % MOD;

                    long long add =
                        ((long long)coefA * valA +
                         (long long)coefB * valB) % MOD;

                    int cur = ans[r] + (int)add;
                    if (cur >= MOD) cur -= MOD;
                    ans[r] = cur;
                }
            }
        }
    }

    int fullMask = M - 1;

    for (int s : cows) {
        int r = fullMask ^ s;
        cout << ans[r] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    int M = 1 << K;

    vector<int> cnt(M, 0);
    vector<int> cows;
    cows.reserve(N);

    for (int i = 0; i < N; i++) {
        int x;
        cin >> x;
        cows.push_back(x);
        cnt[x]++;
    }

    // Superset zeta transform:
    // cnt[mask] = sum_{B superset mask} original_cnt[B]
    for (int b = 0; b < K; b++) {
        int step = 1 << b;
        int block = step << 1;

        for (int base = 0; base < M; base += block) {
            for (int mask = base; mask < base + step; mask++) {
                int v = cnt[mask] + cnt[mask + step];
                if (v >= MOD) v -= MOD;
                cnt[mask] = v;
            }
        }
    }

    vector<int> pc(M, 0);
    for (int i = 1; i < M; i++) {
        pc[i] = pc[i >> 1] + (i & 1);
    }

    // F[r][mask] = sum_{R subset mask, |R|=r} cnt[R]
    vector<int> F((size_t)(K + 1) * M, 0);

    for (int mask = 0; mask < M; mask++) {
        F[(size_t)pc[mask] * M + mask] = cnt[mask];
    }

    // Ranked subset zeta transform
    for (int r = 0; r <= K; r++) {
        int* arr = F.data() + (size_t)r * M;

        for (int b = 0; b < K; b++) {
            int step = 1 << b;
            int block = step << 1;

            for (int base = 0; base < M; base += block) {
                int start = base + step;
                int end = base + block;

                for (int mask = start; mask < end; mask++) {
                    int v = arr[mask] + arr[mask - step];
                    if (v >= MOD) v -= MOD;
                    arr[mask] = v;
                }
            }
        }
    }

    // Binomial coefficients
    int C[21][21] = {};
    C[0][0] = 1;

    for (int n = 1; n <= K; n++) {
        C[n][0] = C[n][n] = 1;
        for (int r = 1; r < n; r++) {
            C[n][r] = C[n - 1][r - 1] + C[n - 1][r];
            if (C[n][r] >= MOD) C[n][r] -= MOD;
        }
    }

    // Mobius coefficients of f(S) = 1/|S| for nonempty S, f(empty)=0
    int invf[21] = {};
    int a[21] = {};

    for (int i = 1; i <= K; i++) {
        invf[i] = (int)modpow(i, MOD - 2);
    }

    for (int s = 1; s <= K; s++) {
        long long sum = 0;

        for (int i = 0; i <= s; i++) {
            long long term = 1LL * C[s][i] * invf[i] % MOD;

            if ((s - i) & 1) sum -= term;
            else sum += term;
        }

        sum %= MOD;
        if (sum < 0) sum += MOD;
        a[s] = (int)sum;
    }

    // B[c][r] = sum_{t=0}^{c} C(c,t) * a[t+r]
    int Bcoef[21][21] = {};

    for (int c = 0; c <= K; c++) {
        for (int r = 0; r <= K - c; r++) {
            long long sum = 0;

            for (int t = 0; t <= c; t++) {
                sum += 1LL * C[c][t] * a[t + r] % MOD;
            }

            Bcoef[c][r] = (int)(sum % MOD);
        }
    }

    vector<int> W(M, 0), V(M, 0);

    for (int mask = 1; mask < M; mask++) {
        int sz = pc[mask];
        int c = K - sz;
        int c2 = c + 1;

        long long sumW = 0;
        long long sumV = 0;

        for (int r = 1; r <= sz; r++) {
            int fv = F[(size_t)r * M + mask];

            sumW += 1LL * Bcoef[c2][r - 1] * fv % MOD;
            sumV += 1LL * Bcoef[c][r - 1] * fv % MOD;
        }

        W[mask] = (int)(sumW % MOD);
        V[mask] = (int)(sumV % MOD);
    }

    // neigh[X] = sum_{i not in X} W[X union {i}]
    vector<int> neigh(M, 0);

    for (int Y = 1; Y < M; Y++) {
        int w = W[Y];
        if (w == 0) continue;

        int bits = Y;

        while (bits) {
            int lb = bits & -bits;
            int X = Y ^ lb;

            int val = neigh[X] + w;
            if (val >= MOD) val -= MOD;
            neigh[X] = val;

            bits -= lb;
        }
    }

    vector<int> ans(M, 0);
    int full = M - 1;

    for (int X = 0; X < M; X++) {
        int sz = pc[X];
        int c = K - sz;

        if (c == 0) continue;

        int A = full ^ X;

        long long res = neigh[X] - 1LL * c * V[X] % MOD;
        res %= MOD;
        if (res < 0) res += MOD;

        ans[A] = (int)res;
    }

    string output;
    output.reserve((size_t)N * 12);

    for (int i = 0; i < N; i++) {
        output += to_string(ans[cows[i]]);
        output.push_back('\n');
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    int M = 1 << K;

    vector<int> cnt(M, 0), wcnt(M, 0);
    vector<int> input(N);

    for (int i = 0; i < N; i++) {
        int x;
        cin >> x;
        input[i] = x;
        cnt[x]++;
        wcnt[x] += __builtin_popcount((unsigned)x);
    }

    // Subset zeta transforms:
    // cnt[u]  = sum_{y subset u} frequency[y]
    // wcnt[u] = sum_{y subset u} frequency[y] * popcount(y)
    for (int bit = 0; bit < K; bit++) {
        int step = 1 << bit;
        for (int base = 0; base < M; base += (step << 1)) {
            for (int off = 0; off < step; off++) {
                cnt[base + step + off] += cnt[base + off];
                wcnt[base + step + off] += wcnt[base + off];
            }
        }
    }

    vector<int> inv(K + 1, 0);
    for (int i = 1; i <= K; i++) {
        inv[i] = (int)modpow(i, MOD - 2);
    }

    long long comb[21][21] = {};
    for (int i = 0; i <= K; i++) {
        comb[i][0] = comb[i][i] = 1;
        for (int j = 1; j < i; j++) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
        }
    }

    // C[s] = sum_t inv[t] * [z^t] z^s (1-z)^(K-s)
    vector<int> C(K + 1, 0);

    for (int s = 0; s <= K; s++) {
        long long val = 0;
        int m = K - s;

        for (int r = 0; r <= m; r++) {
            int t = s + r;
            if (t == 0) continue;

            long long term = comb[m][r] * inv[t] % MOD;
            if (r & 1) val = (val - term + MOD) % MOD;
            else val = (val + term) % MOD;
        }

        C[s] = (int)val;
    }

    vector<int> A(M), B(M);

    for (int u = 0; u < M; u++) {
        int pc = __builtin_popcount((unsigned)u);
        A[u] = (long long)cnt[u] * C[pc] % MOD;
        B[u] = (long long)wcnt[u] * C[pc] % MOD;
    }

    // Superset zeta transforms.
    for (int bit = 0; bit < K; bit++) {
        int step = 1 << bit;
        for (int base = 0; base < M; base += (step << 1)) {
            for (int off = 0; off < step; off++) {
                int idx = base + off;

                int sumA = A[idx] + A[idx + step];
                if (sumA >= MOD) sumA -= MOD;
                A[idx] = sumA;

                int sumB = B[idx] + B[idx + step];
                if (sumB >= MOD) sumB -= MOD;
                B[idx] = sumB;
            }
        }
    }

    for (int x : input) {
        int pc = __builtin_popcount((unsigned)x);

        long long ans = (long long)pc * A[x] % MOD;
        ans = (ans - N) % MOD;
        ans = (ans + B[x]) % MOD;

        if (ans < 0) ans += MOD;
        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int MOD = 1'000'000'007;

long long modPow(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    const int M = 1 << K;

    vector<unsigned char> popcount(M, 0);
    for (int mask = 1; mask < M; ++mask) {
        popcount[mask] = popcount[mask >> 1] + (mask & 1);
    }

    vector<int> cows(N);
    vector<int> F(M, 0), G(M, 0);

    for (int i = 0; i < N; ++i) {
        int mask;
        cin >> mask;
        cows[i] = mask;

        ++F[mask];
        G[mask] += popcount[mask];
    }

    long long choose[21][21] = {};
    for (int n = 0; n <= K; ++n) {
        choose[n][0] = choose[n][n] = 1;
        for (int r = 1; r < n; ++r) {
            choose[n][r] = choose[n - 1][r - 1] + choose[n - 1][r];
        }
    }

    // coefficient[s] = 1 / (s * C(K, s)).
    vector<int> coefficient(K + 1, 0);
    for (int s = 1; s <= K; ++s) {
        long long denominator = s * choose[K][s] % MOD;
        coefficient[s] = static_cast<int>(modPow(denominator, MOD - 2));
    }

    // Subset zeta transforms:
    // F[S] = sum_{B subseteq S} frequency[B]
    // G[S] = sum_{B subseteq S} popcount[B] * frequency[B]
    for (int bit = 1; bit < M; bit <<= 1) {
        for (int start = 0; start < M; start += (bit << 1)) {
            for (int offset = 0; offset < bit; ++offset) {
                int low = start + offset;
                int high = low + bit;

                int value = F[low] + F[high];
                if (value >= MOD) value -= MOD;
                F[low] = value;

                value = G[low] + G[high];
                if (value >= MOD) value -= MOD;
                G[low] = value;
            }
        }
    }

    // Weight each set by 1 / (|S| * C(K, |S|)).
    for (int mask = 0; mask < M; ++mask) {
        int coefficientValue = coefficient[popcount[mask]];
        F[mask] = static_cast<int>(1LL * F[mask] * coefficientValue % MOD);
        G[mask] = static_cast<int>(1LL * G[mask] * coefficientValue % MOD);
    }

    // Superset zeta transforms.
    for (int bit = 1; bit < M; bit <<= 1) {
        for (int start = 0; start < M; start += (bit << 1)) {
            for (int offset = 0; offset < bit; ++offset) {
                int low = start + offset;
                int high = low + bit;

                int value = F[high] + F[low];
                if (value >= MOD) value -= MOD;
                F[high] = value;

                value = G[high] + G[low];
                if (value >= MOD) value -= MOD;
                G[high] = value;
            }
        }
    }

    string output;
    output.reserve(static_cast<size_t>(N) * 11);

    for (int mask : cows) {
        long long answer =
            (1LL * popcount[mask] * F[mask] + G[mask]) % MOD;

        answer -= N;
        if (answer < 0) answer += MOD;

        output += to_string(answer);
        output.push_back('\n');
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
constexpr int MOD = 1'000'000'007;

class FastScanner {
    static constexpr int BUFFER_SIZE = 1 << 16;
    char buffer[BUFFER_SIZE];
    int pos = 0, len = 0;

    inline int getChar() {
        if (pos == len) {
            len = static_cast<int>(
                fread(buffer, 1, BUFFER_SIZE, stdin)
            );
            pos = 0;
            if (len == 0) return EOF;
        }
        return static_cast<unsigned char>(buffer[pos++]);
    }

public:
    bool readInt(int &value) {
        int c;
        do {
            c = getChar();
            if (c == EOF) return false;
        } while (c <= ' ');

        value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = getChar();
        }
        return true;
    }
};

int modPow(int base, int exponent) {
    int64 result = 1;
    int64 x = base;

    while (exponent > 0) {
        if (exponent & 1) result = result * x % MOD;
        x = x * x % MOD;
        exponent >>= 1;
    }

    return static_cast<int>(result);
}

int main() {
    FastScanner fs;

    int N, K;
    if (!fs.readInt(N)) return 0;
    fs.readInt(K);

    const int M = 1 << K;
    const int ALL = M - 1;
    const int W = K + 1;

    vector<int> cows(N);
    vector<int> contain(M, 0);

    for (int i = 0; i < N; ++i) {
        fs.readInt(cows[i]);
        ++contain[cows[i]];
    }

    // Superset zeta transform:
    // contain[T] = number of cows whose masks contain T.
    for (int bit = 0; bit < K; ++bit) {
        const int step = 1 << bit;
        for (int base = 0; base < M; base += step << 1) {
            for (int offset = 0; offset < step; ++offset) {
                contain[base + offset] += contain[base + offset + step];
            }
        }
    }

    vector<uint8_t> popcount(M, 0);
    for (int mask = 1; mask < M; ++mask) {
        popcount[mask] = popcount[mask >> 1] + (mask & 1);
    }

    // ranked[S][r] = sum of contain[T] over T subset of S with |T| = r.
    //
    // These values fit exactly in int64:
    // ranked[S][r] <= N * C(K, r) <= 9.24e10.
    vector<int64> ranked(static_cast<size_t>(M) * W, 0);

    for (int mask = 0; mask < M; ++mask) {
        ranked[static_cast<size_t>(mask) * W + popcount[mask]] =
            contain[mask];
    }

    // Ranked subset zeta transform.
    for (int bit = 0; bit < K; ++bit) {
        const int step = 1 << bit;
        for (int base = 0; base < M; base += step << 1) {
            for (int offset = 0; offset < step; ++offset) {
                const int low = base + offset;
                const int high = low + step;

                const int64 *src =
                    ranked.data() + static_cast<size_t>(low) * W;
                int64 *dst =
                    ranked.data() + static_cast<size_t>(high) * W;

                const int limit = popcount[low];
                for (int r = 0; r <= limit; ++r) {
                    dst[r] += src[r];
                }
            }
        }
    }

    vector<int> factorial(K + 1), inverseFactorial(K + 1);
    factorial[0] = 1;
    for (int i = 1; i <= K; ++i) {
        factorial[i] =
            static_cast<int>(1LL * factorial[i - 1] * i % MOD);
    }

    inverseFactorial[K] = modPow(factorial[K], MOD - 2);
    for (int i = K; i >= 1; --i) {
        inverseFactorial[i - 1] =
            static_cast<int>(1LL * inverseFactorial[i] * i % MOD);
    }

    // weight[a][r] =
    // (-1)^(r-1) * (a-1)! * (r-1)! / (a+r-1)!.
    vector<int> weight(static_cast<size_t>(W) * W, 0);

    for (int a = 1; a <= K; ++a) {
        for (int r = 1; a + r - 1 <= K; ++r) {
            int64 value = 1LL * factorial[a - 1] * factorial[r - 1] % MOD;
            value = value * inverseFactorial[a + r - 1] % MOD;

            if ((r & 1) == 0) value = MOD - value;

            weight[static_cast<size_t>(a) * W + r] =
                static_cast<int>(value);
        }
    }

    vector<int> answer(M, 0);

    for (int A = 1; A < M; ++A) {
        const int S = ALL ^ A;
        const int a = popcount[A];
        const int p = K - a;
        const int maxRank = p + 1;

        int64 accumulator[21];
        for (int r = 1; r <= maxRank; ++r) {
            accumulator[r] = 0;
        }

        const int64 *baseRow =
            ranked.data() + static_cast<size_t>(S) * W;

        // Sum over i in A:
        // D[r] = sum_i (ranked[S union {i}][r] - ranked[S][r]).
        for (int r = 1; r <= p; ++r) {
            accumulator[r] = -1LL * a * baseRow[r];
        }

        int remaining = A;
        while (remaining != 0) {
            const int bit = remaining & -remaining;
            remaining -= bit;

            const int neighbor = S | bit;
            const int64 *row =
                ranked.data() + static_cast<size_t>(neighbor) * W;

            for (int r = 1; r <= maxRank; ++r) {
                accumulator[r] += row[r];
            }
        }

        int64 result = 0;
        const int *weights =
            weight.data() + static_cast<size_t>(a) * W;

        for (int r = 1; r <= maxRank; ++r) {
            int64 value = accumulator[r] % MOD;
            if (value < 0) value += MOD;

            result = (result + value * weights[r]) % MOD;
        }

        answer[A] = static_cast<int>(result);
    }

    string output;
    output.reserve(static_cast<size_t>(N) * 11);

    for (int mask : cows) {
        output += to_string(answer[mask]);
        output.push_back('\n');
    }

    fwrite(output.data(), 1, output.size(), stdout);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int MOD = 1'000'000'007;

inline void addmod(int& a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
}

long long modpow(long long a, long long e) {
    long long result = 1;
    while (e > 0) {
        if (e & 1) result = result * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    const int M = 1 << K;

    vector<int> cows(N);
    vector<int> z(M, 0), w(M, 0);
    vector<unsigned char> popcount(M, 0);

    for (int mask = 1; mask < M; ++mask) {
        popcount[mask] = popcount[mask >> 1] + (mask & 1);
    }

    for (int i = 0; i < N; ++i) {
        cin >> cows[i];
        ++z[cows[i]];
    }

    // Initially:
    // z[mask] = cnt[mask]
    // w[mask] = |mask| * cnt[mask]
    for (int mask = 0; mask < M; ++mask) {
        w[mask] = static_cast<int>(
            1LL * z[mask] * popcount[mask] % MOD
        );
    }

    // Subset zeta transforms:
    // z[U] = sum_{B subseteq U} cnt[B]
    // w[U] = sum_{B subseteq U} |B| * cnt[B]
    for (int bit = 1; bit < M; bit <<= 1) {
        for (int base = 0; base < M; base += (bit << 1)) {
            for (int offset = 0; offset < bit; ++offset) {
                int low = base + offset;
                int high = low + bit;

                addmod(z[high], z[low]);
                addmod(w[high], w[low]);
            }
        }
    }

    long long fact[21];
    fact[0] = 1;
    for (int i = 1; i <= K; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }

    long long invFactK = modpow(fact[K], MOD - 2);

    // coefficient[r] = 1 / (r * C(K, r))
    //                 = (r-1)! * (K-r)! / K!
    int coefficient[21] = {};
    for (int r = 1; r <= K; ++r) {
        coefficient[r] = static_cast<int>(
            fact[r - 1] * fact[K - r] % MOD * invFactK % MOD
        );
    }

    for (int mask = 0; mask < M; ++mask) {
        int c = coefficient[popcount[mask]];
        z[mask] = static_cast<int>(1LL * z[mask] * c % MOD);
        w[mask] = static_cast<int>(1LL * w[mask] * c % MOD);
    }

    // Superset zeta transforms:
    // z[A] = F(A), w[A] = G(A)
    for (int bit = 1; bit < M; bit <<= 1) {
        for (int base = 0; base < M; base += (bit << 1)) {
            for (int offset = 0; offset < bit; ++offset) {
                int low = base + offset;
                int high = low + bit;

                addmod(z[low], z[high]);
                addmod(w[low], w[high]);
            }
        }
    }

    for (int mask : cows) {
        long long answer =
            (1LL * popcount[mask] * z[mask] + w[mask] - N) % MOD;

        if (answer < 0) answer += MOD;
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);
const int BLOCK = 16;

struct Func {
    // Values are defined for k = lo, ..., lo + inc.size().
    // value(lo) = base, and inc contains successive differences.
    int lo = -1;
    ll base = 0;
    vector<ll> inc;

    bool empty() const { return lo == -1; }
};

using Matrix = array<Func, 9>;

static Func singletonFunc(int k, ll value) {
    Func f;
    f.lo = k;
    f.base = value;
    return f;
}

static Func convolve(const Func& f, const Func& g) {
    if (f.empty() || g.empty()) return Func();

    Func r;
    r.lo = f.lo + g.lo;
    r.base = f.base + g.base;
    r.inc.resize(f.inc.size() + g.inc.size());
    merge(f.inc.begin(), f.inc.end(),
          g.inc.begin(), g.inc.end(), r.inc.begin());
    return r;
}

static Func pointwiseMin(Func* fs, int n) {
    if (n == 0) return Func();
    if (n == 1) return std::move(fs[0]);

    int lo = INT_MAX, hi = INT_MIN;
    for (int i = 0; i < n; i++) {
        lo = min(lo, fs[i].lo);
        hi = max(hi, fs[i].lo + (int)fs[i].inc.size());
    }

    vector<ll> values(hi - lo + 1, INF);
    for (int i = 0; i < n; i++) {
        const Func& f = fs[i];
        ll value = f.base;
        int at = f.lo - lo;
        for (int j = 0; j <= (int)f.inc.size(); j++) {
            values[at + j] = min(values[at + j], value);
            if (j < (int)f.inc.size()) value += f.inc[j];
        }
    }

    Func r;
    r.lo = lo;
    r.base = values[0];
    r.inc.resize(values.size() - 1);
    for (int i = 1; i < (int)values.size(); i++) {
        r.inc[i - 1] = values[i] - values[i - 1];
    }
    return r;
}

static Matrix combine(const Matrix& a, const Matrix& b, int states) {
    Matrix c;
    for (int leftState = 0; leftState < states; leftState++) {
        for (int rightState = 0; rightState < states; rightState++) {
            Func tmp[3];
            int cnt = 0;
            for (int midState = 0; midState < states; midState++) {
                const Func& f = a[leftState * states + midState];
                const Func& g = b[midState * states + rightState];
                if (!f.empty() && !g.empty()) {
                    tmp[cnt++] = convolve(f, g);
                }
            }
            if (cnt) {
                c[leftState * states + rightState] = pointwiseMin(tmp, cnt);
            }
        }
    }
    return c;
}

static Matrix makeBlock(const vector<ll>& weight, int l, int r, int states) {
    Matrix result;
    int len = r - l;
    int maxK = (len + states - 1) / states;

    ll dp[3][BLOCK + 1], ndp[3][BLOCK + 1];

    for (int initial = 0; initial < states; initial++) {
        for (int s = 0; s < states; s++) {
            for (int k = 0; k <= maxK; k++) dp[s][k] = INF;
        }
        dp[initial][0] = 0;

        for (int pos = l; pos < r; pos++) {
            for (int s = 0; s < states; s++) {
                for (int k = 0; k <= maxK; k++) ndp[s][k] = INF;
            }

            for (int s = 0; s < states; s++) {
                for (int k = 0; k <= maxK; k++) {
                    ll cur = dp[s][k];
                    if (cur == INF) continue;

                    int skipState = (s == 0 ? 0 : s - 1);
                    ndp[skipState][k] = min(ndp[skipState][k], cur);

                    if (s == 0 && k < maxK) {
                        ndp[states - 1][k + 1] =
                            min(ndp[states - 1][k + 1], cur + weight[pos]);
                    }
                }
            }

            for (int s = 0; s < states; s++) {
                for (int k = 0; k <= maxK; k++) dp[s][k] = ndp[s][k];
            }
        }

        for (int ending = 0; ending < states; ending++) {
            int lo = 0;
            while (lo <= maxK && dp[ending][lo] == INF) lo++;
            if (lo > maxK) continue;

            int hi = maxK;
            while (dp[ending][hi] == INF) hi--;

            Func f;
            f.lo = lo;
            f.base = dp[ending][lo];
            for (int k = lo + 1; k <= hi; k++) {
                f.inc.push_back(dp[ending][k] - dp[ending][k - 1]);
            }
            result[initial * states + ending] = std::move(f);
        }
    }
    return result;
}

static Matrix buildDP(const vector<ll>& weight, int l, int r, int states) {
    if (r - l <= BLOCK) return makeBlock(weight, l, r, states);
    int mid = (l + r) / 2;
    Matrix left = buildDP(weight, l, mid, states);
    Matrix right = buildDP(weight, mid, r, states);
    return combine(left, right, states);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, N;
    cin >> L >> N;

    string s;
    cin >> s;

    vector<ll> cost(N);
    for (ll& x : cost) cin >> x;

    int m = N - L + 1;
    vector<ll> weight(m);
    for (int i = 0; i < m; i++) {
        ll w = 0;
        if (s[i] != 'M') w += cost[i];
        for (int j = 1; j < L; j++) {
            if (s[i + j] != 'O') w += cost[i + j];
        }
        weight[i] = w;
    }

    int K = N / L;

    if (L == 1) {
        sort(weight.begin(), weight.end());
        ll answer = 0;
        for (int k = 0; k < K; k++) {
            answer += weight[k];
            cout << answer << '\n';
        }
        return 0;
    }

    Matrix root = buildDP(weight, 0, m, L);
    Func endings[3];
    int cnt = 0;
    for (int state = 0; state < L; state++) {
        if (!root[state].empty()) endings[cnt++] = std::move(root[state]);
    }
    Func answerFunc = pointwiseMin(endings, cnt);

    ll answer = answerFunc.base;
    for (int k = 1; k <= K; k++) {
        answer += answerFunc.inc[k - answerFunc.lo - 1];
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);
const int BASE = 24;

int L, N;
vector<ll> weight;

struct Funcs {
    vector<ll> f[9];
};

// Inf-convolution of two convex, nondecreasing cost functions.
// Their slopes are merged in increasing order.
vector<ll> convolve(const vector<ll>& a, const vector<ll>& b) {
    if (a.size() == 1) return b;
    if (b.size() == 1) return a;

    vector<ll> res(a.size() + b.size() - 1);
    res[0] = 0;

    size_t i = 1, j = 1;
    for (size_t pos = 1; pos < res.size(); ++pos) {
        ll slope;
        if (i < a.size() &&
            (j == b.size() || a[i] - a[i - 1] <= b[j] - b[j - 1])) {
            slope = a[i] - a[i - 1];
            ++i;
        } else {
            slope = b[j] - b[j - 1];
            ++j;
        }
        res[pos] = res[pos - 1] + slope;
    }
    return res;
}

Funcs brute(int l, int r) {
    Funcs out;

    for (int a = 0; a < L; ++a) {
        for (int b = 0; b < L; ++b) {
            int A = l + a;
            int B = r - b;
            int m = B - A;

            if (m <= 0) {
                out.f[a * L + b] = {0};
                continue;
            }

            int K = m / L;
            ll dp[BASE + 1][BASE + 1];

            for (int i = 0; i <= m; ++i)
                for (int k = 0; k <= K; ++k)
                    dp[i][k] = INF;

            dp[0][0] = 0;

            for (int i = 0; i < m; ++i) {
                for (int k = 0; k <= K; ++k) {
                    if (dp[i][k] == INF) continue;

                    dp[i + 1][k] = min(dp[i + 1][k], dp[i][k]);

                    if (i + L <= m && k < K) {
                        dp[i + L][k + 1] = min(
                            dp[i + L][k + 1],
                            dp[i][k] + weight[A + i]
                        );
                    }
                }
            }

            out.f[a * L + b] =
                vector<ll>(dp[m], dp[m] + K + 1);
        }
    }

    return out;
}

Funcs solve(int l, int r) {
    if (r - l <= BASE) return brute(l, r);

    int mid = (l + r) / 2;
    Funcs left = solve(l, mid);
    Funcs right = solve(mid, r);
    Funcs out;

    for (int a = 0; a < L; ++a) {
        for (int b = 0; b < L; ++b) {
            int A = l + a;
            int B = r - b;
            int K = (B - A) / L;

            // No selected moo crosses mid.
            auto best = convolve(
                left.f[a * L],
                right.f[b]
            );

            if ((int)best.size() < K + 1)
                best.resize(K + 1, INF);

            // Try the unique moo crossing mid, if one is selected.
            for (int p = 1; p < L; ++p) {
                int start = mid - p;
                int q = L - p;

                if (start < A || start + L > B) continue;

                auto cur = convolve(
                    left.f[a * L + p],
                    right.f[q * L + b]
                );

                for (size_t j = 0; j < cur.size(); ++j) {
                    best[j + 1] = min(
                        best[j + 1],
                        cur[j] + weight[start]
                    );
                }
            }

            out.f[a * L + b] = move(best);
        }
    }

    return out;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> L >> N;

    string s;
    cin >> s;

    vector<ll> c(N);
    for (ll& x : c) cin >> x;

    if (L == 1) {
        vector<ll> costs(N);
        for (int i = 0; i < N; ++i)
            costs[i] = (s[i] == 'M' ? 0 : c[i]);

        sort(costs.begin(), costs.end());

        ll sum = 0;
        for (int k = 1; k <= N; ++k) {
            sum += costs[k - 1];
            cout << sum << '\n';
        }
        return 0;
    }

    weight.resize(N - L + 1);
    for (int i = 0; i + L <= N; ++i) {
        ll cost = (s[i] == 'M' ? 0 : c[i]);
        for (int j = 1; j < L; ++j)
            cost += (s[i + j] == 'O' ? 0 : c[i + j]);
        weight[i] = cost;
    }

    Funcs answer = solve(0, N);
    const vector<ll>& f = answer.f[0];

    for (int k = 1; k <= N / L; ++k)
        cout << f[k] << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);

struct Poly {
    int lo = 0;
    vector<ll> v;

    bool empty() const { return v.empty(); }
    int hi() const { return lo + (int)v.size() - 1; }

    ll get(int k) const {
        if (v.empty() || k < lo || k > hi()) return INF;
        return v[k - lo];
    }
};

Poly convolve(const Poly &a, const Poly &b) {
    Poly c;
    c.lo = a.lo + b.lo;

    if (a.v.size() == 1) {
        c.v.resize(b.v.size());
        for (int i = 0; i < (int)b.v.size(); i++)
            c.v[i] = b.v[i] + a.v[0];
        return c;
    }
    if (b.v.size() == 1) {
        c.v.resize(a.v.size());
        for (int i = 0; i < (int)a.v.size(); i++)
            c.v[i] = a.v[i] + b.v[0];
        return c;
    }

    int sa = (int)a.v.size(), sb = (int)b.v.size();
    c.v.resize(sa + sb - 1);

    ll cur = a.v[0] + b.v[0];
    c.v[0] = cur;

    int i = 1, j = 1, out = 1;
    while (i < sa || j < sb) {
        ll da = i < sa ? a.v[i] - a.v[i - 1] : INF;
        ll db = j < sb ? b.v[j] - b.v[j - 1] : INF;

        if (da <= db) {
            cur += da;
            i++;
        } else {
            cur += db;
            j++;
        }
        c.v[out++] = cur;
    }
    return c;
}

Poly polyMin(Poly a, Poly b) {
    if (a.empty()) return b;
    if (b.empty()) return a;

    Poly c;
    c.lo = min(a.lo, b.lo);
    int hi = max(a.hi(), b.hi());
    c.v.resize(hi - c.lo + 1);

    for (int k = c.lo; k <= hi; k++)
        c.v[k - c.lo] = min(a.get(k), b.get(k));

    return c;
}

struct Matrix {
    array<Poly, 9> p;

    Poly &at(int i, int j) { return p[i * 3 + j]; }
    const Poly &at(int i, int j) const { return p[i * 3 + j]; }
};

int L, S, M;
vector<ll> weight;

Matrix combine(const Matrix &a, const Matrix &b) {
    Matrix c;

    for (int i = 0; i < S; i++) {
        for (int j = 0; j < S; j++) {
            for (int mid = 0; mid < S; mid++) {
                const Poly &x = a.at(i, mid);
                const Poly &y = b.at(mid, j);
                if (x.empty() || y.empty()) continue;

                Poly z = convolve(x, y);
                c.at(i, j) = polyMin(std::move(c.at(i, j)), std::move(z));
            }
        }
    }
    return c;
}

Matrix solve(int l, int r) {
    if (l == r) {
        Matrix a;

        for (int s = 0; s < S; s++) {
            Poly p;
            p.lo = 0;
            p.v = {0};
            a.at(s, s == 0 ? 0 : s - 1) = std::move(p);
        }

        Poly selected;
        selected.lo = 1;
        selected.v = {weight[l]};
        a.at(0, L - 1) = std::move(selected);

        return a;
    }

    int mid = (l + r) / 2;
    Matrix left = solve(l, mid);
    Matrix right = solve(mid + 1, r);
    return combine(left, right);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> L >> N;

    string str;
    cin >> str;

    vector<ll> cost(N);
    for (ll &x : cost) cin >> x;

    M = N - L + 1;
    weight.assign(M, 0);

    for (int i = 0; i < M; i++) {
        if (str[i] != 'M') weight[i] += cost[i];
        for (int j = 1; j < L; j++) {
            if (str[i + j] != 'O') weight[i] += cost[i + j];
        }
    }

    int K = N / L;

    if (L == 1) {
        sort(weight.begin(), weight.end());
        ll sum = 0;
        for (int k = 1; k <= K; k++) {
            sum += weight[k - 1];
            cout << sum << '\n';
        }
        return 0;
    }

    S = L;
    Matrix root = solve(0, M - 1);

    Poly answer;
    for (int state = 0; state < S; state++) {
        answer = polyMin(std::move(answer), std::move(root.at(0, state)));
    }

    for (int k = 1; k <= K; k++)
        cout << answer.get(k) << '\n';

    return 0;
}

