#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);
const int BASE = 24;

int L, N;
vector<ll> weight;

struct Funcs {
    vector<ll> f[9];
};

// Inf-convolution of two convex, nondecreasing cost functions.
// Their slopes are merged in increasing order.
vector<ll> convolve(const vector<ll>& a, const vector<ll>& b) {
    if (a.size() == 1) return b;
    if (b.size() == 1) return a;

    vector<ll> res(a.size() + b.size() - 1);
    res[0] = 0;

    size_t i = 1, j = 1;
    for (size_t pos = 1; pos < res.size(); ++pos) {
        ll slope;
        if (i < a.size() &&
            (j == b.size() || a[i] - a[i - 1] <= b[j] - b[j - 1])) {
            slope = a[i] - a[i - 1];
            ++i;
        } else {
            slope = b[j] - b[j - 1];
            ++j;
        }
        res[pos] = res[pos - 1] + slope;
    }
    return res;
}

Funcs brute(int l, int r) {
    Funcs out;

    for (int a = 0; a < L; ++a) {
        for (int b = 0; b < L; ++b) {
            int A = l + a;
            int B = r - b;
            int m = B - A;

            if (m <= 0) {
                out.f[a * L + b] = {0};
                continue;
            }

            int K = m / L;
            ll dp[BASE + 1][BASE + 1];

            for (int i = 0; i <= m; ++i)
                for (int k = 0; k <= K; ++k)
                    dp[i][k] = INF;

            dp[0][0] = 0;

            for (int i = 0; i < m; ++i) {
                for (int k = 0; k <= K; ++k) {
                    if (dp[i][k] == INF) continue;

                    dp[i + 1][k] = min(dp[i + 1][k], dp[i][k]);

                    if (i + L <= m && k < K) {
                        dp[i + L][k + 1] = min(
                            dp[i + L][k + 1],
                            dp[i][k] + weight[A + i]
                        );
                    }
                }
            }

            out.f[a * L + b] =
                vector<ll>(dp[m], dp[m] + K + 1);
        }
    }

    return out;
}

Funcs solve(int l, int r) {
    if (r - l <= BASE) return brute(l, r);

    int mid = (l + r) / 2;
    Funcs left = solve(l, mid);
    Funcs right = solve(mid, r);
    Funcs out;

    for (int a = 0; a < L; ++a) {
        for (int b = 0; b < L; ++b) {
            int A = l + a;
            int B = r - b;
            int K = (B - A) / L;

            // No selected moo crosses mid.
            auto best = convolve(
                left.f[a * L],
                right.f[b]
            );

            if ((int)best.size() < K + 1)
                best.resize(K + 1, INF);

            // Try the unique moo crossing mid, if one is selected.
            for (int p = 1; p < L; ++p) {
                int start = mid - p;
                int q = L - p;

                if (start < A || start + L > B) continue;

                auto cur = convolve(
                    left.f[a * L + p],
                    right.f[q * L + b]
                );

                for (size_t j = 0; j < cur.size(); ++j) {
                    best[j + 1] = min(
                        best[j + 1],
                        cur[j] + weight[start]
                    );
                }
            }

            out.f[a * L + b] = move(best);
        }
    }

    return out;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> L >> N;

    string s;
    cin >> s;

    vector<ll> c(N);
    for (ll& x : c) cin >> x;

    if (L == 1) {
        vector<ll> costs(N);
        for (int i = 0; i < N; ++i)
            costs[i] = (s[i] == 'M' ? 0 : c[i]);

