    }

    Funcs answer = solve(0, N);
    const vector<ll>& f = answer.f[0];

    for (int k = 1; k <= N / L; ++k)
        cout << f[k] << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);

struct Poly {
    int lo = 0;
    vector<ll> v;

    bool empty() const { return v.empty(); }
    int hi() const { return lo + (int)v.size() - 1; }

    ll get(int k) const {
        if (v.empty() || k < lo || k > hi()) return INF;
        return v[k - lo];
    }
};

Poly convolve(const Poly &a, const Poly &b) {
    Poly c;
    c.lo = a.lo + b.lo;

    if (a.v.size() == 1) {
        c.v.resize(b.v.size());
        for (int i = 0; i < (int)b.v.size(); i++)
            c.v[i] = b.v[i] + a.v[0];
        return c;
    }
    if (b.v.size() == 1) {
        c.v.resize(a.v.size());
        for (int i = 0; i < (int)a.v.size(); i++)
            c.v[i] = a.v[i] + b.v[0];
        return c;
    }

    int sa = (int)a.v.size(), sb = (int)b.v.size();
    c.v.resize(sa + sb - 1);

    ll cur = a.v[0] + b.v[0];
    c.v[0] = cur;

    int i = 1, j = 1, out = 1;
    while (i < sa || j < sb) {
        ll da = i < sa ? a.v[i] - a.v[i - 1] : INF;
        ll db = j < sb ? b.v[j] - b.v[j - 1] : INF;

        if (da <= db) {
            cur += da;
            i++;
        } else {
            cur += db;
            j++;
        }
        c.v[out++] = cur;
    }
    return c;
}

Poly polyMin(Poly a, Poly b) {
    if (a.empty()) return b;
    if (b.empty()) return a;

    Poly c;
    c.lo = min(a.lo, b.lo);
    int hi = max(a.hi(), b.hi());
    c.v.resize(hi - c.lo + 1);

    for (int k = c.lo; k <= hi; k++)
        c.v[k - c.lo] = min(a.get(k), b.get(k));

    return c;
}

struct Matrix {
    array<Poly, 9> p;

    Poly &at(int i, int j) { return p[i * 3 + j]; }
    const Poly &at(int i, int j) const { return p[i * 3 + j]; }
};

int L, S, M;
vector<ll> weight;

Matrix combine(const Matrix &a, const Matrix &b) {
    Matrix c;

    for (int i = 0; i < S; i++) {
        for (int j = 0; j < S; j++) {
            for (int mid = 0; mid < S; mid++) {
                const Poly &x = a.at(i, mid);
                const Poly &y = b.at(mid, j);
                if (x.empty() || y.empty()) continue;

                Poly z = convolve(x, y);
                c.at(i, j) = polyMin(std::move(c.at(i, j)), std::move(z));
            }
        }
    }
    return c;
}

Matrix solve(int l, int r) {
    if (l == r) {
        Matrix a;

        for (int s = 0; s < S; s++) {
            Poly p;
            p.lo = 0;
            p.v = {0};
            a.at(s, s == 0 ? 0 : s - 1) = std::move(p);
        }

        Poly selected;
        selected.lo = 1;
        selected.v = {weight[l]};
        a.at(0, L - 1) = std::move(selected);

        return a;
    }

    int mid = (l + r) / 2;
    Matrix left = solve(l, mid);
    Matrix right = solve(mid + 1, r);
    return combine(left, right);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> L >> N;

    string str;
    cin >> str;

    vector<ll> cost(N);
    for (ll &x : cost) cin >> x;

    M = N - L + 1;
    weight.assign(M, 0);

    for (int i = 0; i < M; i++) {
        if (str[i] != 'M') weight[i] += cost[i];
        for (int j = 1; j < L; j++) {
            if (str[i + j] != 'O') weight[i] += cost[i + j];
        }
    }

    int K = N / L;

    if (L == 1) {
        sort(weight.begin(), weight.end());
        ll sum = 0;
        for (int k = 1; k <= K; k++) {
            sum += weight[k - 1];
            cout << sum << '\n';
        }
        return 0;
    }

    S = L;
    Matrix root = solve(0, M - 1);

    Poly answer;
    for (int state = 0; state < S; state++) {
        answer = polyMin(std::move(answer), std::move(root.at(0, state)));
    }

    for (int k = 1; k <= K; k++)
        cout << answer.get(k) << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = 4e18;

struct Seq {
    int lo, hi;
    ll base;
    vector<ll> diff;
    Seq() : lo(0), hi(-1), base(0) {}
};

template<int S>
struct Matrix {
    Seq a[S][S];
};

template<int S, int L>
Matrix<S> buildBlock(const vector<ll>& w, int start, int len) {
    Matrix<S> M;
    int maskState = S - 1;
    int maxC = (len + L - 1) / L;
    const int MAXB = 16;
    ll cur[4][MAXB + 1];
    ll nxt[4][MAXB + 1];

    for (int s = 0; s < S; ++s) {
        for (int mask = 0; mask < S; ++mask)
            for (int c = 0; c <= maxC; ++c)
                cur[mask][c] = INF;
        cur[s][0] = 0;

        for (int pos = start; pos < start + len; ++pos) {
            for (int mask = 0; mask < S; ++mask)
                for (int c = 0; c <= maxC; ++c)
                    nxt[mask][c] = INF;

            ll cost = w[pos];
            for (int mask = 0; mask < S; ++mask) {
                int t0 = (mask << 1) & maskState;
                for (int c = 0; c <= maxC; ++c) {
                    ll val = cur[mask][c];
                    if (val == INF) continue;

                    if (val < nxt[t0][c]) nxt[t0][c] = val;

                    if (mask == 0 && c + 1 <= maxC) {
                        ll nv = val + cost;
                        if (nv < nxt[1][c + 1]) nxt[1][c + 1] = nv;
                    }
                }
            }

            for (int mask = 0; mask < S; ++mask)
                for (int c = 0; c <= maxC; ++c)
                    cur[mask][c] = nxt[mask][c];
        }

        for (int t = 0; t < S; ++t) {
            int lo = -1, hi = -1;
            for (int c = 0; c <= maxC; ++c) {
                if (cur[t][c] != INF) {
                    if (lo == -1) lo = c;
                    hi = c;
                }
            }

            Seq &seq = M.a[s][t];
            if (lo == -1) {
                seq.lo = 0;
                seq.hi = -1;
                seq.base = 0;
                seq.diff.clear();
            } else {
                seq.lo = lo;
                seq.hi = hi;
                seq.base = cur[t][lo];
                seq.diff.clear();
                seq.diff.reserve(hi - lo);
                for (int c = lo + 1; c <= hi; ++c)
                    seq.diff.push_back(cur[t][c] - cur[t][c - 1]);
            }
        }
    }
    return M;
}

template<int S>
Matrix<S> multiply(const Matrix<S>& A, const Matrix<S>& B) {
    Matrix<S> C;

    for (int s = 0; s < S; ++s) {
        for (int t = 0; t < S; ++t) {
            int overallLo = INT_MAX, overallHi = INT_MIN;

            for (int u = 0; u < S; ++u) {
                const Seq &a = A.a[s][u];
                const Seq &b = B.a[u][t];
                if (a.hi >= a.lo && b.hi >= b.lo) {
                    overallLo = min(overallLo, a.lo + b.lo);
                    overallHi = max(overallHi, a.hi + b.hi);
                }
            }

            Seq &out = C.a[s][t];
            if (overallLo == INT_MAX) {
                out.lo = 0;
                out.hi = -1;
                out.base = 0;
                out.diff.clear();
                continue;
            }

            int len = overallHi - overallLo + 1;
            vector<ll> vals(len, INF);

            for (int u = 0; u < S; ++u) {
                const Seq &a = A.a[s][u];
                const Seq &b = B.a[u][t];
                if (a.hi < a.lo || b.hi < b.lo) continue;

                ll cur = a.base + b.base;
                int k = a.lo + b.lo;
                int idx = k - overallLo;
                if (cur < vals[idx]) vals[idx] = cur;

                int ia = 0, ib = 0;
                int lenA = a.diff.size(), lenB = b.diff.size();

                while (ia < lenA || ib < lenB) {
                    ll d;
                    if (ib == lenB || (ia < lenA && a.diff[ia] <= b.diff[ib])) {
                        d = a.diff[ia++];
                    } else {
                        d = b.diff[ib++];
                    }

                    cur += d;
                    ++k;
                    int idx2 = k - overallLo;
                    if (cur < vals[idx2]) vals[idx2] = cur;
                }
            }

            out.lo = overallLo;
            out.hi = overallHi;
            out.base = vals[0];
            int dlen = len - 1;
            out.diff.resize(dlen);
            for (int i = 0; i < dlen; ++i)
                out.diff[i] = vals[i + 1] - vals[i];
        }
    }
    return C;
}

template<int S, int L>
void solveL(int N, int M, const vector<ll>& w, int maxK) {
    const int BLOCK = 16;
    int numBlocks = (M + BLOCK - 1) / BLOCK;

    function<Matrix<S>(int, int)> build = [&](int l, int r) -> Matrix<S> {
        if (r - l == 1) {
            int start = l * BLOCK;
            int len = min(BLOCK, M - start);
            return buildBlock<S, L>(w, start, len);
        }

        int mid = (l + r) / 2;
        Matrix<S> A = build(l, mid);
        Matrix<S> B = build(mid, r);
        return multiply<S>(A, B);
    };

    Matrix<S> total = build(0, numBlocks);
    vector<ll> ans(maxK + 1, INF);

    for (int t = 0; t < S; ++t) {
        const Seq &seq = total.a[0][t];
        if (seq.hi < seq.lo) continue;

        ll cur = seq.base;
        int k = seq.lo;

        if (k >= 1 && k <= maxK)
            ans[k] = min(ans[k], cur);

        for (ll d : seq.diff) {
            cur += d;
            ++k;
            if (k >= 1 && k <= maxK)
                ans[k] = min(ans[k], cur);
        }
    }

    for (int k = 1; k <= maxK; ++k)
        cout << ans[k] << '\n';
}

