    cin >> L >> N;

    string s;
    cin >> s;

    vector<ll> c(N);
    for (int i = 0; i < N; ++i)
        cin >> c[i];

    if (L == 1) {
        vector<ll> w(N);
        for (int i = 0; i < N; ++i)
            w[i] = (s[i] != 'M') ? c[i] : 0;

        sort(w.begin(), w.end());

        ll sum = 0;
        for (int k = 0; k < N; ++k) {
            sum += w[k];
            cout << sum << '\n';
        }
        return 0;
    }

    int M = N - L + 1;
    vector<ll> w(M);

    for (int i = 0; i < M; ++i) {
        ll cost = 0;
        for (int j = 0; j < L; ++j) {
            char target = (j == 0) ? 'M' : 'O';
            if (s[i + j] != target)
                cost += c[i + j];
        }
        w[i] = cost;
    }

    int maxK = N / L;

    if (L == 2) {
        solveL<2, 2>(N, M, w, maxK);
    } else if (L == 3) {
        solveL<4, 3>(N, M, w, maxK);
    }

    return 0;
}

#include <bits/stdc++.h>
