};

Node build(int l, int r) {
    int len = r - l + 1;
    int maxK = (len + L - 1) / L;
    Node node;
    node.len = len;
    node.maxK = maxK;
    node.state.assign(maskCount, vector<State>(maskCount));
    if (len <= 4) {
        vector<vector<vector<long long>>> costArr(
            maskCount, vector<vector<long long>>(maskCount, vector<long long>(maxK + 1, INF)));
        for (int mask = 0; mask < (1 << len); ++mask) {
            bool valid = true;
            long long costSum = 0;
            int count = 0;
            for (int i = 0; i < len; ++i) {
                if (mask & (1 << i)) {
                    costSum += w[l + i];
                    ++count;
