                            }
                        }
                    }
                    if (!valid) break;
                }
            }
            if (!valid) continue;
            int leftMask = 0, rightMask = 0;
            for (int b = 0; b < K; ++b) {
                if (mask & (1 << b)) leftMask |= (1 << b);
                int idx = len - K + b;
                if (idx >= 0 && idx < len && (mask & (1 << idx))) rightMask |= (1 << b);
            }
            if (count <= maxK) {
                costArr[leftMask][rightMask][count] =
                    min(costArr[leftMask][rightMask][count], costSum);
            }
        }
        for (int lm = 0; lm < maskCount; ++lm) {
            for (int rm = 0; rm < maskCount; ++rm) {
                State &st = node.state[lm][rm];
                int minK = -1;
                for (int k = 0; k <= maxK; ++k) {
                    if (costArr[lm][rm][k] < INF) {
                        minK = k;
                        break;
                    }
                }
                if (minK == -1) continue;
                st.minK = minK;
                st.baseCost = costArr[lm][rm][minK];
                int maxK_state = minK;
                for (int k = minK + 1; k <= maxK; ++k) {
                    if (costArr[lm][rm][k] < INF)
                        maxK_state = k;
                    else
                        break;
                }
                for (int k = minK + 1; k <= maxK_state; ++k) {
                    st.marg.push_back(costArr[lm][rm][k] - costArr[lm][rm][k - 1]);
                }
            }
        }
    } else {
        int mid = (l + r) / 2;
        Node left = build(l, mid);
        Node right = build(mid + 1, r);
        for (int lm = 0; lm < maskCount; ++lm) {
            for (int rm = 0; rm < maskCount; ++rm) {
                vector<long long> parentCost(maxK + 1, INF);
                for (int rmL = 0; rmL < maskCount; ++rmL) {
                    State &leftSt = left.state[lm][rmL];
                    if (leftSt.minK == -1) continue;
                    for (int lmR = 0; lmR < maskCount; ++lmR) {
                        State &rightSt = right.state[lmR][rm];
                        if (rightSt.minK == -1) continue;
                        if (!compatible[rmL][lmR]) continue;
                        int minK = leftSt.minK + rightSt.minK;
                        long long base = leftSt.baseCost + rightSt.baseCost;
                        const vector<long long> &m1 = leftSt.marg;
                        const vector<long long> &m2 = rightSt.marg;
                        int k = minK;
                        long long cur = base;
                        if (k <= maxK) parentCost[k] = min(parentCost[k], cur);
                        size_t i = 0, j = 0;
                        while (i < m1.size() || j < m2.size()) {
                            long long val;
                            if (i < m1.size() && (j == m2.size() || m1[i] < m2[j])) {
                                val = m1[i++];
                            } else {
                                val = m2[j++];
                            }
                            cur += val;
                            ++k;
                            if (k <= maxK) parentCost[k] = min(parentCost[k], cur);
                        }
                    }
                }
                State &st = node.state[lm][rm];
                int minK = -1;
                for (int k = 0; k <= maxK; ++k) {
                    if (parentCost[k] < INF) {
                        minK = k;
                        break;
                    }
                }
                if (minK == -1) continue;
                st.minK = minK;
                st.baseCost = parentCost[minK];
                int maxK_state = minK;
                for (int k = minK + 1; k <= maxK; ++k) {
                    if (parentCost[k] < INF)
                        maxK_state = k;
                    else
                        break;
                }
                for (int k = minK + 1; k <= maxK_state; ++k) {
                    st.marg.push_back(parentCost[k] - parentCost[k - 1]);
                }
            }
        }
    }
    return node;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> L >> N;
    string s;
    cin >> s;
    vector<long long> c(N);
    for (int i = 0; i < N; ++i) cin >> c[i];

    M = N - L + 1;
    w.assign(M + 1, 0);
    for (int i = 1; i <= M; ++i) {
        long long cost = 0;
        for (int j = 0; j < L; ++j) {
            int pos = i - 1 + j;
            char desired = (j == 0 ? 'M' : 'O');
            if (s[pos] != desired) cost += c[pos];
        }
        w[i] = cost;
    }

    if (M <= 4) {
        int maxK = N / L;
        vector<long long> ans(maxK + 1, INF);
        ans[0] = 0;
        for (int mask = 0; mask < (1 << M); ++mask) {
            vector<int> selected;
            long long cost = 0;
            for (int i = 0; i < M; ++i) {
                if (mask & (1 << i)) {
                    selected.push_back(i + 1);
                    cost += w[i + 1];
                }
            }
            bool valid = true;
            for (size_t a = 0; a < selected.size(); ++a) {
                for (size_t b = a + 1; b < selected.size(); ++b) {
                    if (selected[b] - selected[a] < L) {
                        valid = false;
                        break;
                    }
                }
                if (!valid) break;
            }
            if (!valid) continue;
            int k = selected.size();
            if (k <= maxK) ans[k] = min(ans[k], cost);
        }
        for (int k = 1; k <= maxK; ++k) {
            cout << ans[k] << "\n";
        }
        return 0;
    }

    K = L - 1;
    maskCount = 1 << K;
    compatible.assign(maskCount, vector<bool>(maskCount, true));
    for (int a = 0; a < maskCount; ++a) {
        for (int b = 0; b < maskCount; ++b) {
            bool conflict = false;
            for (int i = 0; i < K; ++i) {
                if (a & (1 << i)) {
                    for (int j = 0; j < K; ++j) {
                        if (b & (1 << j)) {
                            if (j <= i) {
                                conflict = true;
                                break;
                            }
                        }
                    }
                }
                if (conflict) break;
            }
            compatible[a][b] = !conflict;
        }
    }

    Node root = build(1, M);
    int maxK_root = (M + L - 1) / L;
    vector<long long> ans(maxK_root + 1, INF);
    ans[0] = 0;
    for (int lm = 0; lm < maskCount; ++lm) {
        for (int rm = 0; rm < maskCount; ++rm) {
            State &st = root.state[lm][rm];
            if (st.minK == -1) continue;
            long long cur = st.baseCost;
            int k = st.minK;
            if (k <= maxK_root) ans[k] = min(ans[k], cur);
            for (long long diff : st.marg) {
                cur += diff;
                ++k;
                if (k <= maxK_root) ans[k] = min(ans[k], cur);
            }
        }
    }

    for (int k = 1; k <= maxK_root; ++k) {
        cout << ans[k] << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
static constexpr ll INF = (1LL << 62);

/*
A convex sequence is stored as:
  value(lo) = base
  value(k+1) - value(k) = diff[k - lo]

The differences are nondecreasing.
*/
struct Convex {
    int lo = 0;
    int hi = -1;
    ll base = 0;
    vector<ll> diff;

    bool valid() const {
        return hi >= lo;
    }

    static Convex fromDense(vector<ll> values) {
        Convex result;

        int lo = -1, hi = -1;
        for (int i = 0; i < (int)values.size(); ++i) {
            if (values[i] != INF) {
                if (lo == -1) lo = i;
                hi = i;
            }
        }

        if (lo == -1) return result;

        ll base = values[lo];
        int length = hi - lo;

        // Convert costs into successive differences, reusing the allocation.
        ll previous = base;
        for (int i = 0; i < length; ++i) {
            ll current = values[lo + i + 1];
            values[i] = current - previous;
            previous = current;
        }
        values.resize(length);

        result.lo = lo;
        result.hi = hi;
        result.base = base;
        result.diff = std::move(values);
        return result;
    }
};

template<int L>
class Solver {
public:
    using Matrix = array<Convex, L * L>;

    const vector<ll>& weight;

    explicit Solver(const vector<ll>& weight) : weight(weight) {}

    Matrix makeLeaf(int left, int right) const {
        int length = right - left + 1;
        int maskCount = 1 << length;

        array<ll, 32> maskCost{};
        array<int, 32> maskCountSelected{};
        array<int, 32> firstSelected{};
        array<int, 32> lastSelected{};
        array<bool, 32> maskValid{};

        for (int mask = 0; mask < maskCount; ++mask) {
            bool good = true;
            int count = 0;
            int first = -1;
            int last = -1;
            int previous = -100;
            ll cost = 0;

            for (int j = 0; j < length; ++j) {
                if (mask & (1 << j)) {
                    if (previous != -100 && j - previous < L) {
                        good = false;
                    }
                    if (first == -1) first = j;
                    last = j;
                    previous = j;
                    ++count;
                    cost += weight[left + j];
                }
            }

            maskCost[mask] = cost;
            maskCountSelected[mask] = count;
            firstSelected[mask] = first;
            lastSelected[mask] = last;
            maskValid[mask] = good;
        }

        Matrix result;

        for (int incoming = 0; incoming < L; ++incoming) {
            for (int outgoing = 0; outgoing < L; ++outgoing) {
                vector<ll> values(length + 1, INF);

                for (int mask = 0; mask < maskCount; ++mask) {
                    if (!maskValid[mask]) continue;

                    int count = maskCountSelected[mask];

                    // The incoming cooldown blocks the first 'incoming' starts.
                    if (count > 0 && firstSelected[mask] < incoming) continue;

                    int state = 0;
                    if (count > 0) {
                        state = max(0, lastSelected[mask] + L - length);
                    }

                    if (state == outgoing) {
                        values[count] = min(values[count], maskCost[mask]);
                    }
                }

                result[incoming * L + outgoing] =
                    Convex::fromDense(std::move(values));
            }
        }

        return result;
    }

    Matrix combine(const Matrix& left, const Matrix& right) const {
        Matrix result;

        for (int incoming = 0; incoming < L; ++incoming) {
            for (int outgoing = 0; outgoing < L; ++outgoing) {
                int minimumCount = INT_MAX;
                int maximumCount = -1;

                for (int middle = 0; middle < L; ++middle) {
                    const Convex& a = left[incoming * L + middle];
                    const Convex& b = right[middle * L + outgoing];

                    if (!a.valid() || !b.valid()) continue;

                    minimumCount = min(minimumCount, a.lo + b.lo);
                    maximumCount = max(maximumCount, a.hi + b.hi);
                }

                if (maximumCount == -1) continue;

                vector<ll> best(maximumCount - minimumCount + 1, INF);

                for (int middle = 0; middle < L; ++middle) {
                    const Convex& a = left[incoming * L + middle];
                    const Convex& b = right[middle * L + outgoing];

                    if (!a.valid() || !b.valid()) continue;

                    int convolutionLo = a.lo + b.lo;
                    int convolutionHi = a.hi + b.hi;

                    /*
                    Min-plus convolution of two convex sequences:
                    their nondecreasing difference lists are merged.
                    */
                    size_t ia = 0, ib = 0;
                    ll current = a.base + b.base;
                    int position = convolutionLo - minimumCount;

                    best[position] = min(best[position], current);

                    while (ia < a.diff.size() || ib < b.diff.size()) {
                        ll step;

                        if (ib == b.diff.size() ||
                            (ia < a.diff.size() && a.diff[ia] <= b.diff[ib])) {
                            step = a.diff[ia++];
                        } else {
                            step = b.diff[ib++];
                        }

                        current += step;
                        ++position;
                        best[position] = min(best[position], current);
                    }
                }

                result[incoming * L + outgoing] =
                    Convex::fromDense(std::move(best));
            }
        }

        return result;
    }

    Matrix solve(int left, int right) const {
        int length = right - left + 1;

        // Every leaf has length at least L and less than 2L.
        if (length < 2 * L) {
            return makeLeaf(left, right);
        }

        int middle = left + length / 2 - 1;
        Matrix a = solve(left, middle);
        Matrix b = solve(middle + 1, right);
        return combine(a, b);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, N;
    cin >> L >> N;

    string s;
    cin >> s;

    vector<ll> cost(N);
    for (ll& x : cost) cin >> x;

    if (L == 1) {
        vector<ll> makeM(N);
        for (int i = 0; i < N; ++i) {
            makeM[i] = (s[i] == 'M' ? 0 : cost[i]);
        }
        sort(makeM.begin(), makeM.end());

        ll answer = 0;
        for (ll x : makeM) {
            answer += x;
            cout << answer << '\n';
        }
        return 0;
    }

    vector<ll> weight;
    weight.reserve(N - L + 1);

    for (int i = 0; i + L <= N; ++i) {
        ll current = 0;
        for (int j = 0; j < L; ++j) {
            char desired = (j == 0 ? 'M' : 'O');
            if (s[i + j] != desired) {
                current += cost[i + j];
            }
        }
        weight.push_back(current);
    }

    int maximumMoos = N / L;

    if (maximumMoos == 1) {
        cout << *min_element(weight.begin(), weight.end()) << '\n';
        return 0;
    }

    if (L == 2) {
        Solver<2> solver(weight);
        auto matrix = solver.solve(0, (int)weight.size() - 1);

        vector<ll> answer(maximumMoos + 1, INF);

        // The final cooldown may be anything, so minimize over final states.
        for (int outgoing = 0; outgoing < 2; ++outgoing) {
            const Convex& sequence = matrix[outgoing];
            if (!sequence.valid()) continue;

            ll current = sequence.base;
            answer[sequence.lo] = min(answer[sequence.lo], current);

            for (size_t i = 0; i < sequence.diff.size(); ++i) {
                current += sequence.diff[i];
                int count = sequence.lo + (int)i + 1;
                answer[count] = min(answer[count], current);
            }
        }

        for (int k = 1; k <= maximumMoos; ++k) {
            cout << answer[k] << '\n';
        }
    } else {
        Solver<3> solver(weight);
        auto matrix = solver.solve(0, (int)weight.size() - 1);

        vector<ll> answer(maximumMoos + 1, INF);

        for (int outgoing = 0; outgoing < 3; ++outgoing) {
            const Convex& sequence = matrix[outgoing];
            if (!sequence.valid()) continue;

            ll current = sequence.base;
            answer[sequence.lo] = min(answer[sequence.lo], current);

            for (size_t i = 0; i < sequence.diff.size(); ++i) {
                current += sequence.diff[i];
                int count = sequence.lo + (int)i + 1;
                answer[count] = min(answer[count], current);
            }
        }

        for (int k = 1; k <= maximumMoos; ++k) {
            cout << answer[k] << '\n';
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

static constexpr ll INF = numeric_limits<ll>::max() / 4;
static constexpr int INT_INF = 1'000'000'000;

// Stores values for consecutive feasible cardinalities.
// val[t] is the minimum cost for choosing lo + t intervals.
struct Poly {
    int lo = 0;
    vector<ll> val;
};

template <int L>
struct Matrix {
    array<Poly, L> p;
};

// Transition for one possible starting position.
//
// State d means that the next d starting positions are forbidden.
// State 0 can either skip the position or choose it.
// Choosing it forbids the next L-1 starting positions.
template <int L>
Matrix<L> make_leaf(ll weight) {
    static_assert(L >= 2);

    Matrix<L> res;

    // Skip.
    res.p[0][0].lo = 0;
    res.p[0][0].val = {0};

    // Choose this starting position.
    res.p[0][L - 1].lo = 1;
    res.p[0][L - 1].val = {weight};

    // A positive blocked state must skip the current position.
    for (int d = 1; d < L; ++d) {
        res.p[d][d - 1].lo = 0;
        res.p[d][d - 1].val = {0};
    }

    return res;
}

// Min-plus polynomial matrix multiplication.
//
// Every coefficient sequence of a matrix entry is convex, so convolution
// of two such sequences is computed by merging their marginal costs.
template <int L>
Matrix<L> multiply(const Matrix<L>& A, const Matrix<L>& B) {
    Matrix<L> C;

    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < L; ++j) {
            int low = INT_INF;
            int high = -1;

            for (int t = 0; t < L; ++t) {
                const Poly& x = A.p[i][t];
                const Poly& y = B.p[t][j];

                if (x.val.empty() || y.val.empty()) continue;

                int xHigh = x.lo + (int)x.val.size() - 1;
                int yHigh = y.lo + (int)y.val.size() - 1;

                low = min(low, x.lo + y.lo);
                high = max(high, xHigh + yHigh);
            }

            if (high == -1) continue;

            Poly& z = C.p[i][j];
            z.lo = low;
            z.val.assign(high - low + 1, INF);

            for (int t = 0; t < L; ++t) {
                const Poly& x = A.p[i][t];
                const Poly& y = B.p[t][j];

                if (x.val.empty() || y.val.empty()) continue;

                int nx = (int)x.val.size();
                int ny = (int)y.val.size();
                int base = x.lo + y.lo - z.lo;

                int ix = 0, iy = 0;
                ll current = x.val[0] + y.val[0];

                while (true) {
                    int index = base + ix + iy;
                    z.val[index] = min(z.val[index], current);

                    if (ix + 1 == nx && iy + 1 == ny) break;

                    ll dx = (ix + 1 < nx)
                                ? x.val[ix + 1] - x.val[ix]
                                : INF;
                    ll dy = (iy + 1 < ny)
                                ? y.val[iy + 1] - y.val[iy]
                                : INF;

                    if (dx <= dy) {
                        current += dx;
                        ++ix;
                    } else {
                        current += dy;
                        ++iy;
                    }
                }
            }
        }
    }

    return C;
}

template <int L>
Matrix<L> build_product(const vector<ll>& weights, int left, int right) {
    if (right - left == 1) {
        return make_leaf<L>(weights[left]);
    }

    int middle = (left + right) / 2;
    Matrix<L> A = build_product<L>(weights, left, middle);
    Matrix<L> B = build_product<L>(weights, middle, right);
    return multiply<L>(A, B);
}

template <int L>
vector<ll> get_answers(const vector<ll>& weights, int N) {
    Matrix<L> root = build_product<L>(weights, 0, (int)weights.size());

    int maximum = N / L;
    vector<ll> answer(maximum + 1, INF);

    // Any final blocked state is allowed.
    for (int state = 0; state < L; ++state) {
        const Poly& p = root.p[0][state];
        for (int i = 0; i < (int)p.val.size(); ++i) {
            int k = p.lo + i;
            if (k <= maximum) {
                answer[k] = min(answer[k], p.val[i]);
            }
        }
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, N;
    cin >> L >> N;

    string s;
    cin >> s;

    vector<ll> cost(N);
    for (ll& x : cost) cin >> x;

    if (L == 1) {
        // A length-1 moo is simply an M.
        vector<ll> weights;
        weights.reserve(N);

        for (int i = 0; i < N; ++i) {
            weights.push_back(s[i] == 'O' ? cost[i] : 0);
        }

        sort(weights.begin(), weights.end());

        ll sum = 0;
        for (ll w : weights) {
            sum += w;
            cout << sum << '\n';
        }
        return 0;
    }

    int candidates = N - L + 1;
    vector<ll> weights(candidates, 0);

    for (int i = 0; i < candidates; ++i) {
        // The first character of the moo must be M.
        if (s[i] == 'O') weights[i] += cost[i];

        // The remaining characters must be O.
        for (int j = 1; j < L; ++j) {
            if (s[i + j] == 'M') weights[i] += cost[i + j];
        }
    }

    vector<ll> answer;
    if (L == 2) {
        answer = get_answers<2>(weights, N);
    } else {
        answer = get_answers<3>(weights, N);
    }

    for (int k = 1; k <= N / L; ++k) {
        cout << answer[k] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
static constexpr ll INF = (1LL << 62);
static constexpr int BASE = 32;

int patternLen;
vector<ll> windowCost;

/*
For a fixed boundary-state problem, val[k] is the minimum cost using
exactly lo + k selected windows.

Every such sequence is discretely convex, so its consecutive differences
are nondecreasing.
*/
struct Poly {
    int lo = 0;
    vector<ll> val;

    bool empty() const {
        return val.empty();
    }

    int hi() const {
        return lo + (int)val.size() - 1;
    }
};

struct Matrix {
    int s;
    array<array<Poly, 3>, 3> p;

    explicit Matrix(int s_ = 0) : s(s_) {}
};

/*
Min-plus convolution of two convex sequences.

If the differences of A and B are sorted, the differences of their
min-plus convolution are obtained by merging those two sorted lists.
*/
Poly minPlusConvolution(const Poly &A, const Poly &B) {
    int na = (int)A.val.size();
    int nb = (int)B.val.size();

    Poly C;
    C.lo = A.lo + B.lo;
    C.val.resize(na + nb - 1);

    if (na == 1) {
        for (int j = 0; j < nb; ++j) {
            C.val[j] = A.val[0] + B.val[j];
        }
        return C;
    }

    if (nb == 1) {
        for (int i = 0; i < na; ++i) {
            C.val[i] = A.val[i] + B.val[0];
        }
        return C;
    }

    C.val[0] = A.val[0] + B.val[0];

    int ia = 1, ib = 1, k = 1;
    while (k < (int)C.val.size()) {
        ll da = (ia < na ? A.val[ia] - A.val[ia - 1] : INF);
        ll db = (ib < nb ? B.val[ib] - B.val[ib - 1] : INF);

        if (da <= db) {
            C.val[k] = C.val[k - 1] + da;
            ++ia;
        } else {
            C.val[k] = C.val[k - 1] + db;
            ++ib;
        }
        ++k;
    }

    return C;
}

/*
Tropical matrix multiplication.

C[i][j] = min_h A[i][h] (*) B[h][j],
where (*) is min-plus convolution.
*/
Matrix multiply(const Matrix &A, const Matrix &B) {
    Matrix C(A.s);

    for (int i = 0; i < A.s; ++i) {
        for (int j = 0; j < A.s; ++j) {
            int low = INT_MAX;
            int high = INT_MIN;

            for (int h = 0; h < A.s; ++h) {
                if (A.p[i][h].empty() || B.p[h][j].empty()) continue;

                low = min(low, A.p[i][h].lo + B.p[h][j].lo);
                high = max(high, A.p[i][h].hi() + B.p[h][j].hi());
            }

            if (low == INT_MAX) continue;

            vector<ll> result(high - low + 1, INF);

            for (int h = 0; h < A.s; ++h) {
                if (A.p[i][h].empty() || B.p[h][j].empty()) continue;

                Poly q = minPlusConvolution(A.p[i][h], B.p[h][j]);
                int offset = q.lo - low;

                for (int x = 0; x < (int)q.val.size(); ++x) {
                    ll &dest = result[offset + x];
                    if (q.val[x] < dest) dest = q.val[x];
                }
            }

            int first = 0;
            while (first < (int)result.size() && result[first] == INF) {
                ++first;
            }
            if (first == (int)result.size()) continue;

            int last = (int)result.size() - 1;
            while (last >= first && result[last] == INF) {
                --last;
            }

            size_t newSize = (size_t)(last - first + 1);
            result.erase(result.begin(), result.begin() + first);
            result.resize(newSize);

            C.p[i][j].lo = low + first;
            C.p[i][j].val = move(result);
        }
    }

    return C;
}

/*
Build the transition product for a small block directly.

State q means that the next q candidate starting positions are blocked.
From state 0 we may skip or select the current window.
From state q > 0 we must skip, and the state decreases by one.
*/
Matrix buildBlock(int l, int r) {
    Matrix result(patternLen);

    static constexpr int MAXC = BASE + 2;
    ll buffer1[3][MAXC];
    ll buffer2[3][MAXC];

    ll (*dp)[MAXC] = buffer1;
    ll (*ndp)[MAXC] = buffer2;

    for (int initial = 0; initial < patternLen; ++initial) {
        for (int q = 0; q < patternLen; ++q) {
            fill(dp[q], dp[q] + MAXC, INF);
        }
        dp[initial][0] = 0;

        for (int pos = l; pos <= r; ++pos) {
            for (int q = 0; q < patternLen; ++q) {
                fill(ndp[q], ndp[q] + MAXC, INF);
            }

            for (int q = 0; q < patternLen; ++q) {
                int nextState = (q == 0 ? 0 : q - 1);

                for (int cnt = 0; cnt <= BASE; ++cnt) {
                    if (dp[q][cnt] == INF) continue;

                    ll &skipDest = ndp[nextState][cnt];
                    skipDest = min(skipDest, dp[q][cnt]);

                    if (q == 0) {
                        ll &selectDest = ndp[patternLen - 1][cnt + 1];
                        selectDest = min(selectDest, dp[q][cnt] + windowCost[pos]);
                    }
                }
            }

            swap(dp, ndp);
        }

        for (int q = 0; q < patternLen; ++q) {
            int first = -1, last = -1;
            for (int cnt = 0; cnt <= BASE; ++cnt) {
                if (dp[q][cnt] != INF) {
                    if (first == -1) first = cnt;
                    last = cnt;
                }
            }

            if (first == -1) continue;

            result.p[initial][q].lo = first;
            result.p[initial][q].val.assign(
                dp[q] + first,
                dp[q] + last + 1
            );
        }
    }

    return result;
}

Matrix solve(int l, int r) {
    if (r - l + 1 <= BASE) {
        return buildBlock(l, r);
    }

    int mid = (l + r) / 2;
    Matrix left = solve(l, mid);
    Matrix right = solve(mid + 1, r);
    return multiply(left, right);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> patternLen >> N;

    string s;
    cin >> s;

    vector<ll> costs(N);
    for (ll &x : costs) cin >> x;

    if (patternLen == 1) {
        vector<ll> makeM;
        makeM.reserve(N);

        for (int i = 0; i < N; ++i) {
            makeM.push_back(s[i] == 'O' ? costs[i] : 0);
        }

        sort(makeM.begin(), makeM.end());

        ll sum = 0;
        for (int k = 1; k <= N; ++k) {
            sum += makeM[k - 1];
            cout << sum << '\n';
        }
        return 0;
    }

    int M = N - patternLen + 1;
    windowCost.assign(M, 0);

    for (int i = 0; i < M; ++i) {
        ll cur = 0;

        if (s[i] == 'O') cur += costs[i];

        for (int j = 1; j < patternLen; ++j) {
            if (s[i + j] == 'M') cur += costs[i + j];
        }

        windowCost[i] = cur;
    }

    Matrix result = solve(0, M - 1);

    int maxK = N / patternLen;
    vector<ll> answer(maxK + 1, INF);

    // Any final cooldown state is acceptable.
    for (int state = 0; state < patternLen; ++state) {
        const Poly &p = result.p[0][state];
        for (int x = 0; x < (int)p.val.size(); ++x) {
            int k = p.lo + x;
            if (k <= maxK) {
                answer[k] = min(answer[k], p.val[x]);
            }
        }
    }

    for (int k = 1; k <= maxK; ++k) {
        cout << answer[k] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int N, M;
vector<long long> factv, invfactv, pow2v;
vector<int> wantPos, wantVal;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long comb(int n, int k) {
    if (k < 0 || k > n || n < 0) return 0;
    return factv[n] * invfactv[k] % MOD * invfactv[n - k] % MOD;
}

bool fixedOK(int v, int pos) {
    if (pos < 0 || pos >= N) return false;
    if (wantVal[v] != -1 && wantVal[v] != pos) return false;
    if (wantPos[pos] != -1 && wantPos[pos] != v) return false;
    return true;
}

// type 0: [q, M+q], type 1: [M+q, q].
bool tokenOK(int q, int type, int start) {
    if (type == 0) {
        return fixedOK(q, start) && fixedOK(M + q, start + 1);
    } else {
        return fixedOK(M + q, start) && fixedOK(q, start + 1);
    }
}

struct Event {
    int t, q;
};

struct Layout {
    int kind;       // 0: generic two-sided layout, 1: form with two F-blocks sides
    int leftBase;
    int rightEnd;
    int rightBase;
    int selectedType;
    int unselectedType;
};

int placementStart(const Layout& lay, bool selected, int c, int t) {
    if (lay.kind == 0) {
        if (selected) return lay.leftBase + 2 * c;
        return lay.rightEnd - 2 * (t - c + 1);
    } else {
        if (selected) return 2 * c;
        return lay.rightBase + 2 * (t - c);
    }
}

bool getCandidate(const Layout& lay, bool selected, int q, int t, int& cOut) {
    int type = selected ? lay.selectedType : lay.unselectedType;
    int start = -1;

    if (wantVal[q] != -1) {
        int offset = (type == 0 ? 0 : 1);
        start = wantVal[q] - offset;
    } else if (wantVal[M + q] != -1) {
        int offset = (type == 0 ? 1 : 0);
        start = wantVal[M + q] - offset;
    } else {
        return false;
    }

    int c = -1;
    if (lay.kind == 0) {
        if (selected) {
            int diff = start - lay.leftBase;
            if (diff < 0 || (diff & 1)) return false;
            c = diff / 2;
        } else {
            int diff = lay.rightEnd - start;
            if (diff <= 0 || (diff & 1)) return false;
            c = t + 1 - diff / 2;
        }
    } else {
        if (selected) {
            if (start < 0 || (start & 1)) return false;
            c = start / 2;
        } else {
            int diff = start - lay.rightBase;
            if (diff < 0 || (diff & 1)) return false;
            c = t - diff / 2;
        }
    }

    if (c < 0 || c > t) return false;
    int actualStart = placementStart(lay, selected, c, t);
    if (actualStart != start) return false;
    if (!tokenOK(q, type, start)) return false;

    cOut = c;
    return true;
}

long long countAssignments(int h, const vector<Event>& events,
                           int totalRequired, const Layout& lay) {
    if (totalRequired > h) return 0;

    vector<pair<int, long long>> states;
    states.push_back({0, 1});
    int processed = 0;

    for (const Event& ev : events) {
        int gap = ev.t - processed;
        vector<pair<int, long long>> nextStates;

        for (int sel = 0; sel <= 1; ++sel) {
            int c;
            if (!getCandidate(lay, sel, ev.q, ev.t, c)) continue;

            long long ways = 0;
            for (auto [oldC, oldWays] : states) {
                ways = (ways + oldWays * comb(gap, c - oldC)) % MOD;
            }
            if (!ways) continue;

            int newC = c + sel;
            bool merged = false;
            for (auto& entry : nextStates) {
                if (entry.first == newC) {
                    entry.second = (entry.second + ways) % MOD;
                    merged = true;
                    break;
                }
            }
            if (!merged) nextStates.push_back({newC, ways});
        }

        if (nextStates.empty()) return 0;
        states.swap(nextStates);
        processed = ev.t + 1;
    }

    int remaining = h - processed;
    long long answer = 0;

    if (totalRequired == -1) {
        for (auto [c, ways] : states) {
            answer = (answer + ways * pow2v[remaining]) % MOD;
        }
    } else {
        for (auto [c, ways] : states) {
            answer = (answer + ways * comb(remaining, totalRequired - c)) % MOD;
        }
    }
    return answer;
}

vector<Event> makeEvents(int lo, int hi, int mode) {
    vector<Event> events;
    if (lo > hi) return events;

    if (mode == 0) {
        for (int q = hi; q >= lo; --q) {
            if (wantVal[q] != -1 || wantVal[M + q] != -1) {
                events.push_back({hi - q, q});
            }
        }
    } else {
        for (int q = lo; q <= hi; ++q) {
            if (wantVal[q] != -1 || wantVal[M + q] != -1) {
                events.push_back({q - lo, q});
            }
        }
    }
    return events;
}

// F/R two-sided layout with one variable-position middle token.
long long genericCount(int lo, int hi, int leftBase, int rightEnd,
                       int middleValue, int mode) {
    int h = max(0, hi - lo + 1);
    vector<Event> events = makeEvents(lo, hi, mode);

    int totalRequired = -1;
    if (wantVal[middleValue] != -1) {
        int pos = wantVal[middleValue];
        int diff = pos - leftBase;
        if (diff < 0 || (diff & 1)) return 0;
        totalRequired = diff / 2;
        if (totalRequired < 0 || totalRequired > h) return 0;
        if (!fixedOK(middleValue, pos)) return 0;
    }

    Layout lay;
    lay.kind = 0;
    lay.leftBase = leftBase;
    lay.rightEnd = rightEnd;
    lay.rightBase = 0;

    if (mode == 0) {
        lay.selectedType = 0;
        lay.unselectedType = 1;
    } else {
        lay.selectedType = 1;
        lay.unselectedType = 0;
    }

    return countAssignments(h, events, totalRequired, lay);
}

long long countCanonicalOdd() {
    int h = M - 1;
    long long answer = 0;

    // [M,0], R(Q) increasing, N-1, F(S) decreasing.
    if (fixedOK(M, 0) && fixedOK(0, 1)) {
        answer += genericCount(1, M - 1, 2, N, N - 1, 1);
    }

    // F(P) decreasing, [0,M,N-1], F(S) decreasing.
    vector<Event> middleEvents = makeEvents(1, M - 1, 0);
    for (int p = 0; p <= h; ++p) {
        int a = 2 * p;
        if (!fixedOK(0, a) || !fixedOK(M, a + 1) ||
            !fixedOK(N - 1, a + 2)) {
            continue;
        }

        Layout lay;
        lay.kind = 1;
        lay.leftBase = 0;
        lay.rightEnd = 0;
        lay.rightBase = 2 * p + 3;
        lay.selectedType = 0;
        lay.unselectedType = 0;

        answer += countAssignments(h, middleEvents, p, lay);
        if (answer >= MOD) answer -= MOD;
    }

    // F(P) decreasing, 0, R(Q) increasing, [N-1,M].
    if (fixedOK(N - 1, N - 2) && fixedOK(M, N - 1)) {
        answer += genericCount(1, M - 1, 0, N - 2, 0, 0);
    }
    answer %= MOD;

    // Defective forms, containing [N-1,M,0].
    for (int d = 1; d <= M - 1; ++d) {
        int highCount = M - 1 - d;
        int posB = 2 * highCount + 1;

        if (!fixedOK(N - 1, posB) ||
            !fixedOK(M, posB + 1) ||
            !fixedOK(0, posB + 2)) {
            continue;
        }

        long long highWays = genericCount(
            d + 1, M - 1, 0, posB, d, 0
        );
        if (!highWays) continue;

        long long lowWays = genericCount(
            1, d - 1, posB + 3, N, M + d, 1
        );

        answer = (answer + highWays * lowWays) % MOD;
    }

    return answer;
}

long long countCanonicalEven() {
    vector<int> seq;
    seq.reserve(N);
    for (int k = 0; k < M; ++k) {
        seq.push_back(M - 1 - k);
        seq.push_back(2 * M - 1 - k);
    }

    for (int i = 0; i < N; ++i) {
        if (wantPos[i] != -1 && wantPos[i] != seq[i]) return 0;
    }
    return 1;
}

long long solveCanonical(const vector<pair<int, int>>& constraints, bool reversed) {
    wantPos.assign(N, -1);
    wantVal.assign(N, -1);

    for (auto [i, j] : constraints) {
        int pos = reversed ? N - 1 - i : i;
        wantPos[pos] = j;
        wantVal[j] = pos;
    }

    if (N % 2 == 0) return countCanonicalEven();
    return countCanonicalOdd();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T >> N;
    M = N / 2;

    factv.assign(N + 1, 1);
    for (int i = 1; i <= N; ++i) {
        factv[i] = factv[i - 1] * i % MOD;
    }
    invfactv.assign(N + 1, 1);
    invfactv[N] = modpow(factv[N], MOD - 2);
    for (int i = N; i >= 1; --i) {
        invfactv[i - 1] = invfactv[i] * i % MOD;
    }

    pow2v.assign(N + 1, 1);
    for (int i = 1; i <= N; ++i) {
        pow2v[i] = pow2v[i - 1] * 2 % MOD;
    }

    while (T--) {
        int K;
        cin >> K;
        vector<pair<int, int>> constraints(K);
        for (int i = 0; i < K; ++i) {
            cin >> constraints[i].first >> constraints[i].second;
        }

        long long answer = solveCanonical(constraints, false);
        answer += solveCanonical(constraints, true);
        answer %= MOD;
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
static const int MOD = 1000000007;

int addmod(int a, int b) {
    int s = a + b;
    if (s >= MOD) s -= MOD;
    return s;
}

struct Option {
    int col;
    int req;
};

struct StageOptions {
    int t;
    int n;
    array<Option, 2> op;
};

struct Spec {
    array<int, 2> val;
    array<int, 2> offset;
    int base;
    int step;
    int maxReq;
};

struct Solver {
    int N, m, u;
    vector<int> valPos;

    int binom(int n, int k, const vector<int64>& fact, const vector<int64>& invfact) const {
        if (k < 0 || k > n || n < 0) return 0;
        return int(fact[n] * invfact[k] % MOD * invfact[n - k] % MOD);
    }

    int countChoices(int stages, const vector<StageOptions>& cs, int total,
                     const vector<int64>& fact, const vector<int64>& invfact,
                     const vector<int>& pow2) const {
        if (cs.empty()) {
            if (total == -1) return pow2[stages];
            return binom(stages, total, fact, invfact);
        }

        array<int64, 2> dp{}, ndp{};

        const StageOptions& first = cs.front();
        for (int i = 0; i < first.n; ++i) {
            dp[i] = binom(first.t, first.op[i].req, fact, invfact);
        }
        int prevN = first.n;
        StageOptions prev = first;

        for (int z = 1; z < (int)cs.size(); ++z) {
            const StageOptions& cur = cs[z];
            ndp = {0, 0};
            int gap = cur.t - prev.t - 1;

            for (int i = 0; i < prevN; ++i) {
                if (!dp[i]) continue;
                int before = prev.op[i].req + (prev.op[i].col == 1);
                for (int j = 0; j < cur.n; ++j) {
                    int need = cur.op[j].req - before;
                    int ways = binom(gap, need, fact, invfact);
                    ndp[j] = (ndp[j] + dp[i] * ways) % MOD;
                }
            }

            dp = ndp;
            prevN = cur.n;
            prev = cur;
        }

        int suffix = stages - 1 - prev.t;
        int64 ans = 0;
        for (int i = 0; i < prevN; ++i) {
            if (!dp[i]) continue;
            int before = prev.op[i].req + (prev.op[i].col == 1);
            if (total == -1) {
                ans = (ans + dp[i] * pow2[suffix]) % MOD;
            } else {
                int need = total - before;
                ans = (ans + dp[i] * binom(suffix, need, fact, invfact)) % MOD;
            }
        }
        return int(ans);
    }

    bool addStage(vector<StageOptions>& cs, int t, int off,
                  const array<Spec, 2>& spec) const {
        bool constrained = false;
        for (int k = 0; k < 2; ++k) {
            if (valPos[spec[0].val[k]] != -1) constrained = true;
        }
        if (!constrained) return true;

        StageOptions so;
        so.t = t;
        so.n = 0;

        for (int col = 0; col < 2; ++col) {
            bool ok = true;
            int requirement = -1;

            for (int k = 0; k < 2 && ok; ++k) {
                int value = spec[col].val[k];
                int p = valPos[value];
                if (p == -1) continue;

                int64 local = (int64)p - off;
                int64 start = local - spec[col].offset[k];
                int64 diff = start - spec[col].base;
                int step = spec[col].step;

                if (diff % step != 0) {
                    ok = false;
                    break;
                }

                int64 req = diff / step;
                if (req < 0 || req > spec[col].maxReq) {
                    ok = false;
                    break;
                }

                if (requirement != -1 && requirement != req) {
                    ok = false;
                    break;
                }
                requirement = int(req);
            }

            if (ok) {
                so.op[so.n++] = {col, requirement};
            }
        }

        if (so.n == 0) return false;
        cs.push_back(so);
        return true;
    }

    int fixedAt(int value, int position) const {
        return valPos[value] == -1 || valPos[value] == position;
    }

    int countA(int s, int off,
               const vector<int64>& fact, const vector<int64>& invfact,
               const vector<int>& pow2) const {
        int stages = s - 1;

        if (!fixedAt(0, off)) return 0;

        int total = -1;
        int markValue = m + s;
        if (valPos[markValue] != -1) {
            int local = valPos[markValue] - off;
            if (local < 1 || (local - 1) % 2 != 0) return 0;
            total = (local - 1) / 2;
            if (total < 0 || total > stages) return 0;
        }

        vector<StageOptions> cs;
        for (int r = 1; r <= stages; ++r) {
            int L = r;
            int H = m + r;

            array<Spec, 2> spec;

            // Color 0: L, pair (L_r,H_r), start = 2(s-r)+2a.
            spec[0].val = {L, H};
            spec[0].offset = {0, 1};
            spec[0].base = 2 * (s - r);
            spec[0].step = 2;
            spec[0].maxReq = r - 1;

            // Color 1: R, pair (H_r,L_r), start = 1+2a.
            spec[1].val = {H, L};
            spec[1].offset = {0, 1};
            spec[1].base = 1;
            spec[1].step = 2;
            spec[1].maxReq = r - 1;

            if (!addStage(cs, r - 1, off, spec)) return 0;
        }

        return countChoices(stages, cs, total, fact, invfact, pow2);
    }

    int countB(const vector<int64>& fact, const vector<int64>& invfact,
               const vector<int>& pow2) const {
        int stages = m - 1;

        if (!fixedAt(2 * m, 2 * m - 1)) return 0;

        int total = -1;
        if (valPos[0] != -1) {
            int local = valPos[0];
            if (local < 0 || local % 2 != 0) return 0;
            total = local / 2;
            if (total < 0 || total > stages) return 0;
        }

        vector<StageOptions> cs;
        for (int t = 0; t < stages; ++t) {
            int r = stages - t;
            int L = r;
            int H = m + r;

            array<Spec, 2> spec;

            // Color 0: R, pair (H_r,L_r), start = 2r-1+2x.
            spec[0].val = {H, L};
            spec[0].offset = {0, 1};
            spec[0].base = 2 * r - 1;
            spec[0].step = 2;
            spec[0].maxReq = stages - r;

            // Color 1: D, pair (L_r,H_r), start = 2x.
            spec[1].val = {L, H};
            spec[1].offset = {0, 1};
            spec[1].base = 0;
            spec[1].step = 2;
            spec[1].maxReq = stages - r;

            if (!addStage(cs, t, 0, spec)) return 0;
        }

        return countChoices(stages, cs, total, fact, invfact, pow2);
    }

    int countQ0(int T, const vector<int64>& fact, const vector<int64>& invfact,
                const vector<int>& pow2) const {
        if (!fixedAt(0, 2 * T)) return 0;
        if (!fixedAt(m, 2 * T + 1)) return 0;
        if (!fixedAt(2 * m, 2 * T + 2)) return 0;

        vector<StageOptions> cs;
        for (int r = 1; r <= u; ++r) {
            int L = r;
            int H = m + r;

            array<Spec, 2> spec;

            // Color 0: A, start = 2u-2r+3+2b.
            spec[0].val = {L, H};
            spec[0].offset = {0, 1};
            spec[0].base = 2 * u - 2 * r + 3;
            spec[0].step = 2;
            spec[0].maxReq = r - 1;

            // Color 1: B, start = 2(T-1)-2b.
            spec[1].val = {L, H};
            spec[1].offset = {0, 1};
            spec[1].base = 2 * T - 2;
            spec[1].step = -2;
            spec[1].maxReq = r - 1;

            if (!addStage(cs, r - 1, 0, spec)) return 0;
        }

        return countChoices(u, cs, T, fact, invfact, pow2);
    }

    int countLate(int s, const vector<int64>& fact, const vector<int64>& invfact,
                  const vector<int>& pow2) const {
        int lateStages = u - s;

        int total = -1;
        if (valPos[s] != -1) {
            int p = valPos[s];
            if (p < 0 || p % 2 != 0) return 0;
            total = p / 2;
            if (total < 0 || total > lateStages) return 0;
        }

        vector<StageOptions> cs;
        for (int t = 0; t < lateStages; ++t) {
            int r = u - t;
            int L = r;
            int H = m + r;

            array<Spec, 2> spec;

            // Color 0: A, pair (H_r,L_r).
            spec[0].val = {H, L};
            spec[0].offset = {0, 1};
            spec[0].base = 2 * r - 2 * s - 1;
            spec[0].step = 2;
            spec[0].maxReq = u - r;

            // Color 1: B, pair (L_r,H_r).
            spec[1].val = {L, H};
            spec[1].offset = {0, 1};
            spec[1].base = 0;
            spec[1].step = 2;
            spec[1].maxReq = u - r;

            if (!addStage(cs, t, 0, spec)) return 0;
        }

        return countChoices(lateStages, cs, total, fact, invfact, pow2);
    }

    int run(const vector<int64>& fact, const vector<int64>& invfact,
            const vector<int>& pow2) const {
        int64 ans = 0;

        // Center prepended, base path of type A.
        if (fixedAt(m, 0)) {
            ans += countA(m, 1, fact, invfact, pow2);
        }

        // Center appended, base path of type B.
        if (fixedAt(m, 2 * m)) {
            ans += countB(fact, invfact, pow2);
        }

        // Internal center, orientation 0,center,H_m.
        for (int T = 0; T <= u; ++T) {
            ans += countQ0(T, fact, invfact, pow2);
            if (ans >= MOD) ans -= MOD;
        }

        // Internal center, orientation H_m,center,0.
        for (int s = 1; s <= u; ++s) {
            int v = u - s;
            if (!fixedAt(2 * m, 2 * v + 1)) continue;
            if (!fixedAt(m, 2 * v + 2)) continue;

            int early = countA(s, 2 * v + 3, fact, invfact, pow2);
            if (!early) continue;
            int late = countLate(s, fact, invfact, pow2);
            ans = (ans + (int64)early * late) % MOD;
        }

        return int(ans % MOD);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T, N;
    cin >> T >> N;

    vector<int64> fact(N + 1), invfact(N + 1);
    vector<int> pow2(N + 1);

    fact[0] = 1;
    for (int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;

    auto modpow = [&](int64 a, int e) {
        int64 r = 1;
        while (e) {
            if (e & 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    };

    invfact[N] = modpow(fact[N], MOD - 2);
    for (int i = N; i >= 1; --i) invfact[i - 1] = invfact[i] * i % MOD;

    pow2[0] = 1;
    for (int i = 1; i <= N; ++i) pow2[i] = addmod(pow2[i - 1], pow2[i - 1]);

    while (T--) {
        int K;
        cin >> K;

        vector<pair<int, int>> constraints(K);
        vector<int> valPos(N, -1);

        for (int k = 0; k < K; ++k) {
            int i, j;
            cin >> i >> j;
            constraints[k] = {i, j};
            valPos[j] = i;
        }

        if (N % 2 == 0) {
            int half = N / 2;
            vector<int> p;
            for (int k = 0; k < half; ++k) {
                p.push_back(half + k);
                p.push_back(k);
            }
            vector<int> rev = p;
            reverse(rev.begin(), rev.end());

            int answer = 0;
            for (const vector<int>* q : {&p, &rev}) {
                bool ok = true;
                for (auto [i, j] : constraints) {
                    if ((*q)[i] != j) {
                        ok = false;
                        break;
                    }
                }
                if (ok) answer = addmod(answer, 1);
            }
            cout << answer << '\n';
            continue;
        }

        Solver solver;
        solver.N = N;
        solver.m = N / 2;
        solver.u = solver.m - 1;
        solver.valPos = valPos;

        int answer = solver.run(fact, invfact, pow2);

        vector<int> reversedValPos(N, -1);
        for (int value = 0; value < N; ++value) {
            if (valPos[value] != -1) {
                reversedValPos[value] = N - 1 - valPos[value];
            }
        }
        solver.valPos = move(reversedValPos);

        answer = addmod(answer, solver.run(fact, invfact, pow2));
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;
static const int MAXN = 2000;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long fact[MAXN + 1], invfact[MAXN + 1], pw2[MAXN + 1];

long long C(int n, int r) {
    if (r < 0 || r > n || n < 0) return 0;
    return fact[n] * invfact[r] % MOD * invfact[n - r] % MOD;
}

struct Tok {
    int type; // 0 = low, 1 = high, 2 = middle
    int x;    // low index, or high index
};

struct LC {
    int pos;
    Tok tok;
};

// Number of assignments for a component starting at its minimum low value.
int countS(int n, const vector<LC>& cs) {
    if (n == 1) {
        for (const auto& c : cs) {
            if (c.pos == 0) {
                if (c.tok.type != 0 || c.tok.x != 0) return 0;
            } else if (c.pos == 1) {
                if (c.tok.type != 1 || c.tok.x != 1) return 0;
            } else {
                return 0;
            }
        }
        return 1;
    }

    vector<int> head(n, -1), nxt(cs.size(), -1), peak;

    for (int id = 0; id < (int)cs.size(); ++id) {
        const auto& c = cs[id];
        int k = -1;
        if (c.tok.type == 0) {
            int l = c.tok.x;
            if (l == 0) {
                if (c.pos != 0) return 0;
                continue;
            } else if (l == n - 1) {
                peak.push_back(id);
                continue;
            } else {
                k = l;
            }
        } else if (c.tok.type == 1) {
            int r = c.tok.x;
            if (r >= n - 1) {
                peak.push_back(id);
                continue;
            } else {
                k = r;
            }
        } else {
            return 0;
        }

        if (k < 1 || k > n - 2) return 0;
        nxt[id] = head[k];
        head[k] = id;
    }

    auto matchOrdinary = [&](int k, const LC& c, int pref, int side) {
        int base;
        if (side == 1) {
            base = (c.tok.type == 1 ? 1 : 2);
        } else {
            base = 2 * (n - k) + (c.tok.type == 1 ? 1 : 0);
        }
        return c.pos == base + 2 * pref;
    };

    auto generate = [&](int k, const LC& c, int out[2]) {
        int cnt = 0;
        for (int side = 0; side <= 1; ++side) {
            int base;
            if (side == 1) {
                base = (c.tok.type == 1 ? 1 : 2);
            } else {
                base = 2 * (n - k) + (c.tok.type == 1 ? 1 : 0);
            }
            int dif = c.pos - base;
            if (dif >= 0 && dif % 2 == 0) {
                int pref = dif / 2;
                if (0 <= pref && pref <= k - 1) {
                    out[cnt++] = pref * 2 + side;
                }
            }
        }
        return cnt;
    };

    int prevK = -1, prevN = 0;
    int prevD[4];
    long long prevW[4] = {};

    for (int k = 1; k <= n - 2; ++k) {
        if (head[k] == -1) continue;

        int allowed[4], na = 0;
        int first = head[k];
        na = generate(k, cs[first], allowed);

        for (int id = nxt[first]; id != -1; id = nxt[id]) {
            int filtered[4], nf = 0;
            for (int j = 0; j < na; ++j) {
                int pref = allowed[j] / 2;
                int side = allowed[j] % 2;
                if (matchOrdinary(k, cs[id], pref, side)) {
                    filtered[nf++] = allowed[j];
                }
            }
            na = nf;
            for (int j = 0; j < na; ++j) allowed[j] = filtered[j];
        }
        if (na == 0) return 0;

        int newD[4], newN = 0;
        long long newW[4] = {};

        for (int j = 0; j < na; ++j) {
            int pref = allowed[j] / 2;
            int side = allowed[j] % 2;
            long long ways = 0;

            if (prevK == -1) {
                ways = C(k - 1, pref);
            } else {
                int gap = k - prevK - 1;
                for (int z = 0; z < prevN; ++z) {
                    ways += prevW[z] * C(gap, pref - prevD[z]) % MOD;
                }
                ways %= MOD;
            }

            int after = pref + side;
            int at = -1;
            for (int z = 0; z < newN; ++z) {
                if (newD[z] == after) {
                    at = z;
                    break;
                }
            }
            if (at == -1) {
                at = newN++;
                newD[at] = after;
            }
            newW[at] = (newW[at] + ways) % MOD;
        }

        prevN = newN;
        prevK = k;
        for (int z = 0; z < prevN; ++z) {
            prevD[z] = newD[z];
            prevW[z] = newW[z];
        }
    }

    auto waysWithTotal = [&](int total) -> long long {
        if (prevK == -1) return C(n - 2, total);
        int remaining = n - 2 - prevK;
        long long res = 0;
        for (int z = 0; z < prevN; ++z) {
            res += prevW[z] * C(remaining, total - prevD[z]) % MOD;
        }
        return res % MOD;
    };

    long long answer = 0;

    if (peak.empty()) {
        for (int total = 0; total <= n - 2; ++total) {
            answer += 2 * waysWithTotal(total) % MOD;
        }
        return answer % MOD;
    }

    vector<int> masks(n - 1, 3);

    for (int id : peak) {
        const auto& c = cs[id];
        for (int total = 0; total <= n - 2; ++total) {
            int cur = 0;
            if (c.tok.type == 0) {
                if (c.pos == 2 + 2 * total) cur = 3;
            } else if (c.tok.x == n - 1) {
                if (c.pos == 1 + 2 * total) cur |= 1;
                if (c.pos == 3 + 2 * total) cur |= 2;
            } else {
                if (c.pos == 3 + 2 * total) cur |= 1;
                if (c.pos == 1 + 2 * total) cur |= 2;
            }
            masks[total] &= cur;
        }
    }

    for (int total = 0; total <= n - 2; ++total) {
        if (masks[total]) {
            int cnt = (masks[total] & 1) + ((masks[total] >> 1) & 1);
            answer += waysWithTotal(total) * cnt % MOD;
        }
    }
    return answer % MOD;
}

// Pair type, with exactly b ordinary blocks before the core [0,M,H_m].
int countPair(int m, int b, const vector<LC>& cs) {
    vector<int> head(m, -1), nxt(cs.size(), -1);

    for (int id = 0; id < (int)cs.size(); ++id) {
        const auto& c = cs[id];
        int k = -1;

        if (c.tok.type == 2) {
            if (c.pos != 2 * b + 1) return 0;
            continue;
        }
        if (c.tok.type == 0 && c.tok.x == 0) {
            if (c.pos != 2 * b) return 0;
            continue;
        }
        if (c.tok.type == 1 && c.tok.x == m) {
            if (c.pos != 2 * b + 2) return 0;
            continue;
        }

        k = c.tok.x;
        if (k < 1 || k > m - 1) return 0;
        nxt[id] = head[k];
        head[k] = id;
    }

    auto matchOrdinary = [&](int k, const LC& c, int greater, int side) {
        int g = m - 1 - k;
        int expected;
        if (side == 1) {
            expected = (c.tok.type == 1 ? 1 : 0) + 2 * greater;
        } else {
            expected = 2 * b + 3 + 2 * g +
                       (c.tok.type == 1 ? 1 : 0) - 2 * greater;
        }
        return c.pos == expected;
    };

    auto generate = [&](int k, const LC& c, int out[2]) {
        int cnt = 0;
        int g = m - 1 - k;
        for (int side = 0; side <= 1; ++side) {
            int greater = -1;
            if (side == 1) {
                int base = (c.tok.type == 1 ? 1 : 0);
                int dif = c.pos - base;
                if (dif >= 0 && dif % 2 == 0) greater = dif / 2;
            } else {
                int base = 2 * b + 3 + 2 * g +
                           (c.tok.type == 1 ? 1 : 0);
                int dif = base - c.pos;
                if (dif >= 0 && dif % 2 == 0) greater = dif / 2;
            }
            if (0 <= greater && greater <= g) {
                out[cnt++] = greater * 2 + side;
            }
        }
        return cnt;
    };

    int prevK = -1, prevN = 0;
    int prevD[4];
    long long prevW[4] = {};

    for (int k = m - 1; k >= 1; --k) {
        if (head[k] == -1) continue;

        int allowed[4];
        int first = head[k];
        int na = generate(k, cs[first], allowed);

        for (int id = nxt[first]; id != -1; id = nxt[id]) {
            int filtered[4], nf = 0;
            for (int j = 0; j < na; ++j) {
                int greater = allowed[j] / 2;
                int side = allowed[j] % 2;
                if (matchOrdinary(k, cs[id], greater, side)) {
                    filtered[nf++] = allowed[j];
                }
            }
            na = nf;
            for (int j = 0; j < na; ++j) allowed[j] = filtered[j];
        }
        if (na == 0) return 0;

        int newD[4], newN = 0;
        long long newW[4] = {};

        for (int j = 0; j < na; ++j) {
            int greater = allowed[j] / 2;
            int side = allowed[j] % 2;
            long long ways = 0;

            if (prevK == -1) {
                ways = C(m - 1 - k, greater);
            } else {
                int gap = prevK - k - 1;
                for (int z = 0; z < prevN; ++z) {
                    ways += prevW[z] * C(gap, greater - prevD[z]) % MOD;
                }
                ways %= MOD;
            }

            int after = greater + side;
            int at = -1;
            for (int z = 0; z < newN; ++z) {
                if (newD[z] == after) {
                    at = z;
                    break;
                }
            }
            if (at == -1) {
                at = newN++;
                newD[at] = after;
            }
            newW[at] = (newW[at] + ways) % MOD;
        }

        prevN = newN;
        prevK = k;
        for (int z = 0; z < prevN; ++z) {
            prevD[z] = newD[z];
            prevW[z] = newW[z];
        }
    }

    if (prevK == -1) return C(m - 1, b);

    long long answer = 0;
    for (int z = 0; z < prevN; ++z) {
        answer += prevW[z] * C(prevK - 1, b - prevD[z]) % MOD;
    }
    return answer % MOD;
}

bool addS(vector<LC>& out, int pos, int value, int n, int offset, int mid) {
    Tok t;
    if (value < mid) {
        int l = value - offset;
        if (l < 0 || l >= n) return false;
        t = {0, l};
    } else if (value > mid) {
        int r = value - mid - offset;
        if (r < 1 || r > n) return false;
        t = {1, r};
    } else {
        return false;
    }
    out.push_back({pos, t});
    return true;
}

bool addE(vector<LC>& out, int pos, int value, int n, int offset, int mid) {
    int qpos = 2 * n - 1 - pos;
    Tok t;
    if (value < mid) {
        int l = value - offset;
        if (l < 0 || l >= n) return false;
        t = {1, n - l};
    } else if (value > mid) {
        int r = value - mid - offset;
        if (r < 1 || r > n) return false;
        t = {0, n - r};
    } else {
        return false;
    }
    out.push_back({qpos, t});
    return true;
}

int solveOddLH(int m, const vector<pair<int,int>>& constraints) {
    long long answer = 0;

    // Middle value at the left endpoint.
    {
        vector<LC> cs;
        bool ok = true;
        for (auto [pos, value] : constraints) {
            if (pos == 0) {
                if (value != m) {
                    ok = false;
                    break;
                }
            } else if (!addS(cs, pos - 1, value, m, 0, m)) {
                ok = false;
                break;
            }
        }
        if (ok) answer += countS(m, cs);
    }

    // Middle value at the right endpoint.
    {
        vector<LC> cs;
        bool ok = true;
        for (auto [pos, value] : constraints) {
            if (pos == 2 * m) {
                if (value != m) {
                    ok = false;
                    break;
                }
            } else if (!addE(cs, pos, value, m, 0, m)) {
                ok = false;
                break;
            }
        }
        if (ok) answer += countS(m, cs);
    }

    vector<LC> all;
    for (auto [pos, value] : constraints) {
        Tok t;
        if (value == m) t = {2, 0};
        else if (value < m) t = {0, value};
        else t = {1, value - m};
        all.push_back({pos, t});
    }

    // The middle value lies between 0 and H_m.
    for (int b = 0; b <= m - 1; ++b) {
        answer += countPair(m, b, all);
    }
    answer %= MOD;

    // The middle value lies on an edge H_m -> 0.
    for (int s = 1; s <= m - 1; ++s) {
        int u = m - s;
        vector<LC> upper, lower;
        bool ok = true;

        for (auto [pos, value] : constraints) {
            if (pos < 2 * u) {
                if (!addE(upper, pos, value, u, s, m)) {
                    ok = false;
                    break;
                }
            } else if (pos == 2 * u) {
                if (value != m) {
                    ok = false;
                    break;
                }
            } else {
                if (!addS(lower, pos - 2 * u - 1, value, s, 0, m)) {
                    ok = false;
                    break;
                }
            }
        }

        if (ok) {
            long long a = countS(u, upper);
            if (a) {
                long long b = countS(s, lower);
                answer += a * b % MOD;
            }
        }
    }

    return answer % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    fact[0] = 1;
    for (int i = 1; i <= MAXN; ++i) fact[i] = fact[i - 1] * i % MOD;
    invfact[MAXN] = modpow(fact[MAXN], MOD - 2);
    for (int i = MAXN; i >= 1; --i) {
        invfact[i - 1] = invfact[i] * i % MOD;
    }
    pw2[0] = 1;
    for (int i = 1; i <= MAXN; ++i) pw2[i] = pw2[i - 1] * 2 % MOD;

    int T, N;
    cin >> T >> N;

    while (T--) {
        int K;
        cin >> K;
        vector<pair<int,int>> constraints(K);
        for (auto& [i, j] : constraints) cin >> i >> j;

        if (N % 2 == 0) {
            int m = N / 2;
            vector<int> a(N);
            for (int i = 0; i < N; ++i) {
                if (i % 2 == 0) a[i] = m + i / 2;
                else a[i] = i / 2;
            }

            int answer = 0;
            for (int rev = 0; rev < 2; ++rev) {
                bool ok = true;
                for (auto [pos, value] : constraints) {
                    int expected = rev ? a[N - 1 - pos] : a[pos];
                    if (expected != value) {
                        ok = false;
                        break;
                    }
                }
                if (ok) ++answer;
            }
            cout << answer << '\n';
        } else {
            int m = N / 2;
            if (K == 0) {
                long long answer = (m + 5LL) % MOD * pw2[m - 1] % MOD;
                cout << answer << '\n';
                continue;
            }

            vector<pair<int,int>> reversedConstraints;
            reversedConstraints.reserve(K);
            for (auto [pos, value] : constraints) {
                reversedConstraints.push_back({N - 1 - pos, value});
            }

            int answer = solveOddLH(m, constraints);
            answer += solveOddLH(m, reversedConstraints);
            answer %= MOD;
            cout << answer << '\n';
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int N, M;
vector<long long> factv, invfactv, pow2v;
vector<int> wantPos, wantVal;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long comb(int n, int k) {
    if (k < 0 || k > n || n < 0) return 0;
    return factv[n] * invfactv[k] % MOD * invfactv[n - k] % MOD;
}

bool fixedOK(int v, int pos) {
    if (pos < 0 || pos >= N) return false;
    if (wantVal[v] != -1 && wantVal[v] != pos) return false;
    if (wantPos[pos] != -1 && wantPos[pos] != v) return false;
    return true;
}

// type 0: [q, M+q], type 1: [M+q, q].
bool tokenOK(int q, int type, int start) {
    if (type == 0) {
        return fixedOK(q, start) && fixedOK(M + q, start + 1);
    } else {
        return fixedOK(M + q, start) && fixedOK(q, start + 1);
    }
}

struct Event {
    int t, q;
};

struct Layout {
    int kind;       // 0: generic two-sided layout, 1: form with two F-blocks sides
    int leftBase;
    int rightEnd;
    int rightBase;
    int selectedType;
    int unselectedType;
};

int placementStart(const Layout& lay, bool selected, int c, int t) {
    if (lay.kind == 0) {
        if (selected) return lay.leftBase + 2 * c;
        return lay.rightEnd - 2 * (t - c + 1);
    } else {
        if (selected) return 2 * c;
        return lay.rightBase + 2 * (t - c);
    }
}

bool getCandidate(const Layout& lay, bool selected, int q, int t, int& cOut) {
    int type = selected ? lay.selectedType : lay.unselectedType;
    int start = -1;

    if (wantVal[q] != -1) {
        int offset = (type == 0 ? 0 : 1);
        start = wantVal[q] - offset;
    } else if (wantVal[M + q] != -1) {
        int offset = (type == 0 ? 1 : 0);
        start = wantVal[M + q] - offset;
    } else {
        return false;
    }

    int c = -1;
    if (lay.kind == 0) {
        if (selected) {
            int diff = start - lay.leftBase;
            if (diff < 0 || (diff & 1)) return false;
            c = diff / 2;
        } else {
            int diff = lay.rightEnd - start;
            if (diff <= 0 || (diff & 1)) return false;
            c = t + 1 - diff / 2;
        }
    } else {
        if (selected) {
            if (start < 0 || (start & 1)) return false;
            c = start / 2;
        } else {
            int diff = start - lay.rightBase;
            if (diff < 0 || (diff & 1)) return false;
            c = t - diff / 2;
        }
    }

    if (c < 0 || c > t) return false;
    int actualStart = placementStart(lay, selected, c, t);
    if (actualStart != start) return false;
    if (!tokenOK(q, type, start)) return false;

    cOut = c;
    return true;
}

long long countAssignments(int h, const vector<Event>& events,
                           int totalRequired, const Layout& lay) {
    if (totalRequired > h) return 0;

    vector<pair<int, long long>> states;
    states.push_back({0, 1});
    int processed = 0;

    for (const Event& ev : events) {
        int gap = ev.t - processed;
        vector<pair<int, long long>> nextStates;

        for (int sel = 0; sel <= 1; ++sel) {
            int c;
            if (!getCandidate(lay, sel, ev.q, ev.t, c)) continue;

            long long ways = 0;
            for (auto [oldC, oldWays] : states) {
                ways = (ways + oldWays * comb(gap, c - oldC)) % MOD;
            }
            if (!ways) continue;

            int newC = c + sel;
            bool merged = false;
            for (auto& entry : nextStates) {
                if (entry.first == newC) {
                    entry.second = (entry.second + ways) % MOD;
                    merged = true;
                    break;
                }
            }
            if (!merged) nextStates.push_back({newC, ways});
        }

        if (nextStates.empty()) return 0;
        states.swap(nextStates);
        processed = ev.t + 1;
    }

    int remaining = h - processed;
    long long answer = 0;

    if (totalRequired == -1) {
        for (auto [c, ways] : states) {
            answer = (answer + ways * pow2v[remaining]) % MOD;
        }
    } else {
        for (auto [c, ways] : states) {
            answer = (answer + ways * comb(remaining, totalRequired - c)) % MOD;
        }
    }
    return answer;
}

vector<Event> makeEvents(int lo, int hi, int mode) {
    vector<Event> events;
    if (lo > hi) return events;

    if (mode == 0) {
        for (int q = hi; q >= lo; --q) {
            if (wantVal[q] != -1 || wantVal[M + q] != -1) {
                events.push_back({hi - q, q});
            }
        }
    } else {
        for (int q = lo; q <= hi; ++q) {
            if (wantVal[q] != -1 || wantVal[M + q] != -1) {
                events.push_back({q - lo, q});
            }
        }
    }
    return events;
}

// F/R two-sided layout with one variable-position middle token.
long long genericCount(int lo, int hi, int leftBase, int rightEnd,
                       int middleValue, int mode) {
    int h = max(0, hi - lo + 1);
    vector<Event> events = makeEvents(lo, hi, mode);

    int totalRequired = -1;
    if (wantVal[middleValue] != -1) {
        int pos = wantVal[middleValue];
        int diff = pos - leftBase;
        if (diff < 0 || (diff & 1)) return 0;
        totalRequired = diff / 2;
        if (totalRequired < 0 || totalRequired > h) return 0;
        if (!fixedOK(middleValue, pos)) return 0;
    }

    Layout lay;
    lay.kind = 0;
    lay.leftBase = leftBase;
    lay.rightEnd = rightEnd;
    lay.rightBase = 0;

    if (mode == 0) {
        lay.selectedType = 0;
        lay.unselectedType = 1;
    } else {
        lay.selectedType = 1;
        lay.unselectedType = 0;
    }

    return countAssignments(h, events, totalRequired, lay);
}

long long countCanonicalOdd() {
    int h = M - 1;
    long long answer = 0;

    // [M,0], R(Q) increasing, N-1, F(S) decreasing.
    if (fixedOK(M, 0) && fixedOK(0, 1)) {
        answer += genericCount(1, M - 1, 2, N, N - 1, 1);
    }

    // F(P) decreasing, [0,M,N-1], F(S) decreasing.
    vector<Event> middleEvents = makeEvents(1, M - 1, 0);
    for (int p = 0; p <= h; ++p) {
        int a = 2 * p;
        if (!fixedOK(0, a) || !fixedOK(M, a + 1) ||
            !fixedOK(N - 1, a + 2)) {
            continue;
        }

        Layout lay;
        lay.kind = 1;
        lay.leftBase = 0;
        lay.rightEnd = 0;
        lay.rightBase = 2 * p + 3;
        lay.selectedType = 0;
        lay.unselectedType = 0;

        answer += countAssignments(h, middleEvents, p, lay);
        if (answer >= MOD) answer -= MOD;
    }

    // F(P) decreasing, 0, R(Q) increasing, [N-1,M].
    if (fixedOK(N - 1, N - 2) && fixedOK(M, N - 1)) {
        answer += genericCount(1, M - 1, 0, N - 2, 0, 0);
    }
    answer %= MOD;

    // Defective forms, containing [N-1,M,0].
    for (int d = 1; d <= M - 1; ++d) {
        int highCount = M - 1 - d;
        int posB = 2 * highCount + 1;

        if (!fixedOK(N - 1, posB) ||
            !fixedOK(M, posB + 1) ||
            !fixedOK(0, posB + 2)) {
            continue;
        }

        long long highWays = genericCount(
            d + 1, M - 1, 0, posB, d, 0
        );
        if (!highWays) continue;

        long long lowWays = genericCount(
            1, d - 1, posB + 3, N, M + d, 1
        );

        answer = (answer + highWays * lowWays) % MOD;
    }

    return answer;
}

long long countCanonicalEven() {
    vector<int> seq;
    seq.reserve(N);
    for (int k = 0; k < M; ++k) {
        seq.push_back(M - 1 - k);
        seq.push_back(2 * M - 1 - k);
    }

    for (int i = 0; i < N; ++i) {
        if (wantPos[i] != -1 && wantPos[i] != seq[i]) return 0;
    }
    return 1;
}

long long solveCanonical(const vector<pair<int, int>>& constraints, bool reversed) {
    wantPos.assign(N, -1);
    wantVal.assign(N, -1);

    for (auto [i, j] : constraints) {
        int pos = reversed ? N - 1 - i : i;
        wantPos[pos] = j;
        wantVal[j] = pos;
    }

    if (N % 2 == 0) return countCanonicalEven();
    return countCanonicalOdd();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T >> N;
    M = N / 2;

    factv.assign(N + 1, 1);
    for (int i = 1; i <= N; ++i) {
        factv[i] = factv[i - 1] * i % MOD;
    }
    invfactv.assign(N + 1, 1);
    invfactv[N] = modpow(factv[N], MOD - 2);
    for (int i = N; i >= 1; --i) {
        invfactv[i - 1] = invfactv[i] * i % MOD;
    }

    pow2v.assign(N + 1, 1);
    for (int i = 1; i <= N; ++i) {
        pow2v[i] = pow2v[i - 1] * 2 % MOD;
    }

    while (T--) {
        int K;
        cin >> K;
        vector<pair<int, int>> constraints(K);
        for (int i = 0; i < K; ++i) {
            cin >> constraints[i].first >> constraints[i].second;
        }

        long long answer = solveCanonical(constraints, false);
        answer += solveCanonical(constraints, true);
        answer %= MOD;
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
static const int MOD = 1000000007;

int addmod(int a, int b) {
    int s = a + b;
    if (s >= MOD) s -= MOD;
    return s;
}

struct Option {
    int col;
    int req;
};

struct StageOptions {
    int t;
    int n;
    array<Option, 2> op;
};

struct Spec {
    array<int, 2> val;
    array<int, 2> offset;
    int base;
    int step;
    int maxReq;
};

struct Solver {
    int N, m, u;
    vector<int> valPos;

    int binom(int n, int k, const vector<int64>& fact, const vector<int64>& invfact) const {
        if (k < 0 || k > n || n < 0) return 0;
        return int(fact[n] * invfact[k] % MOD * invfact[n - k] % MOD);
    }

    int countChoices(int stages, const vector<StageOptions>& cs, int total,
                     const vector<int64>& fact, const vector<int64>& invfact,
                     const vector<int>& pow2) const {
        if (cs.empty()) {
            if (total == -1) return pow2[stages];
            return binom(stages, total, fact, invfact);
        }

        array<int64, 2> dp{}, ndp{};

        const StageOptions& first = cs.front();
        for (int i = 0; i < first.n; ++i) {
            dp[i] = binom(first.t, first.op[i].req, fact, invfact);
        }
        int prevN = first.n;
        StageOptions prev = first;

        for (int z = 1; z < (int)cs.size(); ++z) {
            const StageOptions& cur = cs[z];
            ndp = {0, 0};
            int gap = cur.t - prev.t - 1;

            for (int i = 0; i < prevN; ++i) {
                if (!dp[i]) continue;
                int before = prev.op[i].req + (prev.op[i].col == 1);
                for (int j = 0; j < cur.n; ++j) {
                    int need = cur.op[j].req - before;
                    int ways = binom(gap, need, fact, invfact);
                    ndp[j] = (ndp[j] + dp[i] * ways) % MOD;
                }
            }

            dp = ndp;
            prevN = cur.n;
            prev = cur;
        }

        int suffix = stages - 1 - prev.t;
        int64 ans = 0;
        for (int i = 0; i < prevN; ++i) {
            if (!dp[i]) continue;
            int before = prev.op[i].req + (prev.op[i].col == 1);
            if (total == -1) {
                ans = (ans + dp[i] * pow2[suffix]) % MOD;
            } else {
                int need = total - before;
                ans = (ans + dp[i] * binom(suffix, need, fact, invfact)) % MOD;
            }
        }
        return int(ans);
    }

    bool addStage(vector<StageOptions>& cs, int t, int off,
                  const array<Spec, 2>& spec) const {
        bool constrained = false;
        for (int k = 0; k < 2; ++k) {
            if (valPos[spec[0].val[k]] != -1) constrained = true;
        }
        if (!constrained) return true;

        StageOptions so;
        so.t = t;
        so.n = 0;

        for (int col = 0; col < 2; ++col) {
            bool ok = true;
            int requirement = -1;

            for (int k = 0; k < 2 && ok; ++k) {
                int value = spec[col].val[k];
                int p = valPos[value];
                if (p == -1) continue;

                int64 local = (int64)p - off;
                int64 start = local - spec[col].offset[k];
                int64 diff = start - spec[col].base;
                int step = spec[col].step;

                if (diff % step != 0) {
                    ok = false;
                    break;
                }

                int64 req = diff / step;
                if (req < 0 || req > spec[col].maxReq) {
                    ok = false;
                    break;
                }

                if (requirement != -1 && requirement != req) {
                    ok = false;
                    break;
                }
                requirement = int(req);
            }

            if (ok) {
                so.op[so.n++] = {col, requirement};
            }
        }

        if (so.n == 0) return false;
        cs.push_back(so);
        return true;
    }

    int fixedAt(int value, int position) const {
        return valPos[value] == -1 || valPos[value] == position;
    }

    int countA(int s, int off,
               const vector<int64>& fact, const vector<int64>& invfact,
               const vector<int>& pow2) const {
        int stages = s - 1;

        if (!fixedAt(0, off)) return 0;

        int total = -1;
        int markValue = m + s;
        if (valPos[markValue] != -1) {
            int local = valPos[markValue] - off;
            if (local < 1 || (local - 1) % 2 != 0) return 0;
            total = (local - 1) / 2;
            if (total < 0 || total > stages) return 0;
        }

        vector<StageOptions> cs;
        for (int r = 1; r <= stages; ++r) {
            int L = r;
            int H = m + r;

            array<Spec, 2> spec;

            // Color 0: L, pair (L_r,H_r), start = 2(s-r)+2a.
            spec[0].val = {L, H};
            spec[0].offset = {0, 1};
            spec[0].base = 2 * (s - r);
            spec[0].step = 2;
            spec[0].maxReq = r - 1;

            // Color 1: R, pair (H_r,L_r), start = 1+2a.
            spec[1].val = {H, L};
            spec[1].offset = {0, 1};
            spec[1].base = 1;
            spec[1].step = 2;
            spec[1].maxReq = r - 1;

            if (!addStage(cs, r - 1, off, spec)) return 0;
        }

        return countChoices(stages, cs, total, fact, invfact, pow2);
    }

    int countB(const vector<int64>& fact, const vector<int64>& invfact,
               const vector<int>& pow2) const {
        int stages = m - 1;

        if (!fixedAt(2 * m, 2 * m - 1)) return 0;

        int total = -1;
        if (valPos[0] != -1) {
            int local = valPos[0];
            if (local < 0 || local % 2 != 0) return 0;
            total = local / 2;
            if (total < 0 || total > stages) return 0;
        }

        vector<StageOptions> cs;
        for (int t = 0; t < stages; ++t) {
            int r = stages - t;
            int L = r;
            int H = m + r;

            array<Spec, 2> spec;

            // Color 0: R, pair (H_r,L_r), start = 2r-1+2x.
            spec[0].val = {H, L};
            spec[0].offset = {0, 1};
            spec[0].base = 2 * r - 1;
            spec[0].step = 2;
            spec[0].maxReq = stages - r;

            // Color 1: D, pair (L_r,H_r), start = 2x.
            spec[1].val = {L, H};
            spec[1].offset = {0, 1};
            spec[1].base = 0;
            spec[1].step = 2;
            spec[1].maxReq = stages - r;

            if (!addStage(cs, t, 0, spec)) return 0;
        }

        return countChoices(stages, cs, total, fact, invfact, pow2);
    }

    int countQ0(int T, const vector<int64>& fact, const vector<int64>& invfact,
                const vector<int>& pow2) const {
        if (!fixedAt(0, 2 * T)) return 0;
        if (!fixedAt(m, 2 * T + 1)) return 0;
        if (!fixedAt(2 * m, 2 * T + 2)) return 0;

        vector<StageOptions> cs;
        for (int r = 1; r <= u; ++r) {
            int L = r;
            int H = m + r;

            array<Spec, 2> spec;

            // Color 0: A, start = 2u-2r+3+2b.
            spec[0].val = {L, H};
            spec[0].offset = {0, 1};
            spec[0].base = 2 * u - 2 * r + 3;
            spec[0].step = 2;
            spec[0].maxReq = r - 1;

            // Color 1: B, start = 2(T-1)-2b.
            spec[1].val = {L, H};
            spec[1].offset = {0, 1};
            spec[1].base = 2 * T - 2;
            spec[1].step = -2;
            spec[1].maxReq = r - 1;

            if (!addStage(cs, r - 1, 0, spec)) return 0;
        }

        return countChoices(u, cs, T, fact, invfact, pow2);
    }

    int countLate(int s, const vector<int64>& fact, const vector<int64>& invfact,
                  const vector<int>& pow2) const {
        int lateStages = u - s;

        int total = -1;
        if (valPos[s] != -1) {
            int p = valPos[s];
            if (p < 0 || p % 2 != 0) return 0;
            total = p / 2;
            if (total < 0 || total > lateStages) return 0;
        }

        vector<StageOptions> cs;
        for (int t = 0; t < lateStages; ++t) {
            int r = u - t;
            int L = r;
            int H = m + r;

            array<Spec, 2> spec;

            // Color 0: A, pair (H_r,L_r).
            spec[0].val = {H, L};
            spec[0].offset = {0, 1};
            spec[0].base = 2 * r - 2 * s - 1;
            spec[0].step = 2;
            spec[0].maxReq = u - r;

            // Color 1: B, pair (L_r,H_r).
            spec[1].val = {L, H};
            spec[1].offset = {0, 1};
            spec[1].base = 0;
            spec[1].step = 2;
            spec[1].maxReq = u - r;

            if (!addStage(cs, t, 0, spec)) return 0;
        }

        return countChoices(lateStages, cs, total, fact, invfact, pow2);
    }

    int run(const vector<int64>& fact, const vector<int64>& invfact,
            const vector<int>& pow2) const {
        int64 ans = 0;

        // Center prepended, base path of type A.
        if (fixedAt(m, 0)) {
            ans += countA(m, 1, fact, invfact, pow2);
        }

        // Center appended, base path of type B.
        if (fixedAt(m, 2 * m)) {
            ans += countB(fact, invfact, pow2);
        }

        // Internal center, orientation 0,center,H_m.
        for (int T = 0; T <= u; ++T) {
            ans += countQ0(T, fact, invfact, pow2);
            if (ans >= MOD) ans -= MOD;
        }

        // Internal center, orientation H_m,center,0.
        for (int s = 1; s <= u; ++s) {
            int v = u - s;
            if (!fixedAt(2 * m, 2 * v + 1)) continue;
            if (!fixedAt(m, 2 * v + 2)) continue;

            int early = countA(s, 2 * v + 3, fact, invfact, pow2);
            if (!early) continue;
            int late = countLate(s, fact, invfact, pow2);
            ans = (ans + (int64)early * late) % MOD;
        }

        return int(ans % MOD);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T, N;
    cin >> T >> N;

    vector<int64> fact(N + 1), invfact(N + 1);
    vector<int> pow2(N + 1);

    fact[0] = 1;
    for (int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;

    auto modpow = [&](int64 a, int e) {
        int64 r = 1;
        while (e) {
            if (e & 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    };

    invfact[N] = modpow(fact[N], MOD - 2);
    for (int i = N; i >= 1; --i) invfact[i - 1] = invfact[i] * i % MOD;

    pow2[0] = 1;
    for (int i = 1; i <= N; ++i) pow2[i] = addmod(pow2[i - 1], pow2[i - 1]);

    while (T--) {
        int K;
        cin >> K;

        vector<pair<int, int>> constraints(K);
        vector<int> valPos(N, -1);

        for (int k = 0; k < K; ++k) {
            int i, j;
            cin >> i >> j;
            constraints[k] = {i, j};
            valPos[j] = i;
        }

        if (N % 2 == 0) {
            int half = N / 2;
            vector<int> p;
            for (int k = 0; k < half; ++k) {
                p.push_back(half + k);
                p.push_back(k);
            }
            vector<int> rev = p;
            reverse(rev.begin(), rev.end());

            int answer = 0;
            for (const vector<int>* q : {&p, &rev}) {
                bool ok = true;
                for (auto [i, j] : constraints) {
                    if ((*q)[i] != j) {
                        ok = false;
                        break;
                    }
                }
                if (ok) answer = addmod(answer, 1);
            }
            cout << answer << '\n';
            continue;
        }

        Solver solver;
        solver.N = N;
        solver.m = N / 2;
        solver.u = solver.m - 1;
        solver.valPos = valPos;

        int answer = solver.run(fact, invfact, pow2);

        vector<int> reversedValPos(N, -1);
        for (int value = 0; value < N; ++value) {
            if (valPos[value] != -1) {
                reversedValPos[value] = N - 1 - valPos[value];
            }
        }
        solver.valPos = move(reversedValPos);

        answer = addmod(answer, solver.run(fact, invfact, pow2));
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;
static const int MAXN = 2000;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long fact[MAXN + 1], invfact[MAXN + 1], pw2[MAXN + 1];

long long C(int n, int r) {
    if (r < 0 || r > n || n < 0) return 0;
    return fact[n] * invfact[r] % MOD * invfact[n - r] % MOD;
}

struct Tok {
    int type; // 0 = low, 1 = high, 2 = middle
    int x;    // low index, or high index
};

struct LC {
    int pos;
    Tok tok;
};

// Number of assignments for a component starting at its minimum low value.
int countS(int n, const vector<LC>& cs) {
    if (n == 1) {
        for (const auto& c : cs) {
            if (c.pos == 0) {
                if (c.tok.type != 0 || c.tok.x != 0) return 0;
            } else if (c.pos == 1) {
                if (c.tok.type != 1 || c.tok.x != 1) return 0;
            } else {
                return 0;
            }
        }
        return 1;
    }

    vector<int> head(n, -1), nxt(cs.size(), -1), peak;

    for (int id = 0; id < (int)cs.size(); ++id) {
        const auto& c = cs[id];
        int k = -1;
        if (c.tok.type == 0) {
            int l = c.tok.x;
            if (l == 0) {
                if (c.pos != 0) return 0;
                continue;
            } else if (l == n - 1) {
                peak.push_back(id);
                continue;
            } else {
                k = l;
            }
        } else if (c.tok.type == 1) {
            int r = c.tok.x;
            if (r >= n - 1) {
                peak.push_back(id);
                continue;
            } else {
                k = r;
            }
        } else {
            return 0;
        }

        if (k < 1 || k > n - 2) return 0;
        nxt[id] = head[k];
        head[k] = id;
    }

    auto matchOrdinary = [&](int k, const LC& c, int pref, int side) {
        int base;
        if (side == 1) {
            base = (c.tok.type == 1 ? 1 : 2);
        } else {
            base = 2 * (n - k) + (c.tok.type == 1 ? 1 : 0);
        }
        return c.pos == base + 2 * pref;
    };

    auto generate = [&](int k, const LC& c, int out[2]) {
        int cnt = 0;
        for (int side = 0; side <= 1; ++side) {
            int base;
            if (side == 1) {
                base = (c.tok.type == 1 ? 1 : 2);
            } else {
                base = 2 * (n - k) + (c.tok.type == 1 ? 1 : 0);
            }
            int dif = c.pos - base;
            if (dif >= 0 && dif % 2 == 0) {
                int pref = dif / 2;
                if (0 <= pref && pref <= k - 1) {
                    out[cnt++] = pref * 2 + side;
                }
            }
        }
        return cnt;
    };

    int prevK = -1, prevN = 0;
    int prevD[4];
    long long prevW[4] = {};

    for (int k = 1; k <= n - 2; ++k) {
        if (head[k] == -1) continue;

        int allowed[4], na = 0;
        int first = head[k];
        na = generate(k, cs[first], allowed);

        for (int id = nxt[first]; id != -1; id = nxt[id]) {
            int filtered[4], nf = 0;
            for (int j = 0; j < na; ++j) {
                int pref = allowed[j] / 2;
                int side = allowed[j] % 2;
                if (matchOrdinary(k, cs[id], pref, side)) {
                    filtered[nf++] = allowed[j];
                }
            }
            na = nf;
            for (int j = 0; j < na; ++j) allowed[j] = filtered[j];
        }
        if (na == 0) return 0;

        int newD[4], newN = 0;
        long long newW[4] = {};

        for (int j = 0; j < na; ++j) {
            int pref = allowed[j] / 2;
            int side = allowed[j] % 2;
            long long ways = 0;

            if (prevK == -1) {
                ways = C(k - 1, pref);
            } else {
                int gap = k - prevK - 1;
                for (int z = 0; z < prevN; ++z) {
                    ways += prevW[z] * C(gap, pref - prevD[z]) % MOD;
                }
                ways %= MOD;
            }

            int after = pref + side;
            int at = -1;
            for (int z = 0; z < newN; ++z) {
                if (newD[z] == after) {
                    at = z;
                    break;
                }
            }
            if (at == -1) {
                at = newN++;
                newD[at] = after;
            }
            newW[at] = (newW[at] + ways) % MOD;
        }

        prevN = newN;
        prevK = k;
        for (int z = 0; z < prevN; ++z) {
            prevD[z] = newD[z];
            prevW[z] = newW[z];
        }
    }

    auto waysWithTotal = [&](int total) -> long long {
        if (prevK == -1) return C(n - 2, total);
        int remaining = n - 2 - prevK;
        long long res = 0;
        for (int z = 0; z < prevN; ++z) {
            res += prevW[z] * C(remaining, total - prevD[z]) % MOD;
        }
        return res % MOD;
    };

    long long answer = 0;

    if (peak.empty()) {
        for (int total = 0; total <= n - 2; ++total) {
            answer += 2 * waysWithTotal(total) % MOD;
        }
        return answer % MOD;
    }

    vector<int> masks(n - 1, 3);

    for (int id : peak) {
        const auto& c = cs[id];
        for (int total = 0; total <= n - 2; ++total) {
            int cur = 0;
            if (c.tok.type == 0) {
                if (c.pos == 2 + 2 * total) cur = 3;
            } else if (c.tok.x == n - 1) {
                if (c.pos == 1 + 2 * total) cur |= 1;
                if (c.pos == 3 + 2 * total) cur |= 2;
            } else {
                if (c.pos == 3 + 2 * total) cur |= 1;
                if (c.pos == 1 + 2 * total) cur |= 2;
            }
            masks[total] &= cur;
        }
    }

    for (int total = 0; total <= n - 2; ++total) {
        if (masks[total]) {
            int cnt = (masks[total] & 1) + ((masks[total] >> 1) & 1);
            answer += waysWithTotal(total) * cnt % MOD;
        }
    }
    return answer % MOD;
}

// Pair type, with exactly b ordinary blocks before the core [0,M,H_m].
int countPair(int m, int b, const vector<LC>& cs) {
    vector<int> head(m, -1), nxt(cs.size(), -1);

    for (int id = 0; id < (int)cs.size(); ++id) {
        const auto& c = cs[id];
        int k = -1;

        if (c.tok.type == 2) {
            if (c.pos != 2 * b + 1) return 0;
            continue;
        }
        if (c.tok.type == 0 && c.tok.x == 0) {
            if (c.pos != 2 * b) return 0;
            continue;
        }
        if (c.tok.type == 1 && c.tok.x == m) {
            if (c.pos != 2 * b + 2) return 0;
            continue;
        }

        k = c.tok.x;
        if (k < 1 || k > m - 1) return 0;
        nxt[id] = head[k];
        head[k] = id;
    }

    auto matchOrdinary = [&](int k, const LC& c, int greater, int side) {
        int g = m - 1 - k;
        int expected;
        if (side == 1) {
            expected = (c.tok.type == 1 ? 1 : 0) + 2 * greater;
        } else {
            expected = 2 * b + 3 + 2 * g +
                       (c.tok.type == 1 ? 1 : 0) - 2 * greater;
        }
        return c.pos == expected;
    };

    auto generate = [&](int k, const LC& c, int out[2]) {
        int cnt = 0;
        int g = m - 1 - k;
        for (int side = 0; side <= 1; ++side) {
            int greater = -1;
            if (side == 1) {
                int base = (c.tok.type == 1 ? 1 : 0);
                int dif = c.pos - base;
                if (dif >= 0 && dif % 2 == 0) greater = dif / 2;
            } else {
                int base = 2 * b + 3 + 2 * g +
                           (c.tok.type == 1 ? 1 : 0);
                int dif = base - c.pos;
                if (dif >= 0 && dif % 2 == 0) greater = dif / 2;
            }
            if (0 <= greater && greater <= g) {
                out[cnt++] = greater * 2 + side;
            }
        }
        return cnt;
    };

    int prevK = -1, prevN = 0;
    int prevD[4];
    long long prevW[4] = {};

    for (int k = m - 1; k >= 1; --k) {
        if (head[k] == -1) continue;

        int allowed[4];
        int first = head[k];
        int na = generate(k, cs[first], allowed);

        for (int id = nxt[first]; id != -1; id = nxt[id]) {
            int filtered[4], nf = 0;
            for (int j = 0; j < na; ++j) {
                int greater = allowed[j] / 2;
                int side = allowed[j] % 2;
                if (matchOrdinary(k, cs[id], greater, side)) {
                    filtered[nf++] = allowed[j];
                }
            }
            na = nf;
            for (int j = 0; j < na; ++j) allowed[j] = filtered[j];
        }
        if (na == 0) return 0;

        int newD[4], newN = 0;
        long long newW[4] = {};

        for (int j = 0; j < na; ++j) {
            int greater = allowed[j] / 2;
            int side = allowed[j] % 2;
            long long ways = 0;

            if (prevK == -1) {
                ways = C(m - 1 - k, greater);
            } else {
                int gap = prevK - k - 1;
                for (int z = 0; z < prevN; ++z) {
                    ways += prevW[z] * C(gap, greater - prevD[z]) % MOD;
                }
                ways %= MOD;
            }

            int after = greater + side;
            int at = -1;
            for (int z = 0; z < newN; ++z) {
                if (newD[z] == after) {
                    at = z;
                    break;
                }
            }
            if (at == -1) {
                at = newN++;
                newD[at] = after;
            }
            newW[at] = (newW[at] + ways) % MOD;
        }

        prevN = newN;
        prevK = k;
        for (int z = 0; z < prevN; ++z) {
            prevD[z] = newD[z];
            prevW[z] = newW[z];
        }
    }

    if (prevK == -1) return C(m - 1, b);

    long long answer = 0;
    for (int z = 0; z < prevN; ++z) {
        answer += prevW[z] * C(prevK - 1, b - prevD[z]) % MOD;
    }
    return answer % MOD;
}

bool addS(vector<LC>& out, int pos, int value, int n, int offset, int mid) {
    Tok t;
    if (value < mid) {
        int l = value - offset;
        if (l < 0 || l >= n) return false;
        t = {0, l};
    } else if (value > mid) {
        int r = value - mid - offset;
        if (r < 1 || r > n) return false;
        t = {1, r};
    } else {
        return false;
    }
    out.push_back({pos, t});
    return true;
}

bool addE(vector<LC>& out, int pos, int value, int n, int offset, int mid) {
    int qpos = 2 * n - 1 - pos;
    Tok t;
    if (value < mid) {
        int l = value - offset;
        if (l < 0 || l >= n) return false;
        t = {1, n - l};
    } else if (value > mid) {
        int r = value - mid - offset;
        if (r < 1 || r > n) return false;
        t = {0, n - r};
    } else {
        return false;
    }
    out.push_back({qpos, t});
    return true;
}

int solveOddLH(int m, const vector<pair<int,int>>& constraints) {
    long long answer = 0;

    // Middle value at the left endpoint.
    {
        vector<LC> cs;
        bool ok = true;
        for (auto [pos, value] : constraints) {
            if (pos == 0) {
                if (value != m) {
                    ok = false;
                    break;
                }
            } else if (!addS(cs, pos - 1, value, m, 0, m)) {
                ok = false;
                break;
            }
        }
        if (ok) answer += countS(m, cs);
    }

    // Middle value at the right endpoint.
    {
        vector<LC> cs;
        bool ok = true;
        for (auto [pos, value] : constraints) {
            if (pos == 2 * m) {
                if (value != m) {
                    ok = false;
                    break;
                }
            } else if (!addE(cs, pos, value, m, 0, m)) {
                ok = false;
                break;
            }
        }
        if (ok) answer += countS(m, cs);
    }

    vector<LC> all;
    for (auto [pos, value] : constraints) {
        Tok t;
        if (value == m) t = {2, 0};
        else if (value < m) t = {0, value};
        else t = {1, value - m};
        all.push_back({pos, t});
    }

    // The middle value lies between 0 and H_m.
    for (int b = 0; b <= m - 1; ++b) {
        answer += countPair(m, b, all);
    }
    answer %= MOD;

    // The middle value lies on an edge H_m -> 0.
    for (int s = 1; s <= m - 1; ++s) {
        int u = m - s;
        vector<LC> upper, lower;
        bool ok = true;

        for (auto [pos, value] : constraints) {
            if (pos < 2 * u) {
                if (!addE(upper, pos, value, u, s, m)) {
                    ok = false;
                    break;
                }
            } else if (pos == 2 * u) {
                if (value != m) {
                    ok = false;
                    break;
                }
            } else {
                if (!addS(lower, pos - 2 * u - 1, value, s, 0, m)) {
                    ok = false;
                    break;
                }
            }
        }

        if (ok) {
            long long a = countS(u, upper);
            if (a) {
                long long b = countS(s, lower);
                answer += a * b % MOD;
            }
        }
    }

    return answer % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    fact[0] = 1;
    for (int i = 1; i <= MAXN; ++i) fact[i] = fact[i - 1] * i % MOD;
    invfact[MAXN] = modpow(fact[MAXN], MOD - 2);
    for (int i = MAXN; i >= 1; --i) {
        invfact[i - 1] = invfact[i] * i % MOD;
    }
    pw2[0] = 1;
    for (int i = 1; i <= MAXN; ++i) pw2[i] = pw2[i - 1] * 2 % MOD;

    int T, N;
    cin >> T >> N;

    while (T--) {
        int K;
        cin >> K;
        vector<pair<int,int>> constraints(K);
        for (auto& [i, j] : constraints) cin >> i >> j;

        if (N % 2 == 0) {
            int m = N / 2;
            vector<int> a(N);
            for (int i = 0; i < N; ++i) {
                if (i % 2 == 0) a[i] = m + i / 2;
                else a[i] = i / 2;
            }

            int answer = 0;
            for (int rev = 0; rev < 2; ++rev) {
                bool ok = true;
                for (auto [pos, value] : constraints) {
                    int expected = rev ? a[N - 1 - pos] : a[pos];
                    if (expected != value) {
                        ok = false;
                        break;
                    }
                }
                if (ok) ++answer;
            }
            cout << answer << '\n';
        } else {
            int m = N / 2;
            if (K == 0) {
                long long answer = (m + 5LL) % MOD * pw2[m - 1] % MOD;
                cout << answer << '\n';
                continue;
            }

            vector<pair<int,int>> reversedConstraints;
            reversedConstraints.reserve(K);
            for (auto [pos, value] : constraints) {
                reversedConstraints.push_back({N - 1 - pos, value});
            }

            int answer = solveOddLH(m, constraints);
            answer += solveOddLH(m, reversedConstraints);
            answer %= MOD;
            cout << answer << '\n';
        }
    }

    return 0;
}

