    }

    vector<vector<int64>> dp(N + 1, vector<int64>(N + 1, 0));
    vector<int64> forest(N + 1, 0);

    for (int i = N; i >= 1; --i) {
        dp[i][i] = 0;
        forest[i] = 0;
        int64 saved = 0;

        for (int r = i + 1; r <= N; ++r) {
            saved += saving[i][r];
            int64 best = INF;

            for (int before = i; before < r; ++before) {
                int child = before + 1;
                int64 candidate = forest[before] + dp[child][r]
                                + add[i][child];
                best = min(best, candidate);
            }

            forest[r] = best;
            dp[i][r] = best - saved;
        }
    }

    cout << removeAll + dp[1][N] << '\n';
    return 0;
}

