int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> add(N + 2, vector<int>(N + 2, 0));
    vector<vector<int>> rem(N + 2, vector<int>(N + 2, 0));

    for (int j = 2; j <= N; ++j) {
        for (int i = 1; i < j; ++i) {
            int a;
            cin >> a;
            if (a > 0) add[i][j] = a;
            else rem[i][j] = -a;
        }
    }

    // cross[l][r]: cost of removing initial edges from l to vertices after r.
    vector<vector<long long>> cross(N + 2, vector<long long>(N + 2, 0));
    for (int l = 1; l <= N; ++l) {
        for (int r = N - 1; r >= l; --r) {
            cross[l][r] = cross[l][r + 1] + rem[l][r + 1];
        }
    }

    // dp[l][r]: minimum cost for a subtree rooted at l whose preorder
    // interval is exactly [l,r].
    vector<vector<long long>> dp(N + 2, vector<long long>(N + 2, 0));
    const long long INF = (1LL << 62);

    for (int l = N; l >= 1; --l) {
        // forest[x]: minimum cost of the children of l covering [l+1,x].
        vector<long long> forest(N + 2, INF);
        forest[l] = 0;
        dp[l][l] = cross[l][l];

        for (int r = l + 1; r <= N; ++r) {
            long long best = INF;
            for (int c = l + 1; c <= r; ++c) {
                long long candidate =
                    forest[c - 1] + add[l][c] + dp[c][r];
                best = min(best, candidate);
            }
            forest[r] = best;
            dp[l][r] = cross[l][r] + best;
        }
    }

    cout << dp[1][N] << '\n';
    return 0;
}

