int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    // A[i][j] for i<j : positive => edge absent (add cost), negative => present (remove cost)
    vector<vector<int>> A(N + 2, vector<int>(N + 2, 0));
    for (int j = 2; j <= N; j++)
        for (int i = 1; i < j; i++)
            cin >> A[i][j];

    // E[i][j] = cost to make tree edge (i,j) present
    vector<vector<int>> E(N + 2, vector<int>(N + 2, 0));
    for (int i = 1; i <= N; i++)
        for (int j = i + 1; j <= N; j++)
            E[i][j] = max(A[i][j], 0);

    // D[i][j] = total removal cost of present edges (i,k) with k > j
    vector<vector<long long>> D(N + 2, vector<long long>(N + 2, 0));
    for (int i = 1; i <= N; i++) {
        for (int j = N; j >= i; j--) {
            D[i][j] = D[i][j + 1];
            if (A[i][j + 1] < 0) D[i][j] += -(long long)A[i][j + 1];
        }
    }

    const long long INF = (1LL << 60);

    // dpT[r][l] = dp[l][r]: min cost of a subtree rooted at l spanning [l..r]
    vector<vector<long long>> dpT(N + 2, vector<long long>(N + 2, 0));
    vector<long long> f(N + 2, 0);

    for (int l = N; l >= 1; l--) {
        f[l] = 0;
        for (int r = l + 1; r <= N; r++) {
            long long best = INF;
            const long long *drow = dpT[r].data();
            const int *erow = E[l].data();
            for (int m = l + 1; m <= r; m++) {
                long long cand = f[m - 1] + drow[m] + (long long)erow[m];
                if (cand < best) best = cand;
            }
            f[r] = best;
        }
        for (int r = l; r <= N; r++)
            dpT[r][l] = D[l][r] + f[r];
    }

    cout << dpT[N][1] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 760;

static int wgt[MAXN][MAXN];      // wgt[i][j]  = cost of deleting existing edge (i,j)
static int addc[MAXN][MAXN];      // addc[i][j] = cost of adding missing edge (i,j)
static int Pt[MAXN][MAXN];        // Pt[t][x]   = P_x(t) = sum_{y=x+1..t} wgt[x][y]
static long long Ht[MAXN][MAXN];  // Ht[t][i]   = H[i][t]
static long long row[MAXN];       // current DP row H[i][*]

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    for (int j = 2; j <= N; j++) {
        for (int i = 1; i < j; i++) {
            int a; cin >> a;
            if (a < 0) wgt[i][j] = -a;   // existing edge
            else       addc[i][j] = a;    // missing edge
        }
    }

    // Prefix sums of w, stored transposed: Pt[t][x] = sum_{y=x+1..t} wgt[x][y]
    for (int x = 1; x <= N; x++) {
        int run = 0;
        for (int t = x + 1; t <= N; t++) {
            run += wgt[x][t];
            Pt[t][x] = run;
        }
    }

    // Baseline: every pair (x,y) with 2 <= x < y would cost w(x,y) unless x is an ancestor of y
    long long base = 0;
    for (int x = 2; x <= N; x++) base += Pt[N][x];

    const long long INF = (1LL << 62);

    for (int i = N; i >= 1; i--) {
        row[i] = 0;                       // H[i][i] = 0
        for (int pos = i + 1; pos <= N; pos++) {
            long long best = INF;
            const long long* hrow = Ht[pos];   // H[c][pos]
            const int* prow = Pt[pos];         // P_c(pos)
            for (int c = i + 1; c <= pos; c++) {
                long long v = row[c - 1] + hrow[c]
                            + (long long)addc[i][c] - prow[c];
                if (v < best) best = v;
            }
            row[pos] = best;
            Ht[pos][i] = best;
        }
    }

    cout << base + Ht[N][1] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct Rat {
    i128 n;
    int64 d;
};

struct Interval {
    bool ok;
    Rat lo, hi;
};

// Interval of real a for which a punches at 0 and K-a punches at N-1
// (fractional punches allowed) cover all requirements.
Interval getInterval(int64 K, const vector<int64>& p) {
    const int N = (int)p.size();
    const int L = N - 1;

    Interval res{true, {0, 1}, {(i128)K, 1}};

    for (int i = 0; i < N; ++i) {
        i128 base = (i128)K * (L - i);
        int64 d = 2LL * i - L;

        if (d == 0) {
            if (base < (i128)p[i]) {
                res.ok = false;
                return res;
            }
        } else if (d > 0) {
            i128 num = (i128)p[i] - base;
            if (num > 0 && num * res.lo.d > res.lo.n * d) {
                res.lo = {num, d};
            }
        } else {
            int64 e = -d;
            i128 num = base - (i128)p[i];
            if (num < 0) {
                res.ok = false;
                return res;
            }
            if (num * res.hi.d < res.hi.n * e) {
                res.hi = {num, e};
            }
        }
    }

    res.ok = (res.lo.n * res.hi.d <= res.hi.n * res.lo.d);
    return res;
}

// Exact feasibility with K integral punches.
bool integerFeasible(int64 K, const vector<int64>& p) {
    const int N = (int)p.size();
    const int L = N - 1;

    Interval in = getInterval(K, p);
    if (!in.ok) return false;

    i128 ceilLo = in.lo.n / in.lo.d;
    if (in.lo.n % in.lo.d != 0) ++ceilLo;
    i128 floorHi = in.hi.n / in.hi.d;

    // Integral endpoint-only solution.
    if (ceilLo <= floorHi) return true;

    // Otherwise only one possible pair of endpoint base counts remains.
    i128 q = in.lo.n / in.lo.d;
    if (q < 0 || q >= (i128)K) return false;

    int64 A = (int64)q;
    int64 B = K - 1 - A;

    // Check A punches at 0, B punches at N-1, and one additional punch x.
    vector<i128> r(N), suffix(N);
    for (int i = 0; i < N; ++i) {
        i128 base = (i128)A * i + (i128)B * (L - i);
        r[i] = (i128)p[i] - base;
    }

    const i128 INF = i128(1) << 120;
    i128 mn = INF;
    for (int i = N - 1; i >= 0; --i) {
        mn = min(mn, (i128)i - r[i]);
        suffix[i] = mn;
    }

    i128 mx = -INF;
    for (int x = 0; x < N; ++x) {
        mx = max(mx, (i128)x + r[x]);
        if (mx <= (i128)x && (i128)x <= suffix[x]) return true;
    }
    return false;
}

// Ceiling of the fractional (linear programming) optimum.
int64 fractionalCeil(const vector<int64>& p) {
    const int N = (int)p.size();
    const int L = N - 1;

    vector<int> hull;
    hull.reserve(N);

    // Upper concave hull of (i,p_i).
    for (int i = 0; i < N; ++i) {
        while ((int)hull.size() >= 2) {
            int a = hull[(int)hull.size() - 2];
            int b = hull.back();
            i128 lhs = ((i128)p[b] - p[a]) * (i - b);
            i128 rhs = ((i128)p[i] - p[b]) * (b - a);
            if (lhs <= rhs) hull.pop_back();
            else break;
        }
        hull.push_back(i);
    }

    // Evaluate the hull at x=L/2.
    int e = 0;
    while (e + 1 < (int)hull.size() && 2LL * hull[e + 1] < L) ++e;

    int x1 = hull[e], x2 = hull[e + 1];
    int64 dx = x2 - x1;

    i128 den = (i128)L * dx;
    i128 num = 2 * (i128)p[x1] * dx
             + ((i128)p[x2] - p[x1]) * (L - 2LL * x1);

    if (num <= 0) return 0;
    return (int64)((num + den - 1) / den);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;
        vector<int64> p(N);
        for (auto &x : p) cin >> x;

        int64 m = fractionalCeil(p);
        int64 answer = integerFeasible(m, p) ? m : m + 1;
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using i128 = __int128_t;
using int64 = long long;

struct Fraction {
    i128 num;
    int64 den; // always positive
};

static int cmpFraction(const Fraction &a, const Fraction &b) {
    i128 left = a.num * b.den;
    i128 right = b.num * a.den;
    if (left < right) return -1;
    if (left > right) return 1;
    return 0;
}

static i128 floorDiv(i128 a, int64 b) {
    if (a >= 0) return a / b;
    return -((-a + b - 1) / b);
}

static i128 ceilDiv(i128 a, int64 b) {
    if (a >= 0) return (a + b - 1) / b;
    return -((-a) / b);
}

struct TestSolver {
    int n;
    int64 L;
    vector<int64> p;

    bool getRealInterval(int64 m, Fraction &lower, Fraction &upper) const {
        lower = {0, 1};
        upper = {(i128)L * m, 1};

        for (int i = 0; i < n; ++i) {
            i128 mi = (i128)m * i;
            int64 d = L - 2LL * i;

            if (d == 0) {
                if ((i128)p[i] > mi) return false;
                continue;
            }

            i128 num = (i128)L * ((i128)p[i] - mi);
            Fraction f{num, d};
            if (f.den < 0) {
                f.den = -f.den;
                f.num = -f.num;
            }

            if (d > 0) {
                if (cmpFraction(f, lower) > 0) lower = f;
            } else {
                if (cmpFraction(f, upper) < 0) upper = f;
            }

            if (cmpFraction(lower, upper) > 0) return false;
        }
        return true;
    }

    bool feasible(int64 m) const {
        Fraction lower, upper;
        if (!getRealInterval(m, lower, upper)) return false;

        i128 aLo = ceilDiv(lower.num, lower.den);
        i128 aHi = floorDiv(upper.num, upper.den);
        if (aLo > aHi) return false;

        // If A is a multiple of L, punches only at the two endpoints suffice.
        i128 firstMultiple = ceilDiv(aLo, L) * L;
        if (firstMultiple <= aHi) return true;

        // Otherwise all possible A values have the same quotient b=A/L.
        i128 b = aLo / L;
        int64 rLo = (int64)(aLo % L);
        int64 rHi = (int64)(aHi % L);
        if (rLo > rHi || rLo <= 0 || rHi >= L) return false;

        // b punches at L, m-b-1 punches at 0, and one punch at r.
        // At tile i the power is base_i + |i-r|.
        vector<int> diff(L + 2, 0);

        for (int i = 0; i < n; ++i) {
            i128 base = (i128)(m - 1) * i + b * (L - 2LL * i);
            i128 need = (i128)p[i] - base;
            if (need <= 0) continue;

            // Every available r has |i-r| <= L-1.
            if (need >= L) return false;

            int64 t = (int64)need;
            int64 forbiddenL = max(rLo, (int64)i - t + 1);
            int64 forbiddenR = min(rHi, (int64)i + t - 1);

            if (forbiddenL <= forbiddenR) {
                ++diff[forbiddenL];
                --diff[forbiddenR + 1];
            }
        }

        int covered = 0;
        for (int64 r = rLo; r <= rHi; ++r) {
            covered += diff[r];
            if (covered == 0) return true;
        }
        return false;
    }

    int64 solve() const {
        int64 lo = 0, hi = 4000000000000000000LL;
        while (lo < hi) {
            int64 mid = lo + (hi - lo) / 2;
            if (feasible(mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

