#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

struct Rat {
    i128 n;
    int d; // always positive
};

struct Bounds {
    bool ok;
    Rat lo, hi;
};

// For a fixed K, decide whether fractional punches at the two endpoints
// can cover all tiles. beta is the amount punched at tile L=N-1, and
// K-beta is punched at tile 0.
static Bounds getBounds(ll K, const vector<ll>& p, int L) {
    i128 k = (i128)K;
    Rat lo{0, 1}, hi{(i128)K, 1};
    bool ok = true;

    for (int i = 0; i <= L; ++i) {
        // K*i + beta*(L-2*i) >= p[i]
        i128 num = (i128)p[i] - k * (i128)i;
        int c = L - 2 * i;

        if (c == 0) {
            if (num > 0) {
                ok = false;
                break;
            }
        } else if (c > 0) {
            // beta >= num/c
            if (num * (i128)lo.d > lo.n * (i128)c) {
                lo = {num, c};
            }
        } else {
            int d = -c;
            // beta <= (K*i-p[i])/d
            i128 upperNum = -num;
            if (upperNum * (i128)hi.d < hi.n * (i128)d) {
                hi = {upperNum, d};
            }
        }
    }

    if (ok && lo.n * (i128)hi.d > hi.n * (i128)lo.d) {
        ok = false;
    }
    return {ok, lo, hi};
}

static i128 floorDiv(i128 n, i128 d) {
    i128 q = n / d, r = n % d;
    if (r < 0) --q;
    return q;
}

static i128 ceilDiv(i128 n, i128 d) {
    i128 q = n / d, r = n % d;
    if (r > 0) ++q;
    return q;
}

// Check whether K integral punches suffice.
static bool integralFeasible(ll K, const vector<ll>& p, int L) {
    Bounds bounds = getBounds(K, p, L);
    if (!bounds.ok) return false;

    // An integral beta in this interval gives an endpoint-only solution.
    i128 smallestInt = ceilDiv(bounds.lo.n, bounds.lo.d);
    i128 largestInt = floorDiv(bounds.hi.n, bounds.hi.d);
    if (smallestInt <= largestInt) return true;

    // Otherwise every feasible real beta lies strictly between b and b+1.
    // After spreading punches apart, an integral solution can be assumed
    // to have b punches at L, K-1-b punches at 0, and one punch at r.
    i128 b = floorDiv(bounds.lo.n, bounds.lo.d);
    if (b < 0 || b > (i128)(K - 1)) return false;

    const int N = L + 1;
    const i128 INF = ((i128)1 << 120);
    i128 k = (i128)K;

    vector<i128> R(N), A(N), B(N);
    for (int i = 0; i < N; ++i) {
        i128 c = (i128)(L - 2 * i);
        i128 base = (k - 1) * (i128)i + b * c;
        R[i] = (i128)p[i] - base;

        // For the remaining punch at r:
        // |i-r| >= R[i].
        A[i] = (i128)i + R[i]; // r >= A[i] when i < r
        B[i] = (i128)i - R[i]; // r <= B[i] when i > r
    }

    vector<i128> prefixMax(N), suffixMin(N);
    prefixMax[0] = -INF;
    for (int r = 1; r < N; ++r) {
        prefixMax[r] = max(prefixMax[r - 1], A[r - 1]);
    }

    suffixMin[N - 1] = INF;
    for (int r = N - 2; r >= 0; --r) {
        suffixMin[r] = min(suffixMin[r + 1], B[r + 1]);
    }

    for (int r = 0; r < N; ++r) {
        if (R[r] <= 0 &&
            prefixMax[r] <= (i128)r &&
            suffixMin[r] >= (i128)r) {
            return true;
        }
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;
        vector<ll> p(N);
        ll pmax = 0;
        for (ll& x : p) {
            cin >> x;
            pmax = max(pmax, x);
        }

        if (pmax == 0) {
            cout << 0 << '\n';
            continue;
        }

        int L = N - 1;

        // Two equal integral endpoint allocations give an always-feasible
        // upper bound: C*L >= pmax at every tile.
        ll C = (pmax + L - 1) / L;
        ll lo = 0, hi = 2 * C;

        // M is the smallest integer K feasible for the LP relaxation.
        while (lo < hi) {
            ll mid = lo + (hi - lo) / 2;
            if (getBounds(mid, p, L).ok) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }

        ll M = lo;
        // The integral optimum is always either M or M+1.
        ll answer = integralFeasible(M, p, L) ? M : M + 1;
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using i128 = __int128_t;
using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;
        vector<int64> p(N);
        int64 maxP = 0;
        for (int i = 0; i < N; i++) {
            cin >> p[i];
            maxP = max(maxP, p[i]);
        }

        const int L = N - 1;
        vector<int> diff(N + 2);

        auto feasible = [&](int64 k) -> bool {
            if (k == 0) return maxP == 0;

            const i128 K = (i128)k * L;
            i128 slo = 0, shi = K;

            // If S = q[0], then q[N-1] = k*L-S. Since q is convex,
            // q[i] is at most the linear interpolation of its endpoints.
            for (int i = 0; i < N; i++) {
                const int64 c = L - 2LL * i;
                const i128 R = (i128)L * (p[i] - (i128)i * k);

                if (c > 0) {
                    if (R > 0) {
                        i128 lower = (R + c - 1) / c;
                        slo = max(slo, lower);
                    }
                } else if (c < 0) {
                    if (R > 0) return false;
                    i128 upper = (-R) / (-c);
                    shi = min(shi, upper);
                } else {
                    if (R > 0) return false;
                }

                if (slo > shi || shi < 0 || slo > K) return false;
            }

            // Punches only at the two endpoints. Such a configuration exists
            // exactly when an integer multiple of L lies in [slo, shi].
            i128 v = (slo + L - 1) / L;
            if (v <= k && v * L <= shi) return true;

            if (L == 1) return false;

            // Otherwise [slo,shi] has length < L, so only O(1) values of v
            // need to be considered. A maximally spread configuration has
            // v punches at L, one punch at x, and all remaining punches at 0.
            i128 vs = slo / L - 1;
            i128 ve = shi / L + 1;
            int64 vStart = vs > 0 ? (int64)vs : 0;
            int64 vEnd = ve < (i128)(k - 1) ? (int64)ve : k - 1;
            vStart = max<int64>(vStart, 0);

            for (int64 cntRight = vStart; cntRight <= vEnd; cntRight++) {
                i128 baseS = (i128)cntRight * L;

                i128 xl = slo - baseS;
                i128 xr = shi - baseS;
                xl = max(xl, (i128)1);
                xr = min(xr, (i128)(L - 1));
                if (xl > xr) continue;

                int xlo = (int)xl;
                int xhi = (int)xr;

                fill(diff.begin(), diff.begin() + L + 2, 0);

                for (int i = 0; i < N; i++) {
                    i128 basePower =
                        (i128)(k - cntRight - 1) * (L - i) +
                        (i128)cntRight * i;
                    i128 d = (i128)p[i] - basePower;

                    if (d <= 0) continue;

                    // We need |i-x| >= d. Thus the following interval of x
                    // values is forbidden.
                    i128 left = (i128)i - d + 1;
                    i128 right = (i128)i + d - 1;
                    left = max(left, (i128)xlo);
                    right = min(right, (i128)xhi);

                    if (left <= right) {
                        diff[(int)left]++;
                        diff[(int)right + 1]--;
                    }
                }

                int active = 0;
                for (int x = xlo; x <= xhi; x++) {
                    active += diff[x];
                    if (active == 0) return true;
                }
            }

            return false;
        };

        int64 low = 0, high = 2 * maxP;
        while (low < high) {
            int64 mid = low + (high - low) / 2;
            if (feasible(mid)) high = mid;
            else low = mid + 1;
        }

        cout << low << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using i128 = __int128_t;
using int64 = long long;

struct Fraction {
    i128 num;
    int64 den; // always positive
};

static int cmpFraction(const Fraction &a, const Fraction &b) {
    i128 left = a.num * b.den;
    i128 right = b.num * a.den;
    if (left < right) return -1;
    if (left > right) return 1;
    return 0;
}

static i128 floorDiv(i128 a, int64 b) {
    if (a >= 0) return a / b;
    return -((-a + b - 1) / b);
}

static i128 ceilDiv(i128 a, int64 b) {
    if (a >= 0) return (a + b - 1) / b;
    return -((-a) / b);
}

struct TestSolver {
    int n;
    int64 L;
    vector<int64> p;

    bool getRealInterval(int64 m, Fraction &lower, Fraction &upper) const {
        lower = {0, 1};
        upper = {(i128)L * m, 1};

        for (int i = 0; i < n; ++i) {
            i128 mi = (i128)m * i;
            int64 d = L - 2LL * i;

            if (d == 0) {
                if ((i128)p[i] > mi) return false;
                continue;
            }

            i128 num = (i128)L * ((i128)p[i] - mi);
            Fraction f{num, d};
            if (f.den < 0) {
                f.den = -f.den;
                f.num = -f.num;
            }

            if (d > 0) {
                if (cmpFraction(f, lower) > 0) lower = f;
            } else {
                if (cmpFraction(f, upper) < 0) upper = f;
            }

            if (cmpFraction(lower, upper) > 0) return false;
        }
        return true;
    }

    bool feasible(int64 m) const {
        Fraction lower, upper;
        if (!getRealInterval(m, lower, upper)) return false;

        i128 aLo = ceilDiv(lower.num, lower.den);
        i128 aHi = floorDiv(upper.num, upper.den);
        if (aLo > aHi) return false;

        // If A is a multiple of L, punches only at the two endpoints suffice.
        i128 firstMultiple = ceilDiv(aLo, L) * L;
        if (firstMultiple <= aHi) return true;

        // Otherwise all possible A values have the same quotient b=A/L.
        i128 b = aLo / L;
        int64 rLo = (int64)(aLo % L);
        int64 rHi = (int64)(aHi % L);
        if (rLo > rHi || rLo <= 0 || rHi >= L) return false;

        // b punches at L, m-b-1 punches at 0, and one punch at r.
        // At tile i the power is base_i + |i-r|.
        vector<int> diff(L + 2, 0);

        for (int i = 0; i < n; ++i) {
            i128 base = (i128)(m - 1) * i + b * (L - 2LL * i);
            i128 need = (i128)p[i] - base;
            if (need <= 0) continue;

            // Every available r has |i-r| <= L-1.
            if (need >= L) return false;

            int64 t = (int64)need;
            int64 forbiddenL = max(rLo, (int64)i - t + 1);
            int64 forbiddenR = min(rHi, (int64)i + t - 1);

            if (forbiddenL <= forbiddenR) {
                ++diff[forbiddenL];
                --diff[forbiddenR + 1];
            }
        }

        int covered = 0;
        for (int64 r = rLo; r <= rHi; ++r) {
            covered += diff[r];
            if (covered == 0) return true;
        }
        return false;
    }

    int64 solve() const {
        int64 lo = 0, hi = 4000000000000000000LL;
        while (lo < hi) {
            int64 mid = lo + (hi - lo) / 2;
            if (feasible(mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<int64> p(n);
        for (auto &x : p) cin >> x;

        if (n == 2) {
            cout << p[0] + p[1] << '\n';
            continue;
        }

        TestSolver solver{n, n - 1, std::move(p)};
        cout << solver.solve() << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct Point {
    int x;
    int64 y;
};

struct Rational {
    i128 num = 0;
    i128 den = 1;
};

static i128 cross(const Point &a, const Point &b, const Point &c) {
    return (i128)(b.x - a.x) * (c.y - a.y)
         - (i128)(b.y - a.y) * (c.x - a.x);
}

// Continuous optimum for the given required powers.
static Rational continuousOptimum(const vector<int64> &p) {
    int n = (int)p.size();
    int L = n - 1;
    Rational best;

    auto relax = [&](i128 num, i128 den) {
        if (num * best.den > best.num * den) {
            best = {num, den};
        }
    };

    // Dual solutions supported on one tile.
    for (int i = 0; i < n; ++i) {
        int d = max(i, L - i);
        relax((i128)p[i], (i128)d);
    }

    // Upper concave hull of (i,p_i).
    vector<Point> hull;
    hull.reserve(n);
    for (int i = 0; i < n; ++i) {
        Point cur{i, p[i]};
        while (hull.size() >= 2 &&
               cross(hull[hull.size() - 2], hull.back(), cur) >= 0) {
            hull.pop_back();
        }
        hull.push_back(cur);
    }

    // Evaluate the hull at x=L/2.
    int pos = 0;
    while (pos + 1 < (int)hull.size() &&
           2 * hull[pos + 1].x < L) {
        ++pos;
    }

    Point a = hull[pos];
    Point b = hull[pos + 1];
    i128 num = (i128)a.y * (2 * b.x - L)
             + (i128)b.y * (L - 2 * a.x);
    i128 den = (i128)L * (b.x - a.x);
    relax(num, den);

    return best;
}

static void printInt128(i128 x) {
    if (x == 0) {
        cout << '0';
        return;
    }
    string s;
    while (x > 0) {
        s.push_back(char('0' + (int)(x % 10)));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<int64> p(n);
        for (auto &x : p) cin >> x;

        i128 answer = -1;
        vector<int64> adjusted(n);

        // K is the number of punches and a is the parity of the power at tile 0.
        // Every realizable sequence satisfies
        // f_i == a + i*K (mod 2).
        for (int kParity = 0; kParity <= 1; ++kParity) {
            for (int a = 0; a <= 1; ++a) {
                for (int i = 0; i < n; ++i) {
                    int wanted = (a + kParity * (i & 1)) & 1;
                    adjusted[i] = p[i] + (((int)(p[i] & 1) != wanted) ? 1 : 0);
                }

                Rational r = continuousOptimum(adjusted);
                i128 k = (r.num + r.den - 1) / r.den;
                if ((int)(k & 1) != kParity) ++k;

                if (answer == -1 || k < answer) answer = k;
            }
        }

        printInt128(answer);
        cout << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using i128 = __int128_t;

const int MAXN = 100005;

vector<long long> P;
int bestF[MAXN], bestU2[MAXN];
vector<int> stF, hullU2, hullP, stU1;

i128 floor_div(i128 a, i128 b) {
    // b > 0
    if (a >= 0) return a / b;
    return - ((-a + b - 1) / b);
}

i128 ceil_div(i128 a, i128 b) {
    // b > 0
    if (a >= 0) return (a + b - 1) / b;
    return - ((-a) / b);
}

bool feasible(int N, long long K) {
    int m = N - 1;
    int low_end = (m - 1) / 2;          // i with 2*i < m
    int high_start = m / 2 + 1;         // i with 2*i > m
    int mid_even = (m % 2 == 0) ? m / 2 : -1;

    stF.clear();
    hullU2.clear();
    int headU2 = 0;

    auto getA = [&](int i) -> i128 {
        return (i128)P[i] - (i128)(m - i) * K - 2 * i + m;
    };
    auto getC = [&](int i) -> i128 {
        return (i128)P[i] - (i128)(m - i) * K + m;
    };
    auto getAp = [&](int i) -> i128 {
        return -(i128)P[i] + (i128)(m - i) * K + 2 * i - m;
    };
    auto getCp = [&](int i) -> i128 {
        return -(i128)P[i] + (i128)(m - i) * K - m;
    };

    // Decreasing pass: compute bestF and bestU2
    for (int s = m; s >= 1; --s) {
        // F: max over i > s, i >= high_start
        while (stF.size() >= 2) {
            int i1 = stF.back();
            int i2 = stF[stF.size() - 2];
            i128 A1 = getA(i1), A2 = getA(i2);
            i128 c1 = 2 * i1 - m, c2 = 2 * i2 - m;
            if ((s + A1) * c2 <= (s + A2) * c1)
                stF.pop_back();
            else
                break;
        }

        int i = s + 1;
        if (i <= m && i >= high_start) {
            if (stF.empty()) {
                stF.push_back(i);
            } else {
                int b = stF.back();
                i128 Ai = getA(i), Ab = getA(b);
                i128 ci = 2 * i - m, cb = 2 * b - m;
                if ((s + Ai) * cb > (s + Ab) * ci)
                    stF.push_back(i);
            }
        }
        bestF[s] = stF.empty() ? -1 : stF.back();

        // U2: min over i > s, i <= low_end
        int k = s + 1;
        if (k <= low_end) {
            while ((int)hullU2.size() - headU2 >= 2) {
                int ii = hullU2[hullU2.size() - 2];
                int jj = hullU2.back();
                i128 di = m - 2 * ii, dj = m - 2 * jj, dk = m - 2 * k;
                i128 Ai = getAp(ii), Aj = getAp(jj), Ak = getAp(k);

                i128 left_num = di * Aj - dj * Ai;
                i128 left_den = dj - di;
                i128 right_num = dj * Ak - dk * Aj;
                i128 right_den = dk - dj;

                if (left_num * right_den >= right_num * left_den)
                    hullU2.pop_back();
                else
                    break;
            }
            hullU2.push_back(k);
        }

        while ((int)hullU2.size() - headU2 >= 2) {
            int ii = hullU2[headU2];
            int jj = hullU2[headU2 + 1];
            i128 di = m - 2 * ii, dj = m - 2 * jj;
            i128 Ai = getAp(ii), Aj = getAp(jj);
            if ((s - Ai) * dj <= (s - Aj) * di)
                ++headU2;
            else
                break;
        }
        if ((int)hullU2.size() > headU2)
            bestU2[s] = hullU2[headU2];
        else
            bestU2[s] = -1;
    }

    // Increasing pass: compute P, U1 and test each s
    hullP.clear();
    int headP = 0;
    stU1.clear();
    if (low_end >= 0) stU1.push_back(0);

    for (int s = 1; s <= m; ++s) {
        // P: max over i <= s, i >= high_start
        if (s >= high_start) {
            int k = s;
            while ((int)hullP.size() - headP >= 2) {
                int ii = hullP[hullP.size() - 2];
                int jj = hullP.back();
                i128 ci = 2 * ii - m, cj = 2 * jj - m, ck = 2 * k - m;
                i128 Ci = getC(ii), Cj = getC(jj), Ck = getC(k);

                i128 left_num = cj * Ci - ci * Cj;
                i128 left_den = cj - ci;
                i128 right_num = ck * Cj - cj * Ck;
                i128 right_den = ck - cj;

                if (left_num * right_den >= right_num * left_den)
                    hullP.pop_back();
                else
                    break;
            }
            hullP.push_back(k);
        }

        while ((int)hullP.size() - headP >= 2) {
            int ii = hullP[headP];
            int jj = hullP[headP + 1];
            i128 ci = 2 * ii - m, cj = 2 * jj - m;
            i128 Ci = getC(ii), Cj = getC(jj);
            if ((-s + Ci) * cj <= (-s + Cj) * ci)
                ++headP;
            else
                break;
        }
        int bestP = ((int)hullP.size() > headP) ? hullP[headP] : -1;

        // U1: min over i <= s, i <= low_end
        while (stU1.size() >= 2) {
            int i1 = stU1.back();
            int i2 = stU1[stU1.size() - 2];
            i128 d1 = m - 2 * i1, d2 = m - 2 * i2;
            i128 Cp1 = getCp(i1), Cp2 = getCp(i2);
            if ((s + Cp1) * d2 >= (s + Cp2) * d1)
                stU1.pop_back();
            else
                break;
        }

        if (s <= low_end) {
            int k = s;
            if (stU1.empty()) {
                stU1.push_back(k);
            } else {
                int b = stU1.back();
                i128 dk = m - 2 * k, db = m - 2 * b;
                i128 Cpk = getCp(k), Cpb = getCp(b);
                if ((s + Cpk) * db < (s + Cpb) * dk)
                    stU1.push_back(k);
            }
        }
        int bestU1 = stU1.empty() ? -1 : stU1.back();

        // Middle index constraint (only if m even)
        bool mid_ok = true;
        if (mid_even != -1) {
            int i = mid_even;
            i128 val = (i128)(m - i) * K + 2 * max(0, i - s) - m + s;
            if (val < P[i]) mid_ok = false;
        }
        if (!mid_ok) continue;

        i128 qmin = 0;

        if (bestF[s] != -1) {
            int i = bestF[s];
            i128 Ai = getA(i);
            i128 c = 2 * i - m;
            i128 q = ceil_div((i128)s + Ai, c);
            if (q > qmin) qmin = q;
        }
        if (bestP != -1) {
            int i = bestP;
            i128 Ci = getC(i);
            i128 c = 2 * i - m;
            i128 q = ceil_div(Ci - s, c);
            if (q > qmin) qmin = q;
        }

        i128 qmax = ((i128)1 << 120);

        if (bestU1 != -1) {
            int i = bestU1;
            i128 Cp = getCp(i);
            i128 d = m - 2 * i;
            i128 q = floor_div((i128)s + Cp, d);
            if (q < qmax) qmax = q;
        }
        if (bestU2[s] != -1) {
            int i = bestU2[s];
            i128 Ap = getAp(i);
            i128 d = m - 2 * i;
            i128 q = floor_div(Ap - s, d);
            if (q < qmax) qmax = q;
        }

        if (qmin < 0) qmin = 0;
        long long maxq_ll = K - (s < m ? 1 : 0);
        if (maxq_ll < 0) continue;
        if (qmax > (i128)maxq_ll) qmax = maxq_ll;

        if (qmin <= qmax) return true;
    }

    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;
        P.assign(N, 0);
        long long maxp = 0;
        for (int i = 0; i < N; ++i) {
            cin >> P[i];
            if (P[i] > maxp) maxp = P[i];
        }

        if (maxp == 0) {
            cout << 0 << '\n';
            continue;
        }

        long long lo = -1;
        long long hi = 2 * maxp; // always feasible

        while (hi - lo > 1) {
            long long mid = lo + (hi - lo) / 2;
            if (feasible(N, mid))
                hi = mid;
            else
                lo = mid;
        }

        cout << hi << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using i128 = __int128_t;

struct Line {
    long long a;     // numerator of slope
    i128 b;          // numerator of intercept
    long long d;     // positive denominator: value = (a*x + b) / d
};

static inline i128 value_num(const Line& L, long long x) {
    return (i128)L.a * x + L.b;
}

static inline bool ge_at(const Line& L1, const Line& L2, long long x) {
    return value_num(L1, x) * L2.d >= value_num(L2, x) * L1.d;
}

static inline bool leq_at(const Line& L1, const Line& L2, long long x) {
    return value_num(L1, x) * L2.d <= value_num(L2, x) * L1.d;
}

static inline i128 ceil_div_i128(i128 n, i128 d) {
    if (n >= 0) return (n + d - 1) / d;
    return -((-n) / d);
}

static inline bool bad(const Line& l1, const Line& l2, const Line& l3) {
    i128 num12 = l1.b * l2.d - l2.b * l1.d;
    i128 den12 = (i128)l2.a * l1.d - (i128)l1.a * l2.d;
    i128 num23 = l2.b * l3.d - l3.b * l2.d;
    i128 den23 = (i128)l3.a * l2.d - (i128)l2.a * l3.d;
    if (den12 <= 0 || den23 <= 0) return false;
    return num12 * den23 >= num23 * den12;
}

static inline void add_std(vector<Line>& hull, Line L) {
    while (!hull.empty()) {
        if ((i128)hull.back().a * L.d == (i128)L.a * hull.back().d) {
            if (hull.back().b * L.d >= L.b * hull.back().d) return;
            hull.pop_back();
        } else break;
    }
    while (hull.size() >= 2 && bad(hull[hull.size() - 2], hull.back(), L)) {
        hull.pop_back();
    }
    hull.push_back(L);
}

struct Solver {
    int N, m;
    vector<long long> p;

    Solver(int n, vector<long long>& pp) : N(n), m(n - 1), p(pp) {}

    bool check(long long S) {
        vector<i128> L(m + 1);
        for (int i = 0; i <= m; ++i) {
            i128 x = (i128)p[i] + (i128)S * i;
            L[i] = (x + 1) / 2; // ceil(x / 2)
        }

        const long long INF = 4'000'000'000'000'000'000LL;
        vector<long long> qlow(m + 1, -INF), qhigh(m + 1, INF);

        // Pass 1: future lower bounds (c < 0, i > t)
        {
            vector<Line> st;
            st.reserve(m + 1);
            for (int t = m; t >= 1; --t) {
                int i = t + 1;
                if (i <= m) {
                    int c = m - 2 * i;
                    if (c < 0) {
                        long long d = -c;
                        i128 A = -(i128)S * m + 2 * L[i] - 2 * i + m;
                        Line ln{1, A, d};
                        if (!st.empty() && leq_at(ln, st.back(), t)) {
                            // discard
                        } else {
                            st.push_back(ln);
                        }
                    }
                }
                while (st.size() >= 2 && ge_at(st[st.size() - 2], st.back(), t))
                    st.pop_back();
                if (!st.empty()) {
                    i128 num = (i128)st.back().a * t + st.back().b;
                    long long q = (long long)ceil_div_i128(num, st.back().d);
                    if (q > qlow[t]) qlow[t] = q;
                }
            }
        }

        // Pass 2: future upper bounds (c > 0, i > t)
        {
            vector<Line> hull;
            hull.reserve(m + 1);
            int ptr = 0;
            for (int t = m; t >= 1; --t) {
                int i = t + 1;
                if (i <= m) {
                    int c = m - 2 * i;
                    if (c > 0) {
                        long long d = c;
                        i128 A = -(i128)S * m + 2 * L[i] - 2 * i + m;
                        Line ln{-1, A, d};
                        add_std(hull, ln);
                    }
                }
                long long y = -t;
                if (!hull.empty()) {
                    if (ptr >= (int)hull.size()) ptr = (int)hull.size() - 1;
                    while (ptr + 1 < (int)hull.size() && ge_at(hull[ptr + 1], hull[ptr], y))
                        ++ptr;
                    i128 num = (i128)hull[ptr].a * y + hull[ptr].b;
                    i128 ceilv = ceil_div_i128(num, hull[ptr].d);
                    long long qh = -(long long)ceilv;
                    if (qh < qhigh[t]) qhigh[t] = qh;
                }
            }
        }

        // Pass 3: past lower bounds (c < 0, i <= t)
        {
            vector<Line> hull;
            hull.reserve(m + 1);
            int ptr = 0;
            for (int t = 1; t <= m; ++t) {
                int i = t;
                int c = m - 2 * i;
                if (c < 0) {
                    long long d = -c;
                    i128 A = -(i128)S * m + 2 * L[i] + m;
                    Line ln{-1, A, d};
                    add_std(hull, ln);
                }
                if (!hull.empty()) {
                    if (ptr >= (int)hull.size()) ptr = (int)hull.size() - 1;
                    while (ptr + 1 < (int)hull.size() && ge_at(hull[ptr + 1], hull[ptr], t))
                        ++ptr;
                    i128 num = (i128)hull[ptr].a * t + hull[ptr].b;
                    long long q = (long long)ceil_div_i128(num, hull[ptr].d);
                    if (q > qlow[t]) qlow[t] = q;
                }
            }
        }

        // Pass 4: past upper bounds (c > 0, i <= t)
        {
            vector<Line> st;
            st.reserve(m + 1);
            for (int t = 1; t <= m; ++t) {
                if (t == 1) {
                    int i = 0;
                    int c = m - 2 * i;
                    if (c > 0) {
                        long long d = c;
                        i128 A = -(i128)S * m + 2 * L[i] + m;
                        Line ln{1, A, d};
                        long long y = -t;
                        if (!st.empty() && leq_at(ln, st.back(), y)) {
                            // discard
                        } else {
                            st.push_back(ln);
                        }
                    }
                }
                int i = t;
                int c = m - 2 * i;
                if (c > 0) {
                    long long d = c;
                    i128 A = -(i128)S * m + 2 * L[i] + m;
                    Line ln{1, A, d};
                    long long y = -t;
                    if (!st.empty() && leq_at(ln, st.back(), y)) {
                        // discard
                    } else {
                        st.push_back(ln);
                    }
                }
                long long y = -t;
                while (st.size() >= 2 && ge_at(st[st.size() - 2], st.back(), y))
                    st.pop_back();
                if (!st.empty()) {
                    i128 num = (i128)st.back().a * y + st.back().b;
                    i128 ceilv = ceil_div_i128(num, st.back().d);
                    long long qh = -(long long)ceilv;
                    if (qh < qhigh[t]) qhigh[t] = qh;
                }
            }
        }

        // c == 0 constraints
        bool hasZero = (m % 2 == 0);
        int i0 = m / 2;
        i128 zero_low = 0, zero_high = 0;
        if (hasZero) {
            zero_low = 2 * L[i0] + m - (i128)S * m;
            zero_high = (i128)S * m - 2 * L[i0];
        }

        for (int t = 1; t <= m; ++t) {
            if (hasZero) {
                if (t >= i0) {
                    if ((i128)t < zero_low) continue;
                } else {
                    if ((i128)t > zero_high) continue;
                }
            }

            long long lo = qlow[t];
            long long hi = qhigh[t];
            if (lo < 0) lo = 0;

            long long qmax = (t == m ? S : S - 1);
            if (hi > qmax) hi = qmax;

            if (lo <= hi) return true;
        }

        return false;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<long long> p(N);
        for (int i = 0; i < N; ++i) cin >> p[i];

        Solver solver(N, p);

        long long lo = 0;
        long long hi = 4'000'000'000'000'000'000LL;

        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            if (solver.check(mid)) hi = mid;
            else lo = mid + 1;
        }

        cout << lo << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

i128 floor_div(i128 a, i128 b) {
    if (a >= 0) return a / b;
    return - ((-a + b - 1) / b);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int N;
        cin >> N;
        vector<int64> p(N);
        int64 maxp = 0;
        for (int i = 0; i < N; ++i) {
            cin >> p[i];
            maxp = max(maxp, p[i]);
        }

        int M = N - 1;

        auto check = [&](int64 S) -> bool {
            if (S == 0) {
                for (int i = 0; i < N; ++i)
                    if (p[i] != 0) return false;
                return true;
            }
            int64 s = S & 1;
            int64 K = (S - s) / 2;
            i128 Hmin = -(i128)M * (K + s);
            i128 Hmax = (i128)M * K;

            auto G = [&](i128 H) -> i128 {
                i128 q = floor_div(H, M);
                i128 r = H - q * M;
                i128 MK = (i128)M * K;
                i128 min_diff = ((i128)1 << 120);
                for (int i = 0; i <= M; ++i) {
                    i128 F = MK + q * (2LL * i - M) - r + (i128)i * s;
                    i128 extra = (i128)i + r - M;
                    if (extra > 0) F += 2 * extra;
                    i128 diff = F - p[i];
                    if (diff < min_diff) min_diff = diff;
                }
                return min_diff;
            };

            i128 l = Hmin, r = Hmax;
            while (r - l > 3) {
                i128 m1 = l + (r - l) / 3;
                i128 m2 = r - (r - l) / 3;
                i128 g1 = G(m1);
                i128 g2 = G(m2);
                if (g1 < g2) l = m1;
                else r = m2;
            }
            i128 best = -(((i128)1) << 120);
            for (i128 H = l; H <= r; ++H) {
                i128 g = G(H);
                if (g > best) best = g;
            }
            return best >= 0;
        };

        int64 lo = 0, hi = 2 * maxp;
        // ensure hi is feasible
        while (!check(hi)) {
            hi *= 2;
            if (hi == 0) hi = 1;
        }
        while (lo < hi) {
            int64 mid = lo + (hi - lo) / 2;
            if (check(mid)) hi = mid;
            else lo = mid + 1;
        }
        cout << lo << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

static i128 ceilDiv(i128 a, long long b) {
    if (a >= 0) return (a + b - 1) / b;
    return a / b;
}

static i128 floorDiv(i128 a, long long b) {
    if (a >= 0) return a / b;
    return -((-a + b - 1) / b);
}

struct Fraction {
    i128 num;
    long long den;
};

static int compareFractions(const Fraction& x, const Fraction& y) {
    i128 lhs = x.num * y.den;
    i128 rhs = y.num * x.den;
    return (lhs > rhs) - (lhs < rhs);
}

/*
    Represents the line
        y = (a*x + b) / d,  d > 0.

    All hulls used in this solution insert lines in strictly decreasing
    slope order. The query direction is fixed for each hull.
*/
struct Line {
    i128 b;
    int64 a, d;

    Line(int64 a_, i128 b_, int64 d_) : b(b_), a(a_), d(d_) {}
};

class MonotoneHull {
    bool maximum;
    vector<Line> lines;
    size_t head = 0;

    static int compareAt(const Line& x, const Line& y, int64 at) {
        i128 nx = x.b + (i128)x.a * at;
        i128 ny = y.b + (i128)y.a * at;
        i128 lhs = nx * y.d;
        i128 rhs = ny * x.d;
        return (lhs > rhs) - (lhs < rhs);
    }

    // x12 is the intersection of l1,l2; x23 is the intersection of l2,l3.
    bool redundant(const Line& l1, const Line& l2, const Line& l3) const {
        i128 n12 = l2.b * l1.d - l1.b * l2.d;
        i128 n23 = l3.b * l2.d - l2.b * l3.d;

        int64 q12 = l1.a * l2.d - l2.a * l1.d;
        int64 q23 = l2.a * l3.d - l3.a * l2.d;

        // Slopes are decreasing, so q12 and q23 are positive.
        if (maximum) {
            // For a maximum hull, x12 must be greater than x23.
            return n12 * q23 <= n23 * q12;
        } else {
            // For a minimum hull with decreasing slopes, x12 < x23.
            return n12 * q23 >= n23 * q12;
        }
    }

public:
    MonotoneHull(bool maximum_, size_t capacity = 0) : maximum(maximum_) {
        lines.reserve(capacity);
    }

    bool empty() const {
        return lines.size() == head;
    }

    void add(const Line& line) {
        while (lines.size() >= head + 2) {
            size_t n = lines.size();
            if (!redundant(lines[n - 2], lines[n - 1], line)) break;
            lines.pop_back();
        }
        lines.push_back(line);
    }

    // Query x values arrive in increasing order.
    Fraction queryIncreasing(int64 x) {
        if (maximum) {
            while (lines.size() >= head + 2) {
                size_t n = lines.size();
                if (compareAt(lines[n - 2], lines[n - 1], x) < 0) break;
                lines.pop_back();
            }
            const Line& line = lines.back();
            return {line.b + (i128)line.a * x, line.d};
        } else {
            while (lines.size() >= head + 2) {
                if (compareAt(lines[head + 1], lines[head], x) > 0) break;
                ++head;
            }
            const Line& line = lines[head];
            return {line.b + (i128)line.a * x, line.d};
        }
    }

    // Query x values arrive in decreasing order.
    Fraction queryDecreasing(int64 x) {
        if (maximum) {
            while (lines.size() >= head + 2) {
                if (compareAt(lines[head + 1], lines[head], x) < 0) break;
                ++head;
            }
            const Line& line = lines[head];
            return {line.b + (i128)line.a * x, line.d};
        } else {
            while (lines.size() >= head + 2) {
                size_t n = lines.size();
                if (compareAt(lines[n - 2], lines[n - 1], x) > 0) break;
                lines.pop_back();
            }
            const Line& line = lines.back();
            return {line.b + (i128)line.a * x, line.d};
        }
    }
};

/*
    Check whether K punches can break everything using only tiles 0 and L.

    q punches are placed at L, and K-q punches are placed at 0.
*/
static bool endpointFeasible(const vector<int64>& p, int64 K) {
    int L = (int)p.size() - 1;

    i128 lower = 0;
    i128 upper = K;

    for (int i = 0; i <= L; ++i) {
        if (2LL * i < L) {
            long long d = L - 2 * i;
            i128 numerator = (i128)p[i] - (i128)K * i;
            i128 needed = ceilDiv(numerator, d);
            if (needed > lower) lower = needed;
        } else if (2LL * i > L) {
            long long d = 2 * i - L;
            i128 numerator = (i128)K * i - p[i];
            i128 allowed = floorDiv(numerator, d);
            if (allowed < upper) upper = allowed;
        } else {
            if ((i128)K * i < p[i]) return false;
        }

        if (lower > upper) return false;
    }

    return lower <= upper;
}

/*
    Check whether K punches suffice when at most one punch is at an
    interior tile.

    For a remainder r:
      r = 0: q punches at L and K-q punches at 0.
      r > 0: q punches at L, one punch at r, and K-q-1 punches at 0.
*/
static bool interiorFeasible(const vector<int64>& p, int64 K) {
    int L = (int)p.size() - 1;

    if (K == 0) {
        for (int64 x : p) {
            if (x != 0) return false;
        }
        return true;
    }

    int positiveCount = (L + 1) / 2;
    int negativeCount = L - positiveCount;

    MonotoneHull leftPrefix(true, positiveCount);
    MonotoneHull leftSuffix(true, positiveCount);
    MonotoneHull rightSuffix(false, negativeCount);
    MonotoneHull rightPrefix(false, negativeCount);

    vector<Fraction> lower(L), upper(L);
    for (int r = 0; r < L; ++r) {
        lower[r] = {0, 1};
        upper[r] = {(i128)K, 1};
    }

    // Lower bounds from left-side tiles with i <= r.
    for (int r = 0; r < L; ++r) {
        if (2LL * r < L) {
            long long d = L - 2 * r;
            i128 b = (i128)p[r] - ((i128)K - 2) * r;
            leftPrefix.add(Line(-1, b, d));
        }

        Fraction value = leftPrefix.queryIncreasing(r);
        if (compareFractions(value, lower[r]) > 0) lower[r] = value;
    }

    // Lower bounds from left-side tiles with i >= r.
    for (int r = L - 1; r >= 0; --r) {
        if (2LL * r < L) {
            long long d = L - 2 * r;
            i128 b = (i128)p[r] - (i128)K * r;
            leftSuffix.add(Line(1, b, d));
        }

        if (!leftSuffix.empty()) {
            Fraction value = leftSuffix.queryDecreasing(r);
            if (compareFractions(value, lower[r]) > 0) lower[r] = value;
        }
    }

    // Upper bounds from right-side tiles with i >= r.
    // Start at i=L because tile L belongs to this suffix for every r.
    for (int r = L; r >= 0; --r) {
        if (2LL * r > L) {
            long long d = 2 * r - L;
            i128 b = (i128)K * r - p[r];
            rightSuffix.add(Line(-1, b, d));
        }

        if (r < L && !rightSuffix.empty()) {
            Fraction value = rightSuffix.queryDecreasing(r);
            if (compareFractions(value, upper[r]) < 0) upper[r] = value;
        }
    }

    // Upper bounds from right-side tiles with i <= r.
    for (int r = 0; r < L; ++r) {
        if (2LL * r > L) {
            long long d = 2 * r - L;
            i128 b = ((i128)K - 2) * r - p[r];
            rightPrefix.add(Line(1, b, d));
        }

        if (!rightPrefix.empty()) {
            Fraction value = rightPrefix.queryIncreasing(r);
            if (compareFractions(value, upper[r]) < 0) upper[r] = value;
        }
    }

    for (int r = 0; r < L; ++r) {
        // If L is even, the middle tile has no q term.
        if (L % 2 == 0) {
            int middle = L / 2;
            i128 power;
            if (r < middle) {
                power = (i128)K * middle - r;
            } else {
                power = ((i128)K - 2) * middle + r;
            }
            if (power < p[middle]) continue;
        }

        i128 smallestQ = ceilDiv(lower[r].num, lower[r].den);
        i128 largestQ = floorDiv(upper[r].num, upper[r].den);

        i128 cap = (r == 0 ? (i128)K : (i128)K - 1);
        if (largestQ > cap) largestQ = cap;

        if (smallestQ <= largestQ) return true;
    }

    return false;
}

static int64 solve(const vector<int64>& p) {
    int L = (int)p.size() - 1;
    int64 maxP = *max_element(p.begin(), p.end());

    // M punches at each endpoint give every tile at least M*L power.
    int64 M = (maxP + L - 1) / L;

    // Necessary lower bounds for endpoint-only solutions.
    int64 low = (int64)(((i128)p[0] + p[L] + L - 1) / L);
    for (int i = 0; i <= L; ++i) {
        int64 maxDistance = max(i, L - i);
        int64 needed = (p[i] + maxDistance - 1) / maxDistance;
        low = max(low, needed);
    }

    // A potentially tighter endpoint-only feasible upper bound.
    int64 A = (p[L] + L - 1) / L; // punches at 0
    int64 B = (p[0] + L - 1) / L; // punches at L
    i128 maxDeficit = 0;
    for (int i = 0; i <= L; ++i) {
        i128 base = (i128)A * i + (i128)B * (L - i);
        maxDeficit = max(maxDeficit, (i128)p[i] - base);
    }
    int64 extra = (int64)((maxDeficit + L - 1) / L);
    i128 candidate = (i128)A + B + 2 * extra;
    i128 high128 = min((i128)2 * M, candidate);
    int64 high = (int64)high128;

    // Find the minimum using only endpoint punches.
    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (endpointFeasible(p, mid)) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    int64 endpoint optimum = low;

    if (endpointOptimum == 0) return 0;

    // The unrestricted optimum is either E or E-1.
    if (interiorFeasible(p, endpointOptimum - 1)) {
        return endpointOptimum - 1;
    }
    return endpointOptimum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;
        vector<int64> p(N);
        for (int64& x : p) cin >> x;
        cout << solve(p) << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

static i128 ceilDiv(i128 a, int64 b) {
    i128 q = a / b;
    i128 r = a % b;
    if (r > 0) ++q;
    return q;
}

static i128 floorDiv(i128 a, int64 b) {
    i128 q = a / b;
    i128 r = a % b;
    if (r < 0) --q;
    return q;
}

/*
    A line represents the rational function

        (slope * x + b) / den,    den > 0.

    The Li Chao tree maintains either the maximum or the minimum.
*/
class LiChao {
    struct Line {
        i128 b;
        int slope;
        int den;
    };

    int n;
    bool maximize;
    vector<Line> lines;
    vector<int> tree;

    bool better(int id1, int id2, int x) const {
        const Line &a = lines[id1];
        const Line &b = lines[id2];

        i128 lhs = (a.b + (i128)a.slope * x) * b.den;
        i128 rhs = (b.b + (i128)b.slope * x) * a.den;

        return maximize ? lhs > rhs : lhs < rhs;
    }

    void insert(int id, int node, int l, int r) {
        if (tree[node] == -1) {
            tree[node] = id;
            return;
        }

        int mid = (l + r) / 2;
        bool leftBetter = better(id, tree[node], l);
        bool midBetter = better(id, tree[node], mid);

        if (midBetter) swap(id, tree[node]);

        if (l == r) return;

        if (leftBetter != midBetter) {
            insert(id, node * 2, l, mid);
        } else {
            insert(id, node * 2 + 1, mid + 1, r);
        }
    }

public:
    struct Bound {
        i128 num = 0;
        int den = 0;  // den == 0 means empty
    };

    LiChao(int domainSize, bool findMaximum)
        : n(domainSize), maximize(findMaximum), tree(4 * domainSize + 5, -1) {
        lines.reserve(domainSize);
    }

    void clear() {
        lines.clear();
        fill(tree.begin(), tree.end(), -1);
    }

    void add(int slope, i128 b, int den) {
        lines.push_back({b, slope, den});
        insert((int)lines.size() - 1, 1, 0, n - 1);
    }

    Bound query(int x) const {
        int node = 1, l = 0, r = n - 1;
        int best = -1;

        while (true) {
            int id = tree[node];
            if (id == -1) break;

            if (best == -1 || better(id, best, x)) best = id;

            if (l == r) break;

            int mid = (l + r) / 2;
            if (x <= mid) {
                node *= 2;
                r = mid;
            } else {
                node = node * 2 + 1;
                l = mid + 1;
            }
        }

        if (best == -1) return {};

        return {
            lines[best].b + (i128)lines[best].slope * x,
            lines[best].den
        };
    }
};

static bool fractionGreater(const LiChao::Bound &a,
                             const LiChao::Bound &b) {
    return a.num * b.den > b.num * a.den;
}

static bool fractionLess(const LiChao::Bound &a,
                         const LiChao::Bound &b) {
    return a.num * b.den < b.num * a.den;
}

/*
    Is there a fractional endpoint solution with exactly C total punches?

    u punches at 0, v punches at L=N-1, with u+v=C.
    Equivalently, u=C-v.
*/
static bool fractionalEndpointFeasible(int64 C,
                                       const vector<int64> &p,
                                       int L) {
    i128 lowNum = 0;
    int lowDen = 1;

    i128 highNum = C;
    int highDen = 1;

    for (int i = 0; i <= L; ++i) {
        int d = L - 2 * i;

        if (d > 0) {
            // v >= (p[i] - C*i) / d
            i128 num = (i128)p[i] - (i128)C * i;
            if (num * lowDen > lowNum * d) {
                lowNum = num;
                lowDen = d;
            }
        } else if (d < 0) {
            // v <= (C*i - p[i]) / (2*i-L)
            i128 num = (i128)C * i - p[i];
            int den = -d;
            if (num * highDen < highNum * den) {
                highNum = num;
                highDen = den;
            }
        } else {
            if ((i128)C * i < p[i]) return false;
        }
    }

    return lowNum * highDen <= highNum * lowDen;
}

/*
    Quick check using only endpoint punches.
    q punches are at L and C-q punches are at 0.
*/
static bool integerEndpointFeasible(int64 C,
                                     const vector<int64> &p,
                                     int L) {
    i128 low = 0;
    i128 high = C;

    for (int i = 0; i <= L; ++i) {
        int d = L - 2 * i;

        if (d > 0) {
            i128 need = ceilDiv((i128)p[i] - (i128)C * i, d);
            low = max(low, need);
        } else if (d < 0) {
            i128 bound = floorDiv((i128)C * i - p[i], -d);
            high = min(high, bound);
        } else {
            if ((i128)C * i < p[i]) return false;
        }
    }

    return low <= high;
}

/*
    Check whether k punches suffice.

    By the canonicalization argument, it is enough to consider:
      - q ordinary punches at L,
      - one special punch at r,
      - k-1-q ordinary punches at 0,

    where 0 <= q <= k-1 and 0 <= r <= L.

    Their power at tile i is

        (k-1)*i + q*(L-2*i) + abs(i-r).
*/
static bool canonicalFeasible(int64 k,
                              const vector<int64> &p,
                              int L) {
    int N = L + 1;

    if (integerEndpointFeasible(k, p, L)) return true;

    LiChao maxLeft(N, true);
    LiChao minRight(N, false);

    vector<LiChao::Bound> prefixMax(N), prefixMin(N);

    i128 km2 = (i128)k - 2;
    i128 kk = (i128)k;

    // Prefix envelopes: indices i <= r.
    for (int r = 0; r <= L; ++r) {
        int i = r;

        if (2 * i < L) {
            int den = L - 2 * i;
            i128 b = (i128)p[i] - km2 * i;
            maxLeft.add(-1, b, den);
        } else if (2 * i > L) {
            int den = 2 * i - L;
            i128 b = km2 * i - p[i];
            minRight.add(1, b, den);
        }

        prefixMax[r] = maxLeft.query(r);
        prefixMin[r] = minRight.query(r);
    }

    maxLeft.clear();
    minRight.clear();

    // Suffix envelopes: indices i > r.
    for (int r = L; r >= 0; --r) {
        LiChao::Bound suffixMax = maxLeft.query(r);
        LiChao::Bound suffixMin = minRight.query(r);

        // Add tile r to the suffix for the next iteration.
        int i = r;
        if (2 * i < L) {
            int den = L - 2 * i;
            i128 b = (i128)p[i] - kk * i;
            maxLeft.add(1, b, den);
        } else if (2 * i > L) {
            int den = 2 * i - L;
            i128 b = kk * i - p[i];
            minRight.add(-1, b, den);
        }

        LiChao::Bound lowerBound = prefixMax[r];
        if (suffixMax.den != 0 &&
            (lowerBound.den == 0 ||
             fractionGreater(suffixMax, lowerBound))) {
            lowerBound = suffixMax;
        }

        LiChao::Bound upperBound = prefixMin[r];
        if (suffixMin.den != 0 &&
            (upperBound.den == 0 ||
             fractionLess(suffixMin, upperBound))) {
            upperBound = suffixMin;
        }

        if (lowerBound.den == 0 || upperBound.den == 0) continue;

        // The middle tile imposes a condition independent of q.
        if (L % 2 == 0) {
            int mid = L / 2;
            i128 power = (i128)(k - 1) * mid + abs(mid - r);
            if (power < p[mid]) continue;
        }

        i128 low = ceilDiv(lowerBound.num, lowerBound.den);
        i128 high = floorDiv(upperBound.num, upperBound.den);

        if (low < 0) low = 0;
        if (high > (i128)k - 1) high = (i128)k - 1;

        if (low <= high) return true;
    }

    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<int64> p(N);
        int64 maxP = 0;
        for (int i = 0; i < N; ++i) {
            cin >> p[i];
            maxP = max(maxP, p[i]);
        }

        if (maxP == 0) {
            cout << 0 << '\n';
            continue;
        }

        int L = N - 1;

        // Lower bound: one punch contributes at most max(i, L-i).
        int64 low = 0;
        for (int i = 0; i < N; ++i) {
            int64 maxDistance = max(i, L - i);
            int64 need = (p[i] + maxDistance - 1) / maxDistance;
            low = max(low, need);
        }

        // u=v=maxP is always a feasible fractional endpoint solution.
        int64 high = 2 * maxP;

        while (low < high) {
            int64 mid = low + (high - low) / 2;
            if (fractionalEndpointFeasible(mid, p, L)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        int64 K = low;

        if (canonicalFeasible(K, p, L)) {
            cout << K << '\n';
        } else {
            cout << K + 1 << '\n';
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

/*
    A line represents
        f(x) = (a*x + b) / den,  den > 0.

    Slopes are always inserted in increasing order.
*/
struct Line {
    i128 b;
    int a;
    int den;
};

struct Fraction {
    i128 num;
    int den;
};

static i128 ceil_div(i128 a, i128 b) {
    if (a >= 0) return (a + b - 1) / b;
    return a / b;
}

static i128 floor_div(i128 a, i128 b) {
    if (a >= 0) return a / b;
    return -((-a + b - 1) / b);
}

/*
    Monotone convex hull.

    isMax = true:  maximum envelope
    isMax = false: minimum envelope

    pointerMode = true:
        Queries move toward lines with larger slopes.

    pointerMode = false:
        Queries move toward lines with smaller slopes, so dominated
        lines can be permanently removed from the back.
*/
class MonotoneHull {
    bool isMax;
    bool pointerMode;
    vector<Line> hull;
    size_t ptr = 0;

    static bool value_ge(const Line& x, const Line& y, int pos) {
        i128 nx = (i128)x.a * pos + x.b;
        i128 ny = (i128)y.a * pos + y.b;
        return nx * y.den >= ny * x.den;
    }

    static bool value_le(const Line& x, const Line& y, int pos) {
        i128 nx = (i128)x.a * pos + x.b;
        i128 ny = (i128)y.a * pos + y.b;
        return nx * y.den <= ny * x.den;
    }

    // Intersection of consecutive lines, with positive denominator.
    static void intersection(const Line& x, const Line& y,
                             i128& numerator, i128& denominator) {
        denominator = (i128)y.a * x.den - (i128)x.a * y.den;
        numerator = x.b * y.den - y.b * x.den;
    }

    static bool bad_max(const Line& x, const Line& y, const Line& z) {
        i128 n12, d12, n23, d23;
        intersection(x, y, n12, d12);
        intersection(y, z, n23, d23);

        // The middle line is unnecessary if intersection(x,y) >= intersection(y,z).
        return n12 * d23 >= n23 * d12;
    }

    static bool bad_min(const Line& x, const Line& y, const Line& z) {
        i128 n12, d12, n23, d23;
        intersection(x, y, n12, d12);
        intersection(y, z, n23, d23);

        // The middle line is unnecessary if intersection(y,z) >= intersection(x,y).
        return n23 * d12 >= n12 * d23;
    }

public:
    MonotoneHull(bool maximum, bool use_pointer)
        : isMax(maximum), pointerMode(use_pointer) {}

    void reserve(int n) {
        hull.reserve(n);
    }

    void clear() {
        hull.clear();
        ptr = 0;
    }

    bool empty() const {
        return hull.empty();
    }

    void add(Line line) {
        while (hull.size() >= 2) {
            bool bad = isMax
                ? bad_max(hull[hull.size() - 2], hull.back(), line)
                : bad_min(hull[hull.size() - 2], hull.back(), line);

            if (!bad) break;
            hull.pop_back();
        }

        hull.push_back(line);

        if (pointerMode && ptr >= hull.size()) {
            ptr = hull.size() - 1;
        }
    }

    const Line& get(int x) {
        if (pointerMode) {
            while (ptr + 1 < hull.size()) {
                bool next_better = isMax
                    ? value_ge(hull[ptr + 1], hull[ptr], x)
                    : value_le(hull[ptr + 1], hull[ptr], x);

                if (!next_better) break;
                ++ptr;
            }
            return hull[ptr];
        }

        while (hull.size() >= 2) {
            const Line& previous = hull[hull.size() - 2];
            const Line& last = hull.back();

            bool remove_last = isMax
                ? value_ge(previous, last, x)
                : value_le(previous, last, x);

            if (!remove_last) break;
            hull.pop_back();
        }

        return hull.back();
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<int64> p(N);
        int64 maximumPower = 0;

        for (int i = 0; i < N; ++i) {
            cin >> p[i];
            maximumPower = max(maximumPower, p[i]);
        }

        if (maximumPower == 0) {
            cout << 0 << '\n';
            continue;
        }

        const int L = N - 1;

        /*
            Necessary lower bounds:
              1. A punch contributes at most max(i, L-i) to tile i.
              2. The total power at the two endpoints is exactly K*L.
        */
        int64 low = 1;

        for (int i = 0; i < N; ++i) {
            int64 maximumDistance = max(i, L - i);
            int64 needed = (p[i] + maximumDistance - 1) / maximumDistance;
            low = max(low, needed);
        }

        i128 endpointSum = (i128)p[0] + p[L];
        low = max(low, (int64)((endpointSum + L - 1) / L));

        /*
            M punches at tile 0 and M punches at tile L give every tile
            M*i + M*(L-i) = M*L power.
        */
        int64 M = (maximumPower + L - 1) / L;
        int64 high = 2 * M;

        vector<Fraction> prefixF(L + 1);
        vector<Fraction> prefixG(L + 1);

        MonotoneHull fPrefix(true, true);    // Maximum, pointer queries.
        MonotoneHull gPrefix(false, false);   // Minimum, popping queries.
        MonotoneHull fSuffix(true, false);    // Maximum, popping queries.
        MonotoneHull gSuffix(false, true);    // Minimum, pointer queries.

        fPrefix.reserve(L + 1);
        gPrefix.reserve(L + 1);
        fSuffix.reserve(L + 1);
        gSuffix.reserve(L + 1);

        auto feasible = [&](int64 K) -> bool {
            i128 m = (i128)K - 1;

            fill(prefixF.begin(), prefixF.end(), Fraction{0, 0});
            fill(prefixG.begin(), prefixG.end(), Fraction{0, 0});

            fPrefix.clear();
            gPrefix.clear();
            fSuffix.clear();
            gSuffix.clear();

            // Prefix envelopes: indices i <= x.
            for (int x = 0; x <= L; ++x) {
                int coefficient = 2 * x - L;

                if (coefficient > 0) {
                    i128 c = (i128)p[x] - m * (L - x);
                    fPrefix.add(Line{c + x, -1, coefficient});
                } else if (coefficient < 0) {
                    i128 d = m * (L - x) - p[x];
                    gPrefix.add(Line{d - x, 1, -coefficient});
                }

                if (!fPrefix.empty()) {
                    const Line& line = fPrefix.get(x);
                    i128 num = (i128)line.a * x + line.b;

                    Fraction& best = prefixF[x];
                    if (best.den == 0 ||
                        num * best.den > best.num * line.den) {
                        best = Fraction{num, line.den};
                    }
                }

                if (!gPrefix.empty()) {
                    const Line& line = gPrefix.get(x);
                    i128 num = (i128)line.a * x + line.b;

                    Fraction& best = prefixG[x];
                    if (best.den == 0 ||
                        num * best.den < best.num * line.den) {
                        best = Fraction{num, line.den};
                    }
                }
            }

            // Suffix envelopes: indices i >= x.
            for (int x = L; x >= 0; --x) {
                int coefficient = 2 * x - L;

                Fraction F = prefixF[x];
                Fraction G = prefixG[x];

                if (coefficient > 0) {
                    i128 c = (i128)p[x] - m * (L - x);
                    fSuffix.add(Line{c - x, 1, coefficient});

                    const Line& line = fSuffix.get(x);
                    i128 num = (i128)line.a * x + line.b;

                    if (F.den == 0 ||
                        num * F.den > F.num * line.den) {
                        F = Fraction{num, line.den};
                    }
                } else if (coefficient < 0) {
                    i128 d = m * (L - x) - p[x];
                    gSuffix.add(Line{d + x, -1, -coefficient});

                    const Line& line = gSuffix.get(x);
                    i128 num = (i128)line.a * x + line.b;

                    if (G.den == 0 ||
                        num * G.den < G.num * line.den) {
                        G = Fraction{num, line.den};
                    }
                }

                if (F.den == 0 || G.den == 0) continue;

                // If L is even, the middle tile gives no bound on q.
                if (L % 2 == 0) {
                    int middle = L / 2;
                    i128 power = m * middle + abs(middle - x);
                    if ((i128)p[middle] > power) continue;
                }

                i128 minimumQ = ceil_div(F.num, F.den);
                i128 maximumQ = floor_div(G.num, G.den);

                if (minimumQ < 0) minimumQ = 0;
                if (maximumQ > m) maximumQ = m;

                if (minimumQ <= maximumQ) return true;
            }

            return false;
        };

        while (low < high) {
            int64 mid = low + (high - low) / 2;
            if (feasible(mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        cout << low << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Node {
    Node *l, *r;
    ll len, sz, sum;
    int slope, mn, mx;
    unsigned pri;
    int lazyA;
    ll lazyB;
    bool rev;
};

static Node* pool;
static int poolPtr = 0;
static unsigned rngState = 123456789u;

static inline unsigned rnd() {
    rngState ^= rngState << 13;
    rngState ^= rngState >> 17;
    rngState ^= rngState << 5;
    return rngState;
}

static inline ll sz(Node* t) {
    return t ? t->sz : 0;
}

static Node* makeNode(ll len, int slope) {
    if (len <= 0) return nullptr;
    Node* t = &pool[poolPtr++];
    t->l = t->r = nullptr;
    t->len = t->sz = len;
    t->slope = t->mn = t->mx = slope;
    t->sum = (ll)slope * len;
    t->pri = rnd();
    t->lazyA = 1;
    t->lazyB = 0;
    t->rev = false;
    return t;
}

static inline void pull(Node* t) {
    t->sz = t->len + sz(t->l) + sz(t->r);
    t->sum = (ll)t->slope * t->len;
    t->mn = t->mx = t->slope;
    if (t->l) {
        t->sum += t->l->sum;
        t->mn = min(t->mn, t->l->mn);
        t->mx = max(t->mx, t->l->mx);
    }
    if (t->r) {
        t->sum += t->r->sum;
        t->mn = min(t->mn, t->r->mn);
        t->mx = max(t->mx, t->r->mx);
    }
}

// Replaces every slope s in the subtree by a*s+b.
static void apply(Node* t, int a, ll b) {
    if (!t) return;
    t->slope = (int)(a * (ll)t->slope + b);
    t->sum = a * t->sum + b * t->sz;
    if (a == 1) {
        t->mn = (int)(t->mn + b);
        t->mx = (int)(t->mx + b);
    } else {
        int oldMn = t->mn, oldMx = t->mx;
        t->mn = (int)(-oldMx + b);
        t->mx = (int)(-oldMn + b);
    }
    t->lazyA *= a;
    t->lazyB = a * t->lazyB + b;
}

static inline void push(Node* t) {
    if (!t) return;
    if (t->rev) {
        swap(t->l, t->r);
        if (t->l) t->l->rev ^= 1;
        if (t->r) t->r->rev ^= 1;
        t->rev = false;
    }
    if (t->lazyA != 1 || t->lazyB != 0) {
        apply(t->l, t->lazyA, t->lazyB);
        apply(t->r, t->lazyA, t->lazyB);
        t->lazyA = 1;
        t->lazyB = 0;
    }
}

static Node* merge(Node* a, Node* b) {
    if (!a) return b;
    if (!b) return a;
    if (a->pri > b->pri) {
        push(a);
        a->r = merge(a->r, b);
        pull(a);
        return a;
    } else {
        push(b);
        b->l = merge(a, b->l);
        pull(b);
        return b;
    }
}

// Splits into the first k units of length and the remainder.
static void split(Node* t, ll k, Node*& a, Node*& b) {
    if (!t) {
        a = b = nullptr;
        return;
    }
    push(t);
    ll leftSize = sz(t->l);
    if (k < leftSize) {
        split(t->l, k, a, t->l);
        b = t;
        pull(b);
        return;
    }
    if (k > leftSize + t->len) {
        split(t->r, k - leftSize - t->len, t->r, b);
        a = t;
        pull(a);
        return;
    }

    ll take = k - leftSize;
    if (take == 0) {
        a = t->l;
        t->l = nullptr;
        b = t;
        pull(b);
    } else if (take == t->len) {
        b = t->r;
        t->r = nullptr;
        a = t;
        pull(a);
    } else {
        Node* rightPart = makeNode(t->len - take, t->slope);
        rightPart->r = t->r;
        pull(rightPart);
        t->len = take;
        t->r = nullptr;
        a = t;
        b = rightPart;
        pull(a);
    }
}

// Returns the length before the first segment whose slope is at least c.
static ll firstGE(Node* t, ll c) {
    if (!t || t->mx < c) return sz(t);
    push(t);
    if (t->l && t->l->mx >= c) return firstGE(t->l, c);
    ll leftSize = sz(t->l);
    if (t->slope >= c) return leftSize;
    return leftSize + t->len + firstGE(t->r, c);
}

static ll prefixSum(Node* t, ll k) {
    if (!t || k <= 0) return 0;
    push(t);
    ll leftSize = sz(t->l);
    if (k <= leftSize) return prefixSum(t->l, k);

    ll result = t->l ? t->l->sum : 0;
    k -= leftSize;
    if (k <= t->len) return result + (ll)t->slope * k;

    result += (ll)t->slope * t->len;
    return result + prefixSum(t->r, k - t->len);
}

static inline ll evaluate(Node* t, ll base, int lastSlope, ll length, ll d) {
    if (d >= length) {
        return base + (t ? t->sum : 0) + (ll)lastSlope * (d - length);
    }
    return base + prefixSum(t, d);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<ll> w(N + 1), c(N);
    for (int i = 1; i <= N; ++i) cin >> w[i];
    for (int i = 1; i < N; ++i) cin >> c[i];

    pool = new Node[2 * N + 5];

    // V_2(d) = c_1 * max(w_1,d).  Its derivative is represented by T.
    ll base = c[1] * w[1];
    ll length = w[1];
    int lastSlope = (int)c[1];
    Node* T = makeNode(length, 0);

    string output;
    output.reserve((size_t)N * 12);
    output += to_string(evaluate(T, base, lastSlope, length, w[2]));
    output.push_back('\n');

    for (int j = 2; j < N; ++j) {
        ll W = w[j];
        ll cost = c[j];

        // Restrict the derivative to [0,W], extending with its final slope if needed.
        if (W < length) {
            Node *P, *discarded;
            split(T, W, P, discarded);
            T = P;
        } else if (W > length) {
            T = merge(T, makeNode(W - length, lastSlope));
        }

        // Remove the suffix with slopes >= cost.  It becomes a flat prefix.
        ll pos = firstGE(T, cost);
        Node *A, *X;
        if (pos == 0) {
            A = nullptr;
            X = T;
        } else if (pos == W) {
            A = T;
            X = nullptr;
        } else {
            split(T, pos, A, X);
        }

        ll flatLength = sz(X);
        base += (A ? A->sum : 0) + cost * flatLength;

        // Reverse the remaining segments and replace every slope s by cost-s.
        if (A) {
            apply(A, -1, cost);
            A->rev ^= 1;
        }
        T = merge(makeNode(flatLength, 0), A);

        length = W;
        lastSlope = (int)cost;

        output += to_string(evaluate(T, base, lastSlope, length, w[j + 1]));
        output.push_back('\n');
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Node {
    int l = 0, r = 0;
    unsigned priority = 0;
    ll len = 0, slope = 0;
    ll sumLen = 0, sumArea = 0;
    ll minSlope = 0, maxSlope = 0;
    int lazyA = 1;
    ll lazyB = 0;
    bool rev = false;
};

struct FunctionTreap {
    vector<Node> tr;
    mt19937 rng{712367821};

    FunctionTreap(int n) {
        tr.reserve(2 * n + 10);
        tr.emplace_back();
    }

    int newNode(ll len, ll slope) {
        Node x;
        x.len = x.sumLen = len;
        x.slope = x.minSlope = x.maxSlope = slope;
        x.sumArea = len * slope;
        x.priority = rng();
        tr.push_back(x);
        return (int)tr.size() - 1;
    }

    ll getLen(int t) const { return t ? tr[t].sumLen : 0; }
    ll getArea(int t) const { return t ? tr[t].sumArea : 0; }

    void pull(int t) {
        if (!t) return;
        Node &x = tr[t];
        x.sumLen = x.len + getLen(x.l) + getLen(x.r);
        x.sumArea = x.slope * x.len + getArea(x.l) + getArea(x.r);
        x.minSlope = x.maxSlope = x.slope;
        if (x.l) {
            x.minSlope = min(x.minSlope, tr[x.l].minSlope);
            x.maxSlope = max(x.maxSlope, tr[x.l].maxSlope);
        }
        if (x.r) {
            x.minSlope = min(x.minSlope, tr[x.r].minSlope);
            x.maxSlope = max(x.maxSlope, tr[x.r].maxSlope);
        }
    }

    void applyReverse(int t) {
        if (!t) return;
        swap(tr[t].l, tr[t].r);
        tr[t].rev = !tr[t].rev;
    }

    // Replace every slope s by a*s+b.
    void applyAffine(int t, int a, ll b) {
        if (!t) return;
        Node &x = tr[t];
        x.slope = a * x.slope + b;
        x.sumArea = a * x.sumArea + b * x.sumLen;
        if (a == 1) {
            x.minSlope += b;
            x.maxSlope += b;
        } else {
            ll oldMin = x.minSlope, oldMax = x.maxSlope;
            x.minSlope = b - oldMax;
            x.maxSlope = b - oldMin;
        }
        x.lazyB = a * x.lazyB + b;
        x.lazyA = a * x.lazyA;
    }

    void push(int t) {
        if (!t) return;
        if (tr[t].rev) {
            applyReverse(tr[t].l);
            applyReverse(tr[t].r);
            tr[t].rev = false;
        }
        if (tr[t].lazyA != 1 || tr[t].lazyB != 0) {
            int a = tr[t].lazyA;
            ll b = tr[t].lazyB;
            applyAffine(tr[t].l, a, b);
            applyAffine(tr[t].r, a, b);
            tr[t].lazyA = 1;
            tr[t].lazyB = 0;
        }
    }

    int merge(int a, int b) {
        if (!a) return b;
        if (!b) return a;
        if (tr[a].priority > tr[b].priority) {
            push(a);
            tr[a].r = merge(tr[a].r, b);
            pull(a);
            return a;
        } else {
            push(b);
            tr[b].l = merge(a, tr[b].l);
            pull(b);
            return b;
        }
    }

    // Split so that the first returned tree has total length k.
    pair<int, int> splitLen(int t, ll k) {
        if (!t) return {0, 0};
        if (k <= 0) return {0, t};
        if (k >= tr[t].sumLen) return {t, 0};

        push(t);
        ll leftLen = getLen(tr[t].l);

        if (k <= leftLen) {
            auto p = splitLen(tr[t].l, k);
            tr[t].l = p.second;
            pull(t);
            return {p.first, t};
        }

        ll rem = k - leftLen;
        ll nodeLen = tr[t].len;

        if (rem < nodeLen) {
            ll slope = tr[t].slope;
            int b = newNode(slope, nodeLen - rem);
            tr[b].r = tr[t].r;
            pull(b);

            tr[t].len = rem;
            tr[t].r = 0;
            pull(t);
            return {t, b};
        }

        if (rem == nodeLen) {
            int b = tr[t].r;
            tr[t].r = 0;
            pull(t);
            return {t, b};
        }

        auto p = splitLen(tr[t].r, rem - nodeLen);
        tr[t].r = p.first;
        pull(t);
        return {t, p.second};
    }

    // Area under the finite segments over their first k units of length.
    ll areaPrefix(int t, ll k) {
        if (!t || k <= 0) return 0;
        if (k >= tr[t].sumLen) return tr[t].sumArea;

        push(t);
        int l = tr[t].l;
        ll leftLen = getLen(l);

        if (k <= leftLen) return areaPrefix(l, k);

        ll result = getArea(l);
        k -= leftLen;

        if (k <= tr[t].len) {
            result += tr[t].slope * k;
            return result;
        }

        result += tr[t].slope * tr[t].len;
        k -= tr[t].len;
        result += areaPrefix(tr[t].r, k);
        return result;
    }

    // Length before the first segment whose slope is at least c.
    ll lowerSlope(int t, ll c, bool &found) {
        push(t);
        int l = tr[t].l, r = tr[t].r;

        if (l && tr[l].maxSlope >= c) {
            return lowerSlope(l, c, found);
        }
        if (tr[t].slope >= c) {
            found = true;
            return getLen(l);
        }
        if (r && tr[r].maxSlope >= c) {
            ll base = getLen(l) + tr[t].len;
            return base + lowerSlope(r, c, found);
        }

        found = false;
        return 0;
    }
};

struct Solver {
    int root = 0;
    ll minimum = 0;
    ll flatEnd = 0;
    ll finalSlope = 0;
    FunctionTreap treap;

    Solver(int n, ll w1, ll c1) : treap(n) {
        minimum = w1 * c1;
        flatEnd = w1;
        finalSlope = c1;
    }

    ll evaluate(ll x) {
        if (x <= flatEnd) return minimum;

        ll d = x - flatEnd;
        ll totalLen = treap.getLen(root);

        if (d >= totalLen) {
            return minimum + treap.getArea(root)
                 + finalSlope * (d - totalLen);
        }
        return minimum + treap.areaPrefix(root, d);
    }

    void update(ll w, ll c, ll valueAtW) {
        ll oldFlatEnd = flatEnd;
        ll oldFinalSlope = finalSlope;

        ll crossing = 0;
        ll newFlatEnd = 0;
        ll upper = w;

        if (c <= oldFinalSlope) {
            bool found = false;
            ll offset = treap.lowerSlope(root, c, found);
            if (!found) offset = treap.getLen(root);
            crossing = oldFlatEnd + offset;

            if (w > crossing) newFlatEnd = w - crossing;
            upper = min(w, crossing);
        }

        ll baseValue;
        if (newFlatEnd > 0) baseValue = evaluate(crossing);
        else baseValue = valueAtW;

        ll newMinimum = c * newFlatEnd + baseValue;
        ll needed = upper - oldFlatEnd;

        if (needed <= 0) {
            root = 0;
        } else {
            ll totalLen = treap.getLen(root);

            if (needed < totalLen) {
                root = treap.splitLen(root, needed).first;
            } else if (needed > totalLen) {
                int extra = treap.newNode(needed - totalLen, oldFinalSlope);
                root = treap.merge(root, extra);
            }

            treap.applyReverse(root);
            treap.applyAffine(root, -1, c);
        }

        minimum = newMinimum;
        flatEnd = newFlatEnd;
        finalSlope = c;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<ll> w(N + 1), c(N);
    for (int i = 1; i <= N; ++i) cin >> w[i];
    for (int i = 1; i < N; ++i) cin >> c[i];

    Solver solver(N, w[1], c[1]);

    string output;
    output.reserve((size_t)N * 12);

    for (int i = 2; i <= N; ++i) {
        ll answer = solver.evaluate(w[i]);
        output += to_string(answer);
        output.push_back('\n');

        if (i < N) solver.update(w[i], c[i], answer);
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

static const int64 INF_LEN = (1LL << 60);

struct Line {
    int64 s, b;
};

// Maps (s,b) to (a*s+k, b+e*s+f).
struct Transform {
    int64 a, k, e, f;
};

const Transform IDENTITY{1, 0, 0, 0};

bool isIdentity(const Transform &t) {
    return t.a == 1 && t.k == 0 && t.e == 0 && t.f == 0;
}

// Returns p after q.
Transform compose(const Transform &p, const Transform &q) {
    return {
        p.a * q.a,
        p.a * q.k + p.k,
        q.e + p.e * q.a,
        q.f + p.e * q.k + p.f
    };
}

struct Node {
    Node *l = nullptr, *r = nullptr;
    uint32_t priority;
    int64 len, sum;
    Line line;
    Transform tr = IDENTITY;
    bool rev = false;

    Node(int64 length, Line ln, uint32_t p)
        : priority(p), len(length), sum(length), line(ln) {}
};

mt19937 rng(712367821);

int64 lengthSum(Node *t) {
    return t ? t->sum : 0;
}

void pull(Node *t) {
    i128 total = (i128)lengthSum(t->l) + t->len + lengthSum(t->r);
    t->sum = total > INF_LEN ? INF_LEN : (int64)total;
}

Line getLine(const Node *t) {
    const Transform &p = t->tr;
    int64 s = (int64)((i128)p.a * t->line.s + p.k);
    int64 b = (int64)((i128)t->line.b + (i128)p.e * t->line.s + p.f);
    return {s, b};
}

int64 evaluate(const Node *t, int64 x) {
    Line ln = getLine(t);
    return (int64)((i128)ln.s * x + ln.b);
}

void applyTransform(Node *t, const Transform &p) {
    if (t) t->tr = compose(p, t->tr);
}

void applyReverse(Node *t) {
    if (!t) return;
    swap(t->l, t->r);
    t->rev ^= true;
}

void push(Node *t) {
    if (!t) return;
    if (t->rev) {
        applyReverse(t->l);
        applyReverse(t->r);
        t->rev = false;
    }
    if (!isIdentity(t->tr)) {
        Transform p = t->tr;
        Line cur = getLine(t);
        applyTransform(t->l, p);
        applyTransform(t->r, p);
        t->line = cur;
        t->tr = IDENTITY;
    }
}

Node* mergeTrees(Node *a, Node *b) {
    if (!a) return b;
    if (!b) return a;
    if (a->priority < b->priority) {
        push(a);
        a->r = mergeTrees(a->r, b);
        pull(a);
        return a;
    } else {
        push(b);
        b->l = mergeTrees(a, b->l);
        pull(b);
        return b;
    }
}

// Keeps exactly the first d units of length and discards the remainder.
Node* cutPrefix(Node *t, int64 d) {
    push(t);
    int64 left = lengthSum(t->l);

    if (d < left) return cutPrefix(t->l, d);
    if (d == left) return t->l;

    int64 rem = d - left;
    if (rem <= t->len) {
        t->len = rem;
        t->r = nullptr;
        pull(t);
        return t;
    }

    t->r = cutPrefix(t->r, rem - t->len);
    pull(t);
    return t;
}

Node* firstNode(Node *t) {
    while (true) {
        push(t);
        if (!t->l) return t;
        t = t->l;
    }
}

Node* lastNode(Node *t) {
    while (true) {
        push(t);
        if (!t->r) return t;
        t = t->r;
    }
}

Node* popFirst(Node *t) {
    push(t);
    if (!t->l) return t->r;
    t->l = popFirst(t->l);
    pull(t);
    return t;
}

// Finds the segment containing the point at distance d from the branch start.
Node* locate(Node *t, int64 d) {
    push(t);
    int64 left = lengthSum(t->l);
    if (d <= left) return locate(t->l, d);

    int64 rem = d - left;
    if (rem <= t->len) return t;
    return locate(t->r, rem - t->len);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int64> w(N + 1), c(N);
    for (int i = 1; i <= N; ++i) cin >> w[i];
    for (int i = 1; i < N; ++i) cin >> c[i];

    Node *root = new Node(INF_LEN, {c[1], 0}, rng());
    int64 minimizer = w[1];
    int64 minimumValue = c[1] * w[1];

    for (int i = 2; i < N; ++i) {
        int64 answer;
        int64 d = w[i] - minimizer;

        if (d <= 0) {
            answer = minimumValue;
            root = new Node(INF_LEN, {c[i], minimumValue}, rng());
            minimizer = 0;
        } else {
            root = cutPrefix(root, d);
            answer = evaluate(lastNode(root), w[i]);

            applyReverse(root);
            applyTransform(root, Transform{-1, c[i], w[i], 0});
            root = mergeTrees(
                root,
                new Node(INF_LEN, {c[i], minimumValue}, rng())
            );

            int64 newMinimizer = 0;
            while (getLine(firstNode(root)).s < 0) {
                Node *f = firstNode(root);
                newMinimizer += f->len;
                root = popFirst(root);
            }

            minimizer = newMinimizer;
            minimumValue = evaluate(firstNode(root), minimizer);
        }

        cout << answer << '\n';
    }

    int64 answer;
    if (w[N] <= minimizer) {
        answer = minimumValue;
    } else {
        answer = evaluate(locate(root, w[N] - minimizer), w[N]);
    }
    cout << answer << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Node {
    Node *l, *r;
    ll len, sz, sum;
    int slope, mn, mx;
    unsigned pri;
    int lazyA;
    ll lazyB;
    bool rev;
};

static Node* pool;
static int poolPtr = 0;
static unsigned rngState = 123456789u;

static inline unsigned rnd() {
    rngState ^= rngState << 13;
    rngState ^= rngState >> 17;
    rngState ^= rngState << 5;
    return rngState;
}

static inline ll sz(Node* t) {
    return t ? t->sz : 0;
}

static Node* makeNode(ll len, int slope) {
    if (len <= 0) return nullptr;
    Node* t = &pool[poolPtr++];
    t->l = t->r = nullptr;
    t->len = t->sz = len;
    t->slope = t->mn = t->mx = slope;
    t->sum = (ll)slope * len;
    t->pri = rnd();
    t->lazyA = 1;
    t->lazyB = 0;
    t->rev = false;
    return t;
}

static inline void pull(Node* t) {
    t->sz = t->len + sz(t->l) + sz(t->r);
    t->sum = (ll)t->slope * t->len;
    t->mn = t->mx = t->slope;
    if (t->l) {
        t->sum += t->l->sum;
        t->mn = min(t->mn, t->l->mn);
        t->mx = max(t->mx, t->l->mx);
    }
    if (t->r) {
        t->sum += t->r->sum;
        t->mn = min(t->mn, t->r->mn);
        t->mx = max(t->mx, t->r->mx);
    }
}

// Replaces every slope s in the subtree by a*s+b.
static void apply(Node* t, int a, ll b) {
    if (!t) return;
    t->slope = (int)(a * (ll)t->slope + b);
    t->sum = a * t->sum + b * t->sz;
    if (a == 1) {
        t->mn = (int)(t->mn + b);
        t->mx = (int)(t->mx + b);
    } else {
        int oldMn = t->mn, oldMx = t->mx;
        t->mn = (int)(-oldMx + b);
        t->mx = (int)(-oldMn + b);
    }
    t->lazyA *= a;
    t->lazyB = a * t->lazyB + b;
}

static inline void push(Node* t) {
    if (!t) return;
    if (t->rev) {
        swap(t->l, t->r);
        if (t->l) t->l->rev ^= 1;
        if (t->r) t->r->rev ^= 1;
        t->rev = false;
    }
    if (t->lazyA != 1 || t->lazyB != 0) {
        apply(t->l, t->lazyA, t->lazyB);
        apply(t->r, t->lazyA, t->lazyB);
        t->lazyA = 1;
        t->lazyB = 0;
    }
}

static Node* merge(Node* a, Node* b) {
    if (!a) return b;
    if (!b) return a;
    if (a->pri > b->pri) {
        push(a);
        a->r = merge(a->r, b);
        pull(a);
        return a;
    } else {
        push(b);
        b->l = merge(a, b->l);
        pull(b);
        return b;
    }
}

// Splits into the first k units of length and the remainder.
static void split(Node* t, ll k, Node*& a, Node*& b) {
    if (!t) {
        a = b = nullptr;
        return;
    }
    push(t);
    ll leftSize = sz(t->l);
    if (k < leftSize) {
        split(t->l, k, a, t->l);
        b = t;
        pull(b);
        return;
    }
    if (k > leftSize + t->len) {
        split(t->r, k - leftSize - t->len, t->r, b);
        a = t;
        pull(a);
        return;
    }

    ll take = k - leftSize;
    if (take == 0) {
        a = t->l;
        t->l = nullptr;
        b = t;
        pull(b);
    } else if (take == t->len) {
        b = t->r;
        t->r = nullptr;
        a = t;
        pull(a);
    } else {
        Node* rightPart = makeNode(t->len - take, t->slope);
        rightPart->r = t->r;
        pull(rightPart);
        t->len = take;
        t->r = nullptr;
        a = t;
        b = rightPart;
        pull(a);
    }
}

// Returns the length before the first segment whose slope is at least c.
static ll firstGE(Node* t, ll c) {
    if (!t || t->mx < c) return sz(t);
    push(t);
    if (t->l && t->l->mx >= c) return firstGE(t->l, c);
    ll leftSize = sz(t->l);
    if (t->slope >= c) return leftSize;
    return leftSize + t->len + firstGE(t->r, c);
}

static ll prefixSum(Node* t, ll k) {
    if (!t || k <= 0) return 0;
    push(t);
    ll leftSize = sz(t->l);
    if (k <= leftSize) return prefixSum(t->l, k);

    ll result = t->l ? t->l->sum : 0;
    k -= leftSize;
    if (k <= t->len) return result + (ll)t->slope * k;

    result += (ll)t->slope * t->len;
    return result + prefixSum(t->r, k - t->len);
}

static inline ll evaluate(Node* t, ll base, int lastSlope, ll length, ll d) {
    if (d >= length) {
        return base + (t ? t->sum : 0) + (ll)lastSlope * (d - length);
    }
    return base + prefixSum(t, d);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<ll> w(N + 1), c(N);
    for (int i = 1; i <= N; ++i) cin >> w[i];
    for (int i = 1; i < N; ++i) cin >> c[i];

    pool = new Node[2 * N + 5];

    // V_2(d) = c_1 * max(w_1,d).  Its derivative is represented by T.
    ll base = c[1] * w[1];
    ll length = w[1];
    int lastSlope = (int)c[1];
    Node* T = makeNode(length, 0);

    string output;
    output.reserve((size_t)N * 12);
    output += to_string(evaluate(T, base, lastSlope, length, w[2]));
    output.push_back('\n');

    for (int j = 2; j < N; ++j) {
        ll W = w[j];
        ll cost = c[j];

        // Restrict the derivative to [0,W], extending with its final slope if needed.
        if (W < length) {
            Node *P, *discarded;
            split(T, W, P, discarded);
            T = P;
        } else if (W > length) {
            T = merge(T, makeNode(W - length, lastSlope));
        }

        // Remove the suffix with slopes >= cost.  It becomes a flat prefix.
        ll pos = firstGE(T, cost);
        Node *A, *X;
        if (pos == 0) {
            A = nullptr;
            X = T;
        } else if (pos == W) {
            A = T;
            X = nullptr;
        } else {
            split(T, pos, A, X);
        }

        ll flatLength = sz(X);
        base += (A ? A->sum : 0) + cost * flatLength;

        // Reverse the remaining segments and replace every slope s by cost-s.
        if (A) {
            apply(A, -1, cost);
            A->rev ^= 1;
        }
        T = merge(makeNode(flatLength, 0), A);

        length = W;
        lastSlope = (int)cost;

        output += to_string(evaluate(T, base, lastSlope, length, w[j + 1]));
        output.push_back('\n');
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Node {
    int l = 0, r = 0;
    unsigned priority = 0;
    ll len = 0, slope = 0;
    ll sumLen = 0, sumArea = 0;
    ll minSlope = 0, maxSlope = 0;
    int lazyA = 1;
    ll lazyB = 0;
    bool rev = false;
};

struct FunctionTreap {
    vector<Node> tr;
    mt19937 rng{712367821};

    FunctionTreap(int n) {
        tr.reserve(2 * n + 10);
        tr.emplace_back();
    }

    int newNode(ll len, ll slope) {
        Node x;
        x.len = x.sumLen = len;
        x.slope = x.minSlope = x.maxSlope = slope;
        x.sumArea = len * slope;
        x.priority = rng();
        tr.push_back(x);
        return (int)tr.size() - 1;
    }

    ll getLen(int t) const { return t ? tr[t].sumLen : 0; }
    ll getArea(int t) const { return t ? tr[t].sumArea : 0; }

    void pull(int t) {
        if (!t) return;
        Node &x = tr[t];
        x.sumLen = x.len + getLen(x.l) + getLen(x.r);
        x.sumArea = x.slope * x.len + getArea(x.l) + getArea(x.r);
        x.minSlope = x.maxSlope = x.slope;
        if (x.l) {
            x.minSlope = min(x.minSlope, tr[x.l].minSlope);
            x.maxSlope = max(x.maxSlope, tr[x.l].maxSlope);
        }
        if (x.r) {
            x.minSlope = min(x.minSlope, tr[x.r].minSlope);
            x.maxSlope = max(x.maxSlope, tr[x.r].maxSlope);
        }
    }

    void applyReverse(int t) {
        if (!t) return;
        swap(tr[t].l, tr[t].r);
        tr[t].rev = !tr[t].rev;
    }

    // Replace every slope s by a*s+b.
    void applyAffine(int t, int a, ll b) {
        if (!t) return;
        Node &x = tr[t];
        x.slope = a * x.slope + b;
        x.sumArea = a * x.sumArea + b * x.sumLen;
        if (a == 1) {
            x.minSlope += b;
            x.maxSlope += b;
        } else {
            ll oldMin = x.minSlope, oldMax = x.maxSlope;
            x.minSlope = b - oldMax;
            x.maxSlope = b - oldMin;
        }
        x.lazyB = a * x.lazyB + b;
        x.lazyA = a * x.lazyA;
    }

    void push(int t) {
        if (!t) return;
        if (tr[t].rev) {
            applyReverse(tr[t].l);
            applyReverse(tr[t].r);
            tr[t].rev = false;
        }
        if (tr[t].lazyA != 1 || tr[t].lazyB != 0) {
            int a = tr[t].lazyA;
            ll b = tr[t].lazyB;
            applyAffine(tr[t].l, a, b);
            applyAffine(tr[t].r, a, b);
            tr[t].lazyA = 1;
            tr[t].lazyB = 0;
        }
    }

    int merge(int a, int b) {
        if (!a) return b;
        if (!b) return a;
        if (tr[a].priority > tr[b].priority) {
            push(a);
            tr[a].r = merge(tr[a].r, b);
            pull(a);
            return a;
        } else {
            push(b);
            tr[b].l = merge(a, tr[b].l);
            pull(b);
            return b;
        }
    }

    // Split so that the first returned tree has total length k.
    pair<int, int> splitLen(int t, ll k) {
        if (!t) return {0, 0};
        if (k <= 0) return {0, t};
        if (k >= tr[t].sumLen) return {t, 0};

        push(t);
        ll leftLen = getLen(tr[t].l);

        if (k <= leftLen) {
            auto p = splitLen(tr[t].l, k);
            tr[t].l = p.second;
            pull(t);
            return {p.first, t};
        }

        ll rem = k - leftLen;
        ll nodeLen = tr[t].len;

        if (rem < nodeLen) {
            ll slope = tr[t].slope;
            int b = newNode(slope, nodeLen - rem);
            tr[b].r = tr[t].r;
            pull(b);

            tr[t].len = rem;
            tr[t].r = 0;
            pull(t);
            return {t, b};
        }

        if (rem == nodeLen) {
            int b = tr[t].r;
            tr[t].r = 0;
            pull(t);
            return {t, b};
        }

        auto p = splitLen(tr[t].r, rem - nodeLen);
        tr[t].r = p.first;
        pull(t);
        return {t, p.second};
    }

    // Area under the finite segments over their first k units of length.
    ll areaPrefix(int t, ll k) {
        if (!t || k <= 0) return 0;
        if (k >= tr[t].sumLen) return tr[t].sumArea;

        push(t);
        int l = tr[t].l;
        ll leftLen = getLen(l);

        if (k <= leftLen) return areaPrefix(l, k);

        ll result = getArea(l);
        k -= leftLen;

        if (k <= tr[t].len) {
            result += tr[t].slope * k;
            return result;
        }

        result += tr[t].slope * tr[t].len;
        k -= tr[t].len;
        result += areaPrefix(tr[t].r, k);
        return result;
    }

    // Length before the first segment whose slope is at least c.
    ll lowerSlope(int t, ll c, bool &found) {
        push(t);
        int l = tr[t].l, r = tr[t].r;

        if (l && tr[l].maxSlope >= c) {
            return lowerSlope(l, c, found);
        }
        if (tr[t].slope >= c) {
            found = true;
            return getLen(l);
        }
        if (r && tr[r].maxSlope >= c) {
            ll base = getLen(l) + tr[t].len;
            return base + lowerSlope(r, c, found);
        }

        found = false;
        return 0;
    }
};

struct Solver {
    int root = 0;
    ll minimum = 0;
    ll flatEnd = 0;
    ll finalSlope = 0;
    FunctionTreap treap;

    Solver(int n, ll w1, ll c1) : treap(n) {
        minimum = w1 * c1;
        flatEnd = w1;
        finalSlope = c1;
    }

    ll evaluate(ll x) {
        if (x <= flatEnd) return minimum;

        ll d = x - flatEnd;
        ll totalLen = treap.getLen(root);

        if (d >= totalLen) {
            return minimum + treap.getArea(root)
                 + finalSlope * (d - totalLen);
        }
        return minimum + treap.areaPrefix(root, d);
    }

    void update(ll w, ll c, ll valueAtW) {
        ll oldFlatEnd = flatEnd;
        ll oldFinalSlope = finalSlope;

        ll crossing = 0;
        ll newFlatEnd = 0;
        ll upper = w;

        if (c <= oldFinalSlope) {
            bool found = false;
            ll offset = treap.lowerSlope(root, c, found);
            if (!found) offset = treap.getLen(root);
            crossing = oldFlatEnd + offset;

            if (w > crossing) newFlatEnd = w - crossing;
            upper = min(w, crossing);
        }

        ll baseValue;
        if (newFlatEnd > 0) baseValue = evaluate(crossing);
        else baseValue = valueAtW;

        ll newMinimum = c * newFlatEnd + baseValue;
        ll needed = upper - oldFlatEnd;

        if (needed <= 0) {
            root = 0;
        } else {
            ll totalLen = treap.getLen(root);

            if (needed < totalLen) {
                root = treap.splitLen(root, needed).first;
            } else if (needed > totalLen) {
                int extra = treap.newNode(needed - totalLen, oldFinalSlope);
                root = treap.merge(root, extra);
            }

            treap.applyReverse(root);
            treap.applyAffine(root, -1, c);
        }

        minimum = newMinimum;
        flatEnd = newFlatEnd;
        finalSlope = c;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<ll> w(N + 1), c(N);
    for (int i = 1; i <= N; ++i) cin >> w[i];
    for (int i = 1; i < N; ++i) cin >> c[i];

    Solver solver(N, w[1], c[1]);

    string output;
    output.reserve((size_t)N * 12);

    for (int i = 2; i <= N; ++i) {
        ll answer = solver.evaluate(w[i]);
        output += to_string(answer);
        output.push_back('\n');

        if (i < N) solver.update(w[i], c[i], answer);
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

static const int64 INF_LEN = (1LL << 60);

struct Line {
    int64 s, b;
};

// Maps (s,b) to (a*s+k, b+e*s+f).
struct Transform {
    int64 a, k, e, f;
};

const Transform IDENTITY{1, 0, 0, 0};

bool isIdentity(const Transform &t) {
    return t.a == 1 && t.k == 0 && t.e == 0 && t.f == 0;
}

// Returns p after q.
Transform compose(const Transform &p, const Transform &q) {
    return {
        p.a * q.a,
        p.a * q.k + p.k,
        q.e + p.e * q.a,
        q.f + p.e * q.k + p.f
    };
}

struct Node {
    Node *l = nullptr, *r = nullptr;
    uint32_t priority;
    int64 len, sum;
    Line line;
    Transform tr = IDENTITY;
    bool rev = false;

    Node(int64 length, Line ln, uint32_t p)
        : priority(p), len(length), sum(length), line(ln) {}
};

mt19937 rng(712367821);

int64 lengthSum(Node *t) {
    return t ? t->sum : 0;
}

void pull(Node *t) {
    i128 total = (i128)lengthSum(t->l) + t->len + lengthSum(t->r);
    t->sum = total > INF_LEN ? INF_LEN : (int64)total;
}

Line getLine(const Node *t) {
    const Transform &p = t->tr;
    int64 s = (int64)((i128)p.a * t->line.s + p.k);
    int64 b = (int64)((i128)t->line.b + (i128)p.e * t->line.s + p.f);
    return {s, b};
}

int64 evaluate(const Node *t, int64 x) {
    Line ln = getLine(t);
    return (int64)((i128)ln.s * x + ln.b);
}

void applyTransform(Node *t, const Transform &p) {
    if (t) t->tr = compose(p, t->tr);
}

void applyReverse(Node *t) {
    if (!t) return;
    swap(t->l, t->r);
    t->rev ^= true;
}

void push(Node *t) {
    if (!t) return;
    if (t->rev) {
        applyReverse(t->l);
        applyReverse(t->r);
        t->rev = false;
    }
    if (!isIdentity(t->tr)) {
        Transform p = t->tr;
        Line cur = getLine(t);
        applyTransform(t->l, p);
        applyTransform(t->r, p);
        t->line = cur;
        t->tr = IDENTITY;
    }
}

Node* mergeTrees(Node *a, Node *b) {
    if (!a) return b;
    if (!b) return a;
    if (a->priority < b->priority) {
        push(a);
        a->r = mergeTrees(a->r, b);
        pull(a);
        return a;
    } else {
        push(b);
        b->l = mergeTrees(a, b->l);
        pull(b);
        return b;
    }
}

// Keeps exactly the first d units of length and discards the remainder.
Node* cutPrefix(Node *t, int64 d) {
    push(t);
    int64 left = lengthSum(t->l);

    if (d < left) return cutPrefix(t->l, d);
    if (d == left) return t->l;

    int64 rem = d - left;
    if (rem <= t->len) {
        t->len = rem;
        t->r = nullptr;
        pull(t);
        return t;
    }

    t->r = cutPrefix(t->r, rem - t->len);
    pull(t);
    return t;
}

Node* firstNode(Node *t) {
    while (true) {
        push(t);
        if (!t->l) return t;
        t = t->l;
    }
}

Node* lastNode(Node *t) {
    while (true) {
        push(t);
        if (!t->r) return t;
        t = t->r;
    }
}

Node* popFirst(Node *t) {
    push(t);
    if (!t->l) return t->r;
    t->l = popFirst(t->l);
    pull(t);
    return t;
}

// Finds the segment containing the point at distance d from the branch start.
Node* locate(Node *t, int64 d) {
    push(t);
    int64 left = lengthSum(t->l);
    if (d <= left) return locate(t->l, d);

    int64 rem = d - left;
    if (rem <= t->len) return t;
    return locate(t->r, rem - t->len);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int64> w(N + 1), c(N);
    for (int i = 1; i <= N; ++i) cin >> w[i];
    for (int i = 1; i < N; ++i) cin >> c[i];

    Node *root = new Node(INF_LEN, {c[1], 0}, rng());
    int64 minimizer = w[1];
    int64 minimumValue = c[1] * w[1];

    for (int i = 2; i < N; ++i) {
        int64 answer;
        int64 d = w[i] - minimizer;

        if (d <= 0) {
            answer = minimumValue;
            root = new Node(INF_LEN, {c[i], minimumValue}, rng());
            minimizer = 0;
        } else {
            root = cutPrefix(root, d);
            answer = evaluate(lastNode(root), w[i]);

            applyReverse(root);
            applyTransform(root, Transform{-1, c[i], w[i], 0});
            root = mergeTrees(
                root,
                new Node(INF_LEN, {c[i], minimumValue}, rng())
            );

            int64 newMinimizer = 0;
            while (getLine(firstNode(root)).s < 0) {
                Node *f = firstNode(root);
                newMinimizer += f->len;
                root = popFirst(root);
            }

            minimizer = newMinimizer;
            minimumValue = evaluate(firstNode(root), minimizer);
        }

        cout << answer << '\n';
    }

    int64 answer;
    if (w[N] <= minimizer) {
        answer = minimumValue;
    } else {
        answer = evaluate(locate(root, w[N] - minimizer), w[N]);
    }
    cout << answer << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int MAXN = 500005;

struct Node {
    ll x, v;
    ll sumV, sumVX;
    ll add;
    int l, r, sz;
    int mul;
    uint32_t pri;
    bool rev;

    Node() : x(0), v(0), sumV(0), sumVX(0), add(0),
             l(0), r(0), sz(0), mul(1), pri(0), rev(false) {}
};

Node tr[MAXN];
int ptrNode = 0;
uint32_t rngState = 2463534242u;

inline uint32_t rng() {
    rngState ^= rngState << 13;
    rngState ^= rngState >> 17;
    rngState ^= rngState << 5;
    return rngState;
}

inline void pull(int t) {
    if (!t) return;
    tr[t].sz = 1 + tr[tr[t].l].sz + tr[tr[t].r].sz;
    tr[t].sumV = tr[t].v + tr[tr[t].l].sumV + tr[tr[t].r].sumV;
    tr[t].sumVX = tr[t].v * tr[t].x + tr[tr[t].l].sumVX + tr[tr[t].r].sumVX;
}

inline void applyAffine(int t, int mul, ll add) {
    if (!t) return;
    tr[t].x = (ll)mul * tr[t].x + add;
    tr[t].sumVX = (ll)mul * tr[t].sumVX + add * tr[t].sumV;

    tr[t].add = (ll)mul * tr[t].add + add;
    tr[t].mul = mul * tr[t].mul;
}

inline void applyReverse(int t) {
    if (!t) return;
    swap(tr[t].l, tr[t].r);
    tr[t].rev ^= 1;
}

inline void push(int t) {
    if (!t) return;

    if (tr[t].mul != 1 || tr[t].add != 0) {
        applyAffine(tr[t].l, tr[t].mul, tr[t].add);
        applyAffine(tr[t].r, tr[t].mul, tr[t].add);
        tr[t].mul = 1;
        tr[t].add = 0;
    }

    if (tr[t].rev) {
        applyReverse(tr[t].l);
        applyReverse(tr[t].r);
        tr[t].rev = false;
    }
}

int newNode(ll x, ll v) {
    int t = ++ptrNode;
    tr[t].x = x;
    tr[t].v = v;
    tr[t].sumV = v;
    tr[t].sumVX = v * x;
    tr[t].l = tr[t].r = 0;
    tr[t].sz = 1;
    tr[t].mul = 1;
    tr[t].add = 0;
    tr[t].pri = rng();
    tr[t].rev = false;
    return t;
}

void splitByCoord(int t, ll key, int &a, int &b) {
    if (!t) {
        a = b = 0;
        return;
    }

    push(t);

    if (tr[t].x < key) {
        int a1, b1;
        splitByCoord(tr[t].r, key, a1, b1);
        tr[t].r = a1;
        pull(t);
        a = t;
        b = b1;
    } else {
        int a1, b1;
        splitByCoord(tr[t].l, key, a1, b1);
        tr[t].l = b1;
        pull(t);
        a = a1;
        b = t;
    }
}

int mergeTreap(int a, int b) {
    if (!a || !b) return a ? a : b;

    if (tr[a].pri > tr[b].pri) {
        push(a);
        tr[a].r = mergeTreap(tr[a].r, b);
        pull(a);
        return a;
    } else {
        push(b);
        tr[b].l = mergeTreap(a, tr[b].l);
        pull(b);
        return b;
    }
}

struct MinInfo {
    ll m;
    ll r;
    ll fm;
};

MinInfo getMin(int root, ll base, ll F0) {
    if (base >= 0) {
        return {0, base, F0};
    }

    ll need = -base;
    int cur = root;

    ll accV = 0, accVX = 0;
    ll rem = need;

    while (cur) {
        push(cur);

        int l = tr[cur].l;
        ll lv = tr[l].sumV;
        ll lvx = tr[l].sumVX;

        if (lv >= rem) {
            cur = l;
        } else {
            rem -= lv;

            if (tr[cur].v >= rem) {
                ll prefV = accV + lv;
                ll prefVX = accVX + lvx;
                ll m = tr[cur].x;

                ll r = base + prefV + tr[cur].v;
                ll fm = F0 + base * m + prefV * m - prefVX;

                return {m, r, fm};
            } else {
                rem -= tr[cur].v;
                accV += lv + tr[cur].v;
                accVX += lvx + tr[cur].v * tr[cur].x;
                cur = tr[cur].r;
            }
        }
    }

    return {0, base, F0};
}

pair<ll, ll> prefixLess(int root, ll key) {
    ll resV = 0, resVX = 0;
    int cur = root;

    while (cur) {
        push(cur);

        if (tr[cur].x < key) {
            int l = tr[cur].l;
            resV += tr[l].sumV + tr[cur].v;
            resVX += tr[l].sumVX + tr[cur].v * tr[cur].x;
            cur = tr[cur].r;
        } else {
            cur = tr[cur].l;
        }
    }

    return {resV, resVX};
}

ll query(int root, ll base, ll F0, ll W) {
    MinInfo info = getMin(root, base, F0);

    if (W <= info.m) {
        return info.fm;
    }

    auto [sv, svx] = prefixLess(root, W);
    return F0 + base * W + sv * W - svx;
}

void update(int &root, ll &F0, ll &base, ll w, ll c) {
    MinInfo info = getMin(root, base, F0);
    ll m = info.m;

    if (w <= m) {
        F0 = info.fm;
        base = c;
        root = 0;
        return;
    }

    int A, BC, B, C;
    splitByCoord(root, m + 1, A, BC);
    splitByCoord(BC, w, B, C);

    ll sumA = tr[A].sumV;
    ll sumAx = tr[A].sumVX;
    ll sumB = tr[B].sumV;
    ll sumBx = tr[B].sumVX;

    ll sumVw = sumA + sumB;
    ll sumVXw = sumAx + sumBx;

    ll Fw = F0 + base * w + sumVw * w - sumVXw;
    ll FprimeWminus = base + sumVw;

    ll baseNew = c - FprimeWminus;
    ll r = info.r;

    applyAffine(B, -1, w);
    applyReverse(B);

    if (r > 0) {
        int node = newNode(w - m, r);
        B = mergeTreap(B, node);
    }

    root = B;
    F0 = Fw;
    base = baseNew;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<ll> w(N + 1), c(N + 1);

    for (int i = 1; i <= N; i++) cin >> w[i];
    for (int i = 1; i <= N - 1; i++) cin >> c[i];

    ll ans2 = c[1] * max(w[1], w[2]);
    cout << ans2 << '\n';

    if (N == 2) return 0;

    ll F0 = ans2;
    ll base;
    int root = 0;

    if (w[2] > w[1]) {
        base = c[2] - c[1];
        ll a = w[2] - w[1];
        root = newNode(a, c[1]);
    } else {
        base = c[2];
        root = 0;
    }

    for (int i = 3; i <= N; i++) {
        ll ans = query(root, base, F0, w[i]);
        cout << ans << '\n';

        if (i <= N - 1) {
            update(root, F0, base, w[i], c[i]);
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Node {
    long long pos, delta;
    long long sumD, sumP;
    long long mul, add;
    int l, r, sz;
    uint32_t pri;
    bool rev;
};

vector<Node> tr;
int tot = 0;
uint32_t rng_state = 712367821;

uint32_t rng32() {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

int getSz(int x) {
    return x ? tr[x].sz : 0;
}

long long getSumD(int x) {
    return x ? tr[x].sumD : 0;
}

long long getSumP(int x) {
    return x ? tr[x].sumP : 0;
}

void pull(int x) {
    if (!x) return;
    tr[x].sz = 1 + getSz(tr[x].l) + getSz(tr[x].r);
    tr[x].sumD = tr[x].delta + getSumD(tr[x].l) + getSumD(tr[x].r);
    tr[x].sumP = tr[x].delta * tr[x].pos + getSumP(tr[x].l) + getSumP(tr[x].r);
}

void applyAff(int x, long long A, long long B) {
    if (!x) return;
    tr[x].pos = A * tr[x].pos + B;
    tr[x].sumP = A * tr[x].sumP + B * tr[x].sumD;
    tr[x].mul = A * tr[x].mul;
    tr[x].add = A * tr[x].add + B;
}

void applyRev(int x) {
    if (!x) return;
    swap(tr[x].l, tr[x].r);
    tr[x].rev ^= 1;
}

void push(int x) {
    if (!x) return;

    if (tr[x].rev) {
        applyRev(tr[x].l);
        applyRev(tr[x].r);
        tr[x].rev = false;
    }

    if (tr[x].mul != 1 || tr[x].add != 0) {
        long long A = tr[x].mul;
        long long B = tr[x].add;
        applyAff(tr[x].l, A, B);
        applyAff(tr[x].r, A, B);
        tr[x].mul = 1;
        tr[x].add = 0;
    }
}

int newNode(long long pos, long long delta) {
    ++tot;
    tr[tot].pos = pos;
    tr[tot].delta = delta;
    tr[tot].sumD = delta;
    tr[tot].sumP = delta * pos;
    tr[tot].mul = 1;
    tr[tot].add = 0;
    tr[tot].l = tr[tot].r = 0;
    tr[tot].sz = 1;
    tr[tot].pri = rng32();
    tr[tot].rev = false;
    return tot;
}

int mergeTreap(int a, int b) {
    if (!a || !b) return a ? a : b;

    if (tr[a].pri > tr[b].pri) {
        push(a);
        tr[a].r = mergeTreap(tr[a].r, b);
        pull(a);
        return a;
    } else {
        push(b);
        tr[b].l = mergeTreap(a, tr[b].l);
        pull(b);
        return b;
    }
}

void splitTreap(int x, int k, int &a, int &b) {
    if (!x) {
        a = b = 0;
        return;
    }

    push(x);

    if (getSz(tr[x].l) >= k) {
        splitTreap(tr[x].l, k, a, tr[x].l);
        b = x;
        pull(b);
    } else {
        splitTreap(tr[x].r, k - getSz(tr[x].l) - 1, tr[x].r, b);
        a = x;
        pull(a);
    }
}

int countLess(int root, long long x) {
    int cur = root;
    int res = 0;

    while (cur) {
        push(cur);

        if (tr[cur].pos < x) {
            res += getSz(tr[cur].l) + 1;
            cur = tr[cur].r;
        } else {
            cur = tr[cur].l;
        }
    }

    return res;
}

long long findCross(int root, long long target) {
    int cur = root;
    long long acc = 0;

    while (cur) {
        push(cur);

        long long leftSum = getSumD(tr[cur].l);

        if (acc + leftSum + tr[cur].delta >= target) {
            if (acc + leftSum >= target) {
                cur = tr[cur].l;
            } else {
                return tr[cur].pos;
            }
        } else {
            acc += leftSum + tr[cur].delta;
            cur = tr[cur].r;
        }
    }

    return (1LL << 60);
}

pair<long long, long long> prefixInfo(int root, long long x) {
    int cur = root;
    long long sumD = 0, sumP = 0;

    while (cur) {
        push(cur);

        if (tr[cur].pos < x) {
            int l = tr[cur].l;
            sumD += getSumD(l) + tr[cur].delta;
            sumP += getSumP(l) + tr[cur].delta * tr[cur].pos;
            cur = tr[cur].r;
        } else {
            cur = tr[cur].l;
        }
    }

    return {sumD, sumP};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> w(N + 1);
    for (int i = 1; i <= N; i++) cin >> w[i];

    vector<long long> c(N);
    for (int i = 1; i <= N - 1; i++) cin >> c[i];

    tr.assign(N + 10, Node());

    int root = 0;

    long long minimizer = w[1];
    long long bestValue = c[1] * w[1];
    long long initialSlope = c[1];

    auto evalD = [&](long long t) -> long long {
        if (t <= 0) return 0;
        auto [sumD, sumP] = prefixInfo(root, t);
        return initialSlope * t + t * sumD - sumP;
    };

    auto query = [&](long long x) -> long long {
        if (x <= minimizer) return bestValue;
        long long s = x - minimizer;
        return bestValue + evalD(s);
    };

    auto update = [&](long long demand, long long cost) {
        long long A = demand - minimizer;

        if (A <= 0) {
            root = 0;
            minimizer = 0;
            initialSlope = cost;
            return;
        }

        if (initialSlope >= cost) {
            bestValue += cost * A;
            minimizer = A;
            initialSlope = cost;
            root = 0;
            return;
        }

        long long target = cost - initialSlope;
        long long totalJump = root ? tr[root].sumD : 0;

        long long crossPos;
        if (totalJump < target) {
            crossPos = (1LL << 60);
        } else {
            crossPos = findCross(root, target);
        }

        long long t = min(A, crossPos);

        int k = countLess(root, t);
        int L, R;
        splitTreap(root, k, L, R);

        long long sumD = L ? tr[L].sumD : 0;
        long long sumP = L ? tr[L].sumP : 0;

        long long rLeft = initialSlope + sumD;
        long long D = initialSlope * t + t * sumD - sumP;

        bestValue = bestValue + D + cost * (A - t);
        minimizer = A - t;

        long long oldInitial = initialSlope;
        initialSlope = cost - rLeft;

        if (L) {
            applyRev(L);
            applyAff(L, -1, t);
        }

        if (oldInitial > 0) {
            int node = newNode(t, oldInitial);
            L = mergeTreap(L, node);
        }

        root = L;
        // R is discarded.
    };

    for (int i = 2; i <= N; i++) {
        long long ans = query(w[i]);
        cout << ans << '\n';

        if (i < N) {
            update(w[i], c[i]);
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Node {
    int l, r, val, len, sz;
    uint32_t pri;
    long long sum;
    long long lazyAdd;
    int lazyMul;
    bool rev;
};

vector<Node> tr;
uint32_t rng_state = 2463534242u;

uint32_t rng32() {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

int newNode(int v, int len) {
    Node nd;
    nd.l = nd.r = 0;
    nd.val = v;
    nd.len = len;
    nd.sz = len;
    nd.pri = rng32();
    nd.sum = 1LL * v * len;
    nd.lazyAdd = 0;
    nd.lazyMul = 1;
    nd.rev = false;
    tr.push_back(nd);
    return (int)tr.size() - 1;
}

inline int getSz(int t) {
    return t ? tr[t].sz : 0;
}

inline long long getSum(int t) {
    return t ? tr[t].sum : 0;
}

inline void pull(int t) {
    if (!t) return;
    tr[t].sz = tr[t].len + getSz(tr[t].l) + getSz(tr[t].r);
    tr[t].sum = 1LL * tr[t].val * tr[t].len + getSum(tr[t].l) + getSum(tr[t].r);
}

inline void applyRev(int t) {
    if (!t) return;
    swap(tr[t].l, tr[t].r);
    tr[t].rev ^= 1;
}

inline void applyAffine(int t, int mul, long long add) {
    if (!t) return;

    tr[t].val = (int)(1LL * mul * tr[t].val + add);
    tr[t].sum = 1LL * mul * tr[t].sum + add * (long long)tr[t].sz;

    long long oldAdd = tr[t].lazyAdd;
    int oldMul = tr[t].lazyMul;

    tr[t].lazyMul = mul * oldMul;
    tr[t].lazyAdd = 1LL * mul * oldAdd + add;
}

inline void push(int t) {
    if (!t) return;

    if (tr[t].rev) {
        applyRev(tr[t].l);
        applyRev(tr[t].r);
        tr[t].rev = false;
    }

    if (tr[t].lazyMul != 1 || tr[t].lazyAdd != 0) {
        int m = tr[t].lazyMul;
        long long a = tr[t].lazyAdd;
        applyAffine(tr[t].l, m, a);
        applyAffine(tr[t].r, m, a);
        tr[t].lazyMul = 1;
        tr[t].lazyAdd = 0;
    }
}

int mergeTreap(int a, int b) {
    if (!a) return b;
    if (!b) return a;

    if (tr[a].pri > tr[b].pri) {
        push(a);
        tr[a].r = mergeTreap(tr[a].r, b);
        pull(a);
        return a;
    } else {
        push(b);
        tr[b].l = mergeTreap(a, tr[b].l);
        pull(b);
        return b;
    }
}

void splitTreap(int t, int k, int &a, int &b) {
    if (!t) {
        a = b = 0;
        return;
    }
    if (k <= 0) {
        a = 0;
        b = t;
        return;
    }
    if (k >= tr[t].sz) {
        a = t;
        b = 0;
        return;
    }

    push(t);

    int lsz = getSz(tr[t].l);
    int len = tr[t].len;

    if (k < lsz) {
        splitTreap(tr[t].l, k, a, tr[t].l);
        pull(t);
        b = t;
    } else if (k > lsz + len) {
        splitTreap(tr[t].r, k - lsz - len, tr[t].r, b);
        pull(t);
        a = t;
    } else if (k == lsz) {
        a = tr[t].l;
        tr[t].l = 0;
        pull(t);
        b = t;
    } else if (k == lsz + len) {
        b = tr[t].r;
        tr[t].r = 0;
        pull(t);
        a = t;
    } else {
        int take = k - lsz;
        int oldL = tr[t].l;
        int oldR = tr[t].r;

        int leftPart = newNode(tr[t].val, take);
        int rightPart = newNode(tr[t].val, len - take);

        a = mergeTreap(oldL, leftPart);
        b = mergeTreap(rightPart, oldR);
    }
}

void splitByValue(int t, int c, int &a, int &b) {
    if (!t) {
        a = b = 0;
        return;
    }

    push(t);

    if (tr[t].val <= c) {
        int ra, rb;
        splitByValue(tr[t].r, c, ra, rb);
        tr[t].r = ra;
        pull(t);
        a = t;
        b = rb;
    } else {
        int la, lb;
        splitByValue(tr[t].l, c, la, lb);
        tr[t].l = lb;
        pull(t);
        a = la;
        b = t;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> w(N + 1);
    for (int i = 1; i <= N; i++) cin >> w[i];

    vector<int> c(N);
    for (int i = 1; i < N; i++) cin >> c[i];

    tr.reserve(2500005);
    tr.push_back({0, 0, 0, 0, 0, 0, 0, 0, 1, false});

    int root = 0;
    int L = w[1];

    if (L > 0) {
        root = newNode(0, L);
    }

    int tail = c[1];
    long long h0 = 1LL * c[1] * w[1];

    for (int j = 2; j <= N; j++) {
        int wj = w[j];

        int curLen = getSz(root);
        int take = min(wj, curLen);

        int Sroot, rest;
        splitTreap(root, take, Sroot, rest);

        int appended = wj - take;
        if (appended > 0) {
            int node = newNode(tail, appended);
            Sroot = mergeTreap(Sroot, node);
        }

        long long sumS = getSum(Sroot);
        long long ans = h0 + sumS;

        cout << ans << '\n';

        if (j == N) break;

        int cc = c[j];

        int A, Z;
        splitByValue(Sroot, cc, A, Z);

        int cntZ = getSz(Z);
        long long sumZ = getSum(Z);

        long long h0_new = h0 + sumS + 1LL * cntZ * cc - sumZ;

        applyAffine(A, -1, cc);
        applyRev(A);

        int B = 0;
        if (cntZ > 0) {
            B = newNode(0, cntZ);
        }

        B = mergeTreap(B, A);

        root = B;
        tail = cc;
        h0 = h0_new;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

/*
Maintains the vertices of a concave piecewise-linear function.

A stored point (X, Y) represents the actual point

    x = sign * X + shiftX
    y = Y + coefX * X + shiftY

The sign of the x-coordinate can change when the graph is reflected,
so the order of the vertices is also stored in reversed order.
*/
class ConcaveDeque {
private:
    struct Point {
        int64 x;
        i128 y;
    };

    deque<Point> dq;
    bool reversed = false;

    int64 sign = 1;
    int64 shiftX = 0;
    i128 coefX = 0;
    i128 shiftY = 0;

    Point decode(const Point& p) const {
        return {
            sign * p.x + shiftX,
            p.y + coefX * (i128)p.x + shiftY
        };
    }

    Point encode(int64 x, i128 y) const {
        int64 X = sign * (x - shiftX);
        i128 Y = y - coefX * (i128)X - shiftY;
        return {X, Y};
    }

    size_t size() const {
        return dq.size();
    }

    Point back() const {
        if (!reversed) return decode(dq.back());
        return decode(dq.front());
    }

    Point secondBack() const {
        if (!reversed) return decode(dq[dq.size() - 2]);
        return decode(dq[1]);
    }

    void popBack() {
        if (!reversed) dq.pop_back();
        else dq.pop_front();
    }

    void pushFront(int64 x, i128 y) {
        Point p = encode(x, y);
        if (!reversed) dq.push_front(p);
        else dq.push_back(p);
    }

    void pushBack(int64 x, i128 y) {
        Point p = encode(x, y);
        if (!reversed) dq.push_back(p);
        else dq.push_front(p);
    }

public:
    /*
    Reflects the graph about x = C / 2 and adds v*x:

        (x, y) -> (C-x, y + v*(C-x)).

    This is the transformation needed when adding a new plant.
    */
    void reflectAndShift(int64 C, int64 v) {
        int64 oldSign = sign;
        int64 oldShiftX = shiftX;

        coefX = coefX - (i128)v * oldSign;
        shiftY = shiftY + (i128)v * ((i128)C - oldShiftX);

        sign = -oldSign;
        shiftX = C - oldShiftX;

        reversed = !reversed;
    }

    /*
    Restricts the graph to x in [0, C], inserting a vertex if C lies
    inside a segment.
    */
    void cutAt(int64 C) {
        while (size() >= 2 && secondBack().x > C) {
            popBack();
        }

        if (size() >= 2 && back().x > C) {
            Point left = secondBack();
            Point right = back();

            popBack();

            if (left.x < C) {
                // Every segment has an integer slope.
                i128 slope = (right.y - left.y) / (i128)(right.x - left.x);
                i128 y = left.y + slope * (i128)(C - left.x);
                pushBack(C, y);
            }
        }
    }

    /*
    The graph is concave. Remove its descending right-hand suffix.
    The remaining right endpoint is the rightmost maximum.

    Returns {position of maximum, maximum value}.
    */
    pair<int64, i128> trimToMaximum() {
        while (size() >= 2) {
            Point left = secondBack();
            Point right = back();

            if (right.y < left.y) {
                popBack();
            } else {
                break;
            }
        }

        Point p = back();
        return {p.x, p.y};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int64> w(N);
    vector<int64> c(N - 1);

    for (int i = 0; i < N; ++i) cin >> w[i];
    for (int i = 0; i < N - 1; ++i) cin >> c[i];

    string output;
    output.reserve((size_t)N * 20);

    auto emit = [&](i128 answer) {
        // The answer is at most N * 10^6 * 10^6 <= 5 * 10^17.
        output += to_string((int64)answer);
        output.push_back('\n');
    };

    ConcaveDeque graph;

    /*
    For the first two plants, with y_2 = x:

        F_2(x) = w_1 * (c_1 - x) + w_2 * x
               = w_1*c_1 + (w_2-w_1)*x,

    for 0 <= x <= c_1.
    */
    graph.pushBack(0, (i128)w[0] * c[0]);
    graph.pushBack(c[0], (i128)w[1] * c[0]);

    auto state = graph.trimToMaximum();
    int64 maximumPosition = state.first;
    i128 maximumValue = state.second;

    emit(maximumValue);

    for (int plant = 2; plant < N; ++plant) {
        int64 C = c[plant - 1];
        int64 v = w[plant];

        if (C >= maximumPosition) {
            /*
            Add the linear segment M + v*x on [0, C-p], then reflect
            the old graph from [0,p] onto [C-p,C].
            */
            int64 length = C - maximumPosition;
            graph.reflectAndShift(C, v);

            if (length > 0) {
                graph.pushFront(0, maximumValue);
            }
        } else {
            /*
            Every queried argument is below the old maximum.
            Keep only the old graph on [0,C], then reflect it.
            */
            graph.cutAt(C);
            graph.reflectAndShift(C, v);
        }

        state = graph.trimToMaximum();
        maximumPosition = state.first;
        maximumValue = state.second;

        emit(maximumValue);
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

class FastInput {
    static constexpr int BUFFER_SIZE = 1 << 16;
    char buffer[BUFFER_SIZE];
    int pos = 0, len = 0;

    int getChar() {
        if (pos == len) {
            len = static_cast<int>(
                fread(buffer, 1, BUFFER_SIZE, stdin)
            );
            pos = 0;
            if (len == 0) return EOF;
        }
        return static_cast<unsigned char>(buffer[pos++]);
    }

public:
    bool readInt(int& value) {
        int ch = getChar();
        while (ch != EOF && ch <= ' ') ch = getChar();
        if (ch == EOF) return false;

        value = 0;
        while (ch >= '0' && ch <= '9') {
            value = value * 10 + (ch - '0');
            ch = getChar();
        }
        return true;
    }
};

class SlopeDeque {
    struct Block {
        int64 len;
        int64 raw;
    };

    deque<Block> blocks;

    // Logical order is the reverse of physical order when flipped.
    bool flipped = false;

    // Actual value of a block = mul * raw + add.
    // mul is always either 1 or -1.
    int64 mul = 1;
    int64 add = 0;

    int64 totalLength = 0;
    int64 totalArea = 0;

    int64 actualValue(const Block& block) const {
        return mul * block.raw + add;
    }

    Block& logicalBack() {
        return flipped ? blocks.front() : blocks.back();
    }

    void popLogicalBack() {
        if (flipped) blocks.pop_front();
        else blocks.pop_back();
    }

    // Append a block whose actual value is zero.
    void appendLogicalBackZero(int64 length) {
        if (length == 0) return;

        // mul * raw + add = 0, and mul^2 = 1.
        Block block{length, -mul * add};

        if (flipped) blocks.push_front(block);
        else blocks.push_back(block);

        totalLength += length;
        // Its contribution to totalArea is zero.
    }

public:
    SlopeDeque(int64 initialValue, int64 initialLength) {
        blocks.push_back({initialLength, initialValue});
        totalLength = initialLength;
        totalArea = initialValue * initialLength;
    }

    // Returns:
    //   I = integral of the old h over [0, c]
    //   K = integral of max(0, w - old_h(x)) over [0, c]
    pair<int64, int64> transition(int64 c, int64 w) {
        // Retain only the prefix of length c.
        while (totalLength > c) {
            Block& block = logicalBack();
            int64 value = actualValue(block);
            int64 removed = min(block.len, totalLength - c);

            totalArea -= value * removed;
            totalLength -= removed;
            block.len -= removed;

            if (block.len == 0) {
                popLogicalBack();
            }
        }

        const int64 I = totalArea;

        // If the stored function ends before c, its remaining part is zero.
        if (totalLength < c) {
            appendLogicalBackZero(c - totalLength);
        }

        // Reflect: h(c-u).
        flipped = !flipped;

        // After reflection, values are nondecreasing.
        // Pop the suffix whose values are greater than w.
        int64 highLength = 0;

        while (!blocks.empty()) {
            Block block = logicalBack();
            int64 value = actualValue(block);

            if (value <= w) break;

            highLength += block.len;
            totalLength -= block.len;
            totalArea -= value * block.len;
            popLogicalBack();
        }

        const int64 lowLength = totalLength;
        const int64 lowArea = totalArea;
        const int64 K = w * lowLength - lowArea;

        // Apply value -> w - value to every remaining block.
        mul = -mul;
        add = w - add;
        totalArea = K;

        // The popped high-valued suffix becomes one zero-valued suffix.
        appendLogicalBackZero(highLength);

        return {I, K};
    }
};

int main() {
    FastInput input;

    int N;
    if (!input.readInt(N)) return 0;

    vector<int> w(N);
    vector<int> c(N - 1);

    for (int& x : w) input.readInt(x);

    int maxCost = 0;
    for (int& x : c) {
        input.readInt(x);
        maxCost = max(maxCost, x);
    }

    // h_1(x) = w_1. Store enough length for every coordinate queried.
    SlopeDeque slope(w[0], maxCost);

    // base = H_j(0) for the current prefix.
    int64 base = 0;

    string output;
    output.reserve(static_cast<size_t>(N - 1) * 22);

    for (int i = 1; i < N; ++i) {
        auto [I, K] = slope.transition(c[i - 1], w[i]);

        const int64 answer = base + I + K;
        output += to_string(answer);
        output.push_back('\n');

        base += I;
    }

    fwrite(output.data(), 1, output.size(), stdout);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

/*
Represents the increasing part of Q.

Q consists of:
  1. A flat initial segment [0, r], whose value is maintained separately.
  2. A sequence of positive-slope segments with nondecreasing slopes.
  3. An infinite segment with slope infiniteSlope.

The finite segments are stored in a deque. Reversal and the transformation
s -> c-s are performed lazily.
*/
class IncreasingPart {
private:
    struct Segment {
        int64 len;
        int64 rawSlope;
    };

    deque<Segment> segments;

    bool reversed = false;

    // Actual slope of a segment is mul * rawSlope + add, where mul is +/-1.
    int64 mul = 1;
    int64 add = 0;

    int64 lengthSum = 0;
    int64 areaSum = 0;

    int64 actualSlope(const Segment& s) const {
        return mul * s.rawSlope + add;
    }

    Segment& logicalBack() {
        return reversed ? segments.front() : segments.back();
    }

    void popBack() {
        Segment s = logicalBack();
        int64 slope = actualSlope(s);

        if (reversed) {
            segments.pop_front();
        } else {
            segments.pop_back();
        }

        lengthSum -= s.len;
        areaSum -= slope * s.len;
    }

    void trimBack(int64 newLength) {
        Segment& s = logicalBack();
        int64 slope = actualSlope(s);
        int64 removed = s.len - newLength;

        s.len = newLength;
        lengthSum -= removed;
        areaSum -= slope * removed;
    }

    void pushBack(int64 slope, int64 len) {
        // slope = mul * rawSlope + add, and mul^2 = 1.
        int64 rawSlope = (slope - add) * mul;
        Segment s{len, rawSlope};

        if (reversed) {
            segments.push_front(s);
        } else {
            segments.push_back(s);
        }

        lengthSum += len;
        areaSum += slope * len;
    }

    void trimToPrefix(int64 targetLength) {
        while (lengthSum > targetLength) {
            Segment s = logicalBack();
            int64 excess = lengthSum - targetLength;

            if (s.len <= excess) {
                popBack();
            } else {
                trimBack(s.len - excess);
            }
        }
    }

public:
    int64 infiniteSlope = 0;

    void reset(int64 newInfiniteSlope) {
        segments.clear();
        reversed = false;
        mul = 1;
        add = 0;
        lengthSum = 0;
        areaSum = 0;
        infiniteSlope = newInfiniteSlope;
    }

    /*
    Retain only the first wantedLength units of the increasing part.
    If necessary, a finite portion of the infinite tail is included.
    Returns the area (integral of the slope) of that prefix.
    */
    int64 takePrefix(int64 wantedLength) {
        int64 oldFiniteLength = lengthSum;
        int64 keep = min(wantedLength, oldFiniteLength);

        trimToPrefix(keep);

        if (wantedLength > oldFiniteLength) {
            pushBack(infiniteSlope, wantedLength - oldFiniteLength);
        }

        return areaSum;
    }

    /*
    Slopes are nondecreasing, so all slopes >= threshold form a suffix.
    */
    void removeSuffixWithSlopeAtLeast(int64 threshold) {
        while (lengthSum > 0) {
            Segment s = logicalBack();
            if (actualSlope(s) < threshold) {
                break;
            }
            popBack();
        }
    }

    /*
    Reverse the segment order and replace every slope s by c-s.
    */
    void reverseAndComplement(int64 c) {
        areaSum = static_cast<int64>(
            static_cast<__int128>(c) * lengthSum - areaSum
        );

        reversed = !reversed;
        mul = -mul;
        add = c - add;
    }

    int64 length() const {
        return lengthSum;
    }

    int64 area() const {
        return areaSum;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int64> w(N + 1);
    vector<int64> c(N + 1);

    for (int i = 1; i <= N; ++i) {
        cin >> w[i];
    }
    for (int i = 1; i < N; ++i) {
        cin >> c[i];
    }

    /*
    Q_1(z) = c_1 * max(z, w_1).

    Thus its flat part has:
      length = w_1,
      value  = c_1 * w_1,
    followed by an infinite segment of slope c_1.
    */
    IncreasingPart increasing;
    int64 flatLength = w[1];
    int64 flatValue = c[1] * w[1];
    increasing.infiniteSlope = c[1];

    for (int i = 2; i <= N; ++i) {
        int64 answer;

        if (w[i] <= flatLength) {
            answer = flatValue;

            if (i < N) {
                /*
                P_i(x) = c_i*x + Q_{i-1}(0) for every x >= 0,
                so Q_i(z) = Q_{i-1}(0) + c_i*z.
                */
                increasing.reset(c[i]);
                flatLength = 0;
            }
        } else {
            int64 d = w[i] - flatLength;

            // Q_{i-1}(w_i): evaluate the first d units of its increasing part.
            int64 prefixArea = increasing.takePrefix(d);
            answer = flatValue + prefixArea;

            if (i < N) {
                int64 cost = c[i];

                /*
                Keep only the portions whose old slope is < cost.
                The removed portions become the new flat part.
                */
                increasing.removeSuffixWithSlopeAtLeast(cost);

                int64 lowLength = increasing.length();
                int64 lowArea = increasing.area();
                int64 highLength = d - lowLength;

                int64 newFlatValue = static_cast<int64>(
                    static_cast<__int128>(flatValue)
                    + lowArea
                    + static_cast<__int128>(cost) * highLength
                );

                increasing.reverseAndComplement(cost);
                increasing.infiniteSlope = cost;

                flatLength = highLength;
                flatValue = newFlatValue;
            }
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    int maxValue = 0;
    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        maxValue = max(maxValue, a[i]);
    }

    // Positions are bucketed by value.
    vector<int> head(maxValue + 1, -1), nextInBucket(N + 1, -1);
    for (int i = 1; i <= N; ++i) {
        nextInBucket[i] = head[a[i]];
        head[a[i]] = i;
    }

    auto gapEven = [](int g) -> int64 {
        return 1LL * (g / 2) * ((g + 1) / 2);
    };

    auto gapOdd = [&](int g) -> int64 {
        return 1LL * g * (g + 1) / 2 - gapEven(g);
    };

    // Number of even-length subarrays containing p, with left endpoint in
    // [P+1,p] and right endpoint in [p,Q-1].
    auto oneActiveEven = [](int p, int P, int Q) -> int64 {
        int64 leftEven = p / 2 - P / 2;
        int64 leftOdd = (p + 1) / 2 - (P + 1) / 2;
        int64 rightEven = (Q - 1) / 2 - (p - 1) / 2;
        int64 rightOdd = Q / 2 - p / 2;
        return leftEven * rightOdd + leftOdd * rightEven;
    };

    const int64 totalSubarrays = 1LL * N * (N + 1) / 2;
    const int64 totalEven = gapEven(N);
    const int64 totalOdd = totalSubarrays - totalEven;

    // Initially every position is active.
    vector<int> left(N + 2), right(N + 2);
    for (int i = 1; i <= N; ++i) {
        left[i] = i - 1;
        right[i] = i + 1;
    }
    right[0] = 1;
    left[N + 1] = N;

    int64 zeroEven = 0, zeroOdd = 0, exactlyOneEven = 0;
    int64 sumMaximumOdd = 0, sumSecondMaximumEven = 0;
    int previousValue = 0;

    // Process thresholds increasingly, removing positions below the next threshold.
    for (int value = 1; value <= maxValue; ++value) {
        if (head[value] == -1) continue;

        int64 withActiveOdd = totalOdd - zeroOdd;
        int64 withTwoActiveEven = totalEven - zeroEven - exactlyOneEven;

        int64 delta = value - previousValue;
        sumMaximumOdd += delta * withActiveOdd;
        sumSecondMaximumEven += delta * withTwoActiveEven;
        previousValue = value;

        for (int p = head[value]; p != -1; p = nextInBucket[p]) {
            int P = left[p], Q = right[p];

            exactlyOneEven -= oneActiveEven(p, P, Q);

            if (P != 0) {
                int PP = left[P];
                exactlyOneEven -= oneActiveEven(P, PP, p);
                exactlyOneEven += oneActiveEven(P, PP, Q);
            }
            if (Q != N + 1) {
                int QQ = right[Q];
                exactlyOneEven -= oneActiveEven(Q, p, QQ);
                exactlyOneEven += oneActiveEven(Q, P, QQ);
            }

            int oldGapLeft = p - P - 1;
            int oldGapRight = Q - p - 1;
            int mergedGap = Q - P - 1;

            zeroEven += gapEven(mergedGap)
                      - gapEven(oldGapLeft) - gapEven(oldGapRight);
            zeroOdd += gapOdd(mergedGap)
                     - gapOdd(oldGapLeft) - gapOdd(oldGapRight);

            right[P] = Q;
            left[Q] = P;
        }
    }

    /*
       For odd lengths at least 5, the answer is the subarray maximum.
       For even lengths at least 8, it is the second maximum.
       Lengths 1 and 2 already agree with these formulas.
       Only lengths 3, 4, and 6 need corrections.
    */
    int64 correction = 0;

    for (int i = 1; i + 2 <= N; ++i) {
        int x = a[i], y = a[i + 1], z = a[i + 2];
        int rangeMaximum = max(x, max(y, z));
        int answer = max(max(min(x, y), z), max(x, min(y, z)));
        correction += answer - rangeMaximum;
    }

    for (int i = 1; i + 3 <= N; ++i) {
        int v[4] = {a[i], a[i + 1], a[i + 2], a[i + 3]};
        sort(v, v + 4);
        int second = v[2], third = v[1];

        if (second > third) {
            int positions[2], count = 0;
            for (int j = 0; j < 4; ++j) {
                if (a[i + j] >= second) positions[count++] = j + 1;
            }
            int p = positions[0], q = positions[1];
            bool losing = (p == 1 && q == 3)
                       || (p == 2 && q == 3)
                       || (p == 2 && q == 4);
            if (losing) correction += (int64)third - second;
        }
    }

    for (int i = 1; i + 5 <= N; ++i) {
        int v[6] = {a[i], a[i + 1], a[i + 2],
                    a[i + 3], a[i + 4], a[i + 5]};
        sort(v, v + 6);
        int second = v[4], third = v[3];

        if (second > third) {
            int positions[2], count = 0;
            for (int j = 0; j < 6; ++j) {
                if (a[i + j] >= second) positions[count++] = j + 1;
            }
            int p = positions[0], q = positions[1];
            bool losing = (p == 2 && q == 4)
                       || (p == 2 && q == 5)
                       || (p == 3 && q == 5);
            if (losing) correction += (int64)third - second;
        }
    }

    cout << sumMaximumOdd + sumSecondMaximumEven + correction << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

static ll smallExcluded[7][7];

// Number of subarrays of an inactive gap having lengths
// first, first+2, first+4, ... .
static inline ll gapCount(ll d, int first) {
    if (d < first) return 0;
    ll k = (d - first) / 2 + 1;
    return k * (d - first + 1) - k * (k - 1);
}

// A specified active position is at distance A from the active position
// on its left and B from the one on its right. Count even-length (>=8)
// subarrays containing this position and no other active position.
static inline ll oneActiveCount(ll A, ll B) {
    ll evenA = (A + 1) / 2, oddA = A / 2;
    ll evenB = (B + 1) / 2, oddB = B / 2;

    // If u+v is odd, the corresponding subarray has even length.
    ll result = evenA * oddB + oddA * evenB;

    int ia = A >= 6 ? 6 : (int)A;
    int ib = B >= 6 ? 6 : (int)B;

    // Exclude lengths 2, 4 and 6.
    result -= smallExcluded[ia][ib];
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    int maxA = 0;
    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        maxA = max(maxA, a[i]);
    }

    // Precompute exclusions for sums u+v = 1,3,5. Only A,B <= 6 matter.
    for (int A = 1; A <= 6; ++A) {
        for (int B = 1; B <= 6; ++B) {
            for (int s : {1, 3, 5}) {
                int lo = max(0, s - (B - 1));
                int hi = min(s, A - 1);
                if (lo <= hi) smallExcluded[A][B] += hi - lo + 1;
            }
        }
    }

    ll answer = 0;

    // Length 1.
    for (int i = 1; i <= N; ++i) answer += a[i];

    // Length 3: the answer is the maximum of the two endpoints.
    for (int i = 1; i + 2 <= N; ++i) {
        answer += max(a[i], a[i + 2]);
    }

    // Lengths 2, 4 and 6. For two distinguished elements p<q, let the
    // three gaps around/between them have sizes L,M,R. The pair works
    // exactly when the number of nonempty gaps is at most len/2-1.
    auto addEvenLength = [&](int len) {
        if (len > N) return;

        int rounds = len / 2 - 1;
        vector<pair<int, int>> pairs;

        for (int p = 0; p < len; ++p) {
            for (int q = p + 1; q < len; ++q) {
                int nonemptyGaps =
                    (p > 0) +
                    (q - p - 1 > 0) +
                    (len - 1 - q > 0);

                if (nonemptyGaps <= rounds) {
                    pairs.emplace_back(p, q);
                }
            }
        }

        for (int start = 1; start + len - 1 <= N; ++start) {
            int best = 0;
            for (auto [p, q] : pairs) {
                best = max(best, min(a[start + p], a[start + q]));
            }
            answer += best;
        }
    };

    addEvenLength(2);
    addEvenLength(4);
    addEvenLength(6);

    /*
       Remaining subarrays:
         - odd length >= 5: answer is the subarray maximum;
         - even length >= 8: answer is the subarray second maximum.

       For a threshold x, call positions with value >= x active. We need:
         - odd long subarrays containing at least one active position;
         - even long subarrays containing at least two active positions.

       Summing these counts over x=1..max(a) gives the required sum.
       Active positions are maintained under deletions in a linked list.
    */

    const ll totalOdd = gapCount(N, 5);
    const ll totalEven = gapCount(N, 8);

    ll zeroOdd = 0;       // Qualifying odd subarrays with no active position.
    ll zeroEven = 0;      // Qualifying even subarrays with no active position.
    ll exactlyOne = 0;    // Qualifying even subarrays with exactly one active.

    vector<int> prv(N + 2), nxt(N + 2);
    for (int i = 0; i <= N + 1; ++i) {
        prv[i] = i - 1;
        nxt[i] = i + 1;
    }

    // Buckets of positions by value, using linked lists.
    vector<int> head(N + 1, -1), bucketNext(N + 1, -1);
    for (int i = 1; i <= N; ++i) {
        bucketNext[i] = head[a[i]];
        head[a[i]] = i;
    }

    for (int x = 1; x <= maxA; ++x) {
        answer += totalOdd - zeroOdd;
        answer += totalEven - zeroEven - exactlyOne;

        if (x == maxA) break;

        // Delete positions whose value is x, preparing threshold x+1.
        for (int i = head[x]; i != -1; i = bucketNext[i]) {
            int p = prv[i];
            int q = nxt[i];

            ll A = i - p;
            ll B = q - i;

            // Merge the two inactive gaps, with position i joining them.
            zeroOdd += gapCount(A + B - 1, 5)
                     - gapCount(A - 1, 5)
                     - gapCount(B - 1, 5);

            zeroEven += gapCount(A + B - 1, 8)
                      - gapCount(A - 1, 8)
                      - gapCount(B - 1, 8);

            // Remove i's exactly-one-active contribution.
            exactlyOne -= oneActiveCount(A, B);

            // Only the nearest active neighbors change their contributions.
            if (p != 0) {
                ll leftDistance = p - prv[p];
                exactlyOne -= oneActiveCount(leftDistance, A);
                exactlyOne += oneActiveCount(leftDistance, A + B);
            }

            if (q != N + 1) {
                ll rightDistance = nxt[q] - q;
                exactlyOne -= oneActiveCount(B, rightDistance);
                exactlyOne += oneActiveCount(A + B, rightDistance);
            }

            nxt[p] = q;
            prv[q] = p;
        }
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

static int lowPairs[7][7];

// Number of odd-length subarrays of length at least 5 in a segment of length g.
static inline int64 oddFamily(int g) {
    if (g < 5) return 0;
    int64 h = (g + 1) / 2;
    int64 allOdd = h * (g + 1 - h);
    return allOdd - g - (g - 2);
}

// Number of even-length subarrays of length at least 8 in a segment of length g.
static inline int64 evenFamily(int g) {
    if (g < 8) return 0;
    int64 h = g / 2;
    int64 allEven = h * (g - h);
    return allEven - (g - 1) - (g - 3) - (g - 5);
}

/*
   Count subarrays containing one distinguished active position, where:
   L left endpoints and R right endpoints are available.
   The subarray must have even length at least 8.

   If x and y are the numbers of positions used on the two sides, then
   x+y must be odd and at least 7.
*/
static inline int64 oneActiveEven(int L, int R) {
    if (L + R <= 8) return 0;

    int64 evenL = (L + 1LL) / 2;
    int64 oddL = L / 2;
    int64 evenR = (R + 1LL) / 2;
    int64 oddR = R / 2;

    int64 result = evenL * oddR + oddL * evenR;
    result -= lowPairs[min(L, 6)][min(R, 6)];
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Pairs with odd sum less than 7, for small capped values of L and R.
    for (int L = 0; L <= 6; ++L) {
        for (int R = 0; R <= 6; ++R) {
            for (int x = 0; x <= 5; ++x) {
                for (int y = 0; y <= 5; ++y) {
                    if (x < L && y < R && ((x + y) & 1) && x + y < 7) {
                        ++lowPairs[L][R];
                    }
                }
            }
        }
    }

    int N;
    if (!(cin >> N)) return 0;

    vector<int> a(N + 1);
    vector<int> head(N + 1, -1), bucketNext(N + 1, -1);

    int maxA = 0;
    for (int i = 1; i <= N; ++i) {
        cin >> a[i];
        maxA = max(maxA, a[i]);
        bucketNext[i] = head[a[i]];
        head[a[i]] = i;
    }

    int64 answer = 0;

    // Length 1.
    for (int i = 1; i <= N; ++i) {
        answer += a[i];
    }

    // Length 2.
    for (int i = 1; i + 1 <= N; ++i) {
        answer += min(a[i], a[i + 1]);
    }

    // Length 3.
    for (int i = 1; i + 2 <= N; ++i) {
        answer += max(a[i], a[i + 2]);
    }

    // Length 4.
    for (int i = 1; i + 3 <= N; ++i) {
        int cur = min(a[i], a[i + 1]);
        cur = max(cur, min(a[i], a[i + 3]));
        cur = max(cur, min(a[i + 2], a[i + 3]));
        answer += cur;
    }

    /*
       Length 6. A pair of positions can supply the final two numbers iff:
       - it contains the first position, or
       - it contains the last position, or
       - its two positions are adjacent.
    */
    for (int i = 1; i + 5 <= N; ++i) {
        int x0 = a[i], x1 = a[i + 1], x2 = a[i + 2];
        int x3 = a[i + 3], x4 = a[i + 4], x5 = a[i + 5];

        int maxAfterFirst = max(max(x1, x2), max(x3, x4));
        maxAfterFirst = max(maxAfterFirst, x5);

        int maxBeforeLast = max(max(x0, x1), max(x2, x3));
        maxBeforeLast = max(maxBeforeLast, x4);

        int adjacent = min(x0, x1);
        adjacent = max(adjacent, min(x1, x2));
        adjacent = max(adjacent, min(x2, x3));
        adjacent = max(adjacent, min(x3, x4));
        adjacent = max(adjacent, min(x4, x5));

        int cur = max(min(x0, maxAfterFirst),
                      min(maxBeforeLast, x5));
        cur = max(cur, adjacent);
        answer += cur;
    }

    /*
       For odd lengths at least 5, the answer is the subarray maximum.
       For even lengths at least 8, it is the second maximum.

       Sweep the threshold v. Positions with value at least v are active.
       A maximum is at least v iff a subarray contains an active position;
       a second maximum is at least v iff it contains at least two.
    */
    if (N >= 5) {
        const int64 totalOdd = oddFamily(N);
        const int64 totalEven = evenFamily(N);
        const bool needEven = (totalEven != 0);

        vector<int> prev(N + 2), next(N + 2);
        for (int i = 0; i <= N + 1; ++i) {
            prev[i] = i - 1;
            next[i] = i + 1;
        }

        int64 zeroOdd = 0;
        int64 zeroEven = 0;
        int64 exactlyOneEven = 0;

        for (int v = 1; v <= maxA; ++v) {
            answer += totalOdd - zeroOdd;
            if (needEven) {
                answer += totalEven - zeroEven - exactlyOneEven;
            }

            // No further threshold is needed, so avoid the final deletions.
            if (v == maxA) break;

            for (int i = head[v]; i != -1; i = bucketNext[i]) {
                int p = prev[i];
                int q = next[i];

                int gapLeft = i - p - 1;
                int gapRight = q - i - 1;
                int mergedGap = q - p - 1;

                zeroOdd += oddFamily(mergedGap)
                         - oddFamily(gapLeft)
                         - oddFamily(gapRight);

                if (needEven) {
                    zeroEven += evenFamily(mergedGap)
                              - evenFamily(gapLeft)
                              - evenFamily(gapRight);

                    // Remove the term belonging to position i.
                    exactlyOneEven -= oneActiveEven(i - p, q - i);

                    // p's next active position changes from i to q.
                    if (p != 0) {
                        int leftChoices = p - prev[p];
                        exactlyOneEven +=
                            oneActiveEven(leftChoices, q - p)
                          - oneActiveEven(leftChoices, i - p);
                    }

                    // q's previous active position changes from i to p.
                    if (q != N + 1) {
                        int rightChoices = next[q] - q;
                        exactlyOneEven +=
                            oneActiveEven(q - p, rightChoices)
                          - oneActiveEven(q - i, rightChoices);
                    }
                }

                next[p] = q;
                prev[q] = p;
            }
        }
    }

    cout << answer << '\n';
    return 0;
}

