    for (int i = 1; i <= N; ++i) {
        nextInBucket[i] = head[a[i]];
        head[a[i]] = i;
    }

    auto gapEven = [](int g) -> int64 {
        return 1LL * (g / 2) * ((g + 1) / 2);
    };

    auto gapOdd = [&](int g) -> int64 {
        return 1LL * g * (g + 1) / 2 - gapEven(g);
    };

    // Number of even-length subarrays containing p, with left endpoint in
    // [P+1,p] and right endpoint in [p,Q-1].
    auto oneActiveEven = [](int p, int P, int Q) -> int64 {
        int64 leftEven = p / 2 - P / 2;
        int64 leftOdd = (p + 1) / 2 - (P + 1) / 2;
        int64 rightEven = (Q - 1) / 2 - (p - 1) / 2;
        int64 rightOdd = Q / 2 - p / 2;
        return leftEven * rightOdd + leftOdd * rightEven;
    };

    const int64 totalSubarrays = 1LL * N * (N + 1) / 2;
    const int64 totalEven = gapEven(N);
    const int64 totalOdd = totalSubarrays - totalEven;

    // Initially every position is active.
    vector<int> left(N + 2), right(N + 2);
    for (int i = 1; i <= N; ++i) {
        left[i] = i - 1;
        right[i] = i + 1;
    }
    right[0] = 1;
    left[N + 1] = N;

    int64 zeroEven = 0, zeroOdd = 0, exactlyOneEven = 0;
    int64 sumMaximumOdd = 0, sumSecondMaximumEven = 0;
    int previousValue = 0;

    // Process thresholds increasingly, removing positions below the next threshold.
    for (int value = 1; value <= maxValue; ++value) {
        if (head[value] == -1) continue;

        int64 withActiveOdd = totalOdd - zeroOdd;
        int64 withTwoActiveEven = totalEven - zeroEven - exactlyOneEven;

        int64 delta = value - previousValue;
        sumMaximumOdd += delta * withActiveOdd;
        sumSecondMaximumEven += delta * withTwoActiveEven;
        previousValue = value;

        for (int p = head[value]; p != -1; p = nextInBucket[p]) {
            int P = left[p], Q = right[p];

            exactlyOneEven -= oneActiveEven(p, P, Q);

            if (P != 0) {
                int PP = left[P];
                exactlyOneEven -= oneActiveEven(P, PP, p);
                exactlyOneEven += oneActiveEven(P, PP, Q);
            }
            if (Q != N + 1) {
                int QQ = right[Q];
                exactlyOneEven -= oneActiveEven(Q, p, QQ);
                exactlyOneEven += oneActiveEven(Q, P, QQ);
            }

            int oldGapLeft = p - P - 1;
            int oldGapRight = Q - p - 1;
            int mergedGap = Q - P - 1;

            zeroEven += gapEven(mergedGap)
                      - gapEven(oldGapLeft) - gapEven(oldGapRight);
            zeroOdd += gapOdd(mergedGap)
                     - gapOdd(oldGapLeft) - gapOdd(oldGapRight);

            right[P] = Q;
            left[Q] = P;
        }
    }

    /*
       For odd lengths at least 5, the answer is the subarray maximum.
       For even lengths at least 8, it is the second maximum.
       Lengths 1 and 2 already agree with these formulas.
       Only lengths 3, 4, and 6 need corrections.
    */
    int64 correction = 0;

    for (int i = 1; i + 2 <= N; ++i) {
        int x = a[i], y = a[i + 1], z = a[i + 2];
        int rangeMaximum = max(x, max(y, z));
        int answer = max(max(min(x, y), z), max(x, min(y, z)));
        correction += answer - rangeMaximum;
    }

    for (int i = 1; i + 3 <= N; ++i) {
        int v[4] = {a[i], a[i + 1], a[i + 2], a[i + 3]};
        sort(v, v + 4);
        int second = v[2], third = v[1];

        if (second > third) {
            int positions[2], count = 0;
            for (int j = 0; j < 4; ++j) {
                if (a[i + j] >= second) positions[count++] = j + 1;
            }
            int p = positions[0], q = positions[1];
            bool losing = (p == 1 && q == 3)
                       || (p == 2 && q == 3)
                       || (p == 2 && q == 4);
            if (losing) correction += (int64)third - second;
        }
    }

    for (int i = 1; i + 5 <= N; ++i) {
        int v[6] = {a[i], a[i + 1], a[i + 2],
                    a[i + 3], a[i + 4], a[i + 5]};
        sort(v, v + 6);
        int second = v[4], third = v[3];

        if (second > third) {
            int positions[2], count = 0;
            for (int j = 0; j < 6; ++j) {
                if (a[i + j] >= second) positions[count++] = j + 1;
            }
            int p = positions[0], q = positions[1];
            bool losing = (p == 2 && q == 4)
                       || (p == 2 && q == 5)
                       || (p == 3 && q == 5);
            if (losing) correction += (int64)third - second;
        }
    }

    cout << sumMaximumOdd + sumSecondMaximumEven + correction << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

unsigned char winning[7][64];

bool gameWins(const vector<int>& b, bool minOperation) {
    if (b.size() == 1) return b[0];

    int m = (int)b.size();
    for (int i = 0; i + 1 < m; ++i) {
        vector<int> c = b;
        if (minOperation) c[i] = b[i] & b[i + 1];
        else c[i] = b[i] | b[i + 1];
        c.erase(c.begin() + i + 1);

        if (gameWins(c, !minOperation)) return true;
    }
    return false;
}

void precomputeWinningMasks() {
    for (int n = 1; n <= 6; ++n) {
        for (int mask = 0; mask < (1 << n); ++mask) {
            vector<int> b(n);
            for (int i = 0; i < n; ++i) b[i] = (mask >> i) & 1;
            winning[n][mask] = gameWins(b, true);
        }
    }
}

int smallAnswer(const int* v, int n) {
    int order[6];
    for (int i = 0; i < n; ++i) order[i] = i;

    for (int i = 1; i < n; ++i) {
        int x = order[i], j = i;
        while (j > 0 && v[order[j - 1]] < v[x]) {
            order[j] = order[j - 1];
            --j;
        }
        order[j] = x;
    }

    int mask = 0;
    for (int i = 0; i < n; ++i) {
        mask |= 1 << order[i];
        if (winning[n][mask]) return v[order[i]];
    }
    return 0;
}

long long parityCount(int l, int r, int p) {
    if (l > r) return 0;
    int len = r - l + 1;
    if ((l & 1) == p) return (len + 1) / 2;
    return len / 2;
}

// Counts pairs (l,r) in the two intervals having the requested parity,
// then removes the short subarrays already handled directly.
long long rectangleCount(int A, int B, int C, int D,
                         bool sameParity, int maxShortDistance) {
    if (A > B || C > D) return 0;

    long long lo = parityCount(A, B, 1);
    long long le = parityCount(A, B, 0);
    long long ro = parityCount(C, D, 1);
    long long re = parityCount(C, D, 0);

    long long result;
    if (sameParity) result = lo * ro + le * re;
    else result = lo * re + le * ro;

    for (int d = sameParity ? 0 : 1; d <= maxShortDistance; d += 2) {
        int l = max(A, C - d);
        int r = min(B, D - d);
        if (l <= r) result -= r - l + 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    precomputeWinningMasks();

    int N;
    cin >> N;
    vector<int> a(N);
    for (int& x : a) cin >> x;

    long long answer = 0;

    // All subarrays of length at most 6.
    for (int i = 0; i < N; ++i) answer += a[i];

    for (int i = 0; i + 1 < N; ++i)
        answer += min(a[i], a[i + 1]);

    for (int i = 0; i + 2 < N; ++i)
        answer += max(a[i], a[i + 2]);

    for (int i = 0; i + 3 < N; ++i)
        answer += smallAnswer(a.data() + i, 4);

    for (int i = 0; i + 4 < N; ++i) {
        int mx = a[i];
        for (int j = 1; j < 5; ++j) mx = max(mx, a[i + j]);
        answer += mx;
    }

    for (int i = 0; i + 5 < N; ++i)
        answer += smallAnswer(a.data() + i, 6);

    // For odd lengths at least 7 the answer is the maximum.
    // For even lengths at least 8 it is the second maximum.
    // Use a total order on elements, breaking equal values by index.
    auto stronger = [&](int i, int j) {
        return a[i] > a[j] || (a[i] == a[j] && i < j);
    };

    vector<int> prevStronger(N), nextStronger(N), st;
    st.reserve(N);

    for (int i = 0; i < N; ++i) {
        while (!st.empty() && stronger(i, st.back())) st.pop_back();
        prevStronger[i] = st.empty() ? -1 : st.back();
        st.push_back(i);
    }

    st.clear();
    for (int i = N - 1; i >= 0; --i) {
        while (!st.empty() && stronger(i, st.back())) st.pop_back();
        nextStronger[i] = st.empty() ? N : st.back();
        st.push_back(i);
    }

    for (int i = 0; i < N; ++i) {
        int p = prevStronger[i];
        int q = nextStronger[i];

        // Subarrays for which a[i] is the maximum. Keep odd lengths >= 7.
        long long cnt = rectangleCount(
            p + 1, i, i, q - 1, true, 4
        );
        answer += cnt * a[i];

        // a[i] is the second strongest element, and the strongest is on its left.
        if (p != -1) {
            int p2 = prevStronger[p];
            cnt = rectangleCount(
                p2 + 1, p, i, q - 1, false, 5
            );
            answer += cnt * a[i];
        }

        // The strongest element is on the right of a[i].
        if (q != N) {
            int q2 = nextStronger[q];
            cnt = rectangleCount(
                p + 1, i, q, q2 - 1, false, 5
            );
            answer += cnt * a[i];
        }
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct FastSet {
    static constexpr int INF = INT_MAX;
    int n;
    vector<int> sz;
    vector<vector<uint64_t>> bits;

    explicit FastSet(int n_) : n(n_) {
        int cur = n;
        while (true) {
            sz.push_back(cur);
            bits.emplace_back((cur + 63) / 64, 0);
            if (cur == 1) break;
            cur = (cur + 63) / 64;
        }
    }

    void insert(int x) {
        for (int lev = 0; lev < (int)bits.size(); ++lev) {
            int w = x >> 6;
            uint64_t mask = 1ULL << (x & 63);
            uint64_t old = bits[lev][w];
            bits[lev][w] = old | mask;
            if (old != 0 || lev + 1 == (int)bits.size()) break;
            x = w;
        }
    }

    int nextAt(int lev, int x) const {
        if (x >= sz[lev]) return INF;
        int w = x >> 6;
        int b = x & 63;
        uint64_t mask = bits[lev][w] & (~0ULL << b);
        if (mask) return (w << 6) + __builtin_ctzll(mask);
        if (lev + 1 == (int)bits.size()) return INF;
        int nw = nextAt(lev + 1, w + 1);
        if (nw == INF) return INF;
        return (nw << 6) + __builtin_ctzll(bits[lev][nw]);
    }

    int prevAt(int lev, int x) const {
        if (x < 0) return -1;
        int w = x >> 6;
        int b = x & 63;
        uint64_t mask = bits[lev][w] & (~0ULL >> (63 - b));
        if (mask) return (w << 6) + 63 - __builtin_clzll(mask);
        if (lev + 1 == (int)bits.size()) return -1;
        int nw = prevAt(lev + 1, w - 1);
        if (nw == -1) return -1;
        return (nw << 6) + 63 - __builtin_clzll(bits[lev][nw]);
    }

    int next(int x) const {
        if (x < 0) x = 0;
        return nextAt(0, x);
    }

    int prev(int x) const {
        if (x >= n) x = n - 1;
        return prevAt(0, x);
    }
};

struct SegTree {
    int n;
    vector<long long> sum;
    vector<int> setv, addv;

    explicit SegTree(int n_) : n(n_), sum(4 * n_), setv(4 * n_), addv(4 * n_) {}

    void applySet(int v, int l, int r, int x) {
        sum[v] = 1LL * (r - l + 1) * x;
        setv[v] = x;
        addv[v] = 0;
    }

    void applyAdd(int v, int l, int r, int x) {
        sum[v] += 1LL * (r - l + 1) * x;
        addv[v] += x;
    }

    void push(int v, int l, int r) {
        if (!setv[v] && !addv[v]) return;
        int m = (l + r) >> 1;
        if (setv[v]) {
            applySet(v << 1, l, m, setv[v]);
            applySet(v << 1 | 1, m + 1, r, setv[v]);
            setv[v] = 0;
        }
        if (addv[v]) {
            applyAdd(v << 1, l, m, addv[v]);
            applyAdd(v << 1 | 1, m + 1, r, addv[v]);
            addv[v] = 0;
        }
    }

    void rangeSet(int v, int l, int r, int ql, int qr, int x) {
        if (ql <= l && r <= qr) {
            applySet(v, l, r, x);
            return;
        }
        push(v, l, r);
        int m = (l + r) >> 1;
        if (ql <= m) rangeSet(v << 1, l, m, ql, qr, x);
        if (qr > m) rangeSet(v << 1 | 1, m + 1, r, ql, qr, x);
        sum[v] = sum[v << 1] + sum[v << 1 | 1];
    }

    void rangeAdd(int v, int l, int r, int ql, int qr, int x) {
        if (ql <= l && r <= qr) {
            applyAdd(v, l, r, x);
            return;
        }
        push(v, l, r);
        int m = (l + r) >> 1;
        if (ql <= m) rangeAdd(v << 1, l, m, ql, qr, x);
        if (qr > m) rangeAdd(v << 1 | 1, m + 1, r, ql, qr, x);
        sum[v] = sum[v << 1] + sum[v << 1 | 1];
    }

    void setRange(int l, int r, int x) {
        rangeSet(1, 0, n - 1, l, r, x);
    }

    void addRange(int l, int r, int x) {
        rangeAdd(1, 0, n - 1, l, r, x);
    }

    long long total() const {
        return sum[1];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> head(N + 1, -1), nxt(N + 1);
    for (int i = 1; i <= N; ++i) {
        int x;
        cin >> x;
        nxt[i] = head[x];
        head[x] = i;
    }

    // Parity 0: even positions. Parity 1: odd positions.
    FastSet active[2] = {FastSet(N / 2), FastSet((N + 1) / 2)};
    SegTree seg[2] = {SegTree(N / 2), SegTree((N + 1) / 2)};

    auto actualPos = [](int parity, int idx) {
        return 2 * idx + (parity ? 1 : 2);
    };

    auto countLE = [](int parity, int x) {
        if (x <= 0) return 0;
        return parity ? (x + 1) / 2 : x / 2;
    };

    auto endpointCount = [&](int pos) {
        return (N - pos) / 2 + 1;
    };

    auto activate = [&](int p) {
        int s = p & 1;
        int o = s ^ 1;
        int k = s ? (p - 1) / 2 : p / 2 - 1;

        int prevSame = active[s].prev(k - 1);
        int nextSame = active[s].next(k + 1);

        int tP = countLE(o, p);
        int nextOpp = active[o].next(tP);

        int value = endpointCount(p);
        if (nextOpp != FastSet::INF) {
            value += endpointCount(actualPos(o, nextOpp));
        }

        // Activating p can give an earlier second required position to
        // a contiguous collection of starts of the opposite parity.
        int prevPos = prevSame >= 0 ? actualPos(s, prevSame) : 0;
        int tLeft = countLE(o, prevPos);
        int lastOpp = active[o].prev(tP - 1);

        if (lastOpp >= tLeft) {
            int before = active[o].prev(tLeft - 1);
            int oldValue = 0;
            if (nextSame != FastSet::INF) {
                oldValue = endpointCount(actualPos(s, nextSame));
            }
            int delta = endpointCount(p) - oldValue;
            seg[o].addRange(before + 1, lastOpp, delta);
        }

        // Starts whose nearest activated position of their own parity
        // becomes p.
        seg[s].setRange(prevSame + 1, k, value);
        active[s].insert(k);
    };

    long long answer = 0;
    for (int value = N; value >= 1; --value) {
        for (int p = head[value]; p != -1; p = nxt[p]) {
            activate(p);
        }
        answer += seg[0].total() + seg[1].total();
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

static inline ll calcE(int g) {
    // Number of even-length subarrays of length >= 8 inside a gap of length g.
    if (g < 8) return 0;
    ll T = g / 2; // even lengths are 2*t, 4 <= t <= T
    if (T < 4) return 0;
    ll sumT = T * (T + 1) / 2 - 6; // sum t for t=4..T
    return (T - 3) * (g + 1LL) - 2 * sumT;
}

static inline ll calcF(int l, int r) {
    // Count pairs (x,y), 0<=x<=l, 0<=y<=r,
    // with x+y odd and x+y >= 7.
    ll evenL = l / 2 + 1;
    ll oddL = (l + 1) / 2;
    ll evenR = r / 2 + 1;
    ll oddR = (r + 1) / 2;

    ll total = evenL * oddR + oddL * evenR;

    ll small = 0;
    for (int s = 1; s <= 5; s += 2) {
        int lo = max(0, s - r);
        int hi = min(l, s);
        if (lo <= hi) small += hi - lo + 1;
    }
    return total - small;
}

static inline ll countOddMax(int L, int R) {
    // Count x in [0,L-1], y in [0,R-1] with x+y even and x+y >= 4.
    ll evenL = (L + 1LL) / 2;
    ll oddL = L / 2;
    ll evenR = (R + 1LL) / 2;
    ll oddR = R / 2;

    ll total = evenL * evenR + oddL * oddR;

    ll bad = 1; // (0,0)
    if (L >= 1 && R >= 3) ++bad; // (0,2)
    if (L >= 2 && R >= 2) ++bad; // (1,1)
    if (L >= 3 && R >= 1) ++bad; // (2,0)

    return total - bad;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N);
    int maxA = 0;

    vector<int> head(N + 1, -1), nxt(N);

    for (int i = 0; i < N; ++i) {
        cin >> a[i];
        int v = a[i];
        nxt[i] = head[v];
        head[v] = i;
        if (v > maxA) maxA = v;
    }

    ll ans = 0;

    // Length 1
    for (int i = 0; i < N; ++i) ans += a[i];

    // Length 2
    for (int i = 0; i + 1 < N; ++i) {
        ans += min(a[i], a[i + 1]);
    }

    // Length 3
    for (int i = 0; i + 2 < N; ++i) {
        ans += max(a[i], a[i + 2]);
    }

    // Length 4
    for (int i = 0; i + 3 < N; ++i) {
        int v1 = min(a[i], a[i + 1]);
        int v2 = min(a[i + 2], a[i + 3]);
        int v3 = min(a[i], a[i + 3]);
        ans += max({v1, v2, v3});
    }

    // Length 6
    if (N >= 6) {
        for (int s = 0; s + 5 < N; ++s) {
            int best = 0;
            for (int i = 0; i < 6; ++i) {
                for (int j = i + 1; j < 6; ++j) {
                    // Forbidden 0-indexed pairs: (1,3), (1,4), (2,4)
                    if ((i == 1 && j == 3) ||
                        (i == 1 && j == 4) ||
                        (i == 2 && j == 4)) {
                        continue;
                    }
                    best = max(best, min(a[s + i], a[s + j]));
                }
            }
            ans += best;
        }
    }

    // Odd lengths >= 5: answer is the maximum element.
    vector<int> leftLen(N);
    vector<int> st;
    st.reserve(N);

    for (int i = 0; i < N; ++i) {
        while (!st.empty() && a[st.back()] <= a[i]) st.pop_back();
        int p = st.empty() ? -1 : st.back();
        leftLen[i] = i - p;
        st.push_back(i);
    }

    st.clear();

    for (int i = N - 1; i >= 0; --i) {
        while (!st.empty() && a[st.back()] < a[i]) st.pop_back();
        int q = st.empty() ? N : st.back();
        int R = q - i;
        int L = leftLen[i];

        ans += 1LL * a[i] * countOddMax(L, R);
        st.push_back(i);
    }

    // Even lengths >= 8: answer is the second largest element.
    // Sum over thresholds T: count subarrays with at least two elements >= T.
    vector<int> prevPos(N), nextPos(N);
    for (int i = 0; i < N; ++i) {
        prevPos[i] = i - 1;
        nextPos[i] = i + 1;
    }

    ll zeroActive = 0;
    ll oneActive = 0;

    ll totalEven8 = calcE(N);
    ll currentC = totalEven8;
    ll secondSum = 0;

    for (int T = 1; T <= maxA; ++T) {
        secondSum += currentC;

        for (int p = head[T]; p != -1; p = nxt[p]) {
            int L = prevPos[p];
            int R = nextPos[p];

            int l = p - L - 1;
            int r = R - p - 1;
            int g = R - L - 1;

            zeroActive -= calcE(l) + calcE(r);
            zeroActive += calcE(g);

            oneActive -= calcF(l, r);

            if (L >= 0) {
                int LL = prevPos[L];
                int lgL = L - LL - 1;
                oneActive -= calcF(lgL, l);
                oneActive += calcF(lgL, g);
            }

            if (R < N) {
                int RR = nextPos[R];
                int rgR = RR - R - 1;
                oneActive -= calcF(r, rgR);
                oneActive += calcF(g, rgR);
            }

            if (L >= 0) nextPos[L] = R;
            if (R < N) prevPos[R] = L;

            currentC = totalEven8 - zeroActive - oneActive;
        }
    }

    ans += secondSum;

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

static inline ll Feven(int g) {
    // Number of subarrays inside a gap of length g
    // having even length >= 8.
    if (g < 8) return 0;
    ll K = (g - 8) / 2;
    return (K + 1) * ((ll)g - 7 - K);
}

static inline ll Fodd(int g) {
    // Number of subarrays inside a gap of length g
    // having odd length >= 7.
    if (g < 7) return 0;
    ll K = (g - 7) / 2;
    return (K + 1) * ((ll)g - 6 - K);
}

static inline ll cntEven(int n) {
    // Number of even integers in [0, n]
    if (n < 0) return 0;
    return n / 2 + 1;
}

static inline ll cntOdd(int n) {
    // Number of odd integers in [0, n]
    if (n < 0) return 0;
    return (n + 1) / 2;
}

static inline ll H(int A, int B) {
    // Count pairs (x,y), 0<=x<=A, 0<=y<=B, such that
    // x+y is odd and x+y >= 7.
    if (A < 0 || B < 0) return 0;

    ll ceA = cntEven(A), coA = cntOdd(A);
    ll ceB = cntEven(B), coB = cntOdd(B);

    ll total = ceA * coB + coA * ceB; // x+y odd

    ll sub = 0;
    // Remove x+y = 1, 3, 5
    for (int s = 1; s <= 5; s += 2) {
        int lo = max(0, s - B);
        int hi = min(A, s);
        if (lo <= hi) sub += hi - lo + 1;
    }

    return total - sub;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N + 1);
    for (int i = 1; i <= N; ++i) cin >> a[i];

    ll ans = 0;

    // Handle all small lengths directly.
    // L = 1
    for (int i = 1; i <= N; ++i) ans += a[i];

    // L = 2
    if (N >= 2) {
        for (int i = 1; i + 1 <= N; ++i) {
            ans += min(a[i], a[i + 1]);
        }
    }

    // L = 3
    if (N >= 3) {
        for (int i = 1; i + 2 <= N; ++i) {
            ans += max(a[i], a[i + 2]);
        }
    }

    // L = 4
    if (N >= 4) {
        for (int i = 1; i + 3 <= N; ++i) {
            int v1 = min(a[i], a[i + 1]);
            int v2 = min(a[i + 2], a[i + 3]);
            int v3 = min(a[i], a[i + 3]);
            ans += max(v1, max(v2, v3));
        }
    }

    // L = 5
    if (N >= 5) {
        for (int i = 1; i + 4 <= N; ++i) {
            int mx = a[i];
            for (int j = 1; j <= 4; ++j) mx = max(mx, a[i + j]);
            ans += mx;
        }
    }

    // L = 6
    if (N >= 6) {
        for (int i = 1; i + 5 <= N; ++i) {
            int b[6];
            for (int j = 0; j < 6; ++j) b[j] = a[i + j];

            int c[6];
            for (int j = 0; j < 6; ++j) c[j] = b[j];
            sort(c, c + 6, greater<int>());

            ll third = c[2];

            ll bestPair = 0;
            for (int p = 0; p < 6; ++p) {
                for (int q = p + 1; q < 6; ++q) {
                    bool bad =
                        (p == 1 && q == 3) || // (2,4) in 1-based
                        (p == 1 && q == 4) || // (2,5)
                        (p == 2 && q == 4);   // (3,5)

                    if (!bad) {
                        bestPair = max(bestPair, (ll)min(b[p], b[q]));
                    }
                }
            }

            ans += max(third, bestPair);
        }
    }

    // For odd length >= 7: answer is the maximum.
    // For even length >= 8: answer is the second maximum.
    //
    // Compute their sums by threshold sweep over values.

    vector<int> head(N + 2, -1), nxt(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        int v = a[i];
        nxt[i] = head[v];
        head[v] = i;
    }

    ll totalOdd = Fodd(N);
    ll totalEven = Feven(N);

    ll zeroOdd = totalOdd;
    ll zeroEven = totalEven;
    ll oneEven = 0;

    vector<int> leftGap(N + 2, 0), rightGap(N + 2, 0);
    set<int> active;

    ll ansLargeOdd = 0;
    ll ansLargeEven = 0;

    for (int v = N; v >= 1; --v) {
        for (int p = head[v]; p != -1; p = nxt[p]) {
            auto it = active.lower_bound(p);

            int s = (it == active.end() ? N + 1 : *it);
            int q;
            if (it == active.begin()) q = 0;
            else q = *prev(it);

            int g = s - q - 1;
            int L = p - q - 1;
            int R = s - p - 1;

            zeroEven -= Feven(g);
            zeroEven += Feven(L) + Feven(R);

            zeroOdd -= Fodd(g);
            zeroOdd += Fodd(L) + Fodd(R);

            if (q > 0) {
                oneEven -= H(leftGap[q], rightGap[q]);
                rightGap[q] = p - q - 1;
                oneEven += H(leftGap[q], rightGap[q]);
            }

            if (s <= N) {
                oneEven -= H(leftGap[s], rightGap[s]);
                leftGap[s] = s - p - 1;
                oneEven += H(leftGap[s], rightGap[s]);
            }

            leftGap[p] = p - q - 1;
            rightGap[p] = s - p - 1;
            oneEven += H(leftGap[p], rightGap[p]);

            active.insert(p);
        }

        ansLargeOdd += totalOdd - zeroOdd;
        ansLargeEven += totalEven - zeroEven - oneEven;
    }

    ans += ansLargeOdd + ansLargeEven;

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class FastScanner {
    static constexpr int BUFSIZE = 1 << 20;
    int idx = 0, size = 0;
    char buf[BUFSIZE];

    char getChar() {
        if (idx >= size) {
            size = (int)fread(buf, 1, BUFSIZE, stdin);
            idx = 0;
            if (size == 0) return 0;
        }
        return buf[idx++];
    }

public:
    int nextInt() {
        char c = getChar();
        while (c && (c < '0' || c > '9')) c = getChar();
        int x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = getChar();
        }
        return x;
    }
};

static inline long long countParityRange(int l, int r, int p) {
    if (l > r) return 0;
    if (p == 0) { // even
        return r / 2 - (l - 1) / 2;
    } else { // odd
        return (r + 1LL) / 2 - l / 2;
    }
}

static inline long long countEvenLenGE8(int l1, int l2, int r1, int r2) {
    if (l1 > l2 || r1 > r2) return 0;

    long long oddL = countParityRange(l1, l2, 1);
    long long evenL = countParityRange(l1, l2, 0);
    long long oddR = countParityRange(r1, r2, 1);
    long long evenR = countParityRange(r1, r2, 0);

    // Need r - l odd, i.e. l and r have opposite parity.
    long long total = oddL * evenR + evenL * oddR;

    // Subtract r - l = 1, 3, 5, since we need r - l >= 7.
    long long bad = 0;
    for (int d : {1, 3, 5}) {
        int lo = max(l1, r1 - d);
        int hi = min(l2, r2 - d);
        if (lo <= hi) bad += (long long)(hi - lo + 1);
    }

    long long res = total - bad;
    return res > 0 ? res : 0;
}

int main() {
    FastScanner fs;
    int N = fs.nextInt();

    vector<int> a(N + 1);
    for (int i = 1; i <= N; ++i) a[i] = fs.nextInt();

    long long ans = 0;

    // Length 1
    for (int i = 1; i <= N; ++i) ans += a[i];

    // Length 2
    for (int i = 1; i + 1 <= N; ++i) {
        ans += min(a[i], a[i + 1]);
    }

    // Length 3
    for (int i = 1; i + 2 <= N; ++i) {
        ans += max(a[i], a[i + 2]);
    }

    // Length 4
    for (int i = 1; i + 3 <= N; ++i) {
        int v1 = min(a[i], a[i + 1]);
        int v2 = min(a[i], a[i + 3]);
        int v3 = min(a[i + 2], a[i + 3]);
        ans += max({v1, v2, v3});
    }

    // Length 6
    static const int pairs6[12][2] = {
        {1, 2}, {1, 3}, {1, 4}, {1, 5}, {1, 6},
        {2, 3}, {2, 6},
        {3, 4}, {3, 6},
        {4, 5}, {4, 6},
        {5, 6}
    };

    for (int i = 1; i + 5 <= N; ++i) {
        int best = 0;
        for (int k = 0; k < 12; ++k) {
            int x = a[i + pairs6[k][0] - 1];
            int y = a[i + pairs6[k][1] - 1];
            best = max(best, min(x, y));
        }
        ans += best;
    }

    // Odd lengths >= 5: answer is maximum of the subarray.
    vector<int> prv(N + 1), nxt(N + 1);
    vector<int> st;
    st.reserve(N);

    for (int i = 1; i <= N; ++i) {
        while (!st.empty() && a[st.back()] <= a[i]) st.pop_back();
        prv[i] = st.empty() ? 0 : st.back();
        st.push_back(i);
    }

    st.clear();

    for (int i = N; i >= 1; --i) {
        while (!st.empty() && a[st.back()] < a[i]) st.pop_back();
        nxt[i] = st.empty() ? N + 1 : st.back();
        st.push_back(i);
    }

    long long oddMaxSum = 0;

    for (int i = 1; i <= N; ++i) {
        long long A = i - prv[i];
        long long B = nxt[i] - i;

        long long oddA = (A + 1) / 2;
        long long evenA = A / 2;
        long long oddB = (B + 1) / 2;
        long long evenB = B / 2;

        long long total = oddA * oddB + evenA * evenB;

        long long bad = 0;
        if (A >= 1 && B >= 1) ++bad; // u + v = 2
        if (A >= 1 && B >= 3) ++bad; // u + v = 4
        if (A >= 2 && B >= 2) ++bad; // u + v = 4
        if (A >= 3 && B >= 1) ++bad; // u + v = 4

        long long cnt = total - bad;
        if (cnt < 0) cnt = 0;

        oddMaxSum += 1LL * a[i] * cnt;
    }

    ans += oddMaxSum;

    // Even lengths >= 8: answer is the second maximum of the subarray.
    vector<int> head(N + 1, -1), nextPos(N + 1);

    for (int i = 1; i <= N; ++i) {
        int v = a[i];
        nextPos[i] = head[v];
        head[v] = i;
    }

    set<int> active;
    active.insert(0);
    active.insert(N + 1);

    long long cur = 0;
    long long evenSecondMaxSum = 0;

    for (int x = N; x >= 1; --x) {
        for (int p = head[x]; p != -1; p = nextPos[p]) {
            auto itR = active.lower_bound(p);
            int R = *itR;
            auto itL = prev(itR);
            int L = *itL;

            int prevL = 0;
            int nextR = N + 1;

            if (L != 0) {
                auto itPrevL = prev(itL);
                prevL = *itPrevL;
            }

            if (R != N + 1) {
                auto itNextR = next(itR);
                nextR = *itNextR;
            }

            long long add = 0;

            // Subarrays newly getting at least two active positions:
            // include p and L, but not R.
            if (L > 0) {
                add += countEvenLenGE8(prevL + 1, L, p, R - 1);
            }

            // Include p and R, but not L.
            if (R <= N) {
                add += countEvenLenGE8(L + 1, p, R, nextR - 1);
            }

            cur += add;
            active.insert(p);
        }

        evenSecondMaxSum += cur;
    }

    ans += evenSecondMaxSum;

    printf("%lld\n", ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct NextTwo {
    vector<int> first, second;
};

// For every position, find the first and second positions to its right
// whose values are >= its value (GreaterEqual = true), or > its value.
template <bool GreaterEqual>
NextTwo findNextTwo(const vector<int>& a) {
    int n = (int)a.size();

    NextTwo result;
    result.first.assign(n, n);
    result.second.assign(n, n);

    vector<int> waitingFirst, waitingSecond, temporary;
    waitingFirst.reserve(n);
    waitingSecond.reserve(n);
    temporary.reserve(n);

    auto qualifies = [&](int current, int waiting) {
        if constexpr (GreaterEqual) {
            return a[current] >= a[waiting];
        } else {
            return a[current] > a[waiting];
        }
    };

    for (int i = 0; i < n; ++i) {
        while (!waitingSecond.empty() &&
               qualifies(i, waitingSecond.back())) {
            result.second[waitingSecond.back()] = i;
            waitingSecond.pop_back();
        }

        temporary.clear();

        while (!waitingFirst.empty() &&
               qualifies(i, waitingFirst.back())) {
            result.first[waitingFirst.back()] = i;
            temporary.push_back(waitingFirst.back());
            waitingFirst.pop_back();
        }

        for (int j = (int)temporary.size() - 1; j >= 0; --j) {
            waitingSecond.push_back(temporary[j]);
        }

        waitingFirst.push_back(i);
    }

    return result;
}

struct ParityCounts {
    int64 even, odd;
};

inline ParityCounts countParity(int left, int right) {
    if (left > right) return {0, 0};

    int64 length = right - left + 1;
    int64 even = (length + ((left & 1) == 0 ? 1 : 0)) / 2;
    return {even, length - even};
}

inline int secondLargest(const int* a, int length) {
    int largest = 0;
    int second = 0;

    for (int i = 0; i < length; ++i) {
        if (a[i] >= largest) {
            second = largest;
            largest = a[i];
        } else if (a[i] > second) {
            second = a[i];
        }
    }

    return second;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n);
    for (int& x : a) cin >> x;

    // Nearest and second-nearest positions to the right with value >= a[i].
    NextTwo next = findNextTwo<true>(a);

    // Nearest and second-nearest positions to the left with value > a[i].
    vector<int> previous1(n, -1), previous2(n, -1);
    {
        vector<int> reversed(a.rbegin(), a.rend());
        NextTwo prev = findNextTwo<false>(reversed);

        for (int i = 0; i < n; ++i) {
            int reversedIndex = n - 1 - i;

            if (prev.first[reversedIndex] < n) {
                previous1[i] = n - 1 - prev.first[reversedIndex];
            }
            if (prev.second[reversedIndex] < n) {
                previous2[i] = n - 1 - prev.second[reversedIndex];
            }
        }
    }

    int64 answer = 0;

    // Sum maxima over all odd-length subarrays, and second maxima over
    // all even-length subarrays.
    for (int i = 0; i < n; ++i) {
        // i is the rightmost occurrence of the maximum.
        // An odd-length interval has endpoints of the same parity.
        {
            ParityCounts left = countParity(previous1[i] + 1, i);
            ParityCounts right = countParity(i, next.first[i] - 1);

            int64 count = left.even * right.even + left.odd * right.odd;
            answer += count * a[i];
        }

        // i is the second-largest element, and the largest lies to its right.
        if (next.first[i] < n) {
            ParityCounts left = countParity(previous1[i] + 1, i);
            ParityCounts right = countParity(next.first[i], next.second[i] - 1);

            int64 count = left.even * right.odd + left.odd * right.even;
            answer += count * a[i];
        }

        // i is the second-largest element, and the largest lies to its left.
        if (previous1[i] >= 0) {
            ParityCounts left = countParity(previous2[i] + 1, previous1[i]);
            ParityCounts right = countParity(i, next.first[i] - 1);

            int64 count = left.even * right.odd + left.odd * right.even;
            answer += count * a[i];
        }
    }

    // Length 3: the answer is max(a[i], a[i+2]), rather than the
    // maximum of all three elements.
    for (int i = 0; i + 2 < n; ++i) {
        int ordinary = max(a[i], max(a[i + 1], a[i + 2]));
        int actual = max(a[i], a[i + 2]);
        answer += actual - ordinary;
    }

    // Length 4: allowed pairs are (1,2), (3,4), and (1,4).
    for (int i = 0; i + 3 < n; ++i) {
        int ordinary = secondLargest(a.data() + i, 4);

        int actual = max(
            min(a[i], a[i + 1]),
            max(
                min(a[i + 2], a[i + 3]),
                min(a[i], a[i + 3])
            )
        );

        answer += actual - ordinary;
    }

    // Length 6: an allowed pair has an endpoint, or consists of
    // two consecutive positions.
    for (int i = 0; i + 5 < n; ++i) {
        int ordinary = secondLargest(a.data() + i, 6);

        int actual = 0;
        for (int p = 0; p < 6; ++p) {
            for (int q = p + 1; q < 6; ++q) {
                if (p == 0 || q == 5 || q == p + 1) {
                    actual = max(actual, min(a[i + p], a[i + q]));
                }
            }
        }

        answer += actual - ordinary;
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

// Number of integers of parity p in [l, r], where p = 0 means even.
static int64 parityCount(int l, int r, int p) {
    if (l > r) return 0;
    int64 len = r - l + 1;
    int64 even = r / 2 - (l - 1) / 2;
    return (p == 0 ? even : len - even);
}

// Count pairs (l, r) with l in [l1, l2], r in [r1, r2],
// such that r-l+1 has the requested parity and is at least minLen.
static int64 countPairs(int l1, int l2, int r1, int r2,
                         int parity, int minLen) {
    if (l1 > l2 || r1 > r2) return 0;

    int64 lc[2] = {
        parityCount(l1, l2, 0),
        parityCount(l1, l2, 1)
    };
    int64 rc[2] = {
        parityCount(r1, r2, 0),
        parityCount(r1, r2, 1)
    };

    int64 result;
    if (parity == 1) {
        // Odd length: l and r have the same parity.
        result = lc[0] * rc[0] + lc[1] * rc[1];
    } else {
        // Even length: l and r have different parities.
        result = lc[0] * rc[1] + lc[1] * rc[0];
    }

    // Remove intervals shorter than minLen.
    for (int len = 1; len < minLen; ++len) {
        if ((len & 1) != parity) continue;

        int d = len - 1;
        int lo = max(l1, r1 - d);
        int hi = min(l2, r2 - d);
        if (lo <= hi) result -= hi - lo + 1;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i) cin >> a[i];

    int64 answer = 0;

    // Length 1.
    for (int i = 1; i <= n; ++i) {
        answer += a[i];
    }

    // Length 2.
    for (int i = 1; i < n; ++i) {
        answer += min(a[i], a[i + 1]);
    }

    // Length 3.
    for (int i = 1; i + 2 <= n; ++i) {
        answer += max(a[i], a[i + 2]);
    }

    // Length 4.
    for (int i = 1; i + 3 <= n; ++i) {
        int best = max({
            min(a[i], a[i + 1]),
            min(a[i], a[i + 3]),
            min(a[i + 2], a[i + 3])
        });
        answer += best;
    }

    // Length 6.
    for (int i = 1; i + 5 <= n; ++i) {
        int best = 0;
        for (int p = 1; p <= 6; ++p) {
            for (int q = p + 1; q <= 6; ++q) {
                // These are exactly the feasible pairs of positions.
                if (p == 1 || q == p + 1 || q == 6) {
                    best = max(best, min(a[i + p - 1], a[i + q - 1]));
                }
            }
        }
        answer += best;
    }

    // Break ties by index: (a[i], i), so all order statistics are unique.
    auto greaterKey = [&](int x, int y) {
        return a[x] > a[y] || (a[x] == a[y] && x > y);
    };

    vector<int> L1(n + 2, 0), L2(n + 2, 0);
    vector<int> R1(n + 2, n + 1), R2(n + 2, n + 1);

    vector<int> s1, s2, temp;
    s1.reserve(n);
    s2.reserve(n);
    temp.reserve(n);

    // First and second greater elements to the right.
    for (int i = 1; i <= n; ++i) {
        while (!s2.empty() && greaterKey(i, s2.back())) {
            R2[s2.back()] = i;
            s2.pop_back();
        }

        temp.clear();
        while (!s1.empty() && greaterKey(i, s1.back())) {
            R1[s1.back()] = i;
            temp.push_back(s1.back());
            s1.pop_back();
        }

        // Transfer in reverse order.
        while (!temp.empty()) {
            s2.push_back(temp.back());
            temp.pop_back();
        }
        s1.push_back(i);
    }

    s1.clear();
    s2.clear();
    temp.clear();

    // First and second greater elements to the left.
    for (int i = n; i >= 1; --i) {
        while (!s2.empty() && greaterKey(i, s2.back())) {
            L2[s2.back()] = i;
            s2.pop_back();
        }

        temp.clear();
        while (!s1.empty() && greaterKey(i, s1.back())) {
            L1[s1.back()] = i;
            temp.push_back(s1.back());
            s1.pop_back();
        }

        while (!temp.empty()) {
            s2.push_back(temp.back());
            temp.pop_back();
        }
        s1.push_back(i);
    }

    for (int i = 1; i <= n; ++i) {
        // Odd lengths >= 5: the answer is the maximum.
        int64 cnt = countPairs(
            L1[i] + 1, i,
            i, R1[i] - 1,
            1, 5
        );
        answer += 1LL * a[i] * cnt;

        // Even lengths >= 8: the answer is the second-largest value.
        cnt = 0;

        // The unique greater element is to the left.
        cnt += countPairs(
            L2[i] + 1, L1[i],
            i, R1[i] - 1,
            0, 8
        );

        // The unique greater element is to the right.
        cnt += countPairs(
            L1[i] + 1, i,
            R1[i], R2[i] - 1,
            0, 8
        );

        answer += 1LL * a[i] * cnt;
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct ParityCounts {
    int64 even, odd;
};

static inline ParityCounts parityCounts(int l, int r) {
    if (l > r) return {0, 0};
    int64 len = r - l + 1;
    int64 even = r / 2 - (l - 1) / 2;
    return {even, len - even};
}

static int secondLargest(const vector<int>& a, int first, int len) {
    int largest = 0, second = 0;
    for (int j = 0; j < len; ++j) {
        int x = a[first + j];
        if (x >= largest) {
            second = largest;
            largest = x;
        } else if (x > second) {
            second = x;
        }
    }
    return second;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i) cin >> a[i];

    // Break ties by index, so every subarray has a unique maximum
    // and a unique second maximum under this ordering.
    vector<int64> key(n + 1);
    for (int i = 1; i <= n; ++i) {
        key[i] = 1LL * a[i] * (n + 1) + i;
    }

    // L1/L2: first and second positions to the left with a larger key.
    // R1/R2: first and second positions to the right with a larger key.
    vector<int> L1(n + 2, 0), L2(n + 2, 0);
    vector<int> R1(n + 2, n + 1), R2(n + 2, n + 1);

    vector<int> st1, st2, moved;
    st1.reserve(n);
    st2.reserve(n);
    moved.reserve(n);

    // Second greater element to the right.
    for (int i = 1; i <= n; ++i) {
        while (!st2.empty() && key[st2.back()] < key[i]) {
            R2[st2.back()] = i;
            st2.pop_back();
        }

        moved.clear();
        while (!st1.empty() && key[st1.back()] < key[i]) {
            int j = st1.back();
            st1.pop_back();
            R1[j] = i;
            moved.push_back(j);
        }
        while (!moved.empty()) {
            st2.push_back(moved.back());
            moved.pop_back();
        }
        st1.push_back(i);
    }

    st1.clear();
    st2.clear();
    moved.clear();

    // Second greater element to the left.
    for (int i = n; i >= 1; --i) {
        while (!st2.empty() && key[st2.back()] < key[i]) {
            L2[st2.back()] = i;
            st2.pop_back();
        }

        moved.clear();
        while (!st1.empty() && key[st1.back()] < key[i]) {
            int j = st1.back();
            st1.pop_back();
            L1[j] = i;
            moved.push_back(j);
        }
        while (!moved.empty()) {
            st2.push_back(moved.back());
            moved.pop_back();
        }
        st1.push_back(i);
    }

    int64 answer = 0;

    // Sum of maxima over all odd-length subarrays.
    for (int i = 1; i <= n; ++i) {
        ParityCounts left = parityCounts(L1[i] + 1, i);
        ParityCounts right = parityCounts(i, R1[i] - 1);

        // An odd-length interval has endpoints of the same parity.
        int64 count = left.even * right.even + left.odd * right.odd;
        answer += 1LL * a[i] * count;
    }

    // Sum of second maxima over all even-length subarrays.
    for (int i = 1; i <= n; ++i) {
        // The maximum is to the left of the second maximum.
        if (L1[i] != 0) {
            ParityCounts left = parityCounts(L2[i] + 1, L1[i]);
            ParityCounts right = parityCounts(i, R1[i] - 1);

            // An even-length interval has endpoints of opposite parity.
            int64 count = left.even * right.odd + left.odd * right.even;
            answer += 1LL * a[i] * count;
        }

        // The maximum is to the right of the second maximum.
        if (R1[i] != n + 1) {
            ParityCounts left = parityCounts(L1[i] + 1, i);
            ParityCounts right = parityCounts(R1[i], R2[i] - 1);

            int64 count = left.even * right.odd + left.odd * right.even;
            answer += 1LL * a[i] * count;
        }
    }

    // Correct length-3 subarrays:
    // actual answer = max(first, third), rather than max(first, second, third).
    for (int i = 1; i + 2 <= n; ++i) {
        int allThree = max({a[i], a[i + 1], a[i + 2]});
        int endpoints = max(a[i], a[i + 2]);
        answer -= allThree - endpoints;
    }

    // Correct length-4 subarrays.
    for (int i = 1; i + 3 <= n; ++i) {
        int special = max({
            min(a[i], a[i + 1]),
            min(a[i], a[i + 3]),
            min(a[i + 2], a[i + 3])
        });

        int baseline = secondLargest(a, i, 4);
        answer -= baseline - special;
    }

    // Correct length-6 subarrays.
    static constexpr int allowedPairs[12][2] = {
        {1, 2}, {1, 3}, {1, 4}, {1, 5}, {1, 6},
        {2, 3}, {2, 6},
        {3, 4}, {3, 6},
        {4, 5}, {4, 6},
        {5, 6}
    };

    for (int i = 1; i + 5 <= n; ++i) {
        int special = 0;
        for (const auto& p : allowedPairs) {
            special = max(special, min(a[i + p[0] - 1], a[i + p[1] - 1]));
        }

        int baseline = secondLargest(a, i, 6);
        answer -= baseline - special;
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

static inline ll absll(ll x) { return x >= 0 ? x : -x; }

// Coefficients for abs(A), abs(B), then adjusted for their signs.
static pair<i128, i128> bezout(ll A, ll B) {
    ll r0 = absll(A), r1 = absll(B);
    i128 x0 = 1, x1 = 0, y0 = 0, y1 = 1;

    while (r1 != 0) {
        ll q = r0 / r1;
        ll nr = r0 % r1;
        r0 = r1;
        r1 = nr;

        i128 nx = x0 - (i128)q * x1;
        i128 ny = y0 - (i128)q * y1;
        x0 = x1; x1 = nx;
        y0 = y1; y1 = ny;
    }

    if (A < 0) x0 = -x0;
    if (B < 0) y0 = -y0;
    return {x0, y0};
}

// b is positive.
static i128 floorDiv(i128 a, i128 b) {
    i128 q = a / b;
    if (a % b < 0) --q;
    return q;
}

// b is positive.
static i128 ceilDiv(i128 a, i128 b) {
    i128 q = a / b;
    if (a % b > 0) ++q;
    return q;
}

static string toString(i128 x) {
    if (x == 0) return "0";
    bool neg = x < 0;
    if (neg) x = -x;
    string s;
    while (x > 0) {
        s.push_back(char('0' + int(x % 10)));
        x /= 10;
    }
    if (neg) s.push_back('-');
    reverse(s.begin(), s.end());
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    while (Q--) {
        ll a, b, c, d;
        cin >> a >> b >> c >> d;

        if (a == c && b == d) {
            cout << "0\n";
            continue;
        }
        if (a == 0 && b == 0) {
            cout << "-1\n";
            continue;
        }

        ll g = std::gcd(absll(a), absll(b));
        if (std::gcd(absll(c), absll(d)) != g) {
            cout << "-1\n";
            continue;
        }

        // Reduce to primitive vectors.
        ll A = a / g, B = b / g;
        ll C = c / g, D = d / g;

        auto [u, v] = bezout(A, B); // u*A + v*B = 1
        auto [z, t] = bezout(C, D); // z*C + t*D = 1

        /*
           Every integer determinant-one matrix taking (A,B) to (C,D)
           has the form

               M_k = Q * L^k * P^(-1),

           where L = [[1,1],[0,1]].  Its entries are affine in k.
           We need exactly those k for which all entries are nonnegative;
           such a matrix, and only such a matrix, is a product of the two
           operation matrices.
        */

        i128 p0 = (i128)C * u + (i128)t * B;
        i128 q0 = (i128)C * v - (i128)t * A;
        i128 r0 = (i128)D * u - (i128)z * B;
        i128 s0 = (i128)D * v + (i128)z * A;

        i128 cp = -(i128)C * B;
        i128 cq =  (i128)C * A;
        i128 cr = -(i128)D * B;
        i128 cs =  (i128)D * A;

        bool ok = true, hasLo = false, hasHi = false;
        i128 lo = 0, hi = 0;

        auto addConstraint = [&](i128 base, i128 coef) {
            if (!ok) return;
            if (coef == 0) {
                if (base < 0) ok = false;
            } else if (coef > 0) {
                i128 bound = ceilDiv(-base, coef);
                if (!hasLo || bound > lo) {
                    lo = bound;
                    hasLo = true;
                }
            } else {
                i128 bound = floorDiv(base, -coef);
                if (!hasHi || bound < hi) {
                    hi = bound;
                    hasHi = true;
                }
            }
        };

        addConstraint(p0, cp);
        addConstraint(q0, cq);
        addConstraint(r0, cr);
        addConstraint(s0, cs);

        if (!ok || (hasLo && hasHi && lo > hi)) {
            cout << "-1\n";
            continue;
        }

        // Factor a nonnegative SL(2,Z) matrix into the two operation
        // matrices, batching consecutive identical factors.
        auto wordLength = [&](i128 k) -> i128 {
            i128 p = p0 + cp * k;
            i128 q = q0 + cq * k;
            i128 r = r0 + cr * k;
            i128 s = s0 + cs * k;

            if (p < 0 || q < 0 || r < 0 || s < 0) return -1;

            i128 ans = 0;
            while (true) {
                if (q == 0) { // R^r
                    ans += r;
                    break;
                }
                if (r == 0) { // L^q
                    ans += q;
                    break;
                }

                i128 n;
                if (p >= r && q >= s) {
                    // The last factors are L: subtract the second row
                    // from the first row.
                    n = std::min(p / r, q / s);
                    if (n <= 0) return -1;
                    p -= n * r;
                    q -= n * s;
                } else {
                    // The last factors are R: subtract the first row
                    // from the second row.
                    n = std::min(r / p, s / q);
                    if (n <= 0) return -1;
                    r -= n * p;
                    s -= n * q;
                }
                ans += n;
            }
            return ans;
        };

        i128 best = -1;
        auto tryK = [&](i128 k) {
            i128 len = wordLength(k);
            if (len >= 0 && (best < 0 || len < best)) best = len;
        };

        // The shortest representation occurs at an endpoint of the
        // feasible interval.  Normally there is only one finite endpoint.
        if (hasLo) tryK(lo);
        if (hasHi && (!hasLo || hi != lo)) tryK(hi);
        if (!hasLo && !hasHi) tryK(0);

        if (best < 0) cout << "-1\n";
        else cout << toString(best) << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = LLONG_MAX;

// a,b > 0 and c,d > 0. All intermediate states must remain positive.
ll positiveCore(ll a, ll b, ll c, ll d) {
    ll answer = 0;

    while (true) {
        if (c < a || d < b) return -1;
        if (a == c && b == d) return answer;
        if (c == d) return -1;

        if (c < d) {
            swap(a, b);
            swap(c, d);
            continue;
        }

        // Now c > d. The last reverse operations are forced to be c -= d.
        if (d == b && (c - a) % d == 0) {
            return answer + (c - a) / d;
        }

        // Reduce c to a value in [1,d], unless this would overshoot a.
        ll steps = (c - 1) / d;
        ll maximumSteps = (c - a) / d;
        if (steps > maximumSteps) return -1;

        c -= steps * d;
        answer += steps;
    }
}

// Nonnegative initial state, with a nonnegative target.
ll nonnegative(ll a, ll b, ll c, ll d) {
    if (c < a || d < b) return -1;
    if (a == c && b == d) return 0;
    if (a == 0 && b == 0) return -1;

    if (a == 0) {
        // To make the first coordinate nonzero, (0,b) -> (b,b) is forced.
        if (c == 0) return -1;
        ll result = positiveCore(b, b, c, d);
        return result < 0 ? -1 : result + 1;
    }

    if (b == 0) {
        if (d == 0) return -1;
        ll result = positiveCore(a, a, c, d);
        return result < 0 ? -1 : result + 1;
    }

    return positiveCore(a, b, c, d);
}

struct FSeg {
    ll x, y;       // Candidates are z = x-k*y, second coordinate z-y.
    ll maxK;
    ll prefix;
    ll minZ, maxZ;
};

struct BSeg {
    ll u, v;       // Candidates are (u-t*v,v).
    ll maxT;
    ll prefix;
    ll minZ, maxZ;
};

// Candidates for crossing from (x,-y), x>y, to the positive pair (x,x-y).
vector<FSeg> buildForwardSegments(ll A, ll B) {
    vector<FSeg> segments;
    segments.reserve(128);

    ll x = A, y = B, prefix = 0;
    while (x != y) {
        if (x > y) {
            ll q = x / y;
            ll r = x % y;
            ll maxK = r ? q - 1 : q - 2;

            if (maxK >= 0) {
                ll minZ = x - maxK * y;
                segments.push_back({x, y, maxK, prefix, minZ, x});
            }

            if (r) {
                prefix += q;
                x = r;
            } else {
                break;
            }
        } else {
            ll q = y / x;
            ll r = y % x;

            if (r) {
                prefix += q;
                y = r;
            } else {
                break;
            }
        }
    }
    return segments;
}

// Positive ancestors of the target which can serve as a crossing state.
vector<BSeg> buildBackwardSegments(ll C, ll D) {
    vector<BSeg> segments;
    segments.reserve(128);

    ll x = C, y = D, prefix = 0;
    while (x != y) {
        if (x > y) {
            ll q = x / y;
            ll r = x % y;
            ll maxT = r ? q - 1 : q - 2;

            if (maxT >= 0) {
                ll minZ = x - maxT * y;
                segments.push_back({x, y, maxT, prefix, minZ, x});
            }

            if (r) {
                prefix += q;
                x = r;
            } else {
                break;
            }
        } else {
            ll q = y / x;
            ll r = y % x;

            if (r) {
                prefix += q;
                y = r;
            } else {
                break;
            }
        }
    }
    return segments;
}

// Reach (g,-g), where g = gcd(A,B), using only sign-preserving operations.
pair<ll, ll> equalStateInfo(ll A, ll B) {
    ll x = A, y = B, distance = 0;

    while (x != y) {
        if (x > y) {
            ll q = x / y;
            ll r = x % y;
            if (r) {
                distance += q;
                x = r;
            } else {
                distance += q - 1;
                x = y;
            }
        } else {
            ll q = y / x;
            ll r = y % x;
            if (r) {
                distance += q;
                y = r;
            } else {
                distance += q - 1;
                y = x;
            }
        }
    }

    return {x, distance};
}

// Target is still in the quadrant (positive,negative).
ll oppositeDistance(ll A, ll B, ll C, ll D) {
    ll x = A, y = B, prefix = 0;

    while (true) {
        if (x == C && y == D) return prefix;
        if (x == y) return -1;

        if (x > y) {
            ll q = x / y;
            ll r = x % y;
            ll steps = r ? q : q - 1;
            ll endX = r ? r : y;

            if (D == y && C <= x && C >= endX && (x - C) % y == 0) {
                ll k = (x - C) / y;
                if (k <= steps) return prefix + k;
            }

            prefix += steps;
            x = endX;
        } else {
            ll q = y / x;
            ll r = y % x;
            ll steps = r ? q : q - 1;
            ll endY = r ? r : x;

            if (C == x && D <= y && D >= endY && (y - D) % x == 0) {
                ll k = (y - D) / x;
                if (k <= steps) return prefix + k;
            }

            prefix += steps;
            y = endY;
        }
    }
}

// Start is (A,-B), A,B>0; target is strictly positive.
ll crossToPositive(ll A, ll B, ll C, ll D) {
    ll best = INF;

    // Route through (g,-g), then (g,0), followed by nonnegative operations.
    auto [g, toEqual] = equalStateInfo(A, B);
    ll viaZero = nonnegative(g, 0, C, D);
    if (viaZero >= 0) {
        best = toEqual + 1 + viaZero;
    }

    vector<FSeg> forward = buildForwardSegments(A, B);
    vector<BSeg> backward = buildBackwardSegments(C, D);

    // Both lists consist of disjoint intervals, ordered by decreasing z.
    size_t i = 0, j = 0;
    while (i < forward.size() && j < backward.size()) {
        const FSeg &f = forward[i];
        const BSeg &b = backward[j];

        if (f.minZ > b.maxZ) {
            ++i;
            continue;
        }
        if (b.minZ > f.maxZ) {
            ++j;
            continue;
        }

        // Equality of second coordinates gives z-y = v, hence z = y+v.
        ll z = f.y + b.v;

        if (z >= f.minZ && z <= f.maxZ &&
            z >= b.minZ && z <= b.maxZ &&
            (f.x - z) % f.y == 0 &&
            (b.u - z) % b.v == 0) {

            ll k = (f.x - z) / f.y;
            ll t = (b.u - z) / b.v;
            ll total = f.prefix + k + 1 + b.prefix + t;
            best = min(best, total);
        }

        if (f.minZ > b.minZ) {
            ++i;
        } else if (f.minZ < b.minZ) {
            ++j;
        } else {
            ++i;
            ++j;
        }
    }

    return best == INF ? -1 : best;
}

ll solveQuery(ll a, ll b, ll c, ll d) {
    if (a == 0 && b == 0) {
        return (c == 0 && d == 0) ? 0 : -1;
    }

    if (a >= 0 && b >= 0) {
        if (c < 0 || d < 0) return -1;
        return nonnegative(a, b, c, d);
    }

    if (a <= 0 && b <= 0) {
        if (c > 0 || d > 0) return -1;
        return nonnegative(-a, -b, -c, -d);
    }

    // Normalize the opposite-sign start to a>0, b<0.
    if (a < 0) {
        swap(a, b);
        swap(c, d);
    }

    ll A = a;
    ll B = -b;

    if (c > 0 && d < 0) {
        return oppositeDistance(A, B, c, -d);
    }

    if (c < 0 && d > 0) {
        return -1;
    }

    if (c > 0 && d > 0) {
        return crossToPositive(A, B, c, d);
    }

    if (c < 0 && d < 0) {
        // Negate everything and swap coordinates.
        return crossToPositive(B, A, -d, -c);
    }

    // A target with a zero coordinate can only be reached immediately after
    // arriving at (g,-g).
    auto [g, toEqual] = equalStateInfo(A, B);
    if ((c == g && d == 0) || (c == 0 && d == -g)) {
        return toEqual + 1;
    }

    return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    while (Q--) {
        ll a, b, c, d;
        cin >> a >> b >> c >> d;
        cout << solveQuery(a, b, c, d) << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct Run {
    int64 x, y;       // First pair in this run
    int64 start;      // Global index of the first pair
    int64 n;          // Number of pairs in the run
    int64 lo, hi;     // Depth interval of these pairs
    bool horizontal;  // x > y
};

struct RunInfo {
    vector<Run> runs;
    int64 depth = 0;
    int64 root = 0;
};

static int64 abs64(int64 x) {
    return x < 0 ? -x : x;
}

// Compressed list of all non-root ancestors of (x,y), including (x,y).
// A run with x>y contains (x-t*y,y); one with y>x contains (x,y-t*x).
static RunInfo buildRuns(int64 x, int64 y) {
    RunInfo info;
    int64 index = 0;

    while (x != y) {
        Run r;
        r.x = x;
        r.y = y;
        r.start = index;
        r.horizontal = (x > y);

        if (x > y) {
            int64 q = x / y;
            r.n = (x % y == 0 ? q - 1 : q);
            x -= r.n * y;
        } else {
            int64 q = y / x;
            r.n = (y % x == 0 ? q - 1 : q);
            y -= r.n * x;
        }

        index += r.n;
        info.runs.push_back(r);
    }

    info.depth = index;
    info.root = x; // x == y == gcd of the original pair

    for (Run &r : info.runs) {
        r.hi = info.depth - r.start;
        r.lo = r.hi - r.n + 1;
    }
    return info;
}

// Number of parent steps from the pair used to build info to anc,
// or -1 if anc is not an ancestor.
static int64 ancestorDist(const RunInfo &info, pair<int64,int64> anc) {
    for (const Run &r : info.runs) {
        if (r.horizontal) {
            if (anc.second == r.y && anc.first > r.y && anc.first <= r.x) {
                int64 diff = r.x - anc.first;
                if (diff % r.y == 0) {
                    int64 t = diff / r.y;
                    if (t < r.n) return r.start + t;
                }
            }
        } else {
            if (anc.first == r.x && anc.second > r.x && anc.second <= r.y) {
                int64 diff = r.y - anc.second;
                if (diff % r.x == 0) {
                    int64 t = diff / r.x;
                    if (t < r.n) return r.start + t;
                }
            }
        }
    }

    if (anc.first == info.root && anc.second == info.root)
        return info.depth;
    return -1;
}

static int64 solveQuery(int64 a, int64 b, int64 c, int64 d) {
    // Zero initial states: one useful operation reaches (s,s), after which
    // the ordinary same-sign process applies.
    if (a == 0 || b == 0) {
        if (a == 0 && b == 0)
            return (c == 0 && d == 0) ? 0 : -1;

        if (a == c && b == d) return 0;

        int64 s = (b == 0 ? a : b);
        bool correctSign = (s > 0 && c > 0 && d > 0) ||
                           (s < 0 && c < 0 && d < 0);
        if (!correctSign) return -1;

        int64 x = abs64(c), y = abs64(d);
        if (std::gcd(x, y) != abs64(s)) return -1;

        RunInfo target = buildRuns(x, y);
        return target.depth + 1;
    }

    // Both initial components have the same sign.
    if ((a > 0 && b > 0) || (a < 0 && b < 0)) {
        bool correctSign = (a > 0 && c > 0 && d > 0) ||
                           (a < 0 && c < 0 && d < 0);
        if (!correctSign) return -1;

        pair<int64,int64> start = {abs64(a), abs64(b)};
        pair<int64,int64> target = {abs64(c), abs64(d)};
        RunInfo info = buildRuns(target.first, target.second);
        return ancestorDist(info, start);
    }

    // Canonicalize an opposite-sign start to a>0>b. Swapping both pairs
    // preserves operation counts.
    if (a < 0) {
        swap(a, b);
        swap(c, d);
    }

    int64 x = a, y = -b;
    RunInfo startInfo = buildRuns(x, y);
    int64 g = startInfo.root;

    // Zero targets are reachable only through (g,-g).
    if (c == 0 || d == 0) {
        if ((c == 0 && d == -g) || (c == g && d == 0))
            return startInfo.depth + 1;
        return -1;
    }

    // Still opposite signs: only the deterministic non-crossing chain applies.
    if (c > 0 && d < 0) {
        return ancestorDist(startInfo, {c, -d});
    }
    if (c < 0 && d > 0) return -1;

    // The target has equal signs. Normalize to positive absolute values.
    bool positiveTarget = (c > 0);
    int64 tx = abs64(c), ty = abs64(d);
    if (std::gcd(tx, ty) != g) return -1;

    RunInfo targetInfo = buildRuns(tx, ty);

    // Fallback: go to (g,-g), then through a zero state to (g,g) or (-g,-g),
    // and finally follow the same-sign path to the target.
    i128 best = (i128)startInfo.depth + targetInfo.depth + 2;

    // A crossing at a non-root ancestor (x,y), x>y, produces the positive
    // base (x,x-y). At x<y it produces the negative base with absolute
    // values (y-x,y). Match all such bases against ancestors of the target.
    const auto &S = startInfo.runs;
    const auto &T = targetInfo.runs;
    size_t i = 0, j = 0;

    while (i < S.size() && j < T.size()) {
        const Run &s = S[i];
        const Run &t = T[j];

        bool overlap = !(s.hi < t.lo || t.hi < s.lo);

        if (!overlap) {
            if (s.lo > t.hi) ++i;
            else ++j;
            continue;
        }

        // Positive bases come from horizontal runs, negative ones from
        // vertical runs. Equal pairs must also have the same orientation.
        if (s.horizontal == positiveTarget && s.horizontal == t.horizontal) {
            if (s.horizontal) {
                // Base: (s.x-k*s.y, s.x-(k+1)*s.y)
                // Target run: (t.x-l*t.y, t.y)
                int64 diff = s.x - t.y;
                if (diff > 0 && diff % s.y == 0) {
                    int64 h = diff / s.y; // h = k+1
                    if (h >= 1 && h <= s.n) {
                        int64 k = h - 1;
                        int64 baseX = s.x - k * s.y;
                        int64 diff2 = t.x - baseX;
                        if (diff2 >= 0 && diff2 % t.y == 0) {
                            int64 l = diff2 / t.y;
                            if (l < t.n) {
                                i128 cost = (i128)s.start + k + 1 + t.start + l;
                                if (cost < best) best = cost;
                            }
                        }
                    }
                }
            } else {
                // Base: (s.y-(k+1)*s.x, s.y-k*s.x)
                // Target run: (t.x, t.y-l*t.x)
                int64 diff = s.y - t.x;
                if (diff > 0 && diff % s.x == 0) {
                    int64 h = diff / s.x; // h = k+1
                    if (h >= 1 && h <= s.n) {
                        int64 k = h - 1;
                        int64 baseY = s.y - k * s.x;
                        int64 diff2 = t.y - baseY;
                        if (diff2 >= 0 && diff2 % t.x == 0) {
                            int64 l = diff2 / t.x;
                            if (l < t.n) {
                                i128 cost = (i128)s.start + k + 1 + t.start + l;
                                if (cost < best) best = cost;
                            }
                        }
                    }
                }
            }
        }

        // Enumerate only pairs of runs whose depth intervals overlap.
        if (s.lo > t.lo) ++i;
        else if (t.lo > s.lo) ++j;
        else {
            ++i;
            ++j;
        }
    }

    return (int64)best;
}

