    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;
    while (Q--) {
        int64 a, b, c, d;
        cin >> a >> b >> c >> d;
        cout << solveQuery(a, b, c, d) << '\n';
    }
