}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

const int64 INF = numeric_limits<int64>::max();

// A segment represents consecutive states of a subtractive Euclidean chain.
// dir = 0: (x - t*y, y), 0 <= t <= m
// dir = 1: (x, y - t*x), 0 <= t <= m
// dir = -1: terminal state (g,g)
struct Segment {
    int64 x, y, m, k;
    int dir;
    int64 hi, lo; // Range of coordinate sums in this segment.
};

struct Chain {
    vector<Segment> seg;
    int64 g;
    int64 steps;
};

Chain buildChain(int64 x, int64 y) {
    Chain ch;
    ch.seg.reserve(128);
    int64 k = 0;

    while (x != y) {
        Segment s;
        s.x = x;
        s.y = y;
        s.k = k;
        s.hi = x + y;

        int64 nx = x, ny = y;
        if (x > y) {
            s.dir = 0;
            s.m = (x - 1) / y;
            nx = x - s.m * y;
            s.lo = nx + y;
        } else {
            s.dir = 1;
            s.m = (y - 1) / x;
            ny = y - s.m * x;
            s.lo = x + ny;
        }

        ch.seg.push_back(s);
        x = nx;
        y = ny;
        k += s.m;
    }

    Segment terminal{x, y, 0, k, -1, x + y, x + y};
    ch.seg.push_back(terminal);
    ch.g = x;
    ch.steps = k;
    return ch;
}

// Returns the number of reverse operations at which (x,y) occurs,
// or -1 if it does not occur in the chain.
int64 findInChain(const Chain& ch, int64 x, int64 y) {
    for (const Segment& s : ch.seg) {
        if (s.dir == -1) {
            if (x == s.x && y == s.y) return s.k;
            continue;
        }

        if (s.dir == 0) {
            if (y != s.y || x > s.x) continue;
            int64 diff = s.x - x;
            if (diff % s.y != 0) continue;
            int64 t = diff / s.y;
            if (t <= s.m) return s.k + t;
        } else {
            if (x != s.x || y > s.y) continue;
            int64 diff = s.y - y;
            if (diff % s.x != 0) continue;
            int64 t = diff / s.x;
            if (t <= s.m) return s.k + t;
        }
    }
    return -1;
}

// Both initial coordinates are nonnegative.
int64 solveNonnegative(int64 a, int64 b, int64 c, int64 d) {
    if (a == c && b == d) return 0;
    if (a == 0 && b == 0) return -1;

    if (a == 0) {
        if (c == 0 || d == 0) return -1;
        Chain target = buildChain(b, b);
        int64 suffix = findInChain(target, c, d);
        return suffix < 0 ? -1 : suffix + 1;
    }

    if (b == 0) {
        if (c == 0 || d == 0) return -1;
        Chain target = buildChain(a, a);
        int64 suffix = findInChain(target, c, d);
        return suffix < 0 ? -1 : suffix + 1;
    }

    if (c <= 0 || d <= 0) return -1;
    Chain target = buildChain(c, d);
    return findInChain(target, a, b);
}

// A candidate segment corresponds to possible exits from the mixed-sign
// prefix. Its states are obtained from states of the target's positive chain.
struct Candidate {
    int64 x, y, m, k;
    int64 hi, lo; // Range of sums of the associated mixed-chain state.
};

// Try to intersect one mixed-prefix segment and one candidate segment.
bool intersectSegments(const Segment& s, const Candidate& c,
                       int mode, int64& answer) {
    i128 t = 0;
    bool ok = true;

    if (s.dir == 0) {
        // The second coordinate of the mixed-chain state is fixed.
        if (mode == 0) {
            // p2 = c.x - (t+1)*c.y = s.y
            i128 num = (i128)c.x - s.y;
            if (num < 0 || num % c.y != 0) ok = false;
            else t = num / c.y - 1;
        } else {
            // p2 = c.y - t*c.x = s.y
            i128 num = (i128)c.y - s.y;
            if (num < 0 || num % c.x != 0) ok = false;
            else t = num / c.x;
        }
    } else if (s.dir == 1) {
        // The first coordinate of the mixed-chain state is fixed.
        if (mode == 0) {
            // p1 = c.x - t*c.y = s.x
            i128 num = (i128)c.x - s.x;
            if (num < 0 || num % c.y != 0) ok = false;
            else t = num / c.y;
        } else {
            // p1 = c.y - (t+1)*c.x = s.x
            i128 num = (i128)c.y - s.x;
            if (num < 0 || num % c.x != 0) ok = false;
            else t = num / c.x - 1;
        }
    } else {
        ok = false;
    }

    if (!ok || t < 0 || t >= c.m) return false;
    int64 tt = (int64)t;

    i128 p1, p2;
    if (mode == 0) {
        p1 = (i128)c.x - (i128)tt * c.y;
        p2 = (i128)c.x - (i128)(tt + 1) * c.y;
    } else {
        p1 = (i128)c.y - (i128)(tt + 1) * c.x;
        p2 = (i128)c.y - (i128)tt * c.x;
    }

    i128 prefixOffset;
    if (s.dir == 0) {
        if (p2 != s.y || p1 > s.x) return false;
        i128 diff = (i128)s.x - p1;
        if (diff < 0 || diff % s.y != 0) return false;
        prefixOffset = diff / s.y;
    } else {
        if (p1 != s.x || p2 > s.y) return false;
        i128 diff = (i128)s.y - p2;
        if (diff < 0 || diff % s.x != 0) return false;
        prefixOffset = diff / s.x;
    }

    if (prefixOffset < 0 || prefixOffset > s.m) return false;

    i128 cost = (i128)s.k + prefixOffset + 1 + c.k + tt;
    answer = (int64)cost;
    return true;
}

// mode 0: positive target, exit state (X,Y) has X>Y.
// mode 1: negative target (use its negation), exit state has X<Y.
int64 solveSignedTarget(const Chain& mixed, const Chain& target, int mode) {
    vector<Candidate> candidates;
    candidates.reserve(64);

    for (const Segment& s : target.seg) {
        if ((mode == 0 && s.dir == 0) || (mode == 1 && s.dir == 1)) {
            if (s.m == 0) continue;

            Candidate c;
            c.x = s.x;
            c.y = s.y;
            c.m = s.m; // Candidates are t=0,...,m-1.
            c.k = s.k;

            i128 hi, lo;
            if (mode == 0) {
                hi = (i128)2 * s.x - s.y;
                lo = hi - (i128)2 * (s.m - 1) * s.y;
            } else {
                hi = (i128)2 * s.y - s.x;
                lo = hi - (i128)2 * (s.m - 1) * s.x;
            }
            c.hi = (int64)hi;
            c.lo = (int64)lo;
            candidates.push_back(c);
        }
    }

    int64 best = INF;
    size_t i = 0, j = 0;

    // Coordinate sums decrease along both sequences. Merge their intervals;
    // the first intersection also minimizes prefix length + suffix length.
    while (i < mixed.seg.size() && j < candidates.size()) {
        const Segment& s = mixed.seg[i];
        if (s.dir == -1) break;
        const Candidate& c = candidates[j];

        if (c.lo > s.hi) {
            ++j;
            continue;
        }
        if (s.lo > c.hi) {
            ++i;
            continue;
        }

        int64 cost;
        if (intersectSegments(s, c, mode, cost)) {
            best = cost;
            break;
        }

        if (s.lo > c.lo) ++i;
        else if (c.lo > s.lo) ++j;
        else {
            ++i;
            ++j;
        }
    }

    // At the terminal mixed state (g,-g), one can instead pass through an
    // axis state and start the monotone suffix from (g,g), or from (-g,-g).
    if (mixed.g == target.g) {
        i128 special = (i128)mixed.steps + 2 + target.steps;
        best = min(best, (int64)special);
    }

    return best == INF ? -1 : best;
}

int64 solveMixed(int64 a, int64 b, int64 c, int64 d) {
    // Canonicalize to a > 0 > b. Swapping coordinates preserves the answer.
    if (a < 0) {
        swap(a, b);
        swap(c, d);
    }

    Chain mixed = buildChain(a, -b);

    if (c > 0 && d < 0) {
        // The target lies on the deterministic mixed-sign prefix itself.
        return findInChain(mixed, c, -d);
    }

    if (c < 0 && d > 0) return -1;

    if (c > 0 && d > 0) {
        Chain target = buildChain(c, d);
        return solveSignedTarget(mixed, target, 0);
    }

    if (c < 0 && d < 0) {
        Chain target = buildChain(-c, -d);
        return solveSignedTarget(mixed, target, 1);
    }

    // A zero coordinate can first appear only from the terminal state (g,-g).
    if (c == 0 && d < 0 && d == -mixed.g) return mixed.steps + 1;
    if (d == 0 && c > 0 && c == mixed.g) return mixed.steps + 1;
    return -1;
}

int64 solveQuery(int64 a, int64 b, int64 c, int64 d) {
    if (a >= 0 && b >= 0) {
        if (c < 0 || d < 0) return -1;
        return solveNonnegative(a, b, c, d);
    }

    if (a <= 0 && b <= 0) {
        if (c > 0 || d > 0) return -1;
        return solveNonnegative(-a, -b, -c, -d);
    }

    return solveMixed(a, b, c, d);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;
    while (Q--) {
        int64 a, b, c, d;
        cin >> a >> b >> c >> d;
        cout << solveQuery(a, b, c, d) << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = LLONG_MAX;

// a,b > 0 and c,d > 0. All intermediate states must remain positive.
ll positiveCore(ll a, ll b, ll c, ll d) {
    ll answer = 0;

    while (true) {
        if (c < a || d < b) return -1;
        if (a == c && b == d) return answer;
        if (c == d) return -1;

        if (c < d) {
            swap(a, b);
            swap(c, d);
            continue;
        }

        // Now c > d. The last reverse operations are forced to be c -= d.
        if (d == b && (c - a) % d == 0) {
            return answer + (c - a) / d;
        }

        // Reduce c to a value in [1,d], unless this would overshoot a.
        ll steps = (c - 1) / d;
        ll maximumSteps = (c - a) / d;
        if (steps > maximumSteps) return -1;

        c -= steps * d;
        answer += steps;
    }
}

// Nonnegative initial state, with a nonnegative target.
ll nonnegative(ll a, ll b, ll c, ll d) {
    if (c < a || d < b) return -1;
    if (a == c && b == d) return 0;
    if (a == 0 && b == 0) return -1;

    if (a == 0) {
        // To make the first coordinate nonzero, (0,b) -> (b,b) is forced.
        if (c == 0) return -1;
        ll result = positiveCore(b, b, c, d);
        return result < 0 ? -1 : result + 1;
    }

    if (b == 0) {
        if (d == 0) return -1;
        ll result = positiveCore(a, a, c, d);
        return result < 0 ? -1 : result + 1;
    }

    return positiveCore(a, b, c, d);
}

struct FSeg {
    ll x, y;       // Candidates are z = x-k*y, second coordinate z-y.
    ll maxK;
    ll prefix;
    ll minZ, maxZ;
};

struct BSeg {
    ll u, v;       // Candidates are (u-t*v,v).
    ll maxT;
    ll prefix;
    ll minZ, maxZ;
};

// Candidates for crossing from (x,-y), x>y, to the positive pair (x,x-y).
vector<FSeg> buildForwardSegments(ll A, ll B) {
    vector<FSeg> segments;
    segments.reserve(128);

    ll x = A, y = B, prefix = 0;
    while (x != y) {
        if (x > y) {
            ll q = x / y;
            ll r = x % y;
            ll maxK = r ? q - 1 : q - 2;

            if (maxK >= 0) {
                ll minZ = x - maxK * y;
                segments.push_back({x, y, maxK, prefix, minZ, x});
            }

            if (r) {
                prefix += q;
                x = r;
            } else {
                break;
            }
        } else {
            ll q = y / x;
            ll r = y % x;

            if (r) {
                prefix += q;
                y = r;
            } else {
                break;
            }
        }
    }
    return segments;
}

// Positive ancestors of the target which can serve as a crossing state.
vector<BSeg> buildBackwardSegments(ll C, ll D) {
    vector<BSeg> segments;
    segments.reserve(128);

    ll x = C, y = D, prefix = 0;
    while (x != y) {
        if (x > y) {
            ll q = x / y;
            ll r = x % y;
            ll maxT = r ? q - 1 : q - 2;

            if (maxT >= 0) {
                ll minZ = x - maxT * y;
                segments.push_back({x, y, maxT, prefix, minZ, x});
            }

            if (r) {
                prefix += q;
                x = r;
            } else {
                break;
            }
        } else {
            ll q = y / x;
            ll r = y % x;

            if (r) {
                prefix += q;
                y = r;
            } else {
                break;
            }
        }
    }
    return segments;
}

// Reach (g,-g), where g = gcd(A,B), using only sign-preserving operations.
pair<ll, ll> equalStateInfo(ll A, ll B) {
    ll x = A, y = B, distance = 0;

    while (x != y) {
        if (x > y) {
            ll q = x / y;
            ll r = x % y;
            if (r) {
                distance += q;
                x = r;
            } else {
                distance += q - 1;
                x = y;
            }
        } else {
            ll q = y / x;
            ll r = y % x;
            if (r) {
                distance += q;
                y = r;
            } else {
                distance += q - 1;
                y = x;
            }
        }
    }

    return {x, distance};
}

// Target is still in the quadrant (positive,negative).
ll oppositeDistance(ll A, ll B, ll C, ll D) {
    ll x = A, y = B, prefix = 0;

    while (true) {
        if (x == C && y == D) return prefix;
        if (x == y) return -1;

        if (x > y) {
            ll q = x / y;
            ll r = x % y;
            ll steps = r ? q : q - 1;
            ll endX = r ? r : y;

            if (D == y && C <= x && C >= endX && (x - C) % y == 0) {
                ll k = (x - C) / y;
                if (k <= steps) return prefix + k;
            }

            prefix += steps;
            x = endX;
        } else {
            ll q = y / x;
            ll r = y % x;
            ll steps = r ? q : q - 1;
            ll endY = r ? r : x;

            if (C == x && D <= y && D >= endY && (y - D) % x == 0) {
                ll k = (y - D) / x;
                if (k <= steps) return prefix + k;
            }

            prefix += steps;
            y = endY;
        }
    }
}

// Start is (A,-B), A,B>0; target is strictly positive.
ll crossToPositive(ll A, ll B, ll C, ll D) {
    ll best = INF;

    // Route through (g,-g), then (g,0), followed by nonnegative operations.
    auto [g, toEqual] = equalStateInfo(A, B);
    ll viaZero = nonnegative(g, 0, C, D);
    if (viaZero >= 0) {
        best = toEqual + 1 + viaZero;
    }

    vector<FSeg> forward = buildForwardSegments(A, B);
    vector<BSeg> backward = buildBackwardSegments(C, D);

    // Both lists consist of disjoint intervals, ordered by decreasing z.
    size_t i = 0, j = 0;
    while (i < forward.size() && j < backward.size()) {
        const FSeg &f = forward[i];
        const BSeg &b = backward[j];

        if (f.minZ > b.maxZ) {
            ++i;
            continue;
        }
        if (b.minZ > f.maxZ) {
            ++j;
            continue;
        }

        // Equality of second coordinates gives z-y = v, hence z = y+v.
        ll z = f.y + b.v;

        if (z >= f.minZ && z <= f.maxZ &&
            z >= b.minZ && z <= b.maxZ &&
            (f.x - z) % f.y == 0 &&
            (b.u - z) % b.v == 0) {

            ll k = (f.x - z) / f.y;
            ll t = (b.u - z) / b.v;
            ll total = f.prefix + k + 1 + b.prefix + t;
            best = min(best, total);
        }

        if (f.minZ > b.minZ) {
            ++i;
        } else if (f.minZ < b.minZ) {
            ++j;
        } else {
            ++i;
            ++j;
        }
    }

    return best == INF ? -1 : best;
}

ll solveQuery(ll a, ll b, ll c, ll d) {
    if (a == 0 && b == 0) {
        return (c == 0 && d == 0) ? 0 : -1;
    }

    if (a >= 0 && b >= 0) {
        if (c < 0 || d < 0) return -1;
        return nonnegative(a, b, c, d);
    }

    if (a <= 0 && b <= 0) {
        if (c > 0 || d > 0) return -1;
        return nonnegative(-a, -b, -c, -d);
    }

    // Normalize the opposite-sign start to a>0, b<0.
    if (a < 0) {
        swap(a, b);
        swap(c, d);
    }

    ll A = a;
    ll B = -b;

    if (c > 0 && d < 0) {
        return oppositeDistance(A, B, c, -d);
    }

    if (c < 0 && d > 0) {
        return -1;
    }

    if (c > 0 && d > 0) {
        return crossToPositive(A, B, c, d);
    }

    if (c < 0 && d < 0) {
        // Negate everything and swap coordinates.
        return crossToPositive(B, A, -d, -c);
    }

    // A target with a zero coordinate can only be reached immediately after
    // arriving at (g,-g).
    auto [g, toEqual] = equalStateInfo(A, B);
    if ((c == g && d == 0) || (c == 0 && d == -g)) {
        return toEqual + 1;
    }

    return -1;
}

