    inv[1] = 1;
    for (int i = 2; i <= N; ++i) {
        inv[i] = (int)(MOD - (long long)(MOD / i) * inv[MOD % i] % MOD);
    }

    auto G = [&](int L, long long M, long long U) -> int {
        if (U < M) return 0;

        long long D = U - M;
        int limit = (int)min<long long>(L, D);

        long long res = 0;
        long long combD = 1;
        long long combL = 1;

        for (int j = 0; j <= limit; ++j) {
            long long term = combD * combL % MOD * pow2[L - j] % MOD;
            res += term;
            if (res >= MOD) res -= MOD;

            if (j == limit) break;

            combD = combD * ((D - j) % MOD) % MOD * inv[j + 1] % MOD;
            combL = combL * (long long)(L - j) % MOD * inv[j + 1] % MOD;
        }

        return (int)res;
    };

