    int N, Q;
    cin >> N >> Q;

    vector<int> c(Q), v(Q);
    for (int i = 0; i < Q; i++) {
        cin >> c[i] >> v[i];
    }

    vector<int> pow2(N + 1), inv(N + 1), coef(N + 1);

    pow2[0] = 1;
    for (int i = 1; i <= N; i++) {
        pow2[i] = (int)(2LL * pow2[i - 1] % MOD);
    }

    inv[1] = 1;
    for (int i = 2; i <= N; i++) {
        inv[i] = MOD - (long long)(MOD / i) * inv[MOD % i] % MOD;
    }

    const int INV2 = (MOD + 1) / 2;
    for (int i = 1; i <= N; i++) {
        coef[i] = (long long)inv[i] * inv[i] % MOD * INV2 % MOD;
    }

    auto G = [&](int L, int m, int C) -> int {
        if (C < m) return 0;

        long long d = (long long)C - m;
        int K = (int)min((long long)L, d);

        long long term = pow2[L];
        long long sum = term;

        for (int k = 1; k <= K; k++) {
            term = term * (L - k + 1) % MOD;
            term = term * ((d - k + 1) % MOD) % MOD;
            term = term * coef[k] % MOD;

            sum += term;
            if (sum >= MOD) sum -= MOD;
        }

        return (int)sum;
    };

    int x = v[0];

    long long dp0 = 1; // current maximum = x
    long long dp1 = 0; // current maximum = x + 1

    for (int i = 1; i < Q; i++) {
        int y = v[i];
        int L = c[i] - c[i - 1] - 1;

        long long ndp0 = 0;
        long long ndp1 = 0;

