            if (ways == 0) return;

            int g0 = G(L, m, y);
            int g1 = G(L, m, y + 1);

            int t0 = g0;
            int t1 = (g1 - g0 + MOD) % MOD;

            ndp0 += ways * t0 % MOD;
            ndp1 += ways * t1 % MOD;
            ndp0 %= MOD;
            ndp1 %= MOD;
        };

        processState(dp0, x);
        processState(dp1, x + 1);

