using namespace std;

using ll = long long;
using i128 = __int128_t;

struct Vec {
    ll x, y;
};

static inline i128 cross(const Vec &a, const Vec &b) {
    return (i128)a.x * b.y - (i128)a.y * b.x;
}

static inline i128 dot(const Vec &a, const Vec &b) {
    return (i128)a.x * b.x + (i128)a.y * b.y;
}

static inline int half(const Vec &a) {
    return (a.y > 0 || (a.y == 0 && a.x > 0)) ? 0 : 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int N;
        cin >> N;

        vector<Vec> v;
        v.reserve(N);

        for (int i = 0; i < N; i++) {
            ll h, p, s;
            cin >> h >> p >> s;
            Vec a{p - s, h - s};
            if (a.x != 0 || a.y != 0) v.push_back(a);
        }

        int n = (int)v.size();
        if (n < 3) {
            cout << 0 << '\n';
            continue;
        }

        sort(v.begin(), v.end(), [](const Vec &a, const Vec &b) {
            if (half(a) != half(b)) return half(a) < half(b);
            return cross(a, b) > 0;
        });

        vector<Vec> doubled(2 * n);
        for (int i = 0; i < 2 * n; i++) doubled[i] = v[i % n];

        // q[i]: first direction at least pi radians after v[i].
        // r[i]: first direction strictly more than pi radians after v[i].
        vector<int> q(n), r(n);
        int ptr = 1;

        for (int i = 0; i < n; i++) {
            ptr = max(ptr, i + 1);
            int lim = i + n;

            while (ptr < lim) {
                i128 cr = cross(v[i], doubled[ptr]);
                if (cr > 0 || (cr == 0 && dot(v[i], doubled[ptr]) > 0)) {
                    ptr++;
                } else {
                    break;
                }
            }

            q[i] = ptr;
            int z = ptr;
            while (z < lim && cross(v[i], doubled[z]) == 0) z++;
            r[i] = z;
        }

        vector<int> sameEnd(n);
        for (int l = 0; l < n; ) {
            int rr = l + 1;
            while (rr < n && cross(v[l], v[rr]) == 0) rr++;
            for (int i = l; i < rr; i++) sameEnd[i] = rr;
            l = rr;
        }

        vector<int> R(n);
        vector<ll> pref(n + 1, 0);
        for (int i = 0; i < n; i++) {
            R[i] = min(q[i], n);
            pref[i + 1] = pref[i] + R[i];
        }

        ll answer = 0;

        for (int i = 0; i < n; i++) {
            int L = min(r[i], n);
            if (L >= n) continue;

            int lo = sameEnd[i];
            int hi = min(q[i], n);
            if (lo >= hi) continue;

            int start = lower_bound(R.begin() + lo, R.begin() + hi, L + 1)
                        - R.begin();

            if (start < hi) {
                answer += pref[hi] - pref[start]
                          - (ll)(hi - start) * L;
            }
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Point {
    ll x, y;
};

static inline ll cross(const Point& a, const Point& b) {
    return a.x * b.y - a.y * b.x;
}

static inline ll dot(const Point& a, const Point& b) {
    return a.x * b.x + a.y * b.y;
}

static inline int halfPlane(const Point& p) {
    return (p.y > 0 || (p.y == 0 && p.x >= 0)) ? 0 : 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<Point> points;
        points.reserve(N);
        map<pair<ll, ll>, ll> rayCount;

        for (int i = 0; i < N; i++) {
            ll h, p, s;
            cin >> h >> p >> s;

            Point v{h - s, p - s};
            if (v.x == 0 && v.y == 0) continue;

            points.push_back(v);

            ll g = std::gcd(v.x < 0 ? -v.x : v.x,
                            v.y < 0 ? -v.y : v.y);
            rayCount[{v.x / g, v.y / g}]++;
        }

        int M = (int)points.size();
        if (M < 3) {
            cout << 0 << '\n';
            continue;
        }

        sort(points.begin(), points.end(), [](const Point& a, const Point& b) {
            int ha = halfPlane(a), hb = halfPlane(b);
            if (ha != hb) return ha < hb;
            return cross(a, b) > 0;
        });

        ll total = (ll)M * (M - 1) * (M - 2) / 6;

        // Count triples having a circular gap strictly greater than 180 degrees.
        ll bad = 0;
        int r = 0;

        for (int i = 0; i < M; i++) {
            if (r < i + 1) r = i + 1;

            while (r < i + M) {
                const Point& a = points[i];
                const Point& b = points[r % M];

                ll cr = cross(a, b);
                bool inside;

                if (cr > 0) {
                    inside = true; // Angular difference is in (0, 180).
                } else if (cr == 0 && dot(a, b) > 0 && r < M) {
                    inside = true; // Same direction, angular difference 0.
                } else {
                    inside = false;
                }

                if (!inside) break;
                r++;
            }

            ll c = r - i - 1;
            bad += c * (c - 1) / 2;
        }

        // Count triples containing an antipodal pair; these have a gap of
        // exactly 180 degrees and were not counted above.
        __int128 antipodal = 0;

        for (const auto& entry : rayCount) {
            auto key = entry.first;
            pair<ll, ll> opposite{-key.first, -key.second};

            if (!(key < opposite)) continue;

            auto it = rayCount.find(opposite);
            if (it == rayCount.end()) continue;

            ll a = entry.second;
            ll b = it->second;
            ll outside = M - a - b;

            antipodal += (__int128)a * b * outside;
            antipodal += (__int128)a * b * (a + b - 2) / 2;
        }

        ll answer = total - bad - (ll)antipodal;
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct Vec {
    int64 x, y;
};

static inline i128 cross(const Vec& a, const Vec& b) {
    return (i128)a.x * b.y - (i128)a.y * b.x;
}

static inline int halfPlane(const Vec& a) {
    return (a.y > 0 || (a.y == 0 && a.x > 0)) ? 0 : 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<Vec> base;
        base.reserve(N);

        for (int i = 0; i < N; ++i) {
            int64 h, p, s;
            cin >> h >> p >> s;

            // The pairwise comparison sign is the sign of the cross product
            // of (h-s, p-s), up to a fixed reversal. Uniform strategies map
            // to the zero vector and cannot belong to a cycle.
            Vec v{h - s, p - s};
            if (v.x != 0 || v.y != 0) base.push_back(v);
        }

        int m = (int)base.size();
        if (m < 3) {
            cout << 0 << '\n';
            continue;
        }

        sort(base.begin(), base.end(), [](const Vec& a, const Vec& b) {
            int ha = halfPlane(a), hb = halfPlane(b);
            if (ha != hb) return ha < hb;
            return cross(a, b) > 0;
        });

        vector<Vec> a = base;
        a.insert(a.end(), base.begin(), base.end());
        int sz = 2 * m;

        // One past the end of the run of vectors having the same direction.
        vector<int> runEnd(sz);
        runEnd[sz - 1] = sz;
        for (int i = sz - 2; i >= 0; --i) {
            if (cross(a[i], a[i + 1]) == 0)
                runEnd[i] = runEnd[i + 1];
            else
                runEnd[i] = i + 1;
        }

        // up[j]: first direction at least pi radians after direction j.
        vector<int> up(sz);
        int k = 0;
        for (int j = 0; j < sz; ++j) {
            k = max(k, runEnd[j]);
            while (k < sz && cross(a[j], a[k]) > 0) ++k;
            up[j] = k;
        }

        vector<int64> pref(sz + 1, 0);
        for (int i = 0; i < sz; ++i) pref[i + 1] = pref[i] + up[i];

        int64 counted = 0;

        for (int i = 0; i < m; ++i) {
            int lo = runEnd[i]; // Skip directions equal to direction i.
            int hi = up[i];     // Directions strictly between 0 and pi after i.
            if (lo >= hi) continue;

            // First direction strictly more than pi after direction i.
            int left = up[i];
            if (left < sz && cross(a[i], a[left]) == 0)
                left = runEnd[left];

            // For each j in [lo,hi), valid k form [left, up[j]).
            // up[j] is nondecreasing, so sum all positive interval lengths.
            int first = upper_bound(up.begin() + lo, up.begin() + hi, left)
                        - up.begin();
            int64 cnt = hi - first;
            if (cnt > 0) {
                counted += (pref[hi] - pref[first]) - (int64)left * cnt;
            }
        }

        // Every cyclic triple was counted once from each of its three cows.
        cout << counted / 3 << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Vec {
    long long x, y;
};

static inline __int128 cross(const Vec& a, const Vec& b) {
    return (__int128)a.x * b.y - (__int128)a.y * b.x;
}

static inline __int128 dot(const Vec& a, const Vec& b) {
    return (__int128)a.x * b.x + (__int128)a.y * b.y;
}

static inline int half(const Vec& v) {
    return (v.y > 0 || (v.y == 0 && v.x >= 0)) ? 0 : 1;
}

bool cmpAngle(const Vec& a, const Vec& b) {
    int ha = half(a), hb = half(b);
    if (ha != hb) return ha < hb;

    __int128 c = cross(a, b);
    if (c != 0) return c > 0;

    __int128 la = (__int128)a.x * a.x + (__int128)a.y * a.y;
    __int128 lb = (__int128)b.x * b.x + (__int128)b.y * b.y;
    return la < lb;
}

void printInt128(__int128 x) {
    if (x == 0) {
        cout << 0 << '\n';
        return;
    }

    if (x < 0) {
        cout << '-';
        x = -x;
    }

    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 10));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<Vec> pts;
        pts.reserve(N);

        for (int i = 0; i < N; ++i) {
            long long h, p, s;
            cin >> h >> p >> s;

            // Direction relative to the uniform distribution (1/3, 1/3, 1/3)
            long long x = 2 * h - p - s;
            long long y = 2 * p - h - s;

            if (x == 0 && y == 0) continue; // uniform strategy ties with everyone

            pts.push_back({x, y});
        }

        if (pts.size() < 3) {
            cout << 0 << '\n';
            continue;
        }

        sort(pts.begin(), pts.end(), cmpAngle);

        vector<Vec> dirs;
        vector<long long> w;

        dirs.reserve(pts.size());
        w.reserve(pts.size());

        for (const Vec& v : pts) {
            if (!dirs.empty() && cross(dirs.back(), v) == 0 && dot(dirs.back(), v) > 0) {
                ++w.back();
            } else {
                dirs.push_back(v);
                w.push_back(1);
            }
        }

        int M = (int)dirs.size();

        if (M < 3) {
            cout << 0 << '\n';
            continue;
        }

        // e3 = sum over triples of distinct directions w[i] * w[j] * w[k]
        __int128 e1 = 0, e2 = 0, e3 = 0;
        for (long long wi : w) {
            e3 += e2 * wi;
            e2 += e1 * wi;
            e1 += wi;
        }

        vector<long long> pref(2 * M + 1, 0), pref2(2 * M + 1, 0);

        for (int i = 0; i < 2 * M; ++i) {
            long long wi = w[i % M];
            pref[i + 1] = pref[i] + wi;
            pref2[i + 1] = pref2[i] + wi * wi;
        }

        __int128 invalid = 0;
        int r = 0;

        for (int i = 0; i < M; ++i) {
            if (r < i) r = i;

            while (r + 1 < i + M) {
                Vec a = dirs[i];
                Vec b = dirs[(r + 1) % M];

                if (cross(a, b) >= 0) {
                    ++r;
                } else {
                    break;
                }
            }

            int L = i + 1;
            int R = r;

            if (L <= R) {
                long long sumW = pref[R + 1] - pref[L];
                long long sumW2 = pref2[R + 1] - pref2[L];

                __int128 pairs = ((__int128)sumW * sumW - sumW2) / 2;
                invalid += pairs * w[i];
            }
        }

        __int128 answer = e3 - invalid;
        printInt128(answer);
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Point {
    ll x, y;
};

static inline __int128 cross(const Point& a, const Point& b) {
    return (__int128)a.x * b.y - (__int128)a.y * b.x;
}

static inline int half(const Point& p) {
    if (p.y > 0 || (p.y == 0 && p.x > 0)) return 0;
    return 1;
}

struct PairHash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    size_t operator()(const pair<ll, ll>& p) const {
        static const uint64_t FIXED_RANDOM =
            chrono::steady_clock::now().time_since_epoch().count();
        uint64_t a = splitmix64((uint64_t)p.first + FIXED_RANDOM);
        uint64_t b = splitmix64((uint64_t)p.second + FIXED_RANDOM);
        return a ^ (b << 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<Point> pts;
        pts.reserve(N);

        for (int i = 0; i < N; i++) {
            ll h, p, s;
            cin >> h >> p >> s;

            ll sum = h + p + s;

            // Centered vector (up to a factor of 3), projected to 2D.
            ll x = 3 * h - sum;
            ll y = 3 * p - sum;

            // Equal distribution gives the zero vector and can never be in a cycle.
            if (x != 0 || y != 0) {
                pts.push_back({x, y});
            }
        }

        int M = (int)pts.size();

        if (M < 3) {
            cout << 0 << '\n';
            continue;
        }

        // Count triples containing an antipodal pair. These are exactly the
        // boundary cases where the maximum circular gap is exactly pi.
        unordered_map<pair<ll, ll>, ll, PairHash> mp;
        mp.reserve(M * 2 + 10);

        for (const Point& pt : pts) {
            ll x = pt.x;
            ll y = pt.y;

            ll ax = (x >= 0 ? x : -x);
            ll ay = (y >= 0 ? y : -y);
            ll g = std::gcd(ax, ay);

            ll nx = x / g;
            ll ny = y / g;

            mp[{nx, ny}]++;
        }

        ll boundary = 0;

        for (auto& entry : mp) {
            pair<ll, ll> key = entry.first;
            ll a = entry.second;

            pair<ll, ll> opp = {-key.first, -key.second};

            if (key < opp) {
                auto it = mp.find(opp);
                if (it != mp.end()) {
                    ll b = it->second;
                    ll other = (ll)M - a - b;

                    boundary += a * b * other;
                    boundary += (a * (a - 1) / 2) * b;
                    boundary += a * (b * (b - 1) / 2);
                }
            }
        }

        // Sort vectors by polar angle.
        sort(pts.begin(), pts.end(), [](const Point& a, const Point& b) {
            int ha = half(a);
            int hb = half(b);

            if (ha != hb) return ha < hb;

            __int128 cr = cross(a, b);
            if (cr != 0) return cr > 0;

            __int128 la = (__int128)a.x * a.x + (__int128)a.y * a.y;
            __int128 lb = (__int128)b.x * b.x + (__int128)b.y * b.y;
            return la < lb;
        });

        // Count bad triples whose points fit inside an open semicircle.
        ll bad = 0;
        int r = 1;

        for (int i = 0; i < M; i++) {
            if (r < i + 1) r = i + 1;

            while (r < i + M) {
                const Point& a = pts[i];
                const Point& b = pts[r % M];

                __int128 cr = cross(a, b);
                bool inside;

                if (cr > 0) {
                    inside = true;
                } else if (cr < 0) {
                    inside = false;
                } else {
                    __int128 dot = (__int128)a.x * b.x + (__int128)a.y * b.y;

                    if (dot < 0) {
                        // Opposite directions: angle difference is pi.
                        inside = false;
                    } else {
                        // Same direction. Include duplicates only within the
                        // current full turn, not the wrapped copy.
                        inside = (r < M);
                    }
                }

                if (!inside) break;
                ++r;
            }

            ll k = (ll)r - i - 1;
            if (k >= 2) {
                bad += k * (k - 1) / 2;
            }
        }

        ll total = (ll)M * (M - 1) * (M - 2) / 6;
        ll answer = total - bad - boundary;

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
