    bool operator()(const Point& a, const Point& b) const {
        int ha = half(a), hb = half(b);
        if (ha != hb) return ha < hb;

        i128 cr = cross(a, b);
        if (cr != 0) return cr > 0;

        if (a.x != b.x) return a.x < b.x;
        return a.y < b.y;
    }
};

bool sameRay(const Point& a, const Point& b) {
    if (cross(a, b) != 0) return false;
    return dot(a, b) > 0;
}

