        vector<long long> prefW2(2 * M + 1, 0);

        for (int i = 0; i < 2 * M; i++) {
            long long ww = w[i % M];
            prefW[i + 1] = prefW[i] + ww;
            prefW2[i + 1] = prefW2[i] + ww * ww;
        }

        i128 bad = 0;
        i128 degenerate = 0;

        int r = 1;

        for (int i = 0; i < M; i++) {
            if (r < i + 1) r = i + 1;

            Point a{vx[i], vy[i]};

            while (r < i + M) {
                Point b{vx[r % M], vy[r % M]};
                if (cross(a, b) > 0) {
                    r++;
                } else {
                    break;
                }
            }

            i128 sumW = (i128)prefW[r] - prefW[i + 1];
            i128 sumW2 = (i128)prefW2[r] - prefW2[i + 1];

            i128 pairs = (sumW * sumW - sumW2) / 2;
            bad += (i128)w[i] * pairs;

            if (r < i + M) {
                Point b{vx[r % M], vy[r % M]};

                if (cross(a, b) == 0 && dot(a, b) < 0) {
                    int j = r % M;

                    if (i < j) {
                        degenerate += (i128)w[i] * w[j] *
                                      (W - w[i] - w[j]);
                    }
                }
            }
        }

        i128 answer = e3 - bad - degenerate;

        print128(answer);
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct Vec {
    int64 x, y;
};

static inline i128 cross(const Vec& a, const Vec& b) {
    return (i128)a.x * b.y - (i128)a.y * b.x;
}

static inline i128 dot(const Vec& a, const Vec& b) {
    return (i128)a.x * b.x + (i128)a.y * b.y;
}

// Half 0 contains angles [0, pi), half 1 contains [pi, 2*pi).
static inline int half(const Vec& a) {
    return (a.y > 0 || (a.y == 0 && a.x > 0)) ? 0 : 1;
}

struct Group {
    Vec v;
    int64 cnt;  // Number of cows with this direction
    int64 u;    // Number of cows with angle < angle(v) - pi
    int64 l;    // Number of cows with angle <= angle(v) - pi
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<Vec> cows;
        cows.reserve(N);

        for (int i = 0; i < N; ++i) {
            int64 h, p, s;
            cin >> h >> p >> s;

            Vec v{h - p, p - s};

            // A zero vector ties with every other cow, so it cannot
            // participate in a valid triple.
            if (v.x != 0 || v.y != 0) {
                cows.push_back(v);
            }
        }

        if (cows.size() < 3) {
            cout << 0 << '\n';
            continue;
        }

        // Exact polar-angle sorting, without floating point.
        sort(cows.begin(), cows.end(), [](const Vec& a, const Vec& b) {
            int ha = half(a);
            int hb = half(b);
            if (ha != hb) return ha < hb;
            return cross(a, b) > 0;
        });

        // Group cows pointing in the same direction.
        vector<Group> groups;
        groups.reserve(cows.size());

        for (const Vec& v : cows) {
            if (!groups.empty() &&
                cross(groups.back().v, v) == 0 &&
                dot(groups.back().v, v) > 0) {
                ++groups.back().cnt;
            } else {
                groups.push_back({v, 1, 0, 0});
            }
        }

        int M = (int)groups.size();

        vector<int64> prefixCount(M + 1, 0);
        for (int i = 0; i < M; ++i) {
            prefixCount[i + 1] = prefixCount[i] + groups[i].cnt;
        }

        int firstHalfCount = 0;
        while (firstHalfCount < M &&
               half(groups[firstHalfCount].v) == 0) {
            ++firstHalfCount;
        }

        // Compute U and L for every direction.
        for (Group& g : groups) {
            if (half(g.v) == 0) {
                // angle(g.v) - pi is negative.
                g.u = g.l = 0;
                continue;
            }

            // Let phi = angle(g.v) - pi, which lies in [0, pi).
            // For a first-half direction p:
            // cross(g.v, p) > 0 iff angle(p) < phi,
            // cross(g.v, p) = 0 iff angle(p) = phi.
            int lo = 0, hi = firstHalfCount;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (cross(g.v, groups[mid].v) > 0) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }

            int pos = lo;
            g.u = prefixCount[pos];
            g.l = g.u;

            // Include the antipodal direction only in the inclusive count.
            if (pos < firstHalfCount &&
                cross(g.v, groups[pos].v) == 0) {
                g.l += groups[pos].cnt;
            }
        }

        vector<int64> prefixMass(M + 1, 0);
        vector<int64> prefixWeightedU(M + 1, 0);

        for (int i = 0; i < M; ++i) {
            prefixMass[i + 1] = prefixMass[i] + groups[i].cnt;
            prefixWeightedU[i + 1] =
                prefixWeightedU[i] + groups[i].cnt * groups[i].u;
        }

        int64 answer = 0;
        int right = -1;

        for (int j = 0; j < M; ++j) {
            right = max(right, j);

            // For j < k, cross(v_j, v_k) > 0 exactly when
            // angle(k) - angle(j) < pi.
            while (right + 1 < M &&
                   cross(groups[j].v, groups[right + 1].v) > 0) {
                ++right;
            }

            if (right <= j) continue;

            int64 mass =
                prefixMass[right + 1] - prefixMass[j + 1];
            int64 weightedU =
                prefixWeightedU[right + 1] - prefixWeightedU[j + 1];

            answer += groups[j].cnt *
                      (weightedU - groups[j].l * mass);
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct Vec {
    int64 x, y;
};

static i128 cross(const Vec& a, const Vec& b) {
    return (i128)a.x * b.y - (i128)a.y * b.x;
}

static i128 dot(const Vec& a, const Vec& b) {
    return (i128)a.x * b.x + (i128)a.y * b.y;
}

// Half 0: angles in [0, pi), half 1: angles in [pi, 2*pi).
static int half(const Vec& a) {
    return (a.y > 0 || (a.y == 0 && a.x > 0)) ? 0 : 1;
}

static bool polarLess(const Vec& a, const Vec& b) {
    int ha = half(a), hb = half(b);
    if (ha != hb) return ha < hb;
    return cross(a, b) > 0;
}

static int64 choose2(int64 x) {
    if (x < 2) return 0;
    return x * (x - 1) / 2;
}

static int64 choose3(int64 x) {
    if (x < 3) return 0;
    return x * (x - 1) * (x - 2) / 6;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        vector<Vec> vectors;
        vectors.reserve(N);

        for (int i = 0; i < N; ++i) {
            int64 h, p, s;
            cin >> h >> p >> s;

            int64 H = h + p + s;
            int64 x = 3 * h - H;
            int64 y = 3 * p - H;

            // The zero vector represents the uniform strategy, which ties
            // against every strategy and therefore cannot be in a cycle.
            if (x != 0 || y != 0) {
                vectors.push_back({x, y});
            }
        }

        int64 n = (int64)vectors.size();
        if (n < 3) {
            cout << 0 << '\n';
            continue;
        }

        sort(vectors.begin(), vectors.end(), polarLess);

        // Group cows whose strategy vectors point in the same direction.
        vector<Vec> direction;
        vector<int64> count;

        for (const Vec& v : vectors) {
            if (!direction.empty() &&
                cross(direction.back(), v) == 0 &&
                dot(direction.back(), v) > 0) {
                ++count.back();
            } else {
                direction.push_back(v);
                count.push_back(1);
            }
        }

        int m = (int)direction.size();

        // A valid cycle needs three distinct, non-opposite directions.
        if (m < 3) {
            cout << 0 << '\n';
            continue;
        }

        // first[i] is the first direction whose counterclockwise angular
        // distance from direction i is at least pi.
        vector<int> first(m);
        int r = 1;

        for (int i = 0; i < m; ++i) {
            r = max(r, i + 1);
            while (r < i + m &&
                   cross(direction[i], direction[r % m]) > 0) {
                ++r;
            }
            first[i] = r;
        }

        // Invalid triples containing two cows with the same direction.
        int64 sameDirection = 0;
        for (int64 c : count) {
            sameDirection += choose3(c);
            sameDirection += choose2(c) * (n - c);
        }

        // Invalid triples containing a pair of opposite directions.
        // Every opposite pair is found from both endpoints, so divide by 2.
        int64 oppositeTwice = 0;

        for (int i = 0; i < m; ++i) {
            if (first[i] < i + m) {
                int j = first[i] % m;
                if (cross(direction[i], direction[j]) == 0 &&
                    dot(direction[i], direction[j]) < 0) {
                    oppositeTwice +=
                        count[i] * count[j] *
                        (n - count[i] - count[j]);
                }
            }
        }

        int64 opposite = oppositeTwice / 2;

        // Prefix sums over two copies of the circular order.
        vector<int64> prefixCount(2 * m + 1, 0);
        vector<int64> prefixSamePairs(2 * m + 1, 0);

        for (int i = 0; i < 2 * m; ++i) {
            int64 c = count[i % m];
            prefixCount[i + 1] = prefixCount[i] + c;
            prefixSamePairs[i + 1] =
                prefixSamePairs[i] + choose2(c);
        }

        // Invalid triples whose three distinct directions fit in an open
        // semicircle.
        int64 openSemicircle = 0;

        for (int i = 0; i < m; ++i) {
            int64 M = prefixCount[first[i]] - prefixCount[i + 1];
            int64 Q = prefixSamePairs[first[i]] - prefixSamePairs[i + 1];

            // Choose one cow from group i and two cows from different
            // groups in the following open half-circle.
            openSemicircle += count[i] * (choose2(M) - Q);
        }

        int64 answer = choose3(n)
                     - sameDirection
                     - opposite
                     - openSemicircle;

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct PairHash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    size_t operator()(const pair<int64, int64>& p) const {
        static const uint64_t seed =
            chrono::steady_clock::now().time_since_epoch().count();

        uint64_t a = splitmix64(static_cast<uint64_t>(p.first) + seed);
        uint64_t b = splitmix64(static_cast<uint64_t>(p.second) + seed
                                + 0x9e3779b97f4a7c15ULL);
        return a ^ (b + 0x9e3779b97f4a7c15ULL
                    + (a << 6) + (a >> 2));
    }
};

struct Bucket {
    int64 x, y;
    int64 weight;
};

struct Direction {
    int64 x, y;
    int64 weight;
};

static int halfPlane(const Direction& d) {
    return (d.y > 0 || (d.y == 0 && d.x > 0)) ? 0 : 1;
}

static i128 cross(const Direction& a, const Direction& b) {
    return (i128)a.x * b.y - (i128)a.y * b.x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N;
        cin >> N;

        unordered_map<pair<int64, int64>, Bucket, PairHash> buckets;
        buckets.max_load_factor(0.7f);
        buckets.reserve(N);

        int64 active = 0;

        for (int i = 0; i < N; ++i) {
            int64 h, p, s;
            cin >> h >> p >> s;

            int64 x = 2 * h - p - s;
            int64 y = p - s;

            // The completely mixed strategy ties against every strategy.
            if (x == 0 && y == 0) continue;

            // Normalize so that equal rays have the same key.
            int64 g = std::gcd(std::llabs(x), std::llabs(y));
            x /= g;
            y /= g;

            pair<int64, int64> key{x, y};
            auto it = buckets.find(key);

            if (it == buckets.end()) {
                buckets.emplace(key, Bucket{x, y, 1});
            } else {
                ++it->second.weight;
            }

            ++active;
        }

        int64 seen = 0;
        int64 pairs = 0;
        int64 allTriples = 0;
        int64 boundaryTriples = 0;

        vector<Direction> directions;
        directions.reserve(buckets.size());

        for (const auto& entry : buckets) {
            const auto& key = entry.first;
            const Bucket& b = entry.second;

            // Number of choices using three distinct direction groups.
            allTriples += b.weight * pairs;
            pairs += b.weight * seen;
            seen += b.weight;

            directions.push_back({b.x, b.y, b.weight});

            // Exactly opposite rays tie. A triangle containing such a pair
            // has the origin on its boundary, rather than strictly inside.
            pair<int64, int64> opposite{-b.x, -b.y};
            if (key < opposite) {
                auto jt = buckets.find(opposite);
                if (jt != buckets.end()) {
                    int64 a = b.weight;
                    int64 c = jt->second.weight;
                    boundaryTriples += a * c * (active - a - c);
                }
            }
        }

        sort(directions.begin(), directions.end(),
             [](const Direction& a, const Direction& b) {
                 int ha = halfPlane(a);
                 int hb = halfPlane(b);
                 if (ha != hb) return ha < hb;
                 return cross(a, b) > 0;
             });

        int M = (int)directions.size();

        // Duplicate the circular ordering.
        vector<Direction> circular(2 * M);
        for (int i = 0; i < 2 * M; ++i) {
            circular[i] = directions[i % M];
        }

        vector<int64> prefixWeight(2 * M + 1, 0);
        vector<int64> prefixSquare(2 * M + 1, 0);

        for (int i = 0; i < 2 * M; ++i) {
            int64 w = circular[i].weight;
            prefixWeight[i + 1] = prefixWeight[i] + w;
            prefixSquare[i + 1] = prefixSquare[i] + w * w;
        }

        // Count triples lying in an open semicircle. Each such triple has
        // a unique direction immediately following its unique gap > 180°.
        int64 outsideTriples = 0;
        int r = 1;

        for (int i = 0; i < M; ++i) {
            r = max(r, i + 1);

            while (r < i + M && cross(circular[i], circular[r]) > 0) {
                ++r;
            }

            int64 sum = prefixWeight[r] - prefixWeight[i + 1];
            int64 sumSquares =
                prefixSquare[r] - prefixSquare[i + 1];

            int64 twoDistinctGroups = (sum * sum - sumSquares) / 2;
            outsideTriples += circular[i].weight * twoDistinctGroups;
        }

        int64 answer = allTriples - outsideTriples - boundaryTriples;
        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

// f(r) is the next time at which a cow returns to position 0,
// given that its previous return was at time r.
static inline int64 next_reset(int64 r) {
    return (3 * (r + 1)) / 2;
}

// Minimum r such that f(r) >= y.
static inline int64 inverse_threshold(int64 y) {
    if (y <= 0) return 0;
    return (2 * y + 2) / 3 - 1;
}

// Minimum k >= 1 such that 3*k - 1 >= x.
static inline int64 min_cow(int64 x) {
    return (x + 3) / 3;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    while (Q--) {
        int64 l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        if (t == 0) {
            cout << ((l1 == 0 && l2 == 0) ? 1 : 0) << '\n';
            continue;
        }

        int64 answer = 0;

        // Cows which have never entered the moving prefix remain at
        // position equal to their cow number.
        int64 active_max = (t + 1) / 2;
        int64 lo = max({l1, active_max + 1, l2});
        int64 hi = min({r1, t, r2});
        if (lo <= hi) answer += hi - lo + 1;

        // Cow 0 has the same reset-time process, starting at time 0.
        int64 reset = 0;
        while (reset < t) reset = next_reset(reset);
        int64 pos0 = reset - t;
        if (l1 == 0 && l2 <= pos0 && pos0 <= r2) ++answer;

        if (r1 >= 1 && l1 <= active_max) {
            // For cow k >= 1, write x = 3*k - 1. Its reset times are
            // x, f(x), f^2(x), ... . At time t, if f^i(x) is the first
            // reset time >= t, its position is f^i(x) - t.
            //
            // b, c, d are inverse thresholds:
            // b: minimum initial x with f^i(x) >= t
            // c: minimum initial x with f^i(x) >= t+l2
            // d: minimum initial x with f^i(x) >= t+r2+1
            int64 b = t;
            int64 c = t + l2;
            int64 d = t + r2 + 1;
            int64 previous_b = 0;

            for (int i = 0;; ++i) {
                int64 lower = max({int64(1), l1, min_cow(b), min_cow(c)});
                int64 upper = min({active_max, r1, d / 3});

                // For i >= 1, this group also requires
                // f^(i-1)(x) < t, equivalently x < previous_b.
                if (i > 0) upper = min(upper, previous_b / 3);

                if (lower <= upper) answer += upper - lower + 1;

                // Once min_cow(b) == 1, this is the final group and all
                // remaining active cows have been covered.
                if (min_cow(b) <= 1) break;

                previous_b = b;
                b = inverse_threshold(b);
                c = inverse_threshold(c);
                d = inverse_threshold(d);
            }
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

static inline int64 nextFront(int64 f) {
    return (3 * f + 3) / 2;
}

// Number of n in [a,b] whose associated cow lies in [L,R].
int64 countTimes(int64 a, int64 b, int64 L, int64 R) {
    if (a > b || L > R) return 0;

    int64 result = 0;

    // Cow 0 is represented by the base case n = 0.
    if (L == 0 && a == 0) ++result;

    // Initial front times are n = 3*c - 1 for cows c >= 1.
    int64 cowLo = max<int64>(1, L);
    int64 cowHi = R;
    cowLo = max(cowLo, (a + 3) / 3);
    cowHi = min(cowHi, (b + 1) / 3);
    if (cowLo <= cowHi) result += cowHi - cowLo + 1;

    if (b == 0) return result;

    // All other values n arise as nextFront(f).  Since nextFront is
    // increasing, the possible f values form one interval.
    int64 lo = max<int64>(0, 2 * a / 3 - 2);
    while (nextFront(lo) < a) ++lo;

    int64 hi = 2 * b / 3 + 2;
    while (nextFront(hi) > b) --hi;

    if (lo <= hi) result += countTimes(lo, hi, L, R);
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    while (Q--) {
        int64 l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        int64 m = t / 2;
        int64 answer = 0;

        // Cows 0..m occupy positions 0..m.  For such a cow at position p,
        // set n = t+p and recursively determine its cow number.
        int64 L = l1, R = min(r1, m);
        int64 pLo = l2, pHi = min(r2, m);
        if (L <= R && pLo <= pHi) {
            answer += countTimes(t + pLo, t + pHi, L, R);
        }

        // Every cow c > m is still at position c.
        int64 a = max(max(l1, m + 1), l2);
        int64 b = min(min(r1, t), r2);
        if (a <= b) answer += b - a + 1;

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

// Number of integers s in [0, n] for which the cow at the front
// at time s has a label in [a, b].
int64 prefixCount(int64 n, int64 a, int64 b) {
    if (n < 0) return 0;

    int64 result = 0;
    const bool includeZero = (a == 0);

    while (n >= 0) {
        if (includeZero) ++result;
        if (n == 0) break;

        int64 k = (n + 1) / 3;
        int64 lo = max<int64>(1, a);
        int64 hi = min(k, b);
        if (lo <= hi) result += hi - lo + 1;

        n = 2 * (n - 1) / 3;
    }
    return result;
}

int64 rangeCount(int64 l, int64 r, int64 a, int64 b) {
    return prefixCount(r, a, b) - prefixCount(l - 1, a, b);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    while (Q--) {
        int64 l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        const int64 h = t / 2;
        int64 answer = 0;

        // Cows 0..h form the nontrivial prefix of the line.
        int64 cowL = l1, cowR = min(r1, h);
        int64 posL = l2, posR = min(r2, h);

        if (cowL <= cowR && posL <= posR) {
            // The cow at position p is the cow that was/will be at
            // the front at time t+p.
            answer += rangeCount(t + posL, t + posR, cowL, cowR);
        }

        // Every cow i>h remains at position i.
        int64 lo = max(max(l1, l2), h + 1);
        int64 hi = min(r1, r2);
        if (lo <= hi) answer += hi - lo + 1;

        cout << answer << '\n';
    }

    return 0;
}

