        // position equal to their cow number.
        int64 active_max = (t + 1) / 2;
        int64 lo = max({l1, active_max + 1, l2});
        int64 hi = min({r1, t, r2});
        if (lo <= hi) answer += hi - lo + 1;

        // Cow 0 has the same reset-time process, starting at time 0.
        int64 reset = 0;
        while (reset < t) reset = next_reset(reset);
        int64 pos0 = reset - t;
        if (l1 == 0 && l2 <= pos0 && pos0 <= r2) ++answer;

        if (r1 >= 1 && l1 <= active_max) {
            // For cow k >= 1, write x = 3*k - 1. Its reset times are
            // x, f(x), f^2(x), ... . At time t, if f^i(x) is the first
            // reset time >= t, its position is f^i(x) - t.
            //
            // b, c, d are inverse thresholds:
            // b: minimum initial x with f^i(x) >= t
            // c: minimum initial x with f^i(x) >= t+l2
            // d: minimum initial x with f^i(x) >= t+r2+1
            int64 b = t;
            int64 c = t + l2;
            int64 d = t + r2 + 1;
            int64 previous_b = 0;

            for (int i = 0;; ++i) {
                int64 lower = max({int64(1), l1, min_cow(b), min_cow(c)});
                int64 upper = min({active_max, r1, d / 3});

                // For i >= 1, this group also requires
                // f^(i-1)(x) < t, equivalently x < previous_b.
                if (i > 0) upper = min(upper, previous_b / 3);

                if (lower <= upper) answer += upper - lower + 1;

                // Once min_cow(b) == 1, this is the final group and all
                // remaining active cows have been covered.
                if (min_cow(b) <= 1) break;

                previous_b = b;
                b = inverse_threshold(b);
                c = inverse_threshold(c);
                d = inverse_threshold(d);
            }
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

static inline int64 nextFront(int64 f) {
    return (3 * f + 3) / 2;
}

// Number of n in [a,b] whose associated cow lies in [L,R].
int64 countTimes(int64 a, int64 b, int64 L, int64 R) {
    if (a > b || L > R) return 0;

    int64 result = 0;

    // Cow 0 is represented by the base case n = 0.
    if (L == 0 && a == 0) ++result;

    // Initial front times are n = 3*c - 1 for cows c >= 1.
    int64 cowLo = max<int64>(1, L);
    int64 cowHi = R;
    cowLo = max(cowLo, (a + 3) / 3);
    cowHi = min(cowHi, (b + 1) / 3);
    if (cowLo <= cowHi) result += cowHi - cowLo + 1;

    if (b == 0) return result;

    // All other values n arise as nextFront(f).  Since nextFront is
    // increasing, the possible f values form one interval.
    int64 lo = max<int64>(0, 2 * a / 3 - 2);
    while (nextFront(lo) < a) ++lo;

    int64 hi = 2 * b / 3 + 2;
    while (nextFront(hi) > b) --hi;

    if (lo <= hi) result += countTimes(lo, hi, L, R);
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    while (Q--) {
        int64 l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        int64 m = t / 2;
        int64 answer = 0;

        // Cows 0..m occupy positions 0..m.  For such a cow at position p,
        // set n = t+p and recursively determine its cow number.
        int64 L = l1, R = min(r1, m);
        int64 pLo = l2, pHi = min(r2, m);
        if (L <= R && pLo <= pHi) {
            answer += countTimes(t + pLo, t + pHi, L, R);
        }

        // Every cow c > m is still at position c.
        int64 a = max(max(l1, m + 1), l2);
        int64 b = min(min(r1, t), r2);
        if (a <= b) answer += b - a + 1;

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

// Number of integers s in [0, n] for which the cow at the front
// at time s has a label in [a, b].
int64 prefixCount(int64 n, int64 a, int64 b) {
    if (n < 0) return 0;

    int64 result = 0;
    const bool includeZero = (a == 0);

    while (n >= 0) {
        if (includeZero) ++result;
        if (n == 0) break;

        int64 k = (n + 1) / 3;
        int64 lo = max<int64>(1, a);
        int64 hi = min(k, b);
        if (lo <= hi) result += hi - lo + 1;

        n = 2 * (n - 1) / 3;
    }
    return result;
}

int64 rangeCount(int64 l, int64 r, int64 a, int64 b) {
    return prefixCount(r, a, b) - prefixCount(l - 1, a, b);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    while (Q--) {
        int64 l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        const int64 h = t / 2;
        int64 answer = 0;

        // Cows 0..h form the nontrivial prefix of the line.
        int64 cowL = l1, cowR = min(r1, h);
        int64 posL = l2, posR = min(r2, h);

        if (cowL <= cowR && posL <= posR) {
            // The cow at position p is the cow that was/will be at
            // the front at time t+p.
            answer += rangeCount(t + posL, t + posR, cowL, cowR);
        }

        // Every cow i>h remains at position i.
        int64 lo = max(max(l1, l2), h + 1);
        int64 hi = min(r1, r2);
        if (lo <= hi) answer += hi - lo + 1;

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int THRESH = 200;
vector<vector<long long>> smallPerm;

void precomputeSmall() {
    smallPerm.assign(THRESH + 1, {});
    if (THRESH >= 1) smallPerm[1] = {0};
    if (THRESH >= 2) smallPerm[2] = {0, 1};

    for (int n = 3; n <= THRESH; n++) {
        auto &prev = smallPerm[n - 1];
        auto &cur = smallPerm[n];
        cur.reserve(n);

        // C_n = C_{n-1}[2..] + [n-1, C_{n-1}[0], C_{n-1}[1]]
        for (int i = 2; i < (int)prev.size(); i++) cur.push_back(prev[i]);
        cur.push_back(n - 1);
        cur.push_back(prev[0]);
        cur.push_back(prev[1]);
    }
}

// Count entries of C_N whose value is in [vl, vr] and whose position is in [pl, pr].
// odd = 1: A_t = C_N
// odd = 0: A_t = B_N, where B_N is C_N rotated right by one.
long long solvePrefix(long long N, long long vl, long long vr,
                      long long pl, long long pr, int odd) {
    if (N <= 0) return 0;

    if (vl < 0) vl = 0;
    if (vr > N - 1) vr = N - 1;
    if (vl > vr) return 0;

    if (pl < 0) pl = 0;
    if (pr > N - 1) pr = N - 1;
    if (pl > pr) return 0;

    if (N <= THRESH) {
        auto &v = smallPerm[N];
        long long ans = 0;

        if (odd) {
            for (long long pos = pl; pos <= pr; pos++) {
                long long val = v[pos];
                if (vl <= val && val <= vr) ans++;
            }
        } else {
            for (long long pos = pl; pos <= pr; pos++) {
                long long val;
                if (pos == 0) val = v[N - 1];
                else val = v[pos - 1];

                if (vl <= val && val <= vr) ans++;
            }
        }

        return ans;
    }

    const int MAXD = 300;
    long long Ns[MAXD];
    long long suf[MAXD][6];
    int sufLen[MAXD];

    int D = 0;
    Ns[0] = N;

    while (Ns[D] > THRESH) {
        long long cur = Ns[D];
        long long nxt = cur - cur / 3;
        Ns[++D] = nxt;
    }

    // Base suffix.
    {
        long long Nb = Ns[D];
        auto &v = smallPerm[Nb];
        int len = (int)v.size();
        int L = min(6, len);
        sufLen[D] = L;

        for (int i = 0; i < L; i++) {
            suf[D][i] = v[len - L + i];
        }
    }

    // Compute last 6 values of every C_{Ns[j]}.
    for (int j = D - 1; j >= 0; j--) {
        long long cur = Ns[j];
        long long r = cur % 3;

        long long vals[6]; // vals[o] = element at offset o from the end

        for (int o = 0; o < 6; o++) {
            int t = o + 1;

            if (t % 3 == 0) {
                vals[o] = cur - t / 3;
            } else if (t % 3 == 1) {
                int s = (t - 1) / 3;
                int childOffset = (int)r + 2 * s;
                int idx = sufLen[j + 1] - 1 - childOffset;
                vals[o] = suf[j + 1][idx];
            } else {
                int s = (t - 2) / 3;
                int childOffset = (int)r + 2 * s + 1;
                int idx = sufLen[j + 1] - 1 - childOffset;
                vals[o] = suf[j + 1][idx];
            }
        }

        sufLen[j] = 6;
        for (int idx = 0; idx < 6; idx++) {
            suf[j][idx] = vals[5 - idx]; // increasing order
        }
    }

    auto processC = [&](long long Lpos, long long Rpos) -> long long {
        if (Lpos < 0) Lpos = 0;
        if (Rpos > N - 1) Rpos = N - 1;
        if (Lpos > Rpos) return 0;

        long long ans = 0;
        long long curL = Lpos;
        long long curR = Rpos;

        for (int i = 0; i <= D; i++) {
            long long curN = Ns[i];
            if (curL > curR) break;

            if (curN <= THRESH) {
                auto &v = smallPerm[curN];

                for (long long pos = curL; pos <= curR; pos++) {
                    long long val = v[pos];
                    if (vl <= val && val <= vr) ans++;
                }

                break;
            }

            long long k = curN / 3;
            long long r = curN % 3;
            long long n = Ns[i + 1];

            // Special prefix: positions 0 .. r-1.
            for (int p = 0; p < (int)r; p++) {
                if (curL <= p && p <= curR) {
                    int off = (int)r - 1 - p;
                    int idx = sufLen[i + 1] - 1 - off;
                    long long val = suf[i + 1][idx];

                    if (vl <= val && val <= vr) ans++;
                }
            }

            // New labels inside the block.
            long long Lblock = max(curL, r);
            long long Rblock = curR;

            if (Lblock <= Rblock) {
                long long lo = 0;
                long long hi = k - 1;

                long long tL = Lblock - r;
                long long iL = (tL + 2) / 3;
                long long iR = (Rblock - r) / 3;

                lo = max(lo, iL);
                hi = min(hi, iR);

                lo = max(lo, vl - n);
                hi = min(hi, vr - n);

                if (lo <= hi) ans += hi - lo + 1;
            }

            // Old part of the block.
            long long y = curL - r - 1;
            long long pL;

            if (y <= 0) pL = 0;
            else pL = (2 * y + 2) / 3;

            long long z = curR - r - 1;
            long long pR;

            if (z < 0) pR = -1;
            else pR = (2 * z + 1) / 3;

            long long maxP = 2 * k - 1;

            if (pL < 0) pL = 0;
            if (pR > maxP) pR = maxP;
            if (pL > maxP) pL = maxP + 1;

            if (pL > pR) break;

            curL = pL;
            curR = pR;
        }

        return ans;
    };

    if (odd) {
        return processC(pl, pr);
    } else {
        long long ans = 0;

        // B[0] = C[N-1]
        if (pl <= 0 && 0 <= pr) {
            ans += processC(N - 1, N - 1);
        }

        // B[i] = C[i-1] for i >= 1
        long long L = max(1LL, pl);
        long long R = pr;

        if (L <= R) {
            ans += processC(L - 1, R - 1);
        }

        return ans;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    precomputeSmall();

    int Q;
    cin >> Q;

    while (Q--) {
        long long l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        long long m = t / 2;
        long long N = m + 1;

        long long ans = 0;

        // Prefix positions 0..m contain labels 0..m in A_t.
        long long vl = max(l1, 0LL);
        long long vr = min(r1, m);

        long long pl = max(l2, 0LL);
        long long pr = min(r2, m);

        if (vl <= vr && pl <= pr) {
            int odd = (t % 2 == 1);

            if (odd) {
                // A_t = C_N
                ans += solvePrefix(N, vl, vr, pl, pr, 1);
            } else {
                // A_t = B_N
                ans += solvePrefix(N, vl, vr, pl, pr, 0);
            }
        }

        // Suffix labels m+1..t stay at their own positions.
        long long sl = max({l1, m + 1, l2});
        long long sr = min({r1, t, r2});

        if (sl <= sr) {
            ans += sr - sl + 1;
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int TH = 200;
static const int K = 8;
static const int MAXD = 200;

vector<vector<long long>> smallB;

struct Solver {
    long long N;
    int depth;
    long long ns[MAXD];
    long long first[MAXD][K];

    Solver(long long n) : N(n), depth(0) {
        if (N > TH) buildPath();
    }

    static long long countRange(long long a, long long b, long long ql, long long qr) {
        if (a > b) return 0;
        long long L = max(a, ql);
        long long R = min(b, qr);
        if (L > R) return 0;
        return R - L + 1;
    }

    void buildPath() {
        long long cur = N;
        int len = 0;

        while (cur > TH) {
            ns[len++] = cur;
            long long M = cur - (cur % 3);
            cur = 2 * (M / 3);
        }
        ns[len] = cur;
        depth = len + 1;

        int baseIdx = depth - 1;
        long long baseN = ns[baseIdx];
        for (int k = 0; k < K; k++) {
            if (k < (int)smallB[baseN].size()) first[baseIdx][k] = smallB[baseN][k];
            else first[baseIdx][k] = -1;
        }

        for (int j = depth - 2; j >= 0; j--) {
            long long curN = ns[j];
            int r = curN % 3;
            int d = 2 * r;
            long long L = ns[j + 1];

            for (int k = 0; k < K; k++) {
                long long p = d + k;
                int s = p / 3;
                int t = p % 3;
                long long lab;

                if (t == 0) lab = first[j + 1][2 * s];
                else if (t == 1) lab = L + s;
                else lab = first[j + 1][2 * s + 1];

                first[j][k] = lab;
            }
        }
    }

    long long getBMlabel(int j, int k, long long L) const {
        int s = k / 3;
        int t = k % 3;
        if (t == 0) return first[j + 1][2 * s];
        if (t == 1) return L + s;
        return first[j + 1][2 * s + 1];
    }

    long long firstDcount(int j, int d, long long L, long long ql, long long qr) const {
        long long cnt = 0;
        for (int k = 0; k < d; k++) {
            int s = k / 3;
            int t = k % 3;
            long long lab;

            if (t == 0) lab = first[j + 1][2 * s];
            else if (t == 1) lab = L + s;
            else lab = first[j + 1][2 * s + 1];

            if (lab >= ql && lab <= qr) cnt++;
        }
        return cnt;
    }

    long long countSPrefix(int j, int r, long long M, long long L,
                           long long remS, long long ql, long long qr) const {
        long long cnt = 0;

        for (int i = 0; i < remS; i++) {
            long long lab;

            if (r == 1) {
                if (i == 0) lab = getBMlabel(j, 0, L);
                else if (i == 1) lab = M;
                else lab = getBMlabel(j, 1, L);
            } else { // r == 2
                if (i == 0) lab = getBMlabel(j, 0, L);
                else if (i == 1) lab = M;
                else if (i == 2) lab = getBMlabel(j, 1, L);
                else if (i == 3) lab = getBMlabel(j, 2, L);
                else if (i == 4) lab = M + 1;
                else lab = getBMlabel(j, 3, L);
            }

            if (lab >= ql && lab <= qr) cnt++;
        }

        return cnt;
    }

    long long evalPrefix(long long P, long long ql, long long qr) const {
        if (P <= 0) return 0;
        if (P > N) P = N;

        long long ans = 0;

        for (int j = 0; j < depth - 1; j++) {
            long long cur = ns[j];
            int r = cur % 3;
            long long M = cur - r;
            int d = 2 * r;
            long long L = ns[j + 1];

            if (r == 0) {
                long long Sfull = P / 3;
                int rem = P % 3;

                if (Sfull > 0) {
                    ans += countRange(L, L + Sfull - 1, ql, qr);
                }
                if (rem >= 2) {
                    long long lab = L + Sfull;
                    if (lab >= ql && lab <= qr) ans++;
                }

                P = 2 * Sfull + (rem >= 1 ? 1 : 0);
            } else {
                long long lenBase = M - d;

                if (P <= lenBase) {
                    long long PM = d + P;
                    long long Sfull = PM / 3;
                    int rem = PM % 3;

                    if (Sfull > 0) {
                        ans += countRange(L, L + Sfull - 1, ql, qr);
                    }
                    if (rem >= 2) {
                        long long lab = L + Sfull;
                        if (lab >= ql && lab <= qr) ans++;
                    }

                    ans -= firstDcount(j, d, L, ql, qr);

                    P = 2 * Sfull + (rem >= 1 ? 1 : 0);
                } else {
                    ans += countRange(0, M - 1, ql, qr);
                    ans -= firstDcount(j, d, L, ql, qr);

                    long long remS = P - lenBase;
                    ans += countSPrefix(j, r, M, L, remS, ql, qr);

                    return ans;
                }
            }
        }

        long long baseN = ns[depth - 1];
        if (P > baseN) P = baseN;

        const vector<long long>& v = smallB[baseN];
        for (int i = 0; i < P; i++) {
            if (v[i] >= ql && v[i] <= qr) ans++;
        }

        return ans;
    }

    long long countInterval(long long pl, long long pr, long long ql, long long qr) const {
        if (pl < 0) pl = 0;
        if (pr >= N) pr = N - 1;
        if (pl > pr) return 0;

        if (ql < 0) ql = 0;
        if (qr >= N) qr = N - 1;
        if (ql > qr) return 0;

        if (N <= TH) {
            long long cnt = 0;
            const vector<long long>& v = smallB[N];
            for (long long i = pl; i <= pr; i++) {
                if (v[i] >= ql && v[i] <= qr) cnt++;
            }
            return cnt;
        }

        return evalPrefix(pr + 1, ql, qr) - evalPrefix(pl, ql, qr);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    smallB.assign(TH + 1, vector<long long>());

    smallB[1] = {0};
    if (TH >= 2) smallB[2] = {1, 0};

    for (int n = 2; n < TH; n++) {
        vector<long long> v = smallB[n];
        long long a = v[0];
        long long b = v[1];

        vector<long long> nv;
        nv.reserve(n + 1);

        for (int i = 2; i < n; i++) nv.push_back(v[i]);
        nv.push_back(a);
        nv.push_back(n);
        nv.push_back(b);

        smallB[n + 1] = move(nv);
    }

    int Q;
    cin >> Q;

    while (Q--) {
        long long l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        long long N = t / 2 + 1;
        long long ans = 0;

        long long a = max(l2, 0LL);
        long long b = min(r2, N - 1);

        if (a <= b) {
            Solver solver(N);

            if (t % 2 == 0) {
                ans += solver.countInterval(a, b, l1, r1);
            } else {
                // Active prefix is left rotation of B_N by one.
                if (b < N - 1) {
                    ans += solver.countInterval(a + 1, b + 1, l1, r1);
                } else {
                    if (a <= N - 2) {
                        ans += solver.countInterval(a + 1, N - 1, l1, r1);
                    }
                    ans += solver.countInterval(0, 0, l1, r1);
                }
            }
        }

        // Suffix: positions N ... t contain labels equal to their positions.
        long long A = max(l2, N);
        long long B = min(r2, t);

        if (A <= B) {
            long long L = max(A, l1);
            long long R = min(B, r1);
            if (L <= R) ans += R - L + 1;
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

static inline int64 invF(int64 q) {
    // Maximum p >= 0 such that floor(3p/2) + 2 <= q
    if (q < 3) return 0;
    return (2 * q - 3) / 3;
}

static inline int64 countP0Interval(
    int64 lo, int64 hi, int64 L, int64 R, int64 m
) {
    // Count x in [L,R] ∩ [0,m-1] with lo < p0(x) <= hi,
    // where p0(0)=2, p0(1)=1, p0(x)=3x-2 for x>=2.
    if (lo >= hi) return 0;

    int64 ans = 0;

    if (L <= 0 && 0 <= R && m >= 1) {
        if (lo < 2 && 2 <= hi) ++ans;
    }

    if (L <= 1 && 1 <= R && m >= 2) {
        if (lo < 1 && 1 <= hi) ++ans;
    }

    int64 xL = max(L, 2LL);
    int64 xR = min(R, m - 1);

    if (xL <= xR) {
        // lo < 3x - 2 <= hi
        int64 lowX = (lo + 2) / 3 + 1;
        int64 highX = (hi + 2) / 3;

        int64 left = max(xL, lowX);
        int64 right = min(xR, highX);

        if (left <= right) ans += right - left + 1;
    }

    return ans;
}

// Count x in [L,R] whose position in P_m is in [a,b].
// P_m is the active permutation for even time 2(m-1).
static int64 countP(
    int64 m, int64 L, int64 R, int64 a, int64 b
) {
    if (m <= 0 || L > R || a > b) return 0;

    L = max(L, 0LL);
    R = min(R, m - 1);
    a = max(a, 0LL);
    b = min(b, m - 1);

    if (L > R || a > b) return 0;

    if (m == 1) {
        return (L <= 0 && 0 <= R && a <= 0 && 0 <= b) ? 1 : 0;
    }

    // For m >= 2:
    // P_m is the suffix of length m of the generated sequence E.
    int64 S = 2 * m - 3;
    int64 N = 3 * m - 4;

    int64 A = a + S;
    int64 B = b + S;

    int64 cur = N;          // H^k(N)
    int64 low = A - 1;      // H^k(A-1)
    int64 high = B;         // H^k(B)

    int64 ans = 0;

    while (cur > 0) {
        int64 nxt = invF(cur);

        int64 lo = max(nxt, low);
        int64 hi = min(cur, high);

        if (lo < hi) {
            ans += countP0Interval(lo, hi, L, R, m);
        }

        low = invF(low);
        high = invF(high);
        cur = nxt;

        if (low >= high) break;
    }

    return ans;
}

// For odd time, the active permutation is P_m rotated left by one.
static int64 countPCyclic(
    int64 m, int64 L, int64 R, int64 a, int64 b
) {
    if (m <= 0 || L > R || a > b) return 0;

    a = max(a, 0LL);
    b = min(b, m - 1);
    if (a > b) return 0;

    int64 len = b - a + 1;
    int64 start = (a + 1) % m;

    int64 firstLen = min(len, m - start);

    int64 ans = 0;
    if (firstLen > 0) {
        ans += countP(m, L, R, start, start + firstLen - 1);
    }

    int64 rem = len - firstLen;
    if (rem > 0) {
        ans += countP(m, L, R, 0, rem - 1);
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    while (Q--) {
        int64 l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        // Active cows are 0 ... m-1, occupying positions 0 ... m-1.
        int64 m = t / 2 + 1;

        int64 ans = 0;

        // Active part.
        int64 L = max(l1, 0LL);
        int64 R = min(r1, m - 1);

        int64 a = max(l2, 0LL);
        int64 b = min(r2, m - 1);

        if (L <= R && a <= b) {
            if (t % 2 == 0) {
                ans += countP(m, L, R, a, b);
            } else {
                ans += countPCyclic(m, L, R, a, b);
            }
        }

        // Fixed part: cows x >= m have position x.
        int64 lo = max(l1, m);
        lo = max(lo, l2);

        int64 hi = min(r1, r2);

        if (lo <= hi) {
            ans += hi - lo + 1;
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Solver {
    int64 t, m, R, nextZero;

    explicit Solver(int64 time)
        : t(time),
          m(time / 2),
          R((3 * time + 3) / 2),
          nextZero(0) {
        // The service times of cow 0 are h^k(0), for k >= 1.
        // Find its first service time strictly larger than t.
        while (nextZero <= t) {
            nextZero = nextZero + nextZero / 2 + 1;
        }
    }

    // Largest nonnegative z such that h(z) <= x.
    static int64 G(int64 x) {
        return (2 * x - 1) / 3;
    }

    // Number of active cows whose next service time is at most X.
    int64 activeCount(int64 X) const {
        int64 roots = X / 3;

        if (X <= R) {
            return X - t - max(0LL, roots - m);
        }

        return min(roots, m) + 1;
    }

    // Time of the k-th next service among the active cows.
    int64 kthEvent(int64 k) const {
        int64 low = t, high = R;

        while (low < high) {
            int64 mid = low + (high - low) / 2;
            if (activeCount(mid) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        return low;
    }

    // Count cows with labels in [a, b] whose next service time is <= X.
    // The label interval passed here is contained in [0, m].
    int64 selectedCount(int64 X, int64 a, int64 b) const {
        if (X < t || a > b) return 0;

        int64 answer = 0;

        // Depth 0: the first service of cow s is at time 3s.
        int64 lo = max(a, t / 3 + 1);
        int64 hi = min(b, X / 3);
        if (lo <= hi) answer += hi - lo + 1;

        int64 gt = t;
        int64 gx = X;
        int64 previousA = t / 3;

        // Positive-depth first services.
        while (previousA > 0) {
            gt = G(gt);
            if (gx > 0) gx = G(gx);

            int64 currentA = gt / 3;
            int64 currentB = gx / 3;

            lo = max(a, currentA + 1);
            hi = min(b, min(previousA, currentB));

            if (lo <= hi) answer += hi - lo + 1;

            previousA = currentA;

            // No positive label can have a deeper service time <= X.
            if (gx == 0) break;
        }

        // Cow 0 has a separate chain rooted at 0.
        if (a <= 0 && 0 <= b && nextZero <= X) {
            ++answer;
        }

        return answer;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    while (Q--) {
        int64 l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        Solver solver(t);

        // Active cows have labels 0..m and occupy positions 0..m.
        int64 activeLabelsLeft = l1;
        int64 activeLabelsRight = min(r1, solver.m);
        int64 activePositionsLeft = l2;
        int64 activePositionsRight = min(r2, solver.m);

        int64 activeAnswer = 0;

        if (activeLabelsLeft <= activeLabelsRight &&
            activePositionsLeft <= activePositionsRight) {
            int64 before;
            if (activePositionsLeft == 0) {
                before = t;
            } else {
                before = solver.kthEvent(activePositionsLeft);
            }

            int64 through;
            if (activePositionsRight == solver.m) {
                through = solver.R;
            } else {
                through = solver.kthEvent(activePositionsRight + 1);
            }

            activeAnswer =
                solver.selectedCount(
                    through, activeLabelsLeft, activeLabelsRight
                ) -
                solver.selectedCount(
                    before, activeLabelsLeft, activeLabelsRight
                );
        }

        // Every inactive cow s is still at position s.
        int64 inactiveLeft = max(l1, solver.m + 1);
        int64 inactiveRight = min(min(r1, r2), t);

        int64 inactiveAnswer = 0;
        if (inactiveLeft <= inactiveRight) {
            inactiveAnswer = inactiveRight - inactiveLeft + 1;
        }

        cout << activeAnswer + inactiveAnswer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

constexpr int MAX_ITER = 256;

// G(z) = floor(3z / 2).
static inline int64 G(int64 z) {
    return z + z / 2;
}

// H(v) = max { z : G(z) <= v } = floor((2v + 1) / 3).
static inline int64 H(int64 v) {
    return (2 * v + 1) / 3;
}

static inline int64 ceilDiv3(int64 v) {
    return (v + 2) / 3;
}

// Stores H^0(v), H^1(v), ...
static int buildH(int64 v, array<int64, MAX_ITER>& a) {
    int n = 1;
    a[0] = v;
    while (v > 1 && n < MAX_ITER) {
        v = H(v);
        a[n++] = v;
    }
    return n;
}

// Counts a in [lo, hi] with a == 3*x + 2 for some integer x >= 1.
static inline int64 countResidue(int64 lo, int64 hi) {
    if (lo > hi) return 0;

    int64 firstX = lo / 3;
    int64 lastX = (hi - 2) / 3;

    return max(0LL, lastX - firstX + 1);
}

static int64 solveQuery(int64 l1, int64 r1,
                        int64 l2, int64 r2,
                        int64 t) {
    int64 answer = 0;

    const int64 half = t / 2;
    const int64 cycleMax = (t + 1) / 3;
    const int64 S = t + 3;

    // Cows with x > floor(t/2) have not moved and are at position x.
    {
        int64 lo = max({l1, half + 1, l2});
        int64 hi = min(r1, r2);
        if (lo <= hi) answer += hi - lo + 1;
    }

    // Cows with cycleMax < x <= floor(t/2) are at position 3*x - 1 - t.
    {
        int64 lo = max({
            l1,
            cycleMax + 1,
            ceilDiv3(t + l2 + 1)
        });
        int64 hi = min({
            r1,
            half,
            (t + r2 + 1) / 3
        });
        if (lo <= hi) answer += hi - lo + 1;
    }

    const int64 cycleLo = max(l1, 1LL);
    const int64 cycleHi = min(r1, cycleMax);

    // Count positive positions of cows in the cyclic part.
    if (cycleLo <= cycleHi && r2 >= 1) {
        const int64 L = max(l2, 1LL);
        const int64 R = r2;

        array<int64, MAX_ITER> hZero, hLow, hHigh;
        int nZero = buildH(S - 1, hZero);
        int nLow = buildH(S + L - 1, hLow);
        int nHigh = buildH(S + R, hHigh);

        const int64 aLo = 3 * cycleLo + 2;
        const int64 aHi = 3 * cycleHi + 2;

        for (int k = 0;
             k + 1 < nZero && k + 1 < nLow && k + 1 < nHigh;
             ++k) {
            if (hZero[k] < 5) break;

            int64 lo = max(aLo, hLow[k + 1] + 1);
            int64 hi = min(aHi, hHigh[k + 1]);
            hi = min(hi, hZero[k]);

            answer += countResidue(lo, hi);
        }
    }

    // Count cows x >= 1 whose position is zero.
    // G has an exact inverse unless v == 2 (mod 3).
    if (l2 == 0 && cycleLo <= cycleHi) {
        int64 v = S;

        while (v >= 5) {
            int64 rem = v % 3;

            if (rem == 2) {
                int64 x = (v - 2) / 3;
                if (l1 <= x && x <= r1) ++answer;
                break;
            }

            int64 q = v / 3;
            v = (rem == 0 ? 2 * q : 2 * q + 1);
        }
    }

    // Cow 0 follows the same recurrence, but starts with z = 3.
    if (l1 == 0) {
        int64 z = 3;
        int64 next = G(z);

        while (next <= S) {
            z = next;
            next = G(z);
        }

        int64 position = (z == S ? 0 : next - S);
        if (l2 <= position && position <= r2) ++answer;
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    string output;
    output.reserve(static_cast<size_t>(Q) * 22);

    while (Q--) {
        int64 l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        output += to_string(solveQuery(l1, r1, l2, r2, t));
        output.push_back('\n');
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

// If F(v) = floor(3v / 2), then F(v) <= z exactly when v <= G(z).
static inline int64 G(int64 z) {
    return (2 * z + 1) / 3;
}

// Maximum x >= 0 satisfying G^k(z) >= 3x + 2.
// Returns -1 if no such x exists.
static inline int64 maxId(int64 z) {
    if (z < 2) return -1;
    return (z - 2) / 3;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;

    while (Q--) {
        int64 l1, r1, l2, r2, t;
        cin >> l1 >> r1 >> l2 >> r2 >> t;

        int64 answer = 0;

        auto addRange = [&](int64 lo, int64 hi) {
            if (lo <= hi) answer += hi - lo + 1;
        };

        /*
         * Cows whose first jump has not happened yet satisfy x > floor(t / 3).
         *
         * If t < 2x, cow x is still at position x.
         */
        addRange(
            max(l1, max(l2, t / 2 + 1)),
            min(r1, r2)
        );

        /*
         * If 2x <= t < 3x, cow x has position 3x - 1 - t.
         */
        {
            int64 lo = max(l1, t / 3 + 1);
            int64 hi = min(r1, t / 2);

            int64 minX = (t + l2 + 3) / 3; // ceil((t + l2 + 1) / 3)
            int64 maxX = (t + r2 + 1) / 3;

            lo = max(lo, minX);
            hi = min(hi, maxX);
            addRange(lo, hi);
        }

        /*
         * For a cow x, define jump times:
         *   s_0 = 3x
         *   s_{k+1} = s_k + floor(s_k / 2) + 1.
         *
         * Let y_k = s_k + 2 and F(v) = floor(3v / 2).
         * Then y_{k+1} = F(y_k), y_0 = 3x + 2.
         *
         * At time t, phase k satisfies s_k <= t < s_{k+1},
         * and the cow's position is y_{k+1} - t - 3.
         */
        const int64 T = t + 2;
        const int64 L = t + l2 + 3;
        const int64 U = t + r2 + 3;

        // At iteration k:
        // hT = G^k(T), hU = G^k(U), hV = G^k(L - 1).
        int64 hT = T;
        int64 hU = U;
        int64 hV = L - 1;

        while (true) {
            int64 bT = maxId(hT);

            // The phase-ID intervals only shrink as k increases.
            if (bT < l1) break;

            int64 nextHT = G(hT);
            int64 nextHU = G(hU);
            int64 nextHV = G(hV);

            int64 nextBT = maxId(nextHT); // B_{k+1}(T)
            int64 nextBU = maxId(nextHU); // B_{k+1}(U)
            int64 nextBV = maxId(nextHV); // B_{k+1}(L - 1)

            int64 lo = max(l1, max(nextBT + 1, nextBV + 1));
            int64 hi = min(r1, min(bT, nextBU));

            addRange(lo, hi);

            hT = nextHT;
            hU = nextHU;
            hV = nextHV;
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Clue {
    int r, c, x; // x = 0 for '+', 1 for '-'
};

static int parity(int64 x) {
    int p = int(x % 2);
    return p < 0 ? p + 2 : p;
}

static int64 floorDiv2(int64 x) {
    if (x >= 0) return x / 2;
    return -((-x + 1) / 2);
}

static int64 ceilDiv2(int64 x) {
    return floorDiv2(x + 1);
}

// Number of integers in [lo, hi] with the requested parity.
static int64 countWithParity(int64 lo, int64 hi, int p) {
    if (lo > hi) return 0;
    int64 first = lo + (p - parity(lo) + 2) % 2;
    if (first > hi) return 0;
    return (hi - first) / 2 + 1;
}

// Count L in [l0,l1], H in [h0,h1], both of parity p,
// subject to H-L >= separation.
static int64 countPairs(int64 l0, int64 l1,
                        int64 h0, int64 h1,
                        int p, int64 separation) {
    if (l0 > l1 || h0 > h1) return 0;

    int64 il = ceilDiv2(l0 - p);
    int64 ir = floorDiv2(l1 - p);
    int64 jl = ceilDiv2(h0 - p);
    int64 jr = floorDiv2(h1 - p);
    if (il > ir || jl > jr) return 0;

    // L = p+2i, H = p+2j. We need j-i >= need.
    int64 need = (separation + 1) / 2;
    int64 result = 0;

    // i+need <= jl: every permissible j works.
    int64 fullEnd = min(ir, jl - need);
    if (il <= fullEnd) {
        int64 n = fullEnd - il + 1;
        result += n * (jr - jl + 1);
    }

    // jl < i+need <= jr: the number of j values decreases linearly.
    int64 st = max(il, jl - need + 1);
    int64 en = min(ir, jr - need);
    if (st <= en) {
        int64 n = en - st + 1;
        int64 A = jr - need + 1;
        result += A * n - (st + en) * n / 2;
    }

    return result;
}

static int checkerboardCount(const vector<Clue>& clues) {
    int answer = 0;
    for (int base = 0; base < 2; ++base) {
        bool ok = true;
        for (const auto& cl : clues) {
            int expected = base ^ parity(cl.r + cl.c);
            if (expected != cl.x) {
                ok = false;
                break;
            }
        }
        answer += ok;
    }
    return answer;
}

// orient = 0: q = r+c; orient = 1: q = r-c.
static int64 singleWallCount(int R, int C, int orient,
                             const vector<Clue>& clues) {
    int64 qmin = orient == 0 ? 2 : 1 - (int64)C;
    int64 qmax = orient == 0 ? R + (int64)C : R - 1;

    int64 answer = 0;
    for (int b = 0; b < 2; ++b) {
        int base = 1 - b;
        int64 lo = qmin, hi = qmax - 1;

        for (const auto& cl : clues) {
            int64 q = orient == 0 ? cl.r + (int64)cl.c
                                  : cl.r - (int64)cl.c;
            int requiredZ = cl.x ^ parity(q) ^ base;
            if (requiredZ) {
                lo = max(lo, q);       // q <= K
            } else {
                hi = min(hi, q - 1);   // q > K
            }
        }
        answer += countWithParity(lo, hi, b);
    }
    return answer;
}

static int64 doubleWallCount(int R, int C, int orient,
                             const vector<Clue>& clues) {
    int64 qmin = orient == 0 ? 2 : 1 - (int64)C;
    int64 qmax = orient == 0 ? R + (int64)C : R - 1;
    int64 separation = max(R, C);

    int64 answer = 0;

    for (int b = 0; b < 2; ++b) {
        int base = 1 - b;
        vector<int64> ones;
        ones.reserve(clues.size());

        bool hasZero = false;
        int64 minZero = 0, maxZero = 0;

        for (const auto& cl : clues) {
            int64 q = orient == 0 ? cl.r + (int64)cl.c
                                  : cl.r - (int64)cl.c;
            int requiredZ = cl.x ^ parity(q) ^ base;
            if (requiredZ) {
                ones.push_back(q);
            } else {
                if (!hasZero) {
                    hasZero = true;
                    minZero = maxZero = q;
                } else {
                    minZero = min(minZero, q);
                    maxZero = max(maxZero, q);
                }
            }
        }

        sort(ones.begin(), ones.end());

        if (hasZero) {
            // All zeroes lie strictly between L and H. No one can lie in
            // their bounding interval; lower and upper ones force bounds.
            int64 l0 = qmin, l1 = minZero - 1;
            int64 h0 = maxZero + 1, h1 = qmax;

            auto it = lower_bound(ones.begin(), ones.end(), minZero);
            if (it != ones.begin()) {
                l0 = max(l0, *prev(it));
            }

            bool bad = (it != ones.end() && *it <= maxZero);
            if (bad) continue;

            auto jt = upper_bound(ones.begin(), ones.end(), maxZero);
            if (jt != ones.end()) {
                h1 = min(h1, *jt);
            }

            answer += countPairs(l0, l1, h0, h1, b, separation);
        } else {
            // The open interval (L,H) must contain no coordinate of a one.
            // Thus it lies in one of the gaps between consecutive such
            // coordinates. Different gaps count disjoint sets of pairs.
            ones.erase(unique(ones.begin(), ones.end()), ones.end());
            int k = int(ones.size());

            for (int t = 0; t <= k; ++t) {
                int64 l0 = qmin, l1 = qmax;
                int64 h0 = qmin, h1 = qmax;

                if (t > 0) {
                    int64 a = ones[t - 1];
                    l0 = max(l0, a);
                    h0 = max(h0, a + 1);
                }
                if (t < k) {
                    int64 bnd = ones[t];
                    l1 = min(l1, bnd - 1);
                    h1 = min(h1, bnd);
                }

                answer += countPairs(l0, l1, h0, h1, b, separation);
            }
        }
    }

    return answer;
}

static bool validLine(const vector<int>& a) {
    int plusRuns = 0;
    for (int i = 0; i < int(a.size()); ++i) {
        if (i > 0 && a[i - 1] == 1 && a[i] == 1) return false;
        if (i > 0 && a[i - 1] == 0 && a[i] == 0) ++plusRuns;
    }
    return plusRuns <= 1;
}

static int solveTwoByTwo(const vector<Clue>& clues) {
    int answer = 0;
    for (int mask = 0; mask < 16; ++mask) {
        vector<int> x(4);
        for (int i = 0; i < 4; ++i) x[i] = (mask >> i) & 1;

        bool ok = true;
        for (const auto& cl : clues) {
            int idx = (cl.r - 1) * 2 + (cl.c - 1);
            if (x[idx] != cl.x) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;

        ok &= validLine({x[0], x[1]});
        ok &= validLine({x[2], x[3]});
        ok &= validLine({x[0], x[2]});
        ok &= validLine({x[1], x[3]});
        answer += ok;
    }
    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int R, C, X;
        cin >> R >> C >> X;

        vector<Clue> clues(X);
        for (auto& cl : clues) {
            char ch;
            cin >> ch >> cl.r >> cl.c;
            cl.x = (ch == '-');
        }

        if (R == 2 && C == 2) {
            cout << solveTwoByTwo(clues) << '\n';
            continue;
        }

        int64 answer = checkerboardCount(clues);

        if (min(R, C) == 1) {
            // The two diagonal orientations coincide on a one-dimensional
            // grid, so only one is counted.
            answer += singleWallCount(R, C, 0, clues);
        } else {
            for (int orient = 0; orient < 2; ++orient) {
                answer += singleWallCount(R, C, orient, clues);
                answer += doubleWallCount(R, C, orient, clues);
            }
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Clue {
    int r, c, p;
};

struct FamilyData {
    bool hasO[2] = {false, false};
    bool hasI[2] = {false, false};
    int64 maxO[2] = {0, 0};
    int64 minI[2] = {0, 0};
    int64 maxI[2] = {0, 0};
    vector<int64> valuesO[2];
};

static int parity(int64 x) {
    x %= 2;
    if (x < 0) x += 2;
    return static_cast<int>(x);
}

static int64 countWithParity(int64 lo, int64 hi, int p) {
    if (lo > hi) return 0;
    if (parity(lo) != p) ++lo;
    if (lo > hi) return 0;
    return (hi - lo) / 2 + 1;
}

static FamilyData buildData(const vector<Clue>& clues, bool useSum) {
    FamilyData d;

    for (const Clue& clue : clues) {
        int64 t = useSum ? int64(clue.r) + clue.c
                         : int64(clue.c) - clue.r;
        int q = parity(t + clue.p);

        int o = q;
        if (!d.hasO[o]) {
            d.hasO[o] = true;
            d.maxO[o] = t;
        } else {
            d.maxO[o] = max(d.maxO[o], t);
        }
        d.valuesO[o].push_back(t);

        int in = 1 - q;
        if (!d.hasI[in]) {
            d.hasI[in] = true;
            d.minI[in] = d.maxI[in] = t;
        } else {
            d.minI[in] = min(d.minI[in], t);
            d.maxI[in] = max(d.maxI[in], t);
        }
    }

    for (int p = 0; p < 2; ++p) {
        sort(d.valuesO[p].begin(), d.valuesO[p].end());
    }
    return d;
}

// One-transition grids: parameter k lies in [A, B-1].
static int64 countHalfplanes(int64 A, int64 B, const FamilyData& d) {
    int64 result = 0;

    for (int p = 0; p < 2; ++p) {
        int64 lo = A;
        int64 hi = B - 1;

        if (d.hasO[p]) lo = max(lo, d.maxO[p]);
        if (d.hasI[p]) hi = min(hi, d.minI[p] - 1);

        result += countWithParity(lo, hi, p);
    }
    return result;
}

// Two-transition grids: parameters l,u satisfy A <= l < u <= B,
// u-l >= M, and l,u have the same parity.
static int64 countBands(int64 A, int64 B, int64 M, const FamilyData& d) {
    int64 result = 0;
    int64 lastL = B - M;
    if (lastL < A) return 0;

    for (int p = 0; p < 2; ++p) {
        int64 hiL = lastL;
        if (d.hasI[p]) hiL = min(hiL, d.minI[p] - 1);

        int64 l = A;
        if (parity(l) != p) ++l;

        const vector<int64>& v = d.valuesO[p];
        size_t ptr = 0;

        for (; l <= hiL; l += 2) {
            while (ptr < v.size() && v[ptr] <= l) ++ptr;

            int64 loU = l + M;
            if (d.hasI[p]) loU = max(loU, d.maxI[p] + 1);

            int64 hiU = B;
            if (ptr < v.size()) hiU = min(hiU, v[ptr]);

            result += countWithParity(loU, hiU, p);
        }
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int R, C, X;
        cin >> R >> C >> X;

        vector<Clue> clues(X);
        for (Clue& clue : clues) {
            char v;
            cin >> v >> clue.r >> clue.c;
            clue.p = (v == '-');
        }

        int pureCount = 0;
        for (int p = 0; p < 2; ++p) {
            bool ok = true;
            for (const Clue& clue : clues) {
                if (parity(int64(p) + clue.r + clue.c) != clue.p) {
                    ok = false;
                    break;
                }
            }
            pureCount += ok;
        }

        FamilyData differenceData = buildData(clues, false);
        FamilyData sumData = buildData(clues, true);

        const int64 diffA = 1LL - R;
        const int64 diffB = int64(C) - 1;
        const int64 sumA = 2;
        const int64 sumB = int64(R) + C;
        const int64 M = max(R, C);

        int64 answer = pureCount;
        answer += countHalfplanes(diffA, diffB, differenceData);

        if (min(R, C) > 1) {
            answer += countHalfplanes(sumA, sumB, sumData);

            // In the 2x2 case these two bands describe the same all-plus grid.
            if (!(R == 2 && C == 2)) {
                answer += countBands(diffA, diffB, M, differenceData);
            }
            answer += countBands(sumA, sumB, M, sumData);
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Memory {
    int r, c;
    int value;
    int parity;
    array<int, 4> dist;
};

static int64 solveOneDimensional(int n, const vector<Memory>& memories, bool byRow) {
    vector<int> fixed(n + 1, 0);
    for (const auto& m : memories) {
        int pos = byRow ? m.r : m.c;
        fixed[pos] = m.value;
    }

    // State: last value, and whether the unique possible "++" has been used.
    int64 dp[2][2] = {};
    auto index = [](int x) { return x == 1 ? 1 : 0; };

    for (int v : {-1, 1}) {
        if (fixed[1] == 0 || fixed[1] == v) {
            dp[index(v)][0] = 1;
        }
    }

    for (int pos = 2; pos <= n; ++pos) {
        int64 ndp[2][2] = {};
        for (int last = 0; last < 2; ++last) {
            int lastValue = last ? 1 : -1;
            for (int used = 0; used < 2; ++used) {
                int64 ways = dp[last][used];
                if (!ways) continue;
                for (int v : {-1, 1}) {
                    if (fixed[pos] != 0 && fixed[pos] != v) continue;
                    if (v != lastValue) {
                        ndp[index(v)][used] += ways;
                    } else if (v == 1 && used == 0) {
                        ndp[1][1] += ways;
                    }
                }
            }
        }
        memcpy(dp, ndp, sizeof(dp));
    }

    int64 answer = 0;
    for (int last = 0; last < 2; ++last) {
        for (int used = 0; used < 2; ++used) {
            answer += dp[last][used];
        }
    }
    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int64 R, C;
        int X;
        cin >> R >> C >> X;

        vector<Memory> memories(X);
        for (int i = 0; i < X; ++i) {
            char ch;
            int r, c;
            cin >> ch >> r >> c;
            memories[i].r = r;
            memories[i].c = c;
            memories[i].value = (ch == '+' ? 1 : -1);
            memories[i].parity = ((r + c) % 2 == 0 ? 1 : -1);
        }

        if (R == 1 || C == 1) {
            int n = (int)max(R, C);
            bool byRow = (C == 1);
            cout << solveOneDimensional(n, memories, byRow) << '\n';
            continue;
        }

        const int64 cells = R * C;

        // A[k] = number of cells at Manhattan distance < k from a corner.
        // Only areas at most cells/2 are needed for the canonical representation.
        vector<int64> area(1, 0);
        const int maxPossibleK = (int)(R + C - 1);
        for (int k = 1; k <= maxPossibleK; ++k) {
            int d = k - 1;
            int64 lo = max<int64>(0, (int64)d - (C - 1));
            int64 hi = min<int64>(R - 1, d);
            int64 diagonal = (hi >= lo ? hi - lo + 1 : 0);
            int64 nextArea = area.back() + diagonal;
            if (2 * nextArea > cells) break;
            area.push_back(nextArea);
        }

        const int Kmax = (int)area.size() - 1;

        // Corner order: top-left, top-right, bottom-left, bottom-right.
        vector<vector<pair<int, int>>> ordered(4);
        for (int i = 0; i < X; ++i) {
            auto& m = memories[i];
            int64 r = m.r, c = m.c;
            m.dist[0] = (int)((r - 1) + (c - 1));
            m.dist[1] = (int)((r - 1) + (C - c));
            m.dist[2] = (int)((R - r) + (c - 1));
            m.dist[3] = (int)((R - r) + (C - c));

            for (int corner = 0; corner < 4; ++corner) {
                if (m.dist[corner] < Kmax) {
                    ordered[corner].push_back({m.dist[corner], i});
                }
            }
        }
        for (int corner = 0; corner < 4; ++corner) {
            sort(ordered[corner].begin(), ordered[corner].end());
        }

        // A triangle of size k at a corner requires a particular checkerboard phase.
        int factor[4];
        factor[0] = 1;
        factor[1] = (C % 2 == 1 ? 1 : -1);
        factor[2] = (R % 2 == 1 ? 1 : -1);
        factor[3] = ((R + C) % 2 == 0 ? 1 : -1);

        int64 answer = 0;
        const int minDim = (int)min(R, C);
        const int doubleLimit = min(Kmax, minDim - 1);

        for (int base : {1, -1}) {
            int mismatch = 0;
            vector<int> weight(X);
            for (int i = 0; i < X; ++i) {
                int baseValue = base * memories[i].parity;
                if (baseValue != memories[i].value) {
                    ++mismatch;
                    weight[i] = -1;
                } else {
                    weight[i] = 1;
                }
            }

            // weights[corner][k]: total adjustment caused by flipped remembered cells.
            vector<vector<int>> weights(4, vector<int>(Kmax + 1, 0));
            for (int corner = 0; corner < 4; ++corner) {
                int ptr = 0;
                const auto& v = ordered[corner];
                for (int k = 1; k <= Kmax; ++k) {
                    int sum = weights[corner][k - 1];
                    while (ptr < (int)v.size() && v[ptr].first < k) {
                        sum += weight[v[ptr].second];
                        ++ptr;
                    }
                    weights[corner][k] = sum;
                }
            }

            // Unmodified checkerboard.
            if (mismatch == 0) ++answer;

            // One flipped corner triangle.
            for (int corner = 0; corner < 4; ++corner) {
                for (int k = 1; k <= Kmax; ++k) {
                    int sizeSign = (k % 2 == 0 ? 1 : -1);
                    if (factor[corner] * sizeSign != base) continue;
                    if (2 * area[k] == cells && base == -1) continue;
                    if (mismatch + weights[corner][k] == 0) {
                        ++answer;
                    }
                }
            }

            // Two triangles at opposite corners. Their sizes must have disjoint supports.
            const pair<int, int> oppositePairs[2] = {{0, 3}, {1, 2}};
            for (auto [first, second] : oppositePairs) {
                if (doubleLimit < 1) continue;

                int firstParity = (base * factor[first] == -1 ? 1 : 0);
                int secondParity = (base * factor[second] == -1 ? 1 : 0);

                unordered_map<int, vector<int>> positions;
                positions.reserve((size_t)min<int64>(doubleLimit + 1, 2LL * X + 16));

                int secondStart = (secondParity == 1 ? 1 : 2);
                for (int l = secondStart; l <= doubleLimit; l += 2) {
                    positions[weights[second][l]].push_back(l);
                }

                int firstStart = (firstParity == 1 ? 1 : 2);
                for (int k = firstStart; k <= doubleLimit; k += 2) {
                    int maxL = min(doubleLimit, minDim - k);
                    if (maxL < 1) continue;

                    // Binary search the largest size satisfying the canonical area rule.
                    int lo = 1, hi = maxL, best = 0;
                    while (lo <= hi) {
                        int mid = (lo + hi) / 2;
                        int64 twiceArea = 2 * (area[k] + area[mid]);
                        bool ok = (base == 1 ? twiceArea <= cells : twiceArea < cells);
                        if (ok) {
                            best = mid;
                            lo = mid + 1;
                        } else {
                            hi = mid - 1;
                        }
                    }
                    if (best == 0) continue;

                    int wanted = -mismatch - weights[first][k];
                    auto it = positions.find(wanted);
                    if (it == positions.end()) continue;

                    const auto& vec = it->second;
                    answer += (int64)(upper_bound(vec.begin(), vec.end(), best) - vec.begin());
                }
            }
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Clue {
    int r, c, x; // x = 0 for '+', 1 for '-'
};

static int parity(int64 x) {
    int p = int(x % 2);
    return p < 0 ? p + 2 : p;
}

static int64 floorDiv2(int64 x) {
    if (x >= 0) return x / 2;
    return -((-x + 1) / 2);
}

static int64 ceilDiv2(int64 x) {
    return floorDiv2(x + 1);
}

// Number of integers in [lo, hi] with the requested parity.
static int64 countWithParity(int64 lo, int64 hi, int p) {
    if (lo > hi) return 0;
    int64 first = lo + (p - parity(lo) + 2) % 2;
    if (first > hi) return 0;
    return (hi - first) / 2 + 1;
}

// Count L in [l0,l1], H in [h0,h1], both of parity p,
// subject to H-L >= separation.
static int64 countPairs(int64 l0, int64 l1,
                        int64 h0, int64 h1,
                        int p, int64 separation) {
    if (l0 > l1 || h0 > h1) return 0;

    int64 il = ceilDiv2(l0 - p);
    int64 ir = floorDiv2(l1 - p);
    int64 jl = ceilDiv2(h0 - p);
    int64 jr = floorDiv2(h1 - p);
    if (il > ir || jl > jr) return 0;

    // L = p+2i, H = p+2j. We need j-i >= need.
    int64 need = (separation + 1) / 2;
    int64 result = 0;

    // i+need <= jl: every permissible j works.
    int64 fullEnd = min(ir, jl - need);
    if (il <= fullEnd) {
        int64 n = fullEnd - il + 1;
        result += n * (jr - jl + 1);
    }

    // jl < i+need <= jr: the number of j values decreases linearly.
    int64 st = max(il, jl - need + 1);
    int64 en = min(ir, jr - need);
    if (st <= en) {
        int64 n = en - st + 1;
        int64 A = jr - need + 1;
        result += A * n - (st + en) * n / 2;
    }

    return result;
}

static int checkerboardCount(const vector<Clue>& clues) {
    int answer = 0;
    for (int base = 0; base < 2; ++base) {
        bool ok = true;
        for (const auto& cl : clues) {
            int expected = base ^ parity(cl.r + cl.c);
            if (expected != cl.x) {
                ok = false;
                break;
            }
        }
        answer += ok;
    }
    return answer;
}

// orient = 0: q = r+c; orient = 1: q = r-c.
static int64 singleWallCount(int R, int C, int orient,
                             const vector<Clue>& clues) {
    int64 qmin = orient == 0 ? 2 : 1 - (int64)C;
    int64 qmax = orient == 0 ? R + (int64)C : R - 1;

    int64 answer = 0;
    for (int b = 0; b < 2; ++b) {
        int base = 1 - b;
        int64 lo = qmin, hi = qmax - 1;

        for (const auto& cl : clues) {
            int64 q = orient == 0 ? cl.r + (int64)cl.c
                                  : cl.r - (int64)cl.c;
            int requiredZ = cl.x ^ parity(q) ^ base;
            if (requiredZ) {
                lo = max(lo, q);       // q <= K
            } else {
                hi = min(hi, q - 1);   // q > K
            }
        }
        answer += countWithParity(lo, hi, b);
    }
    return answer;
}

static int64 doubleWallCount(int R, int C, int orient,
                             const vector<Clue>& clues) {
    int64 qmin = orient == 0 ? 2 : 1 - (int64)C;
    int64 qmax = orient == 0 ? R + (int64)C : R - 1;
    int64 separation = max(R, C);

    int64 answer = 0;

    for (int b = 0; b < 2; ++b) {
        int base = 1 - b;
        vector<int64> ones;
        ones.reserve(clues.size());

        bool hasZero = false;
        int64 minZero = 0, maxZero = 0;

        for (const auto& cl : clues) {
            int64 q = orient == 0 ? cl.r + (int64)cl.c
                                  : cl.r - (int64)cl.c;
            int requiredZ = cl.x ^ parity(q) ^ base;
            if (requiredZ) {
                ones.push_back(q);
            } else {
                if (!hasZero) {
                    hasZero = true;
                    minZero = maxZero = q;
                } else {
                    minZero = min(minZero, q);
                    maxZero = max(maxZero, q);
                }
            }
        }

        sort(ones.begin(), ones.end());

        if (hasZero) {
            // All zeroes lie strictly between L and H. No one can lie in
            // their bounding interval; lower and upper ones force bounds.
            int64 l0 = qmin, l1 = minZero - 1;
            int64 h0 = maxZero + 1, h1 = qmax;

            auto it = lower_bound(ones.begin(), ones.end(), minZero);
            if (it != ones.begin()) {
                l0 = max(l0, *prev(it));
            }

            bool bad = (it != ones.end() && *it <= maxZero);
            if (bad) continue;

            auto jt = upper_bound(ones.begin(), ones.end(), maxZero);
            if (jt != ones.end()) {
                h1 = min(h1, *jt);
            }

            answer += countPairs(l0, l1, h0, h1, b, separation);
        } else {
            // The open interval (L,H) must contain no coordinate of a one.
            // Thus it lies in one of the gaps between consecutive such
            // coordinates. Different gaps count disjoint sets of pairs.
            ones.erase(unique(ones.begin(), ones.end()), ones.end());
            int k = int(ones.size());

            for (int t = 0; t <= k; ++t) {
                int64 l0 = qmin, l1 = qmax;
                int64 h0 = qmin, h1 = qmax;

                if (t > 0) {
                    int64 a = ones[t - 1];
                    l0 = max(l0, a);
                    h0 = max(h0, a + 1);
                }
                if (t < k) {
                    int64 bnd = ones[t];
                    l1 = min(l1, bnd - 1);
                    h1 = min(h1, bnd);
                }

                answer += countPairs(l0, l1, h0, h1, b, separation);
            }
        }
    }

    return answer;
}

static bool validLine(const vector<int>& a) {
    int plusRuns = 0;
    for (int i = 0; i < int(a.size()); ++i) {
        if (i > 0 && a[i - 1] == 1 && a[i] == 1) return false;
        if (i > 0 && a[i - 1] == 0 && a[i] == 0) ++plusRuns;
    }
    return plusRuns <= 1;
}

static int solveTwoByTwo(const vector<Clue>& clues) {
    int answer = 0;
    for (int mask = 0; mask < 16; ++mask) {
        vector<int> x(4);
        for (int i = 0; i < 4; ++i) x[i] = (mask >> i) & 1;

        bool ok = true;
        for (const auto& cl : clues) {
            int idx = (cl.r - 1) * 2 + (cl.c - 1);
            if (x[idx] != cl.x) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;

        ok &= validLine({x[0], x[1]});
        ok &= validLine({x[2], x[3]});
        ok &= validLine({x[0], x[2]});
        ok &= validLine({x[1], x[3]});
        answer += ok;
    }
    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int R, C, X;
        cin >> R >> C >> X;

        vector<Clue> clues(X);
        for (auto& cl : clues) {
            char ch;
            cin >> ch >> cl.r >> cl.c;
            cl.x = (ch == '-');
        }

        if (R == 2 && C == 2) {
            cout << solveTwoByTwo(clues) << '\n';
            continue;
        }

        int64 answer = checkerboardCount(clues);

        if (min(R, C) == 1) {
            // The two diagonal orientations coincide on a one-dimensional
            // grid, so only one is counted.
            answer += singleWallCount(R, C, 0, clues);
        } else {
            for (int orient = 0; orient < 2; ++orient) {
                answer += singleWallCount(R, C, orient, clues);
                answer += doubleWallCount(R, C, orient, clues);
            }
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Clue {
    char v;
    int r, c;
};

static long long countOdd(long long l, long long r) {
    if (l > r) return 0;
    if (l % 2 == 0) ++l;
    if (l > r) return 0;
    return (r - l) / 2 + 1;
}

static long long countParity(int l, int r, int parity) {
    if (l > r) return 0;
    int first = l;
    if ((first & 1) != parity) ++first;
    if (first > r) return 0;
    return (r - first) / 2 + 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int R, C, X;
        cin >> R >> C >> X;

        vector<Clue> clues(X);
        for (auto &cl : clues) {
            cin >> cl.v >> cl.r >> cl.c;
        }

        if (R == 1 || C == 1) {
            const int N = (R == 1 ? C : R);

            // The two strictly alternating strings.
            bool alternatingOK[2] = {true, true};

            // Candidates with their unique ++ defect starting at position j.
            // Process candidates separately according to the parity of j.
            int lower[2] = {1, 1};
            int upper[2] = {N - 1, N - 1};

            for (const auto &cl : clues) {
                const int i = (R == 1 ? cl.c : cl.r);
                const bool desiredPlus = (cl.v == '+');
                const int minus = (cl.v == '-');

                const bool plusInFirst = (i % 2 == 1);
                if ((alternatingOK[0] || alternatingOK[1])) {
                    if ((plusInFirst != desiredPlus)) alternatingOK[0] = false;
                    if ((!plusInFirst != desiredPlus)) alternatingOK[1] = false;
                }

                const int goodLeftParity = (i & 1) ^ minus;
                const int goodRightParity = ((i - 1) & 1) ^ minus;

                for (int parity = 0; parity < 2; ++parity) {
                    if (parity != goodLeftParity) {
                        upper[parity] = min(upper[parity], i - 1);
                    }
                    if (parity != goodRightParity) {
                        lower[parity] = max(lower[parity], i);
                    }
                }
            }

            long long answer = 0;
            answer += alternatingOK[0];
            answer += alternatingOK[1];

            for (int parity = 0; parity < 2; ++parity) {
                answer += countParity(lower[parity], upper[parity], parity);
            }

            cout << answer << '\n';
            continue;
        }

        // Write a cell as a base checkerboard value flipped according to z.
        // A cell is '+' exactly when z == ((r+c)&1).
        // Every non-checkerboard solution, except all-plus on 2x2, belongs
        // to one of four threshold families in s=r+c or d=c-r.
        bool checkerOK[2] = {true, true};
        bool allPlus = true;

        const long long M = (long long)R + C;
        const long long dMin = 1LL - C;
        const long long dMax = (long long)R - 1;

        // z = 1 iff s >= k.
        long long spL = 3, spR = M;
        // z = 1 iff s <= k.
        long long smL = 3, smR = M - 1;
        // z = 1 iff d >= k.
        long long dpL = dMin + 1, dpR = dMax;
        // z = 1 iff d <= k.
        long long dmL = dMin, dmR = dMax - 1;

        for (const auto &cl : clues) {
            const int parity = (cl.r + cl.c) & 1;
            const int minus = (cl.v == '-');
            const int requiredZ = parity ^ minus;

            if (requiredZ != 0) checkerOK[0] = false;
            if (requiredZ != 1) checkerOK[1] = false;
            if (minus) allPlus = false;

            const long long s = (long long)cl.r + cl.c;
            const long long d = (long long)cl.c - cl.r;

            if (requiredZ == 1) spR = min(spR, s);
            else                spL = max(spL, s + 1);

            if (requiredZ == 1) smL = max(smL, s);
            else                smR = min(smR, s - 1);

            if (requiredZ == 1) dpR = min(dpR, d);
            else                dpL = max(dpL, d + 1);

            if (requiredZ == 1) dmL = max(dmL, d);
            else                dmR = min(dmR, d - 1);
        }

        long long answer = 0;
        answer += checkerOK[0];
        answer += checkerOK[1];
        answer += countOdd(spL, spR);
        answer += countOdd(smL, smR);
        answer += countOdd(dpL, dpR);
        answer += countOdd(dmL, dmR);

        if (R == 2 && C == 2 && allPlus) {
            ++answer;
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Clue {
    int r, c, val;
};

struct Solver {
    int R, C, N;
    vector<Clue> clues;
    int cornerParity[4];

    static int paritySign(int x) {
        return (x & 1) ? -1 : 1;
    }

    static long long countWithParity(int L, int U, int par) {
        if (L > U) return 0;
        int first = L;
        if ((first & 1) != par) ++first;
        if (first > U) return 0;
        return (U - first) / 2 + 1;
    }

    int distanceToCorner(int q, const Clue &cl) const {
        int r = cl.r, c = cl.c;
        if (q == 0) return r + c - 1;                 // top-left
        if (q == 1) return r + C - c;                 // top-right
        if (q == 2) return R + C - r - c + 1;         // bottom-right
        return R - r + c;                             // bottom-left
    }

    long long countPlain() const {
        long long result = 0;
        for (int base : {-1, 1}) {
            bool ok = true;
            for (const Clue &cl : clues) {
                int expected = base * paritySign(cl.r + cl.c);
                if (expected != cl.val) {
                    ok = false;
                    break;
                }
            }
            result += ok;
        }
        return result;
    }

    long long countSingle(int q) const {
        int L[2] = {1, 1};
        int U[2] = {N, N};

        for (const Clue &cl : clues) {
            int d = distanceToCorner(q, cl);
            int s = cl.val * paritySign(cl.r + cl.c) * cornerParity[q];
            int outsideParity = (s == 1 ? 0 : 1);

            for (int par = 0; par < 2; ++par) {
                if (par == outsideParity) {
                    // The cell must be outside the triangle.
                    U[par] = min(U[par], d - 1);
                } else {
                    // The cell must be inside the triangle.
                    L[par] = max(L[par], d);
                }
            }
        }

        long long result = 0;
        for (int par = 0; par < 2; ++par)
            result += countWithParity(L[par], U[par], par);
        return result;
    }

    long long countPair(int diagonal) const {
        const int q1 = diagonal;       // 0: TL+BR, 1: TR+BL
        const int q2 = diagonal + 2;
        const int sizeParityChange = (R + C) & 1;
        long long result = 0;

        for (int par = 0; par < 2; ++par) {
            int maxK = N - 1;
            int maxL = N;

            vector<int> lowBucket(N + 3, 1);
            vector<int> upBucket(N + 3, N);

            for (const Clue &cl : clues) {
                int d1 = distanceToCorner(q1, cl);
                int d2 = distanceToCorner(q2, cl);
                int s = cl.val * paritySign(cl.r + cl.c) * cornerParity[q1];
                int outsideParity = (s == 1 ? 0 : 1);

                if (par == outsideParity) {
                    // The cell must be outside both triangles.
                    maxK = min(maxK, d1 - 1);
                    maxL = min(maxL, d2 - 1);
                } else {
                    // The cell must be inside exactly one triangle.
                    int K = min(d1, N + 1);
                    int lowRequirement = min(d2, N + 1);
                    int upRequirement = min(d2 - 1, N);
                    lowBucket[K] = max(lowBucket[K], lowRequirement);
                    upBucket[K] = min(upBucket[K], upRequirement);
                }
            }

            // futureLow[k] is the maximum lower bound among constraints
            // whose first-triangle threshold is greater than k.
            vector<int> futureLow(N + 3, 1);
            for (int k = N; k >= 1; --k)
                futureLow[k] = max(lowBucket[k + 1], futureLow[k + 1]);

            int secondParity = (par + sizeParityChange) & 1;
            int prefixUp = N;

            for (int k = 1; k <= maxK; ++k) {
                prefixUp = min(prefixUp, upBucket[k]);
                if ((k & 1) != par) continue;

                int low = max(1, futureLow[k]);
                int up = min(maxL, N - k);
                up = min(up, prefixUp);
                result += countWithParity(low, up, secondParity);
            }
        }

        return result;
    }

    bool matchesSingle(int q, int k) const {
        int base = cornerParity[q] * ((k & 1) ? -1 : 1);
        for (const Clue &cl : clues) {
            int expected = base * paritySign(cl.r + cl.c);
            if (k >= distanceToCorner(q, cl)) expected = -expected;
            if (expected != cl.val) return false;
        }
        return true;
    }

    bool matchesPair(int q, int k, int l) const {
        int base = cornerParity[q] * ((k & 1) ? -1 : 1);
        for (const Clue &cl : clues) {
            int expected = base * paritySign(cl.r + cl.c);
            bool inside = false;
            if (k >= distanceToCorner(q, cl)) inside = !inside;
            if (l >= distanceToCorner(q + 2, cl)) inside = !inside;
            if (inside) expected = -expected;
            if (expected != cl.val) return false;
        }
        return true;
    }

    long long solve2D() {
        cornerParity[0] = paritySign(1 + 1);
        cornerParity[1] = paritySign(1 + C);
        cornerParity[2] = paritySign(R + C);
        cornerParity[3] = paritySign(R + 1);

        long long answer = countPlain();
        for (int q = 0; q < 4; ++q)
            answer += countSingle(q);
        answer += countPair(0);
        answer += countPair(1);

        // Remove representations of the same grid with opposite baseline.
        if (R == C) {
            for (int q = 0; q < 2; ++q) {
                if (matchesSingle(q, N)) --answer;
                if (matchesSingle(q, N - 1)) --answer;
            }
        } else if (abs(R - C) == 1) {
            for (int q = 0; q < 2; ++q) {
                if (matchesSingle(q, N)) --answer;
            }
        }

        // The all-plus 2 by 2 grid has one further duplicate representation.
        if (R == 2 && C == 2 && matchesPair(0, 1, 1))
            --answer;

        return answer;
    }
};

long long solveOneDimensional(int length, const vector<pair<int, int>> &clues) {
    long long answer = 0;

    // Perfectly alternating strings.
    for (int start : {-1, 1}) {
        bool ok = true;
        for (auto [pos, val] : clues) {
            int expected = start * Solver::paritySign(pos - 1);
            if (expected != val) {
                ok = false;
                break;
            }
        }
        answer += ok;
    }

    if (length == 1) return answer;

    // Strings whose only ++ pair starts at position d.
    int L[2] = {1, 1};
    int U[2] = {length - 1, length - 1};

    for (auto [pos, val] : clues) {
        int p = Solver::paritySign(pos);
        int requiredParity = (val * p == 1 ? 0 : 1);

        for (int par = 0; par < 2; ++par) {
            if (par == requiredParity)
                L[par] = max(L[par], pos);       // d >= pos
            else
                U[par] = min(U[par], pos - 1);   // d < pos
        }
    }

    for (int par = 0; par < 2; ++par)
        answer += Solver::countWithParity(L[par], U[par], par);

    return answer;
}

