        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Clue {
    int r, c, val; // val: +1 for '+', -1 for '-'
};

// 1D automaton states:
// 0: start A
// 1: B = {0,1}
// 2: C = {-1,0}
// 3: D = {0,1,2}
// 4: E = {-1,0,1}
int transState[5][2] = {
    {1, 2},  // A: '+' -> B, '-' -> C
    {3, 2},  // B
    {1, -1}, // C
    {-1, 4}, // D
    {3, -1}  // E
};

long long countParity(int L, int U, int p) {
    if (L > U) return 0;
    auto parity = [](int x) {
        int m = x % 2;
        if (m < 0) m += 2;
        return m;
    };
    while (parity(L) != p) ++L;
    while (parity(U) != p) --U;
    if (L > U) return 0;
    return (U - L) / 2 + 1;
}

long long solve1D(int R, int C, const vector<Clue>& clues) {
    int N = (R == 1 ? C : R);
    vector<int> clue(N + 1, 0); // 0 unknown, 1 plus, -1 minus

    for (auto &cl : clues) {
        int pos = (R == 1 ? cl.c : cl.r);
        clue[pos] = cl.val;
    }

    long long dp[5] = {0};
    dp[0] = 1;

    for (int pos = 1; pos <= N; ++pos) {
        long long ndp[5] = {0};
        int mask = 3;
        if (clue[pos] == 1) mask = 1;
        else if (clue[pos] == -1) mask = 2;

        for (int st = 0; st < 5; ++st) {
            if (!dp[st]) continue;

            if (mask & 1) { // plus
                int ns = transState[st][0];
                if (ns != -1) ndp[ns] += dp[st];
            }
            if (mask & 2) { // minus
                int ns = transState[st][1];
                if (ns != -1) ndp[ns] += dp[st];
            }
        }

        for (int i = 0; i < 5; ++i) dp[i] = ndp[i];
    }

    long long ans = 0;
    for (int st = 1; st < 5; ++st) ans += dp[st];
    return ans;
}

long long count2xC(int C, const vector<int>& top, const vector<int>& bot) {
    long long dp[25] = {0};
    dp[0] = 1; // state (start, start)

    for (int pos = 1; pos <= C; ++pos) {
        long long ndp[25] = {0};

        int maskTop = 3;
        if (top[pos] == 1) maskTop = 1;
        else if (top[pos] == -1) maskTop = 2;

        int maskBot = 3;
        if (bot[pos] == 1) maskBot = 1;
        else if (bot[pos] == -1) maskBot = 2;

        for (int s1 = 0; s1 < 5; ++s1) {
            for (int s2 = 0; s2 < 5; ++s2) {
                long long cur = dp[s1 * 5 + s2];
                if (!cur) continue;

                for (int c1 = 0; c1 < 2; ++c1) {
                    if (!(maskTop & (1 << c1))) continue;
                    int ns1 = transState[s1][c1];
                    if (ns1 == -1) continue;

                    for (int c2 = 0; c2 < 2; ++c2) {
                        if (!(maskBot & (1 << c2))) continue;

                        // A column cannot be "--"
                        if (c1 == 1 && c2 == 1) continue;

                        int ns2 = transState[s2][c2];
                        if (ns2 == -1) continue;

                        ndp[ns1 * 5 + ns2] += cur;
                    }
                }
            }
        }

        for (int i = 0; i < 25; ++i) dp[i] = ndp[i];
    }

    long long ans = 0;
    for (int i = 0; i < 25; ++i) ans += dp[i];
    return ans;
}

long long countCutType(int R, int C, const vector<Clue>& clues, bool isSum) {
    int L0, U0;
    if (isSum) {
        L0 = 2;
        U0 = R + C - 1;
    } else {
        L0 = 1 - C;
        U0 = R - 2;
    }

    int low[2] = {L0, L0};
    int high[2] = {U0, U0};

    for (auto &cl : clues) {
        int s = isSum ? (cl.r + cl.c) : (cl.r - cl.c);
        int B = ((cl.r + cl.c) & 1) ? -1 : 1;
        bool targetPlus = (cl.val * B == 1);

        for (int p = 0; p < 2; ++p) {
            bool evenK = (p == 0);
            bool needLe = (evenK == targetPlus);

            if (needLe) {
                // Need s <= K, i.e. K >= s
                low[p] = max(low[p], s);
            } else {
                // Need s > K, i.e. K <= s - 1
                high[p] = min(high[p], s - 1);
            }
        }
    }

    long long ans = 0;
    for (int p = 0; p < 2; ++p) {
        int L = max(L0, low[p]);
        int U = min(U0, high[p]);
        ans += countParity(L, U, p);
    }
    return ans;
}

long long solveTemplates(int R, int C, const vector<Clue>& clues) {
    long long ans = 0;

    bool okPlus = true;
    bool okMinus = true;

    for (auto &cl : clues) {
        int B = ((cl.r + cl.c) & 1) ? -1 : 1;

        if (cl.val != B) okPlus = false;
        if (cl.val != -B) okMinus = false;
    }

    ans += (okPlus ? 1 : 0);
    ans += (okMinus ? 1 : 0);

    ans += countCutType(R, C, clues, true);
    ans += countCutType(R, C, clues, false);

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int R, C, X;
        cin >> R >> C >> X;

        vector<Clue> clues;
        clues.reserve(X);

        for (int i = 0; i < X; ++i) {
            string v;
            int r, c;
            cin >> v >> r >> c;
            int val = (v[0] == '+' ? 1 : -1);
            clues.push_back({r, c, val});
        }

        long long ans;

        if (R == 1 || C == 1) {
            ans = solve1D(R, C, clues);
        } else if (R == 2 || C == 2) {
            if (R == 2) {
                vector<int> top(C + 1, 0), bot(C + 1, 0);

                for (auto &cl : clues) {
                    if (cl.r == 1) top[cl.c] = cl.val;
                    else bot[cl.c] = cl.val;
                }

                ans = count2xC(C, top, bot);
            } else {
                // Transpose: original C == 2, R > 2
                int newC = R;
                vector<int> top(newC + 1, 0), bot(newC + 1, 0);

                for (auto &cl : clues) {
                    if (cl.c == 1) top[cl.r] = cl.val;
                    else bot[cl.r] = cl.val;
                }

                ans = count2xC(newC, top, bot);
            }
        } else {
            ans = solveTemplates(R, C, clues);
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

static inline int mod2(ll x) {
    int m = int(x % 2);
    if (m < 0) m += 2;
    return m;
}

ll countParity(ll low, ll high, int p) {
    if (low > high) return 0;
    ll first = low;
    if (mod2(first) != p) ++first;
    if (first > high) return 0;
    return (high - first) / 2 + 1;
}

ll countB(ll a, ll bL, ll bR, ll L, ll R, ll M, int p) {
    if (a < L || a > R) return 0;
    if (a > L && mod2(a) != p) return 0;

    ll low = max(bL, a);
    ll upperSmall = min(bR, R - 1);

    if (a > L) {
        low = max(low, a + M - 1);
    }

    ll res = 0;
    if (low <= upperSmall) {
        res += countParity(low, upperSmall, p);
    }

    // b == R has no parity / length restriction
    if (bL <= R && R <= bR && a <= R) {
        ++res;
    }
    return res;
}

// mark[i] : 1 = must be inside interval, -1 = must be outside, 0 = free
ll countIntervals(ll L, ll R, ll M, int p, const vector<int>& mark) {
    int N = int(R - L + 1);

    bool hasInc = false;
    ll minInc = LLONG_MAX, maxInc = LLONG_MIN;

    for (int i = 0; i < N; ++i) {
        if (mark[i] == 1) {
            hasInc = true;
            ll c = L + i;
            minInc = min(minInc, c);
            maxInc = max(maxInc, c);
        }
    }

    if (!hasInc) {
        ll total = 1; // empty interval

        int i = 0;
        while (i < N) {
            while (i < N && mark[i] == -1) ++i;
            if (i >= N) break;

            int start = i;
            while (i < N && mark[i] != -1) ++i;
            int finish = i - 1;

            ll gapEnd = L + finish;
            for (int idx = start; idx <= finish; ++idx) {
                ll a = L + idx;
                total += countB(a, a, gapEnd, L, R, M, p);
            }
        }
        return total;
    }

    // If any forbidden coordinate lies between minInc and maxInc, impossible.
    for (int i = 0; i < N; ++i) {
        if (mark[i] == -1) {
            ll c = L + i;
            if (minInc <= c && c <= maxInc) return 0;
        }
    }

    ll aL = L, aR = minInc;
    ll bL = maxInc, bR = R;

    for (int i = 0; i < N; ++i) {
        if (mark[i] == -1) {
            ll c = L + i;
            if (c < minInc) {
                aL = max(aL, c + 1);
            } else if (c > maxInc) {
                bR = min(bR, c - 1);
            }
        }
    }

    if (aL > aR || bL > bR) return 0;

    ll total = 0;
    for (ll a = aL; a <= aR; ++a) {
        total += countB(a, bL, bR, L, R, M, p);
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int R, C, X;
        cin >> R >> C >> X;

        vector<tuple<int, int, int>> cons;
        cons.reserve(X);

        for (int i = 0; i < X; ++i) {
            char ch;
            int r, c;
            cin >> ch >> r >> c;
            int v = (ch == '+') ? 1 : -1;
            cons.emplace_back(r, c, v);
        }

        // One-dimensional case
        if (R == 1 || C == 1) {
            int N = max(R, C);
            vector<int> fixed(N + 1, -1); // 1 = '+', 0 = '-'

            for (auto [r, c, v] : cons) {
                int pos = (R == 1) ? c : r;
                fixed[pos] = (v == 1) ? 1 : 0;
            }

            ll dp[2][2] = {};
            // last: 0 = '-', 1 = '+'
            // used: number of "++" substrings, 0 or 1

            for (int pos = 1; pos <= N; ++pos) {
                ll ndp[2][2] = {};

                for (int val = 0; val <= 1; ++val) {
                    if (fixed[pos] != -1 && fixed[pos] != val) continue;

                    if (pos == 1) {
                        ndp[val][0] += 1;
                    } else {
                        for (int last = 0; last < 2; ++last) {
                            for (int used = 0; used < 2; ++used) {
                                if (dp[last][used] == 0) continue;

                                int nused = used;

                                if (val == 0) {
                                    if (last == 0) continue; // "--"
                                } else {
                                    if (last == 1) {
                                        ++nused;
                                        if (nused > 1) continue;
                                    }
                                }

                                ndp[val][nused] += dp[last][used];
                            }
                        }
                    }
                }

                memcpy(dp, ndp, sizeof(dp));
            }

            ll ans = 0;
            for (int a = 0; a < 2; ++a)
                for (int b = 0; b < 2; ++b)
                    ans += dp[a][b];

            cout << ans << '\n';
            continue;
        }

        // Tiny 2x2 brute force
        if (R == 2 && C == 2) {
            int fixed[2][2] = {};

            for (auto [r, c, v] : cons) {
                fixed[r - 1][c - 1] = v;
            }

            ll ans = 0;

            for (int mask = 0; mask < 16; ++mask) {
                int g[2][2];
                bool ok = true;

                for (int i = 0; i < 2; ++i) {
                    for (int j = 0; j < 2; ++j) {
                        int bit = i * 2 + j;
                        int val = ((mask >> bit) & 1) ? 1 : -1;
                        g[i][j] = val;

                        if (fixed[i][j] != 0 && fixed[i][j] != val)
                            ok = false;
                    }
                }

                if (!ok) continue;

                auto goodPair = [](int a, int b) {
                    int s = a + b;
                    return -1 <= s && s <= 2;
                };

                if (!goodPair(g[0][0], g[0][1])) continue;
                if (!goodPair(g[1][0], g[1][1])) continue;
                if (!goodPair(g[0][0], g[1][0])) continue;
                if (!goodPair(g[0][1], g[1][1])) continue;

                ++ans;
            }

            cout << ans << '\n';
            continue;
        }

        // General 2D case
        int L1 = 2;
        int R1 = R + C;
        int N1 = R1 - L1 + 1;
        vector<int> mark1(N1, 0);

        int L2 = 1 - C;
        int R2 = R - 1;
        int N2 = R2 - L2 + 1;
        vector<int> mark2(N2, 0);

        bool conflict1 = false;
        bool conflict2 = false;

        bool all0 = true;
        bool all1 = true;

        for (auto [r, c, v] : cons) {
            int b = ((r + c) % 2 == 0) ? 1 : -1;
            int xval = (v == b) ? 0 : 1;

            if (xval != 0) all0 = false;
            if (xval != 1) all1 = false;

            // Type 1: x = 1 on an interval of r+c
            int s = r + c;
            int idx1 = s - L1;
            int want1 = (xval == 1) ? 1 : -1;

            if (mark1[idx1] == 0) mark1[idx1] = want1;
            else if (mark1[idx1] != want1) conflict1 = true;

            // Type 2: x = 0 on an interval of r-c
            int vc = r - c;
            int idx2 = vc - L2;
            int want2 = (xval == 0) ? 1 : -1;

            if (mark2[idx2] == 0) mark2[idx2] = want2;
            else if (mark2[idx2] != want2) conflict2 = true;
        }

        ll M = max(R, C) - 1;

        ll type1 = 0;
        ll type2 = 0;

        if (!conflict1) {
            type1 = countIntervals(L1, R1, M, 1, mark1);
        }

        if (!conflict2) {
            type2 = countIntervals(L2, R2, M, 0, mark2);
        }

        ll inter = (all0 ? 1 : 0) + (all1 ? 1 : 0);

        ll ans = type1 + type2 - inter;
        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Clue {
    int r, c, v;
};

long long count1D(int n, int L1, int L2, const vector<pair<int,int>>& cons) {
    vector<int> val(n + 2, 0);

    for (auto [idx, v] : cons) {
        if (idx < 1 || idx > n) return 0;
        if (val[idx] != 0 && val[idx] != v) return 0;
        val[idx] = v;
    }

    int M = max(L1, L2);
    int Smin;
    if (M <= 1) Smin = 2;
    else Smin = (M % 2 ? M : M - 1);

    // No defects: alternating sequence.
    long long noDef = 0;
    int req = 0;
    bool ok = true;

    for (int i = 1; i <= n; i++) {
        if (val[i] == 0) continue;

        int base = (i & 1) ? -1 : 1; // (-1)^i
        int need = val[i] * base;

        if (req == 0) req = need;
        else if (req != need) {
            ok = false;
            break;
        }
    }

    if (ok) noDef = (req == 0 ? 2 : 1);

    const int INF = n + 1;

    vector<array<int, 2>> prefMax(n + 2), prefMin(n + 2);
    vector<array<int, 2>> suffMax(n + 2), suffMin(n + 2);

    prefMax[0] = {0, 0};
    prefMin[0] = {INF, INF};

    for (int i = 1; i <= n; i++) {
        prefMax[i] = prefMax[i - 1];
        prefMin[i] = prefMin[i - 1];

        if (val[i] != 0) {
            int vBit = (val[i] == -1 ? 1 : 0);
            int p0 = vBit ^ (i & 1);

            prefMax[i][p0] = max(prefMax[i][p0], i);
            prefMin[i][p0] = min(prefMin[i][p0], i);
        }
    }

    suffMax[n + 1] = {0, 0};
    suffMin[n + 1] = {INF, INF};

    for (int i = n; i >= 1; i--) {
        suffMax[i] = suffMax[i + 1];
        suffMin[i] = suffMin[i + 1];

        if (val[i] != 0) {
            int vBit = (val[i] == -1 ? 1 : 0);
            int p0 = vBit ^ (i & 1);

            suffMax[i][p0] = max(suffMax[i][p0], i);
            suffMin[i][p0] = min(suffMin[i][p0], i);
        }
    }

    long long single = 0;
    long long two = 0;

    for (int e = 1; e <= n - 1; e++) {
        int p = e & 1;

        // For the single-defect sequence with defect at e.
        int L = max(prefMax[e][p], suffMax[e + 1][p ^ 1]);
        int R = min(suffMin[e + 1][p], prefMin[e][p ^ 1]);

        if (R == INF) single++;

        // Add a second defect e2 > e.
        int q = p ^ 1;

        int lo = max({e + 1, L, e + Smin});
        int hi = min(n - 1, R - 1);

        if (lo <= hi) {
            int first = lo;
            if ((first & 1) != q) first++;

            if (first <= hi) {
                two += (hi - first) / 2 + 1;
            }
        }
    }

    return noDef + single + two;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int R, C, X;
        cin >> R >> C >> X;

        vector<Clue> clues;
        clues.reserve(X);

        vector<pair<int, int>> consS, consD;
        consS.reserve(X);
        consD.reserve(X);

        for (int i = 0; i < X; i++) {
            char ch;
            int r, c;
            cin >> ch >> r >> c;

            int v = (ch == '+' ? 1 : -1);
            clues.push_back({r, c, v});

            consS.push_back({r + c - 1, v});
            consD.push_back({r - c + C, v});
        }

        int n = R + C - 1;
        long long ans;

        if (min(R, C) == 1) {
            ans = count1D(n, C, R, consS);
        } else {
            long long cntS = count1D(n, C, R, consS);
            long long cntD = count1D(n, C, R, consD);

            long long inter = 0;

            // The two checkerboard grids.
            for (int sgn : {1, -1}) {
                bool good = true;

                for (auto &cl : clues) {
                    int parity = (cl.r + cl.c) & 1;
                    int expected = (parity == 0 ? 1 : -1) * sgn;

                    if (expected != cl.v) {
                        good = false;
                        break;
                    }
                }

                if (good) inter++;
            }

            // The all-plus grid is also both sum- and difference-constant
            // only in the 2x2 case.
            if (R == 2 && C == 2) {
                bool good = true;

                for (auto &cl : clues) {
                    if (cl.v != 1) {
                        good = false;
                        break;
                    }
                }

                if (good) inter++;
            }

            ans = cntS + cntD - inter;
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Cell {
    int r, c;
    bool plus;
};

/*
For each parameter value, records whether it is invalid for at least one
constraint. Parameter parities are stored separately.
*/
struct ParityBad {
    int n;
    vector<int> diff[2];

    explicit ParityBad(int n = 0) : n(n), diff[2](vector<int>(n + 3, 0)) {}

    void add(int l, int r, int parity) {
        l = max(l, 1);
        r = min(r, n);
        if (l > r) return;

        if ((l & 1) != parity) ++l;
        if ((r & 1) != parity) --r;
        if (l > r) return;

        ++diff[parity][l];
        --diff[parity][r + 2];
    }

    vector<int> build() const {
        vector<int> bad(n + 1, 0);
        int count[2] = {0, 0};

        for (int i = 1; i <= n; ++i) {
            count[i & 1] += diff[i & 1][i];
            bad[i] = count[0] + count[1];
        }
        return bad;
    }
};

static int parityOf(int x) {
    return (x % 2 + 2) % 2;
}

/*
For a defective row H_h, the cell in column c is '+' exactly when

  h and c have the same parity and h >= c, or
  h and c have different parity and h < c.

This routine marks parameter values for which h = coef * parameter + constant
gives the wrong remembered sign.
*/
static void markAffineWrong(
    ParityBad &bad,
    int coef,
    int constant,
    int c,
    bool wantedPlus,
    int L,
    int R
) {
    if (L > R) return;

    int constantParity = parityOf(constant);

    for (int p = 0; p < 2; ++p) {
        int hParity = (p + constantParity) & 1;
        bool sameParity = (hParity == (c & 1));

        // Actual sign is '+' iff:
        //   same parity: h >= c
        //   other parity: h < c
        bool wrongMeansAtLeastC;
        if (wantedPlus) {
            wrongMeansAtLeastC = !sameParity;
        } else {
            wrongMeansAtLeastC = sameParity;
        }

        if (wrongMeansAtLeastC) {
            // h >= c
            if (coef == 1) {
                int low = c - constant;
                bad.add(max(L, low), R, p);
            } else {
                int high = constant - c;
                bad.add(L, min(R, high), p);
            }
        } else {
            // h < c
            if (coef == 1) {
                int high = c - constant - 1;
                bad.add(L, min(R, high), p);
            } else {
                int low = constant - c + 1;
                bad.add(max(L, low), R, p);
            }
        }
    }
}

static bool hCellIsPlus(int h, int c) {
    if ((h & 1) == (c & 1)) return h >= c;
    return h < c;
}

/*
baseType:
  0 -> + - + - ...
  1 -> - + - + ...
*/
static bool patternPlus(int baseType, int c, int distanceParity) {
    bool base = (baseType == 0) ? ((c & 1) != 0) : ((c & 1) == 0);
    return base ^ (distanceParity != 0);
}

static long long countOneD(int length, const vector<pair<int, bool>> &cells) {
    long long answer = 0;

    bool alternatingPlusStart = true;
    bool alternatingMinusStart = true;

    for (auto [c, plus] : cells) {
        if (plus != ((c & 1) != 0)) alternatingPlusStart = false;
        if (plus != ((c & 1) == 0)) alternatingMinusStart = false;
    }

    answer += alternatingPlusStart;
    answer += alternatingMinusStart;

    int n = length - 1;
    if (n == 0) return answer;

    ParityBad bad(n);

    for (auto [c, plus] : cells) {
        // Here h = parameter.
        markAffineWrong(bad, 1, 0, c, plus, 1, n);
    }

    vector<int> badValues = bad.build();
    for (int h = 1; h <= n; ++h) {
        if (badValues[h] == 0) ++answer;
    }

    return answer;
}

static long long countTwoByTwo(const vector<Cell> &cells) {
    long long answer = 0;

    for (int mask = 0; mask < 16; ++mask) {
        bool valid = true;

        auto plusAt = [&](int r, int c) {
            int bit = (r - 1) * 2 + (c - 1);
            return ((mask >> bit) & 1) != 0;
        };

        for (int r = 1; r <= 2 && valid; ++r) {
            for (int c = 1; c <= 2; ++c) {
                if (c == 1 && !plusAt(r, c) && !plusAt(r, c + 1)) valid = false;
                if (r == 1 && !plusAt(r, c) && !plusAt(r + 1, c)) valid = false;
            }
        }

        for (const Cell &cell : cells) {
            if (plusAt(cell.r, cell.c) != cell.plus) {
                valid = false;
                break;
            }
        }

        answer += valid;
    }

    return answer;
}

class GridCounter {
    int R, C, n;
    vector<Cell> cells;

    int topBaseType(bool endsAtN) const {
        if (!endsAtN) return 0;
        return (C & 1) ? 0 : 1;
    }

    int bottomBaseType(bool startsAtN) const {
        if (!startsAtN) return 0;
        return (C & 1) ? 0 : 1;
    }

    long long countCheckerboard(int phase) const {
        for (const Cell &cell : cells) {
            bool expected = (((cell.r + cell.c) & 1) == 0);
            if (phase) expected = !expected;
            if (expected != cell.plus) return 0;
        }
        return 1;
    }

    // A defective block touching the top boundary, followed by pure rows.
    long long countTopSingle(bool endsAtN) const {
        int K = min(n, R - 1);
        if (K <= 0) return 0;

        ParityBad bad(K);

        for (const Cell &cell : cells) {
            int r = cell.r;

            if (endsAtN) {
                // h = n - a + r
                markAffineWrong(bad, -1, n + r, cell.c, cell.plus, r, K);
            } else {
                // h = a - r + 1
                markAffineWrong(bad, 1, 1 - r, cell.c, cell.plus, r, K);
            }

            // If a < r, this cell belongs to the pure suffix.
            int pureRight = min(K, r - 1);
            if (pureRight >= 1) {
                int baseType = topBaseType(endsAtN);
                for (int p = 0; p < 2; ++p) {
                    int distanceParity = (r & 1) ^ p ^ 1;
                    bool expected = patternPlus(baseType, cell.c, distanceParity);
                    if (expected != cell.plus) {
                        bad.add(1, pureRight, p);
                    }
                }
            }
        }

        vector<int> badValues = bad.build();
        long long answer = 0;
        for (int a = 1; a <= K; ++a) {
            answer += (badValues[a] == 0);
        }
        return answer;
    }

    // A defective block touching the bottom boundary, preceded by pure rows.
    long long countBottomSingle(bool startsAtN) const {
        int K = min(n, R - 1);
        if (K <= 0) return 0;

        ParityBad bad(K);

        for (const Cell &cell : cells) {
            int r = cell.r;
            int firstBottomRow = R - r + 1;

            if (startsAtN) {
                // h = n - b - r + R + 1
                markAffineWrong(
                    bad, -1, n - r + R + 1, cell.c, cell.plus,
                    firstBottomRow, K
                );
            } else {
                // h = b + r - R
                markAffineWrong(
                    bad, 1, r - R, cell.c, cell.plus,
                    firstBottomRow, K
                );
            }

            // If b < R-r+1, this cell is in the pure prefix.
            int pureRight = min(K, firstBottomRow - 1);
            if (pureRight >= 1) {
                int baseType = bottomBaseType(startsAtN);
                for (int p = 0; p < 2; ++p) {
                    int distanceParity = (R & 1) ^ p ^ (r & 1);
                    bool expected = patternPlus(baseType, cell.c, distanceParity);
                    if (expected != cell.plus) {
                        bad.add(1, pureRight, p);
                    }
                }
            }
        }

        vector<int> badValues = bad.build();
        long long answer = 0;
        for (int b = 1; b <= K; ++b) {
            answer += (badValues[b] == 0);
        }
        return answer;
    }

    /*
    Two boundary blocks:
      top ends at H_1 and bottom starts at H_n, or
      top ends at H_n and bottom starts at H_1.
    */
    long long countTwoBoundaryBlocks(bool topEndsAtN) const {
        bool bottomStartsAtN = !topEndsAtN;

        ParityBad topBad(n), bottomBad(n);

        for (const Cell &cell : cells) {
            int r = cell.r;

            if (topEndsAtN) {
                markAffineWrong(topBad, -1, n + r, cell.c, cell.plus, r, n);
            } else {
                markAffineWrong(topBad, 1, 1 - r, cell.c, cell.plus, r, n);
            }

            int firstBottomRow = R - r + 1;
            if (bottomStartsAtN) {
                markAffineWrong(
                    bottomBad, -1, n - r + R + 1, cell.c, cell.plus,
                    firstBottomRow, n
                );
            } else {
                markBadBottomStart:
                markAffineWrong(
                    bottomBad, 1, r - R, cell.c, cell.plus,
                    firstBottomRow, n
                );
            }
        }

        vector<int> topBadValues = topBad.build();
        vector<int> bottomBadValues = bottomBad.build();

        // Prefix counts of valid bottom lengths, separated by parity.
        vector<array<int, 2>> pref(n + 1);
        pref[0] = {0, 0};
        for (int b = 1; b <= n; ++b) {
            pref[b] = pref[b - 1];
            if (bottomBadValues[b] == 0) ++pref[b][b & 1];
        }

        /*
        For each parity of a, find the first remembered row in the pure middle
        whose sign would be wrong there.
        */
        const int INF = R + 1;
        vector<vector<int>> firstWrong(2, vector<int>(R + 2, INF));

        for (const Cell &cell : cells) {
            int baseType = topBaseType(topEndsAtN);
            for (int p = 0; p < 2; ++p) {
                int distanceParity = (cell.r & 1) ^ p ^ 1;
                bool expected = patternPlus(baseType, cell.c, distanceParity);
                if (expected != cell.plus) {
                    firstWrong[p][cell.r] = cell.r;
                }
            }
        }

        for (int p = 0; p < 2; ++p) {
            for (int r = R; r >= 1; --r) {
                firstWrong[p][r] = min(firstWrong[p][r], firstWrong[p][r + 1]);
            }
        }

        int maxSum = min(R - 1, C);
        long long answer = 0;

        for (int a = 1; a <= n; ++a) {
            if (topBadValues[a] != 0) continue;

            int high = min(n, maxSum - a);
            if (high < 1) continue;

            int low = 1;
            int wrongRow = firstWrong[a & 1][a + 1];
            if (wrongRow != INF) {
                low = max(low, R - wrongRow + 1);
            }
            if (low > high) continue;

            // R-a-b must have the same parity as C.
            int requiredParity = (R & 1) ^ (C & 1) ^ (a & 1);
            answer += pref[high][requiredParity] - pref[low - 1][requiredParity];
        }

        return answer;
    }

    // An interior defective block spanning H_1, ..., H_n.
    long long countInterior(bool increasing) const {
        int maxL = R - n;
        if (maxL < 2) return 0;

        ParityBad bad(maxL);

        for (const Cell &cell : cells) {
            int r = cell.r;

            // Cell lies in the defective block.
            int blockLeft = max(2, r - n + 1);
            int blockRight = min(maxL, r);
            if (increasing) {
                // h = -l + r + 1
                markAffineWrong(
                    bad, -1, r + 1, cell.c, cell.plus,
                    blockLeft, blockRight
                );
            } else {
                // h = l + n - r
                markAffineWrong(
                    bad, 1, n - r, cell.c, cell.plus,
                    blockLeft, blockRight
                );
            }

            // Cell lies in the pure prefix.
            int leftLeft = r + 1;
            int leftRight = maxL;
            if (leftLeft <= leftRight) {
                int baseType = increasing ? 0 : ((C & 1) ? 0 : 1);
                for (int p = 0; p < 2; ++p) {
                    int distanceParity = p ^ 1 ^ (r & 1);
                    bool expected = patternPlus(baseType, cell.c, distanceParity);
                    if (expected != cell.plus) {
                        bad.add(leftLeft, leftRight, p);
                    }
                }
            }

            // Cell lies in the pure suffix.
            int rightLeft = 2;
            int rightRight = min(maxL, r - n);
            if (rightLeft <= rightRight) {
                int baseType = increasing ? ((C & 1) ? 0 : 1) : 0;
                for (int p = 0; p < 2; ++p) {
                    int distanceParity = (r & 1) ^ p ^ (n & 1);
                    bool expected = patternPlus(baseType, cell.c, distanceParity);
                    if (expected != cell.plus) {
                        bad.add(rightLeft, rightRight, p);
                    }
                }
            }
        }

        vector<int> badValues = bad.build();
        long long answer = 0;
        for (int l = 2; l <= maxL; ++l) {
            answer += (badValues[l] == 0);
        }
        return answer;
    }

    // All rows are defective, with a monotone sequence of defect positions.
    long long countAllDefectiveMonotone(bool increasing) const {
        int low, high;
        if (increasing) {
            low = 1;
            high = n - R + 1;
        } else {
            low = R;
            high = n;
        }
        if (low > high) return 0;

        ParityBad bad(high - low + 1);

        for (const Cell &cell : cells) {
            if (increasing) {
                // h = a + r - 1
                markAffineWrong(
                    bad, 1, cell.r - 1, cell.c, cell.plus,
                    low, high
                );
            } else {
                // h = a - r + 1
                markAffineWrong(
                    bad, 1, 1 - cell.r, cell.c, cell.plus,
                    low, high
                );
            }
        }

        vector<int> badValues = bad.build();
        long long answer = 0;
        for (int a = low; a <= high; ++a) {
            answer += (badValues[a - low] == 0);
        }
        return answer;
    }

    /*
    All rows are defective and the special jump H_1 <-> H_n is used.
    C must be even.
    */
    long long countSpecialAllDefective(bool jumpOneToN) const {
        int low, high;

        if (jumpOneToN) {
            low = max(1, R - n);
            high = min(n, R - 1);
        } else {
            low = max(1, n + 2 - R);
            high = min(n, 2 * n + 1 - R);
        }
        if (low > high) return 0;

        ParityBad bad(high - low + 1);

        for (const Cell &cell : cells) {
            int r = cell.r;

            if (jumpOneToN) {
                // Before the jump: h = k-r+1.
                markAffineWrong(
                    bad, 1, 1 - r, cell.c, cell.plus,
                    max(low, r), high
                );

                // The row containing H_n.
                int k = r - 1;
                if (k >= low && k <= high && !hCellIsPlus(n, cell.c)) {
                    bad.add(k - low, k - low, k & 1);
                }

                // After the jump: h = n+k+1-r.
                markAffineWrong(
                    bad, 1, n + 1 - r, cell.c, cell.plus,
                    low, min(high, r - 2)
                );
            } else {
                // Before the jump: h = a+r-1.
                markAffineWrong(
                    bad, 1, r - 1, cell.c, cell.plus,
                    low, min(high, n - r + 1)
                );

                // The row containing H_1.
                int a = n - r;
                if (a >= low && a <= high && !hCellIsPlus(1, cell.c)) {
                    bad.add(a - low, a - low, a & 1);
                }

                // After the jump: h = a+r-n-1.
                markAffineWrong(
                    bad, 1, r - n - 1, cell.c, cell.plus,
                    low, min(high, n - r - 1)
                );
            }
        }

        vector<int> badValues = bad.build();
        long long answer = 0;
        for (int p = low; p <= high; ++p) {
            answer += (badValues[p - low] == 0);
        }
        return answer;
    }

public:
    GridCounter(int R, int C, vector<Cell> cells)
        : R(R), C(C), n(C - 1), cells(std::move(cells)) {}

    long long solve() const {
        long long answer = 0;

        answer += countCheckerboard(0);
        answer += countCheckerboard(1);

        answer += countTopSingle(false);
        answer += countTopSingle(true);
        answer += countBottomSingle(false);
        answer += countBottomSingle(true);

        answer += countTwoBoundaryBlocks(false);
        answer += countTwoBoundaryBlocks(true);

        answer += countInterior(true);
        answer += countInterior(false);

        answer += countAllDefectiveMonotone(true);
        answer += countAllDefectiveMonotone(false);

        if ((C & 1) == 0) {
            answer += countSpecialAllDefective(true);
            answer += countSpecialAllDefective(false);
        }

        return answer;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int R, C, X;
        cin >> R >> C >> X;

        vector<Cell> cells;
        cells.reserve(X);

        for (int i = 0; i < X; ++i) {
            char value;
            int r, c;
            cin >> value >> r >> c;
            cells.push_back({r, c, value == '+'});
        }

        if (R == 1 || C == 1) {
            int length = max(R, C);
            vector<pair<int, bool>> lineCells;
            lineCells.reserve(X);

            for (const Cell &cell : cells) {
                int position = (R == 1) ? cell.c : cell.r;
                lineCells.push_back({position, cell.plus});
            }

            cout << countOneD(length, lineCells) << '\n';
            continue;
        }

        if (R == 2 && C == 2) {
            cout << countTwoByTwo(cells) << '\n';
            continue;
        }

        // The cases C=2 have a simpler row description. Transpose them so
        // that the main algorithm can assume C>=3.
        if (C == 2) {
            swap(R, C);
            for (Cell &cell : cells) swap(cell.r, cell.c);
        }

        GridCounter solver(R, C, std::move(cells));
        cout << solver.solve() << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;

/*
    A row of length C is valid exactly when:
      - it contains no "--";
      - it contains at most one "++".

    There are C+1 possible valid rows. Number them from 0 through C:
      - state 0 is the alternating row beginning with '+';
      - state C is the alternating row beginning with '-';
      - state p, 1 <= p < C, is the alternating row whose only equal
        adjacent pair is "++" between positions p and p+1.

    For two consecutive rows, their equality positions must all contain '+'.
    Moreover, each column may contain at most one such vertical "++".
    Consequently, walking through the row states uses labeled edges, with
    each label used at most once.

    The compatibility graph of row states is a theta graph:
      - most edges have one label;
      - one edge has no label and may be used repeatedly;
      - at most one additional edge has two labels.

    The memoized search below stores the used labels as a union of intervals.
*/

struct Edge {
    int to;
    vector<int> labels;
};

struct Interval {
    int l, r;

    bool operator<(const Interval& other) const {
        return tie(l, r) < tie(other.l, other.r);
    }
};

static bool contains(const vector<Interval>& used, int x) {
    for (const auto& in : used) {
        if (in.l <= x && x <= in.r) return true;
    }
    return false;
}

static vector<Interval> addLabels(const vector<Interval>& used,
                                  const vector<int>& labels) {
    vector<Interval> result = used;

    for (int x : labels) {
        bool inserted = false;

        for (auto& in : result) {
            if (in.l <= x && x <= in.r) {
                inserted = true;
                break;
            }
        }
        if (inserted) continue;

        result.push_back({x, x});
        sort(result.begin(), result.end());

        vector<Interval> merged;
        for (const auto& in : result) {
            if (!merged.empty() && in.l <= merged.back().r + 1) {
                merged.back().r = max(merged.back().r, in.r);
            } else {
                merged.push_back(in);
            }
        }
        result.swap(merged);
    }

    return result;
}

static bool cellIsPlus(int state, int col, int C) {
    if (state == 0) {
        return (col & 1) != 0;
    }
    if (state == C) {
        return (col & 1) == 0;
    }

    if (col <= state) {
        return ((col + state) & 1) == 0;
    } else {
        return ((col + state) & 1) != 0;
    }
}

static string makeKey(int row, int state, const vector<Interval>& used) {
    string key;
    key.reserve(24 + 16 * used.size());

    auto appendInt = [&](int x) {
        for (int i = 0; i < 4; ++i) {
            key.push_back(static_cast<char>((x >> (8 * i)) & 255));
        }
    };

    appendInt(row);
    appendInt(state);
    appendInt(static_cast<int>(used.size()));
    for (const auto& in : used) {
        appendInt(in.l);
        appendInt(in.r);
    }
    return key;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int R, C, X;
        cin >> R >> C >> X;

        vector<tuple<char, int, int>> clues(X);
        for (auto& [ch, r, c] : clues) {
            cin >> ch >> r >> c;
            --r;
            --c;
        }

        // Use the smaller dimension as the number of rows.
        if (R > C) {
            swap(R, C);
            for (auto& [ch, r, c] : clues) {
                swap(r, c);
            }
        }

        vector<vector<pair<int, int>>> rowClues(R);
        for (const auto& [ch, r, c] : clues) {
            rowClues[r].push_back({c, ch == '+'});
        }

        vector<vector<Edge>> graph(C + 1);

        auto addEdge = [&](int u, int v, vector<int> labels) {
            graph[u].push_back({v, labels});
            graph[v].push_back({u, move(labels)});
        };

        if (C == 1) {
            addEdge(0, 1, {});
            addEdge(0, 0, {1});
        } else if (C == 2) {
            addEdge(0, 1, {1});
            addEdge(1, 2, {2});
            addEdge(0, 2, {});
            addEdge(1, 1, {1, 2});
        } else if (C & 1) {
            for (int i = 0; i + 1 < C; ++i) {
                addEdge(i, i + 1, {i + 1});
            }
            addEdge(0, C - 1, {C});
            addEdge(0, C, {});
        } else {
            for (int i = 0; i + 1 < C; ++i) {
                addEdge(i, i + 1, {i + 1});
            }
            addEdge(C - 1, C, {C});
            addEdge(0, C, {});
            addEdge(1, C - 1, {1, C});
        }

        unordered_map<string, cpp_int> memo;
        memo.reserve(1 << 18);
        memo.max_load_factor(0.7f);

        auto dfs = [&](auto&& self, int row, int state,
                       const vector<Interval>& used) -> cpp_int {
            for (const auto& [col, wantPlus] : rowClues[row]) {
                if (cellIsPlus(state, col, C) != wantPlus) {
                    return 0;
                }
            }

            if (row + 1 == R) {
                return 1;
            }

            string key = makeKey(row, state, used);
            auto it = memo.find(key);
            if (it != memo.end()) return it->second;

            cpp_int answer = 0;

            for (const Edge& e : graph[state]) {
                bool usable = true;
                for (int label : e.labels) {
                    if (contains(used, label)) {
                        usable = false;
                        break;
                    }
                }
                if (!usable) continue;

                vector<Interval> nextUsed = addLabels(used, e.labels);
                answer += self(self, row + 1, e.to, nextUsed);
            }

            memo.emplace(move(key), answer);
            return answer;
        };

        vector<Interval> empty;
        cpp_int answer = dfs(dfs, 0, 0, empty);
        cout << answer << '\n';
    }

    return 0;
}

