#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct SuccessorDSU {
    vector<int> p;

    void init(int n) {
        p.resize(n + 1);
        iota(p.begin(), p.end(), 0);
    }

    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }

    void erase(int x) {
        p[x] = find(x + 1);
    }
};

int greedyPairs(const vector<ll>& a, ll d, ll upper, int needed) {
    int n = (int)a.size();
    vector<int> start(n);
    int j = 0;

    for (int i = 0; i < n; ++i) {
        j = max(j, i + 1);
        while (j < n && a[j] - a[i] < d) ++j;
        start[i] = j;
    }

    SuccessorDSU dsu;
    dsu.init(n);

    int pairs = 0;
    while (true) {
        int i = dsu.find(0);
        if (i == n) break;

        int right = dsu.find(start[i]);
        if (right < n && a[right] - a[i] <= upper) {
            ++pairs;
            if (pairs >= needed) return pairs;
            dsu.erase(i);
            dsu.erase(right);
        } else {
            dsu.erase(i);
        }
    }
    return pairs;
}

int N;
ll C;
vector<ll> pos, revPos;

bool canPair(int k, ll d) {
    if (d > C / 2) return false;
    ll upper = C - d;

    if (greedyPairs(pos, d, upper, k) >= k) return true;
    if (greedyPairs(revPos, d, upper, k) >= k) return true;
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> C;
    pos.resize(N);
    for (ll& x : pos) cin >> x;

    revPos.resize(N);
    for (int i = 0; i < N; ++i) {
        revPos[i] = C - pos[N - 1 - i];
    }

    int K = N / 2;
    vector<ll> answer(K);
    ll previousHigh = C / 2;

    for (int k = 1; k <= K; ++k) {
        ll lo = 0, hi = previousHigh;
        while (lo < hi) {
            ll mid = lo + (hi - lo + 1) / 2;
            if (canPair(k, mid)) lo = mid;
            else hi = mid - 1;
        }
        answer[k - 1] = lo;
        previousHigh = lo;
    }

    for (int i = 0; i < K; ++i) {
        if (i) cout << ' ';
        cout << answer[i];
    }
    cout << '\n';
    return 0;
}

