using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long C;
    cin >> N >> C;

    vector<long long> l(N);
    for (int i = 0; i < N; i++) cin >> l[i];

    const int PERIODS = 6;
    vector<long long> pos;
    pos.reserve(PERIODS * N);
    for (int p = 0; p < PERIODS; p++) {
        for (int i = 0; i < N; i++) {
            pos.push_back(l[i] + 1LL * p * C);
        }
    }

    auto check = [&](int k, long long D) -> bool {
        if (D == 0) return true;

        vector<long long> selected;
        selected.reserve(PERIODS * N);
        deque<long long> q;

        for (long long x : pos) {
            while (!q.empty() && q.front() <= x - D) {
                q.pop_front();
            }
            if ((int)q.size() < k) {
                q.push_back(x);
                selected.push_back(x);
            }
        }

        int need = 2 * k;
        int m = (int)selected.size();
        if (m < need) return false;

        vector<int> bad(m, 0);
        for (int i = 0; i + k < m; i++) {
            long long diff = selected[i + k] - selected[i];
            if (diff < D || diff > C - D) bad[i] = 1;
        }

        vector<int> pref(m + 1, 0);
        for (int i = 0; i < m; i++) {
            pref[i + 1] = pref[i] + bad[i];
        }

        for (int i = 0; i + need <= m; i++) {
            if (selected[i + need - 1] - selected[i] >= C) continue;

            // Need all bad[i .. i+k-1] to be zero.
            if (pref[i + k] - pref[i] == 0) {
                return true;
            }
        }

        return false;
    };

    int K = N / 2;
    vector<long long> ans(K + 1);

    for (int k = 1; k <= K; k++) {
        long long lo = 0, hi = C / 2;

        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            if (check(k, mid)) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }

        ans[k] = lo;
    }

    for (int k = 1; k <= K; k++) {
        if (k > 1) cout << ' ';
        cout << ans[k];
    }
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int N;
long long C;
vector<long long> p;

// Maximum matching size for a fixed cut s and threshold D.
// L = p[0..s-1], R = p[s..N-1]
int eval_cut(int s, int D) {
    if (s <= 0 || s >= N) return 0;
    int cnt = 0, i = 0, q = 0;
    long long U = C - D;
    for (int j = s; j < N; ++j) {
        long long r = p[j];
        while (i < s && p[i] <= r - D) ++i;
        while (q < i && p[q] < r - U) ++q;
        if (q < i) {
            ++cnt;
            ++q;
        }
    }
    return cnt;
}

// Uses ternary search assuming f(s) is unimodal. Used only as a fast heuristic.
int max_matching_ternary(int D) {
    if (D == 0) return N / 2;
    if (2LL * D > C) return 0;
    int l = 0, r = N;
    while (r - l > 5) {
        int m1 = l + (r - l) / 3;
        int m2 = r - (r - l) / 3;
        int f1 = eval_cut(m1, D);
        int f2 = eval_cut(m2, D);
        if (f1 < f2) l = m1;
        else r = m2;
    }
    int best = 0;
    for (int s = l; s <= r; ++s)
        best = max(best, eval_cut(s, D));
    return best;
}

// Exact maximum matching size over all cuts.
int max_matching_exact(int D) {
    if (D == 0) return N / 2;
    if (2LL * D > C) return 0;
    int best = 0;
    int half = N / 2;
    long long U = C - D;
    for (int s = 1; s < N; ++s) {
        int max_possible = min(s, N - s);
        if (max_possible <= best) continue;
        int cnt = 0, i = 0, q = 0;
        for (int j = s; j < N; ++j) {
            long long r = p[j];
            while (i < s && p[i] <= r - D) ++i;
            while (q < i && p[q] < r - U) ++q;
            if (q < i) {
                ++cnt;
                ++q;
            }
        }
        if (cnt > best) {
            best = cnt;
            if (best == half) return best;
        }
    }
    return best;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> C;
    p.resize(N);
    for (int i = 0; i < N; ++i) cin >> p[i];

    int maxK = N / 2;
    vector<int> ans(maxK + 1);
    unordered_map<int, int> exact_cache;
    exact_cache.reserve(2048);

    int prev_high = C / 2;

    for (int k = 1; k <= maxK; ++k) {
        int low = 0, high = prev_high, res = 0;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (max_matching_ternary(mid) >= k) {
                res = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        int ans_k = res;
        bool ok = true;

        // Verify maximality. If the ternary search underestimated, fix it exactly.
        if (ans_k < C / 2) {
            int nextD = ans_k + 1;
            int next_val;
            auto it = exact_cache.find(nextD);
            if (it != exact_cache.end()) {
                next_val = it->second;
            } else {
                next_val = max_matching_exact(nextD);
                exact_cache[nextD] = next_val;
            }
            if (next_val >= k) ok = false;
        }

        if (!ok) {
            int low2 = 0, high2 = C / 2, res2 = 0;
            while (low2 <= high2) {
                int mid = low2 + (high2 - low2) / 2;
                int val;
                auto it = exact_cache.find(mid);
                if (it != exact_cache.end()) {
                    val = it->second;
                } else {
                    val = max_matching_exact(mid);
                    exact_cache[mid] = val;
                }
                if (val >= k) {
                    res2 = mid;
                    low2 = mid + 1;
                } else {
                    high2 = mid - 1;
                }
            }
            ans_k = res2;
        }

        ans[k] = ans_k;
        prev_high = ans_k;
    }

    for (int k = 1; k <= maxK; ++k) {
        if (k > 1) cout << ' ';
        cout << ans[k];
    }
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long C;
    cin >> N >> C;

    vector<long long> l(N);
    for (int i = 0; i < N; i++) cin >> l[i];

    vector<long long> a(2 * N);
    for (int i = 0; i < N; i++) {
        a[i] = l[i];
        a[i + N] = l[i] + C;
    }

    auto feasible = [&](long long D, int k) -> bool {
        int r = 0;
        int W = 0;

        // Maximum number of cows in any open arc of length D.
        for (int i = 0; i < N; i++) {
            if (r < i) r = i;
            while (r < i + N && a[r] - a[i] < D) {
                r++;
            }
            W = max(W, r - i);
        }

        int maxPairs = min(N / 2, N - W);
        return maxPairs >= k;
    };

    int half = N / 2;
    long long high = C / 2;

    for (int k = 1; k <= half; k++) {
        long long lo = 1;
        long long hi = high;
        long long ans = 1;

        while (lo <= hi) {
            long long mid = (lo + hi) / 2;
            if (feasible(mid, k)) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        if (k > 1) cout << ' ';
        cout << ans;

        high = ans;
    }

    cout << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    int64 C;
    cin >> N >> C;

    vector<int64> loc(N);
    for (int64 &x : loc) cin >> x;

    const int M = N / 2;
    vector<int64> answer(M + 1, 0);

    vector<int64> a(N), bucket(N + 1);
    vector<int64> extended(3 * N);
    vector<int> previousSmaller(3 * N), nextSmaller(3 * N);
    vector<int> st;
    st.reserve(3 * N);

    for (int r = 1; r <= M; ++r) {
        // a[i] is the distance between cow i and cow i+r, cyclically.
        for (int i = 0; i < N; ++i) {
            int j = i + r;
            if (j >= N) j -= N;

            int64 d = abs(loc[i] - loc[j]);
            a[i] = min(d, C - d);
        }

        // Work on three copies to handle cyclic windows.
        for (int i = 0; i < 3 * N; ++i) {
            extended[i] = a[i % N];
        }

        // Nearest strictly smaller element to the left.
        st.clear();
        for (int i = 0; i < 3 * N; ++i) {
            while (!st.empty() && extended[st.back()] >= extended[i]) {
                st.pop_back();
            }
            previousSmaller[i] = st.empty() ? -1 : st.back();
            st.push_back(i);
        }

        // Nearest strictly smaller element to the right.
        st.clear();
        for (int i = 3 * N - 1; i >= 0; --i) {
            while (!st.empty() && extended[st.back()] >= extended[i]) {
                st.pop_back();
            }
            nextSmaller[i] = st.empty() ? 3 * N : st.back();
            st.push_back(i);
        }

        fill(bucket.begin(), bucket.end(), -1);

        for (int i = 0; i < N; ++i) {
            int middle = i + N;
            int span;

            if (previousSmaller[middle] == -1 ||
                nextSmaller[middle] == 3 * N) {
                // A global minimum can be included in a window of any length.
                span = N;
            } else {
                span = nextSmaller[middle] - previousSmaller[middle] - 1;
                span = min(span, N);
            }

            bucket[span] = max(bucket[span], a[i]);
        }

        // best[k] = maximum possible minimum of a cyclic window of length k.
        for (int k = N - 1; k >= 1; --k) {
            bucket[k] = max(bucket[k], bucket[k + 1]);
        }

        // A window of length k <= r gives k disjoint parallel pairs.
        for (int k = 1; k <= r; ++k) {
            answer[k] = max(answer[k], bucket[k]);
        }
    }

    for (int k = 1; k <= M; ++k) {
        if (k > 1) cout << ' ';
        cout << answer[k];
    }
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    int64 C;
    cin >> N >> C;

    vector<int64> x(2 * N);
    for (int i = 0; i < N; ++i) cin >> x[i];
    sort(x.begin(), x.begin() + N);

    // Duplicate the circle so cyclic blocks become ordinary intervals.
    for (int i = 0; i < N; ++i) {
        x[i + N] = x[i] + C;
    }

    /*
       Returns whether some block of m consecutive cows has
       pairwise circular distances at most D.
    */
    auto existsBlock = [&](int m, int64 D) -> bool {
        int p = -1;
        int maxBad = -1;
        const int64 upper = C - D;

        for (int j = 0; j < m + N - 1; ++j) {
            // p becomes the largest i < j with x[j] - x[i] > D.
            while (p + 1 < j && x[j] - x[p + 1] > D) {
                ++p;
            }

            /*
               A pair i < j is bad when
                   D < x[j] - x[i] < C-D.

               If p is too far away, all earlier indices are also too far,
               so there is no bad pair ending at j.
            */
            if (p >= 0 && x[j] - x[p] < upper) {
                maxBad = max(maxBad, p);
            }

            if (j >= m - 1) {
                int start = j - m + 1;

                // A bad pair is inside this block exactly when maxBad >= start.
                if (maxBad < start) {
                    return true;
                }
            }
        }

        return false;
    };

    vector<int64> answer(N / 2);

    for (int k = 1; k <= N / 2; ++k) {
        int m = N - k + 1;

        int64 low = 0;
        int64 high = C / 2;

        while (low < high) {
            int64 mid = low + (high - low) / 2;
            if (existsBlock(m, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        answer[k - 1] = low;
    }

    for (int i = 0; i < (int)answer.size(); ++i) {
        if (i) cout << ' ';
        cout << answer[i];
    }
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

class Solver {
private:
    int N;
    int64 C;
    vector<int64> position;

    vector<int> leftmost, rightmost, cutMemo;
    unordered_map<int, int> distanceMemo;

    // Maximum number of valid pairs when every distance is at least d.
    int maximumMatching(int64 d) {
        auto found = distanceMemo.find(static_cast<int>(d));
        if (found != distanceMemo.end()) {
            return found->second;
        }

        const int64 upperDistance = C - d;

        // For row i, valid columns form the interval
        // [leftmost[i], rightmost[i]].
        int ptr = 0;
        for (int i = 0; i < N; ++i) {
            while (ptr < N && position[ptr] - position[i] < d) {
                ++ptr;
            }
            leftmost[i] = ptr;
        }

        ptr = -1;
        for (int i = 0; i < N; ++i) {
            while (ptr + 1 < N &&
                   position[ptr + 1] - position[i] <= upperDistance) {
                ++ptr;
            }
            rightmost[i] = ptr;
        }

        fill(cutMemo.begin(), cutMemo.end(), -1);

        // Maximum bipartite matching across the cut after cow t:
        // left endpoints are at most t, right endpoints are greater than t.
        auto cutCount = [&](int t) -> int {
            int &cached = cutMemo[t];
            if (cached != -1) {
                return cached;
            }

            int nextRight = t + 1;
            int result = 0;

            for (int i = 0; i <= t; ++i) {
                if (nextRight < leftmost[i]) {
                    nextRight = leftmost[i];
                }

                if (nextRight <= rightmost[i]) {
                    ++result;
                    ++nextRight;
                }
            }

            cached = result;
            return cached;
        };

        // The sequence cutCount(t) is concave, so its maximum can be
        // found by binary search.
        int low = 0;
        int high = N - 1;

        while (low < high) {
            int mid = low + (high - low) / 2;

            if (cutCount(mid) < cutCount(mid + 1)) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        int answer = cutCount(low);
        distanceMemo.emplace(static_cast<int>(d), answer);
        return answer;
    }

public:
    void solve() {
        cin >> N >> C;

        position.resize(N);
        for (int i = 0; i < N; ++i) {
            cin >> position[i];
        }

        leftmost.resize(N);
        rightmost.resize(N);
        cutMemo.resize(N);

        distanceMemo.reserve(32768);
        distanceMemo.max_load_factor(0.7f);

        const int K = N / 2;
        int64 previousAnswer = C / 2;

        for (int k = 1; k <= K; ++k) {
            int64 low = 1;
            int64 high = previousAnswer;

            while (low < high) {
                int64 mid = low + (high - low + 1) / 2;

                if (maximumMatching(mid) >= k) {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }

            if (k > 1) {
                cout << ' ';
            }
            cout << low;

            // The optimal minimum distance cannot increase as k increases.
            previousAnswer = low;
        }

        cout << '\n';
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Solver solver;
    solver.solve();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const int MOD = 1000000007;

int modpow(int a, int e = MOD - 2) {
    ll r = 1, b = a;
    while (e) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return (int)r;
}

struct Appearance {
    int pos, cow, dir;
};

struct Candidate {
    int pos = 0;
    int g = 0;
    int cow[2] = {0, 0};
    int mask[2] = {0, 0};
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int N, M;
        ll K;
        cin >> N >> M >> K;

        vector<int> p(N), x(N), ccw(N), invCCW(N, 0);
        for (int &v : p) cin >> v;
        for (int &v : x) cin >> v;

        vector<int> answer(M, 0);
        auto printAnswer = [&]() {
            for (int i = 0; i < M; i++) {
                if (i) cout << ' ';
                cout << answer[i];
            }
            cout << '\n';
        };

        ll q = K / M;
        int r = (int)(K % M);

        for (int i = 0; i < N; i++) {
            ccw[i] = 1 - p[i];
            if (ccw[i] < 0) ccw[i] += MOD;
            if (ccw[i]) invCCW[i] = modpow(ccw[i]);
        }

        if (N == 1) {
            int a = (x[0] + r) % M;
            int b = x[0] - r;
            if (b < 0) b += M;
            answer[a] = (answer[a] + p[0]) % MOD;
            answer[b] = (answer[b] + ccw[0]) % MOD;
            printAnswer();
            continue;
        }

        int twoQ = (int)(2 * (q % N) % N);

        // Multiply a polynomial by ccw[i] + p[i]*y.  The vector's size
        // always equals (number of factors + 1), including trailing zeroes.
        auto multiplyPoly = [&](vector<int> &P, int i) {
            int d = (int)P.size() - 1;
            int a = ccw[i], b = p[i];
            P.resize(d + 2, 0);

            if (b == 0) {
                P[d + 1] = 0;
                return;
            }
            if (a == 0) {
                for (int k = d + 1; k >= 1; k--) P[k] = P[k - 1];
                P[0] = 0;
                return;
            }

            P[d + 1] = (int)((ll)b * P[d] % MOD);
            for (int k = d; k >= 1; k--) {
                P[k] = ((ll)a * P[k] + (ll)b * P[k - 1]) % MOD;
            }
            P[0] = (int)((ll)a * P[0] % MOD);
        };

        // Exact division by ccw[i] + p[i]*y.
        auto dividePoly = [&](vector<int> &P, int i) {
            int newSize = (int)P.size() - 1;
            int a = ccw[i], b = p[i];

            if (a == 0) {
                for (int k = 0; k < newSize; k++) P[k] = P[k + 1];
                P.pop_back();
                return;
            }
            if (b == 0) {
                P.pop_back();
                return;
            }

            int inv = invCCW[i];
            for (int k = 0; k < newSize; k++) {
                int cur = P[k];
                if (k) {
                    int sub = (int)((ll)b * P[k - 1] % MOD);
                    cur -= sub;
                    if (cur < 0) cur += MOD;
                }
                P[k] = (int)((ll)cur * inv % MOD);
            }
            P.pop_back();
        };

        // If K is a whole number of laps, only the total number of
        // clockwise choices is needed.
        if (r == 0) {
            vector<int> dp(1, 1);
            for (int i = 0; i < N; i++) multiplyPoly(dp, i);

            for (int s = 0; s <= N; s++) {
                int rank = (int)((ll)twoQ * s % N);
                answer[x[rank]] = (answer[x[rank]] + dp[s]) % MOD;
            }
            printAnswer();
            continue;
        }

        int H = M - r;

        vector<Appearance> apps;
        apps.reserve(2 * N);
        for (int i = 0; i < N; i++) {
            int a = x[i] + r;
            if (a >= M) a -= M;
            int b = x[i] - r;
            if (b < 0) b += M;
            apps.push_back({a, i, 1}); // clockwise
            apps.push_back({b, i, 2}); // counterclockwise
        }
        sort(apps.begin(), apps.end(),
             [](const Appearance &a, const Appearance &b) {
                 return a.pos < b.pos;
             });

        vector<Candidate> candidates;
        for (int i = 0; i < (int)apps.size();) {
            int j = i;
            Candidate c;
            c.pos = apps[i].pos;

            while (j < (int)apps.size() && apps[j].pos == c.pos) {
                int cow = apps[j].cow;
                int k = 0;
                while (k < c.g && c.cow[k] != cow) k++;
                if (k == c.g) {
                    c.cow[k] = cow;
                    c.mask[k] = 0;
                    c.g++;
                }
                c.mask[k] |= apps[j].dir;
                j++;
            }
            candidates.push_back(c);
            i = j;
        }

        vector<int> regionIds[4];
        for (int i = 0; i < (int)candidates.size(); i++) {
            int v = candidates[i].pos;
            int reg;
            if (v < r && v < H) reg = 0;
            else if (v >= r && v < H) reg = 1;
            else if (v < r) reg = 2;
            else reg = 3;
            regionIds[reg].push_back(i);
        }

        vector<int> mark(N, 0), outResidue(N, 0);
        int stamp = 0;

        vector<int> Pin, Pout, tmpIn, tmpOut;
        vector<pair<int, int>> inTerms;

        for (int reg = 0; reg < 4; reg++) {
            if (regionIds[reg].empty()) continue;

            int e0, delta;
            if (reg == 0) {
                e0 = -1;
                delta = (H > r ? 1 : -1);
            } else if (reg == 1) {
                e0 = 0;
                delta = -1;
            } else if (reg == 2) {
                e0 = -2;
                delta = 1;
            } else {
                e0 = -1;
                delta = (H > r ? 1 : -1);
            }

            auto normN = [&](int v) {
                v %= N;
                if (v < 0) v += N;
                return v;
            };

            int aOut = normN(e0 - twoQ);
            int aIn = normN(aOut + delta);

            vector<int> resIn(N + 1), resOut(N + 1);
            for (int i = 0; i <= N; i++) {
                resIn[i] = (int)((ll)aIn * i % N);
                resOut[i] = (int)((ll)aOut * i % N);
            }

            bool first = true;
            int L = 0, R = 0;

            for (int id : regionIds[reg]) {
                const Candidate &cand = candidates[id];
                int v = cand.pos;

                int leftPos, rightPos, betaCount;

                if (reg == 0) {
                    int A = H + v;
                    int B = r + v;
                    int bi = (int)(lower_bound(x.begin(), x.end(), B) - x.begin());
                    betaCount = bi;
                    if (A > B) {
                        leftPos = B;
                        rightPos = A;
                    } else {
                        leftPos = A;
                        rightPos = B;
                    }
                } else if (reg == 1) {
                    int A = v - r;
                    int B = r + v;
                    leftPos = A;
                    rightPos = B;
                    betaCount = (int)(lower_bound(x.begin(), x.end(), B) - x.begin());
                } else if (reg == 2) {
                    int e = v - H;
                    int A = H + v;
                    leftPos = e;
                    rightPos = A;
                    betaCount = N + (int)(lower_bound(x.begin(), x.end(), e) - x.begin());
                } else {
                    int A = v - r;
                    int e = v - H;
                    if (A > e) {
                        leftPos = e;
                        rightPos = A;
                    } else {
                        leftPos = A;
                        rightPos = e;
                    }
                    betaCount = N + (int)(lower_bound(x.begin(), x.end(), e) - x.begin());
                }

                int newL = (int)(lower_bound(x.begin(), x.end(), leftPos) - x.begin());
                int newR = (int)(lower_bound(x.begin(), x.end(), rightPos) - x.begin());

                if (first) {
                    Pin.assign(1, 1);
                    Pout.assign(1, 1);
                    for (int i = 0; i < N; i++) {
                        if (newL <= i && i < newR) multiplyPoly(Pin, i);
                        else multiplyPoly(Pout, i);
                    }
                    L = newL;
                    R = newR;
                    first = false;
                } else {
                    int leaveEnd = min(R, newL);
                    for (int i = L; i < leaveEnd; i++) {
                        dividePoly(Pin, i);
                        multiplyPoly(Pout, i);
                    }

                    int enterStart = max(R, newL);
                    for (int i = enterStart; i < newR; i++) {
                        dividePoly(Pout, i);
                        multiplyPoly(Pin, i);
                    }

                    L = newL;
                    R = newR;
                }

                bool inside[2];
                bool needIn = false, needOut = false;
                for (int k = 0; k < cand.g; k++) {
                    inside[k] = (L <= cand.cow[k] && cand.cow[k] < R);
                    if (inside[k]) needIn = true;
                    else needOut = true;
                }

                const vector<int> *inPtr = &Pin;
                const vector<int> *outPtr = &Pout;

                if (needIn) {
                    tmpIn = Pin;
                    inPtr = &tmpIn;
                }
                if (needOut) {
                    tmpOut = Pout;
                    outPtr = &tmpOut;
                }

                for (int k = 0; k < cand.g; k++) {
                    if (inside[k]) dividePoly(tmpIn, cand.cow[k]);
                    else dividePoly(tmpOut, cand.cow[k]);
                }

                ++stamp;
                for (int t = 0; t < (int)outPtr->size(); t++) {
                    int coef = (*outPtr)[t];
                    if (!coef) continue;
                    int rr = resOut[t];
                    if (mark[rr] != stamp) {
                        mark[rr] = stamp;
                        outResidue[rr] = coef;
                    } else {
                        int nv = outResidue[rr] + coef;
                        if (nv >= MOD) nv -= MOD;
                        outResidue[rr] = nv;
                    }
                }

                inTerms.clear();
                for (int s = 0; s < (int)inPtr->size(); s++) {
                    int coef = (*inPtr)[s];
                    if (coef) inTerms.push_back({s, coef});
                }

                auto calculate = [&](int need) -> int {
                    __int128 sum = 0;
                    for (auto [s, coef] : inTerms) {
                        int rr = need - resIn[s];
                        if (rr < 0) rr += N;
                        if (mark[rr] == stamp && outResidue[rr]) {
                            sum += (ll)coef * outResidue[rr];
                        }
                    }
                    return (int)(sum % MOD);
                };

                int betaMod = betaCount % N;

                for (int bits = 0; bits < (1 << cand.g); bits++) {
                    int pw = 1;
                    int atHere = 0;
                    int fixedIn = 0, fixedOut = 0;

                    for (int k = 0; k < cand.g; k++) {
                        int cow = cand.cow[k];
                        int dir = (bits >> k) & 1; // 1 = clockwise

                        pw = (int)((ll)pw * (dir ? p[cow] : ccw[cow]) % MOD);

                        bool present = dir ? (cand.mask[k] & 1) : (cand.mask[k] & 2);
                        if (present) atHere++;

                        if (dir) {
                            if (inside[k]) fixedIn++;
                            else fixedOut++;
                        }
                    }

                    if (atHere == 0 || pw == 0) continue;

                    int base = betaMod + resIn[fixedIn];
                    base %= N;
                    base += resOut[fixedOut];
                    base %= N;

                    int need0 = (base == 0 ? 0 : N - base);
                    int prob = calculate(need0);

                    if (atHere == 2) {
                        int need1 = (N - 1) - base;
                        if (need1 < 0) need1 += N;
                        int second = calculate(need1);
                        prob += second;
                        if (prob >= MOD) prob -= MOD;
                    }

                    answer[v] = (answer[v] + (ll)pw * prob) % MOD;
                }
            }
        }

        printAnswer();
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

int modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return int(r);
}

struct Solver {
    struct Factor {
        int ecw, eccw, qccw;
    };
    struct Node {
        vector<Factor> factors;
        int mono = 0;
    };
    struct Candidate {
        int pos, cow, dir; // dir: 0 = clockwise, 1 = counterclockwise
    };
    struct Group {
        int pos, sumSel;
    };

    int N, G;
    vector<Node> seg;
    vector<int> cur, tmp, shiftV;
    vector<vector<int>> backup;
    vector<int> V;
    int sh = 0;

    void rangeAdd(int v, int l, int r, int ql, int qr,
                  bool isMono, const Factor &f) {
        if (ql <= l && r <= qr) {
            if (isMono) {
                seg[v].mono += f.ecw;
                if (seg[v].mono >= N) seg[v].mono -= N;
            } else {
                seg[v].factors.push_back(f);
            }
            return;
        }
        int m = (l + r) >> 1;
        if (ql <= m) rangeAdd(v << 1, l, m, ql, qr, isMono, f);
        if (qr > m) rangeAdd(v << 1 | 1, m + 1, r, ql, qr, isMono, f);
    }

    void multiply(const Factor &f) {
        int off0 = f.ecw ? N - f.ecw : 0;
        int off1 = f.eccw ? N - f.eccw : 0;
        unsigned long long q = f.qccw;

        for (int j = 0; j < N; ++j) {
            int i0 = j + off0;
            if (i0 >= N) i0 -= N;
            int i1 = j + off1;
            if (i1 >= N) i1 -= N;

            int B = cur[i0];
            int A = cur[i1];
            int diff = A - B;
            if (diff < 0) diff += MOD;

            // q*A + (1-q)*B = B + q*(A-B).
            unsigned long long val = (unsigned long long)B + q * diff;
            tmp[j] = int(val % MOD);
        }
        cur.swap(tmp);
    }

    void evaluate(int stage) {
        unsigned long long sum = 0;
        for (int j = 0; j < N; ++j) {
            int residue = j + sh;
            if (residue >= N) residue -= N;
            if (residue < N - 1) {
                sum += (unsigned long long)(N - 1 - residue) * cur[j];
            }
        }
        V[stage] = int(sum % MOD);
    }

    void dfs(int v, int l, int r, int depth) {
        int oldShift = sh;
        sh += seg[v].mono;
        if (sh >= N) sh -= N;

        if (seg[v].factors.empty()) {
            if (l == r) {
                evaluate(l);
            } else {
                int m = (l + r) >> 1;
                dfs(v << 1, l, m, depth + 1);
                dfs(v << 1 | 1, m + 1, r, depth + 1);
            }
        } else {
            memcpy(backup[depth].data(), cur.data(), sizeof(int) * N);
            for (const Factor &f : seg[v].factors) multiply(f);

            if (l == r) {
                evaluate(l);
            } else {
                int m = (l + r) >> 1;
                dfs(v << 1, l, m, depth + 1);
                dfs(v << 1 | 1, m + 1, r, depth + 1);
            }
            cur.swap(backup[depth]);
        }
        sh = oldShift;
    }

    void run() {
        int M;
        long long K;
        cin >> N >> M >> K;

        vector<int> pcw(N), pccw(N), x(N);
        for (int i = 0; i < N; ++i) {
            cin >> pcw[i];
            pccw[i] = 1 - pcw[i];
            if (pccw[i] < 0) pccw[i] += MOD;
        }
        for (int i = 0; i < N; ++i) cin >> x[i];

        long long full = K / M;
        int rem = int(K % M);
        int a = N == 1 ? 0 : int((2 * (full % N)) % N);

        vector<int> ecw(N), eccw(N);
        vector<Candidate> candidates;
        candidates.reserve(2 * N);

        for (int i = 0; i < N; ++i) {
            int c = (x[i] + rem >= M);
            int b = (x[i] < rem);

            ecw[i] = (a + c) % N;
            eccw[i] = b ? N - 1 : 0;

            int posCW = x[i] + rem;
            if (posCW >= M) posCW -= M;
            int posCCW = x[i] - rem;
            if (posCCW < 0) posCCW += M;

            candidates.push_back({posCW, i, 0});
            candidates.push_back({posCCW, i, 1});
        }

        sort(candidates.begin(), candidates.end(),
             [](const Candidate &u, const Candidate &v) {
                 return u.pos < v.pos;
             });

        vector<int> groupCW(N), groupCCW(N);
        vector<Group> groups;

        for (int l = 0; l < (int)candidates.size();) {
            int r = l;
            int pos = candidates[l].pos;
            int sumSel = 0;
            int id = (int)groups.size();

            while (r < (int)candidates.size() && candidates[r].pos == pos) {
                const Candidate &c = candidates[r];
                if (c.dir == 0) {
                    groupCW[c.cow] = id;
                    sumSel += pcw[c.cow];
                } else {
                    groupCCW[c.cow] = id;
                    sumSel += pccw[c.cow];
                }
                if (sumSel >= MOD) sumSel -= MOD;
                ++r;
            }
            groups.push_back({pos, sumSel});
            l = r;
        }

        G = (int)groups.size();
        seg.assign(4 * (G + 1) + 5, Node());

        auto dec = [&](int e) {
            return e == 0 ? N - 1 : e - 1;
        };

        auto addVersion = [&](int ql, int qr, int cow, int e0, int e1) {
            if (ql > qr) return;

            int q = pccw[cow];
            bool isMono = false;
            int monoExp = 0;

            if (q == 0) {
                isMono = true;
                monoExp = e0;
            } else if (q == 1) {
                isMono = true;
                monoExp = e1;
            } else if (e0 == e1) {
                isMono = true;
                monoExp = e0;
            }

            if (isMono) {
                if (monoExp == 0) return;
                Factor f{monoExp, 0, 0};
                rangeAdd(1, 0, G, ql, qr, true, f);
            } else {
                Factor f{e0, e1, q};
                rangeAdd(1, 0, G, ql, qr, false, f);
            }
        };

        for (int i = 0; i < N; ++i) {
            int g0 = groupCW[i], g1 = groupCCW[i];

            if (g0 == g1) {
                addVersion(0, g0, i, ecw[i], eccw[i]);
                addVersion(g0 + 1, G, i, dec(ecw[i]), dec(eccw[i]));
            } else {
                int first = min(g0, g1), second = max(g0, g1);
                addVersion(0, first, i, ecw[i], eccw[i]);

                if (g0 < g1) {
                    addVersion(first + 1, second, i, dec(ecw[i]), eccw[i]);
                } else {
                    addVersion(first + 1, second, i, ecw[i], dec(eccw[i]));
                }
                addVersion(second + 1, G, i, dec(ecw[i]), dec(eccw[i]));
            }
        }

        cur.assign(N, 0);
        tmp.assign(N, 0);
        cur[0] = 1;
        backup.assign(32, vector<int>(N));
        V.assign(G + 1, 0);
        sh = 0;

        dfs(1, 0, G, 0);

        vector<int> answer(M, 0);
        int invN = modpow(N, MOD - 2);

        for (int g = 0; g < G; ++g) {
            int delta = V[g + 1] - V[g];
            if (delta < 0) delta += MOD;

            int num = groups[g].sumSel - delta;
            if (num < 0) num += MOD;

            answer[groups[g].pos] = int((long long)num * invN % MOD);
        }

        string out;
        for (int i = 0; i < M; ++i) {
            if (i) out.push_back(' ');
            out += to_string(answer[i]);
        }
        out.push_back('\n');
        cout << out;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        Solver s;
        s.run();
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int MOD = 1000000007;

int mod_pow(int a, long long e) {
    long long r = 1, x = a;
    while (e) {
        if (e & 1) r = r * x % MOD;
        x = x * x % MOD;
        e >>= 1;
    }
    return int(r);
}

struct Factor {
    int u, v, p; // p*z^u + (1-p)*z^v
};

struct Event {
    int pos, cow, dir, prob;
};

struct SegmentTree {
    int n, modn;
    vector<vector<Factor>> tr;
    vector<vector<int>> backup;
    vector<int> dp, tmp;
    const vector<int>* detShift;
    vector<int>* values;

    SegmentTree(int leaves, int nmod, const vector<int>& ds, vector<int>& vals)
        : n(leaves), modn(nmod), tr(4 * leaves + 5),
          backup(32, vector<int>(nmod)), dp(nmod), tmp(nmod),
          detShift(&ds), values(&vals) {
        dp[0] = 1;
    }

    void add(int node, int l, int r, int ql, int qr, const Factor& f) {
        if (ql <= l && r <= qr) {
            tr[node].push_back(f);
            return;
        }
        int m = (l + r) >> 1;
        if (ql <= m) add(node << 1, l, m, ql, qr, f);
        if (qr > m) add(node << 1 | 1, m + 1, r, ql, qr, f);
    }

    void add_interval(int l, int r, const Factor& f) {
        if (l > r) return;
        add(1, 0, n - 1, l, r, f);
    }

    inline void apply(const Factor& f) {
        int ia = f.u ? modn - f.u : 0;
        int ib = f.v ? modn - f.v : 0;
        const int p = f.p;

        for (int k = 0; k < modn; ++k) {
            int diff = dp[ia] - dp[ib];
            if (diff < 0) diff += MOD;
            int val = int(dp[ib] + (unsigned long long)p * diff % MOD);
            if (val >= MOD) val -= MOD;
            tmp[k] = val;

            if (++ia == modn) ia = 0;
            if (++ib == modn) ib = 0;
        }
        dp.swap(tmp);
    }

    void dfs(int node, int l, int r, int depth, int shift) {
        bool changed = false;
        int localShift = 0;

        if (!tr[node].empty()) {
            for (const Factor& f : tr[node]) {
                if (f.u == f.v) {
                    localShift += f.u;
                    if (localShift >= modn) localShift -= modn;
                }
            }

            for (const Factor& f : tr[node]) {
                if (f.u != f.v) {
                    if (!changed) {
                        memcpy(backup[depth].data(), dp.data(),
                               sizeof(int) * modn);
                        changed = true;
                    }
                    apply(f);
                }
            }
        }

        shift += localShift;
        if (shift >= modn) shift -= modn;

        if (l == r) {
            int sh = shift + (*detShift)[l];
            if (sh >= modn) sh -= modn;

            unsigned long long sum = 0;
            for (int i = 0; i < modn; ++i) {
                int residue = i + sh;
                if (residue >= modn) residue -= modn;
                sum += (unsigned long long)residue * dp[i];
            }
            (*values)[l] = int(sum % MOD);
        } else {
            int m = (l + r) >> 1;
            dfs(node << 1, l, m, depth + 1, shift);
            dfs(node << 1 | 1, m + 1, r, depth + 1, shift);
        }

        if (changed) {
            memcpy(dp.data(), backup[depth].data(), sizeof(int) * modn);
        }
    }

    void run() {
        dfs(1, 0, n - 1, 0, 0);
    }
};

vector<int> solve_test() {
    int N, M;
    long long K;
    cin >> N >> M >> K;

    vector<int> p(N), x(N);
    for (int& v : p) cin >> v;
    for (int& v : x) cin >> v;

    const long long full = K / M;
    const int d = int(K % M);
    const int fullMod = int(full % N);

    vector<int> cwPos(N), ccwPos(N), cwC(N), ccwC(N), ccwProb(N);
    vector<char> randomCow(N);
    vector<array<int, 2>> groupOf(N);
    for (int i = 0; i < N; ++i) groupOf[i] = {-1, -1};

    vector<Event> events;
    events.reserve(2 * N);

    int initialDetShift = 0;

    for (int i = 0; i < N; ++i) {
        int q = 1 - p[i];
        if (q < 0) q += MOD;
        ccwProb[i] = q;

        int a = x[i] + d;
        int A = 0;
        if (a >= M) {
            a -= M;
            A = 1;
        }

        int b = x[i] - d;
        int B = 0;
        if (b < 0) {
            b += M;
            B = 1;
        }

        cwPos[i] = a;
        ccwPos[i] = b;
        cwC[i] = int((2LL * fullMod + A) % N);
        ccwC[i] = B ? N - 1 : 0;

        if (p[i] != 0 && q != 0) {
            randomCow[i] = 1;
            events.push_back({a, i, 0, p[i]});
            events.push_back({b, i, 1, q});
        } else {
            int dir = (p[i] != 0 ? 0 : 1);
            int pos = (dir == 0 ? a : b);
            int c = (dir == 0 ? cwC[i] : ccwC[i]);
            initialDetShift += c;
            if (initialDetShift >= N) initialDetShift -= N;
            events.push_back({pos, i, dir, 1});
        }
    }

    sort(events.begin(), events.end(),
         [](const Event& a, const Event& b) { return a.pos < b.pos; });

    vector<int> positions, lambda, detCount;
    for (const Event& e : events) {
        if (positions.empty() || positions.back() != e.pos) {
            positions.push_back(e.pos);
            lambda.push_back(0);
            detCount.push_back(0);
        }
        int g = int(positions.size()) - 1;
        lambda[g] += e.prob;
        if (lambda[g] >= MOD) lambda[g] -= MOD;

        if (randomCow[e.cow]) {
            groupOf[e.cow][e.dir] = g;
        } else {
            ++detCount[g];
        }
    }

    const int U = int(positions.size());
    vector<int> detShift(U + 1);
    detShift[0] = initialDetShift;
    for (int g = 0; g < U; ++g) {
        int v = detShift[g] - detCount[g];
        v %= N;
        if (v < 0) v += N;
        detShift[g + 1] = v;
    }

    vector<int> G(U + 1);
    SegmentTree st(U + 1, N, detShift, G);

    auto dec = [&](int v) {
        return v == 0 ? N - 1 : v - 1;
    };

    for (int i = 0; i < N; ++i) {
        if (!randomCow[i]) continue;

        int gc = groupOf[i][0];
        int gw = groupOf[i][1];
        int first = min(gc, gw);
        int second = max(gc, gw);

        int u = cwC[i], v = ccwC[i];
        st.add_interval(0, first, {u, v, p[i]});

        if (first < second) {
            if (gc < gw) {
                st.add_interval(first + 1, second, {dec(u), v, p[i]});
            } else {
                st.add_interval(first + 1, second, {u, dec(v), p[i]});
            }
        }

        st.add_interval(second + 1, U, {dec(u), dec(v), p[i]});
    }

    st.run();

    vector<int> answer(M, 0);
    int invN = mod_pow(N, MOD - 2);

    for (int g = 0; g < U; ++g) {
        long long cur = lambda[g];
        cur += G[g + 1];
        cur -= G[g];
        cur %= MOD;
        if (cur < 0) cur += MOD;
        cur = cur * invN % MOD;
        answer[positions[g]] = int(cur);
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    string output;
    while (T--) {
        vector<int> ans = solve_test();
        for (int i = 0; i < (int)ans.size(); ++i) {
            if (i) output.push_back(' ');
            output += to_string(ans[i]);
        }
        output.push_back('\n');
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int MOD = 1000000007;

static inline int mul(int a, int b) {
    return int((long long)a * b % MOD);
}

static int modpow(int a, int e) {
    long long r = 1, x = a;
    while (e > 0) {
        if (e & 1) r = r * x % MOD;
        x = x * x % MOD;
        e >>= 1;
    }
    return int(r);
}

struct Cow {
    int prob[2];       // 0: clockwise, 1: counterclockwise
    int pos[2];
    int w[2];          // contribution to W modulo N
    int ex[2][2];      // ex[l] = l-w modulo N
    unsigned char before[2] = {0, 0};
    int firstDir = -1;
};

struct Candidate {
    int pos, cow, dir;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int N, M;
        long long K;
        cin >> N >> M >> K;

        vector<Cow> cows(N);
        for (int i = 0; i < N; i++) {
            int p;
            cin >> p;
            cows[i].prob[0] = p;
            cows[i].prob[1] = (1 - p + MOD) % MOD;
        }

        vector<int> x(N);
        for (int &v : x) cin >> v;

        long long a = K / M;
        int b = int(K % M);
        int A = N == 1 ? 0 : int((2 * (a % N)) % N);

        vector<Candidate> candidates;
        candidates.reserve(2 * N);

        for (int i = 0; i < N; i++) {
            int hi = (b > 0 && x[i] >= M - b) ? 1 : 0;
            int lo = (x[i] < b) ? 1 : 0;

            int pc = x[i] + b;
            if (pc >= M) pc -= M;
            int pd = x[i] - b;
            if (pd < 0) pd += M;

            cows[i].pos[0] = pc;
            cows[i].pos[1] = pd;
            cows[i].w[0] = N == 1 ? 0 : (A + hi) % N;
            cows[i].w[1] = lo ? (N - 1) % N : 0;

            for (int d = 0; d < 2; d++) {
                for (int l = 0; l < 2; l++) {
                    int e = (l - cows[i].w[d]) % N;
                    if (e < 0) e += N;
                    cows[i].ex[d][l] = e;
                }
            }

            candidates.push_back({pc, i, 0});
            candidates.push_back({pd, i, 1});
        }

        sort(candidates.begin(), candidates.end(),
             [](const Candidate &u, const Candidate &v) {
                 if (u.pos != v.pos) return u.pos < v.pos;
                 if (u.cow != v.cow) return u.cow < v.cow;
                 return u.dir < v.dir;
             });

        for (const Candidate &c : candidates) {
            if (cows[c.cow].firstDir == -1)
                cows[c.cow].firstDir = c.dir;
        }

        const size_t NN = (size_t)N * N;
        vector<int> pw(NN);
        vector<int> points(N), values(N);

        mt19937_64 rng(0x9e3779b97f4a7c15ULL ^
                       ((unsigned long long)N << 32) ^
                       (unsigned long long)M ^
                       (unsigned long long)K);
        unordered_set<int> used;
        used.reserve(2 * N + 20);

        // Choose evaluation points for which every factor that will later
        // need to be divided out is nonzero.
        for (int k = 0; k < N; ) {
            int alpha;
            do {
                alpha = int(rng() % (MOD - 1)) + 1;
            } while (used.count(alpha));
            used.insert(alpha);

            int *row = pw.data() + (size_t)k * N;
            row[0] = 1;
            for (int e = 1; e < N; e++) row[e] = mul(row[e - 1], alpha);

            bool good = true;
            int initialProduct = 1;

            for (int i = 0; i < N && good; i++) {
                const Cow &c = cows[i];
                int c0 = mul(c.prob[0], row[c.ex[0][0]]);
                int d0 = mul(c.prob[1], row[c.ex[1][0]]);

                int initial = c0 + d0;
                if (initial >= MOD) initial -= MOD;

                int second;
                if (c.firstDir == 0) {
                    second = mul(c.prob[0], row[c.ex[0][1]]) + d0;
                } else {
                    second = c0 + mul(c.prob[1], row[c.ex[1][1]]);
                }
                if (second >= MOD) second -= MOD;

                if (initial == 0 || second == 0) {
                    good = false;
                } else {
                    initialProduct = mul(initialProduct, initial);
                }
            }

            if (good) {
                points[k] = alpha;
                values[k] = initialProduct;
                k++;
            }
        }

        // Interpolation weights: coefficient t of P is obtained from
        // P(points[k]) using weight[t*N+k].
        vector<int> weight(NN);
        vector<int> Q(N + 1, 0), h(N);
        Q[0] = 1;

        for (int k = 0; k < N; k++) {
            int alpha = points[k];
            int deg = k;
            Q[deg + 1] = Q[deg];
            for (int e = deg; e >= 1; e--) {
                int v = Q[e - 1] - mul(alpha, Q[e]);
                if (v < 0) v += MOD;
                Q[e] = v;
            }
            int v = mul(alpha, Q[0]);
            Q[0] = v == 0 ? 0 : MOD - v;
        }

        for (int k = 0; k < N; k++) {
            int alpha = points[k];
            h[N - 1] = 1;
            for (int e = N - 2; e >= 0; e--) {
                int v = Q[e + 1] + mul(alpha, h[e + 1]);
                if (v >= MOD) v -= MOD;
                h[e] = v;
            }

            int den = 0;
            for (int e = N - 1; e >= 0; e--) {
                den = mul(den, alpha) + h[e];
                if (den >= MOD) den -= MOD;
            }
            int invDen = modpow(den, MOD - 2);

            for (int t = 0; t < N; t++) {
                weight[(size_t)k * N + t] = mul(h[t], invDen);
            }
        }

        // Transpose so that each needed coefficient's weights are contiguous.
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                swap(weight[(size_t)i * N + j],
                     weight[(size_t)j * N + i]);
            }
        }

        vector<int> answer(M, 0);
        vector<int> oldVal(N), newVal(N), prefix(N + 1);

        for (const Candidate &cand : candidates) {
            Cow &c = cows[cand.cow];
            int d = cand.dir;
            int o = d ^ 1;

            // Remove the selected cow's current factor at every evaluation
            // point, query the desired coefficient, and simultaneously apply
            // the factor update marking this ghost as preceding later ones.
            for (int k = 0; k < N; k++) {
                const int *row = pw.data() + (size_t)k * N;

                int other = mul(c.prob[o], row[c.ex[o][c.before[o]]]);
                int oldTerm = mul(c.prob[d], row[c.ex[d][0]]);
                int newTerm = mul(c.prob[d], row[c.ex[d][1]]);

                int ov = other + oldTerm;
                if (ov >= MOD) ov -= MOD;
                int nv = other + newTerm;
                if (nv >= MOD) nv -= MOD;

                oldVal[k] = ov;
                newVal[k] = nv;
            }

            prefix[0] = 1;
            for (int k = 0; k < N; k++) {
                prefix[k + 1] = mul(prefix[k], oldVal[k]);
            }

            int invProduct = modpow(prefix[N], MOD - 2);
            int target = c.w[d];
            const int *wr = weight.data() + (size_t)target * N;
            int coefficient = 0;

            for (int k = N - 1; k >= 0; k--) {
                int invOld = mul(invProduct, prefix[k]);
                invProduct = mul(invProduct, oldVal[k]);

                int without = mul(values[k], invOld);
                coefficient += mul(without, wr[k]);
                if (coefficient >= MOD) coefficient -= MOD;

                values[k] = mul(without, newVal[k]);
            }

            c.before[d] = 1;
            int add = mul(c.prob[d], coefficient);
            int &dest = answer[cand.pos];
            dest += add;
            if (dest >= MOD) dest -= MOD;
        }

        vector<int>().swap(pw);
        vector<int>().swap(weight);

        string out;
        out.reserve((size_t)M * 11 + 1);
        for (int i = 0; i < M; i++) {
            if (i) out.push_back(' ');
            out += to_string(answer[i]);
        }
        out.push_back('\n');
        cout << out;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int MOD = 1000000007;

struct Endpoint {
    int pos;
    int cow;
    int dir; // 0 = clockwise, 1 = counterclockwise
    long long wind;
};

struct Factor {
    int a, b; // a*y^u + b*y^v; b == 0 means a monomial
    int u, v;
};

struct Solver {
    int N, M, T;
    vector<Endpoint> ep;
    vector<int> answer;
    vector<vector<Factor>> tree;

    vector<int> cur;
    vector<vector<int>> history;
    int histSize = 0;

    static bool isZero(const Factor &f) {
        return f.a == 0 && f.b == 0;
    }

    static bool isIdentity(const Factor &f) {
        return f.b == 0 && f.a == 1 && f.u == 0;
    }

    Factor makeFactor(int a, int u, int b, int v) const {
        if (a == 0) return {b, 0, v, 0};
        if (b == 0) return {a, 0, u, 0};
        if (u == v) {
            int c = a + b;
            if (c >= MOD) c -= MOD;
            return {c, 0, u, 0};
        }
        return {a, b, u, v};
    }

    void addInterval(int node, int l, int r, int ql, int qr, const Factor &f) {
        if (isIdentity(f)) return;
        if (ql <= l && r <= qr) {
            tree[node].push_back(f);
            return;
        }
        int mid = (l + r) >> 1;
        if (ql < mid) addInterval(node << 1, l, mid, ql, qr, f);
        if (qr > mid) addInterval(node << 1 | 1, mid, r, ql, qr, f);
    }

    void addInterval(int l, int r, const Factor &f) {
        if (l < r && !isIdentity(f)) {
            addInterval(1, 0, T, l, r, f);
        }
    }

    // Returns whether the resulting polynomial is nonzero.
    bool apply(const Factor &f) {
        cur.swap(history[histSize]);
        const vector<int> &old = history[histSize];
        ++histSize;

        cur.resize(N);
        bool nonzero = false;

        if (isZero(f)) {
            fill(cur.begin(), cur.end(), 0);
            return false;
        }

        int i0 = f.u == 0 ? 0 : N - f.u;

        if (f.b == 0) {
            if (f.a == 1) {
                for (int j = 0; j < N; ++j) {
                    cur[j] = old[i0];
                    nonzero |= (cur[j] != 0);
                    if (++i0 == N) i0 = 0;
                }
            } else {
                for (int j = 0; j < N; ++j) {
                    cur[j] = (unsigned long long)f.a * old[i0] % MOD;
                    nonzero |= (cur[j] != 0);
                    if (++i0 == N) i0 = 0;
                }
            }
            return nonzero;
        }

        int i1 = f.v == 0 ? 0 : N - f.v;
        for (int j = 0; j < N; ++j) {
            unsigned long long value =
                (unsigned long long)f.a * old[i0] +
                (unsigned long long)f.b * old[i1];
            cur[j] = value % MOD;
            nonzero |= (cur[j] != 0);
            if (++i0 == N) i0 = 0;
            if (++i1 == N) i1 = 0;
        }
        return nonzero;
    }

    void rollback(int mark) {
        while (histSize > mark) {
            --histSize;
            cur.swap(history[histSize]);
        }
    }

    int evaluateLast(const Factor &f, const vector<int> &poly) const {
        int i0 = f.u == 0 ? 0 : N - f.u;
        unsigned long long value = (unsigned long long)f.a * poly[i0];
        if (f.b != 0) {
            int i1 = f.v == 0 ? 0 : N - f.v;
            value += (unsigned long long)f.b * poly[i1];
        }
        return value % MOD;
    }

    void dfs(int node, int l, int r) {
        int mark = histSize;

        if (r - l == 1) {
            auto &factors = tree[node];
            int sz = (int)factors.size();

            for (int i = 0; i + 1 < sz; ++i) {
                if (isZero(factors[i]) || !apply(factors[i])) {
                    rollback(mark);
                    return;
                }
            }

            int value = sz == 0 ? cur[0] : evaluateLast(factors.back(), cur);
            int &dest = answer[ep[l].pos];
            dest += value;
            if (dest >= MOD) dest -= MOD;

            rollback(mark);
            return;
        }

        for (const Factor &f : tree[node]) {
            if (isZero(f) || !apply(f)) {
                rollback(mark);
                return;
            }
        }

        int mid = (l + r) >> 1;
        dfs(node << 1, l, mid);
        dfs(node << 1 | 1, mid, r);

        rollback(mark);
    }

    void combineMonomials() {
        for (auto &factors : tree) {
            if (factors.empty()) continue;

            bool hasMonomial = false;
            int coefficient = 1;
            int exponent = 0;
            vector<Factor> other;
            other.reserve(factors.size());

            for (const Factor &f : factors) {
                if (f.b == 0) {
                    hasMonomial = true;
                    coefficient = (unsigned long long)coefficient * f.a % MOD;
                    exponent += f.u;
                    if (exponent >= N) exponent -= N;
                } else {
                    other.push_back(f);
                }
            }

            if (hasMonomial) {
                if (coefficient == 0) {
                    factors.assign(1, Factor{0, 0, 0, 0});
                    continue;
                }
                Factor combined{coefficient, 0, exponent, 0};
                if (!isIdentity(combined)) other.push_back(combined);
            }
            factors.swap(other);
        }
    }

    void run(int n, int m, long long K, const vector<int> &p,
             const vector<int> &x) {
        N = n;
        M = m;
        T = 2 * N;
        answer.assign(M, 0);

        vector<long long> wind[2];
        wind[0].resize(N);
        wind[1].resize(N);

        ep.reserve(T);

        for (int i = 0; i < N; ++i) {
            for (int dir = 0; dir < 2; ++dir) {
                long long X = dir == 0 ? x[i] + K : x[i] - K;
                long long w = X / M;
                if (X < 0 && X % M != 0) --w;

                long long r = X % M;
                if (r < 0) r += M;

                wind[dir][i] = w;
                ep.push_back({(int)r, i, dir, w});
            }
        }

        sort(ep.begin(), ep.end(), [](const Endpoint &a, const Endpoint &b) {
            if (a.pos != b.pos) return a.pos < b.pos;
            if (a.cow != b.cow) return a.cow < b.cow;
            return a.dir < b.dir;
        });

        vector<array<int, 2>> order(N);
        for (int i = 0; i < T; ++i) {
            order[ep[i].cow][ep[i].dir] = i;
        }

        tree.assign(4 * T + 5, {});

        auto exponent = [&](int indicator, long long w) {
            int e = (int)(w % N);
            e = indicator - e;
            e %= N;
            if (e < 0) e += N;
            return e;
        };

        for (int i = 0; i < N; ++i) {
            int plus = order[i][0];
            int minus = order[i][1];
            int first = min(plus, minus);
            int second = max(plus, minus);
            int ccwProb = p[i] == 0 ? 1 : MOD - p[i];

            // General factors, excluding the two leaves where this cow is
            // the forced target endpoint.
            array<pair<int, int>, 3> ranges = {{
                {0, first},
                {first + 1, second},
                {second + 1, T}
            }};

            for (auto [l, r] : ranges) {
                if (l >= r) continue;
                bool ip = plus < l;
                bool im = minus < l;

                Factor f = makeFactor(
                    p[i], exponent(ip, wind[0][i]),
                    ccwProb, exponent(im, wind[1][i])
                );
                addInterval(l, r, f);
            }

            // At a target leaf, force the corresponding direction.
            for (int dir = 0; dir < 2; ++dir) {
                int at = order[i][dir];
                int probability = dir == 0 ? p[i] : ccwProb;
                Factor f{probability, 0, exponent(0, wind[dir][i]), 0};
                addInterval(at, at + 1, f);
            }
        }

        combineMonomials();

        cur.assign(N, 0);
        cur[0] = 1;
        history.resize(N + 2);
        histSize = 0;

        dfs(1, 0, T);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int TC;
    cin >> TC;

    while (TC--) {
        int N, M;
        long long K;
        cin >> N >> M >> K;

        vector<int> p(N), x(N);
        for (int &v : p) cin >> v;
        for (int &v : x) cin >> v;

        Solver solver;
        solver.run(N, M, K, p, x);

        for (int i = 0; i < M; ++i) {
            if (i) cout << ' ';
            cout << solver.answer[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using u32 = uint32_t;
using u64 = uint64_t;

static constexpr u32 MOD = 1000000007;
static constexpr u32 MONT_ONE = 294967268; // 2^32 mod MOD

static constexpr u32 calc_ninv() {
    u32 x = 1;
    for (int i = 0; i < 6; i++) x *= 2u - MOD * x;
    return 0u - x;
}
static constexpr u32 NINV = calc_ninv();

static inline u32 redc(u64 t) {
    u32 m = u32(t) * NINV;
    u64 r = (t + u64(m) * MOD) >> 32;
    if (r >= MOD) r -= MOD;
    return u32(r);
}

static inline u32 to_mont(u32 x) {
    return u32(u64(x) * MONT_ONE % MOD);
}

static inline u32 add_mod(u32 a, u32 b) {
    u32 c = a + b;
    if (c >= MOD) c -= MOD;
    return c;
}

struct Solver {
    using Poly = vector<u32>;

    struct Query {
        int value, cow, state;
    };

    struct Factor {
        int e[2];
        u32 c[2];
    };

    struct Term {
        int e;
        u32 c;
    };

    struct TermList {
        Term t[4];
        int cnt = 0;

        void add(int e, u32 c) {
            if (!c) return;
            for (int i = 0; i < cnt; i++) {
                if (t[i].e == e) {
                    t[i].c = add_mod(t[i].c, c);
                    return;
                }
            }
            t[cnt++] = {e, c};
        }
    };

    int n, m;
    ll k;
    vector<array<int, 2>> w, fmod, pos;
    vector<array<u32, 2>> prob;
    vector<int> lo, hi;
    vector<Query> queries;
    vector<u32> answer;

    int residue(ll x) const {
        x %= n;
        if (x < 0) x += n;
        return int(x);
    }

    template<int C>
    Poly apply_fixed(const Poly &src, const TermList &tl) const {
        Poly out(n);
        const u32 *s = src.data();
        u32 *d = out.data();

        for (int e = 0; e < n; e++) {
            u64 sum = 0;
            #pragma GCC unroll 4
            for (int j = 0; j < C; j++) {
                int at = e - tl.t[j].e;
                if (at < 0) at += n;
                sum += u64(tl.t[j].c) * s[at];
            }
            d[e] = redc(sum);
        }
        return out;
    }

    Poly rotate_poly(const Poly &src, int shift) const {
        Poly out(n);
        for (int e = 0; e < n; e++) {
            int at = e - shift;
            if (at < 0) at += n;
            out[e] = src[at];
        }
        return out;
    }

    Poly apply_terms(const Poly &src, const TermList &tl) const {
        if (tl.cnt == 1 && tl.t[0].c == MONT_ONE) {
            return rotate_poly(src, tl.t[0].e);
        }
        switch (tl.cnt) {
            case 1: return apply_fixed<1>(src, tl);
            case 2: return apply_fixed<2>(src, tl);
            case 3: return apply_fixed<3>(src, tl);
            default: return apply_fixed<4>(src, tl);
        }
    }

    Poly add_constants(const Poly &g, const vector<int> &ids, int q) const {
        vector<Factor> factors;
        factors.reserve(ids.size());
        int shift = 0;

        for (int i : ids) {
            int ep = (q > pos[i][0]) - fmod[i][0];
            if (ep < 0) ep += n;
            int em = (q > pos[i][1]) - fmod[i][1];
            if (em < 0) em += n;

            u32 cp = prob[i][0], cm = prob[i][1];
            if (!cp) {
                shift += em;
                if (shift >= n) shift -= n;
            } else if (!cm || ep == em) {
                shift += ep;
                if (shift >= n) shift -= n;
            } else {
                factors.push_back({{ep, em}, {cp, cm}});
            }
        }

        if (factors.empty()) return rotate_poly(g, shift);

        Poly cur;
        bool first = true;

        for (size_t z = 0; z < factors.size(); z += 2) {
            TermList tl;
            const Factor &a = factors[z];

            if (z + 1 == factors.size()) {
                tl.add(a.e[0], a.c[0]);
                tl.add(a.e[1], a.c[1]);
            } else {
                const Factor &b = factors[z + 1];
                for (int x = 0; x < 2; x++) {
                    for (int y = 0; y < 2; y++) {
                        int e = a.e[x] + b.e[y];
                        if (e >= n) e -= n;
                        tl.add(e, redc(u64(a.c[x]) * b.c[y]));
                    }
                }
            }

            if (first) {
                for (int j = 0; j < tl.cnt; j++) {
                    tl.t[j].e += shift;
                    if (tl.t[j].e >= n) tl.t[j].e -= n;
                }
                shift = 0;
                cur = apply_terms(g, tl);
                first = false;
            } else {
                cur = apply_terms(cur, tl);
            }
        }

        if (shift) cur = rotate_poly(cur, shift);
        return cur;
    }

    void solve(int l, int r, const vector<int> &active, const Poly &g) {
        if (r - l == 1) {
            const Query &qq = queries[l];
            u32 ways = g[fmod[qq.cow][qq.state]];
            u32 contribution = redc(u64(prob[qq.cow][qq.state]) * ways);
            answer[qq.value] = add_mod(answer[qq.value], contribution);
            return;
        }

        int mid = (l + r) >> 1;
        vector<int> left_active, right_active;
        vector<int> left_constants, right_constants;

        for (int i : active) {
            if (hi[i] < mid) {
                left_active.push_back(i);
                right_constants.push_back(i);
            } else if (lo[i] >= mid) {
                right_active.push_back(i);
                left_constants.push_back(i);
            } else {
                left_active.push_back(i);
                right_active.push_back(i);
            }
        }

        if (left_constants.empty()) {
            solve(l, mid, left_active, g);
        } else {
            Poly next = add_constants(g, left_constants, l);
            solve(l, mid, left_active, next);
        }

        if (right_constants.empty()) {
            solve(mid, r, right_active, g);
        } else {
            Poly next = add_constants(g, right_constants, mid);
            solve(mid, r, right_active, next);
        }
    }

    void run() {
        cin >> n >> m >> k;

        vector<u32> input_p(n);
        for (u32 &x : input_p) cin >> x;

        vector<int> x(n);
        for (int &v : x) cin >> v;

        w.resize(n);
        fmod.resize(n);
        pos.resize(n);
        prob.resize(n);
        lo.resize(n);
        hi.resize(n);

        ll km = k % m;

        for (int i = 0; i < n; i++) {
            u32 p = input_p[i];
            u32 pm = u32((u64(MOD) + 1 - p) % MOD);
            prob[i] = {to_mont(p), to_mont(pm)};

            int wp = int((x[i] + km) % m);
            int wm = int((x[i] - km) % m);
            if (wm < 0) wm += m;
            w[i] = {wp, wm};

            ll fp = (x[i] + k) / m;
            ll num = x[i] - k;
            ll fm = num / m;
            if (num % m < 0) --fm;

            fmod[i] = {residue(fp), residue(fm)};
        }

        queries.reserve(2 * n);
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < 2; s++) {
                queries.push_back({w[i][s], i, s});
            }
        }

        sort(queries.begin(), queries.end(), [](const Query &a, const Query &b) {
            if (a.value != b.value) return a.value < b.value;
            if (a.cow != b.cow) return a.cow < b.cow;
            return a.state < b.state;
        });

        for (int q = 0; q < 2 * n; q++) {
            pos[queries[q].cow][queries[q].state] = q;
        }

        vector<int> active(n);
        iota(active.begin(), active.end(), 0);
        for (int i = 0; i < n; i++) {
            lo[i] = min(pos[i][0], pos[i][1]);
            hi[i] = max(pos[i][0], pos[i][1]);
        }

        answer.assign(m, 0);
        Poly initial(n, 0);
        initial[0] = MONT_ONE;

        solve(0, 2 * n, active, initial);

        string output;
        output.reserve(size_t(m) * 11 + 1);
        for (int i = 0; i < m; i++) {
            if (i) output.push_back(' ');
            output += to_string(redc(answer[i]));
        }
        output.push_back('\n');
        cout << output;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        Solver solver;
        solver.run();
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

struct Factor {
    int w1, e1, w2, e2;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int N, M;
        long long K;
        cin >> N >> M >> K;

        vector<int> p(N);
        for (int i = 0; i < N; ++i) cin >> p[i];

        vector<int> x(N);
        for (int i = 0; i < N; ++i) cin >> x[i];

        long long K_div = K / M;
        long long K_mod_ll = K % M;
        int K_mod = (int)K_mod_ll;
        int kd_mod = (int)(K_div % N);

        vector<int> q_plus(N), a_plus(N), w_plus(N);
        vector<int> q_minus(N), a_minus(N), w_minus(N);

        for (int i = 0; i < N; ++i) {
            int xi = x[i];

            // clockwise (+1)
            long long val = (long long)xi + K_mod;
            int carry = (int)(val / M);
            int qp = (int)(val % M);
            int ap = (kd_mod + carry) % N;

            // counterclockwise (-1)
            val = (long long)xi - K_mod;
            int carry2;
            int qm;
            if (val >= 0) {
                carry2 = 0;
                qm = (int)(val % M);
            } else {
                carry2 = -1;
                qm = (int)(val + M);
            }
            int am = (-kd_mod + carry2) % N;
            if (am < 0) am += N;

            int wp = p[i];
            int wm = (1 - p[i] + MOD) % MOD;

            q_plus[i] = qp;
            a_plus[i] = ap;
            w_plus[i] = wp;

            q_minus[i] = qm;
            a_minus[i] = am;
            w_minus[i] = wm;
        }

        vector<int> qs;
        qs.reserve(2 * N);
        for (int i = 0; i < N; ++i) {
            qs.push_back(q_plus[i]);
            qs.push_back(q_minus[i]);
        }
        sort(qs.begin(), qs.end());
        qs.erase(unique(qs.begin(), qs.end()), qs.end());
        int G = (int)qs.size();

        vector<vector<int>> groupCows(G);
        for (int i = 0; i < N; ++i) {
            int idx1 = lower_bound(qs.begin(), qs.end(), q_plus[i]) - qs.begin();
            int idx2 = lower_bound(qs.begin(), qs.end(), q_minus[i]) - qs.begin();

            if (idx1 == idx2) {
                groupCows[idx1].push_back(1);
            } else {
                if (w_plus[i] != 0) groupCows[idx1].push_back(w_plus[i]);
                if (w_minus[i] != 0) groupCows[idx2].push_back(w_minus[i]);
            }
        }

        vector<vector<Factor>> seg(4 * G + 5);

        auto add_range = [&](auto&& self, int node, int l, int r, int ql, int qr, const Factor& f) -> void {
            if (ql <= l && r <= qr) {
                seg[node].push_back(f);
                return;
            }
            int mid = (l + r) / 2;
            if (ql <= mid) self(self, node * 2, l, mid, ql, qr, f);
            if (qr > mid) self(self, node * 2 + 1, mid + 1, r, ql, qr, f);
        };

        for (int i = 0; i < N; ++i) {
            int idx1 = lower_bound(qs.begin(), qs.end(), q_plus[i]) - qs.begin();
            int idx2 = lower_bound(qs.begin(), qs.end(), q_minus[i]) - qs.begin();

            vector<int> bp = {0, G};
            if (idx1 + 1 < G) bp.push_back(idx1 + 1);
            if (idx2 + 1 < G) bp.push_back(idx2 + 1);

            sort(bp.begin(), bp.end());
            bp.erase(unique(bp.begin(), bp.end()), bp.end());

            for (int j = 0; j + 1 < (int)bp.size(); ++j) {
                int L = bp[j];
                int R = bp[j + 1] - 1;
                if (L > R) continue;

                int ind1 = (L > idx1) ? 1 : 0;
                int ind2 = (L > idx2) ? 1 : 0;

                int e1 = (a_plus[i] - ind1) % N;
                if (e1 < 0) e1 += N;
                int e2 = (a_minus[i] - ind2) % N;
                if (e2 < 0) e2 += N;

                Factor f = {w_plus[i], e1, w_minus[i], e2};
                add_range(add_range, 1, 0, G - 1, L, R, f);
            }
        }

        vector<int> P(N, 0), tmp(N, 0);
        P[0] = 1;

        vector<int> cdist(N + 1, 0), suff(N + 1, 0);
        vector<int> ans_g(G, 0);

        auto apply_factor = [&](const Factor& f) {
            int w1 = f.w1, e1 = f.e1, w2 = f.w2, e2 = f.e2;

            if (w1 == 0 && w2 == 0) {
                fill(P.begin(), P.end(), 0);
                return;
            }
            if (w1 == 0) {
                for (int i = 0; i < N; ++i) {
                    int j = i + e2;
                    if (j >= N) j -= N;
                    tmp[j] = P[i];
                }
                swap(P, tmp);
                return;
            }
            if (w2 == 0) {
                for (int i = 0; i < N; ++i) {
                    int j = i + e1;
                    if (j >= N) j -= N;
                    tmp[j] = P[i];
                }
                swap(P, tmp);
                return;
            }
            if (e1 == e2) {
                for (int i = 0; i < N; ++i) {
                    int j = i + e1;
                    if (j >= N) j -= N;
                    tmp[j] = P[i];
                }
                swap(P, tmp);
                return;
            }

            for (int j = 0; j < N; ++j) {
                int idx1 = j - e1;
                if (idx1 < 0) idx1 += N;
                int idx2 = j - e2;
                if (idx2 < 0) idx2 += N;
                uint64_t val = (uint64_t)w1 * P[idx1] + (uint64_t)w2 * P[idx2];
                tmp[j] = (int)(val % MOD);
            }
            swap(P, tmp);
        };

        auto dfs = [&](auto&& self, int node, int l, int r) -> void {
            bool has = !seg[node].empty();
            vector<int> backup;
            if (has) {
                backup = P;
                for (const auto& f : seg[node]) {
                    apply_factor(f);
                }
            }

            if (l == r) {
                int maxc = 0;
                cdist[0] = 1;

                for (int rprob : groupCows[l]) {
                    if (rprob == 1) {
                        for (int c = maxc + 1; c >= 1; --c) {
                            cdist[c] = cdist[c - 1];
                        }
                        cdist[0] = 0;
                        ++maxc;
                    } else {
                        cdist[maxc + 1] = 0;
                        int nr = (1 - rprob + MOD) % MOD;
                        for (int c = maxc + 1; c >= 1; --c) {
                            cdist[c] = ((long long)cdist[c] * nr + (long long)cdist[c - 1] * rprob) % MOD;
                        }
                        cdist[0] = (long long)cdist[0] * nr % MOD;
                        ++maxc;
                    }
                }

                int run = 0;
                for (int c = maxc; c >= 0; --c) {
                    suff[c] = run;
                    run += cdist[c];
                    if (run >= MOD) run -= MOD;
                }

                long long ans = 0;
                int lim = min(N - 1, maxc - 1);
                for (int s = 0; s <= lim; ++s) {
                    ans = (ans + (long long)P[s] * suff[s]) % MOD;
                }
                ans_g[l] = (int)ans;
            } else {
                int mid = (l + r) / 2;
                self(self, node * 2, l, mid);
                self(self, node * 2 + 1, mid + 1, r);
            }

            if (has) {
                P = backup;
            }
        };

        dfs(dfs, 1, 0, G - 1);

        vector<int> out(M, 0);
        for (int g = 0; g < G; ++g) {
            out[qs[g]] = ans_g[g];
        }

        for (int i = 0; i < M; ++i) {
            if (i) cout << ' ';
            cout << out[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

long long mod_pow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long floor_div(long long a, long long b) {
    // b > 0
    if (a >= 0) return a / b;
    return -((-a + b - 1) / b);
}

struct Factor {
    int a, b;
    int p, q;
};

struct Solver {
    int N, M;
    long long K;
    vector<int> p, x;
    vector<int> a, b;       // residues for CW and CCW
    vector<int> wp, wm;     // quotient mod N
    vector<int> probCW, probCCW;

    vector<int> pos;
    vector<vector<int>> Slist;
    vector<int> posToIndex;
    int Q;

    vector<int> ans;

    Solver(int _N, int _M, long long _K, vector<int>& _p, vector<int>& _x)
        : N(_N), M(_M), K(_K), p(_p), x(_x) {
        probCW = p;
        probCCW.resize(N);
        for (int i = 0; i < N; i++) {
            probCCW[i] = (1 - p[i] + MOD) % MOD;
        }

        a.resize(N);
        b.resize(N);
        wp.resize(N);
        wm.resize(N);

        long long km = K % M;

        for (int i = 0; i < N; i++) {
            long long ai = ((long long)x[i] + km) % M;
            long long bi = ((long long)x[i] - km) % M;
            if (bi < 0) bi += M;
            a[i] = (int)ai;
            b[i] = (int)bi;

            long long qp = ((long long)x[i] + K) / M;
            long long qm = floor_div((long long)x[i] - K, M);

            int vp = qp % N;
            if (vp < 0) vp += N;
            int vm = qm % N;
            if (vm < 0) vm += N;
            wp[i] = vp;
            wm[i] = vm;
        }

        buildEvents();
        ans.assign(M, 0);
    }

    void buildEvents() {
        vector<pair<int,int>> ev;
        ev.reserve(2 * N);
        for (int i = 0; i < N; i++) {
            ev.push_back({a[i], i});
            ev.push_back({b[i], i});
        }
        sort(ev.begin(), ev.end());

        int idx = 0;
        while (idx < (int)ev.size()) {
            int curPos = ev[idx].first;
            vector<int> cows;
            while (idx < (int)ev.size() && ev[idx].first == curPos) {
                int cow = ev[idx].second;
                if (cows.empty() || cows.back() != cow) cows.push_back(cow);
                idx++;
            }
            pos.push_back(curPos);
            Slist.push_back(cows);
        }

        Q = (int)pos.size();
        posToIndex.assign(M, -1);
        for (int i = 0; i < Q; i++) posToIndex[pos[i]] = i;
    }

    void applyFactor(vector<int>& dp, int aa, int bb, int prob, vector<int>& temp) {
        int qq = (1 - prob + MOD) % MOD;
        aa %= N;
        bb %= N;

        if (prob == 0) {
            if (qq == 1 && bb == 0) return;
            for (int k = 0; k < N; k++) {
                int id = k - bb;
                if (id < 0) id += N;
                temp[k] = dp[id];
            }
            dp.swap(temp);
            return;
        }
        if (qq == 0) {
            if (prob == 1 && aa == 0) return;
            for (int k = 0; k < N; k++) {
                int id = k - aa;
                if (id < 0) id += N;
                temp[k] = dp[id];
            }
            dp.swap(temp);
            return;
        }
        if (aa == bb) {
            if (aa == 0) return;
            for (int k = 0; k < N; k++) {
                int id = k - aa;
                if (id < 0) id += N;
                temp[k] = dp[id];
            }
            dp.swap(temp);
            return;
        }

        for (int k = 0; k < N; k++) {
            int i1 = k - aa;
            if (i1 < 0) i1 += N;
            int i2 = k - bb;
            if (i2 < 0) i2 += N;
            long long val = 1LL * prob * dp[i1] + 1LL * qq * dp[i2];
            temp[k] = val % MOD;
        }
        dp.swap(temp);
    }

    bool deconvolve(vector<int>& dp, int aa, int bb, int prob) {
        aa %= N;
        bb %= N;
        int qq = (1 - prob + MOD) % MOD;

        if (aa == bb) {
            vector<int> temp(N);
            for (int k = 0; k < N; k++) {
                int id = k + aa;
                if (id >= N) id -= N;
                temp[k] = dp[id];
            }
            dp.swap(temp);
            return true;
        }

        vector<int> H(N);
        for (int k = 0; k < N; k++) {
            int id = k + aa;
            if (id >= N) id -= N;
            H[k] = dp[id];
        }

        int d = (bb - aa) % N;
        if (d < 0) d += N;

        if (prob == 0) {
            int invq = mod_pow(qq, MOD - 2);
            vector<int> temp(N);
            for (int k = 0; k < N; k++) {
                int id = k + d;
                if (id >= N) id -= N;
                temp[k] = 1LL * H[id] * invq % MOD;
            }
            dp.swap(temp);
            return true;
        }

        if (qq == 0) {
            int invp = mod_pow(prob, MOD - 2);
            for (int k = 0; k < N; k++) {
                dp[k] = 1LL * H[k] * invp % MOD;
            }
            return true;
        }

        int g = std::gcd(N, d);
        int L = N / g;
        int invp = mod_pow(prob, MOD - 2);

        int base = (MOD - 1LL * qq * invp % MOD) % MOD;
        int Blast = (int)mod_pow(base, L);
        int denom = (1 - Blast + MOD) % MOD;
        if (denom == 0) return false;

        int invden = mod_pow(denom, MOD - 2);
        vector<int> temp(N);

        for (int s = 0; s < g; s++) {
            long long A = 0;
            int k = s;
            for (int j = 0; j < L; j++) {
                long long D = H[k];
                long long val = (D - 1LL * qq * A % MOD + MOD) % MOD;
                A = val * invp % MOD;
                k += d;
                if (k >= N) k %= N;
            }

            int x = (long long)A * invden % MOD;
            long long prev = x;

            k = s;
            for (int j = 0; j < L; j++) {
                long long D = H[k];
                long long Gval = (D - 1LL * qq * prev % MOD + MOD) % MOD;
                Gval = Gval * invp % MOD;
                temp[k] = (int)Gval;
                prev = Gval;
                k += d;
                if (k >= N) k %= N;
            }
        }

        dp.swap(temp);
        return true;
    }

    bool fastSolve() {
        fill(ans.begin(), ans.end(), 0);

        vector<int> qplus = wp;
        vector<int> qminus = wm;
        vector<int> dp(N, 0), temp(N);
        dp[0] = 1;

        // At the first event, no residue has been passed yet.
        for (int i = 0; i < N; i++) {
            applyFactor(dp, qplus[i], qminus[i], probCW[i], temp);
        }

        for (int idx = 0; idx < Q; idx++) {
            int t = pos[idx];
            const vector<int>& S = Slist[idx];

            vector<int> G = dp;
            for (int cow : S) {
                if (!deconvolve(G, qplus[cow], qminus[cow], probCW[cow])) {
                    return false;
                }
            }

            int sz = (int)S.size();
            int val = 0;

            for (int mask = 0; mask < (1 << sz); mask++) {
                long long weight = 1;
                int QS = 0, e = 0;

                for (int j = 0; j < sz; j++) {
                    int cow = S[j];
                    int dir = (mask >> j) & 1;

                    if (dir == 0) {
                        QS += qplus[cow];
                        if (QS >= N) QS -= N;
                        if (a[cow] == t) e++;
                        weight = weight * probCW[cow] % MOD;
                    } else {
                        QS += qminus[cow];
                        if (QS >= N) QS -= N;
                        if (b[cow] == t) e++;
                        weight = weight * probCCW[cow] % MOD;
                    }
                }

                if (e > 0) {
                    long long contrib = 0;
                    for (int k = 0; k < e; k++) {
                        int id = (k - QS) % N;
                        if (id < 0) id += N;
                        contrib += G[id];
                        if (contrib >= MOD) contrib -= MOD;
                    }
                    val = (val + weight * contrib) % MOD;
                }
            }

            ans[t] = val;

            for (int cow : S) {
                int olda = qplus[cow];
                int oldb = qminus[cow];
                int newa = olda;
                int newb = oldb;

                if (a[cow] == t) {
                    newa--;
                    if (newa < 0) newa += N;
                }
                if (b[cow] == t) {
                    newb--;
                    if (newb < 0) newb += N;
                }

                if (newa != olda || newb != oldb) {
                    if (!deconvolve(dp, olda, oldb, probCW[cow])) {
                        return false;
                    }
                    applyFactor(dp, newa, newb, probCW[cow], temp);
                    qplus[cow] = newa;
                    qminus[cow] = newb;
                }
            }
        }

        return true;
    }

    void segmentSolve() {
        fill(ans.begin(), ans.end(), 0);

        int S = 1;
        while (S < Q) S <<= 1;

        vector<vector<Factor>> seg(2 * S);

        auto rangeAdd = [&](int l, int r, const Factor& f) {
            l += S;
            r += S;
            while (l < r) {
                if (l & 1) seg[l++].push_back(f);
                if (r & 1) seg[--r].push_back(f);
                l >>= 1;
                r >>= 1;
            }
        };

        for (int i = 0; i < N; i++) {
            int ida = posToIndex[a[i]];
            int idb = posToIndex[b[i]];

            vector<int> br = {0, Q, ida, ida + 1, idb, idb + 1};
            sort(br.begin(), br.end());
            br.erase(unique(br.begin(), br.end()), br.end());

            for (int k = 0; k + 1 < (int)br.size(); k++) {
                int l = br[k], r = br[k + 1];
                if (l >= r) continue;

                if (l == ida && r == ida + 1) continue;
                if (l == idb && r == idb + 1) continue;

                int t = pos[l];
                int qCW = wp[i];
                if (t > a[i]) {
                    qCW--;
                    if (qCW < 0) qCW += N;
                }
                int qCCW = wm[i];
                if (t > b[i]) {
                    qCCW--;
                    if (qCCW < 0) qCCW += N;
                }

                Factor f;
                f.a = qCW % N;
                f.b = qCCW % N;
                f.p = probCW[i];
                f.q = probCCW[i];
                rangeAdd(l, r, f);
            }
        }

        vector<vector<int>> buf(2, vector<int>(N, 0));
        vector<vector<int>> backup(20, vector<int>(N, 0));
        int cur = 0;
        buf[0][0] = 1;

        auto applyFactorSeg = [&](const Factor& f) {
            int aa = f.a, bb = f.b;
            int pp = f.p, qq = f.q;
            int* old = buf[cur].data();
            int* nw = buf[cur ^ 1].data();

            if (pp == 0) {
                if (qq == 1 && bb == 0) return;
                for (int k = 0; k < N; k++) {
                    int id = k - bb;
                    if (id < 0) id += N;
                    nw[k] = old[id];
                }
                cur ^= 1;
                return;
            }
            if (qq == 0) {
                if (pp == 1 && aa == 0) return;
                for (int k = 0; k < N; k++) {
                    int id = k - aa;
                    if (id < 0) id += N;
                    nw[k] = old[id];
                }
                cur ^= 1;
                return;
            }
            if (aa == bb) {
                if (aa == 0) return;
                for (int k = 0; k < N; k++) {
                    int id = k - aa;
                    if (id < 0) id += N;
                    nw[k] = old[id];
                }
                cur ^= 1;
                return;
            }

            for (int k = 0; k < N; k++) {
                int i1 = k - aa;
                if (i1 < 0) i1 += N;
                int i2 = k - bb;
                if (i2 < 0) i2 += N;
                long long val = 1LL * pp * old[i1] + 1LL * qq * old[i2];
                nw[k] = val % MOD;
            }
            cur ^= 1;
        };

        function<void(int,int,int,int)> dfs = [&](int node, int l, int r, int depth) {
            int entryCur = cur;
            bool has = !seg[node].empty();

            if (has) {
                memcpy(backup[depth].data(), buf[cur].data(), N * sizeof(int));
                for (const Factor& f : seg[node]) {
                    applyFactorSeg(f);
                }
            }

            if (node >= S) {
                int leaf = node - S;
                if (leaf < Q) {
                    int t = pos[leaf];
                    const vector<int>& cows = Slist[leaf];
                    int sz = (int)cows.size();
                    int val = 0;

                    for (int mask = 0; mask < (1 << sz); mask++) {
                        long long weight = 1;
                        int QS = 0, e = 0;

                        for (int j = 0; j < sz; j++) {
                            int cow = cows[j];
                            int dir = (mask >> j) & 1;

                            if (dir == 0) {
                                int q = wp[cow];
                                if (t > a[cow]) {
                                    q--;
                                    if (q < 0) q += N;
                                }
                                QS += q;
                                if (QS >= N) QS -= N;
                                if (a[cow] == t) e++;
                                weight = weight * probCW[cow] % MOD;
                            } else {
                                int q = wm[cow];
                                if (t > b[cow]) {
                                    q--;
                                    if (q < 0) q += N;
                                }
                                QS += q;
                                if (QS >= N) QS -= N;
                                if (b[cow] == t) e++;
                                weight = weight * probCCW[cow] % MOD;
                            }
                        }

                        if (e > 0) {
                            long long contrib = 0;
                            for (int k = 0; k < e; k++) {
                                int id = (k - QS) % N;
                                if (id < 0) id += N;
                                contrib += buf[cur][id];
                                if (contrib >= MOD) contrib -= MOD;
                            }
                            val = (val + weight * contrib) % MOD;
                        }
                    }

                    ans[t] = val;
                }
            } else {
                int mid = (l + r) >> 1;
                if (l < Q) dfs(node * 2, l, mid, depth + 1);
                if (mid < Q) dfs(node * 2 + 1, mid, r, depth + 1);
            }

            if (has) {
                cur = entryCur;
                memcpy(buf[cur].data(), backup[depth].data(), N * sizeof(int));
            }
        };

        dfs(1, 0, S, 0);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N, M;
        long long K;
        cin >> N >> M >> K;

        vector<int> p(N), x(N);
        for (int i = 0; i < N; i++) cin >> p[i];
        for (int i = 0; i < N; i++) cin >> x[i];

        Solver solver(N, M, K, p, x);

        if (!solver.fastSolve()) {
            solver.segmentSolve();
        }

        for (int i = 0; i < M; i++) {
            if (i) cout << ' ';
            cout << solver.ans[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;

struct Factor {
    int a, b, p; // p * x^a + (1-p) * x^b
};

long long floor_div(long long a, long long b) {
    if (a >= 0) return a / b;
    return - ((-a + b - 1) / b);
}

int mod_pos(long long a, long long b) {
    int r = (int)(a % b);
    if (r < 0) r += (int)b;
    return r;
}

struct Solver {
    int N, M;
    long long K;

    vector<int> p, q, x;
    vector<int> rp, rm, basep, basem;

    vector<int> positions;
    int Q;

    vector<vector<int>> special;
    vector<vector<Factor>> seg;
    vector<int> diff, offsetAt, ans;
    vector<int> tempArr;

    void addFactor(int idx, int l, int r, int ql, int qr, const Factor& f) {
        if (ql >= r || qr <= l) return;
        if (ql <= l && r <= qr) {
            seg[idx].push_back(f);
            return;
        }
        int m = (l + r) >> 1;
        addFactor(idx << 1, l, m, ql, qr, f);
        addFactor(idx << 1 | 1, m, r, ql, qr, f);
    }

    void applyFactor(vector<int>& cur, const Factor& f) {
        int a = f.a, b = f.b, pj = f.p;
        int *c = cur.data();
        int *t = tempArr.data();

        for (int i = 0; i < N; i++) {
            int i1 = i - a;
            if (i1 < 0) i1 += N;
            int i2 = i - b;
            if (i2 < 0) i2 += N;

            int d = c[i1] - c[i2];
            if (d < 0) d += MOD;

            long long v = (long long)pj * d % MOD;
            int res = c[i2] + (int)v;
            if (res >= MOD) res -= MOD;
            t[i] = res;
        }
        cur.swap(tempArr);
    }

    void processLeaf(int idx, vector<int>& cur) {
        int posi = positions[idx];
        auto& vec = special[idx];
        int s = (int)vec.size();
        int masks = 1 << s;
        int offset = offsetAt[idx];

        long long resAns = 0;

        for (int mask = 0; mask < masks; mask++) {
            long long prob = 1;
            int E = 0;
            int fixed = 0;

            for (int jj = 0; jj < s; jj++) {
                int cow = vec[jj];
                int res, base;

                if (mask & (1 << jj)) {
                    res = rp[cow];
                    base = basep[cow];
                    prob = prob * p[cow] % MOD;
                } else {
                    res = rm[cow];
                    base = basem[cow];
                    prob = prob * q[cow] % MOD;
                }

                int sub = (res < posi ? 1 : 0);
                int h = base - sub;
                if (h < 0) h += N;

                fixed += h;
                if (fixed >= N) fixed -= N;

                if (res == posi) E++;
            }

            if (prob == 0 || E == 0) continue;

            for (int t = 0; t < E; t++) {
                int sOther = t - fixed;
                sOther %= N;
                if (sOther < 0) sOther += N;

                int qidx = sOther - offset;
                qidx %= N;
                if (qidx < 0) qidx += N;

                long long add = prob * cur[qidx] % MOD;
                resAns += add;
                if (resAns >= MOD) resAns -= MOD;
            }
        }

        ans[posi] = (int)(resAns % MOD);
    }

    void dfs(int idx, int l, int r, vector<int>& cur) {
        vector<int> saved;
        bool needSave = false;

        for (const Factor& f : seg[idx]) {
            if (!needSave) {
                saved = cur;
                needSave = true;
            }
            applyFactor(cur, f);
        }

        if (l + 1 == r) {
            processLeaf(l, cur);
        } else {
            int m = (l + r) >> 1;
            dfs(idx << 1, l, m, cur);
            dfs(idx << 1 | 1, m, r, cur);
        }

        if (needSave) {
            cur = move(saved);
        }
    }

    void solve() {
        cin >> N >> M >> K;

        p.resize(N);
        q.resize(N);
        for (int i = 0; i < N; i++) {
            cin >> p[i];
            q[i] = 1 - p[i];
            if (q[i] < 0) q[i] += MOD;
        }

        x.resize(N);
        for (int i = 0; i < N; i++) cin >> x[i];

        rp.resize(N);
        rm.resize(N);
        basep.resize(N);
        basem.resize(N);

        vector<int> allPos;
        allPos.reserve(2 * N);

        for (int i = 0; i < N; i++) {
            long long yp = (long long)x[i] + K;
            long long ym = (long long)x[i] - K;

            int bp = (int)(floor_div(yp, M) % N);
            if (bp < 0) bp += N;
            int bm = (int)(floor_div(ym, M) % N);
            if (bm < 0) bm += N;

            basep[i] = bp;
            basem[i] = bm;

            rp[i] = mod_pos(yp, M);
            rm[i] = mod_pos(ym, M);

            allPos.push_back(rp[i]);
            allPos.push_back(rm[i]);
        }

        sort(allPos.begin(), allPos.end());
        allPos.erase(unique(allPos.begin(), allPos.end()), allPos.end());

        positions = move(allPos);
        Q = (int)positions.size();

        special.assign(Q, {});

        for (int i = 0; i < N; i++) {
            int idx = lower_bound(positions.begin(), positions.end(), rp[i]) - positions.begin();
            special[idx].push_back(i);

            if (rm[i] != rp[i]) {
                idx = lower_bound(positions.begin(), positions.end(), rm[i]) - positions.begin();
                special[idx].push_back(i);
            }
        }

        diff.assign(Q + 1, 0);
        seg.assign(4 * Q + 5, {});
        tempArr.assign(N, 0);

        for (int i = 0; i < N; i++) {
            int rpi = rp[i], rmi = rm[i];

            int c1 = upper_bound(positions.begin(), positions.end(), rpi) - positions.begin();
            int c2 = upper_bound(positions.begin(), positions.end(), rmi) - positions.begin();

            int e1 = lower_bound(positions.begin(), positions.end(), rpi) - positions.begin();
            int e2 = lower_bound(positions.begin(), positions.end(), rmi) - positions.begin();

            vector<int> bounds = {0, Q, c1, c2};
            sort(bounds.begin(), bounds.end());
            bounds.erase(unique(bounds.begin(), bounds.end()), bounds.end());

            for (int bi = 0; bi + 1 < (int)bounds.size(); bi++) {
                int L = bounds[bi];
                int R = bounds[bi + 1];
                if (L >= R) continue;

                vector<int> cuts = {L, R};

                if (e1 >= L && e1 < R) {
                    cuts.push_back(e1);
                    cuts.push_back(e1 + 1);
                }
                if (e2 != e1 && e2 >= L && e2 < R) {
                    cuts.push_back(e2);
                    cuts.push_back(e2 + 1);
                }

                sort(cuts.begin(), cuts.end());
                cuts.erase(unique(cuts.begin(), cuts.end()), cuts.end());

                for (int k = 0; k + 1 < (int)cuts.size(); k++) {
                    int l = cuts[k];
                    int r = cuts[k + 1];
                    if (l >= r) continue;

                    if (r - l == 1 && (l == e1 || l == e2)) continue;

                    int hp = basep[i] - (positions[l] > rpi ? 1 : 0);
                    if (hp < 0) hp += N;

                    int hm = basem[i] - (positions[l] > rmi ? 1 : 0);
                    if (hm < 0) hm += N;

                    int pj = p[i];

                    if (pj == 0) {
                        int shift = hm;
                        diff[l] += shift;
                        if (diff[l] >= N) diff[l] -= N;
                        diff[r] -= shift;
                        if (diff[r] < 0) diff[r] += N;
                    } else if (pj == 1) {
                        int shift = hp;
                        diff[l] += shift;
                        if (diff[l] >= N) diff[l] -= N;
                        diff[r] -= shift;
                        if (diff[r] < 0) diff[r] += N;
                    } else if (hp == hm) {
                        int shift = hp;
                        diff[l] += shift;
                        if (diff[l] >= N) diff[l] -= N;
                        diff[r] -= shift;
                        if (diff[r] < 0) diff[r] += N;
                    } else {
                        Factor f{hp, hm, pj};
                        addFactor(1, 0, Q, l, r, f);
                    }
                }
            }
        }

        offsetAt.assign(Q, 0);
        int curShift = 0;

        for (int i = 0; i < Q; i++) {
            curShift += diff[i];
            curShift %= N;
            if (curShift < 0) curShift += N;
            offsetAt[i] = curShift;
        }

        ans.assign(M, 0);

        vector<int> cur(N, 0);
        cur[0] = 1;

        dfs(1, 0, Q, cur);

        for (int i = 0; i < M; i++) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }
};

