#include <bits/stdc++.h>
using namespace std;

static constexpr int MOD = 1'000'000'007;

int addmod(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

int submod(int a, int b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}

int mulmod(int a, int b) {
    return int(1LL * a * b % MOD);
}

int modpow(int a, long long e) {
    int r = 1;
    while (e > 0) {
        if (e & 1) r = mulmod(r, a);
        a = mulmod(a, a);
        e >>= 1;
    }
    return r;
}

struct Cow {
    int x;
    int cw, ccw;
    int invCw, invCc;
};

struct Event {
    int y;
    int type; // 0: clockwise endpoint, 1: counterclockwise endpoint
    int cow;

    bool operator<(const Event& other) const {
        if (y != other.y) return y < other.y;
        return type < other.type;
    }
};

// Multiplies a polynomial A(z) by q + p*z.
vector<int> multiplyFactor(const vector<int>& a, const Cow& c) {
    int n = int(a.size());
    vector<int> result(n + 1, 0);

    for (int i = 0; i <= n; ++i) {
        long long value = 0;
        if (i < n) value += 1LL * c.ccw * a[i];
        if (i > 0) value += 1LL * c.cw * a[i - 1];
        result[i] = int(value % MOD);
    }
    return result;
}

// Divides a polynomial known to be divisible by q + p*z.
// The size of a is the conceptual number of factors plus one.
vector<int> divideFactor(const vector<int>& a, const Cow& c) {
    int degree = int(a.size()) - 1;
    vector<int> result(degree, 0);

    if (c.ccw != 0) {
        int previous = 0;
        for (int k = 0; k < degree; ++k) {
            int value = submod(a[k], mulmod(c.cw, previous));
            result[k] = mulmod(value, c.invCc);
            previous = result[k];
        }
    } else {
        // q + p*z = p*z because q = 0.
        for (int k = 0; k < degree; ++k) {
            result[k] = mulmod(a[k + 1], c.invCw);
        }
    }

    return result;
}

// Builds A and B such that the cyclic convolution A*B represents
// t * (#CW outside the high set) + (t+1) * (#CW inside the high set).
void buildConvolutionPolynomials(
    const vector<int>& pin,
    const vector<int>& pout,
    int t,
    int n,
    vector<int>& A,
    vector<int>& B
) {
    A.assign(n, 0);
    B.assign(n, 0);

    int tm1 = (t + 1) % n;

    for (int v = 0; v < int(pout.size()); ++v) {
        int index = int(1LL * t * v % n);
        A[index] = addmod(A[index], pout[v]);
    }

    for (int u = 0; u < int(pin.size()); ++u) {
        int index = int(1LL * tm1 * u % n);
        B[index] = addmod(B[index], pin[u]);
    }
}

// Returns selected coefficients of the cyclic convolution A*B.
vector<int> convolutionCoefficients(
    const vector<int>& A,
    const vector<int>& B,
    const vector<int>& targets
) {
    int n = int(A.size());

    vector<pair<int, int>> sa, sb;
    sa.reserve(n);
    sb.reserve(n);

    for (int i = 0; i < n; ++i) {
        if (A[i] != 0) sa.emplace_back(i, A[i]);
        if (B[i] != 0) sb.emplace_back(i, B[i]);
    }

    vector<int> answer(targets.size(), 0);

    if (sa.size() <= sb.size()) {
        for (auto [index, value] : sa) {
            for (int k = 0; k < int(targets.size()); ++k) {
                int other = targets[k] - index;
                if (other < 0) other += n;
                answer[k] = addmod(
                    answer[k],
                    mulmod(value, B[other])
                );
            }
        }
    } else {
        for (auto [index, value] : sb) {
            for (int k = 0; k < int(targets.size()); ++k) {
                int other = targets[k] - index;
                if (other < 0) other += n;
                answer[k] = addmod(
                    answer[k],
                    mulmod(value, A[other])
                );
            }
        }
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N, M;
        long long K;
        cin >> N >> M >> K;

        vector<Cow> cows(N);

        for (int i = 0; i < N; ++i) {
            cin >> cows[i].cw;
            cows[i].ccw = (1 - cows[i].cw + MOD) % MOD;

            cows[i].invCw = cows[i].cw == 0 ? 0 : modpow(cows[i].cw, MOD - 2);
            cows[i].invCc = cows[i].ccw == 0 ? 0 : modpow(cows[i].ccw, MOD - 2);
        }

        for (int i = 0; i < N; ++i) {
            cin >> cows[i].x;
        }

        long long quotient = K / M;
        int remainder = int(K % M);

        int lowValue = (2LL * remainder >= M ? 1 : 0);
        int t = int((2LL * (quotient % N) + lowValue) % N);

        vector<int> h(N);
        vector<int> high(N, 0);

        int sumB = 0;
        for (int i = 0; i < N; ++i) {
            int a = (cows[i].x + remainder) / M;
            int b = (cows[i].x < remainder ? -1 : 0);
            h[i] = a - b;
            sumB += b;
            high[i] = (h[i] == lowValue + 1);
        }

        int bMod = (sumB % N + N) % N;

        auto buildPartition = [&](bool useHigh) {
            vector<int> polynomial(1, 1);
            for (int i = 0; i < N; ++i) {
                if (high[i] == useHigh) {
                    polynomial = multiplyFactor(polynomial, cows[i]);
                }
            }
            return polynomial;
        };

        vector<int> pin = buildPartition(true);
        vector<int> pout = buildPartition(false);

        vector<Event> events;
        events.reserve(2 * N);

        for (int i = 0; i < N; ++i) {
            int clockwiseEndpoint = int((cows[i].x + 1LL * remainder) % M);
            int counterclockwiseEndpoint =
                int((cows[i].x - 1LL * remainder + M) % M);

            events.push_back({clockwiseEndpoint, 0, i});
            events.push_back({counterclockwiseEndpoint, 1, i});
        }

        sort(events.begin(), events.end());

        vector<int> answer(M, 0);

        auto removeCow = [&](vector<int>& polynomial, int cow) {
            polynomial = divideFactor(polynomial, cows[cow]);
        };

        auto updateHigh = [&](int cow, bool newHigh) {
            if (high[cow] == newHigh) return;

            if (newHigh) {
                pin = multiplyFactor(pin, cows[cow]);
                pout = divideFactor(pout, cows[cow]);
            } else {
                pin = divideFactor(pin, cows[cow]);
                pout = multiplyFactor(pout, cows[cow]);
            }

            high[cow] = newHigh;
        };

        int pos = 0;
        while (pos < int(events.size())) {
            int end = pos;
            int y = events[pos].y;

            while (end < int(events.size()) && events[end].y == y) {
                ++end;
            }

            int cp = -1; // Unique cow whose clockwise endpoint is y.
            int cm = -1; // Unique cow whose counterclockwise endpoint is y.

            for (int j = pos; j < end; ++j) {
                if (events[j].type == 0) cp = events[j].cow;
                else cm = events[j].cow;
            }

            int s0 = (N - bMod) % N;
            int s1 = (s0 + 1) % N;

            vector<int> A, B;

            if (cp >= 0 && cm >= 0 && cp == cm) {
                // This cow reaches y regardless of its direction.
                vector<int> pinRest = pin;
                vector<int> poutRest = pout;

                if (high[cp]) removeCow(pinRest, cp);
                else removeCow(poutRest, cp);

                buildConvolutionPolynomials(
                    pinRest, poutRest, t, N, A, B
                );

                int shiftClockwise = (t + high[cp]) % N;
                int targetClockwise = (s0 - shiftClockwise + N) % N;

                vector<int> coefficients = convolutionCoefficients(
                    A, B, {targetClockwise, s0}
                );

                int probability = 0;
                probability = addmod(
                    probability,
                    mulmod(cows[cp].cw, coefficients[0])
                );
                probability = addmod(
                    probability,
                    mulmod(cows[cp].ccw, coefficients[1])
                );

                answer[y] = probability;
            } else if (cp >= 0 && cm >= 0) {
                // Distinct cows can have their endpoints coincide at y.
                vector<int> pinRest = pin;
                vector<int> poutRest = pout;

                if (high[cp]) removeCow(pinRest, cp);
                else removeCow(poutRest, cp);

                if (high[cm]) removeCow(pinRest, cm);
                else removeCow(poutRest, cm);

                buildConvolutionPolynomials(
                    pinRest, poutRest, t, N, A, B
                );

                int zcp = high[cp];
                int zcm = high[cm];

                // Both clockwise: only cp reaches y; D must be 0.
                int shiftBothCW = (2 * t + zcp + zcm) % N;

                // Both counterclockwise: only cm reaches y; D must be 0.
                int shiftBothCCW = 0;

                // cp clockwise and cm counterclockwise: both reach y;
                // D may be 0 or 1.
                int shiftMixed = (t + zcp) % N;

                vector<int> targets = {
                    (s0 - shiftBothCW + N) % N,
                    s0,
                    (s0 - shiftMixed + N) % N,
                    (s1 - shiftMixed + N) % N
                };

                vector<int> coefficients =
                    convolutionCoefficients(A, B, targets);

                int probability = 0;

                probability = addmod(
                    probability,
                    mulmod(
                        mulmod(cows[cp].cw, cows[cm].cw),
                        coefficients[0]
                    )
                );

                probability = addmod(
                    probability,
                    mulmod(
                        mulmod(cows[cp].ccw, cows[cm].ccw),
                        coefficients[1]
                    )
                );

                probability = addmod(
                    probability,
                    mulmod(
                        mulmod(cows[cp].cw, cows[cm].ccw),
                        coefficients[2]
                    )
                );

                probability = addmod(
                    probability,
                    mulmod(
                        mulmod(cows[cp].cw, cows[cm].ccw),
                        coefficients[3]
                    )
                );

                answer[y] = probability;
            } else if (cp >= 0) {
                // Only the clockwise endpoint of cp is y.
                vector<int> pinRest = pin;
                vector<int> poutRest = pout;

                if (high[cp]) removeCow(pinRest, cp);
                else removeCow(poutRest, cp);

                buildConvolutionPolynomials(
                    pinRest, poutRest, t, N, A, B
                );

                int shift = (t + high[cp]) % N;
                int target = (s0 - shift + N) % N;

                vector<int> coefficients =
                    convolutionCoefficients(A, B, {target});

                answer[y] = mulmod(cows[cp].cw, coefficients[0]);
            } else {
                // Only the counterclockwise endpoint of cm is y.
                vector<int> pinRest = pin;
                vector<int> poutRest = pout;

                if (high[cm]) removeCow(pinRest, cm);
                else removeCow(poutRest, cm);

                buildConvolutionPolynomials(
                    pinRest, poutRest, t, N, A, B
                );

                vector<int> coefficients =
                    convolutionCoefficients(A, B, {s0});

                answer[y] = mulmod(cows[cm].ccw, coefficients[0]);
            }

            // At an endpoint, the corresponding floor decreases only
            // after the coordinate itself has been processed.
            if (cp >= 0) --h[cp];

            if (cm >= 0) {
                ++h[cm];
                bMod = (bMod + N - 1) % N;
            }

            if (cp != cm) {
                if (cp >= 0) {
                    updateHigh(cp, h[cp] == lowValue + 1);
                }
                if (cm >= 0) {
                    updateHigh(cm, h[cm] == lowValue + 1);
                }
            }

            pos = end;
        }

        for (int i = 0; i < M; ++i) {
            if (i) cout << ' ';
            cout << answer[i];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int MOD = 1'000'000'007;

class FastScanner {
    static constexpr int SIZE = 1 << 16;
    char buffer[SIZE];
    int pos = 0, len = 0;

    int getChar() {
        if (pos == len) {
            len = (int)fread(buffer, 1, SIZE, stdin);
            pos = 0;
            if (len == 0) return EOF;
        }
        return buffer[pos++];
    }

public:
    template <class T>
    bool read(T &value) {
        int c;
        do {
            c = getChar();
            if (c == EOF) return false;
        } while (c <= ' ');

        bool negative = false;
        if (c == '-') {
            negative = true;
            c = getChar();
        }

        T result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = getChar();
        }

        value = negative ? -result : result;
        return true;
    }
};

class FastOutput {
    static constexpr int SIZE = 1 << 16;
    char buffer[SIZE];
    int pos = 0;

public:
    ~FastOutput() {
        flush();
    }

    void flush() {
        if (pos) {
            fwrite(buffer, 1, pos, stdout);
            pos = 0;
        }
    }

    void putChar(char c) {
        if (pos == SIZE) flush();
        buffer[pos++] = c;
    }

    void writeInt(int value, char after) {
        if (value == 0) {
            putChar('0');
        } else {
            char digits[12];
            int count = 0;
            while (value) {
                digits[count++] = char('0' + value % 10);
                value /= 10;
            }
            while (count) putChar(digits[--count]);
        }
        putChar(after);
    }
};

static int modPow(int base, int exponent) {
    long long result = 1;
    long long current = base;

    while (exponent) {
        if (exponent & 1) result = result * current % MOD;
        current = current * current % MOD;
        exponent >>= 1;
    }
    return (int)result;
}

static int oneMinus(int value) {
    int result = 1 - value;
    if (result < 0) result += MOD;
    return result;
}

/*
    Represents the polynomial a + b*z.

    If the relevant direction occurs with probability b, then:
      - coefficient a is the probability that it does not occur;
      - coefficient b*z is the probability that it occurs.
*/
struct Factor {
    int a, b;
    int inverseA;
    int ratio;  // b/a modulo MOD
};

static Factor makeFactor(int absent, int present) {
    Factor result;
    result.a = absent;
    result.b = present;

    if (result.a == 0) {
        result.inverseA = 0;
        result.ratio = 0;
    } else {
        result.inverseA = modPow(result.a, MOD - 2);
        result.ratio = (long long)result.b * result.inverseA % MOD;
    }
    return result;
}

struct Polynomial {
    vector<int> coefficient;

    Polynomial() : coefficient(1, 1) {}
};

/* Multiply p by a + b*z. */
static void multiplyLinear(Polynomial &p, const Factor &f) {
    if (f.b == 0) return;

    int oldSize = (int)p.coefficient.size();
    p.coefficient.resize(oldSize + 1, 0);

    if (f.a == 0) {
        // The factor is z.
        for (int k = oldSize; k >= 1; --k) {
            p.coefficient[k] = p.coefficient[k - 1];
        }
        p.coefficient[0] = 0;
        return;
    }

    for (int k = oldSize; k >= 1; --k) {
        long long value =
            (long long)f.a * p.coefficient[k] +
            (long long)f.b * p.coefficient[k - 1];
        p.coefficient[k] = (int)(value % MOD);
    }
    p.coefficient[0] = (long long)f.a * p.coefficient[0] % MOD;
}

/*
    Divide p exactly by a + b*z.

    If p = (a+bz)h and a != 0, then
        h[k] = p[k]/a - (b/a)h[k-1].

    If a == 0, the factor is z, so division is a coefficient shift.
*/
static void divideLinear(Polynomial &p, const Factor &f) {
    if (f.b == 0) return;

    int oldSize = (int)p.coefficient.size();

    if (f.a == 0) {
        for (int k = 0; k + 1 < oldSize; ++k) {
            p.coefficient[k] = p.coefficient[k + 1];
        }
        p.coefficient.resize(oldSize - 1);
        return;
    }

    p.coefficient[0] =
        (long long)p.coefficient[0] * f.inverseA % MOD;

    for (int k = 1; k + 1 < oldSize; ++k) {
        long long value =
            (long long)p.coefficient[k] * f.inverseA -
            (long long)f.ratio * p.coefficient[k - 1];
        value %= MOD;
        if (value < 0) value += MOD;
        p.coefficient[k] = (int)value;
    }

    p.coefficient.resize(oldSize - 1);
}

/*
    If clockwiseCandidate is true, candidate cow i is assumed to move
    clockwise. Relevant random variables are then "cow j moves CCW".

    Otherwise, candidate cow i is assumed to move counterclockwise, and
    relevant random variables are "cow j moves CW".
*/
static void processFamily(
    const vector<int> &x,
    const vector<int> &probability,
    int M,
    int kMod,
    long long q,
    int remaining,
    bool clockwiseCandidate,
    vector<int> &answer
) {
    const int N = (int)x.size();

    vector<Factor> factors(N);
    vector<int> ownProbability(N);

    for (int i = 0; i < N; ++i) {
        if (clockwiseCandidate) {
            // Relevant event: cow moves counterclockwise.
            factors[i] = makeFactor(probability[i], oneMinus(probability[i]));
            ownProbability[i] = probability[i];
        } else {
            // Relevant event: cow moves clockwise.
            factors[i] = makeFactor(oneMinus(probability[i]), probability[i]);
            ownProbability[i] = oneMinus(probability[i]);
        }
    }

    const int qMod = (int)(q % N);
    const int qPlusOne = (qMod + 1) % N;

    Polynomial windowPolynomial;
    Polynomial complementPolynomial;
    vector<int> residueSum(N);

    auto evaluateCandidate = [&](int i) {
        if (ownProbability[i] == 0) return;

        // The complement currently contains candidate i. Remove its factor,
        // since its relevant direction is fixed to be absent.
        Polynomial outside = complementPolynomial;
        divideLinear(outside, factors[i]);

        fill(residueSum.begin(), residueSum.end(), 0);

        for (int outsideCount = 0;
             outsideCount < (int)outside.coefficient.size();
             ++outsideCount) {
            int residue =
                (long long)qMod * outsideCount % N;

            int value = residueSum[residue] + outside.coefficient[outsideCount];
            if (value >= MOD) value -= MOD;
            residueSum[residue] = value;
        }

        int target = clockwiseCandidate ? (N - i) % N : i % N;

        __int128 total = 0;

        for (int insideCount = 0;
             insideCount < (int)windowPolynomial.coefficient.size();
             ++insideCount) {
            int needed = (
                target - (long long)qPlusOne * insideCount
            ) % N;
            if (needed < 0) needed += N;

            total += (__int128)windowPolynomial.coefficient[insideCount]
                     * residueSum[needed];
        }

        int eventProbability = (int)(total % MOD);
        int contribution =
            (long long)eventProbability * ownProbability[i] % MOD;

        int position;
        if (clockwiseCandidate) {
            position = x[i] + kMod;
            if (position >= M) position -= M;
        } else {
            position = x[i] - kMod;
            if (position < 0) position += M;
        }

        answer[position] += contribution;
        if (answer[position] >= MOD) answer[position] -= MOD;
    };

    auto enterWindow = [&](int cow) {
        divideLinear(complementPolynomial, factors[cow]);
        multiplyLinear(windowPolynomial, factors[cow]);
    };

    auto leaveWindow = [&](int cow) {
        divideLinear(windowPolynomial, factors[cow]);
        multiplyLinear(complementPolynomial, factors[cow]);
    };

    if (clockwiseCandidate) {
        // Forward window: (x[i], x[i] + remaining], clockwise.
        vector<int> doubledPosition(2 * N);
        for (int i = 0; i < N; ++i) {
            doubledPosition[i] = x[i];
            doubledPosition[i + N] = x[i] + M;
        }

        int end = 0;
        while (end + 1 < 2 * N &&
               doubledPosition[end + 1] <= x[0] + remaining) {
            ++end;
        }

        for (int cow = 0; cow < N; ++cow) {
            if (cow >= 1 && cow <= end) {
                multiplyLinear(windowPolynomial, factors[cow]);
            } else {
                multiplyLinear(complementPolynomial, factors[cow]);
            }
        }

        for (int i = 0; i < N; ++i) {
            evaluateCandidate(i);

            if (i + 1 == N) break;

            int oldEnd = end;
            int newEnd = oldEnd;

            while (newEnd + 1 < 2 * N &&
                   doubledPosition[newEnd + 1] <= x[i + 1] + remaining) {
                ++newEnd;
            }

            // Cow i+1 is the new candidate and leaves the old window
            // if it was present.
            if (oldEnd >= i + 1) {
                leaveWindow((i + 1) % N);
            }

            // The new window starts after cow i+1.
            int firstEntering = max(oldEnd + 1, i + 2);
            for (int k = firstEntering; k <= newEnd; ++k) {
                enterWindow(k % N);
            }

            end = newEnd;
        }
    } else {
        // Backward window: [x[i] - remaining, x[i]), clockwise.
        auto extendedPosition = [&](int index) -> int {
            if (index < 0) return x[index + N] - M;
            return x[index];
        };

        int left = -N;
        while (left + 1 <= 0 &&
               extendedPosition(left + 1) < x[0] - remaining) {
            ++left;
        }

        for (int cow = 0; cow < N; ++cow) {
            bool inside =
                cow != 0 && x[cow] >= M - remaining;

            if (inside) {
                multiplyLinear(windowPolynomial, factors[cow]);
            } else {
                multiplyLinear(complementPolynomial, factors[cow]);
            }
        }

        for (int i = 0; i < N; ++i) {
            evaluateCandidate(i);

            if (i + 1 == N) break;

            int oldLeft = left;
            int newLeft = oldLeft;

            while (newLeft + 1 <= i + 1 &&
                   extendedPosition(newLeft + 1) < x[i + 1] - remaining) {
                ++newLeft;
            }

            // Cows leaving through the left boundary.
            for (int k = oldLeft; k < newLeft && k < i; ++k) {
                int cow = k % N;
                if (cow < 0) cow += N;
                leaveWindow(cow);
            }

            // Cow i enters through the new right boundary, if the window
            // is nonempty.
            if (newLeft <= i) {
                enterWindow(i);
            }

            left = newLeft;
        }
    }
}

int main() {
    FastScanner scanner;
    FastOutput output;

    int T;
    scanner.read(T);

    while (T--) {
        int N, M;
        long long K;
        scanner.read(N);
        scanner.read(M);
        scanner.read(K);

        vector<int> probability(N), x(N);
        for (int &value : probability) scanner.read(value);
        for (int &value : x) scanner.read(value);

        long long twiceK = 2LL * K;
        long long q = twiceK / M;
        int remaining = (int)(twiceK % M);
        int kMod = (int)(K % M);

        vector<int> answer(M, 0);

        processFamily(
            x, probability, M, kMod, q, remaining,
            true, answer
        );

        processFamily(
            x, probability, M, kMod, q, remaining,
            false, answer
        );

        for (int i = 0; i < M; ++i) {
            output.writeInt(answer[i], i + 1 == M ? '\n' : ' ');
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

inline long long norm(long long x) {
    x %= MOD;
    if (x < 0) x += MOD;
    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> parent(N + 1), depth(N + 1);
    vector<vector<int>> children(N + 1);

    for (int v = 2; v <= N; ++v) {
        cin >> parent[v];
        depth[v] = depth[parent[v]] + 1;
        children[parent[v]].push_back(v);
    }

    vector<long long> invInt(N + 1);
    invInt[1] = 1;
    for (int i = 2; i <= N; ++i) {
        invInt[i] = MOD - (MOD / i) * invInt[MOD % i] % MOD;
    }

    // If a subtree contains no special boundary node, its root value is
    // A[v] + B[v] * (sum of values of its proper ancestors).
    vector<long long> A(N + 1), B(N + 1);
    vector<long long> sumA(N + 1), sumB(N + 1);

    for (int v = N; v >= 2; --v) {
        if (children[v].empty()) {
            A[v] = 1;
            B[v] = invInt[depth[v]];
        } else {
            long long d = (long long)children[v].size();
            long long den = norm(d - sumB[v]);
            long long invDen = modpow(den, MOD - 2);
            A[v] = norm(d + sumA[v]) * invDen % MOD;
            B[v] = sumB[v] * invDen % MOD;
        }

        int p = parent[v];
        sumA[p] = norm(sumA[p] + A[v]);
        sumB[p] = norm(sumB[p] + B[v]);
    }

    vector<long long> F(N + 1), SF(N + 1);       // Hitting time of the root.
    vector<long long> U(N + 1), SU(N + 1);       // Homogeneous path solution.
    vector<long long> R(N + 1), SR(N + 1);
    vector<long long> T(N + 1), ST(N + 1);
    vector<long long> prod(N + 1);

    R[1] = SR[1] = 1;
    prod[1] = 1;

    for (int v = 2; v <= N; ++v) {
        int u = parent[v];
        long long d = (long long)children[u].size();
        long long offA = norm(sumA[u] - A[v]);
        long long offB = norm(sumB[u] - B[v]);

        F[v] = norm(A[v] + B[v] * SF[u]);
        SF[v] = norm(SF[u] + F[v]);

        prod[v] = prod[u] * norm(1 + B[v]) % MOD;

        if (u == 1) {
            U[v] = 1;
            SU[v] = 1;
        } else {
            U[v] = norm(d * U[u] - offB * SU[u]);
            SU[v] = norm(SU[u] + U[v]);
        }

        R[v] = norm(d * R[u] - offB * SR[u]);
        T[v] = norm(d * T[u] - d - offA - offB * ST[u]);
        SR[v] = norm(SR[u] + R[v]);
        ST[v] = norm(ST[u] + T[v]);
    }

    vector<long long> invProd(N + 1), invU(N + 1), targetC(N + 1);

    for (int v = 1; v <= N; ++v) {
        invProd[v] = modpow(prod[v], MOD - 2);
    }

    for (int v = 2; v <= N; ++v) {
        invU[v] = modpow(U[v], MOD - 2);

        // Expected time from the root to v is -T[v]/R[v].
        // targetC[v] = F[v] + that expected time.
        targetC[v] = norm(F[v] - T[v] * modpow(R[v], MOD - 2));
    }

    int LOG = 1;
    while ((1 << LOG) <= N) ++LOG;

    vector<vector<int>> up(LOG, vector<int>(N + 1));
    up[0][1] = 1;
    for (int v = 2; v <= N; ++v) up[0][v] = parent[v];

    for (int k = 1; k < LOG; ++k) {
        for (int v = 1; v <= N; ++v) {
            up[k][v] = up[k - 1][up[k - 1][v]];
        }
    }

    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) swap(a, b);

        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; ++k) {
            if (diff & (1 << k)) a = up[k][a];
        }

        if (a == b) return a;

        for (int k = LOG - 1; k >= 0; --k) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return parent[a];
    };

    while (Q--) {
        int x, y;
        cin >> x >> y;

        if (x == y) {
            cout << 0 << '\n';
            continue;
        }

        if (y == 1) {
            cout << F[x] << '\n';
            continue;
        }

        int l = lca(x, y);
        long long r; // Probability of reaching y before the root.

        if (l == x) {
            // x is on the root-to-y path.
            r = U[x] * invU[y] % MOD;
        } else {
            long long k = B[x] * prod[parent[x]] % MOD;
            r = k * invProd[l] % MOD;
            r = r * SU[l] % MOD;
            r = r * invU[y] % MOD;
        }

        long long ans = norm(
            F[x] - F[y] + norm(1 - r) * targetC[y]
        );

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MOD = 1000000007;
using int64 = long long;

int modpow(int a, int e = MOD - 2) {
    int64 r = 1, x = a;
    while (e > 0) {
        if (e & 1) r = r * x % MOD;
        x = x * x % MOD;
        e >>= 1;
    }
    return (int)r;
}

// Transformation: z -> a*z + b*k + c (mod MOD).
struct Aff {
    int a = 1, b = 0, c = 0;
};

// Returns f(g(z)).
Aff compose(const Aff &f, const Aff &g) {
    Aff h;
    h.a = (int64)f.a * g.a % MOD;
    h.b = ((int64)f.a * g.b + f.b) % MOD;
    h.c = ((int64)f.a * g.c + f.c) % MOD;
    return h;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> parent(N + 1), depth(N + 1);
    vector<vector<int>> children(N + 1);

    for (int i = 2; i <= N; ++i) {
        cin >> parent[i];
        children[parent[i]].push_back(i);
        depth[i] = depth[parent[i]] + 1;
    }

    vector<int> inv(N + 1);
    inv[1] = 1;
    for (int i = 2; i <= N; ++i) {
        inv[i] = (int64)(MOD - MOD / i) * inv[MOD % i] % MOD;
    }

    // For every non-root v:
    // H(v,target) = A[v] + B[v] * (sum of H at strict ancestors of v),
    // provided the target is outside subtree(v).
    vector<int> A(N + 1), B(N + 1);
    for (int v = N; v >= 2; --v) {
        if (children[v].empty()) {
            A[v] = 1;
            B[v] = inv[depth[v]];
            continue;
        }

        int64 sumA = 0, sumB = 0;
        for (int c : children[v]) {
            sumA += A[c];
            sumB += B[c];
        }

        int k = (int)children[v].size();
        int avgA = sumA % MOD * inv[k] % MOD;
        int avgB = sumB % MOD * inv[k] % MOD;
        int den = 1 - avgB;
        if (den < 0) den += MOD;
        int invDen = modpow(den);

        A[v] = (int64)(1 + avgA) * invDen % MOD;
        B[v] = (int64)avgB * invDen % MOD;
    }

    int LOG = 1;
    while ((1 << LOG) <= N) ++LOG;

    vector<vector<int>> up(LOG, vector<int>(N + 1));
    for (int v = 2; v <= N; ++v) up[0][v] = parent[v];
    for (int k = 1; k < LOG; ++k) {
        for (int v = 1; v <= N; ++v) {
            up[k][v] = up[k - 1][up[k - 1][v]];
        }
    }

    // tr[k][v] describes the 2^k transformations on the path ending at v,
    // composed from top to bottom.
    vector<vector<Aff>> tr(LOG, vector<Aff>(N + 1));
    for (int v = 2; v <= N; ++v) {
        tr[0][v] = {(B[v] + 1) % MOD, B[v], A[v]};
    }

    for (int k = 1; k < LOG; ++k) {
        int len = 1 << k;
        for (int v = 2; v <= N; ++v) {
            if (depth[v] < len) continue;
            int mid = up[k - 1][v];
            // Bottom half is applied after the top half.
            tr[k][v] = compose(tr[k - 1][v], tr[k - 1][mid]);
        }
    }

    // P[v]: expected time to reach v from the root.
    // C[v]: sum of expected hitting times to v from all strict ancestors of v.
    vector<int> P(N + 1), C(N + 1), ancestorSumP(N + 1), hitParent(N + 1);

    for (int v = 1; v <= N; ++v) {
        if (children[v].empty()) continue;

        int64 sumR = 0;
        for (int c : children[v]) {
            hitParent[c] = (A[c] + (int64)B[c] * C[v]) % MOD;
            sumR += hitParent[c];
        }
        sumR %= MOD;

        int k = (int)children[v].size();
        for (int c : children[v]) {
            int edgeTime = (k + sumR - hitParent[c]) % MOD;
            if (edgeTime < 0) edgeTime += MOD;

            P[c] = (P[v] + edgeTime) % MOD;
            ancestorSumP[c] = (ancestorSumP[v] + P[v]) % MOD;

            C[c] = ((int64)depth[c] * P[c] - ancestorSumP[c]) % MOD;
            if (C[c] < 0) C[c] += MOD;
        }
    }

    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) swap(a, b);
        int diff = depth[a] - depth[b];
        for (int k = LOG - 1; k >= 0; --k) {
            if ((diff >> k) & 1) a = up[k][a];
        }
        if (a == b) return a;

        for (int k = LOG - 1; k >= 0; --k) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    };

    // Sum of hitting values strictly between ancestor a and descendant x,
    // including parent(x), expressed using the boundary value C[a].
    auto intermediateSum = [&](int x, int a) {
        int len = depth[x] - depth[a] - 1;
        if (len <= 0) return 0;

        int cur = parent[x];
        Aff result; // identity

        for (int k = 0; k < LOG; ++k) {
            if ((len >> k) & 1) {
                // The new block is above all previously processed blocks.
                result = compose(result, tr[k][cur]);
                cur = up[k][cur];
            }
        }

        return (int)(((int64)result.b * C[a] + result.c) % MOD);
    };

    // Expected time to reach ancestor a from descendant x.
    auto hitAncestor = [&](int x, int a) {
        int z = intermediateSum(x, a);
        int total = C[a] + z;
        if (total >= MOD) total -= MOD;
        return (int)((A[x] + (int64)B[x] * total) % MOD);
    };

    while (Q--) {
        int x, y;
        cin >> x >> y;

        int w = lca(x, y);
        int answer;

        if (w == y) {
            answer = (x == y) ? 0 : hitAncestor(x, y);
        } else if (w == x) {
            answer = P[y] - P[x];
            if (answer < 0) answer += MOD;
        } else {
            answer = ((int64)hitAncestor(x, w) + P[y] - P[w]) % MOD;
            if (answer < 0) answer += MOD;
        }

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e = MOD - 2) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> par(N + 1, 0), depth(N + 1, 0), deg(N + 1, 0);
    par[1] = 1;
    for (int v = 2; v <= N; ++v) {
        cin >> par[v];
        depth[v] = depth[par[v]] + 1;
        ++deg[par[v]];
    }

    vector<long long> invInt(N + 1, 0);
    invInt[1] = 1;
    for (int i = 2; i <= N; ++i) {
        invInt[i] = MOD - (MOD / i) * invInt[MOD % i] % MOD;
    }

    // For a node v, F_v = A[v] * P_parent(v) + B[v], where
    // P_v is the sum of F values on the root-to-v path.
    vector<long long> A(N + 1, 0), B(N + 1, 0);
    vector<long long> sumA(N + 1, 0), sumB(N + 1, 0);

    for (int v = N; v >= 2; --v) {
        if (deg[v] == 0) {
            A[v] = invInt[depth[v]];
            B[v] = 1;
        } else {
            long long avgA = sumA[v] * invInt[deg[v]] % MOD;
            long long avgB = sumB[v] * invInt[deg[v]] % MOD;
            long long den = (1 - avgA + MOD) % MOD;
            long long invDen = modpow(den);
            A[v] = avgA * invDen % MOD;
            B[v] = (1 + avgB) % MOD * invDen % MOD;
        }

        int p = par[v];
        sumA[p] = (sumA[p] + A[v]) % MOD;
        sumB[p] = (sumB[p] + B[v]) % MOD;
    }

    // G[v] = expected time to reach v starting from the root.
    // SG[v] = sum of G on the root-to-v path.
    vector<long long> G(N + 1, 0), SG(N + 1, 0);

    for (int v = 2; v <= N; ++v) {
        int p = par[v];
        long long invC = invInt[deg[p]];

        long long otherA = (sumA[p] - A[v] + MOD) % MOD;
        long long otherB = (sumB[p] - B[v] + MOD) % MOD;

        long long W = otherA * invC % MOD;
        long long Z = (1 + otherB * invC % MOD) % MOD;

        long long den = (1 - W * (depth[p] + 1LL) % MOD + MOD) % MOD;
        long long num = (G[p] - W * SG[p] % MOD + Z + MOD) % MOD;

        G[v] = num * modpow(den) % MOD;
        SG[v] = (SG[p] + G[v]) % MOD;
    }

    // S[a] is P_parent(a) when a is the target.
    vector<long long> S(N + 1, 0);
    for (int v = 2; v <= N; ++v) {
        S[v] = ((long long)depth[v] * G[v] - SG[par[v]]) % MOD;
        if (S[v] < 0) S[v] += MOD;
    }

    // Compositions of P_v = (1 + A[v]) * P_parent(v) + B[v].
    vector<long long> M(N + 1, 0), K(N + 1, 0), invM(N + 1, 0);
    M[1] = 1;
    K[1] = 0;
    invM[1] = 1;

    for (int v = 2; v <= N; ++v) {
        int p = par[v];
        long long u = (1 + A[v]) % MOD;
        M[v] = u * M[p] % MOD;
        K[v] = (u * K[p] + B[v]) % MOD;
    }
    for (int v = 2; v <= N; ++v) {
        invM[v] = modpow(M[v]);
    }

    int LOG = 1;
    while ((1 << LOG) <= N) ++LOG;

    vector<vector<int>> up(LOG, vector<int>(N + 1, 1));
    for (int v = 2; v <= N; ++v) up[0][v] = par[v];
    up[0][1] = 1;

    for (int j = 1; j < LOG; ++j) {
        for (int v = 1; v <= N; ++v) {
            up[j][v] = up[j - 1][up[j - 1][v]];
        }
    }

    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) swap(a, b);
        int diff = depth[a] - depth[b];

        for (int j = LOG - 1; j >= 0; --j) {
            if (diff & (1 << j)) a = up[j][a];
        }
        if (a == b) return a;

        for (int j = LOG - 1; j >= 0; --j) {
            if (up[j][a] != up[j][b]) {
                a = up[j][a];
                b = up[j][b];
            }
        }
        return up[0][a];
    };

    while (Q--) {
        int x, y;
        cin >> x >> y;

        int a = lca(x, y);
        long long answer = (G[y] - G[a] + MOD) % MOD;

        if (x != a) {
            // Expected time to go from x to its ancestor a.
            int px = par[x];
            long long ratio = M[px] * invM[a] % MOD;

            long long P = (ratio * S[a] % MOD + K[px]) % MOD;
            P = (P - ratio * K[a] % MOD + MOD) % MOD;

            long long hittingTime = (A[x] * P + B[x]) % MOD;
            answer = (answer + hittingTime) % MOD;
        }

        cout << answer << '\n';
    }

    return 0;
}

