#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> create_map(int N, int M, vector<int> A, vector<int> B) {
    vector<pair<int, int>> edges;
    vector<vector<int>> adj(N);

    for (int i = 0; i < M; i++) {
        int u = A[i] - 1;
        int v = B[i] - 1;
        edges.push_back({u, v});
        adj[u].push_back(i);
        adj[v].push_back(i);
    }

    vector<char> isTree(M, false);
    vector<vector<int>> tree(N);

    vector<int> parent(N, -1);
    queue<int> q;
    parent[0] = 0;
    q.push(0);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int ei : adj[u]) {
            int v = (edges[ei].first == u ? edges[ei].second : edges[ei].first);
            if (parent[v] == -1) {
                parent[v] = u;
                isTree[ei] = true;
                tree[u].push_back(v);
                tree[v].push_back(u);
                q.push(v);
            }
        }
    }

    vector<int> seq;

    function<void(int, int)> dfs = [&](int u, int p) {
        seq.push_back(u);
        for (int v : tree[u]) {
            if (v == p) continue;
            dfs(v, u);
            seq.push_back(u);
        }
    };

    dfs(0, -1);

    int L = (int)seq.size();
    int K = 3 * L;

    vector<vector<int>> C(K, vector<int>(K));

    for (int r = 0; r < K; r++) {
        for (int p = 0; p < L; p++) {
            int color = seq[p] + 1;
            for (int d = 0; d < 3; d++) {
                C[r][3 * p + d] = color;
            }
        }
    }

    vector<int> firstCol(N, -1);
    for (int p = 0; p < L; p++) {
        int v = seq[p];
        if (firstCol[v] == -1) {
            firstCol[v] = 3 * p + 1;
        }
    }

    vector<int> used(N, 0);

    for (int i = 0; i < M; i++) {
        if (!isTree[i]) {
            int u = edges[i].first;
            int v = edges[i].second;

            int host = v;
            int island = u;

            int r = 2 * used[host] + 1;
            int c = firstCol[host];

            C[r][c] = island + 1;
            used[host]++;
        }
    }

    return C;
}

