#include <bits/stdc++.h>
using namespace std;

using Mask = uint64_t;

class MaxCliqueSolver {
    int n;
    vector<Mask> adj;
    int bestSize = 0;
    Mask bestSet = 0;

    void colorSort(Mask candidates, vector<int>& order, vector<int>& colors) const {
        order.clear();
        colors.clear();

        Mask uncolored = candidates;
        int color = 0;

        while (uncolored) {
            ++color;
            Mask available = uncolored;

            while (available) {
                int v = __builtin_ctzll(available);
                Mask bit = Mask(1) << v;

                order.push_back(v);
                colors.push_back(color);

                uncolored &= ~bit;
                available &= ~bit;
                available &= ~adj[v];
            }
        }
    }

    void expand(Mask candidates, int size, Mask chosen) {
        if (size > bestSize) {
            bestSize = size;
            bestSet = chosen;
        }

        if (!candidates) return;

        vector<int> order, colors;
        colorSort(candidates, order, colors);

        for (int i = static_cast<int>(order.size()) - 1; i >= 0; --i) {
            if (size + colors[i] <= bestSize) return;

            int v = order[i];
            Mask bit = Mask(1) << v;
            Mask next = candidates & adj[v];

            expand(next, size + 1, chosen | bit);
            candidates &= ~bit;
        }
    }

public:
    explicit MaxCliqueSolver(vector<Mask> graph)
        : n(static_cast<int>(graph.size())), adj(std::move(graph)) {}

    Mask solve() {
        bestSize = 0;
        bestSet = 0;
        Mask all = (Mask(1) << n) - 1;
        expand(all, 0, 0);
        return bestSet;
    }
};

static vector<int> minimumVertexCover(const vector<Mask>& graph) {
    int n = static_cast<int>(graph.size());
    if (n == 0) return {};

    Mask all = (Mask(1) << n) - 1;
    Mask edgeCount = 0;

    for (Mask neighbors : graph) {
        edgeCount += __builtin_popcountll(neighbors);
    }

    if ((edgeCount & 1ULL) == 0 && edgeCount == 0) return {};

    vector<Mask> complement(n);
    for (int v = 0; v < n; ++v) {
        Mask bit = Mask(1) << v;
        complement[v] = all & ~(graph[v] | bit);
    }

    MaxCliqueSolver clique(std::move(complement));
    Mask independentSet = clique.solve();
    Mask cover = all & ~independentSet;

    vector<int> result;
    for (int v = 0; v < n; ++v) {
        if (cover & (Mask(1) << v)) result.push_back(v);
    }
    return result;
}

class GeneralMapSolver {
    using Tree = vector<vector<int>>;

    int n;
    vector<Mask> graph;
    vector<vector<int>> adjacency;

    struct Orientation {
        vector<vector<int>> targets;
        vector<int> load;
    };

    static int treeDiameter(const Tree& tree, int start) {
        int n = static_cast<int>(tree.size());
        vector<int> distance(n, -1), parent(n, -1);
        queue<int> q;

        distance[start] = 0;
        q.push(start);
        int farthest = start;

        while (!q.empty()) {
            int v = q.front();
            q.pop();

            if (distance[v] > distance[farthest]) farthest = v;

            for (int u : tree[v]) {
                if (distance[u] == -1) {
                    distance[u] = distance[v] + 1;
                    parent[u] = v;
                    q.push(u);
                }
            }
        }

        int other = farthest;
        while (parent[other] != -1) other = parent[other];
        return distance[farthest];
    }

    static vector<int> diameterPath(const Tree& tree) {
        int n = static_cast<int>(tree.size());

        auto bfs = [&](int source) {
            vector<int> distance(n, -1), parent(n, -1);
            queue<int> q;
            distance[source] = 0;
            q.push(source);

            while (!q.empty()) {
                int v = q.front();
                q.pop();

                for (int u : tree[v]) {
                    if (distance[u] == -1) {
                        distance[u] = distance[v] + 1;
                        parent[u] = v;
                        q.push(u);
                    }
                }
            }

            int farthest = source;
            for (int v = 0; v < n; ++v) {
                if (distance[v] > distance[farthest]) farthest = v;
            }

            return make_pair(farthest, parent);
        };

        int endpoint = bfs(0).first;
        auto result = bfs(endpoint);
        int other = result.first;
        const auto& parent = result.second;

        vector<int> path;
        while (other != -1) {
            path.push_back(other);
            other = parent[other];
        }
        reverse(path.begin(), path.end());
        return path;
    }

    static vector<int> buildTreeWalk(const Tree& tree) {
        vector<int> path = diameterPath(tree);
        vector<char> onPath(tree.size(), false);
        for (int v : path) onPath[v] = true;

        vector<int> walk;
        walk.push_back(path[0]);

        function<void(int, int)> tour = [&](int v, int parent) {
            walk.push_back(v);

            for (int u : tree[v]) {
                if (u == parent || onPath[u]) continue;
                tour(u, v);
                walk.push_back(v);
            }
        };

        for (int i = 0; i < static_cast<int>(path.size()); ++i) {
            int v = path[i];

            for (int u : tree[v]) {
                if (onPath[u]) continue;
                tour(u, v);
                walk.push_back(v);
            }

            if (i + 1 < static_cast<int>(path.size())) {
                walk.push_back(path[i + 1]);
            }
        }

        return walk;
    }

    vector<Mask> nonTreeEdges(const Tree& tree) const {
        vector<Mask> result(n, 0);
        for (int v = 0; v < n; ++v) {
            for (int u : tree[v]) {
                result[v] |= Mask(1) << u;
            }
        }

        for (int v = 0; v < n; ++v) {
            result[v] = graph[v] & ~result[v];
        }
        return result;
    }

    Orientation orientEdges(const vector<Mask>& edges,
                            const vector<int>& cover) const {
        Mask coverMask = 0;
        for (int v : cover) coverMask |= Mask(1) << v;

        struct Edge {
            int u, v;
            int options;
        };

        vector<Edge> edgeList;
        for (int u = 0; u < n; ++u) {
            for (int v = u + 1; v < n; ++v) {
                if (!(edges[u] & (Mask(1) << v))) continue;

                int options = 0;
                if (coverMask & (Mask(1) << u)) ++options;
                if (coverMask & (Mask(1) << v)) ++options;

                if (options > 0) edgeList.push_back({u, v, options});
            }
        }

        sort(edgeList.begin(), edgeList.end(),
             [](const Edge& a, const Edge& b) {
                 return a.options < b.options;
             });

        vector<int> load(n, 0), assigned(edgeList.size(), -1);

        for (int i = 0; i < static_cast<int>(edgeList.size()); ++i) {
            int u = edgeList[i].u;
            int v = edgeList[i].v;
            bool canU = coverMask & (Mask(1) << u);
            bool canV = coverMask & (Mask(1) << v);

            if (!canU && !canV) return {};

            int chosen;
            if (!canU) {
                chosen = v;
            } else if (!canV) {
                chosen = u;
            } else if (load[u] != load[v]) {
                chosen = load[u] < load[v] ? u : v;
            } else {
                int du = __builtin_popcountll(edges[u]);
                int dv = __builtin_popcountll(edges[v]);
                chosen = du >= dv ? u : v;
            }

            assigned[i] = chosen;
            ++load[chosen];
        }

        bool changed = true;
        while (changed) {
            changed = false;

            for (int i = 0; i < static_cast<int>(edgeList.size()); ++i) {
                int a = assigned[i];
                int b = edgeList[i].u ^ edgeList[i].v ^ a;

                if ((coverMask & (Mask(1) << b)) && load[a] > load[b] + 1) {
                    --load[a];
                    ++load[b];
                    assigned[i] = b;
                    changed = true;
                }
            }
        }

        Orientation result;
        result.load.assign(n, 0);
        result.targets.resize(n);

        for (int i = 0; i < static_cast<int>(edgeList.size()); ++i) {
            int a = assigned[i];
            int b = edgeList[i].u ^ edgeList[i].v ^ a;
            result.targets[a].push_back(b);
            ++result.load[a];
        }

        return result;
    }

    int estimateSize(const Tree& tree, const vector<int>& cover) const {
        vector<int> walk = buildTreeWalk(tree);
        vector<Mask> edges = nonTreeEdges(tree);
        Orientation orientation = orientEdges(edges, cover);

        int length = static_cast<int>(walk.size());
        int capacity = max(1, length / 2);
        int result = length;

        for (int v = 0; v < n; ++v) {
            int count = orientation.load[v];
            if (count == 0) continue;

            int interiorColumns = (count + capacity - 1) / capacity;
            result += interiorColumns + 1;
        }

        return result;
    }

    vector<vector<int>> construct(const Tree& tree,
                                  const vector<int>& cover) const {
        vector<int> walk = buildTreeWalk(tree);
        vector<Mask> edges = nonTreeEdges(tree);
        Orientation orientation = orientEdges(edges, cover);

        int length = static_cast<int>(walk.size());
        int capacity = max(1, length / 2);

        vector<int> firstPosition(n, -1);
        for (int i = 0; i < length; ++i) {
            if (firstPosition[walk[i]] == -1) firstPosition[walk[i]] = i;
        }

        vector<int> width(length, 1);
        for (int v = 0; v < n; ++v) {
            int count = orientation.load[v];
            if (count == 0) continue;

            int position = firstPosition[v];
            if (position == -1) return {};

            int interiorColumns = (count + capacity - 1) / capacity;
            width[position] = interiorColumns + 2;
        }

        int side = accumulate(width.begin(), width.end(), 0);
        if (side > 240) return {};

        vector<int> blockStart(length, 0);
        int currentStart = 0;
        for (int i = 0; i < length; ++i) {
            blockStart[i] = currentStart;
            currentStart += width[i];
        }

        vector<int> base;
        base.reserve(side);
        for (int i = 0; i < length; ++i) {
            for (int j = 0; j < width[i]; ++j) {
                base.push_back(walk[i]);
            }
        }

        vector<vector<int>> result(side, base);

        for (int v = 0; v < n; ++v) {
            if (orientation.targets[v].empty()) continue;

            int position = firstPosition[v];
            int count = orientation.load[v];
            int interiorColumns = (count + capacity - 1) / capacity;
            int start = blockStart[position];
            int targetIndex = 0;

            for (int column = start + 1;
                 column <= start + interiorColumns &&
                 targetIndex < static_cast<int>(orientation.targets[v].size());
                 ++column) {
                for (int row = 0;
                     row < side &&
                     targetIndex < static_cast<int>(orientation.targets[v].size());
                     ++row) {
                    if (((row + column) & 1) == 0) {
                        result[row][column] =
                            orientation.targets[v][targetIndex++];
                    }
                }
            }
        }

        return result;
    }

    bool validMap(const vector<vector<int>>& map) const {
        if (map.empty()) return false;

        int side = static_cast<int>(map.size());
        for (const auto& row : map) {
            if (static_cast<int>(row.size()) != side) return false;
        }

        vector<char> present(n, false);
        vector<Mask> seen(n, 0);

        for (int r = 0; r < side; ++r) {
            for (int c = 0; c < side; ++c) {
                int a = map[r][c];
                if (a < 0 || a >= n) return false;
                present[a] = true;

                if (r + 1 < side) {
                    int b = map[r + 1][c];
                    if (a != b) {
                        if (!(graph[a] & (Mask(1) << b))) return false;
                        seen[a] |= Mask(1) << b;
                    }
                }

                if (c + 1 < side) {
                    int b = map[r][c + 1];
                    if (a != b) {
                        if (!(graph[a] & (Mask(1) << b))) return false;
                        seen[a] |= Mask(1) << b;
                    }
                }
            }
        }

        for (int v = 0; v < n; ++v) {
            if (!present[v]) return false;
        }

        for (int u = 0; u < n; ++u) {
            for (int v = u + 1; v < n; ++v) {
                if ((graph[u] & (Mask(1) << v)) &&
                    !(seen[u] & (Mask(1) << v))) {
                    return false;
                }
            }
        }

        return true;
    }

    Tree breadthFirstTree() const {
        Tree tree(n);
        vector<char> visited(n, false);
        queue<int> q;
        visited[0] = true;
        q.push(0);

        while (!q.empty()) {
            int v = q.front();
            q.pop();

            for (int u : adjacency[v]) {
                if (!visited[u]) {
                    visited[u] = true;
                    tree[v].push_back(u);
                    tree[u].push_back(v);
                    q.push(u);
                }
            }
        }

        return tree;
    }

    Tree randomDepthFirstTree(mt19937& rng, int variant) const {
        Tree tree(n);
        vector<char> visited(n, false);

        function<void(int)> dfs = [&](int v) {
            visited[v] = true;
            vector<int> order = adjacency[v];

            if (variant == 0) {
                sort(order.begin(), order.end(), [&](int a, int b) {
                    return adjacency[a].size() < adjacency[b].size();
                });
            } else if (variant == 1) {
                sort(order.begin(), order.end(), [&](int a, int b) {
                    return adjacency[a].size() > adjacency[b].size();
                });
            } else {
                shuffle(order.begin(), order.end(), rng);
            }

            for (int u : order) {
                if (!visited[u]) {
                    tree[v].push_back(u);
                    tree[u].push_back(v);
                    dfs(u);
                }
            }
        };

        dfs(0);
        return tree;
    }

    Tree randomPrimTree(mt19937& rng) const {
        vector<vector<int>> weight(n, vector<int>(n, -1));

        for (int u = 0; u < n; ++u) {
            for (int v = u + 1; v < n; ++v) {
                if (graph[u] & (Mask(1) << v)) {
                    weight[u][v] = weight[v][u] = static_cast<int>(rng());
                }
            }
        }

        const int INF = numeric_limits<int>::max();
        vector<int> key(n, INF);
        vector<char> used(n, false);
        Tree tree(n);
        int root = static_cast<int>(rng() % n);
        key[root] = 0;

        for (int iteration = 0; iteration < n; ++iteration) {
            int v = -1;
            for (int u = 0; u < n; ++u) {
                if (!used[u] && (v == -1 || key[u] < key[v])) v = u;
            }

            if (v == -1) break;
            used[v] = true;

            for (int u = 0; u < n; ++u) {
                if (!used[u] && weight[v][u] >= 0 && weight[v][u] < key[u]) {
                    key[u] = weight[v][u];
                    tree[v].push_back(u);
                    tree[u].push_back(v);
                }
            }
        }

        return tree;
    }

    bool findHamiltonianPath(mt19937& rng, vector<int>& path) const {
        int leaves = 0;
        for (int v = 0; v < n; ++v) {
            if (adjacency[v].size() == 1) ++leaves;
        }
        if (leaves > 2) return false;

        vector<int> starts(n);
        iota(starts.begin(), starts.end(), 0);
        shuffle(starts.begin(), starts.end(), rng);

        for (int start : starts) {
            vector<char> visited(n, false);
            path.clear();
            path.push_back(start);
            visited[start] = true;
            int nodes = 0;
            const int LIMIT = 300000;

            function<bool(int)> dfs = [&](int v) {
                if (++nodes > LIMIT) return false;
                if (static_cast<int>(path.size()) == n) return true;

                vector<pair<int, int>> candidates;
                for (int u : adjacency[v]) {
                    if (visited[u]) continue;

                    int remaining = 0;
                    for (int w : adjacency[u]) {
                        if (!visited[w]) ++remaining;
                    }
                    candidates.push_back({remaining, u});
                }

                sort(candidates.begin(), candidates.end());

                for (auto [remaining, u] : candidates) {
                    if (nodes > LIMIT) break;
                    visited[u] = true;
                    path.push_back(u);

                    if (dfs(u)) return true;

                    path.pop_back();
                    visited[u] = false;
                }

                return false;
            };

            if (dfs(start)) return true;
        }

        return false;
    }

public:
    GeneralMapSolver(int vertexCount, const vector<Mask>& adjacencyMask)
        : n(vertexCount), graph(adjacencyMask), adjacency(n) {
        for (int v = 0; v < n; ++v) {
            for (int u = 0; u < n; ++u) {
                if (graph[v] & (Mask(1) << u)) adjacency[v].push_back(u);
            }
        }
    }

    vector<vector<int>> solve() {
        mt19937 rng(712367821U + static_cast<unsigned>(n));

        Tree bestTree;
        vector<int> bestCover;
        int bestSize = numeric_limits<int>::max();

        auto consider = [&](const Tree& tree) {
            if (static_cast<int>(tree.size()) != n) return;

            vector<int> walk = buildTreeWalk(tree);
            if (walk.empty()) return;

            vector<Mask> edges = nonTreeEdges(tree);
            vector<int> cover = minimumVertexCover(edges);
            int size = estimateSize(tree, cover);

            if (size < bestSize) {
                bestSize = size;
                bestTree = tree;
                bestCover = std::move(cover);
            }
        };

        consider(breadthFirstTree());

        for (int variant = 0; variant < 14; ++variant) {
            consider(randomDepthFirstTree(rng, variant));
        }

        for (int i = 0; i < 6; ++i) {
            consider(randomPrimTree(rng));
        }

        vector<int> path;
        if (findHamiltonianPath(rng, path)) {
            Tree pathTree(n);
            for (int i = 0; i + 1 < static_cast<int>(path.size()); ++i) {
                int u = path[i], v = path[i + 1];
                pathTree[u].push_back(v);
                pathTree[v].push_back(u);
            }
            consider(pathTree);
        }

        vector<vector<int>> answer = construct(bestTree, bestCover);

        if (!validMap(answer)) {
            vector<int> allVertices(n);
            iota(allVertices.begin(), allVertices.end(), 0);
            answer = construct(bestTree, allVertices);
        }

        return answer;
    }
};

static vector<pair<int, int>> roundRobinMatching(int size, int round) {
    vector<int> arrangement(size - 1);
    iota(arrangement.begin(), arrangement.end(), 0);

    int fixed = size - 1;
    vector<pair<int, int>> matching;
    matching.push_back({fixed, arrangement[round]});

    for (int i = 1; i <= (size - 2) / 2; ++i) {
        int a = arrangement[(round + i) % (size - 1)];
        int b = arrangement[(round - i + size - 1) % (size - 1)];
        matching.push_back({a, b});
    }

    return matching;
}

static vector<vector<int>> completeGraphMap(int n) {
    vector<vector<int>> result(n, vector<int>(n));

    if (n % 2 == 0) {
        for (int round = 0; round < n - 1; ++round) {
            auto matching = roundRobinMatching(n, round);
            int column = 0;

            for (auto [a, b] : matching) {
                result[round][column++] = a;
                result[round][column++] = b;
            }
        }

        for (int column = 0; column < n; ++column) {
            result[n - 1][column] = 0;
        }
    } else {
        for (int round = 0; round < n; ++round) {
            auto matching = roundRobinMatching(n + 1, round);
            int column = 0;
            int singleton = -1;

            for (auto [a, b] : matching) {
                if (a == n) {
                    singleton = b;
                } else if (b == n) {
                    singleton = a;
                } else {
                    result[round][column++] = a;
                    result[round][column++] = b;
                }
            }

            if (singleton != -1) result[round][column++] = singleton;
        }
    }

    return result;
}

static vector<vector<int>> starMap(int n) {
    int side = 2;
    while ((side * side) / 2 < n - 1) ++side;

    vector<vector<int>> result(side, vector<int>(side, 0));
    int nextLeaf = 1;

    for (int r = 0; r < side; ++r) {
        for (int c = 0; c < side; ++c) {
            if ((r + c) & 1) {
                result[r][c] = nextLeaf;
                if (++nextLeaf == n) nextLeaf = 1;
            }
        }
    }

    return result;
}

std::vector<std::vector<int>> create_map(int N, int M,
                                          std::vector<int> A,
                                          std::vector<int> B) {
    vector<Mask> adjacency(N, 0);

    for (int i = 0; i < M; ++i) {
        int u = A[i] - 1;
        int v = B[i] - 1;
        adjacency[u] |= Mask(1) << v;
        adjacency[v] |= Mask(1) << u;
    }

    bool complete = (M == N * (N - 1) / 2);
    if (complete) {
        for (int u = 0; u < N && complete; ++u) {
            if (__builtin_popcountll(adjacency[u]) != N - 1) complete = false;
        }
    }

    if (complete) {
        vector<vector<int>> answer = completeGraphMap(N);
        for (auto& row : answer) {
            for (int& color : row) ++color;
        }
        return answer;
    }

    int maximumDegree = 0;
    for (int v = 0; v < N; ++v) {
        maximumDegree = max(maximumDegree,
                            __builtin_popcountll(adjacency[v]));
    }

    if (N >= 3 && M == N - 1 && maximumDegree == N - 1) {
        vector<vector<int>> answer = starMap(N);
        for (auto& row : answer) {
            for (int& color : row) ++color;
        }
        return answer;
    }

    GeneralMapSolver solver(N, adjacency);
    vector<vector<int>> answer = solver.solve();

    for (auto& row : answer) {
        for (int& color : row) ++color;
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int N, M;
        cin >> N >> M;

        vector<int> A(M), B(M);
        for (int i = 0; i < M; ++i) {
