#include <bits/stdc++.h>
using namespace std;

struct Position {
    int x, y;
};

struct Candidate {
    Position target;
    double weight = 0.0;
};

static constexpr int LIMIT = 3000;

bool operator<(const Position &a, const Position &b) {
    if (a.x != b.x) return a.x < b.x;
    return a.y < b.y;
}

Position clampPosition(int x, int y) {
    x = max(1, min(LIMIT, x));
    y = max(1, min(LIMIT, y));
    return {x, y};
}

Position projectToBoundary(const Position &p, int vx, int vy) {
    if (vx == 0 && vy == 0) return p;

    int steps = INT_MAX;

    if (vx < 0) steps = min(steps, p.x - 1);
    if (vx > 0) steps = min(steps, LIMIT - p.x);
    if (vy < 0) steps = min(steps, p.y - 1);
    if (vy > 0) steps = min(steps, LIMIT - p.y);

    if (steps == INT_MAX) return p;

    return clampPosition(p.x + vx * steps, p.y + vy * steps);
}

vector<Position> buildCage(Position target) {
    vector<Position> cage;

    if (target.y == 1) {
        cage.push_back({target.x + 1, target.y});
        cage.push_back({target.x - 1, target.y});
        cage.push_back({target.x + 1, target.y + 1});
        cage.push_back({target.x - 1, target.y + 1});
        cage.push_back({target.x, target.y + 1});
    } else if (target.y == LIMIT) {
        cage.push_back({target.x + 1, target.y});
        cage.push_back({target.x - 1, target.y});
        cage.push_back({target.x + 1, target.y - 1});
        cage.push_back({target.x - 1, target.y - 1});
        cage.push_back({target.x, target.y - 1});
    } else if (target.x == 1) {
        cage.push_back({target.x, target.y + 1});
        cage.push_back({target.x, target.y - 1});
        cage.push_back({target.x + 1, target.y + 1});
        cage.push_back({target.x + 1, target.y - 1});
        cage.push_back({target.x + 1, target.y});
    } else if (target.x == LIMIT) {
        cage.push_back({target.x, target.y + 1});
        cage.push_back({target.x, target.y - 1});
        cage.push_back({target.x - 1, target.y + 1});
        cage.push_back({target.x - 1, target.y - 1});
        cage.push_back({target.x - 1, target.y});
    } else {
        cage.push_back({target.x + 1, target.y});
        cage.push_back({target.x + 1, target.y + 1});
        cage.push_back({target.x, target.y + 1});
        cage.push_back({target.x - 1, target.y + 1});
        cage.push_back({target.x - 1, target.y});
        cage.push_back({target.x - 1, target.y - 1});
        cage.push_back({target.x, target.y - 1});
        cage.push_back({target.x + 1, target.y - 1});
    }

    for (int radius = 2; radius <= 3; ++radius) {
        for (int dx = -radius; dx <= radius; ++dx) {
            for (int dy = -radius; dy <= radius; ++dy) {
                if (max(abs(dx), abs(dy)) != radius) continue;
                int x = target.x + dx;
                int y = target.y + dy;
                if (1 <= x && x <= LIMIT && 1 <= y && y <= LIMIT) {
                    cage.push_back({x, y});
                }
            }
        }
    }

    cage.push_back(target);
    return cage;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Position current;
    if (!(cin >> current.x >> current.y)) return 0;

    set<Position> black;
    vector<Position> history;
    history.push_back(current);

    for (int turn = 1; turn <= LIMIT; ++turn) {
        map<Position, double> targetWeights;

        if (history.size() == 1) {
            targetWeights[clampPosition(current.x, 1)] += 2.0;
            targetWeights[clampPosition(1, current.y)] += 1.2;
            targetWeights[current] += 0.15;
        } else {
            int transitions = min<int>(5, history.size() - 1);

            for (int age = 0; age < transitions; ++age) {
                const Position &a = history[history.size() - 2 - age];
                const Position &b = history[history.size() - 1 - age];

                int vx = (b.x > a.x) - (b.x < a.x);
                int vy = (b.y > a.y) - (b.y < a.y);

                double weight = (age == 0 ? 6.0 : 2.5 / (age + 1));
                Position target = projectToBoundary(current, vx, vy);
                targetWeights[target] += weight;
            }

            double sx = 0.0, sy = 0.0;
            for (int i = max(1, (int)history.size() - 5); i < (int)history.size(); ++i) {
                sx += history[i].x - history[i - 1].x;
                sy += history[i].y - history[i - 1].y;
            }

            int vx = (sx > 0.05) - (sx < -0.05);
            int vy = (sy > 0.05) - (sy < -0.05);
            if (vx || vy) {
                targetWeights[projectToBoundary(current, vx, vy)] += 3.0;
            }

            if (current.x <= 3 || current.y <= 3 ||
                current.x >= LIMIT - 3 || current.y >= LIMIT - 3) {
                targetWeights[current] += 2.5;
            }
        }

        Position chosenTarget = current;
        double bestWeight = -1.0;
        vector<Position> chosenCage;
        size_t chosenIndex = 0;

        for (const auto &[target, weight] : targetWeights) {
            vector<Position> cage = buildCage(target);
            for (size_t i = 0; i < cage.size(); ++i) {
                if (!black.count(cage[i])) {
                    if (weight > bestWeight) {
                        bestWeight = weight;
                        chosenTarget = target;
                        chosenCage = move(cage);
                        chosenIndex = i;
                    }
                    break;
                }
            }
        }

        Position toMark;

        if (!chosenCage.empty()) {
            toMark = chosenCage[chosenIndex];
        } else {
            bool found = false;
            const int dx[8] = {1, 1, 0, -1, -1, -1, 0, 1};
            const int dy[8] = {0, 1, 1, 1, 0, -1, -1, -1};

            for (int d = 0; d < 8; ++d) {
                Position p{current.x + dx[d], current.y + dy[d]};
                if (p.x < 1 || p.x > LIMIT || p.y < 1 || p.y > LIMIT) continue;
                if (black.count(p)) continue;
                toMark = p;
                found = true;
                break;
            }

            if (!found) toMark = clampPosition(current.x, current.y);
        }

        black.insert(toMark);
        cout << toMark.x << ' ' << toMark.y << endl;

        Position next;
        if (!(cin >> next.x >> next.y)) return 0;
        if (next.x == 0 && next.y == 0) return 0;

        current = next;
        history.push_back(current);
    }

    return 0;
}

