#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;

    while (T--) {
        int n;
        if (!(cin >> n)) return 0;

        vector<vector<int>> g(n + 1);
        for (int i = 0; i < n - 1; ++i) {
            int u, v;
            cin >> u >> v;
            g[u].push_back(v);
            g[v].push_back(u);
        }

        vector<int> parent(n + 1, 0), depth(n + 1, 0);
        vector<int> tin(n + 1), tout(n + 1), order;
        order.reserve(n);

        int timer = 0;
        function<void(int, int)> dfs = [&](int v, int p) {
            parent[v] = p;
            tin[v] = timer++;
            order.push_back(v);
            for (int u : g[v]) {
                if (u == p) continue;
                depth[u] = depth[v] + 1;
                dfs(u, v);
            }
            tout[v] = timer;
        };
        dfs(1, 0);

        auto inSubtree = [&](int v, int x) {
            return tin[x] <= tin[v] && tin[v] < tout[x];
        };

        vector<int> candidates(n);
        iota(candidates.begin(), candidates.end(), 1);

        vector<int> sub(n + 1), endpoint(n + 1), excluded(n + 1);
        vector<int> cnt(n + 1), lastChild(n + 1);
        vector<char> inS(n + 1), group(n + 1), seen(n + 1);

        int queries = 0;

        while (true) {
            if (candidates.size() == 1) {
                cout << "! " << candidates[0] << endl;
                break;
            }

            if (queries >= 160) {
                cout << "! " << candidates[0] << endl;
                break;
            }

            const int m = (int)candidates.size();

            fill(inS.begin(), inS.end(), 0);
            for (int v : candidates) inS[v] = 1;

            for (int v = 1; v <= n; ++v) {
                sub[v] = inS[v] ? 1 : 0;
            }
            for (auto it = order.rbegin(); it != order.rend(); ++it) {
                int v = *it;
                if (parent[v]) sub[parent[v]] += sub[v];
            }

            fill(cnt.begin(), cnt.end(), 0);
            fill(lastChild.begin(), lastChild.end(), 0);
            fill(group.begin(), group.end(), 0);
            fill(endpoint.begin(), endpoint.end(), 0);

            int groupCount = 0;
            for (int v : candidates) {
                if (v == 1) continue;
                int u = parent[v];
                if (!group[u]) {
                    group[u] = 1;
                    ++groupCount;
                }
                ++cnt[u];
                lastChild[u] = v;
            }

            const bool rootCandidate = inS[1];
            if (rootCandidate && !group[1]) {
                group[1] = 1;
                ++groupCount;
            }

            if (group[1]) {
                int e;
                if (rootCandidate || cnt[1] != 1) e = 1;
                else e = lastChild[1];
                ++endpoint[e];
            }

            for (int u = 2; u <= n; ++u) {
                if (!group[u]) continue;
                int e = (cnt[u] == 1 ? lastChild[u] : u);
                ++endpoint[e];
            }

            excluded = endpoint;
            for (auto it = order.rbegin(); it != order.rend(); ++it) {
                int v = *it;
                if (parent[v]) excluded[parent[v]] += excluded[v];
            }

            int bestX = -1;
            int bestWorst = INT_MAX;
            int bestDepth = INT_MAX;
            int bestSum = INT_MAX;

            for (int x = 2; x <= n; ++x) {
                int a = sub[x];
                int b = groupCount - excluded[x];

                if (a == m && b == 0) continue;

                int worst = max(a, b);
                int sum = a + b;

                if (worst < bestWorst ||
                    (worst == bestWorst && depth[x] < bestDepth) ||
                    (worst == bestWorst && depth[x] == bestDepth && sum < bestSum)) {
                    bestX = x;
                    bestWorst = worst;
                    bestDepth = depth[x];
                    bestSum = sum;
                }
            }

            if (bestX == -1) {
                bestX = candidates[0];
                for (int v : candidates) {
                    if (depth[v] > depth[bestX]) bestX = v;
                }
            }

            cout << "? " << bestX << endl;
            ++queries;

            int answer;
            cin >> answer;
            if (answer != 0 && answer != 1) return 0;

            vector<int> next;
            next.reserve(candidates.size());

            if (answer == 1) {
                for (int v : candidates) {
                    if (inSubtree(v, bestX)) next.push_back(v);
                }
            } else {
                fill(seen.begin(), seen.end(), 0);
                for (int v : candidates) {
                    if (inSubtree(v, bestX)) continue;
                    int u = (v == 1 ? 1 : parent[v]);
                    if (!seen[u]) {
                        seen[u] = 1;
                        next.push_back(u);
                    }
                }
            }

            if (next.empty()) return 0;
            candidates.swap(next);
        }
    }

    return 0;
}

#include <bits/stdc++.h>
