int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;

        vector<vector<int>> g(n + 1);
        for (int i = 0; i < n - 1; ++i) {
            int u, v;
            cin >> u >> v;
            g[u].push_back(v);
            g[v].push_back(u);
        }

        int LOG = 1;
        while ((1 << LOG) <= n) ++LOG;

        vector<int> parent(n + 1), depth(n + 1), tin(n + 1), tout(n + 1);
        vector<vector<int>> up(LOG, vector<int>(n + 1));
        vector<int> order;
        order.reserve(n);
        int timer = 0;

        function<void(int, int)> dfs = [&](int v, int p) {
            parent[v] = p;
            up[0][v] = p;
            for (int k = 1; k < LOG; ++k)
                up[k][v] = up[k - 1][up[k - 1][v]];

            tin[v] = timer++;
            order.push_back(v);
            for (int to : g[v]) {
                if (to == p) continue;
                depth[to] = depth[v] + 1;
                dfs(to, v);
            }
            tout[v] = timer;
        };

        parent[1] = 1;
        depth[1] = 0;
        dfs(1, 1);

        auto isAncestor = [&](int a, int b) {
            return tin[a] <= tin[b] && tout[b] <= tout[a];
        };

        auto lca = [&](int a, int b) {
            if (isAncestor(a, b)) return a;
            if (isAncestor(b, a)) return b;
            for (int k = LOG - 1; k >= 0; --k) {
                if (!isAncestor(up[k][a], b))
                    a = up[k][a];
            }
            return parent[a];
        };

        vector<int> candidates(n);
        iota(candidates.begin(), candidates.end(), 1);

        while (candidates.size() > 1) {
            vector<int> positive(n + 1, 0), excluded(n + 1, 0);
            vector<int> groupLca(n + 1, 0);
            int mappedGroups = 0;

            for (int v : candidates) positive[v] = 1;

            for (int v : candidates) {
                int p = parent[v];
                if (groupLca[p] == 0) {
                    groupLca[p] = v;
                    ++mappedGroups;
                } else {
                    groupLca[p] = lca(groupLca[p], v);
                }
            }

            for (int p = 1; p <= n; ++p) {
                if (groupLca[p] != 0)
                    ++excluded[groupLca[p]];
            }

            for (int i = n - 1; i >= 1; --i) {
                int v = order[i];
                positive[parent[v]] += positive[v];
                excluded[parent[v]] += excluded[v];
            }

            int bestX = 1;
            int bestWorst = (int)candidates.size() + 1;

            for (int x = 1; x <= n; ++x) {
                int negative = mappedGroups - excluded[x];
                int worst = max(positive[x], negative);

                if (worst < bestWorst ||
                    (worst == bestWorst && depth[x] < depth[bestX])) {
                    bestWorst = worst;
                    bestX = x;
                }
            }

            cout << "? " << bestX << endl;
            int response;
            cin >> response;
            if (response == -1) return 0;

            vector<int> next;
            if (response == 1) {
                for (int v : candidates) {
                    if (isAncestor(bestX, v))
                        next.push_back(v);
                }
            } else {
                for (int v : candidates) {
                    if (!isAncestor(bestX, v))
                        next.push_back(parent[v]);
                }
                sort(next.begin(), next.end());
                next.erase(unique(next.begin(), next.end()), next.end());
            }

            candidates.swap(next);
        }

        cout << "! " << candidates[0] << endl;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    const int SHALLOW = 8;

    while (T--) {
        int n;
        cin >> n;

        vector<vector<int>> adj(n + 1);
        for (int i = 0; i < n - 1; ++i) {
            int u, v;
            cin >> u >> v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        vector<int> parent(n + 1), depth(n + 1), tin(n + 1), tout(n + 1), order;
        order.reserve(n);
        int timer = 0;

        function<void(int, int)> dfs = [&](int v, int p) {
            parent[v] = p;
            tin[v] = timer++;
            order.push_back(v);

            for (int u : adj[v]) {
                if (u == p) continue;
                depth[u] = depth[v] + 1;
                dfs(u, v);
            }

            tout[v] = timer - 1;
        };

        parent[1] = 1;
        depth[1] = 0;
        dfs(1, 1);

        vector<char> possible(n + 1, true);
        possible[0] = false;
        int m = n;
        int queryCount = 0;
        int answerNode = -1;

        while (m > 1 && queryCount < 160) {
            vector<int> cnt(n + 1, 0);
            for (int v = 1; v <= n; ++v) {
                cnt[v] = possible[v] ? 1 : 0;
            }

            for (int i = n - 1; i >= 0; --i) {
                int v = order[i];
                if (v != 1) {
                    cnt[parent[v]] += cnt[v];
                }
            }

            int bestX = -1;

            if (queryCount < SHALLOW) {
                int bestDepth = INT_MAX;
                int bestC = -1;

                for (int v = 1; v <= n; ++v) {
                    int c = cnt[v];
                    if (c >= 1 && c <= m - 1) {
                        if (depth[v] < bestDepth ||
                            (depth[v] == bestDepth && c > bestC)) {
                            bestDepth = depth[v];
                            bestC = c;
                            bestX = v;
                        }
                    }
                }
            } else {
                int bestMax = INT_MAX;
                int bestDepth = INT_MAX;
                int bestC = -1;

                for (int v = 1; v <= n; ++v) {
                    int c = cnt[v];
                    if (c >= 1 && c <= m - 1) {
                        int mx = max(c, m - c);

                        if (mx < bestMax ||
                            (mx == bestMax && depth[v] < bestDepth) ||
                            (mx == bestMax && depth[v] == bestDepth && c > bestC)) {
                            bestMax = mx;
                            bestDepth = depth[v];
                            bestC = c;
                            bestX = v;
                        }
                    }
                }
            }

            if (bestX == -1) {
                for (int v = 1; v <= n; ++v) {
                    if (possible[v]) {
                        bestX = v;
                        break;
                    }
                }
            }

            cout << "? " << bestX << endl;
            int ans;
            cin >> ans;

            ++queryCount;

            vector<char> newPossible(n + 1, false);

            for (int v = 1; v <= n; ++v) {
                if (!possible[v]) continue;

                bool inside = (tin[bestX] <= tin[v] && tin[v] <= tout[bestX]);

                if (ans == 1) {
                    if (inside) {
                        newPossible[v] = true;
                    }
                } else {
                    if (!inside) {
                        int p = parent[v];
                        newPossible[p] = true;
                    }
                }
            }

            possible.swap(newPossible);

            m = 0;
            for (int v = 1; v <= n; ++v) {
                if (possible[v]) {
                    ++m;
                    answerNode = v;
                }
            }
        }

        if (m == 0) {
            answerNode = 1;
        } else if (m >= 1) {
            for (int v = 1; v <= n; ++v) {
                if (possible[v]) {
                    answerNode = v;
                    break;
                }
            }
        }

        cout << "! " << answerNode << endl;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class InteractiveSolver {
private:
    int n;
    vector<vector<int>> adj, children;
    vector<int> parent, depth, tin, tout, order, subtreeSize;

    vector<char> possible;
    int queryCount = 0;

    bool isInSubtree(int x, int v) const {
        return tin[x] <= tin[v] && tin[v] < tout[x];
    }

    void buildTree() {
        parent.assign(n + 1, 0);
        depth.assign(n + 1, 0);
        tin.assign(n + 1, 0);
        tout.assign(n + 1, 0);
        subtreeSize.assign(n + 1, 1);
        children.assign(n + 1, {});

        parent[1] = 1;
        vector<int> st;
        st.reserve(n);
        st.push_back(1);

        while (!st.empty()) {
            int v = st.back();
            st.pop_back();

            tin[v] = (int)order.size();
            order.push_back(v);

            for (int u : adj[v]) {
                if (u == parent[v]) continue;
                parent[u] = v;
                depth[u] = depth[v] + 1;
                children[v].push_back(u);
                st.push_back(u);
            }
        }

        for (int i = n - 1; i > 0; --i) {
            int v = order[i];
            subtreeSize[parent[v]] += subtreeSize[v];
        }

        for (int v = 1; v <= n; ++v) {
            tout[v] = tin[v] + subtreeSize[v];
        }
    }

    int ask(int x) {
        cout << "? " << x << endl;

        int response;
        if (!(cin >> response) || response == -1) {
            exit(0);
        }

        ++queryCount;
        return response;
    }

    void applyResponse(int x, int response) {
        if (response == 1) {
            for (int v = 1; v <= n; ++v) {
                if (possible[v] && !isInSubtree(x, v)) {
                    possible[v] = false;
                }
            }
        } else {
            vector<char> nextPossible(n + 1, false);

            for (int v = 1; v <= n; ++v) {
                if (!possible[v] || isInSubtree(x, v)) continue;
                nextPossible[parent[v]] = true;
            }

            possible.swap(nextPossible);
        }
    }

    int countCandidates() const {
        int result = 0;
        for (int v = 1; v <= n; ++v) {
            result += possible[v];
        }
        return result;
    }

    int findCandidate() const {
        for (int v = 1; v <= n; ++v) {
            if (possible[v]) return v;
        }
        return -1;
    }

    int chooseQuery() const {
        vector<int> candidateChildren(n + 1, 0);
        vector<int> hasCandidateChild(n + 1, 0);
        vector<int> subtreeCandidates(n + 1, 0);
        vector<int> subtreeParentGroups(n + 1, 0);

        for (int v = 2; v <= n; ++v) {
            if (possible[v]) {
                ++candidateChildren[parent[v]];
            }
        }

        int parentGroups = 0;
        for (int v = 1; v <= n; ++v) {
            hasCandidateChild[v] = (candidateChildren[v] > 0);
            if (v != 1 && hasCandidateChild[v]) {
                ++parentGroups;
            }
            subtreeCandidates[v] = possible[v] ? 1 : 0;
            subtreeParentGroups[v] = hasCandidateChild[v];
        }

        for (int i = n - 1; i > 0; --i) {
            int v = order[i];
            int p = parent[v];
            subtreeCandidates[p] += subtreeCandidates[v];
            subtreeParentGroups[p] += subtreeParentGroups[v];
        }

        int bestVertex = -1;
        int bestWorst = INT_MAX;
        int bestGain = -1;
        int bestDepth = INT_MAX;

        for (int x = 2; x <= n; ++x) {
            int yesCount = subtreeCandidates[x];

            bool rootPresent = possible[1];

            if (parent[x] == 1) {
                if (candidateChildren[1] - (possible[x] ? 1 : 0) > 0) {
                    rootPresent = true;
                }
            } else {
                if (candidateChildren[1] > 0) {
                    rootPresent = true;
                }
            }

            int excludedParent = 0;
            if (parent[x] != 1 &&
                candidateChildren[parent[x]] == 1 &&
                possible[x]) {
                excludedParent = 1;
            }

            int noCount = (rootPresent ? 1 : 0)
                        + parentGroups
                        - subtreeParentGroups[x]
                        - excludedParent;

            if (noCount < 0) noCount = 0;

            if (yesCount == 0 && noCount == 0) continue;
            if (noCount == 0 && yesCount == countCandidates()) continue;

            int worst = max(yesCount, noCount);
            int gain = min(yesCount, noCount);

            if (bestVertex == -1 ||
                worst < bestWorst ||
                (worst == bestWorst && gain > bestGain) ||
                (worst == bestWorst && gain == bestGain &&
                 depth[x] < bestDepth)) {
                bestVertex = x;
                bestWorst = worst;
                bestGain = gain;
                bestDepth = depth[x];
            }
        }

        return bestVertex;
    }

public:
    explicit InteractiveSolver(int n)
        : n(n), adj(n + 1), possible(n + 1, true) {}

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    int solve() {
        buildTree();
        possible[1] = true;

        while (true) {
            int candidates = countCandidates();

            if (candidates == 1) {
                return findCandidate();
            }

            if (queryCount >= 160) {
                exit(0);
            }

            int x = chooseQuery();
            if (x == -1) {
                exit(0);
            }

            int response = ask(x);
            applyResponse(x, response);
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    if (!(cin >> t)) return 0;

    while (t--) {
        int n;
        if (!(cin >> n)) return 0;

        InteractiveSolver solver(n);

        for (int i = 0; i < n - 1; ++i) {
            int u, v;
            cin >> u >> v;
            solver.addEdge(u, v);
        }

        int answer = solver.solve();
        cout << "! " << answer << endl;
    }

    return 0;
}

