        }
        return 0;
    }

    RNG rng;
    vector<Candidate> candidates;

    vector<FccSpec> fccSpecs = findFccSpecs(n);
    int fccLimit = n > 10000 ? 2 : min<int>(8, fccSpecs.size());

    for (int i = 0; i < fccLimit; ++i) {
        vector<Point> points = makeFcc(fccSpecs[i], n, rng);
        improveOrientation(points, rng);
        candidates.push_back({
            move(points), minimumDistance(points),
            FCC_CANDIDATE, double(fccSpecs[i].count - n) / n
        });
    }

    if (n <= 10000) {
        for (const array<int, 3>& dims : findSimpleGrids(n)) {
            vector<Point> points = makeSimpleGrid(dims[0], dims[1], dims[2]);
            candidates.push_back({
                move(points), minimumDistance(points),
                SIMPLE_CANDIDATE, 0.0
            });
        }
    }

    if (n <= 10000) {
        int base = max(2, int(ceil(cbrt(0.5 * n))));
        vector<pair<double, array<int, 3>>> bccSpecs;

        for (int a = max(2, base - 2); a <= base + 3; ++a)
            for (int b = max(2, base - 2); b <= base + 3; ++b)
                for (int c = max(2, base - 2); c <= base + 3; ++c) {
                    int count = a * b * c + (a - 1) * (b - 1) * (c - 1);
                    if (count < n || count > int(1.45 * n)) continue;

                    double sa = 1.0 / max(1, a - 1);
                    double sb = 1.0 / max(1, b - 1);
                    double sc = 1.0 / max(1, c - 1);
                    double delta = sqrt(0.25 * (sa * sa + sb * sb + sc * sc));
                    delta = min(delta, min({sa, sb, sc}));
                    double holes = double(count - n) / n;
                    bccSpecs.push_back({delta * (1.0 - holes), {a, b, c}});
                }

        sort(bccSpecs.begin(), bccSpecs.end(),
             [](const auto& x, const auto& y) { return x.first > y.first; });

        for (int i = 0; i < min<int>(2, bccSpecs.size()); ++i) {
            auto d = bccSpecs[i].second;
            vector<Point> points = makeBcc(d[0], d[1], d[2], n, rng);
            candidates.push_back({
                move(points), minimumDistance(points),
                BCC_CANDIDATE, 0.0
            });
        }
    }

    sort(candidates.begin(), candidates.end(),
         [](const Candidate& a, const Candidate& b) {
             return a.distance > b.distance;
         });

    vector<int> selected;
    auto addCandidate = [&](int index) {
        if (index < 0 || index >= int(candidates.size())) return;
        if (find(selected.begin(), selected.end(), index) == selected.end())
            selected.push_back(index);
    };

    addCandidate(0);

    int minimumHolesFcc = -1;
    for (int i = 0; i < int(candidates.size()); ++i) {
        if (candidates[i].type != FCC_CANDIDATE) continue;
        if (minimumHolesFcc < 0 ||
            candidates[i].holes < candidates[minimumHolesFcc].holes)
            minimumHolesFcc = i;
    }
    addCandidate(minimumHolesFcc);

    for (int i = 0; i < int(candidates.size()) && selected.size() < 4; ++i)
        addCandidate(i);

    int shortIterations = n < 500 ? 400 : n < 5000 ? 100 : 25;
    vector<Candidate> improved;

    for (int index : selected) {
        vector<Point> points = optimizeCandidate(
            candidates[index].points, shortIterations, false, rng
        );
        improved.push_back({
            move(points), minimumDistance(points),
            candidates[index].type, candidates[index].holes
        });
    }

    sort(improved.begin(), improved.end(),
         [](const Candidate& a, const Candidate& b) {
             return a.distance > b.distance;
         });

    int fullIterations = n < 500 ? 1400 : n < 5000 ? 500 : 80;
    vector<Point> best = optimizeCandidate(
        improved.front().points, fullIterations, true, rng
    );
    double bestDistance = minimumDistance(best);

    if (n <= 5000) {
        vector<Point> trial = best;
        perturbCritical(trial, 0.002 * bestDistance, rng);
        trial = optimizeCandidate(trial, max(80, fullIterations / 4), false, rng);
        trial = improveWithTarget(trial, 5, 25);
        double d = minimumDistance(trial);
        if (d > bestDistance) {
            best.swap(trial);
            bestDistance = d;
        }
    }

    double finalDistance = minimumDistance(best);
    double radius = finalDistance / (2.0 * (1.0 + finalDistance));
    double scale = 1.0 / (1.0 + finalDistance);

    cout << setprecision(17);
    for (const Point& p : best) {
        cout << radius + scale * p.x << ' '
             << radius + scale * p.y << ' '
             << radius + scale * p.z << '\n';
    }

    return 0;
}

