int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    unsigned long long x;
    cin >> x;

    vector<int> bits;
    while (x > 0) {
        bits.push_back(x & 1ULL);
        x >>= 1ULL;
    }
    reverse(bits.begin(), bits.end());

    int G = (int)bits.size() - 1;
    int n = 3 + 2 * G;

    vector<vector<int>> grid(n + 1, vector<int>(n + 1, 0));

    // Top wire
    for (int j = 1; j <= n; ++j) grid[1][j] = 1;

    int r0 = 3, c0 = 2;

    // Entry path to A0
    for (int i = 1; i <= r0; ++i) grid[i][1] = 1;
    for (int j = 1; j <= c0; ++j) grid[r0][j] = 1;

    // Gadgets for remaining bits
    for (int idx = 1; idx < (int)bits.size(); ++idx) {
        int bit = bits[idx];
        int t = idx - 1;
        int r = r0 + 2 * t;
        int c = c0 + 2 * t;

        grid[r + 1][c] = 1;
        grid[r][c + 1] = 1;
        grid[r + 1][c + 1] = 1;
        grid[r + 2][c + 1] = 1;
        grid[r + 2][c + 2] = 1;

        if (bit) {
            int C = c + 1;
            for (int row = 2; row <= r; ++row) {
                grid[row][C] = 1;
            }
        }
    }

    // Connect final A to (n,n)
    grid[n][n] = 1;

    cout << n << '\n';
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            cout << grid[i][j] << (j == n ? '\n' : ' ');
        }
    }

