using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long long x;
    cin >> x;

    if (x == 1) {
        cout << "1\n1\n";
        return 0;
    }

    int L = 64 - __builtin_clzll(x);
    int stages = L - 2;
    int n = 2 * stages + 4;

    vector<vector<int>> a(n, vector<int>(n, 0));

    // The initial gadget has either 2 or 3 paths.
    int initial = int((x >> (L - 2)) & 3ULL);

    a[0][0] = 1;
    a[1][0] = 1;

    a[2][0] = a[2][1] = a[2][2] = 1;
    if (initial == 3) {
        a[2][3] = 1;
    }
    a[3][1] = a[3][2] = a[3][3] = 1;

    for (int stage = 0; stage < stages; ++stage) {
        int p = 3 + 2 * stage;

        // Boundary of a square: exactly two disjoint routes
        // from (p,p) to (p+2,p+2).
        for (int c = p; c <= p + 2; ++c) {
            a[p][c] = 1;
            a[p + 2][c] = 1;
        }
        for (int r = p; r <= p + 2; ++r) {
            a[r][p] = 1;
            a[r][p + 2] = 1;
        }

        int bitIndex = L - 3 - stage;
        int bit = int((x >> bitIndex) & 1ULL);

        if (bit == 1) {
            // A unique extra route from the upper rail into this stage.
            for (int r = 0; r <= p; ++r) {
                a[r][p + 2] = 1;
            }
            for (int c = 0; c <= p + 2; ++c) {
                a[0][c] = 1;
            }
        }
    }

    cout << n << '\n';
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (j) cout << ' ';
            cout << a[i][j];
        }
        cout << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Node {
    double value;
    int action; // 0: answer, 1: race, 2: drain one pen
};

struct TestSolver {
    int n;
    unordered_map<uint32_t, Node> memo;

    explicit TestSolver(int n_) : n(n_) {
        memo.reserve(4096);
    }

    pair<double, double> immediate(uint32_t mask) {
        vector<int> v;
        for (int i = 0; i < n; ++i) {
            if (mask & (1u << i)) v.push_back(i);
        }

        int m = (int)v.size();
        int goodPairs = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                goodPairs += (v[i] + v[j] >= n);
            }
        }

        double q = 0.0;
        if (m >= 2) {
            q = (double)goodPairs / ((double)m * (m - 1) / 2.0);
        }

        double r = 0.0;
        if (m >= 3) {
            int a = v[m - 3];
            int b = v[m - 2];
            int c = v[m - 1];
            int d = b + c - 2 * a - n;
            int goodOrders = max(0, min(3, d + 1));
            r = (double)goodOrders / 3.0;
        }

        return {q, r};
    }

    Node dp(uint32_t mask) {
        auto it = memo.find(mask);
        if (it != memo.end()) return it->second;

        int m = __builtin_popcount(mask);
        auto [q, r] = immediate(mask);

        if (m <= 2) {
            Node res{q, 0};
            memo[mask] = res;
            return res;
        }

        Node res{q, 0};
        if (r > res.value + 1e-12) res = {r, 1};

        if (res.value >= 1.0 - 1e-12) {
            memo[mask] = res;
            return res;
        }

        double continuation = 0.0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1u << i)) {
                continuation += dp(mask ^ (1u << i)).value;
            }
        }
        continuation /= m;

        if (continuation > res.value + 1e-12) {
            res = {continuation, 2};
        }

        memo[mask] = res;
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    if (!(cin >> t)) return 0;

    mt19937 rng((unsigned)chrono::steady_clock::now().time_since_epoch().count());

    auto usePen = [&](int id) {
        cout << "0 " << id << endl;
        int x;
        if (!(cin >> x)) exit(0);
        return x;
    };

    auto answer = [&](int a, int b) {
        cout << "1 " << a << " " << b << endl;
    };

    while (t--) {
        int n;
        if (!(cin >> n)) return 0;

        vector<int> pens(n);
        iota(pens.begin(), pens.end(), 0);
        shuffle(pens.begin(), pens.end(), rng);

        uint32_t mask = (n == 32 ? ~0u : ((1u << n) - 1));
        TestSolver solver(n);

        auto race = [&](const vector<int>& group) {
            vector<int> active = group;
            vector<char> alive(n, 0);
            for (int id : active) alive[id] = 1;

            int remaining = (int)active.size();

            while (remaining > 2) {
                vector<int> round = active;

                for (int id : round) {
                    if (remaining == 2) break;
                    if (!alive[id]) continue;

                    int x = usePen(id);
                    if (x == 0) {
                        alive[id] = 0;
                        --remaining;
                    }
                }

                active.clear();
                for (int id : round) {
                    if (alive[id]) active.push_back(id);
                }
            }

            answer(active[0], active[1]);
        };

        while (true) {
            int m = (int)pens.size();

            if (m == 2) {
                answer(pens[0], pens[1]);
                break;
            }

            auto [q, r] = solver.immediate(mask);
            int action;

            if (m <= 10) {
                action = solver.dp(mask).action;
            } else {
                double best = max(q, r);
                if (best >= 2.0 / 3.0 - 1e-12) {
                    action = (r > q + 1e-12 ? 1 : 0);
                } else {
                    action = 2;
                }
            }

            if (action == 0) {
                answer(pens[0], pens[1]);
                break;
            }

            if (action == 1) {
                race(pens);
                break;
            }

            int id = pens[0];
            int p = 0;
            while (usePen(id) == 1) ++p;

            pens.erase(pens.begin());
            mask &= ~(1u << p);
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

mt19937 rng(random_device{}());

int askPen(int id) {
    cout << 0 << ' ' << id << endl;
    int response;
    cin >> response;
    return response;
}

void answerPair(int a, int b) {
    cout << 1 << ' ' << a << ' ' << b << endl;
}

int emptyPen(int id) {
    int value = 0;
    while (true) {
        int response = askPen(id);
        if (response == 0) return value;
        ++value;
    }
}

double randomPairSuccess(const vector<int>& values, int n) {
    int k = (int)values.size();
    int good = 0;
    for (int i = 0; i < k; ++i) {
        for (int j = i + 1; j < k; ++j) {
            if (values[i] + values[j] >= n) ++good;
        }
    }
    return (double)good / ((double)k * (k - 1) / 2.0);
}

double threePenValue(vector<int> values, int n) {
    sort(values.begin(), values.end());
    int a = values[0], b = values[1], c = values[2];

    if (a + b >= n) return 1.0;
    if (b + c < n) return 0.0;

    int damage = a + 1;
    int slack = b + c - n;

    double result = 1.0;
    if (slack >= damage) result += 1.0;
    if (slack >= 2 * damage) result += 1.0;
    return result / 3.0;
}

struct StateSolver {
    int n;
    map<vector<int>, double> memo;

    double solve(vector<int> values) {
        sort(values.begin(), values.end());
        auto it = memo.find(values);
        if (it != memo.end()) return it->second;

        int k = (int)values.size();
        double result;
        if (k == 3) {
            result = threePenValue(values, n);
        } else {
            double stop = randomPairSuccess(values, n);
            double eliminate = 0.0;
            for (int i = 0; i < k; ++i) {
                vector<int> next = values;
                next.erase(next.begin() + i);
                eliminate += solve(next);
            }
            eliminate /= k;
            result = max(stop, eliminate);
        }

        memo[values] = result;
        return result;
    }

    bool shouldEliminate(vector<int> values) {
        sort(values.begin(), values.end());
        double stop = randomPairSuccess(values, n);
        double eliminate = 0.0;
        int k = (int)values.size();
        for (int i = 0; i < k; ++i) {
            vector<int> next = values;
            next.erase(next.begin() + i);
            eliminate += solve(next);
        }
        eliminate /= k;
        return eliminate > stop + 1e-12;
    }
};

void outputRandomPair(vector<int> pens) {
    shuffle(pens.begin(), pens.end(), rng);
    answerPair(pens[0], pens[1]);
}

void solveThreePens(vector<int> pens, vector<int> values, int n) {
    sort(values.begin(), values.end());
    int a = values[0], b = values[1], c = values[2];

    if (a + b >= n || b + c < n) {
        outputRandomPair(pens);
        return;
    }

    shuffle(pens.begin(), pens.end(), rng);
    int x = pens[0], y = pens[1], z = pens[2];
    int damage = a + 1;

    bool xIsHigh = true;
    for (int i = 0; i < damage; ++i) {
        if (askPen(x) == 0) {
            xIsHigh = false;
            break;
        }
    }

    if (!xIsHigh) {
        answerPair(y, z);
        return;
    }

    bool yIsHigh = true;
    for (int i = 0; i < damage; ++i) {
        if (askPen(y) == 0) {
            yIsHigh = false;
            break;
        }
    }

    if (!yIsHigh) answerPair(x, z);
    else answerPair(x, y);
}

void runTestCase(int n) {
    const int adaptiveLimit = 12;

    vector<int> pens(n), values(n);
    iota(pens.begin(), pens.end(), 0);
    iota(values.begin(), values.end(), 0);
    shuffle(pens.begin(), pens.end(), rng);

    while ((int)pens.size() > adaptiveLimit) {
        if (randomPairSuccess(values, n) >= 1.0) {
            outputRandomPair(pens);
            return;
        }

        int pos = uniform_int_distribution<int>(0, (int)pens.size() - 1)(rng);
        int id = pens[pos];
        int value = emptyPen(id);

        pens.erase(pens.begin() + pos);
        values.erase(find(values.begin(), values.end(), value));
    }

    StateSolver solver;
    solver.n = n;
    solver.solve(values);

    while ((int)pens.size() > 3) {
        if (!solver.shouldEliminate(values)) {
            outputRandomPair(pens);
            return;
        }

        int pos = uniform_int_distribution<int>(0, (int)pens.size() - 1)(rng);
        int id = pens[pos];
        int value = emptyPen(id);

        pens.erase(pens.begin() + pos);
        values.erase(find(values.begin(), values.end(), value));
    }

    solveThreePens(pens, values, n);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        runTestCase(n);
    }

    return 0;
}

