int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        const int K = 10;
        vector<bool> used(n, false);
        // Empty pens 0 to n-K-1
        for (int i = 0; i < n - K; i++) {
            int v = 0;
            while (true) {
                cout << "0 " << i << endl;
                cout.flush();
                int x;
                cin >> x;
                if (x == 0) break;
                v++;
            }
            used[v] = true;
        }
        // Collect remaining values S
        vector<int> S;
        for (int v = 0; v < n; v++) {
            if (!used[v]) S.push_back(v);
        }
        // DP
        int totalMasks = 1 << K;
        vector<double> dp(totalMasks, 0.0);
        for (int mask = 0; mask < totalMasks; mask++) {
            int k = __builtin_popcount(mask);
            if (k < 2) {
                dp[mask] = 0.0;
                continue;
            }
            vector<int> rem;
            for (int i = 0; i < K; i++) {
                if (mask & (1 << i)) {
                    rem.push_back(S[i]);
                }
            }
            int valid = 0;
            for (int a = 0; a < k; a++) {
                for (int b = a + 1; b < k; b++) {
                    if (rem[a] + rem[b] >= n) {
                        valid++;
                    }
                }
            }
            double stopProb = (double)valid / (k * (k - 1) / 2);
            double emptyProb = 0.0;
            for (int i = 0; i < K; i++) {
                if (mask & (1 << i)) {
                    emptyProb += dp[mask ^ (1 << i)];
                }
            }
            emptyProb /= k;
            dp[mask] = max(stopProb, emptyProb);
        }
        // Execute strategy
        int mask = totalMasks - 1;
        vector<int> remaining_pens;
        for (int i = 0; i < K; i++) {
            remaining_pens.push_back(n - K + i);
        }
        while (true) {
            int k = __builtin_popcount(mask);
            if (k < 2) {
                break;
            }
            vector<int> rem;
            for (int i = 0; i < K; i++) {
                if (mask & (1 << i)) {
                    rem.push_back(S[i]);
                }
            }
            int valid = 0;
            for (int a = 0; a < k; a++) {
                for (int b = a + 1; b < k; b++) {
                    if (rem[a] + rem[b] >= n) {
                        valid++;
                    }
                }
            }
            double stopProb = (double)valid / (k * (k - 1) / 2);
            double emptyProb = 0.0;
            for (int i = 0; i < K; i++) {
                if (mask & (1 << i)) {
                    emptyProb += dp[mask ^ (1 << i)];
                }
            }
            emptyProb /= k;
            if (stopProb >= emptyProb) {
                int pen1 = remaining_pens[0];
                int pen2 = remaining_pens[1];
                cout << "1 " << pen1 << " " << pen2 << endl;
                cout.flush();
                break;
            } else {
                int pen = remaining_pens[0];
                int v = 0;
                while (true) {
                    cout << "0 " << pen << endl;
                    cout.flush();
                    int x;
                    cin >> x;
                    if (x == 0) break;
                    v++;
                }
                int idx = -1;
                for (int i = 0; i < K; i++) {
                    if ((mask & (1 << i)) && S[i] == v) {
                        idx = i;
                        break;
                    }
                }
                mask ^= (1 << idx);
                remaining_pens.erase(remaining_pens.begin());
            }
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using uint64 = unsigned long long;

struct Entity {
    int limit;
    int consumed;
    int pen;
};

struct PairInfo {
    uint64 favorable = 0;
    uint64 expectedNumerator = 0;
    int minimumSum = INT_MAX;
};

static pair<int, int> chooseBestPair(
    int n,
    const vector<Entity>& entities,
    const vector<int>& capacities
) {
    const int m = (int)entities.size();

    vector<int> order(m);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        return entities[a].limit > entities[b].limit;
    });

    vector<int> greaterCount(m, 0);
    for (int i = 0; i < m; ++i) {
        for (int c : capacities) {
            if (c > entities[i].limit) {
                ++greaterCount[i];
            }
        }
    }

    uint64 totalAssignments = 1;
    for (int k = 0; k < m; ++k) {
        int e = order[k];
        int choices = greaterCount[e] - k;
        if (choices <= 0) {
            totalAssignments = 0;
            break;
        }
        totalAssignments *= choices;
    }

    auto completionWays = [&](int a, int b, int x, int y) -> uint64 {
        uint64 ways = 1;
        int used = 0;

        for (int e : order) {
            if (e == a || e == b) continue;

            int allowed = greaterCount[e];
            allowed -= (x > entities[e].limit);
            allowed -= (y > entities[e].limit);

            int choices = allowed - used;
            if (choices <= 0) return 0;

            ways *= choices;
            ++used;
        }

        return ways;
    };

    vector<vector<PairInfo>> info(m, vector<PairInfo>(m));

    for (int a = 0; a < m; ++a) {
        for (int b = a + 1; b < m; ++b) {
            PairInfo& result = info[a][b];

            for (int x : capacities) {
                if (x <= entities[a].limit) continue;

                for (int y : capacities) {
                    if (y == x || y <= entities[b].limit) continue;

                    uint64 ways = completionWays(a, b, x, y);
                    if (ways == 0) continue;

                    int remainingSum =
                        x - entities[a].consumed +
                        y - entities[b].consumed;

                    result.minimumSum = min(result.minimumSum, remainingSum);
                    result.expectedNumerator +=
                        ways * static_cast<uint64>(remainingSum);

                    if (remainingSum >= n) {
                        result.favorable += ways;
                    }
                }
            }
        }
    }

    int bestA = -1;
    int bestB = -1;
    tuple<int, uint64, int, uint64> bestKey{-1, 0, -1, 0};

    for (int a = 0; a < m; ++a) {
        for (int b = a + 1; b < m; ++b) {
            const PairInfo& current = info[a][b];
            int guaranteed = (current.minimumSum >= n);

            auto key = make_tuple(
                guaranteed,
                current.favorable,
                current.minimumSum,
                current.expectedNumerator
            );

            if (bestA == -1 || key > bestKey) {
                bestKey = key;
                bestA = a;
                bestB = b;
            }
        }
    }

    if (bestA == -1) {
        return {0, 1};
    }

    return {entities[bestA].pen, entities[bestB].pen};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    mt19937_64 rng(
        chrono::steady_clock::now().time_since_epoch().count() ^
        static_cast<uint64>(random_device{}())
    );

    auto ask = [&](int pen) -> bool {
        cout << 0 << ' ' << pen << endl;
        int response;
        if (!(cin >> response)) {
            exit(0);
        }
        return response == 1;
    };

    int t;
    if (!(cin >> t)) return 0;

    while (t--) {
        int n;
        if (!(cin >> n)) return 0;

        vector<int> pens(n);
        iota(pens.begin(), pens.end(), 0);
        shuffle(pens.begin(), pens.end(), rng);

        int reservedCount = (n % 2 == 0 ? 2 : 1);
        int pairCount = (n - reservedCount) / 2;

        vector<Entity> entities;
        vector<int> lowerCapacities;

        for (int i = 0; i < reservedCount; ++i) {
            entities.push_back({-1, 0, pens[i]});
        }

        for (int i = 0; i < pairCount; ++i) {
            int a = pens[reservedCount + 2 * i];
            int b = pens[reservedCount + 2 * i + 1];

            if (rng() & 1ULL) swap(a, b);

            int consumedA = 0;
            int consumedB = 0;

            while (true) {
                if (!ask(a)) {
                    lowerCapacities.push_back(consumedA);
                    entities.push_back({consumedA, consumedB, b});
                    break;
                }
                ++consumedA;

                if (!ask(b)) {
                    lowerCapacities.push_back(consumedB);
                    entities.push_back({consumedB, consumedA, a});
                    break;
                }
                ++consumedB;
            }
        }

        vector<bool> excluded(n, false);
        for (int capacity : lowerCapacities) {
            excluded[capacity] = true;
        }

        vector<int> capacities;
        for (int capacity = 0; capacity < n; ++capacity) {
            if (!excluded[capacity]) {
                capacities.push_back(capacity);
            }
        }

        auto [first, second] = chooseBestPair(n, entities, capacities);

        cout << 1 << ' ' << first << ' ' << second << endl;
    }

    return 0;
}

