#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const int MOVE_LIMIT = 100000;

    int initialDeep;
    cin >> initialDeep;
    if (initialDeep == 0) return 0;

    mt19937 rng(
        static_cast<unsigned int>(
            chrono::high_resolution_clock::now().time_since_epoch().count()
        ) ^ random_device{}()
    );

    int movesUsed = 0;

    auto doMove = [&](int c) -> int {
        cout << "move " << c << '\n' << flush;
        ++movesUsed;
        int result;
        cin >> result;
        return result;
    };

    auto doQuery = [&]() -> int {
        cout << "query\n" << flush;
        int result;
        cin >> result;
        return result;
    };

    int depth = initialDeep;
    int incoming = -1;

    // Find the first upward edge. Afterwards, the color of the edge
    // leading back down is known, so only two colors need consideration.
    for (int c = 0; c < 3; ++c) {
        if (doMove(c)) return 0;

        if (c == 2) {
            depth = initialDeep - 1;
            incoming = c;
            break;
        }

        int newDepth = doQuery();
        if (newDepth == initialDeep - 1) {
            depth = newDepth;
            incoming = c;
            break;
        }

        doMove(c); // Return to the initial node.
    }

    while (depth > 0) {
        int t = min(8, depth);

        // Reserve enough moves to finish deterministically, using at most
        // three moves per remaining level.
        while (t > 1 &&
               movesUsed + 3 * t + 3 * (depth - 1) > MOVE_LIMIT) {
            --t;
        }

        vector<int> path;
        path.reserve(t);

        int previous = incoming;
        for (int i = 0; i < t; ++i) {
            int c = static_cast<int>(rng() % 2);
            if (c >= previous) ++c;
            path.push_back(c);
            previous = c;
        }

        bool reachedExit = false;
        for (int c : path) {
            if (doMove(c)) {
                reachedExit = true;
                break;
            }
        }
        if (reachedExit) return 0;

        int newDepth = doQuery();
        int k = (depth + t - newDepth) / 2;

        if (k == t) {
            // Every move was upward.
            depth -= t;
            incoming = path.back();
            continue;
        }

        // The first k moves were upward, move k+1 was downward, and all
        // subsequent moves were also downward.
        int incomingAtFailure = (k == 0 ? incoming : path[k - 1]);
        int forcedUp = 3 - incomingAtFailure - path[k];

        for (int i = t - 1; i >= 0; --i) {
            if (doMove(path[i])) return 0;
        }

        for (int i = 0; i < k; ++i) {
            if (doMove(path[i])) return 0;
        }

        if (doMove(forcedUp)) return 0;

        depth -= k + 1;
        incoming = forcedUp;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int h;
    cin >> h;
    if (h == 0) {
        return 0;
    }

    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

    long long moves_used = 0;
    long long queries_used = 0;

    int came_from;
    int c = rng() % 3;
    cout << "move " << c << endl;
    int resp;
    cin >> resp;
    moves_used++;
    if (resp == 1) {
        return 0;
    }
    cout << "query" << endl;
    int d;
    cin >> d;
    queries_used++;
    if (d == h - 1) {
        h = d;
        came_from = c;
    } else {
        cout << "move " << c << endl;
        cin >> resp;
        moves_used++;
        if (resp == 1) {
            return 0;
        }
        came_from = c;
    }

    while (h > 0) {
        long long M_rem = 100000 - moves_used;
        long long R = M_rem - 3LL * (h - 1);
        long long max_L_safe = (R - 1) / 2;
        if (max_L_safe < 1) max_L_safe = 1;

        int L_exp = 1;
        int max_cand = min(h, 60);
        for (int Lcand = 1; Lcand <= max_cand; ++Lcand) {
            double p;
            if (Lcand == 1) p = 1.0;
            else {
                if (Lcand - 1 >= 60) p = 2.0;
                else p = 2.0 - 1.0 / (double)(1LL << (Lcand - 1));
            }
            double cost = (2.0 * Lcand) / p;
            if (cost * h <= (double)M_rem + 1e-9) {
                L_exp = Lcand;
            } else {
                break;
            }
        }

        int L = min({L_exp, (int)max_L_safe, h, 60});
        if (L < 1) L = 1;

        vector<int> path;
        path.reserve(L);
        int prev = came_from;
        bool exited = false;
        for (int i = 0; i < L; ++i) {
            int cand[2];
            int idx = 0;
            for (int col = 0; col < 3; ++col) {
                if (col != prev) {
                    cand[idx++] = col;
                }
            }
            int chosen = cand[rng() % 2];
            path.push_back(chosen);
            cout << "move " << chosen << endl;
            cin >> resp;
            moves_used++;
            if (resp == 1) {
                exited = true;
                break;
            }
            prev = chosen;
        }
        if (exited) {
            return 0;
        }

        cout << "query" << endl;
        int d_final;
        cin >> d_final;
        queries_used++;

        int m = (h + L - d_final) / 2;

        if (m == L) {
            h = h - L;
            came_from = path.back();
        } else {
            for (int i = L - 1; i >= m; --i) {
                int col = path[i];
                cout << "move " << col << endl;
                cin >> resp;
                moves_used++;
                if (resp == 1) {
                    return 0;
                }
            }
            int prev_color = (m > 0) ? path[m - 1] : came_from;
            int wrong_color = path[m];
            int correct_color = 3 - prev_color - wrong_color;
            cout << "move " << correct_color << endl;
            cin >> resp;
            moves_used++;
            if (resp == 1) {
                return 0;
            }
            h = h - m - 1;
            came_from = correct_color;
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int MOVE_LIMIT = 100000;

int movesUsed = 0;
int queriesUsed = 0;

uint64_t seed = chrono::steady_clock::now().time_since_epoch().count();
mt19937 rng(static_cast<uint32_t>(seed ^ (seed >> 32)));

void performMove(int color) {
    cout << "move " << color << '\n' << flush;

    int response;
    if (!(cin >> response)) exit(0);

    ++movesUsed;
    if (response == 1) exit(0);
}

int performQuery() {
    cout << "query\n" << flush;

    int distance;
    if (!(cin >> distance)) exit(0);

    ++queriesUsed;
    return distance;
}

vector<int> childColors(int parentColor) {
    vector<int> colors;
    for (int color = 0; color < 3; ++color) {
        if (color != parentColor) colors.push_back(color);
    }
    return colors;
}

void exhaustiveSearch(int level, int parentColor, int targetDepth) {
    vector<int> colors = childColors(parentColor);

    for (int color : colors) {
        performMove(color);

        if (level + 1 == targetDepth) {
            performMove(color);
        } else {
            exhaustiveSearch(level + 1, color, targetDepth);
            performMove(color);
        }
    }
}

int partialLimit = 0;
bool partialStopped = false;

bool partialSearch(int level, int parentColor, int targetDepth) {
    if (level == targetDepth) return true;

    vector<int> colors = childColors(parentColor);
    shuffle(colors.begin(), colors.end(), rng);

    bool complete = true;

    for (int color : colors) {
        if (partialStopped) {
            complete = false;
            break;
        }

        performMove(color);
        bool childComplete = partialSearch(level + 1, color, targetDepth);
        performMove(color);

        if (!childComplete) complete = false;

        if (movesUsed >= partialLimit) {
            partialStopped = true;
            break;
        }
    }

    return complete && !partialStopped;
}

void partialSearchFromRoot(int targetDepth, array<bool, 3>& knownChild) {
    vector<int> firstColors{0, 1, 2};
    shuffle(firstColors.begin(), firstColors.end(), rng);

    partialLimit = 98000;
    partialStopped = false;

    for (int color : firstColors) {
        if (partialStopped) break;

        performMove(color);
        bool complete = partialSearch(1, color, targetDepth);
        performMove(color);

        if (complete) knownChild[color] = true;

        if (movesUsed >= partialLimit) partialStopped = true;
    }
}

class Solver {
public:
    int depth;
    array<bool, 3> knownChild{false, false, false};

    explicit Solver(int initialDepth) : depth(initialDepth) {}

    int knownCount() const {
        return static_cast<int>(knownChild[0]) +
               static_cast<int>(knownChild[1]) +
               static_cast<int>(knownChild[2]);
    }

    int onlyUnknownParentColor() const {
        int sum = 0;
        int count = 0;

        for (int color = 0; color < 3; ++color) {
            if (knownChild[color]) {
                sum += color;
                ++count;
            }
        }

        if (count == 1) return 3 - sum;

        for (int color = 0; color < 3; ++color) {
            if (!knownChild[color]) return color;
        }

        return -1;
    }

    void resetKnownChild(int color = -1) {
        knownChild.fill(false);
        if (color >= 0) knownChild[color] = true;
    }

    void finishAtDepthOne() {
        while (depth > 0) {
            vector<int> candidates;
            for (int color = 0; color < 3; ++color) {
                if (!knownChild[color]) candidates.push_back(color);
            }

            for (int color : candidates) {
                performMove(color);
                performMove(color);
            }
        }
    }

    void directAscend() {
        while (depth > 0) {
            int count = knownCount();

            if (count == 2) {
                int parentColor = onlyUnknownParentColor();
                performMove(parentColor);
                --depth;
                resetKnownChild(parentColor);
                continue;
            }

            vector<int> candidates;
            for (int color = 0; color < 3; ++color) {
                if (!knownChild[color]) candidates.push_back(color);
            }

            shuffle(candidates.begin(), candidates.end(), rng);
            int color = candidates.front();

            performMove(color);
            int queriedDepth = performQuery();

            if (queriedDepth == depth - 1) {
                --depth;
                resetKnownChild(color);
            } else {
                performMove(color);

                if (count == 0) {
                    resetKnownChild(color);
                } else {
                    int oldChildColor = 0;
                    for (int c = 0; c < 3; ++c) {
                        if (knownChild[c]) oldChildColor = c;
                    }

                    int parentColor = 3 - oldChildColor - color;
                    performMove(parentColor);
                    --depth;
                    resetKnownChild(parentColor);
                }
            }
        }
    }

    bool canRunProbe(int length) const {
        int minimumGain = (knownCount() >= 1 ? 1 : 0);
        int remainingDepth = depth - minimumGain;

        long long worstProbeMoves = 2LL * length + 1;
        long long directFallbackMoves = 3LL * remainingDepth + 2;

        return movesUsed + worstProbeMoves + directFallbackMoves <= MOVE_LIMIT;
    }

    void probe(int length) {
        int oldKnownCount = knownCount();
        int oldKnownColor = -1;

        for (int color = 0; color < 3; ++color) {
            if (knownChild[color]) oldKnownColor = color;
        }

        vector<int> candidates;
        for (int color = 0; color < 3; ++color) {
            if (!knownChild[color]) candidates.push_back(color);
        }

        shuffle(candidates.begin(), candidates.end(), rng);

        vector<int> path;
        path.reserve(length);

        int previousColor = candidates.front();
        path.push_back(previousColor);
        performMove(previousColor);

        for (int i = 1; i < length; ++i) {
            vector<int> choices;
            for (int color = 0; color < 3; ++color) {
                if (color != previousColor) choices.push_back(color);
            }

            int color = choices[rng() & 1U];
            path.push_back(color);
            performMove(color);
            previousColor = color;
        }

        int queriedDepth = performQuery();
        int numerator = depth + length - queriedDepth;

        if (numerator < 0 || (numerator & 1)) exit(0);

        int upwardSteps = numerator / 2;

        if (upwardSteps == 0) {
            for (int i = length - 1; i >= 0; --i) {
                performMove(path[i]);
            }

            if (oldKnownCount == 1) {
                int parentColor = 3 - oldKnownColor - path[0];
                performMove(parentColor);
                --depth;
                resetKnownChild(parentColor);
            } else {
                resetKnownChild(path[0]);
            }
        } else if (upwardSteps == length) {
            depth -= length;
            resetKnownChild(path.back());
        } else {
            for (int i = length - 1; i >= upwardSteps; --i) {
                performMove(path[i]);
            }

            int parentColor = 3 - path[upwardSteps - 1] - path[upwardSteps];
            performMove(parentColor);
            depth -= upwardSteps + 1;
            resetKnownChild(parentColor);
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int initialDepth;
    if (!(cin >> initialDepth)) return 0;

    if (initialDepth == 0) return 0;

    if (initialDepth <= 14) {
        exhaustiveSearch(0, -1, initialDepth);
        return 0;
    }

    array<bool, 3> knownChild{false, false, false};

    if (15 <= initialDepth && initialDepth <= 20) {
        partialSearchFromRoot(initialDepth, knownChild);
    }

    Solver solver(initialDepth);
    solver.knownChild = knownChild;

    while (solver.depth > 0) {
        if (solver.depth == 1) {
            solver.finishAtDepthOne();
            break;
        }

        if (solver.depth <= 14) {
            long long requiredMoves = 6LL * ((1LL << solver.depth) - 1);
            if (movesUsed + requiredMoves <= MOVE_LIMIT) {
                exhaustiveSearch(0, -1, solver.depth);
                return 0;
            }
        }

        int selectedLength = 0;
        int maximumLength = min(10, solver.depth);

        for (int length = maximumLength; length >= 1; --length) {
            if (solver.canRunProbe(length)) {
                selectedLength = length;
                break;
            }
        }

        if (selectedLength == 0) {
            solver.directAscend();
        } else {
            solver.probe(selectedLength);
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int NXT[4][2] = {
    {1, 2},
    {-1, 2},
    {0, 3},
    {0, -1}
};

struct Endgame {
    static const int INF = 1000000000;
    vector<int> dist, move;
    vector<vector<int>> patterns;

    static int nextConfig(int key, int qmask, int reply) {
        int m = key >> 8;
        int states = key & 255;
        int newMask = 0, newM = 0;

        for (int i = 0; i < m; i++) {
            int s = (states >> (2 * i)) & 3;
            int b = (qmask >> i) & 1;
            int h = reply ^ b;
            int ns = NXT[s][h];
            if (ns != -1) {
                newMask |= ns << (2 * newM);
                newM++;
            }
        }

        if (newM <= 2) return -1;
        return (newM << 8) | newMask;
    }

    Endgame() {
        dist.assign(5 << 8, INF);
        move.assign(5 << 8, -1);
        patterns.resize(5);

        for (int m = 3; m <= 4; m++) {
            for (int i = 0; i < m; i++) {
                for (int j = i; j < m; j++) {
                    int mask = 0;
                    for (int k = i; k <= j; k++) mask |= 1 << k;
                    patterns[m].push_back(mask);
                }
            }
        }

        vector<int> configs;
        for (int m = 3; m <= 4; m++) {
            int lim = 1 << (2 * m);
            for (int mask = 0; mask < lim; mask++) {
                configs.push_back((m << 8) | mask);
            }
        }

        for (int pass = 0; pass < 1000; pass++) {
            bool changed = false;

            for (int key : configs) {
                int m = key >> 8;
                int best = dist[key];
                int bestMove = move[key];

                for (int qmask : patterns[m]) {
                    bool ok = true;
                    int worst = 0;

                    for (int reply = 0; reply < 2; reply++) {
                        int nk = nextConfig(key, qmask, reply);
                        if (nk == -1) continue;
                        if (dist[nk] >= INF) {
                            ok = false;
                            break;
                        }
                        worst = max(worst, dist[nk]);
                    }

                    if (ok && worst + 1 < best) {
                        best = worst + 1;
                        bestMove = qmask;
                    }
                }

                if (best < dist[key]) {
                    dist[key] = best;
                    move[key] = bestMove;
                    changed = true;
                }
            }

            if (!changed) break;
        }
    }
};

struct Candidate {
    int roll, state;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Endgame endgame;

    int T;
    cin >> T;

    const long double PHI = (1.0L + sqrtl(5.0L)) / 2.0L;

    while (T--) {
        int n;
        cin >> n;

        vector<Candidate> candidates;
        candidates.reserve(n);

        auto ask = [&](int l, int r) {
            cout << "? " << l << ' ' << r << '\n' << flush;
            int x;
            cin >> x;
            return x - (r - l);
        };

        auto applyQuery = [&](int l, int r, int reply) {
            vector<Candidate> next;
            next.reserve(candidates.size());

            for (const Candidate &c : candidates) {
                int b = (l <= c.roll && c.roll <= r) ? 1 : 0;
                int h = reply ^ b;
                int ns = NXT[c.state][h];
                if (ns != -1) next.push_back({c.roll, ns});
            }

            candidates.swap(next);
        };

        int firstReply = ask(1, n);
        int firstHonesty = firstReply ^ 1;
        int initialState = (firstHonesty == 0 ? 0 : 2);

        for (int i = 1; i <= n; i++) {
            candidates.push_back({i, initialState});
        }

        auto configurationKey = [&]() {
            int m = (int)candidates.size();
            int mask = 0;
            for (int i = 0; i < m; i++) {
                mask |= candidates[i].state << (2 * i);
            }
            return (m << 8) | mask;
        };

        while (candidates.size() > 2) {
            bool usedEndgame = false;

            if (candidates.size() <= 4) {
                int key = configurationKey();
                if (endgame.dist[key] < Endgame::INF && endgame.move[key] != -1) {
                    int qmask = endgame.move[key];
                    int first = -1, last = -1;

                    for (int i = 0; i < (int)candidates.size(); i++) {
                        if ((qmask >> i) & 1) {
                            if (first == -1) first = i;
                            last = i;
                        }
                    }

                    int l = candidates[first].roll;
                    int r = candidates[last].roll;
                    int reply = ask(l, r);
                    applyQuery(l, r, reply);
                    usedEndgame = true;
                }
            }

            if (usedEndgame) continue;

            int m = candidates.size();
            vector<long double> d(m);
            long double U = 0, V = 0;

            for (int i = 0; i < m; i++) {
                int s = candidates[i].state;
                long double u, v;

                if (s == 0) {
                    u = 1;
                    v = PHI;
                } else if (s == 1) {
                    u = 0;
                    v = PHI;
                } else if (s == 2) {
                    u = PHI;
                    v = 1;
                } else {
                    u = PHI;
                    v = 0;
                }

                U += u;
                V += v;
                d[i] = v - u;
            }

            long double target = (V - U) / 2;
            long double prefix = 0;
            long double bestDifference = numeric_limits<long double>::infinity();
            int bestR = n;
            int index = 0;

            for (int r = 1; r <= n; r++) {
                while (index < m && candidates[index].roll == r) {
                    prefix += d[index];
                    index++;
                }

                long double difference = fabsl(prefix - target);
                if (difference < bestDifference) {
                    bestDifference = difference;
                    bestR = r;
                }
            }

            int reply = ask(1, bestR);
            applyQuery(1, bestR, reply);
        }

        auto guess = [&](int roll) {
            cout << "! " << roll << '\n' << flush;
            int y;
            cin >> y;
            return y;
        };

        int result = guess(candidates[0].roll);
        if (result == 0 && candidates.size() > 1) {
            guess(candidates[1].roll);
        }

        cout << "#\n" << flush;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Candidate {
    int roll;
    int h = 0;
    int run = 0;
};

static vector<Candidate> applyAnswer(const vector<Candidate>& cs,
                                     const vector<int>& z, int y) {
    vector<Candidate> nxt;
    for (int i = 0; i < (int)cs.size(); ++i) {
        int required = y ^ z[i];
        Candidate d = cs[i];

        if (d.run == 0) {
            d.h = required;
            d.run = 1;
        } else {
            if (d.run == 2 && required == d.h) continue;
            if (required == d.h) {
                d.run = 2;
            } else {
                d.h = required;
                d.run = 1;
            }
        }
        nxt.push_back(d);
    }
    return nxt;
}

static const vector<pair<int, int>> smallBounds = {
    {0, 0}, {0, 1}, {0, 2}, {1, 1}, {1, 2}, {2, 2}
};

static vector<vector<int>> smallPatterns() {
    vector<vector<int>> p;
    for (auto [a, b] : smallBounds) {
        vector<int> z(3, 0);
        for (int i = a; i <= b; ++i) z[i] = 1;
        p.push_back(z);
    }
    return p;
}

static const vector<vector<int>> patterns3 = smallPatterns();
static unordered_map<string, int> memoSmall;
static unordered_map<string, int> choiceSmall;

static string smallKey(const vector<Candidate>& cs, int depth) {
    string s = to_string(depth) + ":";
    for (const auto& c : cs) {
        s.push_back(char('0' + c.h * 2 + (c.run - 1)));
        s.push_back(',');
    }
    return s;
}

static bool solveSmall(const vector<Candidate>& cs, int depth) {
    if ((int)cs.size() <= 2) return true;
    if (depth == 0) return false;

    string key = smallKey(cs, depth);
    auto it = memoSmall.find(key);
    if (it != memoSmall.end()) return it->second;

    for (int p = 0; p < 6; ++p) {
        bool ok = true;
        for (int y = 0; y <= 1; ++y) {
            vector<Candidate> nxt = applyAnswer(cs, patterns3[p], y);
            if (!nxt.empty() && !solveSmall(nxt, depth - 1)) {
                ok = false;
                break;
            }
        }
        if (ok) {
            memoSmall[key] = 1;
            choiceSmall[key] = p;
            return true;
        }
    }

    memoSmall[key] = 0;
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
