        vector<Candidate> cs(n);
        for (int i = 0; i < n; ++i) cs[i].roll = i + 1;

        int queryCount = 0;

        auto ask = [&](int l, int r) {
            cout << "? " << l << " " << r << endl;
            int x;
            cin >> x;

            ++queryCount;
            int len = r - l + 1;
            int y = (x == len ? 1 : 0);

            vector<int> z(cs.size(), 0);
            for (int i = 0; i < (int)cs.size(); ++i) {
                if (l <= cs[i].roll && cs[i].roll <= r) z[i] = 1;
            }
            cs = applyAnswer(cs, z, y);
        };

        auto synchronized = [&]() {
            if (cs.empty()) return true;
            int h = cs[0].h;
            for (const auto& c : cs) {
                if (c.run != 1 || c.h != h) return false;
            }
            return true;
        };

        ask(1, n);

        while ((int)cs.size() > 3) {
            int m = cs.size();
            int firstCount = m / 2;
            ask(1, cs[firstCount - 1].roll);

            m = cs.size();
            if (cs[0].run == 2) {
                int runTwoCount = 0;
                while (runTwoCount < m && cs[runTwoCount].run == 2) {
                    ++runTwoCount;
                }
                int take = runTwoCount / 2;
                ask(1, cs[take - 1].roll);
            } else {
                int start = 0;
                while (start < m && cs[start].run != 2) ++start;
                int runTwoCount = m - start;
                int take = runTwoCount / 2;
                ask(1, cs[start + take - 1].roll);
            }

            if ((int)cs.size() > 3) {
                while (!synchronized()) ask(1, n);
            }
        }

        if ((int)cs.size() > 2) {
            memoSmall.clear();
            choiceSmall.clear();

            int depth = 1;
            while (!solveSmall(cs, depth)) ++depth;

            while ((int)cs.size() > 2) {
                string key = smallKey(cs, depth);
                int p = choiceSmall[key];
                auto [a, b] = smallBounds[p];
                ask(cs[a].roll, cs[b].roll);
                --depth;
            }
        }

        if (!cs.empty()) {
            cout << "! " << cs[0].roll << endl;
            int result;
            cin >> result;

            if (result == 0 && cs.size() == 2) {
                cout << "! " << cs[1].roll << endl;
                cin >> result;
            }
        }

        cout << "#" << endl;
    }

    return 0;
}

