static inline int gf_mul(int a, int b, int k, int poly) {
    int res = 0;
    const int top = 1 << k;
    while (b) {
        if (b & 1) res ^= a;
        b >>= 1;
        a <<= 1;
        if (a & top) a ^= poly;
    }
    return res & (top - 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    const int poly[13] = {
        0, 0x3, 0x7, 0xB, 0x13, 0x25, 0x43,
        0x83, 0x11D, 0x211, 0x409, 0x805, 0x1053
    };

    int bestCount = 1;
    int bestK = -1, bestType = 0, bestC = 0;

    for (int k = 1; k <= 12; ++k) {
        const int q = 1 << k;
        vector<int> cube(q);

        for (int x = 0; x < q; ++x) {
            int sq = gf_mul(x, x, k, poly[k]);
            cube[x] = gf_mul(sq, x, k, poly[k]);
        }

        for (int c = 0; c < q; ++c) {
            int cnt0 = 0, cnt1 = 0;

            for (int x = 0; x < q; ++x) {
                int f = cube[x] ^ c;
                int v0 = (x << k) | f;
                int v1 = (f << k) | x;

                if (v0 >= 1 && v0 <= n) ++cnt0;
                if (v1 >= 1 && v1 <= n) ++cnt1;
            }

            if (cnt0 > bestCount) {
                bestCount = cnt0;
                bestK = k;
                bestType = 0;
                bestC = c;
            }
            if (cnt1 > bestCount) {
                bestCount = cnt1;
                bestK = k;
                bestType = 1;
                bestC = c;
            }
        }
    }

    vector<int> answer;
    if (bestK == -1) {
        answer.push_back(1);
    } else {
        const int k = bestK;
        const int q = 1 << k;
        vector<int> cube(q);

        for (int x = 0; x < q; ++x) {
            int sq = gf_mul(x, x, k, poly[k]);
            cube[x] = gf_mul(sq, x, k, poly[k]);
        }

        for (int x = 0; x < q; ++x) {
            int f = cube[x] ^ bestC;
            int v = (bestType == 0)
                  ? ((x << k) | f)
                  : ((f << k) | x);
            if (v >= 1 && v <= n) answer.push_back(v);
        }
    }

    cout << answer.size() << '\n';
    for (size_t i = 0; i < answer.size(); ++i) {
        if (i) cout << ' ';
        cout << answer[i];
    }
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int gfMul(int a, int b, int k, int poly) {
    int res = 0;
    int mask = (1 << k) - 1;
    for (int i = 0; i < k; ++i) {
        if (b & 1) res ^= a;
        b >>= 1;
        bool carry = (a >> (k - 1)) & 1;
        a = (a << 1) & mask;
        if (carry) a ^= (poly & mask);
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
