        vector<int> cur;

        for (int x = 0; x < q; ++x) {
            int x2 = gfMul(x, x, k, polys[k]);
            int x3 = gfMul(x2, x, k, polys[k]);
            int low = x3 ^ 1;
            int value = (x << k) | low;
            if (value <= n) cur.push_back(value);
        }

