        }
        if (ok) {
            candidates.push_back(id + 1);
        }
    }

    int a = candidates[0];
    int b = candidates.size() == 1 ? candidates[0] : candidates[1];
    cout << "! " << a << ' ' << b << '\n';
    cout.flush();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static constexpr int N = 1000;
static constexpr int BITS = 10;
static constexpr int LIMIT = (1 << BITS) - 1;

/*
For two labels a and b, let d = a XOR b and D = support(d).

After querying both the zero-set and the one-set of every bit, we know
the unordered pair of bits at each position. The only remaining ambiguity
is that, independently at every bit in D, the two labels may be swapped.

For a parity mask t, querying positions for which parity(label & t) is 1
distinguishes such a swap at a nonempty proper subset S of D exactly when

    parity(t & D) = 0 and parity(t & S) = 1.

The following routine constructs a small family of parity masks hitting
every possible pair (D, S).
*/
static vector<int> buildHittingSet() {
    constexpr int MASKS = 1 << BITS;
    constexpr int WORDS = MASKS / 64;

    int constraintCount = 0;
    for (int d = 1; d <= LIMIT; ++d) {
        constraintCount += (1 << __builtin_popcount((unsigned)d)) - 2;
    }

    vector<uint64_t> rows((size_t)constraintCount * WORDS, 0);
    vector<int> gain(MASKS, 0);

    int index = 0;
    for (int d = 1; d <= LIMIT; ++d) {
        for (int s = (d - 1) & d; s; s = (s - 1) & d) {
            uint64_t *row = rows.data() + (size_t)index * WORDS;

            int p = s & -s;
            int difference = d ^ s;
            int q = difference & -difference;
            int freeMask = LIMIT ^ (p | q);

            int u = freeMask;
            while (true) {
                int parityS = __builtin_parity(
                    (unsigned)(u & (s ^ p))
                );
                int parityDifference = __builtin_parity(
                    (unsigned)(u & (difference ^ q))
                );

                int valueP = 1 ^ parityS;
                int valueQ = 1 ^ parityDifference;

                int t = u;
                if (valueP) t |= p;
                if (valueQ) t |= q;

                row[t >> 6] |= 1ULL << (t & 63);
                ++gain[t];

                if (u == 0) break;
                u = (u - 1) & freeMask;
            }
            ++index;
        }
    }

    vector<unsigned char> covered(constraintCount, 0);
    vector<int> selected;
    int remaining = constraintCount;

    while (remaining > 0 && selected.size() < 45) {
        int best = -1;
        for (int t = 0; t < MASKS; ++t) {
            if (best == -1 || gain[t] > gain[best]) best = t;
        }

        if (best == -1 || gain[best] == 0) break;
        selected.push_back(best);

        for (int i = 0; i < constraintCount; ++i) {
            if (covered[i]) continue;

            const uint64_t *row = rows.data() + (size_t)i * WORDS;
            if (!(row[best >> 6] & (1ULL << (best & 63)))) continue;

            covered[i] = 1;
            --remaining;

            for (int w = 0; w < WORDS; ++w) {
                uint64_t values = row[w];
                while (values) {
                    int bit = __builtin_ctzll(values);
                    values &= values - 1;
                    --gain[(w << 6) | bit];
                }
            }
        }
    }

    if (remaining == 0 && selected.size() <= 45) {
        sort(selected.begin(), selected.end());
        return selected;
    }

    // Every pair (D, S) is hit by a mask {i,j} with i in S and j in D\S.
    vector<int> fallback;
    for (int i = 0; i < BITS; ++i) {
        for (int j = i + 1; j < BITS; ++j) {
            fallback.push_back((1 << i) | (1 << j));
        }
    }
    return fallback;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int R, H;
    if (!(cin >> R >> H)) return 0;

    vector<int> parityMasks = buildHittingSet();

    vector<uint16_t> valueMask(N), zeroMask(N);
    vector<uint64_t> checksumMask(N, 0);

    for (int label = 0; label < N; ++label) {
        uint16_t ones = 0;
        for (int bit = 0; bit < BITS; ++bit) {
            if ((label >> bit) & 1) ones |= uint16_t(1 << bit);
        }
        valueMask[label] = ones;
        zeroMask[label] = uint16_t(LIMIT ^ ones);

        for (int j = 0; j < (int)parityMasks.size(); ++j) {
            if (__builtin_parity((unsigned)(label & parityMasks[j]))) {
                checksumMask[label] |= 1ULL << j;
            }
        }
    }

    vector<vector<int>> queries;
    queries.reserve(20 + parityMasks.size());

    for (int bit = 0; bit < BITS; ++bit) {
        vector<int> zeros, ones;
        for (int position = 0; position < N; ++position) {
            if ((position >> bit) & 1) {
                ones.push_back(position + 1);
            } else {
                zeros.push_back(position + 1);
            }
        }
        queries.push_back(move(zeros));
        queries.push_back(move(ones));
    }

    for (int t : parityMasks) {
        vector<int> positions;
        for (int position = 0; position < N; ++position) {
            if (__builtin_parity((unsigned)(position & t))) {
                positions.push_back(position + 1);
            }
        }
        queries.push_back(move(positions));
    }

    for (const auto &query : queries) {
        cout << "? " << query.size();
        for (int position : query) cout << ' ' << position;
        cout << endl;
    }

    cout << "@" << endl;

    int returned;
    if (!(cin >> returned)) return 0;

    vector<int> response(returned);
    for (int &answer : response) {
        if (!(cin >> answer)) return 0;
    }

    int required = 20 + (int)parityMasks.size();
    if (returned < required) return 0;

    uint16_t observedOnes = 0;
    uint16_t observedZeros = 0;

    for (int bit = 0; bit < BITS; ++bit) {
        if (response[2 * bit]) observedOnes |= uint16_t(1 << bit);
        if (response[2 * bit + 1]) observedZeros |= uint16_t(1 << bit);
    }

    uint64_t observedChecksum = 0;
    for (int j = 0; j < (int)parityMasks.size(); ++j) {
        if (response[20 + j]) observedChecksum |= 1ULL << j;
    }

    int answerA = -1, answerB = -1;

    for (int a = 0; a < N && answerA == -1; ++a) {
        for (int b = a; b < N; ++b) {
            if ((valueMask[a] | valueMask[b]) != observedOnes) continue;
            if ((zeroMask[a] | zeroMask[b]) != observedZeros) continue;
            if ((checksumMask[a] | checksumMask[b]) != observedChecksum) continue;

            answerA = a + 1;
            answerB = b + 1;
            break;
        }
    }

    if (answerA == -1) return 0;

    cout << "! " << answerA << ' ' << answerB << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, k;

char ask(int c) {
    cout << "? " << c << '\n';
    cout.flush();
    char r;
    if (!(cin >> r)) exit(0);
    return r;
}

struct Node {
    int side;
    int idx;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n >> k)) return 0;

    if (n == 1) {
        cout << "! 1\n";
        cout.flush();
        return 0;
    }

    if (k == 1) {
        vector<int> reps;

        for (int i = 1; i <= n; i++) {
            if (ask(i) == 'Y') continue;

            if (reps.empty()) {
                reps.push_back(i);
                continue;
            }

            int p = (int)reps.size();

            ask(reps[0]);
            if (ask(i) == 'Y') continue;

            if (p == 1) {
                reps.push_back(i);
                continue;
            }

            bool duplicate = false;
            for (int j = 1; j < p; j++) {
                if (ask(reps[j]) == 'Y') {
                    duplicate = true;
                    break;
                }
                if (j + 1 < p) ask(i);
            }

            if (!duplicate) reps.push_back(i);
        }

        cout << "! " << reps.size() << '\n';
        cout.flush();
        return 0;
    }

    vector<int> reps;

    for (int block = 0; block < n; block += k) {
        vector<int> cand;

        for (int j = 0; j < k; j++) {
            int id = block + j + 1;
            if (ask(id) == 'N') cand.push_back(id);
        }

        if (cand.empty()) continue;

        if (reps.empty()) {
            reps = cand;
            continue;
        }

        int p = (int)reps.size();
        int q = (int)cand.size();

        vector< bitset<1024> > compared(q);
        vector<int> comparedCount(q, 0);
        vector<unsigned char> state(q, 0);
        int resolved = 0;

        auto addComparison = [&](int b, int g) {
            if (!compared[b].test(g)) {
                compared[b].set(g);
                comparedCount[b]++;
                if (state[b] == 0 && comparedCount[b] == p) {
                    state[b] = 2;
                    resolved++;
                }
            }
        };

        deque<Node> memory;

        int firstLen = min(p, k);
        int initialPadding = k - firstLen;

        for (int i = 0; i < initialPadding; i++) {
            ask(reps[0]);
            memory.push_back({0, 0});
        }
        for (int i = 0; i < firstLen; i++) {
            ask(reps[i]);
            memory.push_back({0, i});
        }

        auto processNode = [&](int side, int idx) {
            int bakery = (side == 0 ? reps[idx] : cand[idx]);
            char response = ask(bakery);

            if (response == 'N') {
                if (side == 1) {
                    for (const Node &node : memory) {
                        if (node.side == 0) addComparison(idx, node.idx);
                    }
                } else {
                    for (const Node &node : memory) {
                        if (node.side == 1) addComparison(node.idx, idx);
                    }
                }
            } else if (side == 1 && state[idx] == 0) {
                bool selfInMemory = false;
                for (const Node &node : memory) {
                    if (node.side == 1 && node.idx == idx) {
                        selfInMemory = true;
                        break;
                    }
                }
                if (!selfInMemory) {
                    state[idx] = 1;
                    resolved++;
                }
            }

            memory.push_back({side, idx});
            if ((int)memory.size() > k) memory.pop_front();
        };

        int groups = (p + k - 1) / k;

        for (int i = 0; i < groups && resolved < q; i++) {
            for (int b = 0; b < q && resolved < q; b++) {
                processNode(1, b);
            }

            if (resolved == q) break;

            int gblock = (i + 1 < groups ? i + 1 : 0);
            int begin = gblock * k;
            int end = min(p, begin + k);

            for (int g = begin; g < end && resolved < q; g++) {
                processNode(0, g);
            }
        }

        vector<int> unresolved;
        for (int b = 0; b < q; b++) {
            if (state[b] == 0) unresolved.push_back(b);
        }

        if (!unresolved.empty()) {
            for (int i = 0; i < k; i++) ask(reps[0]);

            int h = k / 2;
            int u = (int)unresolved.size();

            for (int ds = 0; ds < u; ds += h) {
                int de = min(u, ds + h);
                int dsize = de - ds;

                for (int gs = 0; gs < p; gs += h) {
                    bool needed = false;
                    for (int di = ds; di < de; di++) {
                        if (state[unresolved[di]] == 0) {
                            needed = true;
                            break;
                        }
                    }
                    if (!needed) break;

                    int ge = min(p, gs + h);
                    int gsize = ge - gs;

                    if (gs > 0) {
                        int padding = k - gsize - dsize + 1;
                        for (int i = 0; i < padding; i++) ask(reps[0]);
                    }

                    for (int g = gs; g < ge; g++) ask(reps[g]);

                    for (int di = ds; di < de; di++) {
                        int b = unresolved[di];
                        if (ask(cand[b]) == 'Y') state[b] = 1;
                    }
                }
            }
        }

        for (int b = 0; b < q; b++) {
            if (state[b] != 1) reps.push_back(cand[b]);
        }
    }

    cout << "! " << reps.size() << '\n';
    cout.flush();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, k;

char ask(int c) {
    cout << "? " << c << endl;
    char response;
    cin >> response;
    return response;
}

struct DSU {
    vector<int> parent, size;
    explicit DSU(int n) : parent(n), size(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
    }
};

int solveWithCapacityOne(const vector<int>& items) {
    int m = (int)items.size();
    if (m <= 1) return m;

    vector<vector<pair<int, int>>> adjacency(m);
    vector<char> used;
    int edgeCount = 0;

    auto addEdge = [&](int u, int v) {
        int id = edgeCount++;
        adjacency[u].push_back({v, id});
        adjacency[v].push_back({u, id});
    };

    for (int i = 0; i < m; ++i) {
        for (int j = i + 1; j < m; ++j) {
            addEdge(i, j);
        }
    }

    if (m % 2 == 0) {
        for (int i = 0; i < m; i += 2) {
            addEdge(i, i + 1);
        }
    }

    used.assign(edgeCount, 0);
    vector<int> nextEdge(m, 0), st, circuit;
    st.push_back(0);

    while (!st.empty()) {
        int v = st.back();
        while (nextEdge[v] < (int)adjacency[v].size() &&
               used[adjacency[v][nextEdge[v]].second]) {
            ++nextEdge[v];
        }

        if (nextEdge[v] == (int)adjacency[v].size()) {
            circuit.push_back(v);
            st.pop_back();
        } else {
            auto [to, id] = adjacency[v][nextEdge[v]++];
            if (used[id]) continue;
            used[id] = 1;
            st.push_back(to);
        }
    }

    reverse(circuit.begin(), circuit.end());

    DSU dsu(m);
    ask(items[circuit[0]]);
    for (int i = 1; i < (int)circuit.size(); ++i) {
        int previous = circuit[i - 1];
        int current = circuit[i];
        if (ask(items[current]) == 'Y') {
            dsu.unite(previous, current);
        }
    }

    int answer = 0;
    for (int i = 0; i < m; ++i) {
        if (dsu.find(i) == i) ++answer;
    }
    return answer;
}

int solveWithSmallCapacity(const vector<int>& items) {
    vector<int> representatives;

    for (int item : items) {
        bool duplicate = false;

        for (size_t start = 0;
             start < representatives.size() && !duplicate;
             start += k) {
            int length = (int)min((size_t)k,
                                  representatives.size() - start);

            for (int t = 0; t < k; ++t) {
                ask(representatives[start + t % length]);
            }
            if (ask(item) == 'Y') duplicate = true;
        }

        if (!duplicate) representatives.push_back(item);
    }

    return (int)representatives.size();
}

long long estimatedMergeCost(int a, int b) {
    if (a == 0 || b == 0) return 0;
    long long aChunks = (a + k - 1) / k;
    long long bBatches = (b + k - 1) / k;
    return 2LL * aChunks * (bBatches * k + b);
}

vector<int> mergeSets(const vector<int>& first,
                      const vector<int>& second) {
    if (first.empty()) return second;
    if (second.empty()) return first;

    const vector<int>* A = &first;
    const vector<int>* B = &second;

    if (estimatedMergeCost((int)second.size(), (int)first.size()) <
        estimatedMergeCost((int)first.size(), (int)second.size())) {
        swap(A, B);
    }

    vector<int> result = *A;
    result.reserve(A->size() + B->size());

    for (int bStart = 0; bStart < (int)B->size(); bStart += k) {
        int bLength = min(k, (int)B->size() - bStart);
        vector<char> duplicate(bLength, 0);

        for (int aStart = 0; aStart < (int)A->size(); aStart += k) {
            bool allFound = true;
            for (char value : duplicate) {
                if (!value) {
                    allFound = false;
                    break;
                }
            }
            if (allFound) break;

            int aLength = min(k, (int)A->size() - aStart);
            vector<int> padded(k);
            for (int t = 0; t < k; ++t) {
                padded[t] = (*A)[aStart + t % aLength];
            }

            for (int t = 0; t < k; ++t) ask(padded[t]);
            for (int j = 0; j < bLength; ++j) {
                if (ask((*B)[bStart + j]) == 'Y') {
                    duplicate[j] = 1;
                }
            }

            for (int t = k - 1; t >= 0; --t) ask(padded[t]);
            for (int j = bLength - 1; j >= 0; --j) {
                if (ask((*B)[bStart + j]) == 'Y') {
                    duplicate[j] = 1;
                }
            }
        }

        for (int j = 0; j < bLength; ++j) {
            if (!duplicate[j]) result.push_back((*B)[bStart + j]);
        }
    }

    return result;
}

vector<int> solveBlocks(const vector<vector<int>>& blocks, int left, int right) {
    if (right - left == 1) return blocks[left];
    int middle = (left + right) / 2;
    vector<int> a = solveBlocks(blocks, left, middle);
    vector<int> b = solveBlocks(blocks, middle, right);
    return mergeSets(a, b);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;

    vector<vector<int>> blocks(n / k);
    vector<int> candidates;

    for (int i = 1; i <= n; ++i) {
        if (ask(i) == 'N') {
            blocks[(i - 1) / k].push_back(i);
            candidates.push_back(i);
        }
    }

    int answer;
    if (k == n || candidates.size() <= 1) {
        answer = (int)candidates.size();
    } else if (k == 1) {
        answer = solveWithCapacityOne(candidates);
    } else if (k == 2) {
        answer = solveWithSmallCapacity(candidates);
    } else {
        answer = (int)solveBlocks(blocks, 0, (int)blocks.size()).size();
    }

    cout << "! " << answer << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

char ask(int c) {
    cout << "? " << c << "\n";
    cout.flush();
    char ans;
    cin >> ans;
    return ans;
}

void reset_mem() {
    cout << "R\n";
    cout.flush();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    if (!(cin >> n >> k)) return 0;

    if (n == 1) {
        cout << "! 1\n";
        cout.flush();
        return 0;
    }

    if (k >= n) {
        reset_mem();
        int d = 0;
        for (int i = 1; i <= n; ++i) {
            char ans = ask(i);
            if (ans == 'N') ++d;
        }
        cout << "! " << d << "\n";
        cout.flush();
        return 0;
    }

    if (k == 1) {
        vector<int> reps;
        for (int i = 1; i <= n; ++i) {
            if (reps.empty()) {
                reps.push_back(i);
                continue;
            }
            int D = reps.size();
            bool dup = false;
            for (int j = 0; j < D; j += 2) {
                ask(reps[j]);
                char ans = ask(i);
                if (ans == 'Y') { dup = true; break; }
                if (j + 1 < D) {
                    ans = ask(reps[j+1]);
                    if (ans == 'Y') { dup = true; break; }
                }
            }
            if (!dup) reps.push_back(i);
        }
        cout << "! " << reps.size() << "\n";
        cout.flush();
        return 0;
    }

    // k >= 2 and k < n
    vector<int> global_reps;
    for (int start = 1; start <= n; start += k) {
        int end = min(n, start + k - 1);
        reset_mem();
        vector<int> C;
        for (int i = start; i <= end; ++i) {
            char ans = ask(i);
            if (ans == 'N') C.push_back(i);
        }
        int D_old = global_reps.size();
        if (D_old == 0) {
            for (int c : C) global_reps.push_back(c);
            continue;
        }
        vector<int> new_c;
        if (D_old < k) {
            reset_mem();
            for (int c : C) {
                bool dup = false;
                for (int idx : global_reps) {
                    ask(idx);
                }
                char ans = ask(c);
                if (ans == 'Y') dup = true;
                if (!dup) new_c.push_back(c);
            }
        } else {
            for (int c : C) {
                bool dup = false;
                int fullChunks = D_old / k;
                int rem = D_old % k;
                for (int h = 0; h < fullChunks; ++h) {
                    for (int t = 0; t < k; ++t) {
                        ask(global_reps[h * k + t]);
                    }
                    char ans = ask(c);
                    if (ans == 'Y') { dup = true; break; }
                }
                if (!dup && rem > 0) {
                    int startRep = fullChunks * k;
                    for (int t = 0; t < rem; ++t) {
                        ask(global_reps[startRep + t]);
                    }
                    for (int t = 0; t < k - rem; ++t) {
                        ask(global_reps[t]);
                    }
                    char ans = ask(c);
                    if (ans == 'Y') dup = true;
                }
                if (!dup) new_c.push_back(c);
            }
        }
        for (int c : new_c) global_reps.push_back(c);
    }

    cout << "! " << global_reps.size() << "\n";
    cout.flush();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class BakerySurvey {
private:
    int n, k;
    long long queryCount = 0;
    long long resetCount = 0;
    int nextLeaf = 0;
    int blockSize;

    bool ask(int c) {
        cout << "? " << c << '\n';
        cout.flush();

        char response;
        if (!(cin >> response)) exit(0);
        if (response != 'Y' && response != 'N') exit(0);

        ++queryCount;
        return response == 'Y';
    }

    void resetMemory() {
        cout << "R\n";
        cout.flush();
        ++resetCount;
    }

    vector<int> buildLeaf(int left, int right) {
        if (nextLeaf++ > 0) resetMemory();

        vector<int> representatives;
        for (int c = left + 1; c <= right; ++c) {
            if (!ask(c)) representatives.push_back(c);
        }
        return representatives;
    }

    vector<int> mergeSets(const vector<int>& source,
                          const vector<int>& target) {
        int a = static_cast<int>(source.size());
        int b = static_cast<int>(target.size());

        if (a == 0) return target;
        if (b == 0) return source;

        if (a + b <= k + 1) {
            for (int c : source) ask(c);

            vector<char> matched(b, false);
            for (int i = 0; i < b; ++i) {
                if (ask(target[i])) matched[i] = true;
            }

            vector<int> result = source;
            result.reserve(a + b);
            for (int i = 0; i < b; ++i) {
                if (!matched[i]) result.push_back(target[i]);
            }
            return result;
        }

        long long bestOperations = LLONG_MAX;
        int bestSourceChunk = 1;
        int bestTargetChunk = k;

        for (int s = 1; s <= k; ++s) {
            int t = k + 1 - s;
            long long sourceChunks = (a + s - 1) / s;
            long long targetChunks = (b + t - 1) / t;
            long long operations = sourceChunks * targetChunks * (k + 1LL);

            if (operations < bestOperations) {
                bestOperations = operations;
                bestSourceChunk = s;
                bestTargetChunk = t;
            }
        }

        int s = bestSourceChunk;
        int t = bestTargetChunk;

        vector<char> matched(b, false);

        for (int sourceLeft = 0; sourceLeft < a; sourceLeft += s) {
            int sourceRight = min(a, sourceLeft + s);

            for (int targetLeft = 0; targetLeft < b; targetLeft += t) {
                int targetRight = min(b, targetLeft + t);

                for (int i = sourceLeft; i < sourceRight; ++i) {
                    ask(source[i]);
                }
                for (int i = sourceLeft; i < sourceRight; ++i) {
                    ask(source[i]);
                }

                for (int i = targetLeft; i < targetRight; ++i) {
                    if (ask(target[i])) matched[i] = true;
                }

                int padding = t - (targetRight - targetLeft);
                for (int i = 0; i < padding; ++i) {
                    ask(source[sourceLeft]);
                }
            }
        }

        vector<int> result = source;
        result.reserve(a + b);
        for (int i = 0; i < b; ++i) {
            if (!matched[i]) result.push_back(target[i]);
        }
        return result;
    }

    vector<int> solve(int left, int right) {
        if (right - left == 1) {
            return buildLeaf(left * blockSize,
                             min(n, (left + 1) * blockSize) - 1);
        }

        int middle = (left + right) / 2;
        vector<int> first = solve(left, middle);
        vector<int> second = solve(middle, right);
        return mergeSets(second, first);
    }

public:
    BakerySurvey(int n, int k) : n(n), k(k) {
        blockSize = k + 1;
    }

    int run() {
        int leafCount = (n + blockSize - 1) / blockSize;
        vector<int> representatives = solve(0, leafCount);
        return static_cast<int>(representatives.size());
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    BakerySurvey solver(n, k);
    int answer = solver.run();

    cout << "! " << answer << '\n';
    cout.flush();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class Solver {
    static constexpr int H = 50;
    static constexpr int W = 50;
    static constexpr int dr[4] = {-1, 1, 0, 0};
    static constexpr int dc[4] = {0, 0, -1, 1};

    int si, sj, startCell, M = 0;
    int id[H][W], val[H][W];
    vector<int> tileWeight;
    vector<vector<int>> adj;

    vector<unsigned char> vis;
    vector<int> pos;
    vector<int> path, bestPath;
    int bestScore = 0;

    vector<int> seen, bfsQueue;
    int bfsStamp = 0;

    uint32_t rngState = 0x9e3779b9u;
    chrono::steady_clock::time_point deadline;

    uint32_t rnd() {
        rngState ^= rngState << 13;
        rngState ^= rngState >> 17;
        rngState ^= rngState << 5;
        return rngState;
    }

    int randint(int n) {
        return n <= 0 ? 0 : int(rnd() % uint32_t(n));
    }

    bool expired() const {
        return chrono::steady_clock::now() >= deadline;
    }

    inline bool inside(int r, int c) const {
        return 0 <= r && r < H && 0 <= c && c < W;
    }

    int onwardDegree(int cell, int enteringTile) const {
        int r = cell / W, c = cell % W;
        int degree = 0;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d], nc = c + dc[d];
            if (!inside(nr, nc)) continue;
            int nt = id[nr][nc];
            if (nt != enteringTile && !vis[nt]) ++degree;
        }
        return degree;
    }

    void reachableFrom(int cell, int enteringTile, int &count, int &weightSum) {
        vis[enteringTile] = 1;
        ++bfsStamp;
        int qh = 0, qt = 0;
        count = 0;
        weightSum = 0;

        int r = cell / W, c = cell % W;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d], nc = c + dc[d];
            if (!inside(nr, nc)) continue;
            int nt = id[nr][nc];
            if (!vis[nt] && seen[nt] != bfsStamp) {
                seen[nt] = bfsStamp;
                bfsQueue[qt++] = nt;
            }
        }

        while (qh < qt) {
            int t = bfsQueue[qh++];
            ++count;
            weightSum += tileWeight[t];
            for (int u : adj[t]) {
                if (!vis[u] && seen[u] != bfsStamp) {
                    seen[u] = bfsStamp;
                    bfsQueue[qt++] = u;
                }
            }
        }
        vis[enteringTile] = 0;
    }

    void considerPath(bool allowEqualRandom = false) {
        int score = 0;
        for (int cell : path) score += val[cell / W][cell % W];

        bool replace = false;
        if (score > bestScore) replace = true;
        else if (score == bestScore && path.size() > bestPath.size()) replace = true;
        else if (allowEqualRandom && score == bestScore &&
                 path.size() == bestPath.size() && randint(8) == 0) replace = true;

        if (replace) {
            bestScore = score;
            bestPath = path;
        }
    }

    bool applyBackbite(int &stallLimit) {
        const int n = int(path.size());
        if (n < 3) return false;

        int endpoint = path.back();
        int er = endpoint / W, ec = endpoint % W;

        int candidateK[4];
        long long candidateKey[4];
        int candidateCount = 0;

        for (int d = 0; d < 4; ++d) {
            int nr = er + dr[d], nc = ec + dc[d];
            if (!inside(nr, nc)) continue;

            int t = id[nr][nc];
            if (!vis[t]) continue;
            int k = pos[t];
            if (k < 0 || k > n - 3) continue;

            int newEndpoint = path[k + 1];
            int rr = newEndpoint / W, cc = newEndpoint % W;
            int mobility = 0, bestNextValue = 0;

            for (int e = 0; e < 4; ++e) {
                int tr = rr + dr[e], tc = cc + dc[e];
                if (!inside(tr, tc)) continue;
                int nt = id[tr][tc];
                if (!vis[nt]) {
                    ++mobility;
                    bestNextValue = max(bestNextValue, val[tr][tc]);
                }
            }

            long long key;
            if (mobility > 0) {
                key = 1000000LL + bestNextValue * 100LL + mobility * 20LL + randint(256);
            } else {
                key = randint(10000);
            }

            candidateK[candidateCount] = k;
            candidateKey[candidateCount] = key;
            ++candidateCount;
        }

        if (candidateCount == 0) return false;

        int chosen = 0;
        for (int i = 1; i < candidateCount; ++i) {
            if (candidateKey[i] > candidateKey[chosen]) chosen = i;
        }

        int k = candidateK[chosen];
        reverse(path.begin() + k + 1, path.end());
        for (int i = k + 1; i < n; ++i) {
            int cell = path[i];
            pos[id[cell / W][cell % W]] = i;
        }
        return true;
    }

    void runAttempt(bool fromBest, int cut, int style, bool useConnectivity, int rotationLimit) {
        path.clear();
        if (fromBest && !bestPath.empty()) {
            path = bestPath;
            cut = min(cut, int(path.size()) - 1);
            path.resize(path.size() - cut);
        } else {
            path.push_back(startCell);
        }

        fill(vis.begin(), vis.end(), 0);
        fill(pos.begin(), pos.end(), -1);

        int score = 0;
        for (int i = 0; i < int(path.size()); ++i) {
            int cell = path[i];
            int t = id[cell / W][cell % W];
            vis[t] = 1;
            pos[t] = i;
            score += val[cell / W][cell % W];
        }

        int stall = 0;
        const int stepCap = useConnectivity ? 6500 : 10000;

        for (int step = 0; step < stepCap; ++step) {
            if ((step & 7) == 0 && expired()) break;

            int endpoint = path.back();
            int r = endpoint / W, c = endpoint % W;

            int bestCell = -1, bestTile = -1;
            long long bestKey = numeric_limits<long long>::min();

            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (!inside(nr, nc)) continue;

                int nt = id[nr][nc];
                if (vis[nt]) continue;

                int nextCell = nr * W + nc;
                int degree = onwardDegree(nextCell, nt);
                int squareValue = val[nr][nc];
                long long key = 0;

                if (useConnectivity) {
                    int reach = 0, reachWeight = 0;
                    if (degree > 0) {
                        reachableFrom(nextCell, nt, reach, reachWeight);
                    }

                    if ((style & 1) == 0) {
                        key = (reach + 1) * 100000LL
                            - degree * 1000LL
                            + squareValue * 8LL
                            + randint(128);
                    } else {
                        key = (reachWeight + tileWeight[nt]) * 1000LL
                            - degree * 180LL
                            + squareValue * 20LL
                            + randint(256);
                    }
                } else {
                    int terminalPenalty = (degree == 0 ? 200000 : 0);
                    switch (style % 6) {
                        case 0:
                            key = -degree * 2000LL + squareValue * 5LL + randint(256);
                            break;
                        case 1:
                            key = -degree * 600LL + squareValue * 15LL + randint(512);
                            break;
                        case 2:
                            key = -degree * 200LL + squareValue * 5LL + randint(3000);
                            break;
                        case 3:
                            key = degree * 350LL + squareValue * 8LL + randint(1200);
                            break;
                        case 4:
                            key = -degree * 1000LL + squareValue * 2LL + randint(1800);
                            break;
                        default:
                            key = -degree * 800LL + squareValue * 25LL + randint(256);
                            break;
                    }
                    key -= terminalPenalty;
                }

                if (key > bestKey) {
                    bestKey = key;
                    bestCell = nextCell;
                    bestTile = nt;
                }
            }

            if (bestCell >= 0) {
                vis[bestTile] = 1;
                pos[bestTile] = int(path.size());
                path.push_back(bestCell);
                score += val[bestCell / W][bestCell % W];
                stall = 0;

                if (score > bestScore && (path.size() & 31ULL) == 0) {
                    bestScore = score;
                    bestPath = path;
                }
            } else {
                if (stall >= rotationLimit) break;
                if (!applyBackbite(rotationLimit)) break;
                ++stall;
            }
        }

        considerPath(true);
    }

public:
    void solve() {
        auto beginTime = chrono::steady_clock::now();
        deadline = beginTime + chrono::milliseconds(1850);

        cin >> si >> sj;
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                cin >> id[i][j];
                M = max(M, id[i][j] + 1);
            }
        }
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                cin >> val[i][j];
            }
        }

        startCell = si * W + sj;
        vector<int> tileSum(M, 0), tileCells(M, 0);
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                int t = id[i][j];
                tileSum[t] += val[i][j];
                ++tileCells[t];
            }
        }

        tileWeight.resize(M);
        for (int t = 0; t < M; ++t) {
            tileWeight[t] = tileSum[t] / max(1, tileCells[t]);
        }

        adj.assign(M, {});
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                int a = id[i][j];
                if (i + 1 < H) {
                    int b = id[i + 1][j];
                    if (a != b) {
                        adj[a].push_back(b);
                        adj[b].push_back(a);
                    }
                }
                if (j + 1 < W) {
                    int b = id[i][j + 1];
                    if (a != b) {
                        adj[a].push_back(b);
                        adj[b].push_back(a);
                    }
                }
            }
        }
        for (auto &v : adj) {
            sort(v.begin(), v.end());
            v.erase(unique(v.begin(), v.end()), v.end());
        }

        vis.assign(M, 0);
        pos.assign(M, -1);
        seen.assign(M, 0);
        bfsQueue.resize(M);

        bestPath = {startCell};
        bestScore = val[si][sj];

        int attempt = 0;
        while (!expired()) {
            bool fromBest = attempt >= 2 && randint(100) < 74;
            int cut = 0;

            if (fromBest) {
                int maxCut = int(bestPath.size()) - 1;
                if (maxCut > 0) {
                    int type = randint(12);
                    if (type < 2) {
                        cut = 0;
                    } else if (type < 6) {
                        cut = 1 + randint(min(maxCut, 24));
                    } else if (type < 9) {
                        cut = 1 + randint(min(maxCut, 160));
                    } else {
                        cut = 1 + randint(maxCut);
                    }
                }
            }

            int style = attempt < 2 ? attempt : randint(6);
            bool useConnectivity = attempt < 2 || randint(100) < (fromBest ? 58 : 40);
            int rotationLimit = 35 + randint(100);
            if (fromBest && cut == 0) rotationLimit += 100;

            runAttempt(fromBest, cut, style, useConnectivity, rotationLimit);
            ++attempt;
        }

        string answer;
        answer.reserve(bestPath.size());
        for (int i = 1; i < int(bestPath.size()); ++i) {
            int a = bestPath[i - 1], b = bestPath[i];
            if (b == a - W) answer.push_back('U');
            else if (b == a + W) answer.push_back('D');
            else if (b == a - 1) answer.push_back('L');
            else answer.push_back('R');
        }
        cout << answer << '\n';
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Solver solver;
    solver.solve();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using Clock = chrono::steady_clock;

struct XorShift {
    uint64_t x = 0x9e3779b97f4a7c15ULL;
    uint32_t next() {
        x ^= x << 7;
        x ^= x >> 9;
        x ^= x << 8;
        return static_cast<uint32_t>(x >> 32);
    }
    int nextInt(int n) { return static_cast<int>(next() % n); }
};

struct Node {
    int parent;
    char dir;
};

struct State {
    array<uint64_t, 40> used{};
    int pos = 0;
    int score = 0;
    int node = 0;
};

struct Candidate {
    int rank;
    int score;
    int pos;
    int tile;
    int parent;
    char dir;
};

struct RankConfig {
    int lookahead;
    int mobility;
    uint32_t noiseMask;
};

const int H = 50, W = 50;
const int dr[4] = {-1, 1, 0, 0};
const int dc[4] = {0, 0, -1, 1};
const char dchar[4] = {'U', 'D', 'L', 'R'};

int startI, startJ;
int tileAt[H][W];
int tileWeight[2500];
int startPos;
XorShift rng;
Clock::time_point deadline;

int bestScore = -1;
string bestPath;

int charToDir(char c) {
    if (c == 'U') return 0;
    if (c == 'D') return 1;
    if (c == 'L') return 2;
    return 3;
}

void beamSearch(const string &prefix, int width, const RankConfig &cfg) {
    vector<Node> nodes;
    nodes.reserve(1024);
    nodes.push_back({-1, 0});

    State initial;
    initial.used.fill(0);
    initial.pos = startPos;
    int currentTile = tileAt[startPos / W][startPos % W];
    initial.used[currentTile >> 6] |= 1ULL << (currentTile & 63);
    initial.score = tileWeight[currentTile];
    initial.node = 0;

    int pos = startPos;
    int currentNode = 0;
    for (char c : prefix) {
        int d = charToDir(c);
        int r = pos / W + dr[d];
        int col = pos % W + dc[d];
        pos = r * W + col;
        int t = tileAt[r][col];
        initial.used[t >> 6] |= 1ULL << (t & 63);
        initial.score += tileWeight[t];
        nodes.push_back({currentNode, c});
        currentNode = static_cast<int>(nodes.size()) - 1;
    }
    initial.pos = pos;
    initial.node = currentNode;

    vector<State> current, next;
    vector<Candidate> candidates;
    current.reserve(width);
    next.reserve(width);
    candidates.reserve(width * 4);
    current.push_back(initial);

    auto buildPath = [&](int node, char extra) {
        string path;
        while (nodes[node].parent != -1) {
            path.push_back(nodes[node].dir);
            node = nodes[node].parent;
        }
        reverse(path.begin(), path.end());
        path.push_back(extra);
        return path;
    };

    while (!current.empty()) {
        if (Clock::now() >= deadline) return;
        candidates.clear();
        bool stopped = false;

        for (int i = 0; i < static_cast<int>(current.size()); ++i) {
            if ((i & 63) == 0 && Clock::now() >= deadline) {
                stopped = true;
                break;
            }

            const State &state = current[i];
            int r = state.pos / W;
            int c = state.pos % W;

            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;

                int np = nr * W + nc;
                int nt = tileAt[nr][nc];
                if ((state.used[nt >> 6] >> (nt & 63)) & 1ULL) continue;

                int ns = state.score + tileWeight[nt];
                if (ns > bestScore) {
                    bestScore = ns;
                    bestPath = buildPath(state.node, dchar[d]);
                }

                int degree = 0;
                int lookahead = 0;
                for (int e = 0; e < 4; ++e) {
                    int rr = nr + dr[e];
                    int cc = nc + dc[e];
                    if (rr < 0 || rr >= H || cc < 0 || cc >= W) continue;
                    int tt = tileAt[rr][cc];
                    if (tt == nt) continue;
                    if ((state.used[tt >> 6] >> (tt & 63)) & 1ULL) continue;
                    ++degree;
                    lookahead += tileWeight[tt];
                }

                if (degree == 0) continue;

                int rank = ns * 64
                         + lookahead * cfg.lookahead
                         + degree * cfg.mobility;
                if (cfg.noiseMask) rank += static_cast<int>(rng.next() & cfg.noiseMask);

                candidates.push_back({rank, ns, np, nt, i, dchar[d]});
            }
        }

        if (stopped) return;
        if (candidates.empty()) break;

        int keep = min(width, static_cast<int>(candidates.size()));
        if (keep < static_cast<int>(candidates.size())) {
            nth_element(candidates.begin(), candidates.begin() + keep, candidates.end(),
                        [](const Candidate &a, const Candidate &b) {
                            return a.rank > b.rank;
                        });
            candidates.resize(keep);
        }

        next.clear();
        for (const Candidate &cand : candidates) {
            int newNode = static_cast<int>(nodes.size());
            nodes.push_back({current[cand.parent].node, cand.dir});

            State state = current[cand.parent];
            state.used[cand.tile >> 6] |= 1ULL << (cand.tile & 63);
            state.pos = cand.pos;
            state.score = cand.score;
            state.node = newNode;
            next.push_back(state);
        }

        current.swap(next);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> startI >> startJ;
    startPos = startI * W + startJ;

    int maxTile = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            cin >> tileAt[i][j];
            maxTile = max(maxTile, tileAt[i][j]);
        }
    }

    fill(tileWeight, tileWeight + maxTile + 1, 0);
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int p;
            cin >> p;
            tileWeight[tileAt[i][j]] += p;
        }
    }

    rng.x ^= static_cast<uint64_t>(startPos + 1) * 0xbf58476d1ce4e5b9ULL;
    bestScore = tileWeight[tileAt[startI][startJ]];
    bestPath.clear();

    deadline = Clock::now() + chrono::milliseconds(1850);

    beamSearch("", 1800, {8, 80, 0});

    int iteration = 0;
    while (Clock::now() < deadline) {
        string base = bestPath;
        int len = static_cast<int>(base.size());
        int cut = 0;

        auto remaining = duration_cast<chrono::milliseconds>(
            deadline - Clock::now()).count();

        if (len > 1) {
            int lo, hi;
            if (remaining < 180) {
                lo = len * 4 / 5;
                hi = len * 19 / 20;
            } else {
                lo = len / 4;
                hi = len * 3 / 4;
            }
            hi = min(hi, len - 1);
            lo = min(lo, hi);
            cut = lo + rng.nextInt(hi - lo + 1);
        }

        if (iteration % 7 == 6 && remaining > 650) cut = 0;
        string prefix = base.substr(0, cut);

        RankConfig cfg;
        cfg.lookahead = rng.nextInt(13);
        cfg.mobility = rng.nextInt(201) - 50;
        cfg.noiseMask = (1U << (5 + rng.nextInt(8))) - 1;

        int width = (cut == 0 ? 1000 : 650);
        if (remaining < 180) width = 400;
        beamSearch(prefix, width, cfg);
        ++iteration;
    }

    cout << bestPath << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using namespace chrono;

struct Edge { int to; char dir; };
struct Node { int parent; char move; };
struct State {
    int pos, score, node;
    uint64_t used[40];
};
struct Candidate {
    int pos, score, parent, move, avail, rank;
    uint64_t used[40];
};

int tileId[2500], val[2500];
vector<Edge> neigh[2500];
int B;
int startPos;

struct BeamResult {
    int score;
    string path;
};

BeamResult runBeam(int W, int alpha, int seed, double timeLimitSec) {
    auto startTime = steady_clock::now();
    vector<State> cur, next;
    cur.reserve(W);
    next.reserve(W);
    vector<Candidate> candidates;
    candidates.reserve(W * 4);
    vector<Node> nodes;
    nodes.reserve(W * 1500);
    nodes.push_back({-1, 0});
    State root;
    root.pos = startPos;
    root.score = val[startPos];
    root.node = 0;
    memset(root.used, 0, sizeof(root.used));
    int stTile = tileId[startPos];
    root.used[stTile >> 6] |= 1ULL << (stTile & 63);
    cur.push_back(root);
    int bestScore = val[startPos];
    int bestParent = -1;
    char bestMove = 0;
    bool bestHasExtra = false;
    uint32_t rng = seed;
    while (!cur.empty()) {
        auto now = steady_clock::now();
        double elapsed = duration<double>(now - startTime).count();
        if (elapsed > timeLimitSec) break;
        candidates.clear();
        for (auto &st : cur) {
            for (auto &e : neigh[st.pos]) {
                int nt = tileId[e.to];
                if (!((st.used[nt >> 6] >> (nt & 63)) & 1ULL)) {
                    candidates.emplace_back();
                    Candidate &cand = candidates.back();
                    cand.pos = e.to;
                    cand.score = st.score + val[e.to];
                    cand.parent = st.node;
                    cand.move = e.dir;
                    memcpy(cand.used, st.used, B * sizeof(uint64_t));
                    cand.used[nt >> 6] |= 1ULL << (nt & 63);
                    int avail = 0;
                    for (auto &e2 : neigh[e.to]) {
                        int nt2 = tileId[e2.to];
                        if (!((cand.used[nt2 >> 6] >> (nt2 & 63)) & 1ULL)) avail++;
                    }
                    cand.avail = avail;
                    rng ^= rng << 13; rng ^= rng >> 17; rng ^= rng << 5;
                    cand.rank = cand.score * 1000 + alpha * avail + (rng & 127);
                    if (cand.score > bestScore) {
                        bestScore = cand.score;
                        bestParent = st.node;
                        bestMove = e.dir;
                        bestHasExtra = true;
                    }
                }
            }
        }
        if (candidates.empty()) break;
        vector<int> idx;
        idx.reserve(candidates.size());
        for (int i = 0; i < (int)candidates.size(); ++i) {
            if (candidates[i].avail > 0) idx.push_back(i);
        }
        if (idx.empty()) break;
        int take = min((int)idx.size(), W);
        if (take < (int)idx.size()) {
            nth_element(idx.begin(), idx.begin() + take, idx.end(), [&](int a, int b) {
                return candidates[a].rank > candidates[b].rank;
            });
            idx.resize(take);
        }
        next.clear();
        next.reserve(take);
        for (int id : idx) {
            Candidate &cand = candidates[id];
            int nodeId = (int)nodes.size();
            nodes.push_back({cand.parent, cand.move});
            next.emplace_back();
            State &st = next.back();
            st.pos = cand.pos;
            st.score = cand.score;
            st.node = nodeId;
            memcpy(st.used, cand.used, B * sizeof(uint64_t));
        }
        cur.swap(next);
    }
    string ans;
    int node = bestParent;
    while (node != -1) {
        ans.push_back(nodes[node].move);
        node = nodes[node].parent;
    }
    reverse(ans.begin(), ans.end());
    if (bestHasExtra) ans.push_back(bestMove);
    return {bestScore, ans};
}

