            if (r > 0) neigh[idx].push_back({idx - 50, 'U'});
            if (r < 49) neigh[idx].push_back({idx + 50, 'D'});
            if (c > 0) neigh[idx].push_back({idx - 1, 'L'});
            if (c < 49) neigh[idx].push_back({idx + 1, 'R'});
        }
    }
    auto overallStart = steady_clock::now();
    const double totalLimit = 1.8;
    int globalBestScore = -1;
    string globalBestPath = "";
    int runIndex = 0;
    while (true) {
        double elapsed = duration<double>(steady_clock::now() - overallStart).count();
        double remaining = totalLimit - elapsed;
        if (remaining < 0.02) break;
        int W;
