        }
        int seed = 12345 + runIndex * 98765;
        double perRunLimit = min(remaining, 0.8);
        BeamResult res = runBeam(W, alpha, seed, perRunLimit);
        if (res.score > globalBestScore) {
            globalBestScore = res.score;
            globalBestPath = res.path;
        }
        ++runIndex;
    }
    cout << globalBestPath << '\n';
