}

#include <bits/stdc++.h>
using namespace std;

static constexpr int SIDE = 50;
static constexpr int CELLS = SIDE * SIDE;

int tileId[CELLS];
int cellValue[CELLS];
bool tileUsed[CELLS];
vector<int> neighbors[CELLS];

uint64_t rngState = 88172645463325252ULL;

uint32_t random32() {
    rngState ^= rngState >> 7;
    rngState ^= rngState << 9;
    return static_cast<uint32_t>(rngState);
}

int randomInt(int n) {
    return static_cast<int>(random32() % static_cast<uint32_t>(n));
}

double randomDouble() {
    return (static_cast<double>(random32()) + 0.5) / 4294967296.0;
}

using Clock = chrono::steady_clock;
Clock::time_point startTime;

double elapsedSeconds() {
    return chrono::duration<double>(Clock::now() - startTime).count();
}

bool adjacentCells(int a, int b) {
    int ar = a / SIDE, ac = a % SIDE;
    int br = b / SIDE, bc = b % SIDE;
    return abs(ar - br) + abs(ac - bc) == 1;
}

// ---------------------------------------------------------------------------
// Initial path construction: randomized Warnsdorff DFS with backtracking.
// ---------------------------------------------------------------------------

vector<int> dfsPath;
vector<int> initialBestPath;
int dfsPathScore = 0;
int initialBestScore = -1;
int dfsNodeCount = 0;
int dfsNodeLimit = 0;

void considerCurrentDFSPath() {
    if (dfsPathScore > initialBestScore ||
        (dfsPathScore == initialBestScore &&
         static_cast<int>(dfsPath.size()) > static_cast<int>(initialBestPath.size()))) {
        initialBestScore = dfsPathScore;
        initialBestPath = dfsPath;
    }
}

void constructDFS(int current) {
    if (dfsNodeCount >= dfsNodeLimit ||
        ((dfsNodeCount & 2047) == 0 && elapsedSeconds() > 0.245)) {
        considerCurrentDFSPath();
        return;
    }

    ++dfsNodeCount;
    int t = tileId[current];
    tileUsed[t] = true;
    dfsPath.push_back(current);
    dfsPathScore += cellValue[current];

    struct Candidate {
        int cell;
        int exits;
        int noise;
    };
    Candidate candidates[4];
    int candidateCount = 0;

    for (int next : neighbors[current]) {
        if (tileUsed[tileId[next]]) continue;

        int exits = 0;
        for (int exit : neighbors[next]) {
            if (!tileUsed[tileId[exit]] && tileId[exit] != tileId[next]) {
                ++exits;
            }
        }

        candidates[candidateCount++] = {
            next, exits, static_cast<int>(random32() & 15ULL)
        };
    }

    for (int i = 1; i < candidateCount; ++i) {
        Candidate x = candidates[i];
        int j = i - 1;
        while (j >= 0) {
            bool xBefore = x.exits < candidates[j].exits ||
                           (x.exits == candidates[j].exits &&
                            x.noise < candidates[j].noise);
            bool sameNoise = x.exits == candidates[j].exits &&
                             x.noise == candidates[j].noise;
            if (!xBefore && !(sameNoise &&
                              cellValue[x.cell] > cellValue[candidates[j].cell])) {
                break;
            }
            candidates[j + 1] = candidates[j];
            --j;
        }
        candidates[j + 1] = x;
    }

    if (candidateCount == 0) {
        considerCurrentDFSPath();
    } else {
        for (int i = 0; i < candidateCount; ++i) {
            if (dfsNodeCount >= dfsNodeLimit || elapsedSeconds() > 0.245) break;
            constructDFS(candidates[i].cell);
        }
    }

    dfsPathScore -= cellValue[current];
    dfsPath.pop_back();
    tileUsed[t] = false;
}

// ---------------------------------------------------------------------------
// Implicit treap storing the ordered path.
// ---------------------------------------------------------------------------

struct Treap {
    struct Node {
        int left = 0;
        int right = 0;
        int parent = 0;
        int size = 0;
        int sum = 0;
        int cell = -1;
        uint32_t priority = 0;
        bool reversed = false;
    };

    vector<Node> nodes;
    vector<int> freeNodes;
    int cellNode[CELLS];
    int root = 0;

    Treap() {
        nodes.reserve(CELLS + 16);
        reset();
    }

    void reset() {
        nodes.clear();
        nodes.emplace_back();
        freeNodes.clear();
        fill(cellNode, cellNode + CELLS, 0);
        root = 0;
    }

    int nodeSize(int t) const {
        return t ? nodes[t].size : 0;
    }

    int nodeSum(int t) const {
        return t ? nodes[t].sum : 0;
    }

    void pull(int t) {
        int l = nodes[t].left;
        int r = nodes[t].right;
        nodes[t].size = 1 + nodeSize(l) + nodeSize(r);
        nodes[t].sum = cellValue[nodes[t].cell] + nodeSum(l) + nodeSum(r);
        if (l) nodes[l].parent = t;
        if (r) nodes[r].parent = t;
    }

    void applyReverse(int t) {
        if (!t) return;
        swap(nodes[t].left, nodes[t].right);
        nodes[t].reversed = !nodes[t].reversed;
    }

    void push(int t) {
        if (!t || !nodes[t].reversed) return;
        applyReverse(nodes[t].left);
        applyReverse(nodes[t].right);
        nodes[t].reversed = false;
    }

    int newNode(int cell) {
        int id;
        if (freeNodes.empty()) {
            id = static_cast<int>(nodes.size());
            nodes.emplace_back();
        } else {
            id = freeNodes.back();
            freeNodes.pop_back();
            nodes[id] = Node();
        }

        nodes[id].cell = cell;
        nodes[id].size = 1;
        nodes[id].sum = cellValue[cell];
        nodes[id].priority = random32();
        cellNode[cell] = id;
        return id;
    }

    pair<int, int> split(int t, int count) {
        if (!t) return {0, 0};
        push(t);

        int leftSize = nodeSize(nodes[t].left);
        if (count <= leftSize) {
            auto [a, b] = split(nodes[t].left, count);
            nodes[t].left = b;
            pull(t);
            nodes[t].parent = 0;
            if (a) nodes[a].parent = 0;
            return {a, t};
        } else {
            auto [a, b] = split(nodes[t].right, count - leftSize - 1);
            nodes[t].right = a;
            pull(t);
            nodes[t].parent = 0;
            if (b) nodes[b].parent = 0;
            return {t, b};
        }
    }

    int merge(int a, int b) {
        if (!a) {
            if (b) nodes[b].parent = 0;
            return b;
        }
        if (!b) {
            nodes[a].parent = 0;
            return a;
        }

        if (nodes[a].priority < nodes[b].priority) {
            push(a);
            nodes[a].right = merge(nodes[a].right, b);
            pull(a);
            nodes[a].parent = 0;
            return a;
        } else {
            push(b);
            nodes[b].left = merge(a, nodes[b].left);
            pull(b);
            nodes[b].parent = 0;
            return b;
        }
    }

    int size() const {
        return nodeSize(root);
    }

    int nodeAt(int rank) {
        int t = root;
        while (t) {
            push(t);
            int leftSize = nodeSize(nodes[t].left);
            if (rank < leftSize) {
                t = nodes[t].left;
            } else if (rank == leftSize) {
                return t;
            } else {
                rank -= leftSize + 1;
                t = nodes[t].right;
            }
        }
        return 0;
    }

    int getRank(int node) {
        int chain[256];
        int chainLength = 0;
        for (int t = node; t; t = nodes[t].parent) {
            chain[chainLength++] = t;
        }
        for (int i = chainLength - 1; i >= 0; --i) push(chain[i]);

        int rank = nodeSize(nodes[node].left);
        int t = node;
        while (nodes[t].parent) {
            int p = nodes[t].parent;
            if (nodes[p].right == t) {
                rank += nodeSize(nodes[p].left) + 1;
            }
            t = p;
        }
        return rank;
    }

    int prefixSum(int count) {
        int result = 0;
        int t = root;
        while (t && count > 0) {
            push(t);
            int leftSize = nodeSize(nodes[t].left);
            if (count <= leftSize) {
                t = nodes[t].left;
            } else {
                result += nodeSum(nodes[t].left) + cellValue[nodes[t].cell];
                count -= leftSize + 1;
                t = nodes[t].right;
            }
        }
        return result;
    }

    int rangeSum(int left, int right) {
        if (left > right) return 0;
        return prefixSum(right + 1) - prefixSum(left);
    }

    void collect(int t, vector<int>& result) {
        if (!t) return;
        push(t);
        collect(nodes[t].left, result);
        result.push_back(nodes[t].cell);
        collect(nodes[t].right, result);
    }

    void collect(vector<int>& result) {
        result.clear();
        collect(root, result);
    }

    void releaseTree(int t) {
        if (!t) return;
        push(t);
        int l = nodes[t].left;
        int r = nodes[t].right;
        releaseTree(l);
        releaseTree(r);
        int cell = nodes[t].cell;
        tileUsed[tileId[cell]] = false;
        cellNode[cell] = 0;
        freeNodes.push_back(t);
    }
} treap;

// ---------------------------------------------------------------------------
// Local-search operations.
// ---------------------------------------------------------------------------

int currentScore = 0;
int bestScore = -1;
vector<int> bestPath;
vector<int> temporaryPath;

uint32_t seenTile[CELLS];
uint32_t seenStamp = 1;

void rememberBest() {
    int currentLength = treap.size();
    if (currentScore > bestScore ||
        (currentScore == bestScore &&
         currentLength > static_cast<int>(bestPath.size()))) {
        treap.collect(temporaryPath);
        bestPath = temporaryPath;
        bestScore = currentScore;
    }
}

void buildTreapFrom(const vector<int>& path) {
    treap.reset();
    fill(tileUsed, tileUsed + CELLS, false);
    currentScore = 0;

    for (int cell : path) {
        tileUsed[tileId[cell]] = true;
        currentScore += cellValue[cell];
        int node = treap.newNode(cell);
        treap.root = treap.merge(treap.root, node);
    }
}

struct Detour {
    int cells[20];
    int count = 0;
    int gain = 0;
    bool valid = false;
};

bool validateDetour(Detour& d) {
    ++seenStamp;
    if (seenStamp == 0) {
        fill(seenTile, seenTile + CELLS, 0);
        seenStamp = 1;
    }

    d.valid = true;
    d.gain = 0;
    for (int i = 0; i < d.count; ++i) {
        int cell = d.cells[i];
        int t = tileId[cell];
        if (tileUsed[t] || seenTile[t] == seenStamp) {
            d.valid = false;
            return false;
        }
        seenTile[t] = seenStamp;
        d.gain += cellValue[cell];
    }
    return true;
}

bool buildDetour(int u, int v, int side, int height, Detour& d) {
    d.count = 0;
    int ur = u / SIDE, uc = u % SIDE;
    int vr = v / SIDE, vc = v % SIDE;

    if (ur == vr) {
        if (side > 0 && ur + height >= SIDE) return false;
        if (side < 0 && ur - height < 0) return false;

        for (int k = 1; k <= height; ++k) {
            d.cells[d.count++] = (ur + side * k) * SIDE + uc;
        }
        d.cells[d.count++] = (ur + side * height) * SIDE + vc;
        for (int k = height - 1; k >= 1; --k) {
            d.cells[d.count++] = (ur + side * k) * SIDE + vc;
        }
    } else {
        if (side > 0 && uc + height >= SIDE) return false;
        if (side < 0 && uc - height < 0) return false;

        for (int k = 1; k <= height; ++k) {
            d.cells[d.count++] = ur * SIDE + uc + side * k;
        }
        d.cells[d.count++] = vr * SIDE + uc + side * height;
        for (int k = height - 1; k >= 1; --k) {
            d.cells[d.count++] = vr * SIDE + uc + side * k;
        }
    }
    return true;
}

void insertCells(int position, const int* cells, int count, int gain) {
    for (int i = 0; i < count; ++i) {
        tileUsed[tileId[cells[i]]] = true;
    }

    auto [a, b] = treap.split(treap.root, position);
    int middle = 0;
    for (int i = 0; i < count; ++i) {
        int node = treap.newNode(cells[i]);
        middle = treap.merge(middle, node);
    }
    treap.root = treap.merge(treap.merge(a, middle), b);
    currentScore += gain;
}

bool insertRectangleDetour() {
    int n = treap.size();
    if (n < 2) return false;

    int edgeRank = randomInt(n - 1);
    int u = treap.nodes[treap.nodeAt(edgeRank)].cell;
    int v = treap.nodes[treap.nodeAt(edgeRank + 1)].cell;

    int ur = u / SIDE, uc = u % SIDE;
    bool horizontal = (ur == v / SIDE);

    int maxPlus, maxMinus;
    if (horizontal) {
        maxPlus = SIDE - 1 - ur;
        maxMinus = ur;
    } else {
        maxPlus = SIDE - 1 - uc;
        maxMinus = uc;
    }

    int feasible[2];
    int feasibleCount = 0;
    if (maxPlus > 0) feasible[feasibleCount++] = 1;
    if (maxMinus > 0) feasible[feasibleCount++] = -1;
    if (feasibleCount == 0) return false;

    int chosenSide = feasible[randomInt(feasibleCount)];
    int maximumHeight = chosenSide > 0 ? maxPlus : maxMinus;
    int height = 1;
    if (maximumHeight > 1 && randomInt(8) == 0) {
        int choices = min(7, maximumHeight - 1);
        height = 2 + randomInt(choices);
    }

    Detour candidates[2];
    int candidateCount = 0;

    for (int offset = 0; offset < feasibleCount; ++offset) {
        int side = feasible[(offset + randomInt(feasibleCount)) % feasibleCount];
        int limit = side > 0 ? maxPlus : maxMinus;
        if (limit < height) continue;

        Detour d;
        if (!buildDetour(u, v, side, height, d)) continue;
        validateDetour(d);
        if (d.valid) candidates[candidateCount++] = d;
    }

    if (candidateCount == 0) return false;

    int selected = 0;
    if (candidateCount == 2) {
        if (candidates[0].gain != candidates[1].gain && randomInt(100) < 60) {
            selected = candidates[0].gain > candidates[1].gain ? 0 : 1;
        } else {
            selected = randomInt(2);
        }
    }

    const Detour& chosen = candidates[selected];
    insertCells(edgeRank + 1, chosen.cells, chosen.count, chosen.gain);
    return true;
}

bool insertAtEndpoint() {
    int n = treap.size();
    if (n == 0) return false;

    int endpoint = treap.nodes[treap.nodeAt(n - 1)].cell;
    int candidates[4];
    int candidateCount = 0;

    for (int next : neighbors[endpoint]) {
        if (!tileUsed[tileId[next]]) candidates[candidateCount++] = next;
    }
    if (candidateCount == 0) return false;

    int selected = 0;
    if (candidateCount > 1) {
        if (randomInt(100) < 60) {
            int best = 0;
            for (int i = 1; i < candidateCount; ++i) {
                if (cellValue[candidates[i]] > cellValue[candidates[best]]) best = i;
            }
            selected = best;
        } else {
            selected = randomInt(candidateCount);
        }
    }

    int cell = candidates[selected];
    tileUsed[tileId[cell]] = true;
    currentScore += cellValue[cell];
    int node = treap.newNode(cell);
    treap.root = treap.merge(treap.root, node);
    return true;
}

void deleteRange(int left, int right) {
    if (left > right) return;

    auto [a, rest] = treap.split(treap.root, left);
    auto [middle, c] = treap.split(rest, right - left + 1);

    currentScore -= treap.nodeSum(middle);
    treap.root = treap.merge(a, c);
    treap.releaseTree(middle);
}

struct RangeProposal {
    int left;
    int right;
    int loss;
    int length;
};

bool proposeChordDeletion(RangeProposal& proposal) {
    int n = treap.size();
    if (n < 4) return false;

    int firstRank = randomInt(n);
    int firstCell = treap.nodes[treap.nodeAt(firstRank)].cell;
    int maximumLength = (randomInt(20) == 0 ? n : 32);

    RangeProposal proposals[4];
    int proposalCount = 0;

    for (int secondCell : neighbors[firstCell]) {
        int secondNode = treap.cellNode[secondCell];
        if (!secondNode) continue;

        int secondRank = treap.getRank(secondNode);
        if (abs(secondRank - firstRank) <= 1) continue;

        int left = min(firstRank, secondRank) + 1;
        int right = max(firstRank, secondRank) - 1;
        int length = right - left + 1;
        if (length <= 0 || (length & 1) || length > maximumLength) continue;

        proposals[proposalCount++] = {
            left, right, treap.rangeSum(left, right), length
        };
    }

    if (proposalCount == 0) return false;

    int selected;
    if (randomInt(4) == 0) {
        selected = randomInt(proposalCount);
    } else {
        int shortest = INT_MAX;
        for (int i = 0; i < proposalCount; ++i) {
            shortest = min(shortest, proposals[i].length);
        }
        int choices[4];
        int choiceCount = 0;
        for (int i = 0; i < proposalCount; ++i) {
            if (proposals[i].length == shortest) choices[choiceCount++] = i;
        }
        selected = choices[randomInt(choiceCount)];
    }

    proposal = proposals[selected];
    return true;
}

bool proposeEndpointDeletion(RangeProposal& proposal) {
    int n = treap.size();
    if (n <= 2) return false;

    int rank = n - 1;
    int cell = treap.nodes[treap.nodeAt(rank)].cell;
    proposal = {rank, rank, cellValue[cell], 1};
    return true;
}

bool acceptLoss(int loss, double temperature, bool force) {
    if (force || loss == 0) return true;
    return randomDouble() < exp(-static_cast<double>(loss) / temperature);
}

void applyTwoOpt(int firstRank, int secondRank) {
    if (firstRank < secondRank) {
        auto [a, rest] = treap.split(treap.root, firstRank + 1);
        auto [middle, c] = treap.split(rest, secondRank - firstRank);
        treap.applyReverse(middle);
        treap.root = treap.merge(treap.merge(a, middle), c);
    } else {
        auto [a, rest] = treap.split(treap.root, secondRank + 1);
        auto [middle, c] = treap.split(rest, firstRank - secondRank);
        treap.applyReverse(middle);
        treap.root = treap.merge(treap.merge(a, middle), c);
    }
}

bool tryTwoOpt() {
    int n = treap.size();
    if (n < 4) return false;

    int rank = randomInt(n - 1);
    int u = treap.nodes[treap.nodeAt(rank)].cell;
    int v = treap.nodes[treap.nodeAt(rank + 1)].cell;

    int ur = u / SIDE, uc = u % SIDE;
    int vr = v / SIDE, vc = v % SIDE;

    for (int side : {-1, 1}) {
        int oppositeU, oppositeV;

        if (ur == vr) {
            oppositeU = (ur + side) * SIDE + uc;
            oppositeV = (ur + side) * SIDE + vc;
        } else {
            oppositeU = ur * SIDE + uc + side;
            oppositeV = vr * SIDE + uc + side;
        }

        if (oppositeU < 0 || oppositeU >= CELLS ||
            oppositeV < 0 || oppositeV >= CELLS) {
            continue;
        }

        int nodeU = treap.cellNode[oppositeU];
        int nodeV = treap.cellNode[oppositeV];
        if (!nodeU || !nodeV) continue;

        int rankU = treap.getRank(nodeU);
        int rankV = treap.getRank(nodeV);
        if (rankV != rankU + 1) continue;

        applyTwoOpt(rank, rankU);
        return true;
    }
    return false;
}

bool tryRotation() {
    int n = treap.size();
    if (n < 3) return false;

    int endpoint = treap.nodes[treap.nodeAt(n - 1)].cell;
    int candidates[4];
    int candidateCount = 0;

    for (int cell : neighbors[endpoint]) {
        int node = treap.cellNode[cell];
        if (!node) continue;

        int rank = treap.getRank(node);
        if (rank >= n - 2) continue;
        candidates[candidateCount++] = rank;
    }

    if (candidateCount == 0) return false;
    int rank = candidates[randomInt(candidateCount)];

    auto [a, suffix] = treap.split(treap.root, rank + 1);
    treap.applyReverse(suffix);
    treap.root = treap.merge(a, suffix);
    return true;
}

