#include <bits/stdc++.h>
using namespace std;

using Board = array<unsigned char, 100>;

constexpr int N = 10;
constexpr int CELLS = 100;
constexpr int TRIALS = 12;
constexpr int HORIZON = 12;

int flavor[CELLS];
mt19937_64 rng(0xC0FFEE15AHC015ULL);

enum Direction { LEFT, RIGHT, FORWARD, BACKWARD };
const char directionChar[4] = {'L', 'R', 'F', 'B'};

Board tiltBoard(const Board& input, int direction) {
    Board board = input;

    if (direction == LEFT) {
        for (int r = 0; r < N; ++r) {
            int write = 0;
            for (int c = 0; c < N; ++c) {
                int pos = r * N + c;
                if (board[pos] != 0) {
                    int dest = r * N + write;
                    if (dest != pos) {
                        board[dest] = board[pos];
                        board[pos] = 0;
                    }
                    ++write;
                }
            }
        }
    } else if (direction == RIGHT) {
        for (int r = 0; r < N; ++r) {
            int write = N - 1;
            for (int c = N - 1; c >= 0; --c) {
                int pos = r * N + c;
                if (board[pos] != 0) {
                    int dest = r * N + write;
                    if (dest != pos) {
                        board[dest] = board[pos];
                        board[pos] = 0;
                    }
                    --write;
                }
            }
        }
    } else if (direction == FORWARD) {
        for (int c = 0; c < N; ++c) {
            int write = 0;
            for (int r = 0; r < N; ++r) {
                int pos = r * N + c;
                if (board[pos] != 0) {
                    int dest = write * N + c;
                    if (dest != pos) {
                        board[dest] = board[pos];
                        board[pos] = 0;
                    }
                    ++write;
                }
            }
        }
    } else {
        for (int c = 0; c < N; ++c) {
            int write = N - 1;
            for (int r = N - 1; r >= 0; --r) {
                int pos = r * N + c;
                if (board[pos] != 0) {
                    int dest = write * N + c;
                    if (dest != pos) {
                        board[dest] = board[pos];
                        board[pos] = 0;
                    }
                    --write;
                }
            }
        }
    }

    return board;
}

struct Evaluation {
    int componentScore = 0;
    int sameEdges = 0;
    int allEdges = 0;
    int projection = 0;
};

int componentScore(const Board& board) {
    bool visited[CELLS] = {};
    int stack[CELLS];
    int result = 0;

    constexpr int dr[4] = {-1, 1, 0, 0};
    constexpr int dc[4] = {0, 0, -1, 1};

    for (int start = 0; start < CELLS; ++start) {
        if (board[start] == 0 || visited[start]) continue;

        int top = 0;
        int size = 0;
        stack[top++] = start;
        visited[start] = true;
        unsigned char color = board[start];

        while (top > 0) {
            int pos = stack[--top];
            ++size;

            int r = pos / N;
            int c = pos % N;

            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr < 0 || nr >= N || nc < 0 || nc >= N) continue;

                int next = nr * N + nc;
                if (board[next] == color && !visited[next]) {
                    visited[next] = true;
                    stack[top++] = next;
                }
            }
        }

        result += size * size;
    }

    return result;
}

Evaluation evaluateBoard(const Board& board) {
    Evaluation result;
    bool visited[CELLS] = {};
    int stack[CELLS];

    int rowCount[3][N] = {};
    int columnCount[3][N] = {};

    for (int pos = 0; pos < CELLS; ++pos) {
        if (board[pos] == 0) continue;
        int color = board[pos] - 1;
        ++rowCount[color][pos / N];
        ++columnCount[color][pos % N];
    }

    for (int color = 0; color < 3; ++color) {
        for (int i = 0; i < N; ++i) {
            result.projection += rowCount[color][i] * rowCount[color][i];
            result.projection += columnCount[color][i] * columnCount[color][i];
        }
    }

    constexpr int dr[4] = {-1, 1, 0, 0};
    constexpr int dc[4] = {0, 0, -1, 1};

    for (int start = 0; start < CELLS; ++start) {
        if (board[start] == 0 || visited[start]) continue;

        int top = 0;
        int size = 0;
        stack[top++] = start;
        visited[start] = true;
        unsigned char color = board[start];

        while (top > 0) {
            int pos = stack[--top];
            ++size;

            int r = pos / N;
            int c = pos % N;

            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr < 0 || nr >= N || nc < 0 || nc >= N) continue;

                int next = nr * N + nc;
                if (board[next] != 0) {
                    ++result.allEdges;
                    if (board[next] == color) ++result.sameEdges;
                }

                if (board[next] == color && !visited[next]) {
                    visited[next] = true;
                    stack[top++] = next;
                }
            }
        }

        result.componentScore += size * size;
    }

    result.sameEdges /= 2;
    result.allEdges /= 2;
    return result;
}

bool betterEvaluation(const Evaluation& a, const Evaluation& b) {
    if (a.componentScore != b.componentScore)
        return a.componentScore > b.componentScore;
    if (a.sameEdges != b.sameEdges)
        return a.sameEdges > b.sameEdges;
    if (a.projection != b.projection)
        return a.projection > b.projection;
    return a.allEdges > b.allEdges;
}

int greedyTilt(const Board& board) {
    int bestDirection = LEFT;
    Evaluation best;
    bool first = true;

    for (int d = 0; d < 4; ++d) {
        Board next = tiltBoard(board, d);
        Evaluation current = evaluateBoard(next);
        if (first || betterEvaluation(current, best)) {
            first = false;
            best = current;
            bestDirection = d;
        }
    }

    return bestDirection;
}

double recursiveValue(const Board& board, int nextIndex, int depth) {
    if (depth == 0 || nextIndex >= CELLS)
        return componentScore(board);

    int emptyCount = 0;
    for (unsigned char cell : board) {
        if (cell == 0) ++emptyCount;
    }
    if (emptyCount == 0) return componentScore(board);

    double total = 0.0;

    for (int pos = 0; pos < CELLS; ++pos) {
        if (board[pos] != 0) continue;

        Board next = board;
        next[pos] = static_cast<unsigned char>(flavor[nextIndex]);

        if (nextIndex == CELLS - 1) {
            total += componentScore(next);
        } else {
            double best = -1.0;
            for (int d = 0; d < 4; ++d) {
                Board tilted = tiltBoard(next, d);
                best = max(best, recursiveValue(tilted, nextIndex + 1, depth - 1));
            }
            total += best;
        }
    }

    return total / emptyCount;
}

int rolloutValue(const Board& initial, int nextIndex, const array<int, HORIZON>& ranks) {
    Board board = initial;

    for (int step = 0; step < HORIZON; ++step) {
        int index = nextIndex + step;
        int rank = ranks[step];
        int currentRank = 0;
        int destination = -1;

        for (int pos = 0; pos < CELLS; ++pos) {
            if (board[pos] != 0) continue;
            if (currentRank++ == rank) {
                destination = pos;
                break;
            }
        }

        if (destination < 0) break;
        board[destination] = static_cast<unsigned char>(flavor[index]);

        if (index == CELLS - 1) break;

        int d = greedyTilt(board);
        board = tiltBoard(board, d);
    }

    return componentScore(board);
}

double meanOf(const array<double, 4>& values) {
    return (values[0] + values[1] + values[2] + values[3]) / 4.0;
}

double meanAbsoluteDeviation(const array<double, 4>& values, double mean) {
    double result = 0.0;
    for (double value : values) result += abs(value - mean);
    return result / 4.0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    for (int i = 0; i < CELLS; ++i) cin >> flavor[i];

    Board board{};

    for (int turn = 0; turn < CELLS; ++turn) {
        int p;
        cin >> p;

        int rank = 0;
        int destination = -1;
        for (int pos = 0; pos < CELLS; ++pos) {
            if (board[pos] != 0) continue;
            if (++rank == p) {
                destination = pos;
                break;
            }
        }

        if (destination < 0) return 0;
        board[destination] = static_cast<unsigned char>(flavor[turn]);

        if (turn == CELLS - 1) break;

        array<Board, 4> candidates;
        array<Evaluation, 4> immediate;
        array<double, 4> recursive;

        int remaining = 0;
        for (unsigned char cell : board) {
            if (cell == 0) ++remaining;
        }

        for (int d = 0; d < 4; ++d) {
            candidates[d] = tiltBoard(board, d);
            immediate[d] = evaluateBoard(candidates[d]);
        }

        int depth;
        if (remaining <= 5) {
            depth = remaining;
        } else if (remaining <= 7) {
            depth = 3;
        } else if (remaining <= 15) {
            depth = 2;
        } else {
            depth = 1;
        }

        for (int d = 0; d < 4; ++d) {
            recursive[d] = recursiveValue(candidates[d], turn + 1, depth);
        }

        int bestDirection = LEFT;

        if (remaining <= 5) {
            for (int d = 1; d < 4; ++d) {
                if (recursive[d] > recursive[bestDirection] ||
                    (recursive[d] == recursive[bestDirection] &&
                     betterEvaluation(immediate[d], immediate[bestDirection]))) {
                    bestDirection = d;
                }
            }
        } else {
            int horizon = min(HORIZON, remaining);
            array<double, 4> rollout{};
            array<int, HORIZON> ranks{};

            for (int trial = 0; trial < TRIALS; ++trial) {
                for (int step = 0; step < horizon; ++step) {
                    int count = remaining - step;
                    ranks[step] = static_cast<int>(rng() % count);
                }

                for (int d = 0; d < 4; ++d) {
                    rollout[d] += rolloutValue(candidates[d], turn + 1, ranks);
                }
            }

            for (int d = 0; d < 4; ++d) rollout[d] /= TRIALS;

            double rolloutMean = meanOf(rollout);
            double recursiveMean = meanOf(recursive);
            array<double, 4> immediateValue{};
            for (int d = 0; d < 4; ++d)
                immediateValue[d] = immediate[d].componentScore;
            double immediateMean = meanOf(immediateValue);

            double rolloutMad = meanAbsoluteDeviation(rollout, rolloutMean);
            double recursiveMad = meanAbsoluteDeviation(recursive, recursiveMean);
            double immediateMad = meanAbsoluteDeviation(immediateValue, immediateMean);

            double recursiveWeight = remaining <= 15 ? 1.5 : 1.0;
            array<double, 4> combined{};

            for (int d = 0; d < 4; ++d) {
                if (rolloutMad > 1e-12)
                    combined[d] += (rollout[d] - rolloutMean) / rolloutMad;
                if (recursiveMad > 1e-12)
                    combined[d] += recursiveWeight * (recursive[d] - recursiveMean) / recursiveMad;
                if (immediateMad > 1e-12)
                    combined[d] += 0.25 * (immediateValue[d] - immediateMean) / immediateMad;
            }

            for (int d = 1; d < 4; ++d) {
                if (combined[d] > combined[bestDirection] + 1e-9 ||
                    (abs(combined[d] - combined[bestDirection]) <= 1e-9 &&
                     (recursive[d] > recursive[bestDirection] ||
                      (recursive[d] == recursive[bestDirection] &&
                       betterEvaluation(immediate[d], immediate[bestDirection]))))) {
                    bestDirection = d;
                }
            }
        }

        cout << directionChar[bestDirection] << '\n' << flush;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 60);

struct Plan {
    vector<string> ops;
    ll cost = INF;
    bool valid = false;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    const int M = N * N;
    vector<int> h(M);
    bool any = false;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> h[i * N + j];
            if (h[i * N + j] != 0) any = true;
        }
    }
    if (!any) return 0;

    auto startTime = chrono::steady_clock::now();

    vector<vector<int>> dist(M, vector<int>(M));
    for (int a = 0; a < M; ++a) {
        for (int b = 0; b < M; ++b) {
            dist[a][b] = abs(a / N - b / N) + abs(a % N - b % N);
        }
    }

    auto adjacent = [&](int a, int b) {
        return dist[a][b] == 1;
    };

    struct Eval {
        ll cost = INF;
        int start = 0;
        int steps = 0;
    };

    auto evaluate = [&](const vector<int>& c) {
        Eval ev;
        vector<ll> pref(M + 1, 0);
        vector<int> prevBefore(M, -1);
        ll sumAfter = 0;
        ll mn = 0;
        int prev = -1;
        int lastAny = -1;

        for (int k = 0; k < M; ++k) {
            prevBefore[k] = prev;
            pref[k + 1] = pref[k] + h[c[k]];
            sumAfter += pref[k + 1];
            mn = min(mn, pref[k + 1]);
            if (h[c[k]] != 0) {
                prev = k;
                lastAny = k;
            }
        }

        ll transport = sumAfter - (ll)M * mn;
        int bestMetric = INT_MAX;

        for (int s = 0; s < M; ++s) {
            if (pref[s] != mn) continue;
            int p = prevBefore[s];
            if (p < 0) p = lastAny;
            int tail = (p - s + M) % M;
            int metric = dist[0][c[s]] + tail;
            if (metric < bestMetric) {
                bestMetric = metric;
                ev.start = s;
                ev.steps = tail;
            }
        }

        ev.cost = transport + 100LL * bestMetric;
        return ev;
    };

    vector<pair<int, int>> baseCoords;
    for (int j = 0; j < N; ++j) baseCoords.push_back({0, j});
    for (int i = 1; i < N; ++i) {
        if (i & 1) {
            for (int j = N - 1; j >= 1; --j) baseCoords.push_back({i, j});
        } else {
            for (int j = 1; j < N; ++j) baseCoords.push_back({i, j});
        }
    }
    for (int i = N - 1; i >= 1; --i) baseCoords.push_back({i, 0});

    auto normalizedReverse = [&](const vector<int>& c) {
        vector<int> r(M);
        r[0] = c[0];
        for (int k = 1; k < M; ++k) r[k] = c[M - k];
        return r;
    };

    vector<int> bestCycle;
    ll bestCost = INF;

    for (int t = 0; t < 8; ++t) {
        vector<int> c;
        c.reserve(M);
        for (auto [rr, cc] : baseCoords) {
            int r = rr, col = cc;
            if (t & 1) swap(r, col);
            if (t & 2) r = N - 1 - r;
            if (t & 4) col = N - 1 - col;
            c.push_back(r * N + col);
        }

        int z = 0;
        while (c[z] != 0) ++z;
        rotate(c.begin(), c.begin() + z, c.begin());

        for (int rev = 0; rev < 2; ++rev) {
            Eval ev = evaluate(c);
            if (ev.cost < bestCost) {
                bestCost = ev.cost;
                bestCycle = c;
            }
            if (!rev) c = normalizedReverse(c);
        }
    }

    mt19937 rng(712367821);
    vector<int> current = bestCycle;
    ll currentCost = bestCost;
    vector<int> posInCycle(M);
    auto rebuildPos = [&]() {
        for (int k = 0; k < M; ++k) posInCycle[current[k]] = k;
    };
    rebuildPos();

    uniform_real_distribution<double> prob(0.0, 1.0);
    double progress = 0.0;
    bool intensified = false;
    ll iteration = 0;
    const double searchSeconds = 1.65;

    while (true) {
        ++iteration;
        if ((iteration & 1023) == 0) {
            double elapsed = chrono::duration<double>(
                chrono::steady_clock::now() - startTime).count();
            if (elapsed >= searchSeconds) break;
            progress = elapsed / searchSeconds;
            if (progress > 0.72 && !intensified) {
                current = bestCycle;
                currentCost = bestCost;
                rebuildPos();
                intensified = true;
            }
        }

        if ((iteration & 4095) == 0) {
            vector<int> rev = normalizedReverse(current);
            Eval ev = evaluate(rev);
            if (ev.cost < currentCost) {
                current = rev;
                currentCost = ev.cost;
                rebuildPos();
                if (currentCost < bestCost) {
                    bestCost = currentCost;
                    bestCycle = current;
                }
            }
            continue;
        }

        int i = (int)(rng() % M);
        int A = current[i];
        int B = current[(i + 1) % M];
        int ar = A / N, ac = A % N;
        int br = B / N, bc = B % N;
        int dr = br - ar, dc = bc - ac;
        int side = (rng() & 1) ? 1 : -1;
        int pr = -dc * side;
        int pc = dr * side;

        int cr = ar + pr, cc = ac + pc;
        int dr2 = br + pr, dc2 = bc + pc;
        if (cr < 0 || cr >= N || cc < 0 || cc >= N ||
            dr2 < 0 || dr2 >= N || dc2 < 0 || dc2 >= N) {
            continue;
        }

        int C = cr * N + cc;
        int D = dr2 * N + dc2;
        int j = posInCycle[C];
        if (current[(j + 1) % M] != D) continue;

        int a = min(i, j), b = max(i, j);
        if (a == b || b == a + 1 || (a == 0 && b == M - 1)) continue;
        if (!adjacent(current[a], current[b]) ||
            !adjacent(current[a + 1], current[(b + 1) % M])) {
            continue;
        }

        reverse(current.begin() + a + 1, current.begin() + b + 1);
        for (int k = a + 1; k <= b; ++k) posInCycle[current[k]] = k;

        Eval ev = evaluate(current);
        ll delta = ev.cost - currentCost;
        double temp = 10000.0 * pow(0.0001, progress) + 0.01;
        bool accept = (delta <= 0 || prob(rng) < exp(-(double)delta / temp));

        if (accept) {
            currentCost = ev.cost;
            if (currentCost < bestCost) {
                bestCost = currentCost;
                bestCycle = current;
            }
        } else {
            reverse(current.begin() + a + 1, current.begin() + b + 1);
            for (int k = a + 1; k <= b; ++k) posInCycle[current[k]] = k;
        }
    }

    auto makeCyclePlan = [&]() {
        Plan plan;
        plan.ops.clear();
        plan.cost = 0;
        plan.valid = true;

        Eval ev = evaluate(bestCycle);
        ll load = 0;
        int cur = 0;

        auto addMove = [&](int to) {
            int r = cur / N, c = cur % N;
            int nr = to / N, nc = to % N;
            string op;
            if (nr == r + 1) op = "D";
            else if (nr == r - 1) op = "U";
            else if (nc == c + 1) op = "R";
            else op = "L";
            plan.ops.push_back(op);
            plan.cost += 100 + load;
            cur = to;
        };

        int target = bestCycle[ev.start];
        int tr = target / N, tc = target % N;
        while (cur % N < tc) addMove(cur + 1);
        while (cur % N > tc) addMove(cur - 1);
        while (cur / N < tr) addMove(cur + N);
        while (cur / N > tr) addMove(cur - N);

        for (int rel = 0; rel <= ev.steps; ++rel) {
            int idx = (ev.start + rel) % M;
            int cell = bestCycle[idx];
            if (cur != cell) {
                plan.valid = false;
                return plan;
            }

            if (h[cell] > 0) {
                int d = h[cell];
                plan.ops.push_back("+" + to_string(d));
                plan.cost += d;
                load += d;
            } else if (h[cell] < 0) {
                int d = -h[cell];
                if (load < d) {
                    plan.valid = false;
                    return plan;
                }
                plan.ops.push_back("-" + to_string(d));
                plan.cost += d;
                load -= d;
            }

            if (rel < ev.steps) {
                int next = bestCycle[(idx + 1) % M];
                if (!adjacent(cur, next)) {
                    plan.valid = false;
                    return plan;
                }
                addMove(next);
            }
        }

        if (load != 0 || plan.ops.size() > 100000) plan.valid = false;
        return plan;
    };

    Plan answer = makeCyclePlan();

    auto greedyPlan = [&](int variant) {
        Plan plan;
        plan.cost = 0;
        plan.valid = true;
        vector<int> w = h;
        int remaining = 0;
        for (int x : w) if (x != 0) ++remaining;

        int cur = 0;
        ll load = 0;
        bool horizontalFirst = (variant & 1);
        int amountWeight = (variant >= 2) ? 15 : 0;

        auto addMove = [&](int to, const string& op) {
            plan.ops.push_back(op);
            plan.cost += 100 + load;
            cur = to;
        };

        while (remaining > 0) {
            if ((int)plan.ops.size() > 90000) {
                plan.valid = false;
                return plan;
            }

            if (load == 0 && w[cur] > 0) {
                int d = w[cur];
                plan.ops.push_back("+" + to_string(d));
                plan.cost += d;
                load += d;
                w[cur] = 0;
                --remaining;
                continue;
            }

            if (load > 0 && w[cur] < 0) {
                int d = (int)min<ll>(load, -w[cur]);
                plan.ops.push_back("-" + to_string(d));
                plan.cost += d;
                load -= d;
                w[cur] += d;
                if (w[cur] == 0) --remaining;
                continue;
            }

            int targetCell = -1;
            ll bestScore = INF;
            for (int cell = 0; cell < M; ++cell) {
                if (load == 0) {
                    if (w[cell] <= 0) continue;
                } else {
                    if (w[cell] >= 0) continue;
                }

                ll score = 100LL * dist[cur][cell];
                if (load == 0) {
                    score -= amountWeight * (ll)w[cell];
                } else if (variant >= 2 && -w[cell] < load) {
                    score += 40;
                }
                if (variant == 3) score += (ll)(rng() % 7);

                if (score < bestScore) {
                    bestScore = score;
                    targetCell = cell;
                }
            }

            if (targetCell < 0) {
                plan.valid = false;
                return plan;
            }

            int r = cur / N, c = cur % N;
            int tr = targetCell / N, tc = targetCell % N;
            bool canHorizontal = (c != tc);
            bool canVertical = (r != tr);
            bool goHorizontal = canHorizontal &&
                (!canVertical || horizontalFirst);

            if (goHorizontal) {
                if (tc > c) addMove(cur + 1, "R");
                else addMove(cur - 1, "L");
            } else {
                if (tr > r) addMove(cur + N, "D");
                else addMove(cur - N, "U");
            }
        }

        if (load != 0 || plan.ops.size() > 100000) plan.valid = false;
        return plan;
    };

    for (int variant = 0; variant < 4; ++variant) {
        Plan p = greedyPlan(variant);
        if (p.valid && (!answer.valid || p.cost < answer.cost)) {
            answer = move(p);
        }
    }

    for (const string& op : answer.ops) {
        cout << op << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Op {
    int type; // 0: load, 1: unload, 2: U, 3: D, 4: L, 5: R
    int d;
};

struct Config {
    double emptyLook = 0.0;
    double nextLook = 0.0;
    double noise = 0.0;
    double amountBonus = 0.0;
    bool oppUnload = false;
    bool oppPick = false;
    bool oppLoad = false;
    int pathStyle = 0;
    int collectRadius = 0;
    int collectMaxLoad = 0;
    double collectRatio = 1.0;
};

class Solver {
    static constexpr int N = 20;
    static constexpr int CELLS = N * N;
    array<int, CELLS> initial{};
    mt19937 rng{123456789};
    vector<Op> bestOps;
    long long bestCost = (1LL << 62);

    static int row(int p) { return p / N; }
    static int col(int p) { return p % N; }

    static int distance(int a, int b) {
        return abs(row(a) - row(b)) + abs(col(a) - col(b));
    }

    pair<long long, vector<Op>> simulate(const Config &cfg) {
        array<int, CELLS> h = initial;
        vector<Op> ops;
        ops.reserve(12000);

        int pos = 0;
        int load = 0;
        int posCount = 0, negCount = 0;
        for (int i = 0; i < CELLS; ++i) {
            if (h[i] > 0) ++posCount;
            if (h[i] < 0) ++negCount;
        }

        long long cost = 0;

        auto doLoad = [&](int p) {
            int d = h[p];
            h[p] = 0;
            load += d;
            cost += d;
            --posCount;
            ops.push_back({0, d});
        };

        auto doUnload = [&](int p) {
            int d = min(load, -h[p]);
            h[p] += d;
            load -= d;
            cost += d;
            if (h[p] == 0) --negCount;
            ops.push_back({1, d});
        };

        auto handleCurrent = [&](bool intermediate) {
            if (h[pos] > 0) {
                if (load == 0) {
                    if (!intermediate || cfg.oppPick) {
                        doLoad(pos);
                        return true;
                    }
                } else if (cfg.oppLoad) {
                    doLoad(pos);
                    return true;
                }
            }
            if (h[pos] < 0 && load > 0 && (!intermediate || cfg.oppUnload)) {
                doUnload(pos);
                return true;
            }
            return false;
        };

        auto moveOne = [&](int type) {
            if (type == 2) pos -= N;
            else if (type == 3) pos += N;
            else if (type == 4) --pos;
            else ++pos;
            cost += 100 + load;
            ops.push_back({type, 0});
        };

        auto distanceField = [&](bool positive) {
            array<int, CELLS> dist;
            dist.fill(-1);
            queue<int> q;
            for (int i = 0; i < CELLS; ++i) {
                if ((positive && h[i] > 0) || (!positive && h[i] < 0)) {
                    dist[i] = 0;
                    q.push(i);
                }
            }
            const int dr[4] = {-1, 1, 0, 0};
            const int dc[4] = {0, 0, -1, 1};
            while (!q.empty()) {
                int p = q.front();
                q.pop();
                int r = row(p), c = col(p);
                for (int k = 0; k < 4; ++k) {
                    int nr = r + dr[k], nc = c + dc[k];
                    if (nr < 0 || nr >= N || nc < 0 || nc >= N) continue;
                    int np = nr * N + nc;
                    if (dist[np] != -1) continue;
                    dist[np] = dist[p] + 1;
                    q.push(np);
                }
            }
            return dist;
        };

        auto realNoise = [&]() {
            return uniform_real_distribution<double>(-1.0, 1.0)(rng);
        };

        while (true) {
            handleCurrent(false);
            if (posCount == 0 && negCount == 0 && load == 0) break;

            int target = -1;

            if (load == 0) {
                array<int, CELLS> negDist{};
                if (cfg.emptyLook != 0.0) negDist = distanceField(false);

                double best = 1e100;
                for (int s = 0; s < CELLS; ++s) {
                    if (h[s] <= 0) continue;
                    double score = distance(pos, s);
                    if (cfg.emptyLook != 0.0 && negDist[s] >= 0) {
                        score += cfg.emptyLook * negDist[s];
                    }
                    score -= cfg.amountBonus * (double)h[s] / 100.0;
                    score += cfg.noise * realNoise();
                    if (score < best) {
                        best = score;
                        target = s;
                    }
                }
            } else {
                if (cfg.collectRadius > 0 && load < cfg.collectMaxLoad) {
                    int nearestSource = -1;
                    int ds = 1000;
                    for (int s = 0; s < CELLS; ++s) {
                        if (h[s] <= 0) continue;
                        int d = distance(pos, s);
                        if (d < ds) {
                            ds = d;
                            nearestSource = s;
                        }
                    }
                    if (nearestSource != -1 && ds <= cfg.collectRadius) {
                        array<int, CELLS> negDist = distanceField(false);
                        int dn = negDist[pos] < 0 ? 1000 : negDist[pos];
                        if (ds < cfg.collectRatio * max(1, dn) + 1.0) {
                            target = nearestSource;
                        }
                    }
                }

                if (target == -1) {
                    array<int, CELLS> posDist{};
                    if (cfg.nextLook != 0.0) posDist = distanceField(true);

                    double best = 1e100;
                    for (int t = 0; t < CELLS; ++t) {
                        if (h[t] >= 0) continue;
                        double score = distance(pos, t);
                        if (cfg.nextLook != 0.0 && load <= -h[t] && posDist[t] >= 0) {
                            score += cfg.nextLook * posDist[t];
                        }
                        score -= cfg.amountBonus * (double)(-h[t]) / 100.0;
                        score += cfg.noise * realNoise();
                        if (score < best) {
                            best = score;
                            target = t;
                        }
                    }
                }
            }

            if (target == -1) break;

            while (pos != target) {
                int dr = row(target) - row(pos);
                int dc = col(target) - col(pos);
                vector<int> options;

                auto addHorizontal = [&]() {
                    if (dc > 0) options.push_back(5);
                    else if (dc < 0) options.push_back(4);
                };
                auto addVertical = [&]() {
                    if (dr > 0) options.push_back(3);
                    else if (dr < 0) options.push_back(2);
                };

                if (cfg.pathStyle == 0) {
                    addHorizontal();
                    addVertical();
                } else if (cfg.pathStyle == 1) {
                    addVertical();
                    addHorizontal();
                } else {
                    addHorizontal();
                    addVertical();
                    if (options.size() == 2) {
                        int chosen = 0;
                        if (cfg.pathStyle == 2) {
                            chosen = (rng() & 1);
                        } else {
                            double utility[2] = {0.0, 0.0};
                            for (int k = 0; k < 2; ++k) {
                                int np = pos;
                                if (options[k] == 2) np -= N;
                                else if (options[k] == 3) np += N;
                                else if (options[k] == 4) --np;
                                else ++np;

                                if (h[np] < 0 && load > 0 && cfg.oppUnload) {
                                    utility[k] += 2.0 + min(load, -h[np]) / 100.0;
                                }
                                if (h[np] > 0 &&
                                    ((load == 0 && cfg.oppPick) || (load > 0 && cfg.oppLoad))) {
                                    utility[k] += 2.0 + h[np] / 100.0;
                                }
                                utility[k] += uniform_real_distribution<double>(0.0, 0.2)(rng);
                            }
                            chosen = utility[1] > utility[0];
                        }
                        swap(options[0], options[chosen]);
                    }
                }

                moveOne(options[0]);
                if (pos != target && handleCurrent(true)) break;
            }
        }

        return {cost, move(ops)};
    }

public:
    void readInput() {
        int n;
        cin >> n;
        for (int i = 0; i < CELLS; ++i) cin >> initial[i];
    }

    void solve() {
        const int RUNS = 320;

        for (int run = 0; run < RUNS; ++run) {
            Config cfg;

            if (run == 1) {
                cfg.oppUnload = true;
                cfg.oppPick = true;
                cfg.pathStyle = 2;
            } else if (run == 2) {
                cfg.emptyLook = 1.0;
                cfg.oppUnload = true;
                cfg.oppPick = true;
                cfg.pathStyle = 3;
            } else if (run == 3) {
                cfg.emptyLook = 0.5;
                cfg.nextLook = 0.5;
                cfg.oppUnload = true;
                cfg.oppPick = true;
                cfg.pathStyle = 3;
            } else if (run == 4) {
                cfg.emptyLook = 0.5;
                cfg.nextLook = 0.25;
                cfg.oppUnload = true;
                cfg.oppPick = true;
                cfg.oppLoad = true;
                cfg.pathStyle = 3;
            } else if (run == 5) {
                cfg.emptyLook = 1.0;
                cfg.oppUnload = true;
                cfg.oppPick = true;
                cfg.oppLoad = true;
                cfg.pathStyle = 3;
                cfg.collectRadius = 2;
                cfg.collectMaxLoad = 400;
                cfg.collectRatio = 1.0;
            } else if (run >= 6) {
                const double looks[] = {0.0, 0.2, 0.4, 0.7, 1.0, 1.5, 2.0};
                const double noises[] = {0.0, 0.05, 0.15, 0.35, 0.7, 1.2, 2.0};

                cfg.emptyLook = looks[rng() % 7];
                cfg.nextLook = looks[rng() % 7];
                cfg.noise = noises[rng() % 7];
                cfg.amountBonus = (rng() % 5 == 0)
                    ? uniform_real_distribution<double>(0.0, 1.5)(rng) : 0.0;

                cfg.oppUnload = (rng() % 10 != 0);
                cfg.oppPick = (rng() % 10 < 8);
                cfg.oppLoad = (rng() % 10 < 4);
                cfg.pathStyle = 2 + (rng() & 1);

                if (rng() % 100 < 38) {
                    cfg.collectRadius = 1 + rng() % 4;
                    const int limits[] = {150, 250, 400, 700, 1200, 20000};
                    cfg.collectMaxLoad = limits[rng() % 6];
                    cfg.collectRatio = uniform_real_distribution<double>(0.45, 1.5)(rng);
                    cfg.oppLoad = true;
                }
            }

            auto result = simulate(cfg);
            if (result.second.size() > 100000) continue;
            if (result.first < bestCost) {
                bestCost = result.first;
                bestOps = move(result.second);
            }
        }
    }

    void output() const {
        for (const Op &op : bestOps) {
            if (op.type == 0) cout << '+' << op.d << '\n';
            else if (op.type == 1) cout << '-' << op.d << '\n';
            else if (op.type == 2) cout << 'U' << '\n';
            else if (op.type == 3) cout << 'D' << '\n';
            else if (op.type == 4) cout << 'L' << '\n';
            else cout << 'R' << '\n';
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Solver solver;
    solver.readInput();
    solver.solve();
    solver.output();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int N;
vector<vector<int>> H;
int baseCost;

int manhattan(int r1, int c1, int r2, int c2) {
    return abs(r1-r2) + abs(c1-c2);
}

void moveTo(int tr, int tc, int load, int& pr, int& pc, vector<string>& ops, long long& cost) {
    while (pr != tr || pc != tc) {
        char dir;
        if (pr < tr) { pr++; dir='D'; }
        else if (pr > tr) { pr--; dir='U'; }
        else if (pc < tc) { pc++; dir='R'; }
        else { pc--; dir='L'; }
        cost += 100 + load;
        ops.push_back(string(1, dir));
    }
}

struct Params {
    bool partial;
    bool allowPosLoaded;
    bool lookaheadPos;
    int noise;
    double posPenalty;
    double unloadWeight;
};

void runGreedy(const Params& P, vector<string>& bestOps, long long& bestCost) {
    vector<vector<int>> h = H;
    int pr=0, pc=0, load=0;
    long long cost=0;
    vector<string> ops;
    ops.reserve(50000);
    while (true) {
        bool any = false;
        for (int i=0;i<N;i++) for (int j=0;j<N;j++) if (h[i][j]!=0) { any=true; break; }
        if (!any && load==0) break;
        int tr=-1, tc=-1;
        if (load == 0) {
            double bestScore = 1e18;
            for (int r=0;r<N;r++) for (int c=0;c<N;c++) if (h[r][c] > 0) {
                int dist = manhattan(pr,pc,r,c);
                double score = dist * 100.0;
                if (P.lookaheadPos) {
                    int minNeg = 1000000;
                    for (int nr=0;nr<N;nr++) for (int nc=0;nc<N;nc++) if (h[nr][nc] < 0) {
                        minNeg = min(minNeg, manhattan(r,c,nr,nc));
                    }
                    if (minNeg == 1000000) minNeg = 0;
                    score += minNeg * (100.0 + h[r][c]) + h[r][c];
                }
                if (P.noise > 0) {
                    score += (rand() % (2*P.noise+1) - P.noise);
                }
                if (score < bestScore) { bestScore = score; tr=r; tc=c; }
            }
        } else {
            double bestScore = 1e18;
            for (int r=0;r<N;r++) for (int c=0;c<N;c++) {
                if (h[r][c] == 0) continue;
                bool isPos = h[r][c] > 0;
                if (isPos && !P.allowPosLoaded) continue;
                if (!isPos) {
                    if (!P.partial && -h[r][c] > load) continue;
                }
                int dist = manhattan(pr,pc,r,c);
                double score;
                if (isPos) {
                    score = (100.0 + load) * dist + P.posPenalty * h[r][c];
                } else {
                    int unloadAmt = P.partial ? min(load, -h[r][c]) : -h[r][c];
                    score = (100.0 + load) * dist - P.unloadWeight * unloadAmt;
                }
                if (P.noise > 0) {
                    score += (rand() % (2*P.noise+1) - P.noise);
                }
                if (score < bestScore) { bestScore = score; tr=r; tc=c; }
            }
            if (tr == -1) {
                bestScore = 1e18;
                for (int r=0;r<N;r++) for (int c=0;c<N;c++) if (h[r][c] > 0) {
                    int dist = manhattan(pr,pc,r,c);
                    double score = (100.0 + load) * dist;
                    if (P.noise > 0) score += (rand() % (2*P.noise+1) - P.noise);
                    if (score < bestScore) { bestScore = score; tr=r; tc=c; }
                }
            }
        }
        if (tr == -1) break;
        moveTo(tr, tc, load, pr, pc, ops, cost);
        if (h[tr][tc] > 0) {
            int d = h[tr][tc];
            h[tr][tc] = 0;
            load += d;
            cost += d;
            ops.push_back("+" + to_string(d));
        } else if (h[tr][tc] < 0) {
            int d;
            if (P.partial) {
                d = min(load, -h[tr][tc]);
            } else {
                d = -h[tr][tc];
            }
            h[tr][tc] += d;
            load -= d;
            cost += d;
            ops.push_back("-" + to_string(d));
        }
    }
    if (ops.size() <= 100000 && cost < bestCost) {
        bestCost = cost;
        bestOps = ops;
    }
}

void runCycle(const vector<pair<int,int>>& cyc, vector<string>& bestOps, long long& bestCost) {
    int n = cyc.size();
    long long bestLocalCost = LLONG_MAX;
    int bestStart = -1;
    for (int s=0; s<n; s++) {
        int load = 0;
        bool ok = true;
        long long sumLoad = 0;
        for (int i=0; i<n; i++) {
            int idx = (s+i)%n;
            int r = cyc[idx].first, c = cyc[idx].second;
            load += H[r][c];
            if (load < 0) { ok = false; break; }
            if (i < n-1) sumLoad += load;
        }
        if (!ok) continue;
        int dist = manhattan(0,0,cyc[s].first,cyc[s].second);
        long long cost = (long long)baseCost + 100LL*dist + 100LL*(n-1) + sumLoad;
        if (cost < bestLocalCost) {
            bestLocalCost = cost;
            bestStart = s;
        }
    }
    if (bestStart == -1) return;
    vector<string> ops;
    ops.reserve(1000);
    int pr=0, pc=0;
    long long cost=0;
    int sr = cyc[bestStart].first, sc = cyc[bestStart].second;
    moveTo(sr, sc, 0, pr, pc, ops, cost);
    int load = 0;
    for (int i=0; i<n; i++) {
        int idx = (bestStart + i) % n;
        int r = cyc[idx].first, c = cyc[idx].second;
        if (H[r][c] > 0) {
            int d = H[r][c];
            load += d;
            cost += d;
            ops.push_back("+" + to_string(d));
        } else if (H[r][c] < 0) {
            int d = -H[r][c];
            load -= d;
            cost += d;
            ops.push_back("-" + to_string(d));
        }
        if (i < n-1) {
            int nidx = (bestStart + i + 1) % n;
            int nr = cyc[nidx].first, nc = cyc[nidx].second;
            moveTo(nr, nc, load, pr, pc, ops, cost);
        }
    }
    if (ops.size() <= 100000 && cost < bestCost) {
        bestCost = cost;
        bestOps = ops;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N;
    H.assign(N, vector<int>(N));
    baseCost = 0;
    for (int i=0;i<N;i++) {
        for (int j=0;j<N;j++) {
            cin >> H[i][j];
            baseCost += abs(H[i][j]);
        }
    }
    if (baseCost == 0) return 0;

    vector<string> bestOps;
    long long bestCost = LLONG_MAX;

    vector<pair<int,int>> cyc;
    for (int c=0;c<N;c++) cyc.push_back({0,c});
    for (int r=1;r<=N-2;r++) {
        if (r%2==1) {
            for (int c=N-1;c>=1;c--) cyc.push_back({r,c});
        } else {
            for (int c=1;c<=N-1;c++) cyc.push_back({r,c});
        }
    }
    for (int c=N-1;c>=0;c--) cyc.push_back({N-1,c});
    for (int r=N-2;r>=1;r--) cyc.push_back({r,0});

    runCycle(cyc, bestOps, bestCost);
    vector<pair<int,int>> revCyc = cyc;
    reverse(revCyc.begin(), revCyc.end());
    runCycle(revCyc, bestOps, bestCost);

    vector<Params> params;
    params.push_back({true, false, false, 0, 0, 0});
    params.push_back({false, false, false, 0, 0, 0});
    params.push_back({true, false, true, 0, 0, 0});
    params.push_back({false, false, true, 0, 0, 0});
    params.push_back({true, true, true, 0, 10, 10});
    params.push_back({false, true, true, 0, 10, 10});
    params.push_back({true, true, false, 0, 50, 20});
    params.push_back({false, true, false, 0, 50, 20});
    for (auto& p : params) {
        runGreedy(p, bestOps, bestCost);
    }

    srand(12345);
    for (int iter=0; iter<20; iter++) {
        Params p;
        p.partial = rand()%2;
        p.allowPosLoaded = rand()%2;
        p.lookaheadPos = false;
        p.noise = (rand()%5)*200;
        p.posPenalty = 5 + rand()%100;
        p.unloadWeight = 5 + rand()%100;
        runGreedy(p, bestOps, bestCost);
    }

    for (const string& op : bestOps) {
        cout << op << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Task {
    int x, y;
    int delta; // Positive: soil to load, negative: soil to unload.
};

struct Operation {
    char type;
    int amount;
};

class Solver {
public:
    int n, m, startX = 0, startY = 0;
    vector<vector<int>> height;
    vector<vector<int>> cellTask;
    vector<Task> tasks;
    vector<vector<int>> distMatrix;
    vector<int> startDist;
    vector<int> sourceTasks, sinkTasks;
    int baseCost = 0;

    mt19937 rng;

    Solver(int n, vector<vector<int>> h, uint32_t seed)
        : n(n), height(std::move(h)), rng(seed) {
        cellTask.assign(n, vector<int>(n, -1));

        for (int x = 0; x < n; ++x) {
            for (int y = 0; y < n; ++y) {
                if (height[x][y] == 0) continue;
                int id = (int)tasks.size();
                cellTask[x][y] = id;
                tasks.push_back({x, y, height[x][y]});
                baseCost += abs(height[x][y]);
                if (height[x][y] > 0) sourceTasks.push_back(id);
                else sinkTasks.push_back(id);
            }
        }

        m = (int)tasks.size();
        distMatrix.assign(m, vector<int>(m));
        startDist.resize(m);

        for (int i = 0; i < m; ++i) {
            startDist[i] = abs(tasks[i].x) + abs(tasks[i].y);
            for (int j = 0; j < m; ++j) {
                distMatrix[i][j] =
                    abs(tasks[i].x - tasks[j].x) +
                    abs(tasks[i].y - tasks[j].y);
            }
        }
    }

    long long routeCost(const vector<int>& order) const {
        if ((int)order.size() != m) return (1LL << 60);

        int current = -1;
        int load = 0;
        long long cost = 0;

        for (int t : order) {
            int d = (current == -1 ? startDist[t] : distMatrix[current][t]);
            cost += 1LL * d * (100 + load);
            load += tasks[t].delta;
            if (load < 0) return (1LL << 60);
            current = t;
        }
        return cost;
    }

    vector<int> greedyOrder(double beta, double jitter, bool useResultingLoad) {
        vector<char> used(m, false);
        vector<int> order;
        order.reserve(m);

        int current = -1;
        int load = 0;

        for (int step = 0; step < m; ++step) {
            double bestScore = 1e100;
            int best = -1;

            for (int t = 0; t < m; ++t) {
                if (used[t]) continue;

                int newLoad = load + tasks[t].delta;
                if (newLoad < 0) continue;

                int d = (current == -1 ? startDist[t] : distMatrix[current][t]);
                double edgeLoad = useResultingLoad ? newLoad : load;
                double noise = jitter == 0.0
                    ? 0.0
                    : (double(rng()) / double(rng.max()) - 0.5) * 2.0 * jitter;

                double score = d * (100.0 + edgeLoad) + beta * newLoad + noise;

                if (best == -1 || score < bestScore ||
                    (score == bestScore && (rng() & 1))) {
                    bestScore = score;
                    best = t;
                }
            }

            if (best == -1) return {};
            used[best] = true;
            order.push_back(best);
            load += tasks[best].delta;
            current = best;
        }
        return order;
    }

    vector<int> nearestOrder(const vector<int>& candidates) const {
        vector<char> used(m, false);
        vector<int> result;
        int current = -1;

        for (int k = 0; k < (int)candidates.size(); ++k) {
            int best = -1, bestDistance = INT_MAX;
            for (int t : candidates) {
                if (used[t]) continue;
                int d = (current == -1 ? startDist[t] : distMatrix[current][t]);
                if (d < bestDistance ||
                    (d == bestDistance && (rng() & 1))) {
                    bestDistance = d;
                    best = t;
                }
            }
            if (best == -1) break;
            used[best] = true;
            result.push_back(best);
            current = best;
        }
        return result;
    }

    vector<int> snakeOrder(bool rowWise) const {
        vector<int> order;
        if (rowWise) {
            for (int x = 0; x < n; ++x) {
                if (x & 1) {
                    for (int y = n - 1; y >= 0; --y)
                        if (cellTask[x][y] != -1) order.push_back(cellTask[x][y]);
                } else {
                    for (int y = 0; y < n; ++y)
                        if (cellTask[x][y] != -1) order.push_back(cellTask[x][y]);
                }
            }
        } else {
            for (int y = 0; y < n; ++y) {
                if (y & 1) {
                    for (int x = n - 1; x >= 0; --x)
                        if (cellTask[x][y] != -1) order.push_back(cellTask[x][y]);
                } else {
                    for (int x = 0; x < n; ++x)
                        if (cellTask[x][y] != -1) order.push_back(cellTask[x][y]);
                }
            }
        }
        return order;
    }

    vector<int> repairFeasible(const vector<int>& original) const {
        vector<int> order;
        vector<int> pending;
        vector<char> emitted(m, false);
        int load = 0;

        auto servicePending = [&]() {
            while (true) {
                int chosen = -1;
                for (int i = 0; i < (int)pending.size(); ++i) {
                    int t = pending[i];
                    if (load + tasks[t].delta >= 0) {
                        chosen = i;
                        break;
                    }
                }
                if (chosen == -1) break;

                int t = pending[chosen];
                pending.erase(pending.begin() + chosen);
                emitted[t] = true;
                order.push_back(t);
                load += tasks[t].delta;
            }
        };

        for (int t : original) {
            if (emitted[t]) continue;

            if (tasks[t].delta > 0) {
                emitted[t] = true;
                order.push_back(t);
                load += tasks[t].delta;
                servicePending();
            } else if (load + tasks[t].delta >= 0) {
                emitted[t] = true;
                order.push_back(t);
                load += tasks[t].delta;
            } else {
                pending.push_back(t);
            }
        }

        for (int t : pending) {
            order.push_back(t);
            load += tasks[t].delta;
        }
        return order;
    }

    vector<int> beamOrder(int width = 80) {
        if (m == 0) return {};

        struct Node {
            int parent = -1;
            int task = -1;
            int current = -1;
            int load = 0;
            long long cost = 0;
            array<uint64_t, 7> bits{};
        };

        struct Candidate {
            int parent;
            int task;
            int load;
            long long cost;
            double score;
        };

        vector<int> nearestSink(m, 0);
        for (int t = 0; t < m; ++t) {
            int best = INT_MAX;
            for (int s : sinkTasks) {
                if (s == t) continue;
                best = min(best, distMatrix[t][s]);
            }
            nearestSink[t] = (best == INT_MAX ? 0 : best);
        }

        vector<vector<Node>> levels;
        levels.emplace_back();

        for (int depth = 0; depth < m; ++depth) {
            vector<Candidate> candidates;
            candidates.reserve(levels.back().size() * (m - depth));

            for (int p = 0; p < (int)levels.back().size(); ++p) {
                const Node& parent = levels.back()[p];

                for (int t = 0; t < m; ++t) {
                    if ((parent.bits[t >> 6] >> (t & 63)) & 1ULL) continue;

                    int newLoad = parent.load + tasks[t].delta;
                    if (newLoad < 0) continue;

                    int d = (parent.current == -1
                        ? startDist[t]
                        : distMatrix[parent.current][t]);

                    long long newCost =
                        parent.cost + 1LL * d * (100 + parent.load);

                    double score =
                        double(newCost) + double(newLoad) * nearestSink[t];

                    candidates.push_back({p, t, newLoad, newCost, score});
                }
            }

            if (candidates.empty()) return {};

            int poolSize = min((int)candidates.size(), width * 6);
            if (poolSize < (int)candidates.size()) {
                nth_element(
                    candidates.begin(),
                    candidates.begin() + poolSize,
                    candidates.end(),
                    [](const Candidate& a, const Candidate& b) {
                        return a.score < b.score;
                    }
                );
            }
            candidates.resize(poolSize);

            sort(candidates.begin(), candidates.end(),
                 [](const Candidate& a, const Candidate& b) {
                     return a.score < b.score;
                 });

            vector<int> parentCount(levels.back().size(), 0);
            vector<Candidate> selected;
            selected.reserve(width);
            int maxPerParent = max(4, width / 4);

            for (const Candidate& c : candidates) {
                if (parentCount[c.parent] >= maxPerParent) continue;
                parentCount[c.parent]++;
                selected.push_back(c);
                if ((int)selected.size() == width) break;
            }

            if ((int)selected.size() < width) {
                for (const Candidate& c : candidates) {
                    if ((int)selected.size() == width) break;
                    bool already = false;
                    for (const Candidate& s : selected) {
                        if (s.parent == c.parent && s.task == c.task) {
                            already = true;
                            break;
                        }
                    }
                    if (!already) selected.push_back(c);
                }
            }

            vector<Node> nextLevel;
            nextLevel.reserve(selected.size());

            for (const Candidate& c : selected) {
                Node node;
                node.parent = c.parent;
                node.task = c.task;
                node.current = c.task;
                node.load = c.load;
                node.cost = c.cost;
                node.bits = levels.back()[c.parent].bits;
                node.bits[c.task >> 6] |= 1ULL << (c.task & 63);
                nextLevel.push_back(node);
            }

            levels.push_back(std::move(nextLevel));
        }

        int bestIndex = 0;
        for (int i = 1; i < (int)levels.back().size(); ++i) {
            if (levels.back()[i].cost < levels.back()[bestIndex].cost)
                bestIndex = i;
        }

        vector<int> order;
        int index = bestIndex;
        for (int depth = m; depth >= 1; --depth) {
            order.push_back(levels[depth][index].task);
            index = levels[depth][index].parent;
        }
        reverse(order.begin(), order.end());
        return order;
    }

    bool realizeOrder(
        const vector<int>& plan,
        int pathMode,
        bool earlySource,
        bool earlySink,
        vector<int>& extracted
    ) const {
        vector<char> processed(m, false);
        extracted.clear();

        int x = 0, y = 0, load = 0;

        auto processCell = [&](bool forced) -> bool {
            int t = cellTask[x][y];
            if (t == -1 || processed[t]) return true;

            if (tasks[t].delta > 0) {
                if (forced || earlySource) {
                    load += tasks[t].delta;
                    processed[t] = true;
                    extracted.push_back(t);
                }
            } else {
                if (load + tasks[t].delta < 0) return forced;
                if (forced || earlySink) {
                    load += tasks[t].delta;
                    processed[t] = true;
                    extracted.push_back(t);
                }
            }
            return true;
        };

        if (!processCell(false)) return false;

        auto appendMonotone = [&](int tx, int ty, bool verticalFirst) {
            if (verticalFirst) {
                while (x != tx) {
                    if (x < tx) ++x; else --x;
                }
                while (y != ty) {
                    if (y < ty) ++y; else --y;
                }
            } else {
                while (y != ty) {
                    if (y < ty) ++y; else --y;
                }
                while (x != tx) {
                    if (x < tx) ++x; else --x;
                }
            }
        };

        for (int target : plan) {
            if (processed[target]) continue;

            int tx = tasks[target].x;
            int ty = tasks[target].y;

            if (pathMode >= 2) {
                int via = -1;
                int minX = min(x, tx), maxX = max(x, tx);
                int minY = min(y, ty), maxY = max(y, ty);

                for (int t = 0; t < m; ++t) {
                    if (processed[t] || t == target) continue;
                    if (tasks[t].x < minX || tasks[t].x > maxX ||
                        tasks[t].y < minY || tasks[t].y > maxY) continue;

                    if (pathMode == 2 && tasks[t].delta < 0) {
                        via = t;
                        break;
                    }
                    if (pathMode == 3 && tasks[t].delta > 0) {
                        via = t;
                        break;
                    }
                }

                if (via != -1) {
                    int vx = tasks[via].x, vy = tasks[via].y;
                    appendMonotone(vx, vy, (pathMode & 1) != 0);
                    if (!processCell(false)) return false;
                    appendMonotone(tx, ty, (pathMode & 1) == 0);
                } else {
                    appendMonotone(tx, ty, (pathMode & 1) != 0);
                }
            } else {
                appendMonotone(tx, ty, (pathMode & 1) != 0);
            }

            if (!processCell(true)) return false;
        }

        int count = 0;
        for (char c : processed) count += c;
        return count == m && load == 0;
    }

    struct AnnealResult {
        vector<int> order;
        long long cost;
    };

    AnnealResult anneal(
        const vector<int>& initial,
        int iterations,
        double initialTemperature,
        double finalTemperature,
        vector<int>& globalBest,
        long long& globalBestCost
    ) {
        struct State {
            vector<int> order;
            vector<int> prefix;
            long long cost;
        };

        State current;
        current.order = initial;
        current.prefix.assign(m + 1, 0);
        current.cost = routeCost(current.order);

        auto rebuild = [&](State& state) {
            state.prefix.assign(m + 1, 0);
            for (int i = 0; i < m; ++i)
                state.prefix[i + 1] = state.prefix[i] + tasks[state.order[i]].delta;
            state.cost = routeCost(state.order);
        };

        rebuild(current);

        State runBest = current;
        if (current.cost < globalBestCost) {
            globalBestCost = current.cost;
            globalBest = current.order;
        }

        vector<int> segment;
        segment.reserve(m);
        uniform_real_distribution<double> uniform01(0.0, 1.0);

        for (int iteration = 0; iteration < iterations; ++iteration) {
            double progress = double(iteration) / double(iterations);
            double temperature = initialTemperature *
                pow(finalTemperature / initialTemperature, progress);

            int left = rng() % m;
            int right = left;
            int type = rng() % 100;

            auto randomOther = [&](int a) {
                if (rng() & 1) {
                    int span = min(30, m - 1);
                    int offset = 1 + rng() % span;
                    int b = a + ((rng() & 1) ? offset : -offset);
                    if (b < 0) b += m;
                    if (b >= m) b -= m;
                    return b;
                }
                return rng() % m;
            };

            if (type < 24) {
                int i = rng() % (m - 1);
                int j = i + 1;
                left = i;
                right = j;
                segment.assign(current.order.begin() + i,
                               current.order.begin() + j + 1);
                swap(segment.front(), segment.back());
            } else if (type < 44) {
                int i = randomOther(left);
                int j = randomOther(i);
                if (i == j) continue;
                left = min(i, j);
                right = max(i, j);
                segment.assign(current.order.begin() + left,
                               current.order.begin() + right + 1);
                swap(segment.front(), segment.back());
            } else if (type < 69) {
                int from = rng() % m;
                int to = randomOther(from);
                if (from == to) continue;

                left = min(from, to);
                right = max(from, to);
                segment.clear();

                if (from < to) {
                    for (int i = from + 1; i <= to; ++i)
                        segment.push_back(current.order[i]);
                    segment.push_back(current.order[from]);
                } else {
                    segment.push_back(current.order[from]);
                    for (int i = to; i < from; ++i)
                        segment.push_back(current.order[i]);
                }
            } else if (type < 84) {
                if (sourceTasks.empty() || sinkTasks.empty()) continue;
                int st = sourceTasks[rng() % sourceTasks.size()];
                int kt = sinkTasks[rng() % sinkTasks.size()];

                int si = -1, ki = -1;
                for (int i = 0; i < m; ++i) {
                    if (current.order[i] == st) si = i;
                    if (current.order[i] == kt) ki = i;
                }
                if (si < 0 || ki < 0 || si == ki) continue;

                left = min(si, ki);
                right = max(si, ki);
                segment.assign(current.order.begin() + left,
                               current.order.begin() + right + 1);
                swap(segment.front(), segment.back());
            } else if (type < 94) {
                int a = rng() % m;
                int b = a + 1 + rng() % (m - a - 1);
                int c = b + 1 + rng() % (m - b);
                left = a;
                right = c - 1;
                segment.clear();
                for (int i = b; i < c; ++i) segment.push_back(current.order[i]);
                for (int i = a; i < b; ++i) segment.push_back(current.order[i]);
            } else {
                int i = rng() % m;
                int j = rng() % m;
                if (i == j) continue;
                left = min(i, j);
                right = max(i, j);
                segment.assign(current.order.begin() + left,
                               current.order.begin() + right + 1);
                reverse(segment.begin(), segment.end());
            }

            int i = left, j = right;
            long long oldCost = 0;
            long long newCost = 0;

            int firstDistance;
            if (i == 0) firstDistance = startDist[current.order[i]];
            else firstDistance = distMatrix[current.order[i - 1]][current.order[i]];

            oldCost = 1LL * firstDistance * (100 + current.prefix[i]);

            for (int k = i; k < j; ++k) {
                oldCost += 1LL * distMatrix[current.order[k]][current.order[k + 1]]
                           * (100 + current.prefix[k]);
            }
            if (j + 1 < m) {
                oldCost += 1LL * distMatrix[current.order[j]][current.order[j + 1]]
                           * (100 + current.prefix[j]);
            }

            int load = current.prefix[i];
            for (int k = 0; k < (int)segment.size(); ++k) {
                int t = segment[k];
                int d;
                if (k == 0) {
                    d = (i == 0 ? startDist[t]
                                : distMatrix[current.order[i - 1]][t]);
                } else {
                    d = distMatrix[segment[k - 1]][t];
                }

                newCost += 1LL * d * (100 + load);
                load += tasks[t].delta;
                if (load < 0) {
                    newCost = (1LL << 60);
                    break;
                }
            }

            if (newCost == (1LL << 60)) continue;

            if (j + 1 < m) {
                newCost += 1LL * distMatrix[segment.back()][current.order[j + 1]]
                           * (100 + load);
            }

            long long delta = newCost - oldCost;
            bool accept = delta <= 0;
            if (!accept) {
                accept = uniform01(rng) <
                    exp(-double(delta) / max(0.0001, temperature));
            }
            if (!accept) continue;

            int newLoad = current.prefix[i];
            for (int k = 0; k < (int)segment.size(); ++k) {
                int pos = i + k;
                current.order[pos] = segment[k];
                newLoad += tasks[segment[k]].delta;
                current.prefix[pos] = newLoad;
            }
            current.cost += delta;

            if (current.cost < runBest.cost) {
                runBest = current;
                if (runBest.cost < globalBestCost) {
                    globalBestCost = runBest.cost;
                    globalBest = runBest.order;
                }
            }

            if ((iteration & 8191) == 8191 &&
                current.cost > runBest.cost + 5000) {
                current = runBest;
            }
        }

        if (runBest.cost < globalBestCost) {
            globalBestCost = runBest.cost;
            globalBest = runBest.order;
        }
        return {runBest.order, runBest.cost};
    }

    bool generatePartialPlan(
        double beta,
        int sourcePolicy,
        int automaticMode,
        bool verticalFirst,
        vector<Operation>& result,
        long long& resultCost
    ) const {
        vector<int> remaining(m);
        for (int i = 0; i < m; ++i) remaining[i] = tasks[i].delta;

        vector<Operation> operations;
        operations.reserve(20000);

        int x = 0, y = 0, load = 0;
        long long cost = 0;
        int remainingNonzero = m;

        auto nearestSinkDemand = [&](int source) {
            int best = INT_MAX;
            for (int t : sinkTasks) {
                if (remaining[t] >= 0) continue;
                int d = distMatrix[source][t];
                if (d < best) best = d;
            }
            if (best == INT_MAX) return INT_MAX;
            for (int t : sinkTasks) {
                if (remaining[t] < 0 &&
                    distMatrix[source][t] == best)
                    return -remaining[t];
            }
            return INT_MAX;
        };

        auto sourceAmount = [&](int t) {
            if (sourcePolicy == 0) return remaining[t];
            int demand = nearestSinkDemand(t);
            if (demand == INT_MAX) return remaining[t];
            return min(remaining[t], demand);
        };

        auto processCell = [&](bool forced) {
            int t = cellTask[x][y];
            if (t == -1 || remaining[t] == 0) return;

            if (remaining[t] > 0) {
                if (forced || (automaticMode & 1)) {
                    int amount = sourceAmount(t);
                    if (amount <= 0) return;
                    remaining[t] -= amount;
                    load += amount;
                    cost += amount;
                    operations.push_back({'+', amount});
                    --remainingNonzero;
                }
            } else {
                int amount = min(load, -remaining[t]);
                if (amount <= 0) return;
                if (forced || (automaticMode & 2)) {
                    remaining[t] += amount;
                    load -= amount;
                    cost += amount;
                    operations.push_back({'-', amount});
                    if (remaining[t] == 0) --remainingNonzero;
                }
            }
        };

        for (int iteration = 0; iteration < 2500 && remainingNonzero > 0; ++iteration) {
            int target = -1;
            double bestScore = 1e100;

            for (int t = 0; t < m; ++t) {
                if (remaining[t] == 0) continue;

                int amount, resultLoad;
                if (remaining[t] > 0) {
                    amount = sourceAmount(t);
                    if (amount <= 0) continue;
                    resultLoad = load + amount;
                } else {
                    if (load == 0) continue;
                    amount = min(load, -remaining[t]);
                    resultLoad = load - amount;
                }

                int d = abs(x - tasks[t].x) + abs(y - tasks[t].y);
                double score = d * (100.0 + load) + beta * resultLoad;
                if (target == -1 || score < bestScore ||
                    (score == bestScore && (rng() & 1))) {
                    bestScore = score;
                    target = t;
                }
            }

            if (target == -1) return false;

            int tx = tasks[target].x;
            int ty = tasks[target].y;

            auto moveVertical = [&]() {
                while (x != tx) {
                    if (x < tx) {
                        ++x;
                        operations.push_back({'D', 0});
                    } else {
                        --x;
                        operations.push_back({'U', 0});
                    }
                    cost += 100 + load;
                    processCell(false);
                }
            };

            auto moveHorizontal = [&]() {
                while (y != ty) {
                    if (y < ty) {
                        ++y;
                        operations.push_back({'R', 0});
                    } else {
                        --y;
                        operations.push_back({'L', 0});
                    }
                    cost += 100 + load;
                    processCell(false);
                }
            };

            if (verticalFirst) {
                moveVertical();
                moveHorizontal();
            } else {
                moveHorizontal();
                moveVertical();
            }
            processCell(true);

            if (operations.size() > 100000) return false;
        }

        if (remainingNonzero != 0 || load != 0) return false;

        result = std::move(operations);
        resultCost = cost;
        return true;
    }

    vector<Operation> makeFullPlan(const vector<int>& order) const {
        vector<Operation> operations;
        operations.reserve(order.size() * 8);

        int x = 0, y = 0;
        for (int t : order) {
            while (x < tasks[t].x) {
                ++x;
                operations.push_back({'D', 0});
            }
            while (x > tasks[t].x) {
                --x;
                operations.push_back({'U', 0});
            }
            while (y < tasks[t].y) {
                ++y;
                operations.push_back({'R', 0});
            }
            while (y > tasks[t].y) {
                --y;
                operations.push_back({'L', 0});
            }

            if (tasks[t].delta > 0)
                operations.push_back({'+', tasks[t].delta});
            else
                operations.push_back({'-', -tasks[t].delta});
        }
        return operations;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> height(N, vector<int>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            cin >> height[i][j];

    Solver solver(N, std::move(height), 712367821ULL);

    if (solver.m == 0) return 0;

    vector<pair<vector<int>, long long>> candidates;

    auto addCandidate = [&](const vector<int>& order) {
        if ((int)order.size() != solver.m) return;
        long long cost = solver.routeCost(order);
        if (cost >= (1LL << 60)) return;
        candidates.push_back({order, cost});
    };

    const vector<double> betas = {0.0, 1.0, 2.0, 5.0, 10.0, 20.0};
    const vector<double> jitters = {0.0, 50.0};

    for (double beta : betas) {
        for (double jitter : jitters) {
            addCandidate(solver.greedyOrder(beta, jitter, false));
            addCandidate(solver.greedyOrder(beta, jitter, true));
        }
    }

    vector<int> allSources = solver.sourceTasks;
    vector<int> allSinks = solver.sinkTasks;
    vector<int> sourceFirst = solver.nearestOrder(allSources);
    vector<int> sinkPart = solver.nearestOrder(allSinks);
    sourceFirst.insert(sourceFirst.end(), sinkPart.begin(), sinkPart.end());
    addCandidate(sourceFirst);

    addCandidate(solver.repairFeasible(solver.snakeOrder(true)));
    addCandidate(solver.repairFeasible(solver.snakeOrder(false)));

    vector<int> beam = solver.beamOrder(80);
    addCandidate(beam);

    sort(candidates.begin(), candidates.end(),
         [](const auto& a, const auto& b) {
             return a.second < b.second;
         });

    for (int i = 0; i < min(4, (int)candidates.size()); ++i) {
        vector<int> extracted;
        for (int mode = 0; mode < 4; ++mode) {
            if (solver.realizeOrder(
                    candidates[i].first,
                    mode,
                    mode == 1 || mode == 3,
                    mode == 2 || mode == 3,
                    extracted)) {
                addCandidate(extracted);
            }
        }
    }

    sort(candidates.begin(), candidates.end(),
         [](const auto& a, const auto& b) {
             return a.second < b.second;
         });

    vector<int> globalBest = candidates.front().first;
    long long globalBestCost = candidates.front().second;

    vector<int> starts;
    for (int i = 0; i < min(4, (int)candidates.size()); ++i)
        starts.push_back(candidates[i].first);

    if (!beam.empty()) {
        bool exists = false;
        for (const auto& order : starts)
            if (order == beam) exists = true;
        if (!exists && starts.size() < 5) starts.push_back(beam);
    }

    for (const auto& order : starts) {
        solver.anneal(order, 80000, 1400.0, 2.0,
                      globalBest, globalBestCost);
    }

    solver.anneal(globalBest, 180000, 600.0, 1.0,
                  globalBest, globalBestCost);

    vector<int> extracted;
    for (int mode = 0; mode < 4; ++mode) {
        if (solver.realizeOrder(
                globalBest,
                mode,
                mode == 1 || mode == 3,
                mode == 2 || mode == 3,
                extracted)) {
            long long cost = solver.routeCost(extracted);
            if (cost < globalBestCost) {
                globalBestCost = cost;
                globalBest = extracted;
            }
        }
    }

    if (globalBestCost < (1LL << 60)) {
        solver.anneal(globalBest, 60000, 350.0, 1.0,
                      globalBest, globalBestCost);
    }

    vector<Operation> fullOperations = solver.makeFullPlan(globalBest);
    long long fullCost = globalBestCost + solver.baseCost;

    vector<Operation> partialOperations;
    long long partialCost = (1LL << 60);

    const vector<double> partialBetas = {0.0, 0.7, 1.5, 3.0, 6.0, 10.0};

    for (double beta : partialBetas) {
        for (int policy = 0; policy < 2; ++policy) {
            for (int automatic = 0; automatic < 4; ++automatic) {
                vector<Operation> operations;
                long long cost;
                if (solver.generatePartialPlan(
                        beta, policy, automatic, (rng() & 1) != 0,
                        operations, cost) &&
                    cost < partialCost) {
                    partialCost = cost;
                    partialOperations = std::move(operations);
                }
            }
        }
    }

    const vector<Operation>* answer = &fullOperations;
    if (partialCost < fullCost) answer = &partialOperations;

    string output;
    output.reserve(answer->size() * 10);

    for (const Operation& op : *answer) {
        if (op.type == '+' || op.type == '-') {
            output.push_back(op.type);
            output += to_string(op.amount);
        } else {
            output.push_back(op.type);
        }
        output.push_back('\n');
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct FastRNG {
    uint64_t state;
    explicit FastRNG(uint64_t seed) : state(seed) {}
    uint64_t next() {
        uint64_t x = state;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        state = x;
        return x * 2685821657736338717ULL;
    }
    int operator()(int bound) {
        return int(next() % uint64_t(bound));
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto startTime = chrono::steady_clock::now();
    auto deadline = startTime + chrono::milliseconds(1800);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> adj(n);
    vector<pair<int, int>> edges;
    edges.reserve(m);

    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
        edges.push_back({u, v});
    }

    if (m == 0) {
        for (int i = 0; i < n; ++i) {
            if (i) cout << ' ';
            cout << 1;
        }
        cout << '\n';
        return 0;
    }

    FastRNG rng(0x9E3779B97F4A7C15ULL ^ uint64_t(n) * 1000003ULL ^ uint64_t(m));

    // Bipartite graphs already have an optimal two-coloring.
    vector<int> bipartiteColor(n, -1);
    bool bipartite = true;
    for (int s = 0; s < n && bipartite; ++s) {
        if (bipartiteColor[s] != -1) continue;
        queue<int> q;
        bipartiteColor[s] = 0;
        q.push(s);
        while (!q.empty() && bipartite) {
            int v = q.front();
            q.pop();
            for (int u : adj[v]) {
                if (bipartiteColor[u] == -1) {
                    bipartiteColor[u] = bipartiteColor[v] ^ 1;
                    q.push(u);
                } else if (bipartiteColor[u] == bipartiteColor[v]) {
                    bipartite = false;
                    break;
                }
            }
        }
    }

    if (bipartite) {
        for (int i = 0; i < n; ++i) {
            if (i) cout << ' ';
            cout << bipartiteColor[i] + 1;
        }
        cout << '\n';
        return 0;
    }

    vector<int> degree(n);
    for (int v = 0; v < n; ++v) degree[v] = int(adj[v].size());

    auto greedyColoring = [&](bool randomized) {
        vector<int> color(n, -1);
        vector<array<int, 3>> neighborColors(n);
        for (auto &a : neighborColors) a = {0, 0, 0};
        vector<int> saturation(n, 0);
        vector<int> tieRank(n);
        iota(tieRank.begin(), tieRank.end(), 0);
        if (randomized) {
            for (int i = n - 1; i > 0; --i) {
                int j = rng(i + 1);
                swap(tieRank[i], tieRank[j]);
            }
        }

        for (int step = 0; step < n; ++step) {
            int v = -1;
            for (int i = 0; i < n; ++i) {
                if (color[i] != -1) continue;
                if (v == -1 ||
                    saturation[i] > saturation[v] ||
                    (saturation[i] == saturation[v] && degree[i] > degree[v]) ||
                    (saturation[i] == saturation[v] && degree[i] == degree[v] &&
                     (randomized ? tieRank[i] > tieRank[v] : i < v))) {
                    v = i;
                }
            }

            int minConflict = INT_MAX;
            for (int c = 0; c < 3; ++c) {
                minConflict = min(minConflict, neighborColors[v][c]);
            }

            int chosen = -1;
            int bestImpact = INT_MAX;
            int ties = 0;
            for (int c = 0; c < 3; ++c) {
                if (neighborColors[v][c] != minConflict) continue;

                int impact = 0;
                for (int u : adj[v]) {
                    if (color[u] == -1 && neighborColors[u][c] == 0) ++impact;
                }

                if (chosen == -1 || impact < bestImpact) {
                    chosen = c;
                    bestImpact = impact;
                    ties = 1;
                } else if (impact == bestImpact) {
                    ++ties;
                    if (!randomized || rng(ties) == 0) chosen = c;
                }
            }

            color[v] = chosen;
            for (int u : adj[v]) {
                if (color[u] != -1) continue;
                if (neighborColors[u][chosen] == 0) ++saturation[u];
                ++neighborColors[u][chosen];
            }
        }
        return color;
    };

    int bestE = INT_MAX;
    vector<int> bestColor;

    auto conflictsOf = [&](const vector<int> &color) {
        int e = 0;
        for (auto [u, v] : edges) e += (color[u] == color[v]);
        return e;
    };

    auto record = [&](const vector<int> &color, int e) {
        if (e < bestE) {
            bestE = e;
            bestColor = color;
        }
    };

    auto tabuSearch = [&](vector<int> color, int maxStagnation) {
        vector<array<int, 3>> cnt(n);
        for (auto &a : cnt) a = {0, 0, 0};
        for (int v = 0; v < n; ++v) {
            for (int u : adj[v]) ++cnt[v][color[u]];
        }

        vector<array<int, 3>> tabu(n);
        for (auto &a : tabu) a = {0, 0, 0};

        int currentE = conflictsOf(color);
        record(color, currentE);
        if (bestE == 0) return;

        int runBest = currentE;
        int lastImprovement = 0;
        int iteration = 0;

        while (true) {
            ++iteration;
            if ((iteration & 63) == 0 && chrono::steady_clock::now() >= deadline) break;
            if (iteration - lastImprovement > maxStagnation) break;

            int bestDelta = INT_MAX;
            int bestVertex = -1;
            int bestNewColor = -1;
            int conflictingVertices = 0;
            int ties = 0;

            for (int v = 0; v < n; ++v) {
                int oldColor = color[v];
                if (cnt[v][oldColor] == 0) continue;
                ++conflictingVertices;

                for (int c = 0; c < 3; ++c) {
                    if (c == oldColor) continue;
                    int delta = cnt[v][c] - cnt[v][oldColor];
                    bool isTabu = tabu[v][c] > iteration;
                    if (isTabu && currentE + delta >= bestE) continue;

                    if (delta < bestDelta) {
                        bestDelta = delta;
                        bestVertex = v;
                        bestNewColor = c;
                        ties = 1;
                    } else if (delta == bestDelta) {
                        ++ties;
                        if (rng(ties) == 0) {
                            bestVertex = v;
                            bestNewColor = c;
                        }
                    }
                }
            }

            if (bestVertex == -1) {
                for (auto &a : tabu) a = {0, 0, 0};
                continue;
            }

            int v = bestVertex;
            int oldColor = color[v];
            int newColor = bestNewColor;

            for (int u : adj[v]) {
                --cnt[u][oldColor];
                ++cnt[u][newColor];
            }
            color[v] = newColor;
            currentE += bestDelta;

            int tenure = 5 + rng(10) + int(0.6 * conflictingVertices);
            tabu[v][oldColor] = iteration + tenure;

            if (currentE < runBest) {
                runBest = currentE;
                lastImprovement = iteration;
            }
            if (currentE < bestE) {
                bestE = currentE;
                bestColor = color;
                if (bestE == 0) return;
            }
        }
    };

    vector<int> initial = greedyColoring(false);
    record(initial, conflictsOf(initial));

    int run = 0;
    while (bestE > 0 && chrono::steady_clock::now() < deadline) {
        vector<int> current;

        if (run == 0) {
            current = initial;
        } else if (run % 4 == 1) {
            current = bestColor;
            int changes = max(2, n / 25);
            for (int k = 0; k < changes; ++k) {
                int v = rng(n);
                int c = rng(2);
                if (c >= current[v]) ++c;
                current[v] = c;
            }
        } else if (run % 4 == 2) {
            current = greedyColoring(true);
        } else if (run % 4 == 3) {
            current = bestColor;
        } else {
            current.resize(n);
            for (int v = 0; v < n; ++v) current[v] = rng(3);
        }

        record(current, conflictsOf(current));
        if (bestE == 0) break;

        tabuSearch(current, 100000);
        ++run;
    }

    for (int i = 0; i < n; ++i) {
        if (i) cout << ' ';
        cout << bestColor[i] + 1;
    }
    cout << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto startTime = chrono::steady_clock::now();
    const double TIME_LIMIT = 1.80;

    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    if (m == 0) {
        for (int i = 0; i < n; ++i) {
            if (i) cout << ' ';
            cout << 1;
        }
        cout << '\n';
        return 0;
    }

    mt19937 rng(712367821);
    vector<int> bestColor(n, 0);
    int bestE = INT_MAX;

    auto elapsed = [&]() {
        return chrono::duration<double>(chrono::steady_clock::now() - startTime).count();
    };

    auto dsatur = [&](bool randomized) {
        vector<int> col(n, -1), sat(n, 0), used(3, 0);
        vector<array<int, 3>> cnt(n);
        for (auto &a : cnt) a = {0, 0, 0};

        for (int step = 0; step < n; ++step) {
            int v = -1;
            for (int i = 0; i < n; ++i) {
                if (col[i] != -1) continue;
                if (v == -1) {
                    v = i;
                    continue;
                }
                int si = __builtin_popcount((unsigned)sat[i]);
                int sv = __builtin_popcount((unsigned)sat[v]);
                if (si > sv || (si == sv && adj[i].size() > adj[v].size())) {
                    v = i;
                } else if (randomized && si == sv && adj[i].size() == adj[v].size()
                           && (rng() & 1)) {
                    v = i;
                }
            }

            int c = 0, ties = 1;
            for (int k = 1; k < 3; ++k) {
                if (cnt[v][k] < cnt[v][c] ||
                    (cnt[v][k] == cnt[v][c] && used[k] < used[c])) {
                    c = k;
                    ties = 1;
                } else if (randomized && cnt[v][k] == cnt[v][c] && used[k] == used[c]) {
                    ++ties;
                    if (rng() % ties == 0) c = k;
                }
            }

            col[v] = c;
            ++used[c];
            for (int u : adj[v]) {
                if (col[u] == -1) {
                    ++cnt[u][c];
                    sat[u] |= 1 << c;
                }
            }
        }
        return col;
    };

    vector<array<int, 3>> cnt(n);
    vector<array<int, 3>> tabu(n);
    int restart = 0;

    while (true) {
        vector<int> col;
        if (restart == 0) {
            col = dsatur(false);
        } else if (restart % 4 == 1) {
            col = dsatur(true);
        } else if (restart % 4 == 2) {
            col = bestColor;
            int changes = max(2, n / 12);
            for (int i = 0; i < changes; ++i) {
                int v = rng() % n;
                col[v] = rng() % 3;
            }
        } else if (restart % 4 == 3) {
            col.resize(n);
            for (int &c : col) c = rng() % 3;
        } else {
            vector<int> order(n);
            iota(order.begin(), order.end(), 0);
            shuffle(order.begin(), order.end(), rng);
            col.assign(n, -1);
            for (int v : order) {
                int cc[3] = {0, 0, 0};
                for (int u : adj[v]) if (col[u] != -1) ++cc[col[u]];
                int c = 0, ties = 1;
                for (int k = 1; k < 3; ++k) {
                    if (cc[k] < cc[c]) {
                        c = k;
                        ties = 1;
                    } else if (cc[k] == cc[c]) {
                        ++ties;
                        if (rng() % ties == 0) c = k;
                    }
                }
                col[v] = c;
            }
        }

        int currentE = 0;
        for (int v = 0; v < n; ++v) {
            cnt[v] = {0, 0, 0};
            tabu[v] = {0, 0, 0};
        }
        for (int v = 0; v < n; ++v) {
            for (int u : adj[v]) ++cnt[v][col[u]];
            currentE += cnt[v][col[v]];
        }
        currentE /= 2;

        if (currentE < bestE) {
            bestE = currentE;
            bestColor = col;
            if (bestE == 0) break;
        }

        int noImprove = 0;
        int iteration = 0;
        const int restartLimit = 12000 + 8 * n;

        while (noImprove < restartLimit) {
            if ((iteration & 127) == 0 && elapsed() > TIME_LIMIT) break;
            ++iteration;

            int moveV = -1, moveC = -1, moveDelta = INT_MAX;
            int ties = 0, conflicting = 0;

            for (int v = 0; v < n; ++v) {
                int old = col[v];
                if (cnt[v][old] == 0) continue;
                ++conflicting;
                for (int c = 0; c < 3; ++c) {
                    if (c == old) continue;
                    int delta = cnt[v][c] - cnt[v][old];
                    if (tabu[v][c] > iteration && currentE + delta >= bestE) continue;
                    if (delta < moveDelta) {
                        moveDelta = delta;
                        moveV = v;
                        moveC = c;
                        ties = 1;
                    } else if (delta == moveDelta) {
                        ++ties;
                        if (rng() % ties == 0) {
                            moveV = v;
                            moveC = c;
                        }
                    }
                }
            }

            if (moveV == -1) {
                moveDelta = INT_MAX;
                ties = 0;
                for (int v = 0; v < n; ++v) {
                    int old = col[v];
                    if (cnt[v][old] == 0) continue;
                    for (int c = 0; c < 3; ++c) {
                        if (c == old) continue;
                        int delta = cnt[v][c] - cnt[v][old];
                        if (delta < moveDelta) {
                            moveDelta = delta;
                            moveV = v;
                            moveC = c;
                            ties = 1;
                        } else if (delta == moveDelta) {
                            ++ties;
                            if (rng() % ties == 0) {
                                moveV = v;
                                moveC = c;
                            }
                        }
                    }
                }
            }

            if (moveV == -1) break;

            int old = col[moveV];
            col[moveV] = moveC;
            currentE += moveDelta;
            for (int u : adj[moveV]) {
                --cnt[u][old];
                ++cnt[u][moveC];
            }

            int tenure = 5 + (int)(rng() % 10) + (int)(0.6 * conflicting);
            tabu[moveV][old] = iteration + tenure;

            if (currentE < bestE) {
                bestE = currentE;
                bestColor = col;
                noImprove = 0;
                if (bestE == 0) break;
            } else {
                ++noImprove;
            }
        }

        if (bestE == 0 || elapsed() > TIME_LIMIT) break;
        ++restart;
    }

    for (int i = 0; i < n; ++i) {
        if (i) cout << ' ';
        cout << bestColor[i] + 1;
    }
    cout << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1005;

int n, m;
vector<int> adj[MAXN];
int colorArr[MAXN], bestColor[MAXN];
int cnt[MAXN][3];
int tabuArr[MAXN][3];
int E, bestE;

int initCountsForColor() {
    memset(cnt, 0, sizeof(cnt));
    for (int v = 0; v < n; ++v) {
        for (int u : adj[v]) {
            ++cnt[v][colorArr[u]];
        }
    }
    int e = 0;
    for (int v = 0; v < n; ++v) {
        e += cnt[v][colorArr[v]];
    }
    return e / 2;
}

vector<int> greedyColoring(bool randomTie) {
    vector<int> col(n, -1);
    vector<array<int, 3>> gcnt(n);
    for (int i = 0; i < n; ++i) gcnt[i] = {0, 0, 0};
    vector<unsigned char> mask(n, 0);
    vector<int> deg(n);
    for (int v = 0; v < n; ++v) deg[v] = (int)adj[v].size();

    for (int step = 0; step < n; ++step) {
        int best = -1;
        int bestSat = -1;
        int bestDeg = -1;

        for (int v = 0; v < n; ++v) {
            if (col[v] != -1) continue;
            int sat = __builtin_popcount((unsigned)mask[v]);
            if (sat > bestSat ||
                (sat == bestSat && (deg[v] > bestDeg ||
                 (randomTie && deg[v] == bestDeg && (rand() & 1))))) {
                bestSat = sat;
                bestDeg = deg[v];
                best = v;
            }
        }

        int minConf = 1000000000;
        int choices[3];
        int num = 0;
        for (int c = 0; c < 3; ++c) {
            if (gcnt[best][c] < minConf) {
                minConf = gcnt[best][c];
                num = 0;
                choices[num++] = c;
            } else if (gcnt[best][c] == minConf) {
                choices[num++] = c;
            }
        }

        int chosen;
        if (randomTie) chosen = choices[rand() % num];
        else chosen = choices[0];

        col[best] = chosen;

        for (int v : adj[best]) {
            if (col[v] == -1) {
                if (gcnt[v][chosen] == 0) {
                    mask[v] |= (1 << chosen);
                }
                ++gcnt[v][chosen];
            }
        }
    }

    return col;
}

int evaluate(const vector<int>& col) {
    int e = 0;
    for (int v = 0; v < n; ++v) {
        for (int u : adj[v]) {
            if (v < u && col[v] == col[u]) ++e;
        }
    }
    return e;
}

bool checkBipartite(vector<int>& res) {
    res.assign(n, -1);
    queue<int> q;

    for (int s = 0; s < n; ++s) {
        if (res[s] != -1) continue;
        res[s] = 0;
        q.push(s);

        while (!q.empty()) {
            int v = q.front();
            q.pop();

            for (int u : adj[v]) {
                if (res[u] == -1) {
                    res[u] = res[v] ^ 1;
                    q.push(u);
                } else if (res[u] == res[v]) {
                    return false;
                }
            }
        }
    }

    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    srand((unsigned)chrono::steady_clock::now().time_since_epoch().count());

    cin >> n >> m;

    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    if (m == 0) {
        for (int i = 0; i < n; ++i) {
            if (i) cout << ' ';
            cout << 1;
        }
        cout << '\n';
        return 0;
    }

    vector<int> bip;
    if (checkBipartite(bip)) {
        for (int i = 0; i < n; ++i) {
            if (i) cout << ' ';
            cout << (bip[i] + 1);
        }
        cout << '\n';
        return 0;
    }

    bestE = 1000000000;
    vector<int> bestVec;

    const int greedyRuns = 30;
    for (int r = 0; r < greedyRuns; ++r) {
        vector<int> col = greedyColoring(r > 0);
        int e = evaluate(col);

        if (e < bestE) {
            bestE = e;
            bestVec = col;
        }

        if (bestE == 0) break;
    }

    if (bestE == 0) {
        for (int i = 0; i < n; ++i) {
            if (i) cout << ' ';
            cout << bestVec[i] + 1;
        }
        cout << '\n';
        return 0;
    }

    for (int v = 0; v < n; ++v) colorArr[v] = bestVec[v];

    E = initCountsForColor();
    bestE = E;

    for (int v = 0; v < n; ++v) bestColor[v] = colorArr[v];

    memset(tabuArr, 0, sizeof(tabuArr));

    int iter = 0;
    int noImprove = 0;
    const int maxNoImprove = 1000 + n;

    auto start = chrono::steady_clock::now();
    const double timeLimit = 1.5;

    while (true) {
        if ((iter & 127) == 0) {
            auto now = chrono::steady_clock::now();
            double elapsed = chrono::duration<double>(now - start).count();
            if (elapsed > timeLimit) break;
        }

        int bestDelta = 1000000000;
        int bestV = -1;
        int bestC = -1;

        for (int v = 0; v < n; ++v) {
            int old = colorArr[v];
            int base = cnt[v][old];

            for (int c = 0; c < 3; ++c) {
                if (c == old) continue;

                int delta = cnt[v][c] - base;

                if (tabuArr[v][c] > iter && E + delta >= bestE) continue;

                if (delta < bestDelta ||
                    (delta == bestDelta && (rand() & 1))) {
                    bestDelta = delta;
                    bestV = v;
                    bestC = c;
                }
            }
        }

        if (bestV == -1) {
            bestV = rand() % n;
            bestC = (colorArr[bestV] + 1 + rand() % 2) % 3;
            bestDelta = cnt[bestV][bestC] - cnt[bestV][colorArr[bestV]];
        }

        int oldc = colorArr[bestV];

        E += bestDelta;
        colorArr[bestV] = bestC;

        for (int u : adj[bestV]) {
            --cnt[u][oldc];
            ++cnt[u][bestC];
        }

        int tenure = 7 + rand() % 10;
        tenure += noImprove / 500;
        if (tenure > 50) tenure = 50;

        tabuArr[bestV][oldc] = iter + tenure;
        ++iter;

        if (E < bestE) {
            bestE = E;
            for (int v = 0; v < n; ++v) bestColor[v] = colorArr[v];
            noImprove = 0;

            if (bestE == 0) break;
        } else {
            ++noImprove;
        }

        if (noImprove > maxNoImprove) {
            for (int v = 0; v < n; ++v) colorArr[v] = bestColor[v];

            E = initCountsForColor();
            memset(tabuArr, 0, sizeof(tabuArr));

            int K = max(1, n / 10);
            for (int k = 0; k < K; ++k) {
                int v = rand() % n;
                int oldc2 = colorArr[v];
                int newc = rand() % 3;

                if (newc == oldc2) newc = (newc + 1 + rand() % 2) % 3;

                int delta = cnt[v][newc] - cnt[v][oldc2];
                E += delta;
                colorArr[v] = newc;

                for (int u : adj[v]) {
                    --cnt[u][oldc2];
                    ++cnt[u][newc];
                }
            }

            noImprove = 0;

            if (rand() % 5 == 0) {
                for (int v = 0; v < n; ++v) colorArr[v] = rand() % 3;
                E = initCountsForColor();
                memset(tabuArr, 0, sizeof(tabuArr));
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        if (i) cout << ' ';
        cout << bestColor[i] + 1;
    }
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct FastScanner {
    static constexpr int SIZE = 1 << 16;
    char buffer[SIZE];
    int pos = 0, len = 0;

    inline char getChar() {
        if (pos == len) {
            len = (int)fread(buffer, 1, SIZE, stdin);
            pos = 0;
            if (len == 0) return 0;
        }
        return buffer[pos++];
    }

    bool readInt(int &x) {
        char c;
        do {
            c = getChar();
            if (!c) return false;
        } while (c <= ' ');

        x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = getChar();
        }
        return true;
    }
};

struct RNG {
    uint64_t state;

    explicit RNG(uint64_t seed) : state(seed) {}

    inline uint64_t next() {
        uint64_t z = (state += 0x9e3779b97f4a7c15ULL);
        z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
        z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
        return z ^ (z >> 31);
    }

    inline int integer(int n) {
        return n <= 1 ? 0 : (int)(next() % (uint64_t)n);
    }
};

class CoreSolver {
private:
    int n;
    vector<vector<int>> graph;
    vector<unsigned char> adjacent;
    int edgeCount = 0;

    vector<int> color, bestColor;
    vector<array<int, 3>> neighborCount;
    vector<unsigned char> badFlag;
    vector<int> badVertices;
    vector<int> badPosition;
    vector<array<int, 3>> tabuUntil;

    int conflicts = 0;
    int bestConflicts = INT_MAX;

    vector<int> exactColor;
    vector<array<int, 3>> forbidden;
    long long exactLimit = 0;
    long long exactUsed = 0;
    bool exactAborted = false;

    RNG rng;

    int computeConflicts(const vector<int> &c) const {
        int result = 0;
        for (int u = 0; u < n; ++u) {
            for (int v : graph[u]) {
                if (v > u && c[u] == c[v]) ++result;
            }
        }
        return result;
    }

    bool findBipartiteColoring() {
        color.assign(n, -1);
        vector<int> queue;
        queue.reserve(n);

        for (int root = 0; root < n; ++root) {
            if (color[root] != -1) continue;
            color[root] = 0;
            queue.clear();
            queue.push_back(root);

            for (size_t head = 0; head < queue.size(); ++head) {
                int u = queue[head];
                for (int v : graph[u]) {
                    if (color[v] == -1) {
                        color[v] = color[u] ^ 1;
                        queue.push_back(v);
                    } else if (color[v] == color[u]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    void greedyColoring() {
        bestConflicts = INT_MAX;

        for (int variant = 0; variant < 6; ++variant) {
            color.assign(n, -1);
            vector<array<int, 3>> same(n);
            for (auto &a : same) a.fill(0);
            vector<int> mask(n, 0);
            array<int, 3> classSize{0, 0, 0};
            vector<int> candidates;
            candidates.reserve(n);

            for (int step = 0; step < n; ++step) {
                int bestSaturation = -1;
                int bestDegree = -1;
                candidates.clear();

                for (int v = 0; v < n; ++v) {
                    if (color[v] != -1) continue;
                    int saturation = __builtin_popcount((unsigned)mask[v]);
                    int degree = (int)graph[v].size();

                    if (saturation > bestSaturation ||
                        (saturation == bestSaturation && degree > bestDegree)) {
                        bestSaturation = saturation;
                        bestDegree = degree;
                        candidates.clear();
                    }
                    if (saturation == bestSaturation && degree == bestDegree) {
                        candidates.push_back(v);
                    }
                }

                int v;
                if (variant % 3 == 0) {
                    v = candidates.front();
                } else {
                    v = candidates[rng.integer((int)candidates.size())];
                }

                int minimumSame = INT_MAX;
                for (int c = 0; c < 3; ++c) {
                    minimumSame = min(minimumSame, same[v][c]);
                }

                array<int, 3> choices{0, 0, 0};
                int numberOfChoices = 0;

                if (variant & 1) {
                    for (int c = 0; c < 3; ++c) {
                        if (same[v][c] == minimumSame) {
                            choices[numberOfChoices++] = c;
                        }
                    }
                } else {
                    int minimumClassSize = INT_MAX;
                    for (int c = 0; c < 3; ++c) {
                        if (same[v][c] == minimumSame) {
                            minimumClassSize = min(minimumClassSize, classSize[c]);
                        }
                    }
                    for (int c = 0; c < 3; ++c) {
                        if (same[v][c] == minimumSame &&
                            classSize[c] == minimumClassSize) {
                            choices[numberOfChoices++] = c;
                        }
                    }
                }

                int chosenColor = choices[rng.integer(numberOfChoices)];
                color[v] = chosenColor;
                ++classSize[chosenColor];

                for (int u : graph[v]) {
                    if (color[u] == -1) {
                        mask[u] |= 1 << chosenColor;
                        ++same[u][chosenColor];
                    }
                }
            }

            int current = computeConflicts(color);
            if (current < bestConflicts) {
                bestConflicts = current;
                bestColor = color;
            }
        }
    }

    bool exactDFS(int remaining) {
        if (exactUsed >= exactLimit) {
            exactAborted = true;
            return false;
        }
        ++exactUsed;

        if (remaining == 0) return true;

        int chosen = -1;
        int minimumAvailable = 4;
        int maximumDegree = -1;

        for (int v = 0; v < n; ++v) {
            if (exactColor[v] != -1) continue;

            int available = 0;
            for (int c = 0; c < 3; ++c) {
                if (forbidden[v][c] == 0) ++available;
            }

            if (available == 0) return false;

            int degree = (int)graph[v].size();
            if (available < minimumAvailable ||
                (available == minimumAvailable && degree > maximumDegree)) {
                chosen = v;
                minimumAvailable = available;
                maximumDegree = degree;
            }
        }

        array<int, 3> order{0, 1, 2};
        int shift = rng.integer(3);
        for (int k = 0; k < 3; ++k) {
            int c = order[(k + shift) % 3];
            if (forbidden[chosen][c] != 0) continue;

            exactColor[chosen] = c;
            for (int u : graph[chosen]) {
                if (exactColor[u] == -1) ++forbidden[u][c];
            }

            if (exactDFS(remaining - 1)) return true;

            for (int u : graph[chosen]) {
                if (exactColor[u] == -1) --forbidden[u][c];
            }
            exactColor[chosen] = -1;

            if (exactAborted) return false;
        }

        return false;
    }

    bool attemptExactColoring(long long &globalBudget,
                              long long allowance,
                              vector<int> &answer) {
        if (globalBudget <= 0 || allowance <= 0) return false;

        exactLimit = min(globalBudget, allowance);
        exactUsed = 0;
        exactAborted = false;
        exactColor.assign(n, -1);
        forbidden.assign(n, {});
        for (auto &a : forbidden) a.fill(0);

        int root = 0;
        for (int v = 1; v < n; ++v) {
            if (graph[v].size() > graph[root].size()) root = v;
        }

        exactColor[root] = 0;
        for (int u : graph[root]) {
            if (exactColor[u] == -1) ++forbidden[u][0];
        }

        bool success = exactDFS(n - 1);
        globalBudget -= min(globalBudget, exactUsed);

        if (success) answer = exactColor;
        return success;
    }

    void rebuildBadVertices() {
        badFlag.assign(n, 0);
        badPosition.assign(n, -1);
        badVertices.clear();
        badVertices.reserve(n);

        for (int v = 0; v < n; ++v) {
            if (neighborCount[v][color[v]] > 0) {
                badFlag[v] = 1;
                badPosition[v] = (int)badVertices.size();
                badVertices.push_back(v);
            }
        }
    }

    void rebuildState() {
        for (int v = 0; v < n; ++v) {
            neighborCount[v].fill(0);
            for (int u : graph[v]) {
                ++neighborCount[v][color[u]];
            }
        }

        conflicts = 0;
        for (int v = 0; v < n; ++v) {
            conflicts += neighborCount[v][color[v]];
        }
        conflicts /= 2;

        rebuildBadVertices();
    }

    inline void refreshBad(int v) {
        bool nowBad = neighborCount[v][color[v]] > 0;
        if (nowBad == (bool)badFlag[v]) return;

        badFlag[v] = nowBad;
        if (nowBad) {
            badPosition[v] = (int)badVertices.size();
            badVertices.push_back(v);
        } else {
            int p = badPosition[v];
            int last = badVertices.back();
            badVertices[p] = last;
            badPosition[last] = p;
            badVertices.pop_back();
            badPosition[v] = -1;
        }
    }

    inline void applyMove(int v, int newColor) {
        int oldColor = color[v];
        if (oldColor == newColor) return;

        conflicts += neighborCount[v][newColor] - neighborCount[v][oldColor];
        color[v] = newColor;
        refreshBad(v);

        for (int u : graph[v]) {
            --neighborCount[u][oldColor];
            ++neighborCount[u][newColor];
            refreshBad(u);
        }
    }

    inline int swapDelta(int u, int v) const {
        int a = color[u];
        int b = color[v];
        int delta = neighborCount[u][b] - neighborCount[u][a]
                  + neighborCount[v][a] - neighborCount[v][b];
        if (adjacent[u * n + v]) delta -= 2;
        return delta;
    }

    inline void applySwap(int u, int v) {
        int a = color[u];
        int b = color[v];
        if (a == b) return;

        conflicts += swapDelta(u, v);
        color[u] = b;
        color[v] = a;

        for (int x : graph[u]) {
            --neighborCount[x][a];
            ++neighborCount[x][b];
        }
        for (int x : graph[v]) {
            --neighborCount[x][b];
            ++neighborCount[x][a];
        }

        rebuildBadVertices();
    }

    inline void saveBestIfBetter() {
        if (conflicts < bestConflicts) {
            bestConflicts = conflicts;
            bestColor = color;
        }
    }

    void restoreBest() {
        color = bestColor;
        rebuildState();
    }

    void improveVertices(int maximumMoves) {
        for (int step = 0; step < maximumMoves; ++step) {
            int bestDelta = 0;
            int chosenVertex = -1;
            int chosenColor = -1;
            uint64_t bestKey = 0;

            for (int v : badVertices) {
                int current = color[v];
                for (int c = 0; c < 3; ++c) {
                    if (c == current) continue;
                    int delta = neighborCount[v][c] - neighborCount[v][current];
                    if (delta < bestDelta) {
                        bestDelta = delta;
                        chosenVertex = v;
                        chosenColor = c;
                        bestKey = rng.next();
                    } else if (delta == bestDelta) {
                        uint64_t key = rng.next();
                        if (key > bestKey) {
                            bestKey = key;
                            chosenVertex = v;
                            chosenColor = c;
                        }
                    }
                }
            }

            if (chosenVertex == -1) break;
            applyMove(chosenVertex, chosenColor);
            saveBestIfBetter();
        }
    }

    void improveSwaps(int maximumMoves) {
        for (int step = 0; step < maximumMoves; ++step) {
            int bestDelta = 0;
            int chosenU = -1;
            int chosenV = -1;
            uint64_t bestKey = 0;

            for (int u = 0; u < n; ++u) {
                int a = color[u];
                for (int v = u + 1; v < n; ++v) {
                    int b = color[v];
                    if (a == b) continue;

                    int delta = neighborCount[u][b] - neighborCount[u][a]
                              + neighborCount[v][a] - neighborCount[v][b];
                    if (adjacent[u * n + v]) delta -= 2;

                    if (delta < bestDelta) {
                        bestDelta = delta;
                        chosenU = u;
                        chosenV = v;
                        bestKey = rng.next();
                    } else if (delta == bestDelta) {
                        uint64_t key = rng.next();
                        if (key > bestKey) {
                            bestKey = key;
                            chosenU = u;
                            chosenV = v;
                        }
                    }
                }
            }

            if (chosenU == -1) break;
            applySwap(chosenU, chosenV);
            saveBestIfBetter();
        }
    }

    void perturb() {
        int numberOfSwaps = 2 + n / 100;

        for (int k = 0; k < numberOfSwaps; ++k) {
            int u = rng.integer(n);
            int v = -1;
            for (int attempt = 0; attempt < 20; ++attempt) {
                v = rng.integer(n);
                if (u != v && color[u] != color[v]) break;
            }
            if (u != v && color[u] != color[v]) {
                applySwap(u, v);
                saveBestIfBetter();
            }
        }

        int selectedCount = min(n, max(2, n / 25));
        vector<int> selected;
        vector<unsigned char> marked(n, 0);
        selected.reserve(selectedCount);

        if (!badVertices.empty()) {
            int v = badVertices[rng.integer((int)badVertices.size())];
            selected.push_back(v);
            marked[v] = 1;
        }

        while ((int)selected.size() < selectedCount) {
            int v = rng.integer(n);
            if (!marked[v]) {
                marked[v] = 1;
                selected.push_back(v);
            }
        }

        for (int v : selected) {
            int c = rng.integer(3);
            if (c == color[v]) c = (c + 1) % 3;
            applyMove(v, c);
            saveBestIfBetter();
        }

        for (int i = (int)selected.size() - 1; i > 0; --i) {
            int j = rng.integer(i + 1);
            swap(selected[i], selected[j]);
        }

        for (int v : selected) {
            int minimum = INT_MAX;
            for (int c = 0; c < 3; ++c) {
                minimum = min(minimum, neighborCount[v][c]);
            }

            array<int, 3> choices{0, 0, 0};
            int numberOfChoices = 0;
            for (int c = 0; c < 3; ++c) {
                if (neighborCount[v][c] == minimum) {
                    choices[numberOfChoices++] = c;
                }
            }

            int c = choices[rng.integer(numberOfChoices)];
            if (c != color[v]) {
                applyMove(v, c);
                saveBestIfBetter();
            }
        }
    }

    void optimize(int iterationAllowance) {
        restoreBest();
        tabuUntil.resize(n);
        for (auto &a : tabuUntil) a.fill(0);

        int phaseLength = max(400, min(8000, 8 * n));
        int phaseBest = bestConflicts;

        for (int iteration = 0;
             iteration < iterationAllowance && bestConflicts > 0;
             ++iteration) {
            if (badVertices.empty()) break;

            int anyDelta = INT_MAX;
            int anyVertex = -1;
            int anyColor = -1;
            uint64_t anyKey = 0;

            int allowedDelta = INT_MAX;
            int allowedVertex = -1;
            int allowedColor = -1;
            uint64_t allowedKey = 0;
            bool haveAllowed = false;

            for (int v : badVertices) {
                int current = color[v];
                for (int c = 0; c < 3; ++c) {
                    if (c == current) continue;
                    int delta = neighborCount[v][c] - neighborCount[v][current];

                    if (delta < anyDelta) {
                        anyDelta = delta;
                        anyVertex = v;
                        anyColor = c;
                        anyKey = rng.next();
                    } else if (delta == anyDelta) {
                        uint64_t key = rng.next();
                        if (key > anyKey) {
                            anyKey = key;
                            anyVertex = v;
                            anyColor = c;
                        }
                    }

                    bool isTabu = tabuUntil[v][c] > iteration;
                    bool aspiration = conflicts + delta < bestConflicts;
                    if (isTabu && !aspiration) continue;

                    if (delta < allowedDelta) {
                        allowedDelta = delta;
                        allowedVertex = v;
                        allowedColor = c;
                        allowedKey = rng.next();
                        haveAllowed = true;
                    } else if (delta == allowedDelta) {
                        uint64_t key = rng.next();
                        if (key > allowedKey) {
                            allowedKey = key;
                            allowedVertex = v;
                            allowedColor = c;
                        }
                    }
                }
            }

            int selectedDelta = haveAllowed ? allowedDelta : anyDelta;
            int selectedVertex = haveAllowed ? allowedVertex : anyVertex;
            int selectedColor = haveAllowed ? allowedColor : anyColor;
            bool useSwap = false;
            int swapU = -1;
            int swapV = -1;

            if ((iteration & 7) == 7 && badVertices.size() >= 2) {
                int bestSwapDelta = INT_MAX;
                uint64_t bestSwapKey = 0;

                for (int sample = 0; sample < 32; ++sample) {
                    int u = badVertices[rng.integer((int)badVertices.size())];
                    int v;
                    if (rng.next() & 1ULL) {
                        v = badVertices[rng.integer((int)badVertices.size())];
                    } else {
                        v = rng.integer(n);
                    }

                    if (u == v || color[u] == color[v]) continue;
                    int delta = swapDelta(u, v);

                    if (delta < bestSwapDelta) {
                        bestSwapDelta = delta;
                        bestSwapKey = rng.next();
                        swapU = u;
                        swapV = v;
                    } else if (delta == bestSwapDelta) {
                        uint64_t key = rng.next();
                        if (key > bestSwapKey) {
                            bestSwapKey = key;
                            swapU = u;
                            swapV = v;
                        }
                    }
                }

                if (swapU != -1 &&
                    (bestSwapDelta < selectedDelta ||
                     (bestSwapDelta == selectedDelta && (rng.next() & 1ULL)))) {
                    useSwap = true;
                    selectedDelta = bestSwapDelta;
                }
            }

            int tenure = 8 + rng.integer(8);

            if (useSwap) {
                int oldU = color[swapU];
                int oldV = color[swapV];
                applySwap(swapU, swapV);
                tabuUntil[swapU][oldU] = iteration + tenure;
                tabuUntil[swapV][oldV] = iteration + tenure;
            } else {
                int oldColor = color[selectedVertex];
                applyMove(selectedVertex, selectedColor);
                tabuUntil[selectedVertex][oldColor] = iteration + tenure;
            }

            saveBestIfBetter();

            if ((iteration + 1) % phaseLength == 0) {
                improveVertices(60);
                improveSwaps(2);
                saveBestIfBetter();

                if (bestConflicts >= phaseBest) {
                    restoreBest();
                    for (auto &a : tabuUntil) a.fill(0);
                    perturb();
                    saveBestIfBetter();
                }
                phaseBest = bestConflicts;
            }
        }

        restoreBest();
        for (int round = 0; round < 5; ++round) {
            int before = bestConflicts;
            improveVertices(200);
            improveSwaps(8);
            if (bestConflicts == before) break;
        }
        saveBestIfBetter();
    }

public:
    CoreSolver(vector<vector<int>> g, uint64_t seed)
        : n((int)g.size()), graph(std::move(g)), rng(seed) {
        adjacent.assign((size_t)n * n, 0);
        edgeCount = 0;
        for (int u = 0; u < n; ++u) {
            for (int v : graph[u]) {
                if (!adjacent[u * n + v]) {
                    adjacent[u * n + v] = 1;
                    adjacent[v * n + u] = 1;
                    ++edgeCount;
                }
            }
        }
        edgeCount /= 2;
        neighborCount.resize(n);
    }

    vector<int> solve(long long &globalExactBudget,
                      long long exactAllowance,
                      int iterationAllowance) {
        if (n == 0) return {};

        if (edgeCount == (long long)n * (n - 1) / 2) {
            vector<int> answer(n);
            for (int v = 0; v < n; ++v) answer[v] = v % 3;
            return answer;
        }

        if (findBipartiteColoring()) return color;

        greedyColoring();
        if (bestConflicts == 0) return bestColor;

        vector<int> exactAnswer;
        if (attemptExactColoring(globalExactBudget, exactAllowance, exactAnswer)) {
            return exactAnswer;
        }

        restoreBest();
        improveVertices(100);
        improveSwaps(8);
        saveBestIfBetter();

        optimize(iterationAllowance);
        return bestColor;
    }
};

int main() {
    FastScanner scanner;

    int n, m;
    if (!scanner.readInt(n)) return 0;
    scanner.readInt(m);

    vector<vector<int>> graph(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        scanner.readInt(u);
        scanner.readInt(v);
        --u;
        --v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    vector<int> degree(n);
    vector<unsigned char> removed(n, 0);
    vector<int> removalOrder;
    removalOrder.reserve(n);

    for (int v = 0; v < n; ++v) degree[v] = (int)graph[v].size();

    vector<int> queue;
    queue.reserve(n);
    for (int v = 0; v < n; ++v) {
        if (degree[v] < 3) queue.push_back(v);
    }

    for (size_t head = 0; head < queue.size(); ++head) {
        int v = queue[head];
        if (removed[v]) continue;

        removed[v] = 1;
        removalOrder.push_back(v);

        for (int u : graph[v]) {
            if (!removed[u]) {
                --degree[u];
                if (degree[u] == 2) queue.push_back(u);
            }
        }
    }

    vector<unsigned char> visited(n, 0);
    vector<vector<int>> coreComponents;

    for (int root = 0; root < n; ++root) {
        if (removed[root] || visited[root]) continue;

        vector<int> component;
        component.push_back(root);
        visited[root] = 1;

        for (size_t head = 0; head < component.size(); ++head) {
            int v = component[head];
            for (int u : graph[v]) {
                if (!removed[u] && !visited[u]) {
                    visited[u] = 1;
                    component.push_back(u);
                }
            }
        }
        coreComponents.push_back(std::move(component));
    }

    sort(coreComponents.begin(), coreComponents.end(),
         [](const vector<int> &a, const vector<int> &b) {
             return a.size() < b.size();
         });

    int totalCoreVertices = 0;
    for (const auto &component : coreComponents) {
        totalCoreVertices += (int)component.size();
    }

    vector<int> answer(n, -1);
    long long exactBudget = 300000;
    const long long totalLocalIterations = 120000;

    for (size_t componentIndex = 0;
         componentIndex < coreComponents.size();
         ++componentIndex) {
        const auto &component = coreComponents[componentIndex];
        int size = (int)component.size();

        vector<int> localIndex(n, -1);
        for (int i = 0; i < size; ++i) {
            localIndex[component[i]] = i;
        }

        vector<vector<int>> localGraph(size);
        for (int i = 0; i < size; ++i) {
            int v = component[i];
            for (int u : graph[v]) {
                if (!removed[u] && localIndex[u] != -1) {
                    localGraph[i].push_back(localIndex[u]);
                }
            }
        }

        long long exactAllowance = 100000;
        if (!coreComponents.empty()) {
            long long remainingComponents =
                (long long)coreComponents.size() - (long long)componentIndex;
            exactAllowance = min(exactAllowance,
                                 max(5000LL, exactBudget / remainingComponents));
        }

        int localAllowance = 3000;
        if (totalCoreVertices > 0) {
            localAllowance = (int)min(
                120000LL,
                max(3000LL, totalLocalIterations * size / totalCoreVertices)
            );
        }

        uint64_t seed = 0x9e3779b97f4a7c15ULL ^
                        ((uint64_t)size << 32) ^
                        ((uint64_t)componentIndex * 0x94d049bb133111ebULL);

        CoreSolver solver(std::move(localGraph), seed);
        vector<int> localAnswer = solver.solve(
            exactBudget, exactAllowance, localAllowance
        );

        for (int i = 0; i < size; ++i) {
            answer[component[i]] = localAnswer[i];
        }
    }

    for (int i = (int)removalOrder.size() - 1; i >= 0; --i) {
        int v = removalOrder[i];
        array<int, 3> used{0, 0, 0};

        for (int u : graph[v]) {
            if (answer[u] != -1) used[answer[u]] = 1;
        }

        int chosen = -1;
        for (int c = 0; c < 3; ++c) {
            if (!used[c]) {
                chosen = c;
                break;
            }
        }

        if (chosen == -1) {
            array<int, 3> counts{0, 0, 0};
            for (int u : graph[v]) {
                if (answer[u] != -1) ++counts[answer[u]];
            }
            chosen = (int)(min_element(counts.begin(), counts.end()) -
                            counts.begin());
        }
        answer[v] = chosen;
    }

    string output;
    output.reserve((size_t)n * 2);
    for (int v = 0; v < n; ++v) {
        if (v) output.push_back(' ');
        output.push_back(char('0' + answer[v] + 1));
    }
    output.push_back('\n');
    fwrite(output.data(), 1, output.size(), stdout);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct FastInput {
    static const int SZ = 1 << 20;
    char buf[SZ];
    int len = 0, pos = 0;

    inline char getChar() {
        if (pos >= len) {
            len = (int)fread(buf, 1, SZ, stdin);
            pos = 0;
            if (len == 0) return 0;
        }
        return buf[pos++];
    }

    bool readInt(int &x) {
        char c;
        do {
            c = getChar();
            if (!c) return false;
        } while (c <= ' ');
        x = 0;
        while (c > ' ') {
            x = x * 10 + (c - '0');
            c = getChar();
        }
        return true;
    }
};

int N, W;
vector<vector<int>> G;
vector<uint64_t> adjBits;
mt19937 rng(0x9e3779b9U);
chrono::steady_clock::time_point startTime;
const double TIME_LIMIT = 1.86;

inline double elapsed() {
    return chrono::duration<double>(chrono::steady_clock::now() - startTime).count();
}

inline bool timeUp() {
    return elapsed() >= TIME_LIMIT;
}

inline bool hasEdge(int u, int v) {
    return (adjBits[(size_t)u * W + (v >> 6)] >> (v & 63)) & 1ULL;
}

void outputSet(const vector<char> &sol) {
    string out;
    out.reserve((size_t)N * 2);
    for (int i = 0; i < N; ++i) {
        out.push_back(sol[i] ? '1' : '0');
        out.push_back('\n');
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

struct HopcroftKarp {
    const vector<int> &part;
    vector<int> matchL, matchR, dist, q;

    HopcroftKarp(const vector<int> &p)
        : part(p), matchL(N, -1), matchR(N, -1), dist(N, -1), q(N) {}

    bool bfs() {
        fill(dist.begin(), dist.end(), -1);
        int qh = 0, qt = 0;
        for (int u = 0; u < N; ++u) {
            if (part[u] == 0 && matchL[u] == -1) {
                dist[u] = 0;
                q[qt++] = u;
            }
        }

        bool found = false;
        while (qh < qt) {
            int u = q[qh++];
            for (int v : G[u]) {
                int nxt = matchR[v];
                if (nxt == -1) {
                    found = true;
                } else if (dist[nxt] == -1) {
                    dist[nxt] = dist[u] + 1;
                    q[qt++] = nxt;
                }
            }
        }
        return found;
    }

    bool dfs(int u) {
        for (int v : G[u]) {
            int nxt = matchR[v];
            if (nxt == -1 || (dist[nxt] == dist[u] + 1 && dfs(nxt))) {
                matchL[u] = v;
                matchR[v] = u;
                return true;
            }
        }
        dist[u] = -1;
        return false;
    }

    bool run() {
        while (true) {
            if (elapsed() > 1.68) return false;
            if (!bfs()) return true;
            for (int u = 0; u < N; ++u) {
                if (part[u] == 0 && matchL[u] == -1 && dist[u] == 0) {
                    dfs(u);
                }
            }
        }
    }
};

vector<char> staticGreedy() {
    vector<int> order(N);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        if (G[a].size() != G[b].size()) return G[a].size() < G[b].size();
        return a < b;
    });

    vector<char> blocked(N, 0), sol(N, 0);
    for (int v : order) {
        if (blocked[v]) continue;
        sol[v] = 1;
        blocked[v] = 1;
        for (int u : G[v]) blocked[u] = 1;
    }
    return sol;
}

vector<char> dynamicGreedy(int noise) {
    struct Node {
        uint64_t key;
        int d, v;
        bool operator<(const Node &other) const {
            return key > other.key;
        }
    };

    vector<int> deg(N);
    vector<char> active(N, 1);
    vector<uint32_t> randomValue(N);
    vector<char> sol(N, 0);
    priority_queue<Node> pq;

    for (int i = 0; i < N; ++i) {
        deg[i] = (int)G[i].size();
        randomValue[i] = rng();
    }

    auto makeKey = [&](int v, int d) -> uint64_t {
        uint64_t key = (uint64_t)d << 12;
        if (noise == 0) key += randomValue[v] & 4095U;
        else key += randomValue[v] % (noise * 4096U + 1U);
        return key;
    };

    for (int i = 0; i < N; ++i) {
        pq.push({makeKey(i, deg[i]), deg[i], i});
    }

    auto removeVertex = [&](int x) {
        active[x] = 0;
        for (int y : G[x]) {
            if (active[y]) {
                --deg[y];
                pq.push({makeKey(y, deg[y]), deg[y], y});
            }
        }
    };

    while (!pq.empty()) {
        Node node = pq.top();
        pq.pop();
        int v = node.v;
        if (!active[v] || node.d != deg[v]) continue;

        sol[v] = 1;
        removeVertex(v);
        for (int u : G[v]) {
            if (active[u]) removeVertex(u);
        }
    }
    return sol;
}

struct State {
    vector<char> inS;
    vector<int> tight;
    int sz = 0;

    vector<vector<int>> groups;
    vector<int> touched;
    vector<uint64_t> groupBits;

    State() : inS(N, 0), tight(N, 0), groups(N), groupBits(W) {}

    void build(const vector<char> &sol) {
        inS = sol;
        fill(tight.begin(), tight.end(), 0);
        sz = 0;
        for (int u = 0; u < N; ++u) {
            if (!inS[u]) continue;
            ++sz;
            for (int v : G[u]) ++tight[v];
        }
    }

    inline void add(int v) {
        inS[v] = 1;
        ++sz;
        for (int u : G[v]) ++tight[u];
    }

    inline void remove(int v) {
        inS[v] = 0;
        --sz;
        for (int u : G[v]) --tight[u];
    }

    void maximalize(bool randomize) {
        vector<int> candidates;
        for (int v = 0; v < N; ++v) {
            if (!inS[v] && tight[v] == 0) candidates.push_back(v);
        }
        if (candidates.empty()) return;

        if (randomize) {
            shuffle(candidates.begin(), candidates.end(), rng);
            stable_sort(candidates.begin(), candidates.end(), [&](int a, int b) {
                return G[a].size() < G[b].size();
            });
        } else {
            sort(candidates.begin(), candidates.end(), [&](int a, int b) {
                if (G[a].size() != G[b].size()) return G[a].size() < G[b].size();
                return a < b;
            });
        }

        for (int v : candidates) {
            if (!inS[v] && tight[v] == 0) add(v);
        }
    }

    bool findPair(const vector<int> &group, int &a, int &b) {
        fill(groupBits.begin(), groupBits.end(), 0ULL);
        for (int v : group) {
            groupBits[v >> 6] |= 1ULL << (v & 63);
        }

        for (int v : group) {
            uint64_t selfMask = 1ULL << (v & 63);
            groupBits[v >> 6] &= ~selfMask;
            const uint64_t *row = &adjBits[(size_t)v * W];

            bool found = false;
            for (int j = 0; j < W; ++j) {
                uint64_t available = groupBits[j] & ~row[j];
                if (available) {
                    a = v;
                    b = (j << 6) + __builtin_ctzll(available);
                    found = true;
                    break;
                }
            }
            groupBits[v >> 6] |= selfMask;
            if (found) return true;
        }
        return false;
    }

    void improve(bool randomMode) {
        vector<int> selected;
        selected.reserve(N);

        while (!timeUp()) {
            maximalize(randomMode);

            for (int u : touched) groups[u].clear();
            touched.clear();
            selected.clear();

            for (int u = 0; u < N; ++u) {
                if (inS[u]) selected.push_back(u);
            }
            if (randomMode) shuffle(selected.begin(), selected.end(), rng);

            for (size_t i = 0; i < selected.size(); ++i) {
                if ((i & 63) == 0 && timeUp()) return;
                int u = selected[i];
                for (int v : G[u]) {
                    if (!inS[v] && tight[v] == 1) groups[u].push_back(v);
                }
                if (!groups[u].empty()) touched.push_back(u);
            }

            bool swapped = false;
            for (int u : selected) {
                if (groups[u].size() < 2) continue;
                int a, b;
                if (findPair(groups[u], a, b)) {
                    remove(u);
                    add(a);
                    add(b);
                    swapped = true;
                    break;
                }
            }
            if (!swapped) break;
        }
    }

    void perturb(int strength) {
        vector<int> removed;
        for (int step = 0; step < strength; ++step) {
            int v = -1;

            if (rng() % 100 < 85) {
                int bestTight = INT_MAX;
                for (int t = 0; t < 24; ++t) {
                    int x = (int)(rng() % N);
                    if (inS[x]) continue;
                    if (tight[x] < bestTight || (tight[x] == bestTight && (rng() & 1))) {
                        bestTight = tight[x];
                        v = x;
                    }
                }
            }

            if (v == -1) {
                int start = (int)(rng() % N);
                for (int i = 0; i < N; ++i) {
                    int x = start + i;
                    if (x >= N) x -= N;
                    if (!inS[x]) {
                        v = x;
                        break;
                    }
                }
            }
            if (v == -1) return;

            removed.clear();
            for (int u : G[v]) {
                if (inS[u]) removed.push_back(u);
            }
            for (int u : removed) remove(u);
            if (!inS[v]) add(v);
        }
    }
};

int main() {
    startTime = chrono::steady_clock::now();
    static FastInput in;

    int M;
    if (!in.readInt(N)) return 0;
    in.readInt(M);

    W = (N + 63) >> 6;
    G.assign(N, {});
    adjBits.assign((size_t)N * W, 0ULL);

    for (int i = 0; i < M; ++i) {
        int u, v;
        in.readInt(u);
        in.readInt(v);
        --u;
        --v;

        size_t idx = (size_t)u * W + (v >> 6);
        uint64_t mask = 1ULL << (v & 63);
        if (adjBits[idx] & mask) continue;

        adjBits[idx] |= mask;
        adjBits[(size_t)v * W + (u >> 6)] |= 1ULL << (u & 63);
        G[u].push_back(v);
        G[v].push_back(u);
    }

    vector<int> part(N, -1), q(N);
    bool bipartite = true;

    for (int s = 0; s < N && bipartite; ++s) {
        if (part[s] != -1) continue;
        part[s] = 0;
        int qh = 0, qt = 0;
        q[qt++] = s;

        while (qh < qt) {
            int u = q[qh++];
            for (int v : G[u]) {
                if (part[v] == -1) {
                    part[v] = part[u] ^ 1;
                    q[qt++] = v;
                } else if (part[v] == part[u]) {
                    bipartite = false;
                    break;
                }
            }
            if (!bipartite) break;
        }
    }

    if (bipartite) {
        HopcroftKarp hk(part);
        if (!hk.run()) {
            int leftCount = 0;
            for (int i = 0; i < N; ++i) leftCount += (part[i] == 0);
            vector<char> fallback(N, 0);
            int chosenPart = (leftCount * 2 >= N ? 0 : 1);
            for (int i = 0; i < N; ++i) fallback[i] = (part[i] == chosenPart);
            outputSet(fallback);
            return 0;
        }

        vector<char> reachable(N, 0);
        int qh = 0, qt = 0;
        for (int u = 0; u < N; ++u) {
            if (part[u] == 0 && hk.matchL[u] == -1) {
                reachable[u] = 1;
                q[qt++] = u;
            }
        }

        while (qh < qt) {
            int u = q[qh++];
            if (part[u] == 0) {
                for (int v : G[u]) {
                    if (hk.matchL[u] != v && !reachable[v]) {
                        reachable[v] = 1;
                        q[qt++] = v;
                    }
                }
            } else {
                int v = hk.matchR[u];
                if (v != -1 && !reachable[v]) {
                    reachable[v] = 1;
                    q[qt++] = v;
                }
            }
        }

        vector<char> exact(N, 0);
        for (int i = 0; i < N; ++i) {
            exact[i] = (part[i] == 0 ? reachable[i] : !reachable[i]);
        }
        outputSet(exact);
        return 0;
    }

    vector<char> best = staticGreedy();
    int bestSize = 0;
    for (char x : best) bestSize += x;

    auto runCandidate = [&](int noise) {
        vector<char> candidate = dynamicGreedy(noise);
        State state;
        state.build(candidate);
        state.improve(false);
        if (state.sz > bestSize) {
            bestSize = state.sz;
            best = state.inS;
        }
    };

    if (elapsed() < 1.45) runCandidate(0);

    int extraRuns = 0;
    while (extraRuns < 2 && elapsed() < 0.82) {
        runCandidate(1 + extraRuns * 2);
        ++extraRuns;
    }

    State current;
    current.build(best);

    int iteration = 0;
    int noImprovement = 0;

    while (!timeUp()) {
        int oldSize = current.sz;
        int r = (int)(rng() % 100);
        int strength;
        if (r < 70) strength = 1;
        else if (r < 93) strength = 2 + (int)(rng() % 2);
        else strength = 4 + (int)(rng() % 5);

        if (noImprovement > 60 && rng() % 12 == 0) {
            strength = 8 + (int)(rng() % 8);
        }

        current.perturb(strength);
        current.improve(true);

        if (current.sz > bestSize) {
            bestSize = current.sz;
            best = current.inS;
            noImprovement = 0;
        } else {
            ++noImprovement;
            if (current.sz == bestSize && rng() % 6 == 0) {
                best = current.inS;
            }
        }

        if (current.sz < bestSize - 3 ||
            current.sz + 3 < oldSize ||
            (iteration % 160 == 159 && current.sz < bestSize)) {
            current.build(best);
        }
        ++iteration;
    }

    outputSet(best);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using Clock = chrono::steady_clock;

int n, m, wordCount;
vector<vector<int>> g;
vector<uint64_t> adjBits;
Clock::time_point startTime;
mt19937 rng(0x9e3779b9u);

inline bool hasEdge(int u, int v) {
    return (adjBits[(size_t)u * wordCount + (v >> 6)] >> (v & 63)) & 1ULL;
}

inline bool timeUp() {
    return chrono::duration<double>(Clock::now() - startTime).count() > 1.80;
}

struct State {
    vector<unsigned char> in;
    vector<int> cnt;
    int sz = 0;
};

State emptyState() {
    State s;
    s.in.assign(n, 0);
    s.cnt.assign(n, 0);
    s.sz = 0;
    return s;
}

inline void addVertex(State &s, int v) {
    s.in[v] = 1;
    ++s.sz;
    for (int u : g[v]) ++s.cnt[u];
}

inline void removeVertex(State &s, int v) {
    s.in[v] = 0;
    --s.sz;
    for (int u : g[v]) --s.cnt[u];
}

State constructFromOrder(const vector<int> &order) {
    State s = emptyState();
    for (int v : order) {
        if (s.cnt[v] == 0) addVertex(s, v);
    }
    return s;
}

void maximalize(State &s, const vector<int> &order) {
    for (int v : order) {
        if (!s.in[v] && s.cnt[v] == 0) addVertex(s, v);
    }
}

State dynamicMinDegreeGreedy() {
    State s = emptyState();
    vector<unsigned char> remaining(n, 1);
    vector<int> deg(n), tie(n);
    for (int v = 0; v < n; ++v) {
        deg[v] = (int)g[v].size();
        tie[v] = (int)(rng() & 0x7fffffff);
    }

    using Item = tuple<int, int, int>;
    priority_queue<Item, vector<Item>, greater<Item>> pq;
    for (int v = 0; v < n; ++v) pq.emplace(deg[v], tie[v], v);

    while (!pq.empty()) {
        auto [d, t, v] = pq.top();
        pq.pop();
        if (!remaining[v] || deg[v] != d) continue;

        remaining[v] = 0;
        addVertex(s, v);

        for (int u : g[v]) {
            if (!remaining[u]) continue;
            remaining[u] = 0;
            for (int w : g[u]) {
                if (!remaining[w]) continue;
                --deg[w];
                pq.emplace(deg[w], tie[w], w);
            }
        }
    }
    return s;
}

void oneTwoImprovements(State &s, int maxRounds) {
    const int checkLimit = 40000;

    for (int round = 0; round < maxRounds; ++round) {
        if ((round & 3) == 0 && timeUp()) return;

        vector<vector<int>> groups(n);
        vector<int> blockers;

        for (int v = 0; v < n; ++v) {
            if (s.in[v] || s.cnt[v] != 1) continue;
            for (int u : g[v]) {
                if (s.in[u]) {
                    if (groups[u].empty()) blockers.push_back(u);
                    groups[u].push_back(v);
                    break;
                }
            }
        }

        shuffle(blockers.begin(), blockers.end(), rng);
        bool found = false;
        int checks = 0;

        for (int u : blockers) {
            auto &cand = groups[u];
            if (cand.size() < 2) continue;
            if (cand.size() > 3) shuffle(cand.begin(), cand.end(), rng);

            for (int i = 0; i < (int)cand.size() && !found; ++i) {
                for (int j = i + 1; j < (int)cand.size(); ++j) {
                    if (++checks > checkLimit) break;
                    int a = cand[i], b = cand[j];
                    if (!hasEdge(a, b)) {
                        removeVertex(s, u);
                        addVertex(s, a);
                        addVertex(s, b);
                        found = true;
                        break;
                    }
                }
                if (checks > checkLimit) break;
            }
            if (found || checks > checkLimit) break;
        }

        if (!found) return;
    }
}

bool bipartiteColoring(vector<int> &color) {
    color.assign(n, -1);
    vector<int> q(n);
    for (int root = 0; root < n; ++root) {
        if (color[root] != -1) continue;
        color[root] = 0;
        int qh = 0, qt = 0;
        q[qt++] = root;
        while (qh < qt) {
            int v = q[qh++];
            for (int u : g[v]) {
                if (color[u] == -1) {
                    color[u] = color[v] ^ 1;
                    q[qt++] = u;
                } else if (color[u] == color[v]) {
                    return false;
                }
            }
        }
    }
    return true;
}

vector<unsigned char> solveBipartite(const vector<int> &color) {
    vector<int> matchL(n, -1), matchR(n, -1), dist(n);

    auto bfs = [&]() {
        queue<int> q;
        for (int v = 0; v < n; ++v) {
            if (color[v] == 0 && matchL[v] == -1) {
                dist[v] = 0;
                q.push(v);
            } else {
                dist[v] = -1;
            }
        }
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : g[u]) {
                int nxt = matchR[v];
                if (nxt != -1 && dist[nxt] == -1) {
                    dist[nxt] = dist[u] + 1;
                    q.push(nxt);
                }
            }
        }
    };

    auto dfs = [&](auto &&self, int u) -> bool {
        for (int v : g[u]) {
            int nxt = matchR[v];
            if (nxt == -1 || (dist[nxt] == dist[u] + 1 && self(self, nxt))) {
                matchL[u] = v;
                matchR[v] = u;
                return true;
            }
        }
        dist[u] = -1;
        return false;
    };

    while (true) {
        bfs();
        bool augmented = false;
        for (int v = 0; v < n; ++v) {
            if (color[v] == 0 && matchL[v] == -1) {
                if (dfs(dfs, v)) augmented = true;
            }
        }
        if (!augmented) break;
    }

    vector<unsigned char> reachable(n, 0);
    queue<int> q;
    for (int v = 0; v < n; ++v) {
        if (color[v] == 0 && matchL[v] == -1) {
            reachable[v] = 1;
            q.push(v);
        }
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (color[u] == 0) {
            for (int v : g[u]) {
                if (matchL[u] == v || reachable[v]) continue;
                reachable[v] = 1;
                q.push(v);
            }
        } else {
            int v = matchR[u];
            if (v != -1 && !reachable[v]) {
                reachable[v] = 1;
                q.push(v);
            }
        }
    }

    vector<unsigned char> independent(n, 0);
    for (int v = 0; v < n; ++v) {
        if (color[v] == 0) independent[v] = reachable[v];
        else independent[v] = !reachable[v];
    }
    return independent;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    startTime = Clock::now();
    cin >> n >> m;
    g.assign(n, {});
    wordCount = (n + 63) >> 6;
    adjBits.assign((size_t)n * wordCount, 0ULL);

    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;
        size_t pos = (size_t)u * wordCount + (v >> 6);
        uint64_t mask = 1ULL << (v & 63);
        if (adjBits[pos] & mask) continue;
        adjBits[pos] |= mask;
        adjBits[(size_t)v * wordCount + (u >> 6)] |= 1ULL << (u & 63);
        g[u].push_back(v);
        g[v].push_back(u);
    }

    vector<int> bipColor;
    if (bipartiteColoring(bipColor)) {
        vector<unsigned char> answer = solveBipartite(bipColor);
        for (int v = 0; v < n; ++v) cout << (int)answer[v] << '\n';
        return 0;
    }

    vector<int> baseOrder(n);
    iota(baseOrder.begin(), baseOrder.end(), 0);
    sort(baseOrder.begin(), baseOrder.end(), [](int a, int b) {
        if (g[a].size() != g[b].size()) return g[a].size() < g[b].size();
        return a < b;
    });

    State best = dynamicMinDegreeGreedy();
    oneTwoImprovements(best, 70);
    maximalize(best, baseOrder);

    State candidate = constructFromOrder(baseOrder);
    if (candidate.sz >= best.sz - 4) {
        oneTwoImprovements(candidate, 50);
        maximalize(candidate, baseOrder);
    }
    if (candidate.sz > best.sz) best = candidate;

    vector<pair<double, int>> keyed(n);
    for (int iter = 0; iter < 14 && !timeUp(); ++iter) {
        for (int v = 0; v < n; ++v) {
            double d = (double)g[v].size();
            double r = (double)(rng() & 0xffffff) / (double)0xffffff;
            double key;
            if (iter & 1) key = d * (0.60 + 0.80 * r);
            else key = d + r * (3.0 + 0.35 * d);
            keyed[v] = {key, v};
        }
        sort(keyed.begin(), keyed.end(), [](const auto &a, const auto &b) {
            return a.first < b.first;
        });
        vector<int> order(n);
        for (int v = 0; v < n; ++v) order[v] = keyed[v].second;

        State s = constructFromOrder(order);
        if (s.sz >= best.sz - 4) {
            oneTwoImprovements(s, 30);
            maximalize(s, order);
        }
        if (s.sz > best.sz) best = s;
    }

    State current = best;
    vector<int> randomOrder(n);
    iota(randomOrder.begin(), randomOrder.end(), 0);

    int iteration = 0, stall = 0;
    while (!timeUp()) {
        ++iteration;
        if (iteration % 40 == 0 || current.sz + 3 < best.sz) current = best;

        State s = current;
        int chosen = -1;

        for (int attempt = 0; attempt < 40; ++attempt) {
            int v = (int)(rng() % n);
            if (!s.in[v] && (s.cnt[v] == 1 || (s.cnt[v] == 2 && attempt >= 25))) {
                chosen = v;
                break;
            }
        }
        if (chosen == -1) {
            int start = (int)(rng() % n);
            for (int k = 0; k < n; ++k) {
                int v = start + k;
                if (v >= n) v -= n;
                if (!s.in[v]) {
                    chosen = v;
                    break;
                }
            }
        }
        if (chosen == -1) break;

        for (int u : g[chosen]) {
            if (s.in[u]) removeVertex(s, u);
        }
        addVertex(s, chosen);

        if (rng() % 100 < 18) {
            int removals = 1 + (int)(rng() % 3);
            for (int r = 0; r < removals; ++r) {
                for (int attempt = 0; attempt < 20; ++attempt) {
                    int v = (int)(rng() % n);
                    if (s.in[v] && v != chosen) {
                        removeVertex(s, v);
                        break;
                    }
                }
            }
        }

        shuffle(randomOrder.begin(), randomOrder.end(), rng);
        maximalize(s, randomOrder);

        if (s.sz >= best.sz - 3 || iteration % 7 == 0) {
            oneTwoImprovements(s, 10);
            maximalize(s, randomOrder);
        }

        if (s.sz > best.sz) {
            best = s;
            stall = 0;
        } else {
            ++stall;
        }

        if (s.sz >= current.sz || (s.sz + 1 == current.sz && rng() % 5 == 0)) {
            current = s;
        }
        if (stall > 70) {
            current = best;
            stall = 0;
        }
    }

    for (int v = 0; v < n; ++v) {
        if (!best.in[v]) continue;
        for (int u : g[v]) {
            if (u > v && best.in[u]) removeVertex(best, u);
        }
    }

    for (int v = 0; v < n; ++v) cout << (int)best.in[v] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Result {
    int size;
    uint64_t chosen;
};

Result exactMIS(uint64_t mask, const vector<uint64_t>& adj, unordered_map<uint64_t, Result>& memo) {
    if (mask == 0) return {0, 0};
    auto it = memo.find(mask);
    if (it != memo.end()) return it->second;

    int isolated = -1;
    int leaf = -1;
    int leafNeighbor = -1;
    uint64_t temp = mask;
    while (temp) {
        int v = __builtin_ctzll(temp);
        temp &= temp - 1;
        uint64_t neighbors = adj[v] & mask;
        int deg = __builtin_popcountll(neighbors);
        if (deg == 0) {
            isolated = v;
            break;
        } else if (deg == 1) {
            leaf = v;
            leafNeighbor = __builtin_ctzll(neighbors);
            break;
        }
    }

    if (isolated != -1) {
        uint64_t newMask = mask & ~(1ULL << isolated);
        Result res = exactMIS(newMask, adj, memo);
        res.size += 1;
        res.chosen |= (1ULL << isolated);
        memo[mask] = res;
        return res;
    }

    if (leaf != -1) {
        uint64_t newMask = mask & ~(1ULL << leaf) & ~(1ULL << leafNeighbor);
        Result res = exactMIS(newMask, adj, memo);
        res.size += 1;
        res.chosen |= (1ULL << leaf);
        memo[mask] = res;
        return res;
    }

    int bestV = -1;
    int maxDeg = -1;
    temp = mask;
    while (temp) {
        int v = __builtin_ctzll(temp);
        temp &= temp - 1;
        int deg = __builtin_popcountll(adj[v] & mask);
        if (deg > maxDeg) {
            maxDeg = deg;
            bestV = v;
        }
    }

    uint64_t includeMask = mask & ~(1ULL << bestV) & ~adj[bestV];
    Result resInc = exactMIS(includeMask, adj, memo);
    resInc.size += 1;
    resInc.chosen |= (1ULL << bestV);

    uint64_t excludeMask = mask & ~(1ULL << bestV);
    Result resExc = exactMIS(excludeMask, adj, memo);

    Result best = (resInc.size >= resExc.size) ? resInc : resExc;
    memo[mask] = best;
    return best;
}

int greedyMinDegree(const vector<vector<int>>& adj, mt19937& rng, vector<char>& sol) {
    int N = adj.size();
    vector<int> deg(N);
    vector<uint32_t> rank(N);
    for (int i = 0; i < N; ++i) {
        deg[i] = adj[i].size();
        rank[i] = rng();
    }
    vector<char> active(N, 1), inS(N, 0);
    priority_queue<pair<uint64_t, int>, vector<pair<uint64_t, int>>, greater<pair<uint64_t, int>>> pq;
    for (int i = 0; i < N; ++i) {
        pq.push({((uint64_t)deg[i] << 32) | rank[i], i});
    }
    vector<int> removed;
    while (!pq.empty()) {
        auto [key, u] = pq.top();
        pq.pop();
        int d = key >> 32;
        if (!active[u] || deg[u] != d) continue;
        inS[u] = 1;
        removed.clear();
        active[u] = 0;
        removed.push_back(u);
        for (int v : adj[u]) {
            if (active[v]) {
                active[v] = 0;
                removed.push_back(v);
            }
        }
        for (int x : removed) {
            for (int y : adj[x]) {
                if (active[y]) {
                    deg[y]--;
                    pq.push({((uint64_t)deg[y] << 32) | rank[y], y});
                }
            }
        }
    }
    sol = move(inS);
    int K = 0;
    for (char c : sol) K += c;
    return K;
}

void improveILS(const vector<vector<int>>& adj, vector<char>& bestS, steady_clock::time_point deadline, mt19937& rng) {
    int N = adj.size();
    if (N == 0) return;
    vector<char> curS = bestS;
    vector<int> degS(N, 0);
    for (int v = 0; v < N; ++v) {
        if (curS[v]) {
            for (int u : adj[v]) degS[u]++;
        }
    }
    vector<int> sel;
    for (int v = 0; v < N; ++v) if (curS[v]) sel.push_back(v);
    int curK = sel.size();
    int bestK = curK;
    bestS = curS;
    int stagnation = 0;
    vector<int> candidates;
    candidates.reserve(1024);

    vector<char> backupS;
    vector<int> backupDegS;
    vector<int> backupSel;
    int backupK;

    while (steady_clock::now() < deadline) {
        int p = 1;
        bool kick = false;
        if (stagnation > 500) {
            p = 2 + (rng() % 3);
            kick = true;
            stagnation = 0;
        }

        if (kick) {
            backupS = curS;
            backupDegS = degS;
            backupSel = sel;
            backupK = curK;
        }

        candidates.clear();
        int remCount = min(p, (int)sel.size());
        for (int i = 0; i < remCount; ++i) {
            int idx = rng() % sel.size();
            int u = sel[idx];
            sel[idx] = sel.back();
            sel.pop_back();
            curS[u] = 0;
            curK--;
            candidates.push_back(u);
            for (int v : adj[u]) {
                degS[v]--;
                if (!curS[v] && degS[v] == 0) {
                    candidates.push_back(v);
                }
            }
        }

        shuffle(candidates.begin(), candidates.end(), rng);

        for (int v : candidates) {
            if (!curS[v] && degS[v] == 0) {
                curS[v] = 1;
                curK++;
                sel.push_back(v);
                for (int u : adj[v]) {
                    degS[u]++;
                }
            }
        }

        if (curK > bestK) {
            bestK = curK;
            bestS = curS;
            stagnation = 0;
        } else {
            stagnation++;
        }

        if (kick) {
            if (curK >= backupK) {
                // accept
            } else if (curK > bestK) {
                // accept
            } else if (curK >= backupK - 1 && (rng() % 100 < 20)) {
                // accept slightly worse
            } else {
                curS = backupS;
                degS = backupDegS;
                sel = backupSel;
                curK = backupK;
            }
        }

        if (curK < bestK - 5) {
            curS = bestS;
            fill(degS.begin(), degS.end(), 0);
            sel.clear();
            for (int v = 0; v < N; ++v) {
                if (curS[v]) {
                    sel.push_back(v);
                    for (int u : adj[v]) degS[u]++;
                }
            }
            curK = sel.size();
        }
    }
}

vector<char> solveMIS(const vector<vector<int>>& adj, steady_clock::time_point deadline) {
    int N = adj.size();
    if (N == 0) return {};
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count() ^ (uintptr_t)&adj);
    vector<char> bestS(N, 0);
    int bestK = 0;

    vector<int> degree(N);
    int maxDeg = 0;
    for (int i = 0; i < N; ++i) {
        degree[i] = adj[i].size();
        maxDeg = max(maxDeg, degree[i]);
    }

    vector<vector<int>> buckets(maxDeg + 1);
    for (int i = 0; i < N; ++i) {
        buckets[degree[i]].push_back(i);
    }

    vector<int> flatOrder;
    flatOrder.reserve(N);
    vector<pair<int, int>> segments;
    for (int d = 0; d <= maxDeg; ++d) {
        int l = flatOrder.size();
        for (int v : buckets[d]) flatOrder.push_back(v);
        int r = flatOrder.size();
        if (r > l) segments.push_back({l, r});
    }

    vector<int> order(N);
    vector<char> inS(N);

    auto now = steady_clock::now();
    auto remaining = deadline - now;
    if (remaining.count() <= 0) remaining = chrono::milliseconds(0);
    auto staticDeadline = now + remaining * 20 / 100;
    auto dynDeadline = now + remaining * 50 / 100;

    int runs = 0;
    while (steady_clock::now() < staticDeadline && runs < 1000) {
        order = flatOrder;
        for (auto& seg : segments) {
            shuffle(order.begin() + seg.first, order.begin() + seg.second, rng);
        }
        fill(inS.begin(), inS.end(), 0);
        int K = 0;
        for (int v : order) {
            bool conflict = false;
            for (int u : adj[v]) {
                if (inS[u]) {
                    conflict = true;
                    break;
                }
            }
            if (!conflict) {
                inS[v] = 1;
                K++;
            }
        }
        if (K > bestK) {
            bestK = K;
            bestS = inS;
        }
        runs++;
    }

    if (bestK == 0 && N > 0) {
        order = flatOrder;
        for (auto& seg : segments) {
            shuffle(order.begin() + seg.first, order.begin() + seg.second, rng);
        }
        fill(inS.begin(), inS.end(), 0);
        int K = 0;
        for (int v : order) {
            bool conflict = false;
            for (int u : adj[v]) {
                if (inS[u]) {
                    conflict = true;
                    break;
                }
            }
            if (!conflict) {
                inS[v] = 1;
                K++;
            }
        }
        bestK = K;
        bestS = inS;
    }

    int dynRuns = 0;
    while (steady_clock::now() < dynDeadline && dynRuns < 10) {
        vector<char> sol;
        int K = greedyMinDegree(adj, rng, sol);
        if (K > bestK) {
            bestK = K;
            bestS = sol;
        }
        dynRuns++;
    }

    if (steady_clock::now() < deadline) {
        improveILS(adj, bestS, deadline, rng);
    }

    return bestS;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto programStart = steady_clock::now();
    auto overallDeadline = programStart + chrono::milliseconds(1900);

    int N, M;
    cin >> N >> M;
    vector<vector<int>> adj(N);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    for (int i = 0; i < N; ++i) {
        sort(adj[i].begin(), adj[i].end());
        adj[i].erase(unique(adj[i].begin(), adj[i].end()), adj[i].end());
    }

    vector<int> compId(N, -1);
    vector<vector<int>> components;
    for (int i = 0; i < N; ++i) {
        if (compId[i] == -1) {
            vector<int> verts;
            vector<int> stack;
            stack.push_back(i);
            compId[i] = components.size();
            while (!stack.empty()) {
                int u = stack.back();
                stack.pop_back();
                verts.push_back(u);
                for (int v : adj[u]) {
                    if (compId[v] == -1) {
                        compId[v] = components.size();
                        stack.push_back(v);
                    }
                }
            }
            components.push_back(verts);
        }
    }

    vector<char> finalS(N, 0);
    vector<int> largeVerts;
    const int EXACT_LIMIT = 25;
    vector<int> localIdx(N, -1);

    for (auto& verts : components) {
        int sz = verts.size();
        if (sz <= EXACT_LIMIT) {
            for (int i = 0; i < sz; ++i) localIdx[verts[i]] = i;
            vector<uint64_t> adjMask(sz, 0);
            for (int i = 0; i < sz; ++i) {
                int u = verts[i];
                for (int v : adj[u]) {
                    int j = localIdx[v];
                    if (j != -1) adjMask[i] |= (1ULL << j);
                }
            }
            unordered_map<uint64_t, Result> memo;
            uint64_t fullMask = (1ULL << sz) - 1;
            Result res = exactMIS(fullMask, adjMask, memo);
            for (int i = 0; i < sz; ++i) {
                if (res.chosen & (1ULL << i)) {
                    finalS[verts[i]] = 1;
                }
            }
            for (int v : verts) localIdx[v] = -1;
        } else {
            for (int v : verts) largeVerts.push_back(v);
        }
    }

    int L = largeVerts.size();
    if (L > 0) {
        vector<int> globalToLocal(N, -1);
        for (int i = 0; i < L; ++i) {
            globalToLocal[largeVerts[i]] = i;
        }
        vector<vector<int>> g(L);
        for (int i = 0; i < L; ++i) {
            int u = largeVerts[i];
            for (int v : adj[u]) {
                int j = globalToLocal[v];
                if (j != -1) g[i].push_back(j);
            }
        }
        vector<char> largeS = solveMIS(g, overallDeadline);
        for (int i = 0; i < L; ++i) {
            if (largeS[i]) {
                finalS[largeVerts[i]] = 1;
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        cout << (int)finalS[i] << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using u64 = uint64_t;
using u128 = unsigned __int128;

static mt19937 rng(
    static_cast<unsigned>(
        chrono::steady_clock::now().time_since_epoch().count()
    )
);

static int randInt(int n) {
    return n <= 1 ? 0 : static_cast<int>(rng() % static_cast<unsigned>(n));
}

struct FastScanner {
    static constexpr int SIZE = 1 << 16;
    char buffer[SIZE];
    int pos = 0, len = 0;

    inline char getChar() {
        if (pos == len) {
            len = static_cast<int>(fread(buffer, 1, SIZE, stdin));
            pos = 0;
            if (len == 0) return 0;
        }
        return buffer[pos++];
    }

    int nextInt() {
        char c;
        do {
            c = getChar();
        } while (c <= ' ' && c);

        int x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = getChar();
        }
        return x;
    }
};

static inline bool adjacent(
    const vector<vector<u64>>& matrix,
    int u,
    int v
) {
    return (matrix[u][v >> 6] >> (v & 63)) & 1ULL;
}

struct U128Hash {
    static u64 mix(u64 x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    size_t operator()(u128 x) const noexcept {
        u64 low = static_cast<u64>(x);
        u64 high = static_cast<u64>(x >> 64);
        return static_cast<size_t>(mix(low ^ mix(high + 0x123456789abcdefULL)));
    }
};

struct MaxClique64 {
    int n;
    vector<u64> original;
    vector<u64> complement;
    int bestSize = 0;
    u64 bestMask = 0;
    long long nodes = 0;
    long long nodeLimit;
    bool aborted = false;

    explicit MaxClique64(
        int n,
        const vector<u64>& original,
        long long nodeLimit = 3000000
    ) : n(n), original(original), nodeLimit(nodeLimit) {
        u64 full = (n == 64 ? ~0ULL : ((1ULL << n) - 1));
        complement.resize(n);
        for (int i = 0; i < n; ++i) {
            complement[i] = full & ~(original[i] | (1ULL << i));
        }
    }

    int colorSort(u64 candidates, int* order, int* bound) const {
        int length = 0;
        int color = 0;
        u64 remaining = candidates;

        while (remaining) {
            ++color;
            u64 available = remaining;

            while (available) {
                int v = __builtin_ctzll(available);
                order[length] = v;
                bound[length] = color;
                ++length;

                remaining &= ~(1ULL << v);
                available &= original[v];
                available &= ~(1ULL << v);
            }
        }
        return length;
    }

    void expand(u64 candidates, int size, u64 chosen) {
        if (aborted) return;

        if (size > bestSize) {
            bestSize = size;
            bestMask = chosen;
        }
        if (!candidates) return;

        if (++nodes > nodeLimit) {
            aborted = true;
            return;
        }

        int order[64], bound[64];
        int length = colorSort(candidates, order, bound);

        for (int i = length - 1; i >= 0; --i) {
            if (size + bound[i] <= bestSize) return;

            int v = order[i];
            u64 next = candidates & complement[v];
            expand(next, size + 1, chosen | (1ULL << v));

            if (aborted) return;
            candidates &= ~(1ULL << v);
        }
    }

    void solve() {
        u64 full = (n == 64 ? ~0ULL : ((1ULL << n) - 1));
        expand(full, 0, 0);
    }
};

struct GeneralComponent {
    vector<int> vertices;
    vector<vector<int>> adj;
    int edgeCount = 0;
    vector<char> best;
    vector<char> alternative;
};

static vector<char> greedyMinimumDegree(
    const GeneralComponent& component,
    int noise,
    bool useNoise
) {
    const int n = static_cast<int>(component.vertices.size());
    const auto& adj = component.adj;

    vector<int> degree(n);
    int maxDegree = 0;
    for (int i = 0; i < n; ++i) {
        degree[i] = static_cast<int>(adj[i].size());
        maxDegree = max(maxDegree, degree[i]);
    }

    vector<vector<int>> bucket(maxDegree + 1);
    vector<int> bucketPosition(n, -1);
    vector<char> active(n, true);
    vector<char> selected(n, false);

    auto eraseBucket = [&](int v, int d) {
        auto& b = bucket[d];
        int p = bucketPosition[v];
        if (p < 0) return;
        int last = b.back();
        b[p] = last;
        bucketPosition[last] = p;
        b.pop_back();
        bucketPosition[v] = -1;
    };

    auto insertBucket = [&](int v, int d) {
        bucket[d].push_back(v);
        bucketPosition[v] = static_cast<int>(bucket[d].size()) - 1;
    };

    for (int v = 0; v < n; ++v) insertBucket(v, degree[v]);

    int minimumDegree = 0;
    vector<int> removed;

    while (true) {
        while (minimumDegree <= maxDegree && bucket[minimumDegree].empty()) {
            ++minimumDegree;
        }
        if (minimumDegree > maxDegree) break;

        int chosenDegree = minimumDegree;
        if (useNoise && noise > 0 && randInt(3) == 0) {
            for (int offset = 1; offset <= noise; ++offset) {
                int d = minimumDegree + offset;
                if (d <= maxDegree && !bucket[d].empty()) {
                    chosenDegree = d;
                    break;
                }
            }
        }

        int v = bucket[chosenDegree][randInt(static_cast<int>(bucket[chosenDegree].size()))];
        selected[v] = true;

        removed.clear();
        removed.push_back(v);
        for (int u : adj[v]) {
            if (active[u]) removed.push_back(u);
        }

        for (int x : removed) {
            active[x] = false;
            eraseBucket(x, degree[x]);
        }

        for (int x : removed) {
            for (int y : adj[x]) {
                if (active[y]) {
                    eraseBucket(y, degree[y]);
                    --degree[y];
                    insertBucket(y, degree[y]);
                    minimumDegree = min(minimumDegree, degree[y]);
                }
            }
        }
    }

    return selected;
}

static vector<char> greedyRandomOrder(const GeneralComponent& component) {
    const int n = static_cast<int>(component.vertices.size());
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    shuffle(order.begin(), order.end(), rng);

    vector<char> selected(n, false);
    vector<char> blocked(n, false);

    for (int v : order) {
        if (blocked[v]) continue;
        selected[v] = true;
        for (int u : component.adj[v]) blocked[u] = true;
    }
    return selected;
}

struct HopcroftKarp {
    const vector<vector<int>>& graph;
    const vector<int>& leftVertices;
    const vector<int>& rightVertices;

    vector<int> pairLeft, pairRight, distance, current;
    int shortest = 0;

    HopcroftKarp(
        const vector<vector<int>>& graph,
        const vector<int>& leftVertices,
        const vector<int>& rightVertices
    ) : graph(graph), leftVertices(leftVertices), rightVertices(rightVertices) {
        const int n = static_cast<int>(graph.size());
        pairLeft.assign(n, -1);
        pairRight.assign(n, -1);
        distance.assign(n, -1);
        current.assign(n, 0);
    }

    bool bfs() {
        const int INF = 1e9;
        queue<int> q;

        for (int u : leftVertices) {
            if (pairLeft[u] == -1) {
                distance[u] = 0;
                q.push(u);
            } else {
                distance[u] = INF;
            }
        }

        shortest = INF;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            if (distance[u] >= shortest) continue;

            for (int v : graph[u]) {
                int next = pairRight[v];
                if (next == -1) {
                    shortest = min(shortest, distance[u] + 1);
                } else if (distance[next] == INF) {
                    distance[next] = distance[u] + 1;
                    q.push(next);
                }
            }
        }

        return shortest != INF;
    }

    bool dfs(int u) {
        for (int& i = current[u]; i < static_cast<int>(graph[u].size()); ++i) {
            int v = graph[u][i];
            int next = pairRight[v];

            if (next == -1) {
                if (distance[u] + 1 != shortest) continue;
            } else {
                if (distance[next] != distance[u] + 1 || !dfs(next)) continue;
            }

            pairLeft[u] = v;
            pairRight[v] = u;
            return true;
        }

        distance[u] = 1e9;
        return false;
    }

    int solve() {
        int matching = 0;
        while (bfs()) {
            for (int u : leftVertices) current[u] = 0;
            for (int u : leftVertices) {
                if (pairLeft[u] == -1 && dfs(u)) ++matching;
            }
        }
        return matching;
    }
};

class LocalOptimizer {
    static constexpr int MAX_K = 5;

    struct GroupDescription {
        u128 key;
        int poolSize;
    };

    const vector<vector<int>>& adj;
    int n;
    int words;

    vector<vector<u64>> bits;
    vector<char> selected;
    vector<int> conflictCount;
    vector<array<int, MAX_K>> smallBlockers;

    vector<vector<int>> countBucket;
    vector<int> countPosition;

    vector<vector<int>> privateNeighbors;
    vector<int> privatePosition;

    vector<int> selectedVertices;
    vector<int> selectedPosition;

    vector<int> tabuUntil;
    vector<int> lockedUntil;

    void eraseCountBucket(int v, int count) {
        if (count < 0 || count > MAX_K) return;
        auto& b = countBucket[count];
        int p = countPosition[v];
        if (p < 0) return;

        int last = b.back();
        b[p] = last;
        countPosition[last] = p;
        b.pop_back();
        countPosition[v] = -1;
    }

    void insertCountBucket(int v, int count) {
        if (count < 0 || count > MAX_K) return;
        countBucket[count].push_back(v);
        countPosition[v] = static_cast<int>(countBucket[count].size()) - 1;
    }

    void removePrivate(int v, int blocker) {
        if (blocker < 0) return;
        auto& b = privateNeighbors[blocker];
        int p = privatePosition[v];
        if (p < 0) return;

        int last = b.back();
        b[p] = last;
        privatePosition[last] = p;
        b.pop_back();
        privatePosition[v] = -1;
    }

    void insertPrivate(int v, int blocker) {
        if (blocker < 0) return;
        auto& b = privateNeighbors[blocker];
        b.push_back(v);
        privatePosition[v] = static_cast<int>(b.size()) - 1;
    }

    void changeConflict(int v, int delta, int changedBlocker) {
        int oldCount = conflictCount[v];
        int newCount = oldCount + delta;

        if (oldCount == 1) {
            removePrivate(v, smallBlockers[v][0]);
        }

        if (oldCount <= MAX_K) {
            if (delta < 0) {
                int position = -1;
                for (int i = 0; i < oldCount; ++i) {
                    if (smallBlockers[v][i] == changedBlocker) {
                        position = i;
                        break;
                    }
                }

                if (position >= 0) {
                    for (int i = position; i + 1 < oldCount; ++i) {
                        smallBlockers[v][i] = smallBlockers[v][i + 1];
                    }
                } else {
                    int count = 0;
                    for (int u : adj[v]) {
                        if (selected[u]) smallBlockers[v][count++] = u;
                    }
                }
            } else if (oldCount < MAX_K) {
                smallBlockers[v][oldCount] = changedBlocker;
            }
        } else if (newCount <= MAX_K) {
            int count = 0;
            for (int u : adj[v]) {
                if (selected[u]) smallBlockers[v][count++] = u;
            }
        }

        conflictCount[v] = newCount;

        if (newCount == 1) {
            insertPrivate(v, smallBlockers[v][0]);
        }

        eraseCountBucket(v, oldCount);
        insertCountBucket(v, newCount);
    }

    void removeFromSelectedList(int v) {
        int p = selectedPosition[v];
        if (p < 0) return;
        int last = selectedVertices.back();
        selectedVertices[p] = last;
        selectedPosition[last] = p;
        selectedVertices.pop_back();
        selectedPosition[v] = -1;
    }

    void addVertex(int v) {
        eraseCountBucket(v, 0);

        selected[v] = true;
        selectedPosition[v] = static_cast<int>(selectedVertices.size());
        selectedVertices.push_back(v);

        for (int u : adj[v]) {
            if (!selected[u]) changeConflict(u, +1, v);
        }
    }

    void removeVertex(int v) {
        selected[v] = false;
        removeFromSelectedList(v);

        for (int u : adj[v]) {
            if (!selected[u]) changeConflict(u, -1, v);
        }

        conflictCount[v] = 0;
        smallBlockers[v].fill(-1);
        insertCountBucket(v, 0);
    }

    bool adjacentLocal(int a, int b) const {
        return (bits[static_cast<size_t>(a) * words + (b >> 6)] >>
                (b & 63)) & 1ULL;
    }

    static u128 encodeKey(const vector<int>& values) {
        u128 key = 0;
        for (int i = 0; i < static_cast<int>(values.size()); ++i) {
            key |= static_cast<u128>(values[i]) << (14 * i);
        }
        return key;
    }

    static u128 encodeKey(const array<int, MAX_K>& values, int length) {
        u128 key = 0;
        for (int i = 0; i < length; ++i) {
            key |= static_cast<u128>(values[i]) << (14 * i);
        }
        return key;
    }

    static vector<int> decodeKey(u128 key, int length) {
        vector<int> result(length);
        for (int i = 0; i < length; ++i) {
            result[i] = static_cast<int>((key >> (14 * i)) & 16383ULL);
        }
        return result;
    }

    int randomSetBit(const vector<u64>& mask) const {
        int nonzero = 0;
        int chosenWord = -1;

        for (int w = 0; w < words; ++w) {
            if (mask[w]) {
                ++nonzero;
                if (randInt(nonzero) == 0) chosenWord = w;
            }
        }
        if (chosenWord < 0) return -1;

        u64 value = mask[chosenWord];
        int amount = __builtin_popcountll(value);
        int rank = randInt(amount);

        while (value) {
            int bit = __builtin_ctzll(value);
            value &= value - 1;
            if (rank-- == 0) return chosenWord * 64 + bit;
        }
        return -1;
    }

    bool searchIndependentDFS(
        vector<u64>& mask,
        int need,
        vector<int>& chosen,
        int& nodes,
        int limit
    ) const {
        if (need == 0) return true;

        int count = 0;
        for (u64 word : mask) count += __builtin_popcountll(word);
        if (count < need) return false;
        if (++nodes > limit) return false;

        if (need == 1) {
            for (int w = 0; w < words; ++w) {
                if (mask[w]) {
                    chosen.push_back(w * 64 + __builtin_ctzll(mask[w]));
                    return true;
                }
            }
            return false;
        }

        for (int w = 0; w < words; ++w) {
            while (mask[w]) {
                int v = w * 64 + __builtin_ctzll(mask[w]);
                mask[w] &= ~(1ULL << (v & 63));

                vector<u64> child(words);
                const u64* row = &bits[static_cast<size_t>(v) * words];
                for (int j = 0; j < words; ++j) {
                    child[j] = mask[j] & ~row[j];
                }
                child[v >> 6] &= ~(1ULL << (v & 63));

                chosen.push_back(v);
                if (searchIndependentDFS(child, need - 1, chosen, nodes, limit)) {
                    return true;
                }
                chosen.pop_back();
            }
        }
        return false;
    }

    vector<int> findIndependentSet(const vector<int>& input, int need) const {
        vector<int> pool = input;
        sort(pool.begin(), pool.end());
        pool.erase(unique(pool.begin(), pool.end()), pool.end());
        if (static_cast<int>(pool.size()) < need) return {};

        vector<u64> candidate(words, 0);
        for (int v : pool) candidate[v >> 6] |= 1ULL << (v & 63);

        vector<pair<int, u64>> order;
        order.reserve(pool.size());

        if (pool.size() <= 512) {
            for (int v : pool) {
                const u64* row = &bits[static_cast<size_t>(v) * words];
                int degree = 0;
                for (int w = 0; w < words; ++w) {
                    degree += __builtin_popcountll(row[w] & candidate[w]);
                }
                order.emplace_back(degree, static_cast<u64>(rng()));
            }
        } else {
            for (int v : pool) {
                order.emplace_back(static_cast<int>(adj[v].size()),
                                   static_cast<u64>(rng()));
            }
        }

        sort(order.begin(), order.end(), [](const auto& a, const auto& b) {
            if (a.first != b.first) return a.first < b.first;
            return a.second < b.second;
        });

        vector<int> result;
        result.reserve(need);
        for (const auto& entry : order) {
            int v = pool[static_cast<size_t>(entry.second & 0xFFFFFFFFULL)];
            bool ok = true;
            for (int u : result) {
                if (adjacentLocal(v, u)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                result.push_back(v);
                if (static_cast<int>(result.size()) == need) return result;
            }
        }

        if (pool.size() <= 512) {
            vector<u64> mask = candidate;
            vector<int> found;
            int nodes = 0;
            if (searchIndependentDFS(mask, need, found, nodes, 10000)) {
                return found;
            }
        }

        if (need == 2) {
            int attempts = min<int>(pool.size(), 128);
            for (int attempt = 0; attempt < attempts; ++attempt) {
                int v = pool[attempt];
                const u64* row = &bits[static_cast<size_t>(v) * words];
                for (int w = 0; w < words; ++w) {
                    u64 possible = candidate[w] & ~row[w];
                    possible &= ~(1ULL << (v & 63));
                    if (possible) {
                        int u = w * 64 + __builtin_ctzll(possible);
                        return {v, u};
                    }
                }
            }
        }

        for (int attempt = 0; attempt < 24; ++attempt) {
            vector<u64> eligible = candidate;
            vector<int> chosen;
            chosen.reserve(need);

            while (static_cast<int>(chosen.size()) < need) {
                int v = randomSetBit(eligible);
                if (v < 0) break;

                chosen.push_back(v);
                const u64* row = &bits[static_cast<size_t>(v) * words];
                for (int w = 0; w < words; ++w) {
                    eligible[w] &= ~row[w];
                }
                eligible[v >> 6] &= ~(1ULL << (v & 63));
            }

            if (static_cast<int>(chosen.size()) == need) return chosen;
        }

        return {};
    }

    void replaceBlockers(
        const vector<int>& blockers,
        const vector<int>& replacement,
        int iteration
    ) {
        for (int v : blockers) {
            removeVertex(v);
            tabuUntil[v] = iteration + 8 + randInt(8);
        }
        for (int v : replacement) {
            addVertex(v);
            lockedUntil[v] = iteration + 8 + randInt(8);
        }
    }

    bool trySingleBlockerReplacement() {
        vector<int> candidates;
        for (int v : selectedVertices) {
            if (privateNeighbors[v].size() >= 2) candidates.push_back(v);
        }

        sort(candidates.begin(), candidates.end(), [&](int a, int b) {
            return privateNeighbors[a].size() > privateNeighbors[b].size();
        });

        int limit = min<int>(40, candidates.size());
        for (int i = 0; i < limit; ++i) {
            int blocker = candidates[i];
            vector<int> replacement = findIndependentSet(privateNeighbors[blocker], 2);
            if (replacement.size() == 2) {
                replaceBlockers({blocker}, replacement, iteration);
                return true;
            }
        }
        return false;
    }

    bool tryTwoSingletonBlockers() {
        vector<int> candidates;
        for (int v : selectedVertices) {
            if (!privateNeighbors[v].empty()) candidates.push_back(v);
        }

        sort(candidates.begin(), candidates.end(), [&](int a, int b) {
            return privateNeighbors[a].size() > privateNeighbors[b].size();
        });
        if (candidates.size() > 70) candidates.resize(70);

        struct PairDescription {
            int a, b, size;
        };
        vector<PairDescription> pairs;

        for (int i = 0; i < static_cast<int>(candidates.size()); ++i) {
            for (int j = i + 1; j < static_cast<int>(candidates.size()); ++j) {
                int a = candidates[i];
                int b = candidates[j];
                int size = static_cast<int>(privateNeighbors[a].size() +
                                           privateNeighbors[b].size());
                if (size >= 3) pairs.push_back({a, b, size});
            }
        }

        sort(pairs.begin(), pairs.end(), [](const auto& a, const auto& b) {
            return a.size > b.size;
        });

        int limit = min<int>(24, pairs.size());
        for (int i = 0; i < limit; ++i) {
            vector<int> pool = privateNeighbors[pairs[i].a];
            pool.insert(pool.end(),
                        privateNeighbors[pairs[i].b].begin(),
                        privateNeighbors[pairs[i].b].end());

            vector<int> replacement = findIndependentSet(pool, 3);
            if (replacement.size() == 3) {
                replaceBlockers({pairs[i].a, pairs[i].b}, replacement, iteration);
                return true;
            }
        }
        return false;
    }

    bool tryGroupedReplacement() {
        array<unordered_map<u128, vector<int>, U128Hash>, MAX_K + 1> groups;

        for (int k = 2; k <= MAX_K; ++k) {
            groups[k].max_load_factor(0.7f);
            groups[k].reserve(countBucket[k].size() * 2 + 1);

            for (int v : countBucket[k]) {
                array<int, MAX_K> blockers = smallBlockers[v];
                sort(blockers.begin(), blockers.begin() + k);
                u128 key = encodeKey(blockers, k);
                groups[k][key].push_back(v);
            }
        }

        for (int k = 2; k <= MAX_K; ++k) {
            vector<GroupDescription> descriptions;
            descriptions.reserve(groups[k].size());

            for (const auto& entry : groups[k]) {
                vector<int> blockers = decodeKey(entry.first, k);
                int poolSize = static_cast<int>(entry.second.size());

                for (int blocker : blockers) {
                    poolSize += static_cast<int>(privateNeighbors[blocker].size());
                }

                for (int mask = 1; mask < (1 << k); ++mask) {
                    int subsetSize = __builtin_popcount(static_cast<unsigned>(mask));
                    if (subsetSize < 2 || subsetSize >= k) continue;

                    vector<int> subset;
                    for (int i = 0; i < k; ++i) {
                        if (mask & (1 << i)) subset.push_back(blockers[i]);
                    }
                    u128 key = encodeKey(subset);
                    auto it = groups[subsetSize].find(key);
                    if (it != groups[subsetSize].end()) {
                        poolSize += static_cast<int>(it->second.size());
                    }
                }

                if (poolSize >= k + 1) {
                    descriptions.push_back({entry.first, poolSize});
                }
            }

            sort(descriptions.begin(), descriptions.end(),
                 [](const auto& a, const auto& b) {
                     return a.poolSize > b.poolSize;
                 });

            int limit;
            if (k == 2) limit = 20;
            else if (k == 3) limit = 14;
            else if (k == 4) limit = 10;
            else limit = 8;
            limit = min(limit, static_cast<int>(descriptions.size()));

            for (int d = 0; d < limit; ++d) {
                vector<int> blockers = decodeKey(descriptions[d].key, k);
                vector<int> pool = groups[k].at(descriptions[d].key);

                for (int blocker : blockers) {
                    const auto& p = privateNeighbors[blocker];
                    pool.insert(pool.end(), p.begin(), p.end());
                }

                for (int mask = 1; mask < (1 << k); ++mask) {
                    int subsetSize = __builtin_popcount(static_cast<unsigned>(mask));
                    if (subsetSize < 2 || subsetSize >= k) continue;

                    vector<int> subset;
                    for (int i = 0; i < k; ++i) {
                        if (mask & (1 << i)) subset.push_back(blockers[i]);
                    }
                    u128 key = encodeKey(subset);
                    auto it = groups[subsetSize].find(key);
                    if (it != groups[subsetSize].end()) {
                        const auto& p = it->second;
                        pool.insert(pool.end(), p.begin(), p.end());
                    }
                }

                vector<int> replacement = findIndependentSet(pool, k + 1);
                if (replacement.size() == k + 1) {
                    replaceBlockers(blockers, replacement, iteration);
                    return true;
                }
            }

            if (k == 2 && tryTwoSingletonBlockers()) return true;
        }

        return false;
    }

    bool tryReplacement() {
        if (trySingleBlockerReplacement()) return true;
        return tryGroupedReplacement();
    }

    void rebuildFrom(const vector<char>& state) {
        selected = state;

        for (auto& bucket : countBucket) bucket.clear();
        for (auto& bucket : privateNeighbors) bucket.clear();

        fill(countPosition.begin(), countPosition.end(), -1);
        fill(privatePosition.begin(), privatePosition.end(), -1);
        fill(selectedPosition.begin(), selectedPosition.end(), -1);
        selectedVertices.clear();

        for (int v = 0; v < n; ++v) {
            conflictCount[v] = 0;
            smallBlockers[v].fill(-1);
            tabuUntil[v] = 0;
            lockedUntil[v] = 0;

            if (selected[v]) {
                selectedPosition[v] = static_cast<int>(selectedVertices.size());
                selectedVertices.push_back(v);
                continue;
            }

            int count = 0;
            for (int u : adj[v]) {
                if (selected[u]) {
                    if (count < MAX_K) smallBlockers[v][count] = u;
                    ++count;
                }
            }
            conflictCount[v] = count;

            if (count <= MAX_K) insertCountBucket(v, count);
            if (count == 1) insertPrivate(v, smallBlockers[v][0]);
        }
    }

public:
    int iteration = 0;

    LocalOptimizer(
        const vector<vector<int>>& adjacency,
        const vector<char>& initial
    ) : adj(adjacency), n(static_cast<int>(adjacency.size())) {
        words = (n + 63) / 64;
        bits.assign(static_cast<size_t>(n) * words, 0);

        for (int u = 0; u < n; ++u) {
            for (int v : adj[u]) {
                bits[static_cast<size_t>(u) * words + (v >> 6)] |=
                    1ULL << (v & 63);
            }
        }

        selected.assign(n, false);
        conflictCount.assign(n, 0);
        smallBlockers.resize(n);
        countBucket.resize(MAX_K + 1);
        countPosition.assign(n, -1);
        privateNeighbors.resize(n);
        privatePosition.assign(n, -1);
        selectedPosition.assign(n, -1);
        tabuUntil.assign(n, 0);
        lockedUntil.assign(n, 0);

        rebuildFrom(initial);
    }

    vector<char> run(
        int maxIterations,
        chrono::steady_clock::time_point deadline
    ) {
        vector<char> best = selected;
        int bestSize = static_cast<int>(selectedVertices.size());

        for (iteration = 1; iteration <= maxIterations; ++iteration) {
            if ((iteration & 31) == 0 &&
                chrono::steady_clock::now() >= deadline) {
                break;
            }

            if (tryReplacement()) {
                int currentSize = static_cast<int>(selectedVertices.size());
                if (currentSize > bestSize) {
                    bestSize = currentSize;
                    best = selected;
                }
                continue;
            }

            if (!countBucket[0].empty()) {
                int v = countBucket[0][randInt(static_cast<int>(countBucket[0].size()))];
                addVertex(v);
                lockedUntil[v] = iteration + 8 + randInt(8);

                int currentSize = static_cast<int>(selectedVertices.size());
                if (currentSize > bestSize) {
                    bestSize = currentSize;
                    best = selected;
                }
                continue;
            }

            bool moved = false;
            for (int attempt = 0; attempt < 24 && !countBucket[1].empty(); ++attempt) {
                int v = countBucket[1][randInt(static_cast<int>(countBucket[1].size()))];
                int blocker = smallBlockers[v][0];

                if (tabuUntil[v] > iteration || lockedUntil[blocker] > iteration) {
                    continue;
                }

                removeVertex(blocker);
                tabuUntil[blocker] = iteration + 8 + randInt(8);
                addVertex(v);
                lockedUntil[v] = iteration + 8 + randInt(8);
                moved = true;
                break;
            }
            if (moved) continue;

            bool perturbed = false;
            for (int k = 2; k <= MAX_K; ++k) {
                if (countBucket[k].empty()) continue;

                int v = countBucket[k][randInt(static_cast<int>(countBucket[k].size()))];
                vector<int> blockers;
                for (int i = 0; i < k; ++i) blockers.push_back(smallBlockers[v][i]);

                for (int blocker : blockers) {
                    removeVertex(blocker);
                    tabuUntil[blocker] = iteration + 12 + randInt(12);
                }
                addVertex(v);
                lockedUntil[v] = iteration + 12 + randInt(12);
                perturbed = true;
                break;
            }

            if (!perturbed && !selectedVertices.empty()) {
                int v = selectedVertices[randInt(static_cast<int>(selectedVertices.size()))];
                removeVertex(v);
                tabuUntil[v] = iteration + 12 + randInt(12);
            } else if (!perturbed) {
                break;
            }
        }

        return best;
    }
};

int main() {
    using Clock = chrono::steady_clock;
    const auto start = Clock::now();
    const auto preprocessingDeadline = start + chrono::milliseconds(300);
    const auto initializationDeadline = start + chrono::milliseconds(1450);
    const auto hardDeadline = start + chrono::milliseconds(1820);

    FastScanner scanner;
    int N = scanner.nextInt();
    int M = scanner.nextInt();
    if (N <= 0) return 0;

    const int globalWords = (N + 63) / 64;
    vector<vector<u64>> adjacencyMatrix(
        N, vector<u64>(globalWords, 0)
    );
    vector<vector<int>> graph(N);

    for (int i = 0; i < M; ++i) {
        int u = scanner.nextInt() - 1;
        int v = scanner.nextInt() - 1;

        u64 mask = 1ULL << (v & 63);
        if ((adjacencyMatrix[u][v >> 6] & mask) == 0) {
            adjacencyMatrix[u][v >> 6] |= mask;
            adjacencyMatrix[v][u >> 6] |= 1ULL << (u & 63);
            graph[u].push_back(v);
            graph[v].push_back(u);
        }
    }

    vector<char> chosen(N, false);
    vector<char> active(N, true);
    vector<u64> activeMask(globalWords, ~0ULL);
    if (N & 63) activeMask.back() = (1ULL << (N & 63)) - 1;

    vector<int> reductionQueue;
    reductionQueue.reserve(N);
    vector<char> inQueue(N, true);
    for (int v = 0; v < N; ++v) reductionQueue.push_back(v);

    auto enqueue = [&](int v) {
        if (active[v] && !inQueue[v]) {
            inQueue[v] = true;
            reductionQueue.push_back(v);
        }
    };

    auto deactivate = [&](int v) {
        if (!active[v]) return;
        active[v] = false;
        activeMask[v >> 6] &= ~(1ULL << (v & 63));
        inQueue[v] = false;

        for (int u : graph[v]) {
            if (active[u]) enqueue(u);
        }
    };

    size_t queueHead = 0;
    vector<int> activeNeighbors;

    while (queueHead < reductionQueue.size()) {
        if ((queueHead & 2047) == 0 &&
            Clock::now() >= preprocessingDeadline) {
            break;
        }

        int v = reductionQueue[queueHead++];
        inQueue[v] = false;
        if (!active[v]) continue;

        activeNeighbors.clear();
        for (int u : graph[v]) {
            if (active[u]) activeNeighbors.push_back(u);
        }

        int degree = static_cast<int>(activeNeighbors.size());
        if (degree <= 1) {
            int neighbor = degree == 1 ? activeNeighbors[0] : -1;
            chosen[v] = true;
            deactivate(v);
            if (neighbor >= 0) deactivate(neighbor);
            continue;
        }

        bool simplicial = degree <= 64;
        if (simplicial) {
            for (int u : activeNeighbors) {
                for (int w : activeNeighbors) {
                    if (u != w && !adjacent(adjacencyMatrix, u, w)) {
                        simplicial = false;
                        break;
                    }
                }
                if (!simplicial) break;
            }
        }

        if (simplicial) {
            vector<int> neighbors = activeNeighbors;
            chosen[v] = true;
            deactivate(v);
            for (int u : neighbors) deactivate(u);
        }
    }

    vector<char> visited(N, false);
    vector<vector<int>> components;

    for (int root = 0; root < N; ++root) {
        if (!active[root] || visited[root]) continue;

        vector<int> component;
        component.push_back(root);
        visited[root] = true;

        for (size_t head = 0; head < component.size(); ++head) {
            int v = component[head];
            for (int u : graph[v]) {
                if (active[u] && !visited[u]) {
                    visited[u] = true;
                    component.push_back(u);
                }
            }
        }
        components.push_back(move(component));
    }

    vector<int> localIndex(N, -1);
    vector<int> color(N, -1);
    vector<GeneralComponent> generalComponents;

    for (const auto& component : components) {
        int size = static_cast<int>(component.size());
        int edgeCount = 0;

        for (int v : component) {
            for (int u : graph[v]) {
                if (active[u]) ++edgeCount;
            }
        }
        edgeCount /= 2;

        if (size == 1) {
            chosen[component[0]] = true;
            continue;
        }

        if (edgeCount == size - 1) {
            vector<int> parent(N, -2);
            vector<int> order;
            order.reserve(size);
            parent[component[0]] = -1;
            order.push_back(component[0]);

            for (size_t i = 0; i < order.size(); ++i) {
                int v = order[i];
                for (int u : graph[v]) {
                    if (!active[u] || u == parent[v]) continue;
                    parent[u] = v;
                    order.push_back(u);
                }
            }

            vector<int> dp0(N, 0), dp1(N, 1);
            for (int i = size - 1; i >= 0; --i) {
                int v = order[i];
                for (int u : graph[v]) {
                    if (!active[u] || parent[u] != v) continue;
                    dp0[v] += max(dp0[u], dp1[u]);
                    dp1[v] += dp0[u];
                }
            }

            vector<char> take(N, false);
            for (int v : order) {
                if (parent[v] == -1) {
                    take[v] = dp1[v] > dp0[v];
                } else {
                    int p = parent[v];
                    take[v] = !take[p] && dp1[v] > dp0[v];
                }
                if (take[v]) chosen[v] = true;
            }
            continue;
        }

        bool bipartite = true;
        vector<int> leftVertices, rightVertices;

        for (int root : component) {
            if (color[root] != -1) continue;

            vector<int> queue;
            queue.push_back(root);
            color[root] = 0;

            for (size_t head = 0; head < queue.size(); ++head) {
                int v = queue[head];
                if (color[v] == 0) leftVertices.push_back(v);
                else rightVertices.push_back(v);

                for (int u : graph[v]) {
                    if (!active[u]) continue;
                    if (color[u] == -1) {
                        color[u] = color[v] ^ 1;
                        queue.push_back(u);
                    } else if (color[u] == color[v]) {
                        bipartite = false;
                    }
                }
            }
        }

        if (bipartite) {
            HopcroftKarp matching(graph, leftVertices, rightVertices);
            matching.solve();

            vector<char> reachableLeft(N, false);
            vector<char> reachableRight(N, false);
            queue<int> q;

            for (int u : leftVertices) {
                if (matching.pairLeft[u] == -1) {
                    reachableLeft[u] = true;
                    q.push(u);
                }
            }

            while (!q.empty()) {
                int u = q.front();
                q.pop();

                for (int v : graph[u]) {
                    if (matching.pairLeft[u] == v || reachableRight[v]) continue;
                    reachableRight[v] = true;

                    int next = matching.pairRight[v];
                    if (next != -1 && !reachableLeft[next]) {
                        reachableLeft[next] = true;
                        q.push(next);
                    }
                }
            }

            for (int u : leftVertices) {
                if (reachableLeft[u]) chosen[u] = true;
            }
            for (int v : rightVertices) {
                if (!reachableRight[v]) chosen[v] = true;
            }
            continue;
        }

        if (edgeCount == size * (size - 1) / 2) {
            chosen[component[0]] = true;
            continue;
        }

        if (size <= 64) {
            for (int i = 0; i < size; ++i) {
                localIndex[component[i]] = i;
            }

            vector<u64> original(size, 0);
            for (int i = 0; i < size; ++i) {
                int v = component[i];
                for (int u : graph[v]) {
                    int j = localIndex[u];
                    if (j >= 0) original[i] |= 1ULL << j;
                }
            }

            MaxClique64 solver(size, original);
            solver.solve();
            for (int i = 0; i < size; ++i) {
                if ((solver.bestMask >> i) & 1ULL) chosen[component[i]] = true;
            }
            continue;
        }

        GeneralComponent gc;
        gc.vertices = component;
        gc.adj.resize(size);
        gc.edgeCount = edgeCount;

        for (int i = 0; i < size; ++i) {
            localIndex[component[i]] = i;
        }
        for (int i = 0; i < size; ++i) {
            for (int u : graph[component[i]]) {
                int j = localIndex[u];
                if (j >= 0) gc.adj[i].push_back(j);
            }
        }

        generalComponents.push_back(move(gc));
    }

    for (auto& component : generalComponents) {
        int size = static_cast<int>(component.vertices.size());
        int target = size < 300 ? 40 : (size < 1200 ? 32 : 24);

        int bestSize = -1;
        int alternativeSize = -1;

        for (int attempt = 0; attempt < target; ++attempt) {
            if (attempt > 0 && Clock::now() >= initializationDeadline) break;

            vector<char> candidate;
            if (attempt % 4 == 3) {
                candidate = greedyRandomOrder(component);
            } else {
                int mode = (attempt % 4 == 2) ? 1 : 0;
                candidate = greedyMinimumDegree(component, mode, mode != 0);
            }

            int count = accumulate(candidate.begin(), candidate.end(), 0);

            if (count > bestSize) {
                alternativeSize = bestSize;
                if (component.alternative.size() == static_cast<size_t>(bestSize)) {
                    component.alternative = component.best;
                }
                bestSize = count;
                component.best = move(candidate);
            } else if (count > alternativeSize) {
                alternativeSize = count;
                component.alternative = move(candidate);
            }
        }

        if (component.best.empty()) {
            component.best = greedyMinimumDegree(component, 0, false);
        }
        if (component.alternative.empty()) {
            component.alternative = component.best;
        }
    }

    double remainingWeight = 0;
    for (const auto& component : generalComponents) {
        remainingWeight += max(1, static_cast<int>(component.vertices.size()));
    }

    for (auto& component : generalComponents) {
        if (Clock::now() >= hardDeadline) break;

        double weight = max(1, static_cast<int>(component.vertices.size()));
        double available = chrono::duration<double>(
            hardDeadline - Clock::now()
        ).count();
        available = max(0.0, available);

        double slice = remainingWeight > 0
            ? available * weight / remainingWeight
            : available;

        auto componentDeadline = Clock::now() +
            chrono::duration_cast<Clock::duration>(duration<double>(slice));

        LocalOptimizer optimizer(component.adj, component.best);
        vector<char> result = optimizer.run(30000, componentDeadline);

        if (Clock::now() < componentDeadline &&
            component.alternative != component.best) {
            LocalOptimizer second(component.adj, component.alternative);
            vector<char> other = second.run(30000, componentDeadline);
            if (accumulate(other.begin(), other.end(), 0) >
                accumulate(result.begin(), result.end(), 0)) {
                result = move(other);
            }
        }

        for (int i = 0; i < static_cast<int>(component.vertices.size()); ++i) {
            chosen[component.vertices[i]] = result[i];
        }

        remainingWeight -= weight;
    }

    queue<int> conflictQueue;
    for (int v = 0; v < N; ++v) {
        if (chosen[v]) conflictQueue.push(v);
    }

    while (!conflictQueue.empty()) {
        int v = conflictQueue.front();
        conflictQueue.pop();
        if (!chosen[v]) continue;

        for (int u : graph[v]) {
            if (!chosen[u]) continue;

            if (graph[v].size() >= graph[u].size()) {
                chosen[v] = false;
                break;
            } else {
                chosen[u] = false;
                conflictQueue.push(u);
            }
        }
    }

    string output;
    output.reserve(static_cast<size_t>(N) * 2);
    for (int v = 0; v < N; ++v) {
        output.push_back(chosen[v] ? '1' : '0');
        output.push_back('\n');
    }
    fwrite(output.data(), 1, output.size(), stdout);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<pair<int, int>> clauses(m);
    auto literalOf = [](int a) {
        int v = abs(a) - 1;
        return 2 * v + (a < 0);
    };

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        clauses[i] = {literalOf(a), literalOf(b)};
    }

    if (m == 0) {
        for (int i = 0; i < n; ++i) {
            if (i) cout << ' ';
            cout << 0;
        }
        cout << '\n';
        return 0;
    }

    // First check whether all clauses can be satisfied using 2-SAT.
    int N = 2 * n;
    vector<vector<int>> g(N), rg(N);
    auto addImplication = [&](int a, int b) {
        g[a].push_back(b);
        rg[b].push_back(a);
    };

    for (auto [a, b] : clauses) {
        addImplication(a ^ 1, b);
        addImplication(b ^ 1, a);
    }

    vector<int> order;
    order.reserve(N);
    vector<char> used(N, 0);

    function<void(int)> dfs1 = [&](int v) {
        used[v] = 1;
        for (int to : g[v]) {
            if (!used[to]) dfs1(to);
        }
        order.push_back(v);
    };

    for (int v = 0; v < N; ++v) {
        if (!used[v]) dfs1(v);
    }

    vector<int> comp(N, -1);
    function<void(int, int)> dfs2 = [&](int v, int id) {
        comp[v] = id;
        for (int to : rg[v]) {
            if (comp[to] == -1) dfs2(to, id);
        }
    };

    int componentCount = 0;
    for (int i = N - 1; i >= 0; --i) {
        int v = order[i];
        if (comp[v] == -1) dfs2(v, componentCount++);
    }

    bool satisfiable = true;
    for (int i = 0; i < n; ++i) {
        if (comp[2 * i] == comp[2 * i + 1]) {
            satisfiable = false;
            break;
        }
    }

    if (satisfiable) {
        vector<uint8_t> answer(n);
        for (int i = 0; i < n; ++i) {
            answer[i] = comp[2 * i] > comp[2 * i + 1];
        }

        bool verified = true;
        for (auto [a, b] : clauses) {
            int va = answer[a >> 1] ^ (a & 1);
            int vb = answer[b >> 1] ^ (b & 1);
            if (!(va | vb)) {
                verified = false;
                break;
            }
        }

        if (verified) {
            for (int i = 0; i < n; ++i) {
                if (i) cout << ' ';
                cout << int(answer[i]);
            }
            cout << '\n';
            return 0;
        }
    }

    // Incremental local search for the unsatisfiable case.
    vector<vector<int>> adj(n);
    for (int c = 0; c < m; ++c) {
        int v1 = clauses[c].first >> 1;
        int v2 = clauses[c].second >> 1;
        adj[v1].push_back(c);
        if (v2 != v1) adj[v2].push_back(c);
    }

    mt19937 rng(0xC0FFEE);
    vector<uint8_t> x(n), bestAssignment(n);
    vector<int> satCount(m), unsat, positionInUnsat(m, -1);
    int currentScore = 0, bestScore = -1;

    auto literalValue = [&](int lit) -> int {
        return int(x[lit >> 1]) ^ (lit & 1);
    };

    auto addUnsat = [&](int c) {
        positionInUnsat[c] = int(unsat.size());
        unsat.push_back(c);
    };

    auto removeUnsat = [&](int c) {
        int p = positionInUnsat[c];
        int last = unsat.back();
        unsat[p] = last;
        positionInUnsat[last] = p;
        unsat.pop_back();
        positionInUnsat[c] = -1;
    };

    auto rebuild = [&]() {
        unsat.clear();
        fill(positionInUnsat.begin(), positionInUnsat.end(), -1);
        for (int c = 0; c < m; ++c) {
            int s = literalValue(clauses[c].first) +
                    literalValue(clauses[c].second);
            satCount[c] = s;
            if (s == 0) addUnsat(c);
        }
        currentScore = m - int(unsat.size());
    };

    auto updateBest = [&]() {
        if (currentScore > bestScore) {
            bestScore = currentScore;
            bestAssignment = x;
        }
    };

    auto calculateGain = [&](int v) {
        int delta = 0;
        for (int c : adj[v]) {
            int before = satCount[c];
            int after = before;

            int a = clauses[c].first;
            int b = clauses[c].second;
            if ((a >> 1) == v) after += literalValue(a) ? -1 : 1;
            if ((b >> 1) == v) after += literalValue(b) ? -1 : 1;

            if (before == 0 && after > 0) ++delta;
            else if (before > 0 && after == 0) --delta;
        }
        return delta;
    };

    auto flip = [&](int v) {
        x[v] ^= 1;
        for (int c : adj[v]) {
            int before = satCount[c];
            int after = literalValue(clauses[c].first) +
                        literalValue(clauses[c].second);
            satCount[c] = after;

            if (before == 0 && after > 0) {
                removeUnsat(c);
                ++currentScore;
            } else if (before > 0 && after == 0) {
                addUnsat(c);
                --currentScore;
            }
        }
    };

    auto startTime = chrono::steady_clock::now();
    const double TIME_LIMIT = 0.80;
    auto timeUp = [&]() {
        return chrono::duration<double>(
                   chrono::steady_clock::now() - startTime
               ).count() >= TIME_LIMIT;
    };

    vector<int> seen(n, 0);
    int seenToken = 0;

    struct QueueNode {
        int gain, variable, version;
        bool operator<(const QueueNode& other) const {
            return gain < other.gain;
        }
    };

    auto greedyAscent = [&]() {
        priority_queue<QueueNode> pq;
        vector<int> gains(n), versions(n, 0);

        for (int v = 0; v < n; ++v) {
            gains[v] = calculateGain(v);
            pq.push({gains[v], v, 0});
        }

        vector<int> affected;
        long long flips = 0;

        while (!pq.empty()) {
            if ((flips & 31) == 0 && timeUp()) return;

            QueueNode node = pq.top();
            pq.pop();

            int v = node.variable;
            if (node.version != versions[v] || node.gain != gains[v]) continue;
            if (node.gain <= 0) break;

            flip(v);
            updateBest();

            affected.clear();
            ++seenToken;
            auto touch = [&](int u) {
                if (seen[u] != seenToken) {
                    seen[u] = seenToken;
                    affected.push_back(u);
                }
            };

            touch(v);
            for (int c : adj[v]) {
                touch(clauses[c].first >> 1);
                touch(clauses[c].second >> 1);
            }

            for (int u : affected) {
                gains[u] = calculateGain(u);
                ++versions[u];
                pq.push({gains[u], u, versions[u]});
            }

            ++flips;
        }
    };

    // Try several inexpensive starting assignments.
    vector<int> positive(n, 0), negative(n, 0);
    for (auto [a, b] : clauses) {
        for (int lit : {a, b}) {
            if (lit & 1) ++negative[lit >> 1];
            else ++positive[lit >> 1];
        }
    }

    for (int v = 0; v < n; ++v) x[v] = positive[v] >= negative[v];
    rebuild();
    updateBest();

    fill(x.begin(), x.end(), 0);
    rebuild();
    updateBest();

    fill(x.begin(), x.end(), 1);
    rebuild();
    updateBest();

    for (int rep = 0; rep < 4; ++rep) {
        for (int v = 0; v < n; ++v) x[v] = rng() & 1;
        rebuild();
        updateBest();
    }

    x = bestAssignment;
    rebuild();
    if (!timeUp()) greedyAscent();

    x = bestAssignment;
    rebuild();

    long long iterations = 0;
    long long sinceImprovement = 0;
    long long restarts = 0;
    const long long maxIterations = max(300000LL, 3000LL * n);
    const long long stagnationLimit = max(20000LL, 40LL * n);

    while (iterations < maxIterations) {
        if ((iterations & 1023) == 0 && timeUp()) break;
        if (unsat.empty()) {
            updateBest();
            break;
        }

        if (sinceImprovement >= stagnationLimit) {
            ++restarts;

            if (restarts % 6 == 0) {
                for (int v = 0; v < n; ++v) x[v] = rng() & 1;
                rebuild();
                updateBest();
            } else {
                x = bestAssignment;
                rebuild();

                int range = max(1, n / 10);
                int perturbations = 1 + int(rng() % range);
                for (int j = 0; j < perturbations; ++j) {
                    flip(int(rng() % n));
                }
                updateBest();
            }

            if (restarts % 3 == 0 && !timeUp()) greedyAscent();
            sinceImprovement = 0;
            continue;
        }

        int c = unsat[rng() % unsat.size()];
        int a = clauses[c].first;
        int b = clauses[c].second;
        int v1 = a >> 1;
        int v2 = b >> 1;
        int chosen;

        int noise = 150 + int(350LL * min(sinceImprovement, stagnationLimit) /
                              stagnationLimit);

        if (v1 == v2) {
            chosen = v1;
        } else if (int(rng() % 1000) < noise) {
            chosen = (rng() & 1) ? v1 : v2;
        } else {
            int g1 = calculateGain(v1);
            int g2 = calculateGain(v2);
            if (g1 > g2) chosen = v1;
            else if (g2 > g1) chosen = v2;
            else chosen = (rng() & 1) ? v1 : v2;
        }

        flip(chosen);

        if (currentScore > bestScore) {
            updateBest();
            sinceImprovement = 0;
        } else {
            ++sinceImprovement;
        }

        ++iterations;
    }

    for (int i = 0; i < n; ++i) {
        if (i) cout << ' ';
        cout << int(bestAssignment[i]);
    }
    cout << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Clause {
    int a, b;
};

struct RNG {
    uint64_t x = 0x9e3779b97f4a7c15ULL;
    uint64_t next() {
        x ^= x << 7;
        x ^= x >> 9;
        return x;
    }
    int get(int bound) {
        return bound <= 1 ? 0 : int(next() % uint64_t(bound));
    }
};

static int varOf(int lit) {
    return abs(lit) - 1;
}

static int nodeOf(int lit) {
    int v = varOf(lit);
    return 2 * v + (lit < 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<Clause> clauses(m);
    vector<vector<int>> graph(2 * n), revGraph(2 * n);

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        clauses[i] = {a, b};

        int na = nodeOf(a), nb = nodeOf(b);
        int nna = na ^ 1, nnb = nb ^ 1;
        graph[nna].push_back(nb);
        revGraph[nb].push_back(nna);
        graph[nnb].push_back(na);
        revGraph[na].push_back(nnb);
    }

    auto printAnswer = [&](const vector<int>& assignment) {
        for (int i = 0; i < n; ++i) {
            if (i) cout << ' ';
            cout << assignment[i];
        }
        cout << '\n';
    };

    if (m == 0) {
        printAnswer(vector<int>(n, 0));
        return 0;
    }

    // First check whether the formula is fully satisfiable.
    vector<int> order, comp(2 * n, -1);
    order.reserve(2 * n);
    vector<int> iter(2 * n, 0), st;
    vector<char> visited(2 * n, 0);

    for (int s = 0; s < 2 * n; ++s) {
        if (visited[s]) continue;
        visited[s] = 1;
        st = {s};
        while (!st.empty()) {
            int v = st.back();
            if (iter[v] < int(graph[v].size())) {
                int to = graph[v][iter[v]++];
                if (!visited[to]) {
                    visited[to] = 1;
                    st.push_back(to);
                }
            } else {
                order.push_back(v);
                st.pop_back();
            }
        }
    }

    int componentCount = 0;
    for (int oi = int(order.size()) - 1; oi >= 0; --oi) {
        int s = order[oi];
        if (comp[s] != -1) continue;
        st = {s};
        comp[s] = componentCount;
        while (!st.empty()) {
            int v = st.back();
            st.pop_back();
            for (int to : revGraph[v]) {
                if (comp[to] == -1) {
                    comp[to] = componentCount;
                    st.push_back(to);
                }
            }
        }
        ++componentCount;
    }

    bool satisfiable = true;
    for (int i = 0; i < n; ++i) {
        if (comp[2 * i] == comp[2 * i + 1]) {
            satisfiable = false;
            break;
        }
    }

    if (satisfiable) {
        vector<int> answer(n);
        for (int i = 0; i < n; ++i) {
            answer[i] = comp[2 * i] > comp[2 * i + 1];
        }
        printAnswer(answer);
        return 0;
    }

    auto startTime = chrono::steady_clock::now();
    auto timeExpired = [&]() {
        return chrono::duration<double>(chrono::steady_clock::now() - startTime).count() > 0.90;
    };

    RNG rng;
    vector<vector<int>> incident(n);
    vector<int> positiveCount(n, 0), negativeCount(n, 0);

    for (int i = 0; i < m; ++i) {
        int a = clauses[i].a, b = clauses[i].b;
        int va = varOf(a), vb = varOf(b);
        incident[va].push_back(i);
        if (vb != va) incident[vb].push_back(i);
        if (a > 0) ++positiveCount[va]; else ++negativeCount[va];
        if (b > 0) ++positiveCount[vb]; else ++negativeCount[vb];
    }

    vector<int> active;
    for (int i = 0; i < n; ++i) {
        if (!incident[i].empty()) active.push_back(i);
    }

    vector<int> value(n, 0), satCount(m, 0), gain(n, 0), tabu(n, 0);
    vector<int> mark(n, 0);
    int markStamp = 0;
    int score = 0;

    auto literalTrue = [&](int lit) {
        int v = varOf(lit);
        return value[v] == (lit > 0 ? 1 : 0);
    };

    auto changeInTrueLiterals = [&](int ci, int v) {
        int delta = 0;
        int a = clauses[ci].a, b = clauses[ci].b;
        if (varOf(a) == v) delta += literalTrue(a) ? -1 : 1;
        if (varOf(b) == v) delta += literalTrue(b) ? -1 : 1;
        return delta;
    };

    auto computeGain = [&](int v) {
        int result = 0;
        for (int ci : incident[v]) {
            int before = satCount[ci];
            int after = before + changeInTrueLiterals(ci, v);
            result += int(after > 0) - int(before > 0);
        }
        return result;
    };

    auto initializeState = [&]() {
        score = 0;
        for (int i = 0; i < m; ++i) {
            int cnt = int(literalTrue(clauses[i].a)) + int(literalTrue(clauses[i].b));
            satCount[i] = cnt;
            score += cnt > 0;
        }
        for (int v : active) gain[v] = computeGain(v);
        fill(tabu.begin(), tabu.end(), 0);
    };

    auto evaluate = [&](const vector<int>& assignment) {
        int result = 0;
        for (const Clause& c : clauses) {
            bool ta = assignment[varOf(c.a)] == (c.a > 0 ? 1 : 0);
            bool tb = assignment[varOf(c.b)] == (c.b > 0 ? 1 : 0);
            result += ta || tb;
        }
        return result;
    };

    vector<int> bestAssignment(n, 0), majority(n, 0);
    for (int i = 0; i < n; ++i) {
        majority[i] = positiveCount[i] >= negativeCount[i];
    }

    int bestScore = evaluate(bestAssignment);
    bestAssignment = vector<int>(n, 0);

    int majorityScore = evaluate(majority);
    if (majorityScore > bestScore) {
        bestScore = majorityScore;
        bestAssignment = majority;
    }

    auto flipVariable = [&](int v) {
        for (int ci : incident[v]) {
            int before = satCount[ci];
            int after = before + changeInTrueLiterals(ci, v);
            satCount[ci] = after;
            score += int(after > 0) - int(before > 0);
        }
        value[v] ^= 1;

        vector<int> affected;
        ++markStamp;
        auto addAffected = [&](int u) {
            if (mark[u] != markStamp) {
                mark[u] = markStamp;
                affected.push_back(u);
            }
        };

        addAffected(v);
        for (int ci : incident[v]) {
            addAffected(varOf(clauses[ci].a));
            addAffected(varOf(clauses[ci].b));
        }
        for (int u : affected) gain[u] = computeGain(u);
    };

    int run = 0;
    while (!timeExpired()) {
        if (run == 0) {
            value = majority;
        } else if (run % 3 == 0) {
            value = bestAssignment;
            int perturbations = max(1, n / 20);
            for (int j = 0; j < perturbations && !active.empty(); ++j) {
                value[active[rng.get(int(active.size()))]] ^= 1;
            }
        } else {
            for (int i = 0; i < n; ++i) value[i] = int(rng.next() & 1ULL);
        }

        initializeState();
        if (score > bestScore) {
            bestScore = score;
            bestAssignment = value;
        }

        int noImprovement = 0;
        for (int step = 1; ; ++step) {
            if ((step & 127) == 0 && timeExpired()) break;

            int chosen = -1;
            int chosenGain = INT_MIN;

            for (int v : active) {
                if (tabu[v] > step && score + gain[v] <= bestScore) continue;
                int g = gain[v];
                if (g > chosenGain || (g == chosenGain && chosen != -1 && (rng.next() & 1ULL))) {
                    chosen = v;
                    chosenGain = g;
                }
            }

            if (chosen == -1) {
                if (active.empty()) break;
                chosen = active[rng.get(int(active.size()))];
            }

            flipVariable(chosen);
            int tenure = 4 + rng.get(10) + min(8, noImprovement / 1000);
            tabu[chosen] = step + tenure;

            if (score > bestScore) {
                bestScore = score;
                bestAssignment = value;
                noImprovement = 0;
            } else {
                ++noImprovement;
            }

            if (noImprovement > 5000) break;
        }

        ++run;
    }

    printAnswer(bestAssignment);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, m;
vector<int> V0, V1, D0, D1;
vector<vector<int>> vc;

uint32_t rng_state;

inline uint32_t rnd() {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

inline int contrib(int c, int w, int sat, const vector<int>& val) {
    int d = 0;
    if (V0[c] == w) {
        int old = (val[w] == D0[c]);
        d += old ? -1 : 1;
    }
    if (V1[c] == w) {
        int old = (val[w] == D1[c]);
        d += old ? -1 : 1;
    }
    int newCnt = sat + d;
    return (newCnt > 0) - (sat > 0);
}

int computeAll(vector<int>& val, vector<int>& satCnt, vector<int>& delta) {
    fill(delta.begin(), delta.end(), 0);
    int total = 0;
    for (int c = 0; c < m; ++c) {
        int cnt = (val[V0[c]] == D0[c]) + (val[V1[c]] == D1[c]);
        satCnt[c] = cnt;
        if (cnt > 0) ++total;
    }
    for (int c = 0; c < m; ++c) {
        int a = V0[c], b = V1[c];
        int s = satCnt[c];
        delta[a] += contrib(c, a, s, val);
        if (b != a) delta[b] += contrib(c, b, s, val);
    }
    return total;
}

void flipVar(int v, vector<int>& val, vector<int>& satCnt, vector<int>& delta, int& total) {
    for (int c : vc[v]) {
        int a = V0[c], b = V1[c];
        int s = satCnt[c];
        delta[a] -= contrib(c, a, s, val);
        if (b != a) delta[b] -= contrib(c, b, s, val);
    }

    val[v] ^= 1;

    for (int c : vc[v]) {
        int oldSat = (satCnt[c] > 0);
        int cnt = (val[V0[c]] == D0[c]) + (val[V1[c]] == D1[c]);
        satCnt[c] = cnt;
        int newSat = (cnt > 0);
        total += newSat - oldSat;

        int a = V0[c], b = V1[c];
        int s = cnt;
        delta[a] += contrib(c, a, s, val);
        if (b != a) delta[b] += contrib(c, b, s, val);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;

    if (m == 0) {
        for (int i = 0; i < n; ++i) {
            if (i) cout << ' ';
            cout << 0;
        }
        cout << '\n';
        return 0;
    }

    V0.resize(m);
    V1.resize(m);
    D0.resize(m);
    D1.resize(m);
    vc.assign(n, {});

    for (int c = 0; c < m; ++c) {
        int a, b;
        cin >> a >> b;
        int va = (a > 0 ? a : -a) - 1;
        int vb = (b > 0 ? b : -b) - 1;
        int da = (a > 0) ? 1 : 0;
        int db = (b > 0) ? 1 : 0;
        V0[c] = va;
        V1[c] = vb;
        D0[c] = da;
        D1[c] = db;
        vc[va].push_back(c);
        if (vb != va) vc[vb].push_back(c);
    }

    rng_state = chrono::steady_clock::now().time_since_epoch().count();
    if (rng_state == 0) rng_state = 123456789;

    const int TIME_LIMIT_MS = 850;
    auto start = chrono::steady_clock::now();

    vector<int> bestValGlobal(n, 0);
    int bestTotalGlobal = -1;

    vector<int> val(n);
    vector<int> satCnt(m);
    vector<int> delta(n);

    while (true) {
        auto now = chrono::steady_clock::now();
        if (chrono::duration_cast<chrono::milliseconds>(now - start).count() > TIME_LIMIT_MS) break;

        if (bestTotalGlobal < 0 || (rnd() % 100 < 20)) {
            for (int i = 0; i < n; ++i) val[i] = rnd() & 1;
        } else {
            val = bestValGlobal;
            int perturb = 1 + rnd() % (n / 20 + 1);
            for (int k = 0; k < perturb; ++k) {
                val[rnd() % n] ^= 1;
            }
        }

        int total = computeAll(val, satCnt, delta);

        if (total > bestTotalGlobal) {
            bestTotalGlobal = total;
            bestValGlobal = val;
        }

        vector<int> tabu(n, 0);
        int bestThis = total;
        int noImprove = 0;
        int maxIter = 20000 + n * 20;
        if (maxIter > 100000) maxIter = 100000;

        for (int iter = 1; iter <= maxIter; ++iter) {
            if ((iter & 1023) == 0) {
                auto now2 = chrono::steady_clock::now();
                if (chrono::duration_cast<chrono::milliseconds>(now2 - start).count() > TIME_LIMIT_MS) break;
            }

            int bestV = -1;
            int bestDelta = -1000000000;

            for (int v = 0; v < n; ++v) {
                bool allowed = (tabu[v] <= iter || total + delta[v] > bestTotalGlobal);
                if (allowed) {
                    if (delta[v] > bestDelta || (delta[v] == bestDelta && (rnd() & 1))) {
                        bestDelta = delta[v];
                        bestV = v;
                    }
                }
            }

            if (bestV == -1) {
                for (int v = 0; v < n; ++v) {
                    if (delta[v] > bestDelta || (delta[v] == bestDelta && (rnd() & 1))) {
                        bestDelta = delta[v];
                        bestV = v;
                    }
                }
            }

            flipVar(bestV, val, satCnt, delta, total);

            int tenure = 5 + rnd() % 10 + n / 200;
            tabu[bestV] = iter + tenure;

            if (total > bestThis) {
                bestThis = total;
                noImprove = 0;
                if (total > bestTotalGlobal) {
                    bestTotalGlobal = total;
                    bestValGlobal = val;
                }
            } else {
                ++noImprove;
            }

            if (noImprove > 5000 + n * 5) break;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (i) cout << ' ';
        cout << bestValGlobal[i];
    }
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct RNG {
    uint64_t state;

    explicit RNG(uint64_t seed = 88172645463325252ULL) {
        state = seed ? seed : 88172645463325252ULL;
    }

    uint64_t next() {
        state ^= state >> 12;
        state ^= state << 25;
        state ^= state >> 27;
        return state * 2685821657736338717ULL;
    }

    int get(int n) {
        return n <= 0 ? 0 : static_cast<int>(next() % static_cast<uint64_t>(n));
    }

    double real() {
        return static_cast<double>(next() >> 11) * (1.0 / 9007199254740992.0);
    }
};

struct Clause {
    int a, b;       // b == -1 denotes a unit clause
    int sa, sb;     // +1 for a positive literal, -1 for a negative literal
    int weight;
};

static bool solveTwoSAT(
    int n,
    const vector<pair<int, int>>& clauses,
    vector<int>& assignment,
    vector<char>* conflict = nullptr
) {
    const int vertices = 2 * n;
    vector<vector<int>> graph(vertices), reverseGraph(vertices);

    auto literalNode = [](int literal) {
        int variable = abs(literal) - 1;
        return 2 * variable + (literal < 0);
    };

    auto addEdge = [&](int from, int to) {
        graph[from].push_back(to);
        reverseGraph[to].push_back(from);
    };

    for (auto [a, b] : clauses) {
        if (a == -b) continue;

        int u = literalNode(a);
        int v = literalNode(b);
        addEdge(u ^ 1, v);
        addEdge(v ^ 1, u);
    }

    vector<char> visited(vertices, false);
    vector<int> order;
    order.reserve(vertices);

    auto dfs1 = [&](auto&& self, int vertex) -> void {
        visited[vertex] = true;
        for (int to : graph[vertex]) {
            if (!visited[to]) self(self, to);
        }
        order.push_back(vertex);
    };

    for (int vertex = 0; vertex < vertices; ++vertex) {
        if (!visited[vertex]) dfs1(dfs1, vertex);
    }

    vector<int> component(vertices, -1);
    int componentCount = 0;

    auto dfs2 = [&](auto&& self, int vertex, int id) -> void {
        component[vertex] = id;
        for (int to : reverseGraph[vertex]) {
            if (component[to] == -1) self(self, to, id);
        }
    };

    for (int i = static_cast<int>(order.size()) - 1; i >= 0; --i) {
        int vertex = order[i];
        if (component[vertex] == -1) {
            dfs2(dfs2, vertex, componentCount++);
        }
    }

    if (conflict) conflict->assign(n, false);

    bool satisfiable = true;
    for (int variable = 0; variable < n; ++variable) {
        if (component[2 * variable] == component[2 * variable + 1]) {
            satisfiable = false;
            if (conflict) (*conflict)[variable] = true;
        }
    }

    assignment.assign(n, 0);
    if (satisfiable) {
        for (int variable = 0; variable < n; ++variable) {
            assignment[variable] =
                component[2 * variable] > component[2 * variable + 1];
        }
    }
    return satisfiable;
}

class MaxTwoSATHeuristic {
public:
    struct StoredClause {
        int a, b;
        int sa, sb;
        int weight;
    };

    int n;
    vector<StoredClause> clauses;
    vector<vector<int>> adjacency;
    vector<int> value;
    vector<int> bestValue;

    long long work = 0;
    long long workLimit = 30000000LL;
    int bestUnsatisfied = INT_MAX;

private:
    vector<int> unsatisfied;
    vector<int> position;
    vector<int> lastPicked;

    vector<int> makeRaw, breakRaw;
    vector<long long> makeWeighted, breakWeighted;

    static constexpr int MAX_WEIGHT = 5000;

    bool literalTrue(int variable, int sign) const {
        return sign > 0 ? value[variable] != 0 : value[variable] == 0;
    }

    void addUnsatisfied(int id) {
        position[id] = static_cast<int>(unsatisfied.size());
        unsatisfied.push_back(id);
    }

    void removeUnsatisfied(int id) {
        int index = position[id];
        int last = static_cast<int>(unsatisfied.size()) - 1;
        if (index != last) {
            int moved = unsatisfied[last];
            unsatisfied[index] = moved;
            position[moved] = index;
        }
        unsatisfied.pop_back();
        position[id] = -1;
    }

public:
    double averageIncidence() const {
        long long incidences = 0;
        for (const auto& clause : clauses) {
            incidences += 1 + (clause.b != -1);
        }
        return max(1.0, static_cast<double>(incidences) / max(1, n));
    }

    explicit MaxTwoSATHeuristic(int variableCount, vector<StoredClause> input)
        : n(variableCount), clauses(std::move(input)) {
        adjacency.assign(n, {});
        position.assign(clauses.size(), -1);
        lastPicked.assign(clauses.size(), -1000000000);
        value.assign(n, 0);
        bestValue.assign(n, 0);

        makeRaw.assign(n, 0);
        breakRaw.assign(n, 0);
        makeWeighted.assign(n, 0);
        breakWeighted.assign(n, 0);
        unsatisfied.reserve(clauses.size());

        for (int id = 0; id < static_cast<int>(clauses.size()); ++id) {
            adjacency[clauses[id].a].push_back(id);
            if (clauses[id].b != -1) {
                adjacency[clauses[id].b].push_back(id);
            }
        }
    }

    bool considerCurrent() {
        if (static_cast<int>(unsatisfied.size()) < bestUnsatisfied) {
            bestUnsatisfied = static_cast<int>(unsatisfied.size());
            bestValue = value;
            return true;
        }
        return false;
    }

    bool loadAssignment(const vector<int>& assignment) {
        value = assignment;

        fill(makeRaw.begin(), makeRaw.end(), 0);
        fill(breakRaw.begin(), breakRaw.end(), 0);
        fill(makeWeighted.begin(), makeWeighted.end(), 0);
        fill(breakWeighted.begin(), breakWeighted.end(), 0);
        fill(position.begin(), position.end(), -1);
        fill(lastPicked.begin(), lastPicked.end(), -1000000000);
        unsatisfied.clear();

        for (auto& clause : clauses) clause.weight = 1;

        for (int id = 0; id < static_cast<int>(clauses.size()); ++id) {
            const auto& clause = clauses[id];
            bool trueA = literalTrue(clause.a, clause.sa);
            bool trueB = clause.b != -1 && literalTrue(clause.b, clause.sb);

            if (!trueA && !trueB) {
                ++makeRaw[clause.a];
                makeWeighted[clause.a] += clause.weight;
                if (clause.b != -1) {
                    ++makeRaw[clause.b];
                    makeWeighted[clause.b] += clause.weight;
                }
                addUnsatisfied(id);
            } else {
                if (trueA && !trueB) {
                    ++breakRaw[clause.a];
                    breakWeighted[clause.a] += clause.weight;
                } else if (!trueA && trueB) {
                    ++breakRaw[clause.b];
                    breakWeighted[clause.b] += clause.weight;
                }
            }
        }

        return considerCurrent();
    }

    void flip(int variable) {
        work += static_cast<long long>(adjacency[variable].size());

        for (int id : adjacency[variable]) {
            auto& clause = clauses[id];

            bool oldA = literalTrue(clause.a, clause.sa);
            bool oldB = clause.b != -1 && literalTrue(clause.b, clause.sb);

            bool newA = clause.a == variable ? !oldA : oldA;
            bool newB = clause.b != -1 &&
                        (clause.b == variable ? !oldB : oldB);

            int oldMakeA = !oldA && !oldB;
            int oldBreakA = oldA && !oldB;
            int newMakeA = !newA && !newB;
            int newBreakA = newA && !newB;

            makeRaw[clause.a] += newMakeA - oldMakeA;
            breakRaw[clause.a] += newBreakA - oldBreakA;
            makeWeighted[clause.a] +=
                1LL * (newMakeA - oldMakeA) * clause.weight;
            breakWeighted[clause.a] +=
                1LL * (newBreakA - oldBreakA) * clause.weight;

            if (clause.b != -1) {
                int oldMakeB = !oldB && !oldA;
                int oldBreakB = oldB && !oldA;
                int newMakeB = !newB && !newA;
                int newBreakB = newB && !oldA;

                makeRaw[clause.b] += newMakeB - oldMakeB;
                breakRaw[clause.b] += newBreakB - oldBreakB;
                makeWeighted[clause.b] +=
                    1LL * (newMakeB - oldMakeB) * clause.weight;
                breakWeighted[clause.b] +=
                    1LL * (newBreakB - oldBreakB) * clause.weight;
            }

            bool oldSatisfied = oldA || oldB;
            bool newSatisfied = newA || newB;

            if (oldSatisfied != newSatisfied) {
                if (newSatisfied) {
                    removeUnsatisfied(id);
                } else {
                    addUnsatisfied(id);
                }
            }

            if (oldSatisfied && !newSatisfied && clause.b != -1 &&
                clause.weight < MAX_WEIGHT) {
                ++clause.weight;
                ++makeWeighted[clause.a];
                ++makeWeighted[clause.b];
            }
        }

        value[variable] ^= 1;
    }

    void hillClimb() {
        while (work < workLimit && !unsatisfied.empty()) {
            int bestVariable = -1;
            int bestGain = 0;
            long long bestTie = LLONG_MIN;

            for (int variable = 0; variable < n; ++variable) {
                int gain = makeRaw[variable] - breakRaw[variable];
                if (gain <= 0) continue;

                long long tie =
                    makeWeighted[variable] - breakWeighted[variable];
                if (gain > bestGain ||
                    (gain == bestGain && tie > bestTie)) {
                    bestGain = gain;
                    bestTie = tie;
                    bestVariable = variable;
                }
            }

            if (bestVariable == -1) break;

            flip(bestVariable);
            considerCurrent();
        }
    }

    int pickClause(int iteration, RNG& random) {
        int size = static_cast<int>(unsatisfied.size());
        int chosen = unsatisfied[random.get(size)];

        if (size >= 8) {
            for (int sample = 0; sample < 2; ++sample) {
                int candidate = unsatisfied[random.get(size)];
                int chosenAge = iteration - lastPicked[chosen];
                int candidateAge = iteration - lastPicked[candidate];

                if (clauses[candidate].weight > clauses[chosen].weight ||
                    (clauses[candidate].weight == clauses[chosen].weight &&
                     candidateAge > chosenAge)) {
                    chosen = candidate;
                }
            }
        }

        lastPicked[chosen] = iteration;
        return chosen;
    }

    void reweightUnsatisfiedClauses() {
        work += 2LL * unsatisfied.size();

        for (int id : unsatisfied) {
            auto& clause = clauses[id];
            if (clause.b != -1 && clause.weight < MAX_WEIGHT) {
                ++clause.weight;
                ++makeWeighted[clause.a];
                ++makeWeighted[clause.b];
            }
        }
    }

    void walk(int maxFlips, int noisePerMille, RNG& random) {
        if (unsatisfied.empty()) {
            considerCurrent();
            return;
        }

        considerCurrent();

        int stale = 0;
        int reweightEvery = max(2000, static_cast<int>(10 * averageIncidence()));

        for (int iteration = 0;
             iteration < maxFlips && work < workLimit &&
             !unsatisfied.empty();
             ++iteration) {
            int id = pickClause(iteration, random);
            const auto& clause = clauses[id];

            int chosen = clause.a;
            if (clause.b != -1) {
                long long scoreA =
                    makeWeighted[clause.a] - breakWeighted[clause.a];
                long long scoreB =
                    makeWeighted[clause.b] - breakWeighted[clause.b];

                bool chooseB;
                if (random.get(1000) < noisePerMille) {
                    chooseB = random.get(2) != 0;
                } else if (scoreA == scoreB) {
                    chooseB = random.get(2) != 0;
                } else {
                    chooseB = scoreB > scoreA;
                }

                if (chooseB) chosen = clause.b;
            }

            int previousBest = bestUnsatisfied;
            flip(chosen);
            bool improved = considerCurrent();

            if (bestUnsatisfied < previousBest) {
                stale = 0;
            } else {
                ++stale;
            }

            if (stale >= reweightEvery) {
                reweightUnsatisfiedClauses();
                stale = 0;
            }
        }

        hillClimb();
    }

    void perturb(int count, RNG& random) {
        if (count <= 0 || clauses.empty()) return;

        vector<char> seen(n, false), chosen(n, false);
        vector<int> hot, all;

        for (int id : unsatisfied) {
            const auto& clause = clauses[id];
            if (!seen[clause.a]) {
                seen[clause.a] = true;
                hot.push_back(clause.a);
            }
            if (clause.b != -1 && !seen[clause.b]) {
                seen[clause.b] = true;
                hot.push_back(clause.b);
            }
        }

        fill(seen.begin(), seen.end(), false);
        for (int variable = 0; variable < n; ++variable) {
            if (!adjacency[variable].empty()) {
                seen[variable] = true;
                all.push_back(variable);
            }
        }

        auto pickUnused = [&](const vector<int>& candidates) {
            for (int attempt = 0;
                 attempt < static_cast<int>(candidates.size()); ++attempt) {
                int candidate = candidates[random.get(candidates.size())];
                if (!chosen[candidate]) return candidate;
            }
            return -1;
        };

        for (int step = 0; step < count && work < workLimit; ++step) {
            int variable = -1;

            if (!hot.empty() && random.get(100) < 75) {
                variable = pickUnused(hot);
            }
            if (variable == -1) {
                variable = pickUnused(all);
            }
            if (variable == -1) break;

            chosen[variable] = true;
            flip(variable);
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<pair<int, int>> inputClauses(m);
    for (auto& [a, b] : inputClauses) {
        cin >> a >> b;
    }

    vector<int> twoSATAssignment;
    vector<char> conflict;
    bool satisfiable =
        solveTwoSAT(n, inputClauses, twoSATAssignment, &conflict);

    if (satisfiable) {
        for (int variable = 0; variable < n; ++variable) {
            if (variable) cout << ' ';
            cout << twoSATAssignment[variable];
        }
        cout << '\n';
        return 0;
    }

    vector<MaxTwoSATHeuristic::StoredClause> clauses;
    clauses.reserve(m);

    for (auto [a, b] : inputClauses) {
        if (a == -b) continue;

        int variableA = abs(a) - 1;
        int signA = a > 0 ? 1 : -1;

        if (abs(a) == abs(b)) {
            clauses.push_back({variableA, -1, signA, 1, 1});
        } else {
            int variableB = abs(b) - 1;
            int signB = b > 0 ? 1 : -1;
            clauses.push_back({variableA, variableB, signA, signB, 1});
        }
    }

    if (clauses.empty()) {
        for (int variable = 0; variable < n; ++variable) {
            if (variable) cout << ' ';
            cout << 0;
        }
        cout << '\n';
        return 0;
    }

    uint64_t seed = 0x9E3779B97F4A7C15ULL ^
                    (static_cast<uint64_t>(n) << 32) ^
                    static_cast<uint64_t>(m);
    RNG random(seed);

    MaxTwoSATHeuristic solver(n, std::move(clauses));

    long long computedLimit =
        700LL * static_cast<long long>(solver.clauses.size()) + 50LL * n;
    solver.workLimit = min(30000000LL, max(4000000LL, computedLimit));

    vector<int> polarity(n, 0);
    for (const auto& clause : solver.clauses) {
        polarity[clause.a] += clause.sa;
        if (clause.b != -1) polarity[clause.b] += clause.sb;
    }

    vector<int> majority(n, 0);
    for (int variable = 0; variable < n; ++variable) {
        if (polarity[variable] > 0) {
            majority[variable] = 1;
        } else if (polarity[variable] < 0) {
            majority[variable] = 0;
        } else {
            majority[variable] = random.get(2);
        }
    }

    vector<int> sccSeed = twoSATAssignment;
    for (int variable = 0; variable < n; ++variable) {
        if (conflict[variable]) {
            sccSeed[variable] = random.get(2);
        }
    }

    long long phase1End = static_cast<long long>(solver.workLimit * 0.62);
    long long phase2End = static_cast<long long>(solver.workLimit * 0.82);
    const int noise[] = {140, 220, 300, 380, 180, 280};

    for (int round = 0; round < 6 && solver.work < phase1End; ++round) {
        if (round < 4) {
            vector<int> seed;
            if (round == 0) {
                seed = sccSeed;
            } else if (round == 1) {
                seed = majority;
            } else {
                seed.assign(n, 0);
                for (int variable = 0; variable < n; ++variable) {
                    seed[variable] = random.get(2);
                }
            }
            solver.loadAssignment(seed);
        } else {
            solver.loadAssignment(solver.bestValue);
            solver.perturb(4 + random.get(8), random);
            solver.considerCurrent();
        }

        int remainingRounds = 6 - round;
        long long allowance = (phase1End - solver.work) / remainingRounds;
        long long flips = allowance /
            max(1LL, static_cast<long long>(solver.averageIncidence()));
        flips = max(3000LL, min(70000LL, flips));

        solver.walk(static_cast<int>(flips), noise[round], random);
        if (solver.bestUnsatisfied == 0) break;
    }

    int trials = 0;
    while (solver.work < phase2End && trials < 400 &&
           solver.bestUnsatisfied > 0) {
        solver.loadAssignment(solver.bestValue);
        solver.perturb(3 + random.get(10), random);
        solver.considerCurrent();

        if ((trials & 3) == 3) {
            solver.walk(1200, 350, random);
        } else {
            solver.hillClimb();
        }
        ++trials;
    }

    if (solver.bestUnsatisfied > 0) {
        solver.loadAssignment(solver.bestValue);
        long long remaining = solver.workLimit - solver.work;
        long long flips = remaining /
            max(1LL, static_cast<long long>(solver.averageIncidence()));
        flips = max(1000LL, min(250000LL, flips));
        solver.walk(static_cast<int>(flips), 230, random);
    }

    solver.loadAssignment(solver.bestValue);
    solver.hillClimb();

    for (int variable = 0; variable < n; ++variable) {
        if (variable) cout << ' ';
        cout << solver.bestValue[variable];
    }
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 INF = (int64)4e18;

struct Node {
    string id;
    int64 x, y;
    char type;
};

struct Edge {
    int u, v;
};

struct Tree {
    vector<Edge> edges;
    int64 cost = 0;
};

struct DSU {
    vector<int> p, sz;
    explicit DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n);
        sz.assign(n, 1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

class Solver {
public:
    int N, K, M;
    vector<Node> nodes;
    vector<int64> w;
    vector<vector<int>> starOrder;
    vector<int> relayOrder;
    chrono::steady_clock::time_point startTime;
    Tree best;

    explicit Solver(vector<Node> inputNodes, int n, int k) : N(n), K(k) {
        for (const auto &node : inputNodes)
            if (node.type != 'C') nodes.push_back(node);
        for (const auto &node : inputNodes)
            if (node.type == 'C') nodes.push_back(node);
        M = N + K;
        startTime = chrono::steady_clock::now();
    }

    bool timeUp() const {
        return chrono::duration<double>(chrono::steady_clock::now() - startTime).count() > 8.5;
    }

    inline int64 weight(int u, int v) const {
        return w[(size_t)u * M + v];
    }

    void buildWeights() {
        w.assign((size_t)M * M, 0);
        for (int i = 0; i < M; ++i) {
            for (int j = i + 1; j < M; ++j) {
                int64 value = INF;
                if (!(i >= N && j >= N)) {
                    int64 dx = nodes[i].x - nodes[j].x;
                    int64 dy = nodes[i].y - nodes[j].y;
                    int64 d2 = dx * dx + dy * dy;
                    int factor = 10;
                    if (i < N && j < N &&
                        (nodes[i].type == 'S' || nodes[j].type == 'S'))
                        factor = 8;
                    value = d2 * factor;
                }
                w[(size_t)i * M + j] = value;
                w[(size_t)j * M + i] = value;
            }
        }
    }

    vector<Edge> mst(const vector<int> &vertices, int relayPercent) const {
        int n = (int)vertices.size();
        vector<Edge> result;
        if (n <= 1) return result;

        vector<int64> key(n, INF);
        vector<int> parent(n, -1);
        vector<char> used(n, false);
        key[0] = 0;
        result.reserve(n - 1);

        for (int it = 0; it < n; ++it) {
            int u = -1;
            for (int i = 0; i < n; ++i) {
                if (!used[i] && (u == -1 || key[i] < key[u])) u = i;
            }
            if (u == -1 || key[u] == INF) break;
            used[u] = true;
            if (parent[u] != -1)
                result.push_back({vertices[u], vertices[parent[u]]});

            int gu = vertices[u];
            for (int v = 0; v < n; ++v) {
                if (used[v]) continue;
                int gv = vertices[v];
                int64 value = weight(gu, gv);
                if (value == INF) continue;
                if (relayPercent != 100 && (gu >= N || gv >= N))
                    value = value * relayPercent / 100;
                if (value < key[v]) {
                    key[v] = value;
                    parent[v] = u;
                }
            }
        }
        return result;
    }

    Tree pruneRelayLeaves(const vector<Edge> &edges) const {
        Tree result;
        int E = (int)edges.size();
        if (E == 0) return result;

        struct Arc {
            int to, id, next;
        };
        vector<int> degree(M, 0), head(M, -1), queueVertices;
        vector<Arc> arcs;
        arcs.reserve(2 * E);
        vector<char> removed(E, false);

        for (int i = 0; i < E; ++i) {
            int u = edges[i].u, v = edges[i].v;
            ++degree[u];
            ++degree[v];
            arcs.push_back({v, i, head[u]});
            head[u] = (int)arcs.size() - 1;
            arcs.push_back({u, i, head[v]});
            head[v] = (int)arcs.size() - 1;
        }

        for (int i = N; i < M; ++i)
            if (degree[i] == 1) queueVertices.push_back(i);

        for (size_t q = 0; q < queueVertices.size(); ++q) {
            int u = queueVertices[q];
            if (degree[u] != 1) continue;
            for (int a = head[u]; a != -1; a = arcs[a].next) {
                int id = arcs[a].id;
                if (removed[id]) continue;
                removed[id] = true;
                int v = arcs[a].to;
                --degree[u];
                --degree[v];
                if (v >= N && degree[v] == 1) queueVertices.push_back(v);
                break;
            }
        }

        result.edges.reserve(E);
        for (int i = 0; i < E; ++i) {
            if (!removed[i]) {
                result.edges.push_back(edges[i]);
                result.cost += weight(edges[i].u, edges[i].v);
            }
        }
        return result;
    }

    int activeRelayCount(const Tree &t) const {
        vector<char> active(K, false);
        int count = 0;
        for (const auto &e : t.edges) {
            if (e.u >= N && !active[e.u - N]) {
                active[e.u - N] = true;
                ++count;
            }
            if (e.v >= N && !active[e.v - N]) {
                active[e.v - N] = true;
                ++count;
            }
        }
        return count;
    }

    Tree normalize(Tree t) const {
        for (int iteration = 0; iteration < 4; ++iteration) {
            vector<char> active(K, false);
            for (const auto &e : t.edges) {
                if (e.u >= N) active[e.u - N] = true;
                if (e.v >= N) active[e.v - N] = true;
            }

            vector<int> vertices(N);
            iota(vertices.begin(), vertices.end(), 0);
            int oldActive = 0;
            for (int c = 0; c < K; ++c) {
                if (active[c]) {
                    vertices.push_back(N + c);
                    ++oldActive;
                }
            }

            Tree next = pruneRelayLeaves(mst(vertices, 100));
            if (next.cost > t.cost) break;
            int newActive = activeRelayCount(next);
            t = std::move(next);
            if (newActive >= oldActive) break;
        }
        return t;
    }

    void buildRelayOrders() {
        starOrder.assign(K, {});
        vector<int64> score(K, 0);

        for (int c = 0; c < K; ++c) {
            int g = N + c;
            starOrder[c].resize(N);
            iota(starOrder[c].begin(), starOrder[c].end(), 0);
            sort(starOrder[c].begin(), starOrder[c].end(), [&](int a, int b) {
                int64 wa = weight(g, a), wb = weight(g, b);
                if (wa != wb) return wa < wb;
                return a < b;
            });
            if (N >= 2)
                score[c] = weight(g, starOrder[c][0]) + weight(g, starOrder[c][1]);
            else if (N == 1)
                score[c] = weight(g, starOrder[c][0]);
        }

        relayOrder.resize(K);
        iota(relayOrder.begin(), relayOrder.end(), 0);
        sort(relayOrder.begin(), relayOrder.end(), [&](int a, int b) {
            if (score[a] != score[b]) return score[a] < score[b];
            return a < b;
        });
    }

    bool insertionPass(Tree &current, const vector<int> &order) {
        bool improved = false;
        vector<char> active(M, false);
        for (const auto &e : current.edges) {
            if (e.u >= N) active[e.u] = true;
            if (e.v >= N) active[e.v] = true;
        }

        vector<Edge> sortedTree = current.edges;
        auto sortTree = [&]() {
            sort(sortedTree.begin(), sortedTree.end(), [&](const Edge &a, const Edge &b) {
                int64 wa = weight(a.u, a.v), wb = weight(b.u, b.v);
                if (wa != wb) return wa < wb;
                if (a.u != b.u) return a.u < b.u;
                return a.v < b.v;
            });
        };
        sortTree();

        for (int c : order) {
            if (timeUp() || current.cost == 0) break;
            int g = N + c;
            if (active[g]) continue;

            DSU dsu(M);
            int target = (int)current.edges.size() + 1;
            int selected = 0;
            size_t i = 0;
            int j = 0;
            vector<Edge> candidateEdges;
            candidateEdges.reserve(target);

            while (selected < target &&
                   (i < sortedTree.size() || j < N)) {
                Edge e;
                if (i >= sortedTree.size()) {
                    e = {g, starOrder[c][j++]};
                } else if (j >= N) {
                    e = sortedTree[i++];
                } else {
                    int64 treeW = weight(sortedTree[i].u, sortedTree[i].v);
                    int64 starW = weight(g, starOrder[c][j]);
                    if (treeW <= starW) e = sortedTree[i++];
                    else e = {g, starOrder[c][j++]};
                }

                if (dsu.unite(e.u, e.v)) {
                    candidateEdges.push_back(e);
                    ++selected;
                }
            }

            if (selected != target) continue;
            Tree candidate = pruneRelayLeaves(candidateEdges);
            if (candidate.cost < current.cost) {
                current = std::move(candidate);
                improved = true;

                fill(active.begin(), active.end(), false);
                for (const auto &e : current.edges) {
                    if (e.u >= N) active[e.u] = true;
                    if (e.v >= N) active[e.v] = true;
                }
                sortedTree = current.edges;
                sortTree();
            }
        }
        return improved;
    }

    vector<Edge> connectNeighbors(const vector<int> &neighbors) const {
        int d = (int)neighbors.size();
        vector<Edge> added;
        if (d <= 1) return added;

        vector<int64> key(d, INF);
        vector<int> parent(d, -1);
        vector<char> used(d, false);
        key[0] = 0;
        added.reserve(d - 1);

        for (int it = 0; it < d; ++it) {
            int u = -1;
            for (int i = 0; i < d; ++i)
                if (!used[i] && (u == -1 || key[i] < key[u])) u = i;
            used[u] = true;
            if (parent[u] != -1)
                added.push_back({neighbors[u], neighbors[parent[u]]});

            for (int v = 0; v < d; ++v) {
                if (used[v]) continue;
                int64 value = weight(neighbors[u], neighbors[v]);
                if (value < key[v]) {
                    key[v] = value;
                    parent[v] = u;
                }
            }
        }
        return added;
    }

    bool deletionPass(Tree &current, const vector<int> &order) {
        bool improved = false;
        vector<char> active(M, false);
        for (const auto &e : current.edges) {
            if (e.u >= N) active[e.u] = true;
            if (e.v >= N) active[e.v] = true;
        }

        for (int c : order) {
            if (timeUp() || current.cost == 0) break;
            int g = N + c;
            if (!active[g]) continue;

            vector<Edge> remaining;
            vector<int> neighbors;
            remaining.reserve(current.edges.size());

            for (const auto &e : current.edges) {
                if (e.u == g || e.v == g) {
                    neighbors.push_back(e.u == g ? e.v : e.u);
                } else {
                    remaining.push_back(e);
                }
            }
            if (neighbors.empty()) continue;

            vector<Edge> added = connectNeighbors(neighbors);
            remaining.insert(remaining.end(), added.begin(), added.end());
            Tree candidate = pruneRelayLeaves(remaining);

            if (candidate.cost < current.cost) {
                current = std::move(candidate);
                improved = true;
                fill(active.begin(), active.end(), false);
                for (const auto &e : current.edges) {
                    if (e.u >= N) active[e.u] = true;
                    if (e.v >= N) active[e.v] = true;
                }
            }
        }
        return improved;
    }

    Tree localSearch(Tree current, const vector<int> &order) {
        current = normalize(current);
        for (int round = 0; round < 5 && !timeUp() && current.cost > 0; ++round) {
            int64 before = current.cost;
            insertionPass(current, order);
            if (!timeUp()) current = normalize(current);
            if (!timeUp()) {
                deletionPass(current, order);
                current = normalize(current);
            }
            if (current.cost >= before) break;
        }
        return current;
    }

    void updateBest(const Tree &t) {
        if (t.cost < best.cost ||
            (t.cost == best.cost && t.edges.size() < best.edges.size()))
            best = t;
    }

    void solve() {
        buildWeights();

        vector<int> robots(N);
        iota(robots.begin(), robots.end(), 0);
        Tree base = pruneRelayLeaves(mst(robots, 100));
        best = base;

        if (base.cost == 0 || K == 0) return;

        buildRelayOrders();

        Tree initial = localSearch(base, relayOrder);
        updateBest(initial);
        if (best.cost == 0) return;

        vector<Tree> seeds;
        vector<int> allVertices(M);
        iota(allVertices.begin(), allVertices.end(), 0);
        const int percentages[] = {65, 80, 100, 115, 135, 165, 220};

        for (int percent : percentages) {
            if (timeUp()) break;
            Tree seed = pruneRelayLeaves(mst(allVertices, percent));
            seed = normalize(seed);
            updateBest(seed);
            seeds.push_back(std::move(seed));
        }

        if (!timeUp() && K >= 3) {
            int choices[2] = {K / 3, 2 * K / 3};
            for (int q : choices) {
                if (q <= 0 || timeUp()) continue;
                vector<int> vertices = robots;
                for (int i = 0; i < q; ++i)
                    vertices.push_back(N + relayOrder[i]);
                Tree seed = pruneRelayLeaves(mst(vertices, 100));
                seed = normalize(seed);
                updateBest(seed);
                seeds.push_back(std::move(seed));
            }
        }

        sort(seeds.begin(), seeds.end(), [](const Tree &a, const Tree &b) {
            if (a.cost != b.cost) return a.cost < b.cost;
            return a.edges.size() < b.edges.size();
        });

        int usedSeeds = 0;
        for (const auto &seed : seeds) {
            if (usedSeeds >= 4 || timeUp() || best.cost == 0) break;
            Tree candidate = localSearch(seed, relayOrder);
            updateBest(candidate);
            ++usedSeeds;
        }

        mt19937 rng(123456789);
        for (int attempt = 0; attempt < 3 && !timeUp() && best.cost > 0; ++attempt) {
            vector<int> randomOrder = relayOrder;
            shuffle(randomOrder.begin(), randomOrder.end(), rng);
            Tree candidate = localSearch(base, randomOrder);
            updateBest(candidate);
        }
    }

    void output() const {
        vector<char> selected(K, false);
        for (const auto &e : best.edges) {
            if (e.u >= N) selected[e.u - N] = true;
            if (e.v >= N) selected[e.v - N] = true;
        }

        bool any = false, first = true;
        for (int c = 0; c < K; ++c) {
            if (!selected[c]) continue;
            any = true;
            if (!first) cout << '#';
            first = false;
            cout << nodes[N + c].id;
        }
        if (!any) cout << '#';
        cout << '\n';

        for (size_t i = 0; i < best.edges.size(); ++i) {
            if (i) cout << '#';
            cout << nodes[best.edges[i].u].id << '-'
                 << nodes[best.edges[i].v].id;
        }
        cout << '\n';
    }
};

