#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 INF = (int64)4e18;

struct Node {
    string id;
    int64 x, y;
    char type;
};

struct Edge {
    int u, v;
    int64 w;
};

struct Solution {
    vector<Edge> edges;
    vector<char> active;
    int64 cost = 0;
};

struct DSU {
    vector<int> p;
    explicit DSU(int n) : p(n, -1) {}

    int find(int x) {
        while (p[x] >= 0) {
            if (p[p[x]] >= 0) p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }

    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (p[a] > p[b]) swap(a, b);
        p[a] += p[b];
        p[b] = a;
        return true;
    }
};

int N, K, M;
vector<Node> nodes;
vector<Edge> relayStars;

int64 edgeWeight(int u, int v) {
    int64 dx = nodes[u].x - nodes[v].x;
    int64 dy = nodes[u].y - nodes[v].y;
    int64 d2 = dx * dx + dy * dy;

    char a = nodes[u].type;
    char b = nodes[v].type;
    if (a == 'C' && b == 'C') return INF;
    if (a == 'C' || b == 'C') return 5 * d2;
    if (a == 'R' && b == 'R') return 5 * d2;
    return 4 * d2;
}

Solution pruneRelayLeaves(Solution s) {
    int E = (int)s.edges.size();
    vector<vector<int>> adj(M);
    vector<int> degree(M, 0);
    vector<char> removed(E, 0);

    s.active.assign(M, 0);
    for (int i = 0; i < N; ++i) s.active[i] = 1;

    for (int i = 0; i < E; ++i) {
        int u = s.edges[i].u;
        int v = s.edges[i].v;
        adj[u].push_back(i);
        adj[v].push_back(i);
        ++degree[u];
        ++degree[v];
        s.active[u] = 1;
        s.active[v] = 1;
    }

    queue<int> q;
    for (int r = N; r < M; ++r) {
        if (s.active[r] && degree[r] <= 1) q.push(r);
    }

    while (!q.empty()) {
        int v = q.front();
        q.pop();
        if (!s.active[v] || degree[v] > 1) continue;

        s.active[v] = 0;
        for (int ei : adj[v]) {
            if (removed[ei]) continue;
            removed[ei] = 1;
            int other = s.edges[ei].u ^ s.edges[ei].v ^ v;
            --degree[v];
            --degree[other];
            if (other >= N && s.active[other] && degree[other] <= 1) {
                q.push(other);
            }
        }
    }

    vector<Edge> kept;
    kept.reserve(E);
    s.cost = 0;
    for (int i = 0; i < E; ++i) {
        if (!removed[i]) {
            kept.push_back(s.edges[i]);
            s.cost += s.edges[i].w;
        }
    }
    s.edges.swap(kept);
    return s;
}

Solution primPrefix(int count) {
    vector<int64> key(M, INF);
    vector<int> parent(M, -1);
    vector<char> used(M, 0);

    Solution result;
    result.active.assign(M, 0);
    for (int i = 0; i < count; ++i) result.active[i] = 1;
    result.cost = 0;
    key[0] = 0;

    for (int it = 0; it < count; ++it) {
        int u = -1;
        for (int i = 0; i < count; ++i) {
            if (!used[i] && (u == -1 || key[i] < key[u])) u = i;
        }
        if (u == -1) break;

        used[u] = 1;
        if (parent[u] != -1) {
            int64 w = edgeWeight(parent[u], u);
            result.edges.push_back({parent[u], u, w});
            result.cost += w;
        }

        for (int v = 0; v < count; ++v) {
            if (used[v]) continue;
            if (nodes[u].type == 'C' && nodes[v].type == 'C') continue;
            int64 w = edgeWeight(u, v);
            if (w < key[v]) {
                key[v] = w;
                parent[v] = u;
            }
        }
    }

    sort(result.edges.begin(), result.edges.end(),
         [](const Edge &a, const Edge &b) { return a.w < b.w; });
    return result;
}

Solution primActive(const vector<char> &active) {
    vector<int> vertices;
    for (int i = 0; i < M; ++i) {
        if (active[i]) vertices.push_back(i);
    }

    vector<int64> key(M, INF);
    vector<int> parent(M, -1);
    vector<char> used(M, 0);

    Solution result;
    result.active = active;
    result.cost = 0;
    key[0] = 0;

    for (int it = 0; it < (int)vertices.size(); ++it) {
        int u = -1;
        for (int v : vertices) {
            if (!used[v] && (u == -1 || key[v] < key[u])) u = v;
        }
        if (u == -1) break;

        used[u] = 1;
        if (parent[u] != -1) {
            int64 w = edgeWeight(parent[u], u);
            result.edges.push_back({parent[u], u, w});
            result.cost += w;
        }

        for (int v : vertices) {
            if (used[v]) continue;
            if (nodes[u].type == 'C' && nodes[v].type == 'C') continue;
            int64 w = edgeWeight(u, v);
            if (w < key[v]) {
                key[v] = w;
                parent[v] = u;
            }
        }
    }

    sort(result.edges.begin(), result.edges.end(),
         [](const Edge &a, const Edge &b) { return a.w < b.w; });
    return result;
}

const Edge *starPointer(int relay) {
    return relayStars.data() + (size_t)(relay - N) * N;
}

int64 addedTreeCost(const Solution &current, int relay) {
    DSU dsu(M);
    const Edge *star = starPointer(relay);

    size_t i = 0;
    int j = 0;
    int accepted = 0;
    int needed = (int)current.edges.size() + 1;
    int64 cost = 0;

    while (accepted < needed) {
        bool takeStar;
        if (i >= current.edges.size()) takeStar = true;
        else if (j >= N) takeStar = false;
        else takeStar = star[j].w < current.edges[i].w;

        Edge e;
        if (takeStar) e = star[j++];
        else e = current.edges[i++];

        if (dsu.unite(e.u, e.v)) {
            cost += e.w;
            ++accepted;
        }
    }
    return cost;
}

Solution buildAddedTree(const Solution &current, int relay) {
    DSU dsu(M);
    const Edge *star = starPointer(relay);

    Solution result;
    result.edges.reserve(current.edges.size() + 1);
    result.cost = 0;

    size_t i = 0;
    int j = 0;
    int needed = (int)current.edges.size() + 1;

    while ((int)result.edges.size() < needed) {
        bool takeStar;
        if (i >= current.edges.size()) takeStar = true;
        else if (j >= N) takeStar = false;
        else takeStar = star[j].w < current.edges[i].w;

        Edge e;
        if (takeStar) e = star[j++];
        else e = current.edges[i++];

        if (dsu.unite(e.u, e.v)) {
            result.edges.push_back(e);
            result.cost += e.w;
        }
    }

    result.active = current.active;
    result.active[relay] = 1;
    return result;
}

Solution sequentialImprove(Solution current, const vector<int> &order, int passes) {
    for (int pass = 0; pass < passes; ++pass) {
        bool changed = false;

        for (int relay : order) {
            if (current.active[relay]) continue;

            int64 rawCost = addedTreeCost(current, relay);
            if (rawCost >= current.cost) continue;

            Solution candidate = buildAddedTree(current, relay);
            candidate = pruneRelayLeaves(std::move(candidate));

            if (candidate.cost < current.cost) {
                current = std::move(candidate);
                changed = true;
            }
        }

        if (!changed) break;
    }
    return current;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> K;
    M = N + K;

    vector<Node> robots, relays;
    robots.reserve(N);
    relays.reserve(K);

    for (int i = 0; i < M; ++i) {
        Node node;
        cin >> node.id >> node.x >> node.y >> node.type;
        if (node.type == 'C') relays.push_back(node);
        else robots.push_back(node);
    }

    nodes = robots;
    nodes.insert(nodes.end(), relays.begin(), relays.end());

    Solution base = primPrefix(N);
    Solution best = base;

    auto consider = [&](Solution s) {
        if (s.cost < best.cost ||
            (s.cost == best.cost && s.edges.size() < best.edges.size())) {
            best = std::move(s);
        }
    };

    if (K > 0) {
        relayStars.resize((size_t)K * N);
        for (int r = 0; r < K; ++r) {
            Edge *star = relayStars.data() + (size_t)r * N;
            for (int v = 0; v < N; ++v) {
                star[v] = {N + r, v, edgeWeight(N + r, v)};
            }
            sort(star, star + N, [](const Edge &a, const Edge &b) {
                if (a.w != b.w) return a.w < b.w;
                return a.v < b.v;
            });
        }

        vector<int> inputOrder(K), nearestOrder(K), gainOrder(K);
        iota(inputOrder.begin(), inputOrder.end(), N);
        nearestOrder = inputOrder;
        gainOrder = inputOrder;

        sort(nearestOrder.begin(), nearestOrder.end(), [](int a, int b) {
            int64 wa = starPointer(a)[0].w;
            int64 wb = starPointer(b)[0].w;
            if (wa != wb) return wa < wb;
            return a < b;
        });

        vector<int64> gains(M, 0);
        for (int relay : inputOrder) {
            gains[relay] = base.cost - addedTreeCost(base, relay);
        }

        sort(gainOrder.begin(), gainOrder.end(), [&](int a, int b) {
            if (gains[a] != gains[b]) return gains[a] > gains[b];
            int64 wa = starPointer(a)[0].w;
            int64 wb = starPointer(b)[0].w;
            if (wa != wb) return wa < wb;
            return a < b;
        });

        consider(sequentialImprove(base, inputOrder, 2));
        consider(sequentialImprove(base, nearestOrder, 2));
        consider(sequentialImprove(base, gainOrder, 2));

        mt19937 rng(123456789);
        for (int t = 0; t < 2; ++t) {
            vector<int> randomOrder = inputOrder;
            shuffle(randomOrder.begin(), randomOrder.end(), rng);
            consider(sequentialImprove(base, randomOrder, 1));
        }

        Solution full = pruneRelayLeaves(primPrefix(M));
        for (int it = 0; it < 2; ++it) {
            vector<char> previous = full.active;
            full = pruneRelayLeaves(primActive(full.active));
            if (full.active == previous) break;
        }
        consider(full);
        consider(sequentialImprove(std::move(full), gainOrder, 1));

        consider(sequentialImprove(best, gainOrder, 2));
    }

    bool first = true;
    for (int r = N; r < M; ++r) {
        if (!best.active[r]) continue;
        if (!first) cout << '#';
        cout << nodes[r].id;
        first = false;
    }
    if (first) cout << '#';
    cout << '\n';

    for (int i = 0; i < (int)best.edges.size(); ++i) {
        if (i) cout << '#';
        cout << nodes[best.edges[i].u].id << '-'
             << nodes[best.edges[i].v].id;
    }
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Robot {
    long long x, y;
    char type;
    int id;
};

struct Relay {
    long long x, y;
    int id;
};

struct Edge {
    long long w;
    int u, v;
    int relay_idx;
    bool operator<(const Edge& other) const { return w < other.w; }
};

int N, K;
vector<Robot> robots;
vector<Relay> relays;
vector<Edge> all_edges;
vector<vector<pair<long long, int>>> relay_edges;
vector<int> T_nodes;
vector<Edge> T_edges;
long long T_cost;
vector<char> in_T;

int parent[3005];
int sz[3005];

int find_set(int v) {
    if (v == parent[v]) return v;
    return parent[v] = find_set(parent[v]);
}

void union_sets(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a != b) {
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }
}

int deg_relay[1505];
vector<int> touched_relays;
vector<Edge> temp_selected;

long long eval_add(int r) {
    temp_selected.clear();
    touched_relays.clear();
    for (int node : T_nodes) {
        parent[node] = node;
        sz[node] = 1;
    }
    parent[N + r] = N + r;
    sz[N + r] = 1;
    int V = T_nodes.size() + 1;
    int selected = 0;
    int i = 0, j = 0;
    while (selected < V - 1) {
        long long w;
        int u, v;
        if (i < (int)T_edges.size() && (j >= (int)relay_edges[r].size() || T_edges[i].w <= relay_edges[r][j].first)) {
            w = T_edges[i].w;
            u = T_edges[i].u;
            v = T_edges[i].v;
            i++;
        } else {
            w = relay_edges[r][j].first;
            u = N + r;
            v = relay_edges[r][j].second;
            j++;
        }
        if (find_set(u) != find_set(v)) {
            union_sets(u, v);
            temp_selected.push_back({w, u, v, -1});
            selected++;
        }
    }
    for (Edge &e : temp_selected) {
        if (e.u >= N) {
            int rid = e.u - N;
            if (deg_relay[rid] == 0) touched_relays.push_back(rid);
            deg_relay[rid]++;
        }
        if (e.v >= N) {
            int rid = e.v - N;
            if (deg_relay[rid] == 0) touched_relays.push_back(rid);
            deg_relay[rid]++;
        }
    }
    long long pruned_cost = 0;
    for (Edge &e : temp_selected) {
        bool remove = false;
        if (e.u >= N && deg_relay[e.u - N] == 1) remove = true;
        if (e.v >= N && deg_relay[e.v - N] == 1) remove = true;
        if (!remove) pruned_cost += e.w;
    }
    for (int rid : touched_relays) deg_relay[rid] = 0;
    return pruned_cost;
}

void build_new_T(int r) {
    for (int node : T_nodes) {
        parent[node] = node;
        sz[node] = 1;
    }
    parent[N + r] = N + r;
    sz[N + r] = 1;
    int V = T_nodes.size() + 1;
    int selected = 0;
    int i = 0, j = 0;
    vector<Edge> selected_edges;
    selected_edges.reserve(V - 1);
    while (selected < V - 1) {
        long long w;
        int u, v;
        if (i < (int)T_edges.size() && (j >= (int)relay_edges[r].size() || T_edges[i].w <= relay_edges[r][j].first)) {
            w = T_edges[i].w;
            u = T_edges[i].u;
            v = T_edges[i].v;
            i++;
        } else {
            w = relay_edges[r][j].first;
            u = N + r;
            v = relay_edges[r][j].second;
            j++;
        }
        if (find_set(u) != find_set(v)) {
            union_sets(u, v);
            selected_edges.push_back({w, u, v, -1});
            selected++;
        }
    }
    vector<int> deg(K, 0);
    for (Edge &e : selected_edges) {
        if (e.u >= N) deg[e.u - N]++;
        if (e.v >= N) deg[e.v - N]++;
    }
    vector<int> new_T_nodes;
    for (int idx = 0; idx < N; ++idx) new_T_nodes.push_back(idx);
    for (int rid = 0; rid < K; ++rid) {
        if ((in_T[N + rid] || rid == r) && deg[rid] >= 2) {
            new_T_nodes.push_back(N + rid);
        }
    }
    vector<Edge> new_T_edges;
    long long new_T_cost = 0;
    for (Edge &e : selected_edges) {
        bool remove = false;
        if (e.u >= N && deg[e.u - N] == 1) remove = true;
        if (e.v >= N && deg[e.v - N] == 1) remove = true;
        if (!remove) {
            new_T_edges.push_back(e);
            new_T_cost += e.w;
        }
    }
    T_nodes = move(new_T_nodes);
    T_edges = move(new_T_edges);
    T_cost = new_T_cost;
    for (int rid = 0; rid < K; ++rid) in_T[N + rid] = false;
    for (int node : T_nodes) if (node >= N) in_T[node] = true;
}

bool try_remove(int r) {
    int relay_node = N + r;
    long long sum_incident = 0;
    int deg = 0;
    for (Edge &e : T_edges) {
        if (e.u == relay_node || e.v == relay_node) {
            sum_incident += e.w;
            deg++;
        }
    }
    if (deg == 0) return false;
    for (int node : T_nodes) {
        parent[node] = node;
        sz[node] = 1;
    }
    vector<Edge> forest_edges;
    for (Edge &e : T_edges) {
        if (e.u == relay_node || e.v == relay_node) continue;
        forest_edges.push_back(e);
        union_sets(e.u, e.v);
    }
    int need = deg - 1;
    long long added_cost = 0;
    vector<Edge> added_edges;
    if (need > 0) {
        for (Edge &e : all_edges) {
            if (e.u == relay_node || e.v == relay_node) continue;
            if (e.u >= N && !in_T[e.u]) continue;
            if (e.v >= N && !in_T[e.v]) continue;
            if (find_set(e.u) != find_set(e.v)) {
                union_sets(e.u, e.v);
                added_cost += e.w;
                added_edges.push_back(e);
                need--;
                if (need == 0) break;
            }
        }
    }
    if (need > 0) return false;
    long long new_cost = T_cost - sum_incident + added_cost;
    if (new_cost < T_cost) {
        vector<int> new_T_nodes;
        for (int node : T_nodes) if (node != relay_node) new_T_nodes.push_back(node);
        vector<Edge> new_T_edges = move(forest_edges);
        for (Edge &e : added_edges) new_T_edges.push_back(e);
        sort(new_T_edges.begin(), new_T_edges.end(), [](const Edge& a, const Edge& b) { return a.w < b.w; });
        T_nodes = move(new_T_nodes);
        T_edges = move(new_T_edges);
        T_cost = new_cost;
        in_T[relay_node] = false;
        return true;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> N >> K;
    vector<Robot> temp_robots;
    vector<Relay> temp_relays;
    for (int i = 0; i < N + K; ++i) {
        int id;
        long long x, y;
        char type;
        cin >> id >> x >> y >> type;
        if (type == 'C') {
            temp_relays.push_back({x, y, id});
        } else {
            temp_robots.push_back({x, y, type, id});
        }
    }
    robots = move(temp_robots);
    relays = move(temp_relays);
    N = robots.size();
    K = relays.size();

    all_edges.reserve(N * (N - 1) / 2 + K * N);
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            long long dx = robots[i].x - robots[j].x;
            long long dy = robots[i].y - robots[j].y;
            long long D = dx * dx + dy * dy;
            int factor = (robots[i].type == 'S' || robots[j].type == 'S') ? 4 : 5;
            long long w = D * factor;
            all_edges.push_back({w, i, j, -1});
        }
    }
    relay_edges.resize(K);
    for (int r = 0; r < K; ++r) {
        for (int i = 0; i < N; ++i) {
            long long dx = relays[r].x - robots[i].x;
            long long dy = relays[r].y - robots[i].y;
            long long D = dx * dx + dy * dy;
            long long w = D * 5;
            all_edges.push_back({w, N + r, i, r});
            relay_edges[r].push_back({w, i});
        }
    }
    sort(all_edges.begin(), all_edges.end(), [](const Edge& a, const Edge& b) { return a.w < b.w; });
    for (int r = 0; r < K; ++r) {
        sort(relay_edges[r].begin(), relay_edges[r].end());
    }

    T_nodes.clear();
    for (int i = 0; i < N; ++i) T_nodes.push_back(i);
    T_edges.clear();
    T_cost = 0;
    for (int i = 0; i < N; ++i) {
        parent[i] = i;
        sz[i] = 1;
    }
    int edges_needed = N - 1;
    for (Edge &e : all_edges) {
        if (e.relay_idx != -1) continue;
        if (find_set(e.u) != find_set(e.v)) {
            union_sets(e.u, e.v);
            T_edges.push_back(e);
            T_cost += e.w;
            if (--edges_needed == 0) break;
        }
    }
    in_T.assign(N + K, false);
    for (int i = 0; i < N; ++i) in_T[i] = true;

    temp_selected.reserve(3005);

    auto start_time = chrono::steady_clock::now();
    auto get_elapsed = [&]() {
        return chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now() - start_time).count() / 1000.0;
    };

    for (int round = 0; round < 3; ++round) {
        priority_queue<pair<long long, int>> pq;
        for (int r = 0; r < K; ++r) {
            if (in_T[N + r]) continue;
            long long new_cost = eval_add(r);
            long long imp = T_cost - new_cost;
            if (imp > 0) pq.push({imp, r});
        }
        while (!pq.empty()) {
            if (get_elapsed() > 8.5) break;
            auto [imp_cached, r] = pq.top();
            pq.pop();
            if (in_T[N + r]) continue;
            long long new_cost = eval_add(r);
            long long imp = T_cost - new_cost;
            if (imp <= 0) continue;
            if (!pq.empty() && pq.top().first > imp) {
                pq.push({imp, r});
                continue;
            }
            build_new_T(r);
        }
        bool changed = true;
        while (changed && get_elapsed() < 8.5) {
            changed = false;
            vector<int> relays_in_T;
            for (int r = 0; r < K; ++r) if (in_T[N + r]) relays_in_T.push_back(r);
            for (int r : relays_in_T) {
                if (!in_T[N + r]) continue;
                if (get_elapsed() > 8.5) break;
                if (try_remove(r)) {
                    changed = true;
                }
            }
        }
    }

    vector<int> selected_relays;
    for (int r = 0; r < K; ++r) {
        if (in_T[N + r]) selected_relays.push_back(relays[r].id);
    }
    if (selected_relays.empty()) {
        cout << "#\n";
    } else {
        for (size_t i = 0; i < selected_relays.size(); ++i) {
            if (i > 0) cout << "#";
            cout << selected_relays[i];
        }
        cout << "\n";
    }
    for (size_t i = 0; i < T_edges.size(); ++i) {
        if (i > 0) cout << "#";
        Edge &e = T_edges[i];
        int u = e.u;
        int v = e.v;
        int id_u, id_v;
        if (u < N) id_u = robots[u].id;
        else id_u = relays[u - N].id;
        if (v < N) id_v = robots[v].id;
        else id_v = relays[v - N].id;
        cout << id_u << "-" << id_v;
    }
    cout << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
static const ll INF = (1LL << 62);

struct Dev { ll x, y; int id; char tp; };
struct TE { int u, v; ll w; };

int N, K, M;
vector<Dev> D;
vector<char> relayAlive;   // 1 = relay still free
vector<char> nodeIn;       // 1 = node currently in the active set
vector<char> robotAlive;
vector<int> robots, relays;

vector<TE> gEdges;         // current tree (edges)
ll gCost = 0;              // current tree cost (scaled by 40)

auto T0 = chrono::steady_clock::now();
const ll TIME_BUDGET_MS = 8200;

bool timeUp() {
    return chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now() - T0).count() > TIME_BUDGET_MS;
}

// ---------------- cost helpers (all scaled by 40) ----------------
inline ll d2f(int a, int b) {
    ll dx = D[a].x - D[b].x, dy = D[a].y - D[b].y;
    return dx * dx + dy * dy;
}
// link cost: R-R = 40*D ; R-S / S-S = 32*D ; C-any = 40*D
inline ll Wf(int a, int b) {
    ll d = d2f(a, b);
    if (D[a].tp == 'C' || D[b].tp == 'C') return 40 * d;
    if (D[a].tp == 'S' || D[b].tp == 'S') return 32 * d;
    return 40 * d;
}
// "A" coefficient: max possible gain when subdividing edge (a,b) with a relay
inline ll Af(int a, int b) {
    ll d = d2f(a, b);
    if (D[a].tp == 'C' || D[b].tp == 'C') return 20 * d;
    if (D[a].tp == 'S' || D[b].tp == 'S') return 12 * d;
    return 20 * d;
}

// ---------------- kd-tree ----------------
struct KDTree {
    struct Nd { ll x, y; int id; int l = -1, r = -1; int ax = 0; };
    vector<Nd> t;
    int root = -1;
    const vector<char>* al = nullptr;

    int build(vector<Nd>& v, int l, int r, int dep) {
        if (l >= r) return -1;
        int mid = (l + r) >> 1, ax = dep & 1;
        nth_element(v.begin() + l, v.begin() + mid, v.begin() + r,
                    [ax](const Nd& a, const Nd& b) { return ax ? (a.y < b.y) : (a.x < b.x); });
        int id = (int)t.size();
        t.push_back(v[mid]);
        t[id].ax = ax;
        t[id].l = build(v, l, mid, dep + 1);
        t[id].r = build(v, mid + 1, r, dep + 1);
        return id;
    }
    void init(vector<Nd>& v, const vector<char>* alive) {
        al = alive;
        t.clear();
        t.reserve(v.size() + 1);
        root = build(v, 0, (int)v.size(), 0);
    }
    void srch(int n, ll qx, ll qy, ll& best, int& bid) const {
        const Nd& nd = t[n];
        ll dx = qx - nd.x, dy = qy - nd.y, d = dx * dx + dy * dy;
        if ((*al)[nd.id] && d < best) { best = d; bid = nd.id; }
        ll delta = nd.ax ? (qy - nd.y) : (qx - nd.x);
        int n1 = delta < 0 ? nd.l : nd.r;
        int n2 = delta < 0 ? nd.r : nd.l;
        if (n1 >= 0) srch(n1, qx, qy, best, bid);
        if (n2 >= 0) { ll bd = delta * delta; if (bd < best) srch(n2, qx, qy, best, bid); }
    }
    int nearest(ll qx, ll qy, ll& bd) const {
        ll b = INF; int id = -1;
        if (root >= 0) srch(root, qx, qy, b, id);
        bd = b; return id;
    }
    void ksrch(int n, ll qx, ll qy, priority_queue<pair<ll,int>>& h, int k) const {
        const Nd& nd = t[n];
        ll dx = qx - nd.x, dy = qy - nd.y, d = dx * dx + dy * dy;
        if ((*al)[nd.id]) {
            if ((int)h.size() < k) h.push({d, nd.id});
            else if (d < h.top().first) { h.pop(); h.push({d, nd.id}); }
        }
        ll delta = nd.ax ? (qy - nd.y) : (qx - nd.x);
        int n1 = delta < 0 ? nd.l : nd.r;
        int n2 = delta < 0 ? nd.r : nd.l;
        if (n1 >= 0) ksrch(n1, qx, qy, h, k);
        if (n2 >= 0) { ll bd = delta * delta; if ((int)h.size() < k || bd < h.top().first) ksrch(n2, qx, qy, h, k); }
    }
    void knearest(ll qx, ll qy, int k, vector<int>& out) const {
        priority_queue<pair<ll,int>> h;
        if (root >= 0) ksrch(root, qx, qy, h, k);
        out.clear();
        while (!h.empty()) { out.push_back(h.top().second); h.pop(); }
        reverse(out.begin(), out.end());
    }
};

KDTree kdRob, kdRel, kdAct;

void rebuildRelayKD() {
    vector<KDTree::Nd> pts;
    for (int r : relays) if (relayAlive[r])
        pts.push_back({2 * D[r].x, 2 * D[r].y, r, -1, -1, 0});
    kdRel.init(pts, &relayAlive);
}

// ---------------- union find / mst ----------------
struct UFD {
    vector<int> p;
    void init(int n) { p.resize(n); iota(p.begin(), p.end(), 0); }
    int find(int x) { while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; } return x; }
    bool uni(int a, int b) { a = find(a); b = find(b); if (a == b) return false; p[a] = b; return true; }
};

ll primMST(const vector<int>& vs, vector<TE>& out) {
    out.clear();
    int m = (int)vs.size();
    if (m <= 1) return 0;
    vector<ll> best(m, INF); vector<int> par(m, -1); vector<char> done(m, 0);
    best[0] = 0; ll tot = 0;
    for (int it = 0; it < m; it++) {
        int bi = -1; ll bv = INF;
        for (int i = 0; i < m; i++) if (!done[i] && best[i] < bv) { bv = best[i]; bi = i; }
        if (bi < 0) break;
        done[bi] = 1; tot += bv;
        if (par[bi] >= 0) out.push_back({vs[bi], vs[par[bi]], bv});
        for (int i = 0; i < m; i++) if (!done[i]) {
            int a = vs[bi], b = vs[i];
            if (D[a].tp == 'C' && D[b].tp == 'C') continue;
            ll w = Wf(a, b);
            if (w < best[i]) { best[i] = w; par[i] = bi; }
        }
    }
    return tot;
}

// merged kruskal of two edge lists already sorted by weight
ll kruskalMerge(const vector<TE>& A, const vector<TE>& B, vector<TE>& out) {
    out.clear();
    UFD uf; uf.init(M);
    size_t i = 0, j = 0; ll tot = 0;
    while (i < A.size() || j < B.size()) {
        TE e;
        if (j >= B.size() || (i < A.size() && A[i].w <= B[j].w)) e = A[i++];
        else e = B[j++];
        if (D[e.u].tp == 'C' && D[e.v].tp == 'C') continue;
        if (uf.uni(e.u, e.v)) { out.push_back(e); tot += e.w; }
    }
    return tot;
}

void setTree(const vector<TE>& es) {
    gEdges = es; gCost = 0;
    for (auto& e : gEdges) gCost += e.w;
}

// exact MST over the currently active node set (robots + used relays)
void exactMST() {
    vector<int> act;
    act.reserve(robots.size() + relays.size());
    for (int r : robots) act.push_back(r);
    for (int r : relays) if (!relayAlive[r]) act.push_back(r);
    vector<TE> es;
    ll c = primMST(act, es);
    if (c <= gCost) setTree(es);
}

// remove relays that ended up as useless leaves
void pruneLeaves() {
    bool changed = true;
    while (changed) {
        changed = false;
        vector<int> deg(M, 0);
        for (auto& e : gEdges) { deg[e.u]++; deg[e.v]++; }
        for (int r : relays) {
            if (relayAlive[r]) continue;
            if (deg[r] == 1) {
                for (size_t i = 0; i < gEdges.size(); i++) {
                    if (gEdges[i].u == r || gEdges[i].v == r) {
                        gCost -= gEdges[i].w;
                        gEdges.erase(gEdges.begin() + i);
                        break;
                    }
                }
                relayAlive[r] = 1;
                changed = true;
                break;
            }
        }
    }
}

// ---------------- robot level structure (sparse, relay aware) ----------------
vector<TE> buildRobotLevel() {
    vector<TE> cand;
    // plain robot MST edges (guarantees connectivity + good baseline)
    {
        vector<TE> es; primMST(robots, es);
        for (auto& e : es) cand.push_back(e);
    }
    // near robot-robot direct edges
    for (int u : robots) {
        vector<int> nr; kdRob.knearest(D[u].x, D[u].y, 9, nr);
        for (int v : nr) if (v != u) cand.push_back({u, v, Wf(u, v)});
    }
    // relay mediated robot pairs
    for (int c : relays) {
        vector<int> nr; kdRob.knearest(D[c].x, D[c].y, 8, nr);
        int k = (int)nr.size();
        for (int i = 0; i < k; i++)
            for (int j = i + 1; j < k; j++) {
                int u = nr[i], v = nr[j];
                ll w = 40 * (d2f(u, c) + d2f(c, v));
                cand.push_back({u, v, w});
            }
    }
    sort(cand.begin(), cand.end(), [](const TE& a, const TE& b) { return a.w < b.w; });
    UFD uf; uf.init(M);
    vector<TE> tree;
    for (auto& e : cand) if (uf.uni(e.u, e.v)) tree.push_back(e);
    if ((int)tree.size() != (int)robots.size() - 1) {
        vector<TE> es; primMST(robots, es);
        for (auto& e : es) if (uf.uni(e.u, e.v)) tree.push_back(e);
    }
    return tree;
}

// ---------------- greedy relay subdivision ----------------
void phaseA() {
    vector<int> rl;
    for (int i = 0; i < (int)gEdges.size(); i++) {
        int u = gEdges[i].u, v = gEdges[i].v;
        if (D[u].tp != 'C' && D[v].tp != 'C') rl.push_back(i);
    }
    sort(rl.begin(), rl.end(), [](int a, int b) {
        return Af(gEdges[a].u, gEdges[a].v) > Af(gEdges[b].u, gEdges[b].v);
    });
    int since = 0;
    while (!rl.empty() && !timeUp()) {
        ll bestGain = 0; int bestPos = -1, bestC = -1;
        for (int pos = 0; pos < (int)rl.size(); pos++) {
            TE e = gEdges[rl[pos]];
            ll A = Af(e.u, e.v);
            if (A <= bestGain) break;
            ll qx = D[e.u].x + D[e.v].x, qy = D[e.u].y + D[e.v].y;
            ll dd; int c = kdRel.nearest(qx, qy, dd);
            if (c < 0) continue;
            ll gain = A - 20 * dd;
            if (gain > bestGain) { bestGain = gain; bestPos = pos; bestC = c; }
        }
        if (bestPos < 0) break;
        int ei = rl[bestPos]; TE e = gEdges[ei];
        ll w1 = Wf(e.u, bestC), w2 = Wf(bestC, e.v);
        gEdges[ei] = {e.u, bestC, w1};
        gEdges.push_back({bestC, e.v, w2});
        gCost += w1 + w2 - e.w;
        rl.erase(rl.begin() + bestPos);
        relayAlive[bestC] = 0;
        if (++since >= 40) { rebuildRelayKD(); since = 0; }
    }
}

// ---------------- exact insertion of a free relay (hub / restructure aware) ----
bool b1Step() {
    vector<int> act;
    act.reserve(robots.size() + relays.size());
    for (int r : robots) act.push_back(r);
    for (int r : relays) if (!relayAlive[r]) act.push_back(r);
    if (act.empty()) return false;

    for (int i = 0; i < M; i++) nodeIn[i] = 0;
    for (int a : act) nodeIn[a] = 1;
    {
        vector<KDTree::Nd> pts; pts.reserve(act.size());
        for (int a : act) pts.push_back({D[a].x, D[a].y, a, -1, -1, 0});
        kdAct.init(pts, &nodeIn);
    }
    vector<TE> st = gEdges;
    sort(st.begin(), st.end(), [](const TE& a, const TE& b) { return a.w < b.w; });
    ll maxW = st.empty() ? 0 : st.back().w;

    ll bestDelta = 0; int bestC = -1; vector<TE> bestTree;
    vector<int> nr; vector<TE> star; vector<TE> out;
    for (int c : relays) {
        if (!relayAlive[c]) continue;
        kdAct.knearest(D[c].x, D[c].y, 12, nr);
        if (nr.empty()) continue;
        ll mn = INF;
        for (int x : nr) mn = min(mn, Wf(c, x));
        if (mn >= maxW) continue;          // cannot possibly improve
        star.clear();
        for (int x : nr) star.push_back({c, x, Wf(c, x)});
        sort(star.begin(), star.end(), [](const TE& a, const TE& b) { return a.w < b.w; });
        ll cost = kruskalMerge(st, star, out);
        ll delta = cost - gCost;
        if (delta < bestDelta) { bestDelta = delta; bestC = c; bestTree = out; }
    }
    if (bestC < 0) return false;
    setTree(bestTree);
    relayAlive[bestC] = 0;
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> N >> K)) return 0;
    M = N + K;
    D.resize(M);
    for (int i = 0; i < M; i++) {
        int id; ll x, y; char t;
        cin >> id >> x >> y >> t;
        D[i] = {x, y, id, t};
    }
    for (int i = 0; i < M; i++) {
        if (D[i].tp == 'C') relays.push_back(i); else robots.push_back(i);
    }
    relayAlive.assign(M, 0); nodeIn.assign(M, 0); robotAlive.assign(M, 0);
    for (int r : relays) relayAlive[r] = 1;
    for (int r : robots) robotAlive[r] = 1;

    {
        vector<KDTree::Nd> pts; pts.reserve(robots.size());
        for (int r : robots) pts.push_back({D[r].x, D[r].y, r, -1, -1, 0});
        kdRob.init(pts, &robotAlive);
    }
    rebuildRelayKD();

    setTree(buildRobotLevel());

    phaseA();
    for (int it = 0; it < 8 && !timeUp(); it++) {
        exactMST(); pruneLeaves(); exactMST();
        ll c0 = gCost;
        phaseA();
        if (gCost >= c0) break;
    }

    for (int s = 0; s < 400 && !timeUp(); s++) {
        if (!b1Step()) break;
    }

    if (!timeUp()) {
        exactMST(); pruneLeaves(); exactMST();
        phaseA();
        exactMST(); pruneLeaves(); exactMST();
    }

    // -------- output --------
    vector<int> sel;
    for (int r : relays) if (!relayAlive[r]) sel.push_back(r);
    sort(sel.begin(), sel.end(), [](int a, int b) { return D[a].id < D[b].id; });
    if (sel.empty()) cout << "#\n";
    else {
        for (size_t i = 0; i < sel.size(); i++) {
            if (i) cout << '#';
            cout << D[sel[i]].id;
        }
        cout << '\n';
    }
    vector<pair<int,int>> links;
    for (auto& e : gEdges) {
        int a = D[e.u].id, b = D[e.v].id;
        if (a > b) swap(a, b);
        links.push_back({a, b});
    }
    sort(links.begin(), links.end());
    if (links.empty()) cout << '\n';
    else {
        for (size_t i = 0; i < links.size(); i++) {
            if (i) cout << '#';
            cout << links[i].first << '-' << links[i].second;
        }
        cout << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int ask(int v, long long x) {
    cout << "? " << v << " " << x << '\n' << flush;
    int response;
    cin >> response;
    return response;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    for (int tc = 0; tc < n; ++tc) {
        int start = ask(1, 1);

        vector<int> cache(1025, -1);
        cache[0] = start;

        auto getValue = [&](int x) -> int {
            if (cache[x] == -1) cache[x] = ask(start, x);
            return cache[x];
        };

        auto attempt = [&](int baby, int giants) -> int {
            unordered_map<int, int> position;
            position.reserve(2 * baby + 10);

            for (int i = 0; i < baby; ++i) {
                int w = getValue(i);
                auto it = position.find(w);
                if (it != position.end()) return i - it->second;
                position.emplace(w, i);
            }

            for (int k = 1; k <= giants; ++k) {
                int x = k * baby;
                int w = getValue(x);
                auto it = position.find(w);
                if (it != position.end()) return x - it->second;
            }
            return -1;
        };

        int answer = attempt(2, 4);
        if (answer == -1) answer = attempt(8, 4);
        if (answer == -1) answer = attempt(32, 32);

        if (answer == -1) {
            unordered_map<int, int> position;
            position.reserve(2048);

            for (int i = 0; i < 1000; ++i) {
                int w = getValue(i);
                auto it = position.find(w);
                if (it != position.end()) {
                    answer = i - it->second;
                    break;
                }
                position.emplace(w, i);
            }

            int k = 2;
            while (answer == -1) {
                int x = k * 1000;
                int w = ask(start, x);
                auto it = position.find(w);
                if (it != position.end()) answer = x - it->second;
                ++k;
            }
        }

        cout << "! " << answer << '\n' << flush;
        int verdict;
        if (!(cin >> verdict) || verdict == -1) return 0;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int MAXV = 1000000;
static const int B = 1000;

long long ask(long long v, long long x) {
    cout << "? " << v << " " << x << endl;
    cout.flush();
    long long res;
    if (!(cin >> res)) exit(0);
    return res;
}

bool answer(long long s) {
    cout << "! " << s << endl;
    cout.flush();
    int verdict;
    if (!(cin >> verdict)) exit(0);
    return verdict == 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> seen(MAXV + 1, -1);

    for (int g = 0; g < n; ++g) {
        long long a = ask(1, 1);
        long long s = -1;

        seen[a] = 0;

        for (int i = 1; i <= B; ++i) {
            long long r = ask(a, i);
            if (r == a) {
                s = i;
                break;
            }
            seen[r] = i;
        }

        if (s == -1) {
            for (long long j = 2; ; ++j) {
                long long x = j * B;
                long long r = ask(a, x);
                if (seen[r] != -1) {
                    s = x - seen[r];
                    break;
                }
            }
        }

        if (!answer(s)) return 0;

        seen[a] = -1;
        for (int i = 1; i <= min<long long>(B, s - 1); ++i) {
            // Entries are cleared below by reconstructing only when necessary.
        }
        fill(seen.begin(), seen.end(), -1);
    }

    return 0;
}

