#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

constexpr int MAX_VERTEX = 1'000'000;
constexpr int QUERY_LIMIT = 2500;
constexpr int EXTRACTION_RESERVE = 32;
constexpr int EXPONENT_RANGE = 1'000'000'000;

static int firstExponent[MAX_VERTEX + 1];

int64 randomExponent(mt19937_64& rng) {
    return uniform_int_distribution<int>(1, EXPONENT_RANGE)(rng);
}

vector<pair<int64, int>> factorSmallPrimes(int64 value) {
    vector<pair<int64, int>> factors;
    int64 remaining = value;

    for (int64 p = 2; p * p <= remaining; ++p) {
        if (remaining % p != 0) continue;

        int exponent = 0;
        do {
            remaining /= p;
            ++exponent;
        } while (remaining % p == 0);

        if (p <= MAX_VERTEX) {
            factors.emplace_back(p, exponent);
        }
    }

    if (remaining > 1 && remaining <= MAX_VERTEX) {
        factors.emplace_back(remaining, 1);
    }

    return factors;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    uint64_t seed = chrono::high_resolution_clock::now().time_since_epoch().count();
    seed ^= uint64_t(random_device{}()) << 32;
    mt19937_64 rng(seed);

    int queries = 0;

    auto ask = [&](int vertex, int64 exponent) -> int {
        cout << "? " << vertex << ' ' << exponent << endl;
        if (!(cin >> queries)) {
            exit(0);
        }
        ++queries;

        int result;
        if (!(cin >> result)) exit(0);
        return result;
    };

    auto recoverPeriod = [&](int64 multiple, int cycleVertex) -> int64 {
        auto factors = factorSmallPrimes(multiple);
        int64 answer = 1;

        for (auto [prime, exponent] : factors) {
            int64 fullPower = 1;
            for (int i = 0; i < exponent; ++i) {
                fullPower *= prime;
            }

            int64 remainingMultiple = multiple / fullPower;

            int low = 0;
            int high = exponent;

            while (low < high) {
                int mid = (low + high) / 2;

                int64 primePower = 1;
                for (int i = 0; i < mid; ++i) {
                    primePower *= prime;
                }

                int64 testExponent = remainingMultiple * primePower;
                bool isPeriod = (ask(cycleVertex, testExponent) == cycleVertex);

                if (isPeriod) {
                    high = mid;
                } else {
                    low = mid + 1;
                }
            }

            for (int i = 0; i < low; ++i) {
                answer *= prime;
            }
        }

        return answer;
    };

    while (n--) {
        fill(firstExponent, firstExponent + MAX_VERTEX + 1, -1);

        int cycleVertex = ask(1, 1);
        firstExponent[cycleVertex] = 0;

        int64 difference = 0;

        while (difference == 0 && queries < QUERY_LIMIT - EXTRACTION_RESERVE) {
            int64 exponent = randomExponent(rng);
            int result = ask(cycleVertex, exponent);

            if (firstExponent[result] == -1) {
                firstExponent[result] = static_cast<int>(exponent);
            } else {
                int64 previous = firstExponent[result];
                if (previous != exponent) {
                    difference = exponent > previous
                                   ? exponent - previous
                                   : previous - exponent;
                }
            }
        }

        if (difference == 0) {
            int64 exponent = randomExponent(rng);
            int result = ask(cycleVertex, exponent);

            if (firstExponent[result] != -1) {
                int64 previous = firstExponent[result];
                if (previous != exponent) {
                    difference = exponent > previous
                                   ? exponent - previous
                                   : previous - exponent;
                }
            }
        }

        if (difference == 0) {
            int result = ask(cycleVertex, MAX_VERTEX);
            if (result == cycleVertex) {
                difference = MAX_VERTEX;
            } else {
                constexpr int64 FALLBACK_MULTIPLE = 223092870;
                result = ask(cycleVertex, FALLBACK_MULTIPLE);
                if (result == cycleVertex) {
                    difference = FALLBACK_MULTIPLE;
                }
            }
        }

        int64 answer = (difference != 0)
                           ? recoverPeriod(difference, cycleVertex)
                           : MAX_VERTEX;

        cout << "! " << answer << endl;

        int verdict;
        if (!(cin >> verdict) || verdict != 1) return 0;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Builder {
    int n, N, mode;
    vector<vector<unsigned char>> adj;
    vector<vector<int>> out;
    vector<array<int, 3>> ops;

    Builder(int n_, int mode_) : n(n_), N(n_ + 1), mode(mode_) {
        adj.assign(N, vector<unsigned char>(N, 0));
        out.assign(N, {});
        for (int i = 0; i < n; ++i) {
            adj[i][i + 1] = 1;
            out[i].push_back(i + 1);
        }
    }

    void addEdge(int a, int b, int c) {
        if (adj[a][c]) return;
        adj[a][c] = 1;
        out[a].push_back(c);
        ops.push_back({a, b, c});
    }

    bool withinTwo(int v, int t) {
        if (adj[v][t]) return true;
        for (int b : out[v]) {
            if (b < t && adj[b][t]) return true;
        }
        return false;
    }

    bool findTwoPath(int v, int t, int &mid) {
        for (int b : out[v]) {
            if (b < t && adj[b][t]) {
                mid = b;
                return true;
            }
        }
        return false;
    }

    int leftSize(int L) {
        int a;
        if (mode == 0) {
            a = (L + 1) / 2;
        } else if (mode == 1) {
            a = (2 * L + 2) / 3;
        } else if (mode == 2) {
            a = (7 * L + 9) / 10;
        } else if (mode == 3) {
            a = (3 * L + 3) / 4;
        } else {
            if (L <= 32) a = L - 3;
            else a = (7 * L + 9) / 10;
        }
        return max(1, min(L - 1, a));
    }

    void solve(int l, int r) {
        int L = r - l;
        if (L <= 3) return;

        if (L == 4) {
            addEdge(l + 2, l + 3, l + 4);
            return;
        }

        if (L <= 8) {
            int h = l + 4;
            addEdge(h - 2, h - 1, h);
            addEdge(h - 3, h - 2, h);
            for (int c = h + 2; c <= r; ++c) {
                addEdge(h, c - 1, c);
            }
            return;
        }

        int a = leftSize(L);
        int h = l + a;

        solve(l, h);
        solve(h, r);

        for (int u = h + 2; u <= r; ++u) {
            if (!adj[h][u]) addEdge(h, u - 1, u);
        }

        for (int v = h - 1; v >= l; --v) {
            if (withinTwo(v, h)) continue;
            int src = v + 1;
            int mid = -1;
            findTwoPath(src, h, mid);
            addEdge(src, mid, h);
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<array<int, 3>> best;
    bool first = true;

    for (int mode = 0; mode < 5; ++mode) {
        Builder builder(n, mode);
        builder.solve(0, n);
        if (first || builder.ops.size() < best.size()) {
            best = builder.ops;
            first = false;
        }
    }

    cout << best.size() << '\n';
    for (auto &op : best) {
        cout << op[0] << ' ' << op[1] << ' ' << op[2] << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Op {
    int a, b, c;
};

int n;
vector<int> dp, choice;
vector<Op> answer;
set<pair<int, int>> added;

void addEdge(int a, int b, int c) {
    if (added.count({a, c})) return;
    added.insert({a, c});
    answer.push_back({a, b, c});
}

void solveBase5(int l) {
    const vector<vector<Op>> candidates = {
        {{0, 1, 2}, {2, 3, 4}},
        {{2, 3, 4}, {1, 2, 4}},
        {{1, 2, 3}, {1, 3, 4}},
        {{0, 1, 2}, {3, 4, 5}},
        {{1, 2, 3}, {3, 4, 5}}
    };

    int best = 0, bestMissing = INT_MAX;
    for (int i = 0; i < (int)candidates.size(); ++i) {
        int missing = 0;
        for (const Op &op : candidates[i]) {
            if (!added.count({l + op.a, l + op.c})) ++missing;
        }
        if (missing < bestMissing) {
            bestMissing = missing;
            best = i;
        }
    }

    for (const Op &op : candidates[best]) {
        addEdge(l + op.a, l + op.b, l + op.c);
    }
}

void solve(int l, int r) {
    int len = r - l;
    if (len <= 3) return;

    if (len == 4) {
        if (added.count({l, l + 2}) || added.count({l + 2, r})) return;
        addEdge(l, l + 1, l + 2);
        return;
    }

    if (len == 5) {
        solveBase5(l);
        return;
    }

    int leftLen = choice[len];
    int A = l + leftLen;
    int B = A + 4;

    for (int u = A - 2; u >= l; --u) {
        addEdge(u, u + 1, A);
    }

    for (int v = B + 2; v <= r; ++v) {
        addEdge(B, v - 1, v);
    }

    addEdge(A + 1, A + 2, A + 3);
    addEdge(A + 1, A + 3, B);
    addEdge(A, A + 1, B);

    solve(l, A);
    solve(B, r);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    dp.assign(n + 1, 0);
    choice.assign(n + 1, 0);

    if (n >= 4) dp[4] = 1;
    if (n >= 5) dp[5] = 2;

    for (int len = 6; len <= n; ++len) {
        int best = INT_MAX;
        int bestLeft = 1;

        for (int left = 1; left <= len - 5; ++left) {
            int right = len - 4 - left;
            int current = len - 3 + dp[left] + dp[right];
            if (current < best) {
                best = current;
                bestLeft = left;
            }
        }

        dp[len] = best;
        choice[len] = bestLeft;
    }

    if (n >= 4) solve(0, n);

    cout << answer.size() << '\n';
    for (const Op &op : answer) {
        cout << op.a << ' ' << op.b << ' ' << op.c << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
int dp[4097][64];
struct Recon {
    int k, p1, p2, flag;
} recon[4097][64];
vector<int> profiles[4097];

int encode(int a, int b, int c) {
    return a * 16 + b * 4 + c;
}

void build(int L, int l, int p, vector<tuple<int,int,int>>& edges) {
    if (L == 0) return;
    if (L <= 3) {
        int a = p / 16, b = (p / 4) % 4, c = p % 4;
        if (L == 1) {
            // no edges
        } else if (L == 2) {
            if (a == 2 && b == 2 && c == 2) {
                // no edges
            } else if (a == 1 && b == 1 && c == 1) {
                edges.emplace_back(l, l + 1, l + 2);
            }
        } else if (L == 3) {
            if (a == 3 && b == 3 && c == 3) {
                // no edges
            } else if (a == 2 && b == 2 && c == 2) {
                edges.emplace_back(l, l + 1, l + 2);
            } else if (a == 1 && b == 1 && c == 2) {
                edges.emplace_back(l, l + 1, l + 2);
                edges.emplace_back(l, l + 2, l + 3);
            } else if (a == 1 && b == 2 && c == 1) {
                edges.emplace_back(l + 1, l + 2, l + 3);
                edges.emplace_back(l, l + 1, l + 3);
            } else if (a == 1 && b == 1 && c == 1) {
                edges.emplace_back(l, l + 1, l + 2);
                edges.emplace_back(l + 1, l + 2, l + 3);
                edges.emplace_back(l, l + 2, l + 3);
            }
        }
        return;
    }
    int k = recon[L][p].k;
    int p1 = recon[L][p].p1;
    int p2 = recon[L][p].p2;
    int flag = recon[L][p].flag;
    build(k, l, p1, edges);
    build(L - k, l + k, p2, edges);
    if (flag == 1) {
        edges.emplace_back(l, l + k, l + L);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    if (n == 0) {
        cout << 0 << "\n";
        return 0;
    }

    for (int i = 0; i <= n; ++i)
        for (int j = 0; j < 64; ++j)
            dp[i][j] = INF;

    // Base cases
    int p = encode(1, 1, 1);
    dp[1][p] = 0;
    profiles[1].push_back(p);

    p = encode(2, 2, 2); dp[2][p] = 0; profiles[2].push_back(p);
    p = encode(1, 1, 1); dp[2][p] = 1; profiles[2].push_back(p);

    p = encode(3, 3, 3); dp[3][p] = 0; profiles[3].push_back(p);
    p = encode(2, 2, 2); dp[3][p] = 1; profiles[3].push_back(p);
    p = encode(1, 1, 2); dp[3][p] = 2; profiles[3].push_back(p);
    p = encode(1, 2, 1); dp[3][p] = 2; profiles[3].push_back(p);
    p = encode(1, 1, 1); dp[3][p] = 3; profiles[3].push_back(p);

    int combine[64][64];
    int add_combine[64][64];
    for (int p1 = 0; p1 < 64; ++p1) {
        int a1 = p1 / 16, b1 = (p1 / 4) % 4, c1 = p1 % 4;
        for (int p2 = 0; p2 < 64; ++p2) {
            int a2 = p2 / 16, b2 = (p2 / 4) % 4, c2 = p2 % 4;
            combine[p1][p2] = -1;
            add_combine[p1][p2] = -1;
            if (c1 + b2 <= 3) {
                int na = min(4, a1 + a2);
                int nb = min(4, max(b1, a1 + b2));
                int nc = min(4, max(c2, c1 + a2));
                if (na <= 3 && nb <= 3 && nc <= 3) {
                    combine[p1][p2] = na * 16 + nb * 4 + nc;
                }
                if (a1 == 1 && a2 == 1) {
                    int na2 = 1;
                    int nb2 = min(4, max(b1, a1 + b2));
                    int nc2 = min(4, max(c2, c1 + a2));
                    if (nb2 <= 3 && nc2 <= 3) {
                        add_combine[p1][p2] = na2 * 16 + nb2 * 4 + nc2;
                    }
                }
            }
        }
    }

    for (int L = 4; L <= n; ++L) {
        for (int k = 1; k < L; ++k) {
            int L1 = k, L2 = L - k;
            for (int p1 : profiles[L1]) {
                int cost1 = dp[L1][p1];
                for (int p2 : profiles[L2]) {
                    int cost2 = dp[L2][p2];

                    int newp = combine[p1][p2];
                    if (newp != -1) {
                        int cost = cost1 + cost2;
                        if (cost < dp[L][newp]) {
                            dp[L][newp] = cost;
                            recon[L][newp] = {k, p1, p2, 0};
                        }
                    }

                    newp = add_combine[p1][p2];
                    if (newp != -1) {
                        int cost = cost1 + cost2 + 1;
                        if (cost < dp[L][newp]) {
                            dp[L][newp] = cost;
                            recon[L][newp] = {k, p1, p2, 1};
                        }
                    }
                }
            }
        }
        for (int p = 0; p < 64; ++p) {
            if (dp[L][p] < INF) {
                profiles[L].push_back(p);
            }
        }
    }

    int best_p = -1;
    int best_cost = INF;
    for (int p : profiles[n]) {
        if (dp[n][p] < best_cost) {
            best_cost = dp[n][p];
            best_p = p;
        }
    }

    if (best_p == -1) return 0;

    vector<tuple<int,int,int>> edges;
    build(n, 0, best_p, edges);

    cout << edges.size() << "\n";
    for (auto &e : edges) {
        cout << get<0>(e) << " " << get<1>(e) << " " << get<2>(e) << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Addition {
    int u, c, v;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    const int N = n + 1;
    const int INF = 1'000'000'000;
    const int MAXK = 10;

    vector<int> baseCost(N + 1, INF);
    for (int s = 0; s <= min(N, 4); ++s) baseCost[s] = 0;
    if (N >= 5) baseCost[5] = 1;
    if (N >= 6) baseCost[6] = 2;
    if (N >= 7) baseCost[7] = 3;
    if (N >= 8) baseCost[8] = 4;
    if (N >= 9) baseCost[9] = 5;
    if (N >= 10) baseCost[10] = 6;

    vector<int> best(N + 1, INF);
    vector<int> chosenK(N + 1, -1);

    vector<vector<int>> A(MAXK + 1, vector<int>(N + 1, INF));
    vector<vector<int>> aChoice(MAXK + 1, vector<int>(N + 1, -1));
    vector<vector<int>> dChoice(MAXK + 1, vector<int>(N + 1, -1));

    vector<int> endCost(N + 1, 0);
    vector<int> middleCost(N + 1, 0);

    for (int s = 0; s <= N; ++s) {
        if (baseCost[s] < INF) best[s] = baseCost[s];

        for (int k = 2; k <= min(MAXK, s + 1); ++k) {
            int separators = k - 1;
            int r = s - separators;

            int value = INF;
            int arg = 0;
            const auto &prev = A[k - 1];

            for (int x = 0; x <= r; ++x) {
                int candidate = prev[r - x] + endCost[x];
                if (candidate < value) {
                    value = candidate;
                    arg = x;
                }
            }

            dChoice[k][r] = arg;
            int candidate = value + separators * (separators - 1) / 2;

            if (candidate < best[s]) {
                best[s] = candidate;
                chosenK[s] = k;
            }
        }

        endCost[s] = best[s] + s - (s > 0 ? 1 : 0);
        middleCost[s] = best[s] + 2 * s - (s > 0 ? 2 : 1);

        A[1][s] = endCost[s];

        for (int k = 2; k <= MAXK; ++k) {
            int value = INF;
            int arg = 0;
            const auto &prev = A[k - 1];

            for (int x = 0; x <= s; ++x) {
                int candidate = prev[s - x] + middleCost[x];
                if (candidate < value) {
                    value = candidate;
                    arg = x;
                }
            }

            A[k][s] = value;
            aChoice[k][s] = arg;
        }
    }

    function<vector<int>(int, int)> reconstructA =
        [&](int k, int total) -> vector<int> {
            if (k == 1) return {total};

            int x = aChoice[k][total];
            vector<int> result = reconstructA(k - 1, total - x);
            result.push_back(x);
            return result;
        };

    vector<Addition> additions;

    auto add = [&](int u, int c, int v) {
        additions.push_back({u, c, v});
    };

    auto addBase = [&](int offset, int size) {
        auto addRelative = [&](int u, int c, int v) {
            add(offset + u, offset + c, offset + v);
        };

        switch (size) {
            case 5:
                addRelative(1, 2, 3);
                break;
            case 6:
                addRelative(2, 3, 4);
                addRelative(1, 2, 4);
                break;
            case 7:
                addRelative(2, 3, 4);
                addRelative(1, 2, 4);
                addRelative(4, 5, 6);
                break;
            case 8:
                addRelative(1, 2, 3);
                addRelative(3, 4, 5);
                addRelative(1, 3, 5);
                addRelative(5, 6, 7);
                break;
            case 9:
                addRelative(1, 2, 3);
                addRelative(3, 4, 5);
                addRelative(1, 3, 5);
                addRelative(5, 6, 7);
                addRelative(5, 7, 8);
                break;
            case 10:
                addRelative(1, 2, 3);
                addRelative(3, 4, 5);
                addRelative(1, 3, 5);
                addRelative(5, 6, 7);
                addRelative(5, 7, 8);
                addRelative(5, 8, 9);
                break;
            default:
                break;
        }
    };

    function<void(int, int)> build = [&](int offset, int size) {
        if (size == 0) return;

        int k = chosenK[size];
        if (k == -1) {
            addBase(offset, size);
            return;
        }

        int separators = k - 1;
        int r = size - separators;
        int last = dChoice[k][r];

        vector<int> childSizes = reconstructA(k - 1, r - last);
        childSizes.push_back(last);

        vector<int> childLeft(k), childRight(k);
        vector<int> sep(separators);

        int pos = offset;
        for (int j = 0; j < k; ++j) {
            childLeft[j] = pos;
            childRight[j] = pos + childSizes[j] - 1;
            pos += childSizes[j];

            if (j < separators) {
                sep[j] = pos;
                ++pos;
            }
        }

        for (int j = 0; j < k; ++j) {
            build(childLeft[j], childSizes[j]);

            if (j < separators) {
                for (int x = childLeft[j]; x <= childRight[j]; ++x) {
                    if (sep[j] - x > 1) {
                        add(x, x + 1, sep[j]);
                    }
                }
            }

            if (j > 0) {
                for (int x = childLeft[j]; x <= childRight[j]; ++x) {
                    if (x - sep[j - 1] > 1) {
                        add(sep[j - 1], x - 1, x);
                    }
                }
            }
        }

        for (int a = 0; a < separators; ++a) {
            for (int b = a + 1; b < separators; ++b) {
                if (sep[b] - sep[a] == 1) continue;

                if (b == a + 1) {
                    add(sep[a], sep[a] + 1, sep[b]);
                } else {
                    add(sep[a], sep[a + 1], sep[b]);
                }
            }
        }
    };

    build(0, N);

    sort(additions.begin(), additions.end(),
         [](const Addition &a, const Addition &b) {
             int da = a.v - a.u;
             int db = b.v - b.u;
             if (da != db) return da < db;
             if (a.u != b.u) return a.u < b.u;
             return a.v < b.v;
         });

    cout << additions.size() << '\n';
    for (const auto &e : additions) {
        cout << e.u << ' ' << e.c << ' ' << e.v << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Query {
    int a, b, res;
};

int n;
map<pair<int, int>, int> cache;
vector<Query> history;

int ask(int a, int b) {
    if (a > b) swap(a, b);
    auto key = make_pair(a, b);
    auto it = cache.find(key);
    if (it != cache.end()) return it->second;

    cout << "? " << a + 1 << " " << b + 1 << endl;
    cout.flush();

    int res;
    cin >> res;
    if (res == -1) exit(0);

    cache[key] = res;
    history.push_back({a, b, res});
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    vector<int> candidates(n);
    iota(candidates.begin(), candidates.end(), 0);

    vector<int> answer(n, -1);
    int zero = -1;

    while (zero == -1) {
        if (candidates.size() == 1) {
            zero = candidates[0];
            break;
        }

        int a = candidates[0];
        int value = ~0;
        vector<pair<int, int>> results;

        for (int i = 1; i < (int)candidates.size(); ++i) {
            int b = candidates[i];
            int res = ask(a, b);
            value &= res;
            results.push_back({b, res});
        }

        answer[a] = value;

        if (value == 0) {
            zero = a;
            break;
        }

        vector<int> nextCandidates;
        for (auto [b, res] : results) {
            if (res == value) nextCandidates.push_back(b);
        }
        candidates.swap(nextCandidates);
    }

    answer[zero] = 0;

    for (const auto &q : history) {
        if (q.a == zero) answer[q.b] = q.res;
        if (q.b == zero) answer[q.a] = q.res;
    }

    for (int i = 0; i < n; ++i) {
        if (answer[i] == -1) {
            answer[i] = ask(zero, i);
        }
    }

    cout << "!";
    for (int i = 0; i < n; ++i) {
        cout << " " << answer[i];
    }
    cout << endl;
    cout.flush();

