static int n;
static vector<int> perm;
static mt19937 rng((unsigned)chrono::steady_clock::now().time_since_epoch().count());

static int ask(int i, int j) {
    cout << "? " << (i + 1) << ' ' << (j + 1) << endl;
    int r;
    if (!(cin >> r)) exit(0);
    if (r == -1) exit(0);
    return r;
}

/*
   Invariant: the leaves in G hold exactly the values
              { u : u is a submask of W } \ {W}
   (so |G| = 2^popcount(W) - 1 and 0 belongs to the set).
   Returns the leaf whose hidden value equals 0.
*/
static int findZero(const vector<int>& G) {
    if (G.size() == 1) return G[0];

    const int m = (int)G.size();
    const int x = G[(int)(rng() % m)];

    vector<int> av(m, -1);
    int w = -1;
    for (int i = 0; i < m; i++) {
        if (G[i] == x) continue;
        av[i] = ask(x, G[i]);
        w = (w < 0) ? av[i] : (w & av[i]);
    }
    /* w == p_x  (AND trick: every bit is missing from at least two values) */
    if (w == 0) {
        for (int i = 0; i < m; i++)
            if (G[i] != x) perm[G[i]] = av[i];
        return x;
    }

    vector<int> G2;
    for (int i = 0; i < m; i++) {
        if (G[i] == x) continue;
        if ((av[i] & ~w) == 0) G2.push_back(G[i]);
    }
    return findZero(G2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n)) return 0;
    perm.assign(n, -1);

    if (n <= 4) {
        /* tiny instances: ask everything and solve by backtracking */
        vector<vector<int>> q(n, vector<int>(n, -1));
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) { q[i][j] = q[j][i] = ask(i, j); }
        vector<int> p(n, -1);
        vector<char> used(n, 0);
        function<bool(int)> rec = [&](int i) -> bool {
            if (i == n) return true;
            for (int v = 0; v < n; v++) {
                if (used[v]) continue;
                bool ok = true;
                for (int j = 0; j < i; j++)
                    if ((v | p[j]) != q[i][j]) { ok = false; break; }
                if (!ok) continue;
                p[i] = v; used[v] = 1;
                if (rec(i + 1)) return true;
                used[v] = 0;
            }
            return false;
        };
        rec(0);
        cout << "!";
        for (int i = 0; i < n; i++) cout << ' ' << p[i];
        cout << endl;
        return 0;
    }

    /* step 1: a star around vertex 0 -> p_0 and p_j & ~p_0 for every other j */
    vector<int> a(n, -1);
    int c = -1;
    for (int j = 1; j < n; j++) {
        a[j] = ask(0, j);
        c = (c < 0) ? a[j] : (c & a[j]);
    }
    perm[0] = c;

    int z;
    if (c == 0) {
        /* p_0 == 0 : the star already revealed every value */
        z = 0;
        for (int j = 1; j < n; j++) perm[j] = a[j];
    } else {
        /* leaves whose value is a submask of c contain the value 0 */
        vector<int> G0;
        for (int j = 1; j < n; j++)
            if ((a[j] & ~c) == 0) G0.push_back(j);
        z = findZero(G0);
    }
    perm[z] = 0;

    /* step 2: read every remaining value using the zero vertex */
    for (int j = 0; j < n; j++) {
        if (j == 0 || j == z || perm[j] != -1) continue;
        perm[j] = ask(z, j);
    }

    cout << "!";
    for (int i = 0; i < n; i++) cout << ' ' << perm[i];
    cout << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Solver {
    int n;
    vector<int> answer;
    vector<int> pointValue;

    explicit Solver(int n) : n(n), answer(n + 1, 0), pointValue(n + 1, 0) {}

    pair<int, int> ask(int l, int r) {
        cout << "? " << l << ' ' << r << endl;
        int x, f;
        if (!(cin >> x >> f)) exit(0);
        if (x == -1) exit(0);
        return {x, f};
    }

    int getPoint(int pos) {
        if (pointValue[pos] != 0) return pointValue[pos];
        int value = ask(pos, pos).first;
        pointValue[pos] = value;
        return value;
    }

    void fillInterval(int l, int r, int value) {
        fill(answer.begin() + l, answer.begin() + r + 1, value);
    }

    int locateRun(int l, int r, int x, int f) {
        if (getPoint(l) == x) return l;
        if (getPoint(r) == x) return r - f + 1;

        const int maxStart = r - f;
        const int minEnd = l + f;
        const int remaining = (r - l + 1) - f;

        auto ordinaryBinarySearch = [&]() {
            int lo = l + 1, hi = maxStart;
            while (lo < hi) {
                int mid = (lo + hi) >> 1;
                if (getPoint(mid) < x) lo = mid + 1;
                else hi = mid;
            }
            return lo;
        };

        int budget = 0;
        for (int t = remaining; t; t >>= 1) ++budget;

        int leftFalse = l;
        int rightFalse = r;
        long long leftStep = 1, rightStep = 1;
        int used = 0;

        while (true) {
            int p = (int)min<long long>(maxStart, (long long)l + leftStep);
            int value = getPoint(p);

            if (value >= x) {
                int lo = leftFalse + 1, hi = p;
                while (lo < hi) {
                    int mid = (lo + hi) >> 1;
                    if (getPoint(mid) < x) lo = mid + 1;
                    else hi = mid;
                }
                return lo;
            }

            leftFalse = p;
            leftStep <<= 1;
            if (++used >= budget) return ordinaryBinarySearch();

            int q = (int)max<long long>(minEnd, (long long)r - rightStep);
            value = getPoint(q);

            if (value <= x) {
                int lo = q, hi = rightFalse;
                while (hi - lo > 1) {
                    int mid = (lo + hi) >> 1;
                    if (getPoint(mid) <= x) lo = mid;
                    else hi = mid;
                }
                return lo - f + 1;
            }

            rightFalse = q;
            rightStep <<= 1;
            if (++used >= budget) return ordinaryBinarySearch();
        }
    }

    void solve(int l, int r) {
        if (l > r) return;

        if (l == r) {
            answer[l] = getPoint(l);
            return;
        }

        if (pointValue[l] != 0 && pointValue[l] == pointValue[r]) {
            fillInterval(l, r, pointValue[l]);
            return;
        }

        auto [x, f] = ask(l, r);
        if (f == r - l + 1) {
            fillInterval(l, r, x);
            return;
        }

        int start = locateRun(l, r, x, f);
        int finish = start + f - 1;
        fillInterval(start, finish, x);

        solve(l, start - 1);
        solve(finish + 1, r);
    }

    void run() {
        solve(1, n);
        cout << '!';
        for (int i = 1; i <= n; ++i) cout << ' ' << answer[i];
        cout << endl;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    Solver solver(n);
    solver.run();
    return 0;
}

