    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    answer_array.assign(n + 1, 0);
    query_cache.reserve(1024);

    solve(1, n);

    cout << "!";
    for (int i = 1; i <= n; ++i) {
        cout << " " << answer_array[i];
    }
    cout << endl;

    return 0;
}

